#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PacketList;

void init_packet_list(PacketList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_packet(PacketList* list, DataPacket packet) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        return;
    }
    new_node->data = packet;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void update_packet(PacketList* list, int packet_id, DataPacket new_data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            current->data = new_data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

Node* get_packets_in_range(PacketList* list, time_t start_time, time_t end_time) {
    Node* result_head = NULL;
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.timestamp >= start_time && current->data.timestamp <= end_time) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            if (new_node == NULL) {
                perror("Failed to allocate memory for new node");
                break;
            }
            new_node->data = current->data;
            new_node->next = result_head;
            result_head = new_node;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return result_head;
}

void free_packet_list(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
