#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record *records;
    size_t capacity;
    size_t size;
} DataBatch;

DataBatch* create_data_batch(long offset, int key, size_t initial_capacity) {
    if (initial_capacity == 0) {
        fprintf(stderr, "Initial capacity must be greater than zero.\n");
        return NULL;
    }

    DataBatch *batch = (DataBatch*)malloc(sizeof(DataBatch));
    if (!batch) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    batch->offset = offset;
    batch->key = key;
    batch->capacity = initial_capacity;
    batch->size = 0;

    batch->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!batch->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(batch);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        batch->records[i].value = key * i; // Example initialization using hash function
    }

    return batch;
}

void destroy_data_batch(DataBatch *batch) {
    if (!batch) {
        fprintf(stderr, "Invalid batch pointer.\n");
        return;
    }

    free(batch->records);
    free(batch);
}

int main() {
    DataBatch *batch = create_data_batch(100L, 42, 10);
    if (batch) {
        // Use the batch for processing
        destroy_data_batch(batch);
    }
    return 0;
}
