#include <unistd.h>

#define MAX_LINE_LENGTH 1024
#define CACHE_SIZE 100

typedef struct {
    char hostname[256];
    u_char ip[4];
} DNSCacheEntry;

DNSCacheEntry cache[CACHE_SIZE];
int cache_count = 0;
int cache_head = 0;

u_char* resolveDNS(const char* hostname) {
    // Check cache
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[(cache_head + i) % CACHE_SIZE].hostname, hostname) == 0) {
            return cache[(cache_head + i) % CACHE_SIZE].ip;
        }
    }

    // DNS resolution logic here
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        // Store in cache
        if (cache_count < CACHE_SIZE) {
            strcpy(cache[cache_head].hostname, hostname);
            memcpy(cache[cache_head].ip, addr, 4);
            cache_head = (cache_head + 1) % CACHE_SIZE;
            cache_count++;
        }
    }

    freeaddrinfo(res); // all done with this structure
    return NULL; // Placeholder for actual IP address
}

int main() {
    FILE *file = fopen("weblog.txt", "r");
    if (!file) {
