#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_INTS 1000
#define BUFFER_SIZE 4096

int process_network_stream(int sockfd) {
    int *ints = NULL;
    size_t count = 0;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while ((bytes_read = read(sockfd, buffer, BUFFER_SIZE)) > 0) {
        for (size_t i = 0; i < bytes_read; i += sizeof(int)) {
            int new_int = *(int *)(buffer + i);
            if (count >= MAX_INTS) {
                fprintf(stderr, "Maximum number of integers reached.\n");
                free(ints);
                return -1;
            }
            for (size_t j = 0; j < count; ++j) {
                if (ints[j] == new_int) {
                    fprintf(stderr, "Duplicate integer received.\n");
                    free(ints);
                    return -2;
                }
            }
            ints = realloc(ints, (count + 1) * sizeof(int));
            if (!ints) {
                perror("Memory allocation failed");
                return -3;
            }
            ints[count++] = new_int;
        }
    }

    if (bytes_read == -1) {
        perror("Read error from network socket");
        free(ints);
        return -4;
    }

    // Process the integers as needed
    for (size_t i = 0; i < count; ++i) {
        printf("Processed integer: %d\n", ints[i]);
    }

    free(ints);
    return 0;
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("Socket creation failed");
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("Connection failed");
        close(sockfd);
        return 1;
    }

    int result = process_network_stream(sockfd);
    if (result != 0) {
        fprintf(stderr, "Error processing network stream: %d\n", result);
    }

    close(sockfd);
    return 0;
}
