#include <stdio.h>
#include <stdarg.h>
#include <string.h>

#define MAX_LOG_SIZE 4096

typedef enum {
    LOG_CONSOLE,
    LOG_FILE,
    LOG_NETWORK
} LogDestination;

void log_message(LogDestination destination, const char *format, ...) {
    va_list args;
    va_start(args, format);

    char buffer[MAX_LOG_SIZE];
    vsnprintf(buffer, sizeof(buffer), format, args);
    buffer[sizeof(buffer) - 1] = '\0'; // Ensure null-termination

    switch (destination) {
        case LOG_CONSOLE:
            printf("%s\n", buffer);
            break;
        case LOG_FILE:
            FILE *file = fopen("log.txt", "a");
            if (file) {
                fprintf(file, "%s\n", buffer);
                fclose(file);
            }
            break;
        case LOG_NETWORK:
            // Implement network logging logic here
            break;
    }

    va_end(args);
}

int main() {
    log_message(LOG_CONSOLE, "This is a console log message.");
    log_message(LOG_FILE, "This is a file log message.");
    log_message(LOG_NETWORK, "This is a network log message.");

    return 0;
}
