#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <openssl/gcm.h>
#include <openssl/ccm.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>

EVP_CIPHER_CTX* create_cipher_context(const char* mode, int key_size) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const EVP_CIPHER* cipher;
    if (strcmp(mode, "AES-128-GCM") == 0) {
        cipher = EVP_aes_128_gcm();
    } else if (strcmp(mode, "AES-192-GCM") == 0) {
        cipher = EVP_aes_192_gcm();
    } else if (strcmp(mode, "AES-256-GCM") == 0) {
        cipher = EVP_aes_256_gcm();
    } else if (strcmp(mode, "AES-128-CCM") == 0) {
        cipher = EVP_aes_128_ccm();
    } else if (strcmp(mode, "AES-192-CCM") == 0) {
        cipher = EVP_aes_192_ccm();
    } else if (strcmp(mode, "AES-256-CCM") == 0) {
        cipher = EVP_aes_256_ccm();
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

int derive_key(const char* password, const unsigned char* salt, size_t salt_len, unsigned char* key, int key_size) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, 100000, EVP_sha256(), key_size, key);
}

int encrypt_data(EVP_CIPHER_CTX* ctx, const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext, unsigned char* tag) {
    if (!EVP_EncryptUpdate(ctx, ciphertext, NULL, plaintext, plaintext_len)) return 0;
    int len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) return 0;
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)) return 0;
    return len + 16; // Return ciphertext length including tag
}

int decrypt_data(EVP_CIPHER_CTX* ctx, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext, const unsigned char* tag) {
    if (!EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL)) return 0;
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, (unsigned char*)tag)) return 0;
    int len;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len - 16)) return 0;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) return 0;
    return len;
}

void free_cipher_context(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
