import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PokemonReportService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final Cache<String, PokemonDetails> cache = new DistributedCache();

    public CompletableFuture<PokemonDetails> getPokemonDetails(String pokemonName) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                // Check cache first
                PokemonDetails cachedDetails = cache.get(pokemonName);
                if (cachedDetails != null) {
                    return cachedDetails;
                }

                // Fetch details from external APIs asynchronously
                CompletableFuture<PokemonDetails> typeFuture = fetchTypeDetails(pokemonName, executor);
                CompletableFuture<PokemonDetails> weaknessFuture = fetchWeaknessDetails(pokemonName, executor);

                // Wait for both futures to complete
                PokemonDetails typeDetails = typeFuture.get();
                PokemonDetails weaknessDetails = weaknessFuture.get();

                // Merge details and store in cache
                PokemonDetails mergedDetails = mergeDetails(typeDetails, weaknessDetails);
                cache.put(pokemonName, mergedDetails);

                return mergedDetails;
            } catch (Exception e) {
                handleException(e);
                throw new RuntimeException("Failed to fetch Pokemon details", e);
            }
        }, executor);
    }

    private CompletableFuture<PokemonDetails> fetchTypeDetails(String pokemonName, ExecutorService executor) {
        // Simulate fetching type details from an external API
        return CompletableFuture.supplyAsync(() -> {
            try {
                TimeUnit.SECONDS.sleep(1); // Simulate network delay
                return new PokemonDetails(pokemonName, "Fire", null);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Failed to fetch type details", e);
            }
        }, executor);
    }

    private CompletableFuture<PokemonDetails> fetchWeaknessDetails(String pokemonName, ExecutorService executor) {
        // Simulate fetching weakness details from an external API
        return CompletableFuture.supplyAsync(() -> {
            try {
                TimeUnit.SECONDS.sleep(1); // Simulate network delay
                return new PokemonDetails(pokemonName, null, "Water");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Failed to fetch weakness details", e);
            }
        }, executor);
    }

    private PokemonDetails mergeDetails(PokemonDetails typeDetails, PokemonDetails weaknessDetails) {
        // Merge type and weakness details
        return new PokemonDetails(typeDetails.getName(), typeDetails.getType(), weaknessDetails.getWeakness());
    }

    private void handleException(Exception e) {
        // Log the exception or notify monitoring system
        System.err.println("Error fetching Pokemon details: " + e.getMessage());
    }
}

class PokemonDetails {
    private String name;
    private String type;
    private String weakness;

    public PokemonDetails(String name, String type, String weakness) {
        this.name = name;
        this.type = type;
        this.weakness = weakness;
    }

    // Getters and setters
    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getType() {
        return type;
    }

    public void setType(String type) {
        this.type = type;
    }

    public String getWeakness() {
        return weakness;
    }

    public void setWeakness(String weakness) {
        this.weakness = weakness;
    }
}

interface Cache<K, V> {
    V get(K key);
    void put(K key, V value);
}

class DistributedCache implements Cache<String, PokemonDetails> {
    private final java.util.Map<String, PokemonDetails> cacheMap = new java.util.concurrent.ConcurrentHashMap<>();

    @Override
    public PokemonDetails get(String key) {
        return cacheMap.get(key);
    }

    @Override
    public void put(String key, PokemonDetails value) {
        cacheMap.put(key, value);
    }
}
```

