#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <dlfcn.h>

typedef struct {
    void* handle;
    char* name;
} CryptoModule;

typedef struct {
    CryptoModule** modules;
    size_t count;
} CryptoPrimitiveList;

CryptoPrimitiveList* get_available_primitives(const char* directory) {
    DIR* dir = opendir(directory);
    if (!dir) return NULL;

    CryptoPrimitiveList* list = (CryptoPrimitiveList*)malloc(sizeof(CryptoPrimitiveList));
    list->modules = NULL;
    list->count = 0;

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".so")) {
            char path[256];
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

            void* handle = dlopen(path, RTLD_LAZY);
            if (!handle) continue;

            CryptoModule* module = (CryptoModule*)malloc(sizeof(CryptoModule));
            module->handle = handle;
            module->name = strdup(entry->d_name);

            list->count++;
            list->modules = realloc(list->modules, list->count * sizeof(CryptoModule*));
            list->modules[list->count - 1] = module;
        }
    }

    closedir(dir);
    return list;
}

void free_primitive_list(CryptoPrimitiveList* list) {
    for (size_t i = 0; i < list->count; i++) {
        dlclose(list->modules[i]->handle);
        free(list->modules[i]->name);
