['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 10

typedef struct {
    sem_t *sems[MAX_SEMAPHORES];
    int count;
    pthread_mutex_t lock;
} SemaphoreManager;

SemaphoreManager *initializeSemaphoreManager() {
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    if (manager == NULL) {
        return NULL;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

sem_t *acquireSemaphore(SemaphoreManager *manager, int value) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_SEMAPHORES) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    if (sem == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    if (sem_init(sem, 0, value) != 0) {
        free(sem);
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    manager->sems[manager->count++] = sem;
    pthread_mutex_unlock(&manager->lock);
    return sem;
}

void releaseSemaphore(SemaphoreManager *manager, sem_t *sem) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->sems[i] == sem) {
            sem_destroy(sem);
            free(sem);
            for (; i < manager->count - 1; i++) {
                manager->sems[i] = manager->sems[i + 1];
            }
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroySemaphoreManager(SemaphoreManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        sem_destroy(manager->sems[i]);
        free(manager->sems[i]);
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
