#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <chrono>
#include <string>
#include <curl/curl.h>

class HttpClient {
public:
    HttpClient(const std::vector<std::string>& servers, int maxThreads)
        : servers_(servers), maxThreads_(maxThreads), stop_(false) {
        for (int i = 0; i < maxThreads_; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex_);
                        condition_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                        if (stop_ && tasks_.empty()) {
                            return;
                        }
                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }
                    task();
                }
            });
        }
    }

    ~HttpClient() {
        {
            std::unique_lock<std::mutex> lock(queueMutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    void addRequest(const std::string& url, const std::string& method) {
        tasks_.push([this, url, method] {
            CURL* curl = curl_easy_init();
            if (curl) {
                curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
                curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, method.c_str());
                // Add more options as needed
                CURLcode res = curl_easy_perform(curl);
                if (res != CURLE_OK) {
                    std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
                }
                curl_easy_cleanup(curl);
            } else {
                std::cerr << "Failed to initialize libcurl" << std::endl;
            }
        });
    }

private:
    std::vector<std::string> servers_;
    int maxThreads_;
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex queueMutex_;
    std::condition_variable condition_;
    std::atomic<bool> stop_;
};

int main(int argc, char* argv[]) {
    // Example usage
    HttpClient client({"http://server1.com", "http://server2.com"}, 4);
    client.addRequest("http://example.com/api/data", "GET");
    return 0;
}
```

