    if 'name' not in updated_state or len(updated_state['name']) < 3:
        return jsonify({"error": "Invalid data format"}), 400

    resources[resource_id] = updated_state
    log_operation(user_id, resource_id, 'updated', changes=updated_state)

    return jsonify(updated_state), 200

@app.route('/resources/<int:resource_id>', methods=['DELETE'])
