using System;
using System.IO;
using System.Xml.XPath;

public class XmlParser
{
    public static XPathNavigator GetFirstElement(string elementName)
    {
        string xmlPath = Environment.GetEnvironmentVariable("XML_PATH");
        if (string.IsNullOrEmpty(xmlPath))
        {
            xmlPath = Path.Combine(Path.GetTempPath(), "xml_data");
            if (!Directory.Exists(xmlPath))
            {
                Directory.CreateDirectory(xmlPath);
            }
            Environment.SetEnvironmentVariable("XML_PATH", xmlPath, EnvironmentVariableTarget.Process);
        }

        string filePath = Path.Combine(xmlPath, "data.xml");
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("XML file not found.", filePath);
        }

        try
        {
            XPathDocument doc = new XPathDocument(filePath);
            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select($"//{elementName}");

            if (nodes.Count == 0)
            {
                throw new InvalidOperationException($"No elements with name '{elementName}' found.");
            }
            else if (nodes.Count > 1)
            {
                throw new InvalidOperationException($"Multiple elements with name '{elementName}' found.");
            }

            return nodes.Current;
        }
        catch (XmlException ex)
        {
            throw new InvalidOperationException("Malformed XML file.", ex);
        }
    }
}
