import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class HashProcessor {
    private static final int MAX_INPUT_SIZE = 8 * 1024; // 8 KB
    private static final ConcurrentHashMap<String, String> hashCache = new ConcurrentHashMap<>();

    public void processText(String text) throws InputTooLargeException {
        if (text == null || text.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty");
        }

        if (text.length() > MAX_INPUT_SIZE) {
            throw new InputTooLargeException("Input exceeds maximum size of 8 KB");
        }

        String hash = generateMD5Hash(text);
        storeInDatabase(hash, text);

        logHashGeneration(text, hash);
    }

    private String generateMD5Hash(String text) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(text.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    private void storeInDatabase(String hash, String text) {
        // Simulate database storage
        hashCache.put(hash, text);
    }

    private void logHashGeneration(String text, String hash) {
