import java.io.*;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.os.Environment;

public class ThemeLoader {

    private static final String DEFAULT_THEME_DIR = "/default_theme_dir";
    private static final int MAX_CACHED_FILES = 10;

    public MoSTState loadAndCacheTheme(String filePath) {
        MoSTState state = null;
        FileInputStream fis = null;
        ObjectInputStream ois = null;
        Bitmap themeBitmap = null;

        try {
            fis = new FileInputStream(filePath);
            ois = new ObjectInputStream(fis);
            state = (MoSTState) ois.readObject();

            if (!(state instanceof MoSTState)) {
                return null;
            }

            // Recycle theme bitmap if not already recycled
            if (!themeBitmap.isRecycled()) {
                try {
                    themeBitmap.recycle();
                } catch (OutOfMemoryError e) {
                    Log.e("ThemeLoader", "Failed to recycle theme bitmap due to memory constraint");
                }
            }

            // Set default theme directory if not set
            File cacheDir = Environment.getExternalStorageDirectory().getAbsolutePath() + DEFAULT_THEME_DIR;
            if (!new File(cacheDir).exists()) {
                new File(cacheDir).mkdirs();
            }

            // Parse and cache PNG file from cache root directory
            File pngFile = new File(cacheDir, "theme.png");
            if (pngFile.exists()) {
                themeBitmap = BitmapFactory.decodeFile(pngFile.getAbsolutePath());
                cacheThemeFiles(cacheDir);
            } else {
                Log.w("ThemeLoader", "PNG file not found in cache directory");
            }

        } catch (IOException | ClassNotFoundException e) {
            Log.e("ThemeLoader", "Error loading and caching theme: ", e);
        } finally {
            try {
                if (ois != null) ois.close();
                if (fis != null) fis.close();
            } catch (IOException e) {
                Log.e("ThemeLoader", "Error closing streams: ", e);
            }
        }

        return state;
    }

    private void cacheThemeFiles(File cacheDir) {
        // Implement caching strategy to limit the number of cached files
        File[] files = cacheDir.listFiles();
        if (files != null && files.length > MAX_CACHED_FILES) {
            for (File file : files) {
                if (!file.isDirectory() && file.getName().endsWith(".png")) {
                    file.delete();
                }
            }
        }
    }
}
