["```javascript
const fs = require('fs');
const readline = require('readline');

function processCloudTerms(config) {
  const { cloudServices, logFunction } = config;
  const termFrequency = {};
  let stream;

  function updateTermFrequency(term) {
    if (cloudServices.includes(term)) {
      termFrequency[term] = (termFrequency[term] || 0) + 1;
    }
  }

  function processLine(line) {
    const terms = line.match(/\b[A-Za-z]+\b/g);
    if (terms) {
      terms.forEach(updateTermFrequency);
    }
  }

  function handleData(data) {
    data.split('\n').forEach(processLine);
  }

  function handleError(error) {
    console.error('Error processing document:', error);
  }

  function handleEnd() {
    logFunction(termFrequency);
  }

  return (filePath) => {
    stream = readline.createInterface({
      input: fs.createReadStream(filePath),
      crlfDelay: Infinity
    });

    stream.on('line', processLine);
    stream.on('close', handleEnd);
    stream.on('error', handleError);

    return new Promise((resolve, reject) => {
      stream.on('open', () => resolve());
      stream.on('error', (error) => reject(error));
    });
  };
}

// Example usage:
const config = {
  cloudServices: ['aws', 'azure', 'google cloud'],
  logFunction: (frequency) => console.log(frequency)
};

const processCloudTermsFunc = processCloudTerms(config);
processCloudTermsFunc('path/to/large/document.txt')
  .then(() => console.log('Processing complete'))
  .catch((error) => console.error('Failed to process document:', error));
```

This code snippet defines a `processCloudTerms` function that takes a configuration object with an array of cloud service terms and a logging function. It returns a function that processes a large text document in chunks, updating the term frequency based on the specified cloud services. The example usage demonstrates how to use this function to process a document located at 'path/to/large/document.txt'."]

['```javascript
function renderFooterScripts(scripts, config = { strict: false }) {
    if (!scripts || !Array.isArray(scripts) || scripts.length === 0) {
        console.log("No scripts to render.");
        return "<p>Loading scripts...</p>";
    }

    const scriptContainer = document.createElement('div');
    let scriptCount = 0;

    scripts.forEach(script => {
        if (config.strict && !script.key.startsWith("core")) {
            console.warn(`Script with key ${script.key} is not a core script and will be skipped.`);
            return;
        }

        if (!script.code) {
            console.error(`Script with key ${script.key} has no code. Skipping.`);
            return;
        }

        const scriptElement = document.createElement('script');
        scriptElement.type = 'text/javascript';
        scriptElement.text = script.code;

        scriptContainer.appendChild(scriptElement);
        scriptCount++;
    });

    if (scriptCount === 0) {
        console.log("No valid scripts to render.");
        return "<p>No valid scripts to load.</p>";
    }

    document.getElementById('footer').appendChild(scriptContainer);
    return `<p>${scriptCount} scripts loaded successfully.</p>`;
}
