// main.js
const fs = require('fs');
const path = require('path');

class ScriptLoader {
  constructor(directory) {
    this.directory = directory;
    this.scripts = [];
    this.dependencies = {};
  }

  loadScripts() {
    return new Promise((resolve, reject) => {
      fs.readdir(this.directory, (err, files) => {
        if (err) return reject(err);

        files.forEach(file => {
          const filePath = path.join(this.directory, file);
          fs.stat(filePath, (err, stats) => {
            if (err) return reject(err);

            if (stats.isFile() && path.extname(file).toLowerCase() === '.js') {
              this.scripts.push({ name: file, path: filePath });
              this.dependencies[file] = [];
            }
          });
        });

        this.resolveDependencies().then(() => resolve(this.executeScripts()));
      });
    });
  }

  resolveDependencies() {
    return new Promise((resolve, reject) => {
      const queue = [...this.scripts];
      const resolved = [];

      while (queue.length > 0) {
        const script = queue.shift();
        fs.readFile(script.path, 'utf8', (err, content) => {
          if (err) return reject(err);

          const dependencies = this.findDependencies(content);
          if (dependencies.length === 0) {
            resolved.push(script.name);
            continue;
          }

          let allResolved = true;
          for (const dep of dependencies) {
            if (!resolved.includes(dep)) {
              allResolved = false;
              queue.push(this.scripts.find(s => s.name === dep));
            }
          }

          if (allResolved) {
            resolved.push(script.name);
          } else {
            return reject(new Error(`Circular dependency detected: ${script.name}`));
          }
        });
      }

      resolve();
    });
  }

  findDependencies(content) {
    const regex = /require\(['"]([^'"]+)['"]\)/g;
    let match;
    const dependencies = [];

    while ((match = regex.exec(content)) !== null) {
      dependencies.push(match[1]);
    }

    return dependencies;
  }

  executeScripts() {
    return new Promise((resolve, reject) => {
      const queue = [...this.scripts];
      const executed = [];

      const executeNext = () => {
        if (queue.length === 0) return resolve();

        const script = queue.shift();
        fs.readFile(script.path, 'utf8', (err, content) => {
          if (err) return reject(err);

          try {
            eval(content);
            executed.push(script.name);
            executeNext();
          } catch (e) {
            return reject(new Error(`Failed to execute ${script.name}: ${e.message}`));
          }
        });
      };

      executeNext();
    });
  }

  modifyFilename(filename, sequence, fileType) {
    const baseName = path.basename(filename, path.extname(filename));
    return `${baseName}_${sequence}${fileType}`;
  }
}

module.exports = ScriptLoader;
```

