import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class FilePathProcessor {

    private static final Logger logger = Logger.getLogger(FilePathProcessor.class.getName());
    private DirectoryTraverser directoryTraverser;

    public FilePathProcessor(DirectoryTraverser directoryTraverser) {
        this.directoryTraverser = directoryTraverser;
    }

    public int countUniqueDirectories(String[] filePaths, boolean parallelProcessing, int maxRetries, long retryDelay, Level logLevel) {
        logger.setLevel(logLevel);
        Set<Path> uniqueDirectories = ConcurrentHashMap.newKeySet();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (String path : filePaths) {
            if (parallelProcessing) {
                CompletableFuture.runAsync(() -> processPath(path, uniqueDirectories, maxRetries, retryDelay), executor);
            } else {
                processPath(path, uniqueDirectories, maxRetries, retryDelay);
            }
        }

        if (parallelProcessing) {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(1, TimeUnit.HOURS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }

        return uniqueDirectories.size();
    }

    private void processPath(String path, Set<Path> uniqueDirectories, int maxRetries, long retryDelay) {
        Path fullPath = Paths.get(path);
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            try {
                if (Files.exists(fullPath)) {
                    Path directory = fullPath.getParent();
                    if (directory != null) {
                        uniqueDirectories.add(directory.normalize());
                    }
                    logger.info("Processed path: " + path);
                    return;
                } else {
                    logger.warning("Path does not exist: " + path);
                }
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error processing path: " + path, e);
            }

            if (attempt < maxRetries) {
                try {
                    Thread.sleep(retryDelay);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
        }
    }
}
