import java.util.concurrent.*;
import java.io.IOException;
import java.net.Socket;

public class AsyncConnectionPool {
    private final BlockingQueue<Socket> pool;
    private final ExecutorService executor;
    private final int maxConnections;
    private final long connectionTimeout;

    public AsyncConnectionPool(int maxConnections, long connectionTimeout) {
        this.maxConnections = maxConnections;
        this.connectionTimeout = connectionTimeout;
        this.pool = new ArrayBlockingQueue<>(maxConnections);
        this.executor = Executors.newFixedThreadPool(maxConnections);
    }

    public Socket getConnection() throws InterruptedException {
        return pool.poll(connectionTimeout, TimeUnit.MILLISECONDS);
    }

    public void releaseConnection(Socket socket) {
        if (pool.size() < maxConnections) {
            pool.offer(socket);
        }
    }

    public void submitTask(Runnable task) {
        executor.submit(task);
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        AsyncConnectionPool pool = new AsyncConnectionPool(100, 5000);

        // Example usage
        for (int i = 0; i < 150; i++) {
            pool.submitTask(() -> {
                try {
                    Socket socket = pool.getConnection();
                    // Perform file transfer operations
                    pool.releaseConnection(socket);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }

        pool.shutdown();
    }
}
```

