import os
import threading
from collections import OrderedDict

class ThemeCacheManager:
    def __init__(self, default_theme_dir=None):
        self.theme_cache = OrderedDict()
        self.lock = threading.Lock()
        if not default_theme_dir:
            self.default_theme_dir = "/path/to/recommended/fallback/theme/directory"
        else:
            self.default_theme_dir = default_theme_dir

    def load_theme(self, theme_name):
        with self.lock:
            if theme_name in self.theme_cache:
                # Move the accessed theme to the end of the cache
                self.theme_cache.move_to_end(theme_name)
                return self.theme_cache[theme_name]
            else:
                try:
                    theme_path = os.path.join(self.default_theme_dir, f"{theme_name}.theme")
                    with open(theme_path, 'r') as file:
                        theme_data = file.read()
                    # Cache the loaded theme
                    self.theme_cache[theme_name] = theme_data
                    return theme_data
                except FileNotFoundError:
                    raise Exception(f"Theme '{theme_name}' not found.")
                except IOError:
                    raise Exception(f"Error reading theme '{theme_name}'.")

    def save_theme(self, theme_name, theme_data):
        with self.lock:
            try:
                theme_path = os.path.join(self.default_theme_dir, f"{theme_name}.theme")
                with open(theme_path, 'w') as file:
                    file.write(theme_data)
                # Update the cache with the saved theme
                self.theme_cache[theme_name] = theme_data
            except IOError:
                raise Exception(f"Error saving theme '{theme_name}'.")

    def get_theme_frequency(self):
        return {theme: count for theme, count in self.theme_cache.items()}

# Example usage
cache_manager = ThemeCacheManager()
try:
    theme_data = cache_manager.load_theme("default")
    print(theme_data)
    cache_manager.save_theme("custom", "new_theme_data")
except Exception as e:
    print(e)
