import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private ExecutorService executorService;
    private boolean isRunning = false;

    public void startService() {
        if (!isRunning) {
            executorService = Executors.newFixedThreadPool(10);
            // Start service logic here
            System.out.println("Service started at " + System.currentTimeMillis());
            isRunning = true;
        }
    }

    public void stopService() {
        if (isRunning) {
            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException e) {
                executorService.shutdownNow();
            }
            System.out.println("Service stopped at " + System.currentTimeMillis());
            isRunning = false;
        }
    }

    public void handleRequest(Runnable task) {
        if (isRunning) {
            executorService.submit(task);
        } else {
            System.err.println("Service is not running to handle request");
        }
    }

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager();
        serviceManager.startService();

        // Simulate handling requests
        for (int i = 0; i < 100; i++) {
            final int requestId = i;
            serviceManager.handleRequest(() -> {
                System.out.println("Handling request " + requestId);
                try {
                    Thread.sleep(500); // Simulate processing time
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }

        // Stop the service after some time
        try {
            TimeUnit.SECONDS.sleep(10);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        serviceManager.stopService();
    }
}
```

