['```rust
use reqwest::{Client, RequestBuilder, Error};
use std::time::{Duration, Instant};
use serde_json::Value;
use std::env;

#[derive(Debug)]
struct Config {
    base_url: String,
    max_retries: u32,
    total_duration_limit: Duration,
}

impl Config {
    fn from_env() -> Result<Self, Error> {
        let base_url = env::var("BASE_URL")?;
        let max_retries = env::var("MAX_RETRIES").map(|v| v.parse().unwrap())?;
        let total_duration_limit = env::var("TOTAL_DURATION_LIMIT")
            .map(|v| Duration::from_secs(v.parse().unwrap()))?;

        Ok(Config {
            base_url,
            max_retries,
            total_duration_limit,
        })
    }
}

async fn make_request_with_retry(
    client: &Client,
    config: &Config,
    request_builder: RequestBuilder,
) -> Result<Value, Error> {
    let mut retries = 0;
    let start_time = Instant::now();

    while retries < config.max_retries {
        if start_time.elapsed() > config.total_duration_limit {
            return Err(Error::new(reqwest::StatusCode::RequestTimeout, "Total duration limit exceeded"));
        }

        match request_builder.send().await {
            Ok(response) => {
                if response.status().is_success() {
                    return response.json().await;
                } else {
                    retries += 1;
                    tokio::time::sleep(Duration::from_secs(2u32.pow(retries))).await;
                }
            },
            Err(e) => {
                retries += 1;
                tokio::time::sleep(Duration::from_secs(2u32.pow(retries))).await;
            }
        }
    }

    Err(Error::new(reqwest::StatusCode::TooManyRequests, "Max retries exceeded"))
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let config = Config::from_env()?;
    let client = Client::new();

    let request_builder = client
        .get(&config.base_url)
        .header("Authorization", format!("Bearer {}", env::var("AUTH_TOKEN")?))
        .json(&serde_json::json!({ "key": "value" }));

    let response: Value = make_request_with_retry(&client, &config, request_builder).await?;
    println!("{:?}", response);

    Ok(())
}
```']

