<?php

class FileAndUtilityManager {
    /**
     * Generates a random string of a specified length using a provided character set.
     *
     * @param int $length The desired length of the random string.
     * @param string $characters The character set to use for generating the string.
     * @return string The generated random string.
     */
    public static function generateRandomString($length, $characters) {
        if ($length <= 0 || empty($characters)) {
            throw new InvalidArgumentException('Invalid input: length must be greater than 0 and characters cannot be empty.');
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[rand(0, strlen($characters) - 1)];
        }

        return $randomString;
    }

    /**
     * Hashes a password using a specified cost factor.
     *
     * @param string $password The password to hash.
     * @param int $costFactor The cost factor for the hashing algorithm.
     * @return string The hashed password.
     */
    public static function hashPassword($password, $costFactor = 10) {
        if (empty($password)) {
            throw new InvalidArgumentException('Invalid input: password cannot be empty.');
        }

        $options = [
            'cost' => $costFactor,
        ];

        return password_hash($password, PASSWORD_BCRYPT, $options);
    }

    /**
     * Reads a file asynchronously from a specified directory and returns its content as a string.
     *
     * @param string $filePath The path to the file to read.
     * @return string The content of the file.
     */
    public static function readFileAsync($filePath) {
        if (!file_exists($filePath)) {
            throw new Exception('File not found: ' . $filePath);
        }

        $content = '';
        $handle = fopen($filePath, 'r');
        if ($handle === false) {
            throw new Exception('Failed to open file for reading.');
        }

        while (($line = fgets($handle)) !== false) {
            $content .= $line;
        }

        fclose($handle);

        return $content;
    }
}
