const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function generateCertificateFromOAuthRequest(oauthConfig) {
  const { privateKeyUrl, certificateUrl } = oauthConfig;
  const cacheKey = `certificate_${privateKeyUrl}_${certificateUrl}`;
  const cacheFilePath = path.join(__dirname, 'cache', `${cacheKey}.pem`);

  if (fs.existsSync(cacheFilePath)) {
    return new Promise((resolve) => {
      fs.readFile(cacheFilePath, 'utf8', (err, data) => {
        if (err) {
          resolve(generateCertificateFromOAuthRequest(oauthConfig));
        } else {
          resolve(data);
        }
      });
    });
  }

  const fetchResource = async (url) => {
    return new Promise((resolve, reject) => {
      const request = require('https').get(url, (response) => {
        let data = '';
        response.on('data', (chunk) => {
          data += chunk;
        });
        response.on('end', () => {
          resolve(data);
        });
      }).on('error', (err) => {
        reject(err);
      });
    });
  };

  const mergeResources = async (privateKey, certificate) => {
    return new Promise((resolve) => {
      fs.writeFile(cacheFilePath, `${privateKey}\n${certificate}`, 'utf8', () => {
        resolve(`-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`);
      });
    });
  };

  const handleErrors = (error) => {
    console.error('Error fetching resources:', error);
    return generateCertificateFromOAuthRequest(oauthConfig);
  };

  return Promise.all([fetchResource(privateKeyUrl), fetchResource(certificateUrl)])
    .then(([privateKey, certificate]) => mergeResources(privateKey, certificate))
    .catch(handleErrors);
}
