#include <iostream>
#include <vector>
#include <memory>

struct OctreeNode {
    std::array<std::unique_ptr<OctreeNode>, 8> children;
    std::vector<int> data;
};

class Octree {
public:
    Octree(double featureSize, int numLeafNodes, int dataCapacity)
        : featureSize(featureSize), numLeafNodes(numLeafNodes), dataCapacity(dataCapacity) {
        root = std::make_unique<OctreeNode>();
    }

    void insert(const std::vector<double>& point, int dataId) {
        if (point.size() != 3 || featureSize <= 0 || numLeafNodes <= 0 || dataCapacity <= 0) {
            throw std::invalid_argument("Invalid input parameters");
        }
        insertRecursive(root.get(), point, dataId, 0);
    }

private:
    void insertRecursive(OctreeNode* node, const std::vector<double>& point, int dataId, int depth) {
        if (depth == numLeafNodes || node->data.size() < dataCapacity) {
            node->data.push_back(dataId);
            return;
        }
        int index = 0;
        for (int i = 0; i < 3; ++i) {
            if (point[i] > featureSize / 2) {
                index |= 1 << i;
            }
        }
        if (!node->children[index]) {
            node->children[index] = std::make_unique<OctreeNode>();
        }
        insertRecursive(node->children[index].get(), point, dataId, depth + 1);
    }

    double featureSize;
    int numLeafNodes;
    int dataCapacity;
    std::unique_ptr<OctreeNode> root;
};

int main() {
    Octree octree(1.0, 4, 10);
    octree.insert({0.5, 0.5, 0.5}, 1);
    octree.insert({-0.5, -0.5, -0.5}, 2);
    return 0;
}
