#define MAX_SENSORS 100

typedef struct {
    int id;
    double value;
    time_t timestamp;
} SensorData;

typedef struct {
    SensorData data[MAX_SENSORS];
    int count;
    pthread_mutex_t lock;
} SensorBuffer;

SensorBuffer sensor_buffer;

void init_sensor_buffer() {
    pthread_mutex_init(&sensor_buffer.lock, NULL);
}

void add_sensor_data(int id, double value) {
    pthread_mutex_lock(&sensor_buffer.lock);
    if (sensor_buffer.count < MAX_SENSORS) {
        sensor_buffer.data[sensor_buffer.count].id = id;
        sensor_buffer.data[sensor_buffer.count].value = value;
        sensor_buffer.data[sensor_buffer.count].timestamp = time(NULL);
        sensor_buffer.count++;
    }
    pthread_mutex_unlock(&sensor_buffer.lock);
}

int find_sensor_with_highest_variance(double *threshold) {
    double mean = 0, variance = 0, max_variance = -1;
    int max_id = -1;

    pthread_mutex_lock(&sensor_buffer.lock);
    for (int i = 0; i < sensor_buffer.count; i++) {
        mean += sensor_buffer.data[i].value;
    }
    if (sensor_buffer.count > 0) {
        mean /= sensor_buffer.count;
    }

    for (int i = 0; i < sensor_buffer.count; i++) {
        double diff = sensor_buffer.data[i].value - mean;
        variance += diff * diff;
    }
    if (sensor_buffer.count > 1) {
        variance /= sensor_buffer.count - 1;
    }

    for (int i = 0; i < sensor_buffer.count; i++) {
        double diff = sensor_buffer.data[i].value - mean;
        double var = diff * diff / variance;
        if (var > max_variance) {
            max_variance = var;
            max_id = sensor_buffer.data[i].id;
        }
    }

    *threshold = variance;
    pthread_mutex_unlock(&sensor_buffer.lock);

    return max_id;
}

void log_performance_metrics() {
    // Implement logging mechanism here
    printf("Logging performance metrics...\n");
}
