struct GameState {
    int energyPool;
    int cooldownTimer;
    std::mt19937 rng;
    std::uniform_int_distribution<> attackDist;

    GameState() : energyPool(100), cooldownTimer(0), rng(std::random_device{}()), attackDist(1, 4) {}
};

void performAttack(GameState& gameState) {
    if (gameState.energyPool >= 20) {
        gameState.energyPool -= 20;
        int selectedAttack = gameState.attackDist(gameState.rng);
        std::cout << "Performing attack: " << selectedAttack << std::endl;
    } else {
        std::cout << "Not enough energy to perform an attack." << std::endl;
    }
}

void gameLoop(GameState& gameState) {
    while (true) {
        if (gameState.cooldownTimer > 0) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            gameState.cooldownTimer--;
        } else {
            performAttack(gameState);
            gameState.cooldownTimer = 5 + gameState.rng() % 11; // Random cooldown between 5 and 15 seconds
        }
    }
}

int main() {
    GameState gameState;
    std::thread gameThread(gameLoop, std::ref(gameState));

    // Simulate energy replenishment over time
    while (gameState.energyPool < 200) {
        gameState.energyPool += 10; // Example of variable energy replenishment rate
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }

    gameThread.join();
    return 0;
}
