using System;
using System.Collections.Generic;
using System.Linq;

public class CustomRandomGenerator
{
    private float minValue;
    private float maxValue;
    private Random random = new Random();
    private Dictionary<float[], int> weightCache = new Dictionary<float[], int>();

    public CustomRandomGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void SetRange(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return (float)(random.NextDouble() * (maxValue - minValue) + minValue);
    }

    public int GetRandomInt()
    {
        return random.Next((int)Math.Floor(minValue), (int)Math.Ceiling(maxValue) + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if ((int)Math.Ceiling(maxValue) - (int)Math.Floor(minValue) <= 1)
            throw new ArgumentException("Range too small for exclusive random integer.");
        return random.Next((int)Math.Floor(minValue) + 1, (int)Math.Ceiling(maxValue));
    }

    public float GetRandomWeightedValue(float[] weights)
    {
        if (weights.Length == 0)
            throw new ArgumentException("Weights array cannot be empty.");

        float totalWeight = weights.Sum();
        float randomValue = random.NextDouble() * totalWeight;
        float cumulativeWeight = 0;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return minValue + (i / (float)(weights.Length - 1)) * (maxValue - minValue);
        }

        throw new InvalidOperationException("Failed to select a weighted value.");
    }

    public int GetRandomWeightedInt(float[] weights)
    {
        float[] normalizedWeights = weights.Select(w => w / weights.Sum()).ToArray();
        return GetRandomWeightedInt(normalizedWeights);
    }

    public float GetRandomWeightedValueWithCache(float[] weights)
    {
        if (!weightCache.ContainsKey(weights))
        {
            weightCache[weights] = GetRandomWeightedInt(weights);
        }
        return minValue + (weightCache[weights] / (float)(weights.Length - 1)) * (maxValue - minValue);
    }

    public int GetRandomWeightedIntWithCache(float[] weights)
    {
        if (!weightCache.ContainsKey(weights))
        {
            weightCache[weights] = GetRandomWeightedInt(weights);
        }
        return weightCache[weights];
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
