int initialize_network_config(const char *config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    json_object *root = json_tokener_parse_file(file);
    fclose(file);

    if (!root || !json_is_object(root)) {
        fprintf(stderr, "Invalid JSON format in the configuration file\n");
        json_object_put(root);
        return -1;
    }

    int active_interfaces = 0;
    json_object_object_foreach(root, key, val) {
        if (strcmp(key, "interfaces") == 0 && json_is_array(val)) {
            struct json_object_iterator it = json_object_iter_init(val);
            while ((it.current != NULL) && !json_object_iter_at_end(&it)) {
                json_object *interface = json_object_iter_val(&it);
                if (json_is_object(interface)) {
                    int is_active = 0;
                    json_object_object_foreach(interface, sub_key, sub_val) {
                        if (strcmp(sub_key, "active") == 0 && json_is_boolean(sub_val)) {
                            is_active = json_object_get_boolean(sub_val);
                        }
                    }
                    if (is_active) {
                        active_interfaces++;
                    }
                }
                json_object_iter_next(&it);
            }
        }
    }

    json_object_put(root);

    return active_interfaces;
}

int main() {
    const char *config_path = "network_config.json";
    int num_active_interfaces = initialize_network_config(config_path);
    if (num_active_interfaces >= 0) {
        printf("Number of active network interfaces: %d\n", num_active_interfaces);
    } else {
        printf("Failed to initialize network configuration.\n");
    }
    return 0;
}
