// Assume these functions are provided by a DOM traversal API
void* dom_traverse_start(const char* selector);
int dom_traverse_next(void* context, int* id);
void dom_traverse_end(void* context);

char* construct_string_with_ids(const char* input, size_t size_limit, const char* selector) {
    void* traverse_context = dom_traverse_start(selector);
    if (!traverse_context) {
        return NULL; // Error in starting traversal
    }

    int id;
    int count = 0;
    while (dom_traverse_next(traverse_context, &id)) {
        count++;
    }
    dom_traverse_end(traverse_context);

    size_t total_length = strlen(input);
    if (count > 0) {
        total_length += count * 12; // Estimate for comma-separated IDs
    }

    if (total_length > size_limit) {
        return NULL; // Exceeds size limit
    }

    char* result = (char*)malloc(total_length + 1);
    if (!result) {
        return NULL; // Memory allocation failed
    }

    strcpy(result, input);

    traverse_context = dom_traverse_start(selector);
    if (!traverse_context) {
        free(result);
        return NULL; // Error in starting traversal
    }

    int first_id = 1;
    while (dom_traverse_next(traverse_context, &id)) {
        if (!first_id) {
            strcat(result, ",");
        }
        char id_str[12];
        snprintf(id_str, sizeof(id_str), "%d", id);
        strcat(result, id_str);
        first_id = 0;
    }
    dom_traverse_end(traverse_context);

    return result;
}
