typedef struct {
    uint16 bitsPerSample;
    uint16 samplesPerPixel;
    uint16 extraSamples;
    char* sampleInfo;
    unsigned char* imageData;
    char md5Hash[33];
} TIFFMetadata;

TIFFMetadata parseTIFF(const char* filename) {
    TIFFMetadata metadata = {0};
    TIFF* tif = TIFFOpen(filename, "r");

    if (!tif) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return metadata;
    }

    uint16 bitsPerSample, samplesPerPixel, extraSamples;
    uint32 width, height;

    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) &&
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) &&
        TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples)) {

        if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
            fprintf(stderr, "Unsupported bits per sample: %d\n", bitsPerSample);
            TIFFClose(tif);
            return metadata;
        }

        if (extraSamples > 0) {
            uint16* extraSampleInfo = malloc(extraSamples * sizeof(uint16));
            if (!TIFFGetField(tif, TIFFTAG_EXTRASAMPLETYPE, extraSampleInfo)) {
                fprintf(stderr, "Error reading extra sample types\n");
                free(extraSampleInfo);
                TIFFClose(tif);
                return metadata;
            }
            metadata.sampleInfo = (char*)malloc(extraSamples * 10); // Simplified for example
            snprintf(metadata.sampleInfo, extraSamples * 10, "%d extra samples: ", extraSamples);
            for (int i = 0; i < extraSamples; ++i) {
                snprintf(metadata.sampleInfo + strlen(metadata.sampleInfo), 10, "%d ", extraSampleInfo[i]);
            }
            free(extraSampleInfo);
        }

        if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width) && TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height)) {
            metadata.imageData = (unsigned char*)malloc(width * height * bitsPerSample / 8);
            if (!metadata.imageData) {
                fprintf(stderr, "Memory allocation failed\n");
                TIFFClose(tif);
                return metadata;
            }

            tsize_t scanlineSize = TIFFScanlineSize(tif);
            for (uint32 row = 0; row < height; ++row) {
                if (TIFFReadScanline(tif, metadata.imageData + row * scanlineSize, row, 0) != scanlineSize) {
                    fprintf(stderr, "Error reading scanline %d\n", row);
                    free(metadata.imageData);
                    TIFFClose(tif);
                    return metadata;
                }
            }

            // Compute MD5 hash
            unsigned char md5[16];
            TIFFMD5File(tif, md5);
            snprintf(metadata.md5Hash, 33, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
                     md5[0], md5[1], md5[2], md5[3],
                     md5[4], md5[5], md5[6], md5[7],
                     md5[8], md5[9], md5[10], md5[11],
                     md5[12], md5[13], md5[14], md5[15]);
        }
    }

    TIFFClose(tif);
    return metadata;
}
