#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char *directory_path;
    int digits_for_extension;
    const char *file_type;
    pthread_mutex_t lock;
} RenameContext;

void* rename_files(void* arg) {
    RenameContext *context = (RenameContext*)arg;
    DIR *dir;
    struct dirent *entry;
    char old_file[MAX_FILENAME_LENGTH], new_file[MAX_FILENAME_LENGTH];
    int fd, result;

    if ((dir = opendir(context->directory_path)) == NULL) {
        perror("opendir");
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        snprintf(old_file, MAX_FILENAME_LENGTH, "%s/%s", context->directory_path, entry->d_name);
        snprintf(new_file, MAX_FILENAME_LENGTH, "%s/%.*s_%0*d.%s",
                 context->directory_path,
                 (int)strlen(entry->d_name) - strlen(context->file_type),
                 entry->d_name,
                 context->digits_for_extension,
                 0,
                 context->file_type);

        if (pthread_mutex_lock(&context->lock) != 0) {
            perror("pthread_mutex_lock");
            continue;
        }

        fd = open(old_file, O_RDONLY);
        if (fd == -1) {
            perror("open");
            pthread_mutex_unlock(&context->lock);
            continue;
        }

        result = rename(old_file, new_file);
        close(fd);

        if (result != 0) {
            perror("rename");
        } else {
            printf("Renamed %s to %s\n", old_file, new_file);
        }

        pthread_mutex_unlock(&context->lock);
    }

    closedir(dir);
    return NULL;
}

int main() {
    RenameContext context = {
        .directory_path = "/path/to/directory",
        .digits_for_extension = 3,
        .file_type = "txt",
        .lock = PTHREAD_MUTEX_INITIALIZER
    };

    pthread_t thread;
    if (pthread_create(&thread, NULL, rename_files, &context) != 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("pthread_join");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

This code snippet provides a basic structure for the `rename_files` function, which dynamically renames files in a specified directory based on the given parameters. It includes a lock mechanism to handle potential race conditions and uses POSIX threads for concurrent execution. The main function initializes the context and creates a thread to perform the renaming operation.']

