#include <stdio.h>
#include <stdlib.h>

int convertJpegToPdf(const char* jpegPath, const char* outputDir, const char* logFilePath) {
    FILE* logFile = fopen(logFilePath, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file: %s\n", logFilePath);
        return 1;
    }

    char command[256];
    snprintf(command, sizeof(command), "convert %s %s/output.pdf", jpegPath, outputDir);

    int result = system(command);
    if (result != 0) {
        fprintf(logFile, "Conversion failed with error code: %d\n", result);
        fclose(logFile);
        return 1;
    }

    fprintf(logFile, "Conversion successful\n");
    fclose(logFile);
    return 0;
}
