#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define MAX_PROCESSES 10
#define LOG_FILE "process_log.txt"
#define DEFAULT_TIMEOUT 60

typedef struct {
    pid_t pid;
    int status;
    time_t start_time;
} BackgroundProcess;

BackgroundProcess processes[MAX_PROCESSES];
int process_count = 0;

void log_process_status(int pid, int status) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "PID: %d, Status: %d\n", pid, status);
        fclose(log_file);
    }
}

void handle_signal(int signum) {
    for (int i = 0; i < process_count; i++) {
        if (processes[i].pid != 0 && waitpid(processes[i].pid, &processes[i].status, WNOHANG) > 0) {
            log_process_status(processes[i].pid, processes[i].status);
            processes[i].pid = 0;
            process_count--;
        }
    }
}

int execute_command_in_background(const char *command, int timeout_seconds) {
    if (process_count >= MAX_PROCESSES) {
        return -1; // Insufficient resources
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return -1;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("execlp"); // Should not reach here
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        processes[process_count].pid = pid;
        processes[process_count].status = -1;
        processes[process_count].start_time = time(NULL);
        process_count++;

        signal(SIGCHLD, handle_signal);

        int status;
        if (waitpid(pid, &status, WNOHANG) == 0) {
            // Process is still running
            struct timespec ts;
            ts.tv_sec = timeout_seconds;
            ts.tv_nsec = 0;

            while (process_count > 0 && waitpid(-1, NULL, WNOHANG) != -1) {
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    time_t current_time = time(NULL);
                    for (int i = 0; i < process_count; i++) {
                        if (current_time - processes[i].start_time > timeout_seconds) {
                            kill(processes[i].pid, SIGKILL);
                            log_process_status(processes[i].pid, -1);
                            processes[i].pid = 0;
                            process_count--;
                        }
                    }
                }
            }

            for (int i = 0; i < process_count; i++) {
                if (processes[i].pid != 0) {
                    waitpid(processes[i].pid, &status, 0);
                    log_process_status(processes[i].pid, status);
                    processes[i].pid = 0;
                }
            }

            return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
        } else {
            // Process has already exited
            log_process_status(pid, status);
            process_count--;
            return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
        }
    }

    return -1; // Should not reach here
}
