import java.io.File;
import java.io.IOException;
import java.net.ServerSocket;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServerLauncher {
    private static final String SERVER_LOG_FILE = "server.log";
    private static final int HEALTH_CHECK_PORT = 8081;
    private Process serverProcess;
    private ExecutorService healthCheckExecutor;

    public void launchServer() throws IOException, InterruptedException {
        if (isServerRunning()) {
            System.out.println("Server is already running.");
            return;
        }

        File tempFilesDir = new File("temp_files");
        tempFilesDir.mkdirs();

        ProcessBuilder processBuilder = new ProcessBuilder(
                "java", "-jar", "server.jar",
                "--log-file=" + SERVER_LOG_FILE,
                "--temp-dir=" + tempFilesDir.getAbsolutePath()
        );
        serverProcess = processBuilder.start();

        healthCheckExecutor = Executors.newSingleThreadExecutor();
        healthCheckExecutor.submit(() -> {
            try (ServerSocket socket = new ServerSocket(HEALTH_CHECK_PORT)) {
                while (!Thread.currentThread().isInterrupted()) {
                    System.out.println("Server is healthy.");
                    Thread.sleep(5000);
                }
            } catch (IOException | InterruptedException e) {
                // Handle exceptions
            }
        });
    }

    public void shutdownServer() throws IOException, InterruptedException {
        if (serverProcess != null && serverProcess.isAlive()) {
            serverProcess.destroy();
            serverProcess.waitFor();
        }

        healthCheckExecutor.shutdownNow();

        File tempFilesDir = new File("temp_files");
        deleteDirectory(tempFilesDir);
    }

    private boolean isServerRunning() {
        try (ServerSocket socket = new ServerSocket(HEALTH_CHECK_PORT)) {
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    private void deleteDirectory(File directory) {
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    deleteDirectory(file);
                } else {
                    file.delete();
                }
            }
        }
        directory.delete();
    }

    public static void main(String[] args) {
        ServerLauncher launcher = new ServerLauncher();
        try {
            launcher.launchServer();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }

        // Simulate graceful shutdown
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            try {
                launcher.shutdownServer();
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        }));
    }
}
