    public static async Task<object> ProcessAndPersistData(byte[] data, int? timeout = null, int? retryCount = null, bool enableLogging = false)
    {
        string connectionString = Environment.GetEnvironmentVariable("DB_CONNECTION_STRING");
        if (string.IsNullOrEmpty(connectionString))
            throw new ArgumentException("Database connection string is not configured.");

        string logFilePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "error.log");

        try
        {
            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                // Validate byte array and prepare SQL command
                SqlCommand command = PrepareSqlCommand(connection, data);

                if (enableLogging)
                    LogCommand(command, logFilePath);

                // Execute the command with retry logic
                for (int attempt = 0; attempt <= retryCount.GetValueOrDefault(0); attempt++)
                {
                    try
                    {
                        using (SqlDataReader reader = await command.ExecuteReaderAsync())
                        {
                            return reader;
                        }
                    }
                    catch (Exception ex)
                    {
                        if (attempt == retryCount.GetValueOrDefault(0))
                            throw;

                        LogError(ex, logFilePath);
                        await Task.Delay(1000); // Wait before retrying
                    }
                }
            }
        }
        catch (Exception ex)
