    public DecryptionManager(string keyFilePath, string ivFilePath, ILogService logService)
    {
        _logService = logService;
        var key = LoadSecureData(keyFilePath);
        var iv = LoadSecureData(ivFilePath);

        using (var des = new TripleDESCryptoServiceProvider())
        {
            des.Key = key;
            des.IV = iv;
            _decryptor = des.CreateDecryptor();
        }
    }

