    {
        try
        {
            return File.ReadAllBytes(filePath);
        }
        catch (Exception ex)
        {
            _logService.LogError($"Failed to load secure data from {filePath}: {ex.Message}");
            throw;
        }
    }

    public string DecryptMessage(string base64EncodedMessage, string checksumAlgorithm)
    {
        if (_cache.TryGetValue(base64EncodedMessage, out var decryptedData))
        {
            return Encoding.UTF8.GetString(decryptedData);
        }

        try
        {
            var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            decryptedData = _decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            if (checksumAlgorithm != null)
            {
                VerifyChecksum(decryptedData, checksumAlgorithm);
            }

            _cache.TryAdd(base64EncodedMessage, decryptedData);
        }
        catch (Exception ex)
        {
            _logService.LogError($"Failed to decrypt message: {ex.Message}");
            throw;
        }

        return Encoding.UTF8.GetString(decryptedData);
