using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public class UserIdentifierAnonymizer
{
    private readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private readonly int _maxCacheSize;
    private readonly object _lockObject = new object();

    public UserIdentifierAnonymizer(int maxCacheSize)
    {
        _maxCacheSize = maxCacheSize;
    }

    public string AnonymizeUserId(string userId)
    {
        if (_cache.TryGetValue(userId, out var anonymizedId))
        {
            return anonymizedId;
        }

        lock (_lockObject)
        {
            if (_cache.Count >= _maxCacheSize)
            {
                _cache.Clear();
            }

            anonymizedId = GenerateHash(userId);
            _cache.TryAdd(userId, anonymizedId);
        }

        return anonymizedId;
    }

    private string GenerateHash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(bytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }
}
