using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DataDecryptor
{
    private readonly ICryptoTransform _decryptor;
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public DataDecryptor(byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 16 && key.Length != 32)
            throw new ArgumentException("Invalid key length. Must be 16 or 32 bytes.");
        if (iv == null || iv.Length != 16)
            throw new ArgumentException("IV must be 16 bytes.");

        _key = key;
        _iv = iv;

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = _key;
            aesAlg.IV = _iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;
            _decryptor = aesAlg.CreateDecryptor();
        }
    }

    public byte[] Decrypt(byte[] ciphertext)
    {
        using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, _decryptor, CryptoStreamMode.Read))
        {
            using (MemoryStream msOutput = new MemoryStream())
            {
                csDecrypt.CopyTo(msOutput);
                return msOutput.ToArray();
            }
        }
    }

    public static byte[] GenerateKey(int keySize)
    {
        if (keySize != 128 && keySize != 256)
