import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class DeserializationUtil {

    private static final Map<String, Class<?>> supportedClasses = new HashMap<>();
    private static final String FALLBACK_CLASS_NAME = "com.example.FallbackClass";

    public static <T> T deserialize(byte[] data, Class<T> targetClass) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {

            Object obj = ois.readObject();
            if (!targetClass.isInstance(obj)) {
                logWarning("Deserialized object is not an instance of the specified class.");
                obj = instantiateFallbackClass();
            }

            return targetClass.cast(obj);

        } catch (IOException | ClassNotFoundException e) {
            logError("Failed to deserialize byte array: " + e.getMessage());
            return null;
        }
    }

    private static Object instantiateFallbackClass() {
        try {
            Class<?> fallbackClass = Class.forName(FALLBACK_CLASS_NAME);
            return fallbackClass.getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            logError("Failed to instantiate fallback class: " + e.getMessage());
            return null;
        }
    }

    private static void logWarning(String message) {
        System.out.println("[WARNING] " + message);
    }

    private static void logError(String message) {
        System.err.println("[ERROR] " + message);
    }

    // Method to fetch supported classes dynamically from an external data source
    public static void loadSupportedClasses() {
        // Implementation to fetch and cache supported classes
    }
}
