["```python
from typing import Any, Dict, List, Optional, Union
import threading

class GraphNode:
    def __init__(self, id: int, properties: Dict[str, Any]):
        self.id = id
        self.properties = properties
        self.edges = {}

class GraphEdge:
    def __init__(self, to_node_id: int, weight: Optional[float] = None):
        self.to_node_id = to_node_id
        self.weight = weight

class GraphDatabase:
    def __init__(self):
        self.nodes = {}
        self.lock = threading.Lock()

    def add_vertex(self, id: int, properties: Dict[str, Any]):
        with self.lock:
            if id not in self.nodes:
                self.nodes[id] = GraphNode(id, properties)

    def remove_vertex(self, id: int):
        with self.lock:
            if id in self.nodes:
                del self.nodes[id]

    def add_edge(self, from_id: int, to_id: int, weight: Optional[float] = None):
        with self.lock:
            if from_id in self.nodes and to_id in self.nodes:
                self.nodes[from_id].edges[to_id] = GraphEdge(to_id, weight)

    def remove_edge(self, from_id: int, to_id: int):
        with self.lock:
            if from_id in self.nodes and to_id in self.nodes:
                if to_id in self.nodes[from_id].edges:
                    del self.nodes[from_id].edges[to_id]

    def get_node_properties(self, id: int) -> Dict[str, Any]:
        with self.lock:
            if id in self.nodes:
                return self.nodes[id].properties
            return {}

    def get_neighbors(self, id: int) -> List[int]:
        with self.lock:
            if id in self.nodes:
                return list(self.nodes[id].edges.keys())
            return []

    def find_connected_components(self):
        visited = set()
        components = []
        for node_id in self.nodes:
            if node_id not in visited:
                component = self._dfs(node_id, visited)
                components.append(component)
        return components

    def _dfs(self, node_id: int, visited: set) -> List[int]:
        stack = [node_id]
        component = []
        while stack:
            current_node_id = stack.pop()
            if current_node_id not in visited:
                visited.add(current_node_id)
                component.append(current_node_id)
                for neighbor_id in self.nodes[current_node_id].edges:
                    stack.append(neighbor_id)
        return component

    def find_shortest_path(self, from_id: int, to_id: int) -> List[int]:
        if from_id not in self.nodes or to_id not in self.nodes:
            return []

        distances = {node_id: float('inf') for node_id in self.nodes}
        previous_nodes = {node_id: None for node_id in self.nodes}
        distances[from_id] = 0
        queue = [from_id]

        while queue:
            current_node_id = queue.pop(0)
            for neighbor_id, edge in self.nodes[current_node_id].edges.items():
                distance = distances[current_node_id] + (edge.weight if edge.weight is not None else 1)
                if distance < distances[neighbor_id]:
                    distances[neighbor_id] = distance
                    previous_nodes[neighbor_id] = current_node_id
                    queue.append(neighbor_id)

        path = []
        current_node_id = to_id
        while current_node_id is not None:
            path.insert(0, current_node_id)
            current_node_id = previous_nodes[current_node_id]
        return path

# Example usage
graph_db = GraphDatabase()
graph_db.add_vertex(1, {'name': 'A', 'type': 'City'})
graph_db.add_vertex(2, {'name': 'B', 'type': 'City'})
graph_db.add_edge(1, 2, weight=5)
print(graph_db.find_shortest_path(1, 2))
```"]

