use std::env;
use std::fs;
use std::path::Path;
use log::{info, error};

fn manage_config_directory(
    directory_name: &str,
    base_path: &str,
    config_system_id: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let expected_dir = Path::new(base_path).join(directory_name).join(config_system_id);
    let config_dir_var = "CONFIG_DIR";

    if let Some(current_dir) = env::var_os(config_dir_var) {
        let current_dir_path = Path::new(&current_dir);
        if current_dir_path == &expected_dir {
            info!("Using existing configuration directory: {:?}", expected_dir);
            return Ok(());
        }
    }

    match fs::create_dir_all(&expected_dir) {
        Ok(_) => {
            env::set_var(config_dir_var, expected_dir.display().to_string());
            info!("Created new configuration directory: {:?}", expected_dir);
        },
        Err(e) => {
            error!("Failed to create or validate configuration directory: {}", e);
            return Err(e.into());
        }
    }

    Ok(())
}
