import json
from xml.etree import ElementTree as ET
import yaml
from collections import defaultdict
from threading import Lock

class DataParserRegistry:
    _instance = None
    _lock = Lock()

    def __new__(cls):
        with cls._lock:
            if cls._instance is None:
                cls._instance = super(DataParserRegistry, cls).__new__(cls)
                cls._instance.parsers = defaultdict(lambda: lambda data: None)
                cls._instance.cache = {}
            return cls._instance

    @classmethod
    def register_parser(cls, format_name, parser_function):
        with cls._lock:
            cls._instance.parsers[format_name] = parser_function

    @classmethod
    def get_parser(cls, format_name):
        with cls._lock:
            return cls._instance.parsers.get(format_name)

    @classmethod
    def parse_data(cls, data, format_name):
        with cls._lock:
            if format_name in cls._instance.cache:
                return cls._instance.cache[format_name]
            parser = cls.get_parser(format_name)
            if parser:
                result = parser(data)
                cls._instance.cache[format_name] = result
                return result
            else:
                raise ValueError(f"No parser registered for format: {format_name}")

# Example usage
def json_parser(data):
    return json.loads(data)

def xml_parser(data):
    return ET.fromstring(data)

def yaml_parser(data):
    return yaml.safe_load(data)

DataParserRegistry.register_parser('json', json_parser)
DataParserRegistry.register_parser('xml', xml_parser)
DataParserRegistry.register_parser('yaml', yaml_parser)

# Parsing data
data_json = '{"name": "John", "age": 30}'
data_xml = '<person><name>John</name><age>30</age></person>'
data_yaml = 'name: John\nage: 30'

print(DataParserRegistry.parse_data(data_json, 'json'))
print(DataParserRegistry.parse_data(data_xml, 'xml'))
print(DataParserRegistry.parse_data(data_yaml, 'yaml'))
