#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ADJUSTMENTS 1000

typedef struct {
    int value;
} record;

int allocate_and_initialize(long N, int L, long **offsets, int **keys, record **records) {
    *offsets = (long *)malloc(N * sizeof(long));
    *keys = (int *)malloc(N * sizeof(int));
    *records = (record *)calloc(N, sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1; // Memory allocation failed
    }

    int total_sum = 0;
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        (*records)[i].value = rand() % 1001;
        total_sum += (*records)[i].value;
    }

    if (total_sum > L) {
        int adjustments = 0;
        while (total_sum > L && adjustments < MAX_ADJUSTMENTS) {
            for (int i = 0; i < N && total_sum > L; i++) {
                int adjustment = rand() % 1001;
                if ((*records)[i].value + adjustment <= 1000) {
                    (*records)[i].value += adjustment;
                    total_sum += adjustment;
                    adjustments++;
                }
            }
        }

        if (total_sum > L) {
            return -2; // Failed to adjust within the limit
        }
    }

    return adjustments;
}

int main() {
    long N = 1000;
    int L = 500000;
    long *offsets;
    int *keys;
    record *records;

    int result = allocate_and_initialize(N, L, &offsets, &keys, &records);

    if (result == -1) {
        printf("Memory allocation failed\n");
    } else if (result == -2) {
        printf("Failed to adjust within the limit\n");
    } else {
        printf("Total adjustments made: %d\n", result);
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
