import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class FileHashUtility {
    private static final int MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB
    private static final Map<String, String> cache = new ConcurrentHashMap<>();
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final Logger logger = LoggerFactory.getLogger(FileHashUtility.class);

    public static void processFiles(List<String> filePaths, Path logFile) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(logFile)) {
            for (String path : filePaths) {
                executorService.submit(() -> {
                    try {
                        Path resolvedPath = Paths.get(path).toRealPath();
                        if (!Files.exists(resolvedPath) || !Files.isReadable(resolvedPath)) {
                            throw new IllegalArgumentException("Invalid file path: " + path);
                        }
                        if (Files.size(resolvedPath) > MAX_FILE_SIZE) {
                            throw new IOException("File size exceeds limit: " + path);
                        }
                        String hash = computeHash(resolvedPath);
                        cache.put(path, hash);
                        writer.write(path + ": " + hash + "\n");
                    } catch (Exception e) {
                        logger.error("Error processing file: " + path, e);
                    }
                });
            }
        }
    }

    private static String computeHash(Path filePath) throws IOException, NoSuchAlgorithmException {
        if (cache.containsKey(filePath.toString())) {
            return cache.get(filePath.toString());
        }
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream is = Files.newInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) throws IOException {
        List<String> filePaths = Arrays.asList("path/to/file1", "path/to/file2");
        Path logFile = Paths.get("path/to/logfile.log");
        processFiles(filePaths, logFile);
        shutdown();
    }
}
