class FileAndDataHandlingUtils {
    /**
     * Reads a file synchronously from a specified directory and returns its content as a string.
     * @param string $filePath The path to the file to read.
     * @param int $timeoutSeconds Maximum time (in seconds) allowed for file reading operation.
     * @return string The content of the file.
     * @throws Exception If the file does not exist, exceeds the timeout limit, or cannot be read.
     */
    public function readFileContent($filePath, $timeoutSeconds) {
        if (!file_exists($filePath)) {
            throw new Exception("File not found.");
        }

        $start = microtime(true);
        $fileContent = file_get_contents($filePath);
        $end = microtime(true);

        if ($end - $start > $timeoutSeconds) {
            throw new Exception("Read operation exceeded the allowed time limit.");
        }

        return $fileContent;
    }

    /**
     * Generates a random string of a specified length using a given character set.
     * @param int $length The desired length of the random string.
     * @param array $charSet An array of characters to be used in the random string.
     * @param int $entropyLevel Minimum entropy level required for the random string.
     * @return string The generated random string.
     * @throws Exception If the operation fails, such as if the charSet is empty or entropy level is not met.
     */
    public function generateRandomString($length, $charSet, $entropyLevel) {
        if (empty($charSet)) {
            throw new Exception("Character set cannot be empty.");
        }

        $entropyCheck = function ($str) use ($entropyLevel) {
            $pattern = '/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{'.strlen($str).'}$/';
            return preg_match($pattern, $str) && hash('sha256', $str, true) !== false;
        };

        $randomString = '';
        do {
            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $randomString .= $charSet[random_int(0, count($charSet) - 1)];
            }
        } while (!$entropyCheck($randomString) || random_int(0, 10) > $entropyLevel);

        return $randomString;
    }

