#include <curl/curl.h>

typedef struct {
    CURL *handle;
    char *url;
} RequestBuilder;

RequestBuilder* create_request_builder(const char *url) {
    if (url == NULL) {
        return NULL; // Invalid input
    }

    RequestBuilder *builder = malloc(sizeof(RequestBuilder));
    if (builder == NULL) {
        return NULL; // Memory allocation failed
    }

    builder->handle = curl_easy_init();
    if (builder->handle == NULL) {
        free(builder);
        return NULL; // CURL initialization failed
    }

    builder->url = strdup(url);
    if (builder->url == NULL) {
        curl_easy_cleanup(builder->handle);
        free(builder);
        return NULL; // Memory allocation for URL failed
    }

    return builder;
}

void destroy_request_builder(RequestBuilder *builder) {
    if (builder != NULL) {
        if (builder->url != NULL) {
            free(builder->url);
        }
        curl_easy_cleanup(builder->handle);
        free(builder);
    }
}

int set_no_ssl_verification(RequestBuilder *builder, int disable) {
    if (builder == NULL) {
        return -1; // Invalid input
    }

    if (disable) {
        curl_easy_setopt(builder->handle, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(builder->handle, CURLOPT_SSL_VERIFYHOST, 0L);
    } else {
        curl_easy_setopt(builder->handle, CURLOPT_SSL_VERIFYPEER, 1L);
        curl_easy_setopt(builder->handle, CURLOPT_SSL_VERIFYHOST, 2L);
    }

    return 0; // Success
}
