        InitializeUnionFind(array);
        for (int i = 0; i < array.Length - 1; i++)
        {
            Union(array[i], array[i + 1]);
        }
        int disjointPairs = 0;
        foreach (var key in parent.Keys)
        {
            if (parent[key] == key) disjointPairs++;
        }
        long endTime = DateTime.Now.Ticks;
        Console.WriteLine($"Disjoint pairs: {disjointPairs}, Time taken: {(endTime - startTime) / TimeSpan.TicksPerMillisecond} ms");
        return disjointPairs;
    }

    private void InitializeUnionFind(int[] array)
    {
        foreach (var item in array)
        {
            parent[item] = item;
            rank[item] = 0;
        }
    }

    private int Find(int x)
    {
        if (parent[x] != x) parent[x] = Find(parent[x]);
        return parent[x];
    }

    private void Union(int x, int y)
    {
        int rootX = Find(x);
        int rootY = Find(y);
        if (rootX != rootY)
        {
            if (rank[rootX] > rank[rootY])
                parent[rootY] = rootX;
            else if (rank[rootX] < rank[rootY])
                parent[rootX] = rootY;
            else
            {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public void UpdateWeights()
