typedef struct {
    char* key;
    int value;
} NumericKeyValue;

typedef int (*KeyValidationFunction)(const char*);

char* processFileAndJSON(const char* filePath, size_t maxBufferSize, KeyValidationFunction validateKey) {
    FILE* file = fopen(filePath, "r");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize > maxBufferSize) {
        fclose(file);
        return NULL;
    }

    char* buffer = malloc(maxBufferSize + 1);
    if (!buffer) {
        fclose(file);
        return NULL;
    }

    size_t bytesRead = fread(buffer, 1, maxBufferSize, file);
    buffer[bytesRead] = '\0';
    fclose(file);

    json_object* jsonObject = json_tokener_parse(buffer);
    free(buffer);

    if (!jsonObject || !json_is_object(jsonObject)) {
        return NULL;
    }

    NumericKeyValue* keyValuePairs = malloc(sizeof(NumericKeyValue) * 100); // Initial capacity
    int count = 0;

    void parseJSON(json_object* obj, const char* parentKey) {
        json_object_object_foreach(obj, key, val) {
            if (parentKey && strlen(parentKey) > 0) {
                char fullKey[256];
                snprintf(fullKey, sizeof(fullKey), "%s.%s", parentKey, key);
                if (validateKey(fullKey)) {
                    if (count >= 100) { // Resize array
                        keyValuePairs = realloc(keyValuePairs, sizeof(NumericKeyValue) * (count + 50));
                    }
                    keyValuePairs[count].key = strdup(fullKey);
                    json_object* numVal;
                    if (json_is_number(val)) {
                        numVal = val;
                    } else if (json_is_array(val)) {
                        for (int i = 0; i < json_array_length(val); i++) {
                            json_object* item = json_array_get_idx(val, i);
                            if (json_is_number(item)) {
                                numVal = item;
                                break;
                            }
                        }
                    } else {
                        continue;
                    }
                    keyValuePairs[count].value = json_object_get_int(numVal);
                    count++;
                }
            }
            if (json_is_object(val)) {
                parseJSON(val, key);
            }
        }
    }

    parseJSON(jsonObject, "");

    char* lastModifiedTime = malloc(20);
    time_t fileTime = get_file_modification_time(filePath); // Assume this function exists
    strftime(lastModifiedTime, 20, "%Y-%m-%d %H:%M:%S", localtime(&fileTime));

    json_object_put(jsonObject);

    return lastModifiedTime;
}
