#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 500
#define MEMORY_THRESHOLD 1024 * 1024 // 1MB

typedef struct {
    int value;
} record;

int manage_memory(long* offset, int* key, record** records, size_t num_offsets, size_t num_keys) {
    if (num_offsets > MAX_OFFSET_SIZE || num_keys > MAX_KEY_SIZE) {
        fprintf(stderr, "Error: Array sizes exceed maximum limits.\n");
        return 0;
    }

    size_t total_memory = num_offsets * sizeof(long) + num_keys * sizeof(int);
    if (total_memory > MEMORY_THRESHOLD) {
        fprintf(stderr, "Error: Memory usage exceeds threshold.\n");
        return 0;
    }

    offset = realloc(offset, num_offsets * sizeof(long));
    key = realloc(key, num_keys * sizeof(int));
    records = realloc(records, num_offsets * sizeof(record*));

    if (!offset || !key || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return 0;
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Error: Record allocation failed.\n");
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offset);
            free(key);
            free(records);
            return 0;
        }
    }

    pid_t pid = fork();
    if (pid == -1) {
        fprintf(stderr, "Error: Fork failed.\n");
        // Free previously allocated memory
        for (size_t i = 0; i < num_offsets; ++i) {
            free(records[i]);
        }
        free(offset);
        free(key);
        free(records);
        return 0;
    } else if (pid == 0) {
        // Child process
        char* args[] = {"external_command", NULL};
        execvp("external_command", args);
        fprintf(stderr, "Error: Execvp failed.\n");
        exit(1);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            return 1;
        } else {
            fprintf(stderr, "Error: External command execution failed.\n");
            // Free previously allocated memory
            for (size_t i = 0; i < num_offsets; ++i) {
                free(records[i]);
            }
            free(offset);
            free(key);
            free(records);
            return 0;
        }
    }

    // Free allocated memory
    for (size_t i = 0; i < num_offsets; ++i) {
        free(records[i]);
    }
    free(offset);
    free(key);
    free(records);

    return 1;
}
