import java.io.*;
import java.util.*;

public class ObjectDeserializer {

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bis);
        try {
            return clazz.cast(ois.readObject());
        } finally {
            ois.close();
            bis.close();
        }
    }

    public static void main(String[] args) {
        // Example usage
        byte[] serializedData = ...; // Obtain serialized data from somewhere
        try {
            Object deserializedObject = deserialize(serializedData, MyClass.class);
            // Use the deserialized object
        } catch (IOException | ClassNotFoundException e) {
            handleDeserializationError(e);
        }
    }

    private static void handleDeserializationError(Exception e) {
        String errorMessage = "Failed to deserialize object: " + e.getMessage();
        System.err.println(errorMessage);
        throw new RuntimeException(errorMessage, e);
    }
}
