['```javascript
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

function executeCommands(commands) {
  const maxConcurrentCommands = parseInt(process.env.MAX_CONCURRENT_COMMANDS || '10', 10);
  const commandTimeout = parseInt(process.env.COMMAND_TIMEOUT || '5000', 10);
  const logLevel = process.env.LOG_LEVEL || 'info';

  let activeCommands = 0;
  let allOutput = '';

  function executeCommand(command) {
    if (activeCommands >= maxConcurrentCommands) {
      return new Promise((resolve, reject) => {
        setTimeout(() => executeCommand(command), 100);
      });
    }

    activeCommands++;
    const startTime = Date.now();

    return new Promise((resolve, reject) => {
      exec(command, { timeout: commandTimeout }, (error, stdout, stderr) => {
        if (error) {
          log('error', `Command failed: ${command}\n${stderr}`);
          reject(error);
        } else {
          const duration = Date.now() - startTime;
          log('info', `Command completed in ${duration}ms:\n${stdout}`);
          resolve(stdout);
        }
      });
    }).finally(() => {
      activeCommands--;
    });
  }

  function log(level, message) {
    if (logLevel === 'debug' || (logLevel === 'info' && level !== 'error')) return;
    const timestamp = new Date().toISOString();
    fs.appendFile(path.join(__dirname, 'command_logs.txt'), `[${timestamp}] [${level.toUpperCase()}] ${message}\n`, (err) => {
      if (err) console.error('Error writing log:', err);
    });
  }

  async function runCommands() {
    for (const command of commands) {
      try {
        const output = await executeCommand(command);
        allOutput += output;
      } catch (error) {
        console.error('Failed to execute command:', error);
      }
    }
    return allOutput;
  }

  return runCommands();
}

// Example usage:
executeCommands([
  'echo "Hello, World!"',
  'sleep 2 && echo "Second command"',
  'ls -la'
]).then((output) => {
  console.log('All commands executed:', output);
}).catch((error) => {
  console.error('Error executing commands:', error);
});
```

