#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for key-value pairs
typedef struct {
    int key;
    char *value;
} KeyValue;

// Define a structure for the event buffer
typedef struct {
    KeyValue *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventBuffer;

// Initialize the event buffer
void init_event_buffer(EventBuffer *buffer, size_t initial_capacity) {
    buffer->capacity = initial_capacity;
    buffer->size = 0;
    buffer->events = (KeyValue *)malloc(initial_capacity * sizeof(KeyValue));
    if (buffer->events == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&buffer->lock, NULL);
}

// Resize the event buffer
void resize_event_buffer(EventBuffer *buffer, size_t new_capacity) {
    KeyValue *new_events = (KeyValue *)realloc(buffer->events, new_capacity * sizeof(KeyValue));
    if (new_events == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    buffer->events = new_events;
    buffer->capacity = new_capacity;
}

// Add an event to the buffer
void add_event(EventBuffer *buffer, int key, const char *value) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->size == buffer->capacity) {
        resize_event_buffer(buffer, buffer->capacity * 2);
    }
    buffer->events[buffer->size].key = key;
    buffer->events[buffer->size].value = strdup(value);
    buffer->size++;
    pthread_mutex_unlock(&buffer->lock);
}

// Free the event buffer
void free_event_buffer(EventBuffer *buffer) {
    for (size_t i = 0; i < buffer->size; i++) {
        free(buffer->events[i].value);
    }
    free(buffer->events);
    pthread_mutex_destroy(&buffer->lock);
}

int main() {
    EventBuffer buffer;
    init_event_buffer(&buffer, 1024);

    add_event(&buffer, 1, "Event1");
    add_event(&buffer, 2, "Event2");

    for (size_t i = 0; i < buffer.size; i++) {
        printf("Key: %d, Value: %s\n", buffer.events[i].key, buffer.events[i].value);
    }

    free_event_buffer(&buffer);

    return 0;
}
```

