typedef struct {
    int* prime_ptr;
    int value;
} record;

bool is_prime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return false;
    }
    return true;
}

void generate_primes(int* primes, int min_prime, int max_prime) {
    bool* sieve = (bool*)calloc(max_prime + 1, sizeof(bool));
    for (int i = 2; i <= max_prime; i++) {
        if (!sieve[i]) {
            if (i >= min_prime) {
                primes[0] = i;
                int index = 1;
                while (index < 10000 && primes[index - 1] * primes[index - 1] + 2 * primes[index - 1] * i <= max_prime) {
                    primes[index++] = primes[index - 1] * primes[index - 1] + 2 * primes[index - 1] * i;
                }
            }
            for (int j = i * i; j <= max_prime; j += i) sieve[j] = true;
        }
    }
    free(sieve);
}

record* initialize_resources(int min_key, int max_key, int min_prime, int max_prime) {
    record* records = (record*)malloc(10000 * sizeof(record));
    if (!records) return NULL;

    long* offsets = (long*)malloc(10000 * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    int* keys = (int*)malloc(10000 * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        return NULL;
    }

    int* primes = (int*)malloc(10000 * sizeof(int));
    if (!primes) {
        free(keys);
        free(offsets);
        free(records);
        return NULL;
    }

    generate_primes(primes, min_prime, max_prime);

    for (int i = 0; i < 10000; i++) {
        records[i].prime_ptr = &primes[i];
        records[i].value = primes[i];
    }

    // Initialize offsets and keys with unique values
    for (int i = 0; i < 10000; i++) {
        offsets[i] = i * 1000 + rand() % 1000;
        keys[i] = min_key + rand() % (max_key - min_key + 1);
    }

    // Validate uniqueness of keys and offsets
    for (int i = 0; i < 9999; i++) {
        for (int j = i + 1; j < 10000; j++) {
            if (offsets[i] == offsets[j] || keys[i] == keys[j]) {
                free(primes);
                free(keys);
                free(offsets);
                free(records);
                return NULL;
            }
        }
    }

    // Integrate with existing system and minimize disruption
    // ...

    return records;
}

int main() {
    record* resources = initialize_resources(1, 100, 2, 1000);
    if (resources) {
        printf("Resources initialized successfully.\n");
        free(resources[0].prime_ptr); // Free the prime numbers
        free(resources);
    } else {
        printf("Failed to initialize resources.\n");
