typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    pthread_mutex_t mutex;
} CRCArray;

CRCArray* create_crc_array(size_t N) {
    CRCArray *crc_array = (CRCArray*)malloc(sizeof(CRCArray));
    if (!crc_array) return NULL;

    crc_array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array->array) {
        free(crc_array);
        return NULL;
    }

    crc_array->size = N;
    pthread_mutex_init(&crc_array->mutex, NULL);

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < N; ++i) {
        crc_array->array[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        crc_array->array[i].RNTI = rand() % 65536; // Random RNTI
        crc_array->array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
    }

    return crc_array;
}

void destroy_crc_array(CRCArray *crc_array) {
    if (crc_array) {
        pthread_mutex_destroy(&crc_array->mutex);
        free(crc_array->array);
        free(crc_array);
    }
}

void update_crc_flags(CRCArray *crc_array, uint16_t rnti_filter) {
    pthread_mutex_lock(&crc_array->mutex);

    for (size_t i = 0; i < crc_array->size; ++i) {
        if (crc_array->array[i].RNTI == rnti_filter) {
            // Update CRCFLAG based on specific conditions
            crc_array->array[i].CRC_INDICATION_REL8_TAG = !crc_array->array[i].CRC_INDICATION_REL8_TAG;
        }
    }

    pthread_mutex_unlock(&crc_array->mutex);
}

void iterate_and_update(CRCArray *crc_array, void (*update_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&crc_array->mutex);

    for (size_t i = 0; i < crc_array->size; ++i) {
        update_func(&crc_array->array[i]);
    }

    pthread_mutex_unlock(&crc_array->mutex);
}
