#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <resolv.h>

#define MAX_IP_LEN 46

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[MAX_IP_LEN];

        // Get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // Convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        printf("  %s\n", ipstr);

        // Copy the IP address to the output buffer
        if (p->ai_family == AF_INET) {
            memcpy(ip_address, &(ipv4->sin_addr), INET_ADDRSTRLEN);
        } else {
            memcpy(ip_address, &(ipv6->sin6_addr), INET6_ADDRSTRLEN);
        }

        freeaddrinfo(res); // Free the linked list
        return 0;
    }

    freeaddrinfo(res); // Free the linked list if no addresses were found
    return -1;
}

int main() {
    u_char ip_address[MAX_IP_LEN];
    int result = resolve_dns("example.com", ip_address);
    if (result == 0) {
        printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr *)ip_address));
    } else {
        printf("Failed to resolve DNS.\n");
    }
    return 0;
}
```

This code snippet provides a basic implementation of a C function that performs DNS resolution for a given hostname using standard library functions. It handles both IPv4 and IPv6 addresses, logs unsuccessful resolution attempts, and returns the IP address in a `u_char` array. The function uses `getaddrinfo` to retrieve the IP address and `inet_ntop` to convert it to a string format. Error handling is done by checking the return value of `getaddrinfo`.']

