    State* head = NULL;
    State** current = &head;

    for (int i = 0; i < num_states; i++) {
        State* new_state = malloc(sizeof(State));
        if (!new_state) {
            // Handle memory allocation failure
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
        new_state->id = states[i];
        new_state->next = NULL;

        *current = new_state;
        current = &(*current)->next;
    }

    // Initialize the FSA with the last state
    fsa->last_state = last_state;

    pthread_mutex_destroy(&mutex);
    return head;
}
