using UnityEngine;

public class ValueGenerator
{
    private float minValue;
    private float maxValue;
    private Dictionary<string, Func<float>> methodMap = new Dictionary<string, Func<float>>
    {
        { "GenerateRandomFloat", GenerateRandomFloat },
        { "GenerateRandomInt", GenerateRandomInt }
    };

    public ValueGenerator(float min, float max)
    {
        minValue = min;
        maxValue = max;
        ValidateRange();
    }

    private void ValidateRange()
    {
        if (minValue > maxValue)
        {
            Debug.LogError($"Invalid range: {minValue} > {maxValue}");
            minValue = maxValue = 0; // Default to zero range if invalid
        }
    }

    public T GenerateValue<T>(string methodType)
    {
        if (!methodMap.ContainsKey(methodType))
        {
            Debug.LogError($"Method type {methodType} not found.");
            return default(T);
        }

        try
        {
            var generator = methodMap[methodType];
            return generator();
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error generating value: {ex.Message}");
            return default(T);
        }
    }

    private float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    private int GenerateRandomInt()
    {
        return UnityEngine.Random.Range((int)minValue, (int)maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    // Additional Method: Ensure that the range is valid before proceeding with operations
    public bool ValidateRange()
    {
        return minValue <= maxValue;
    }
}
