void manage_memory(size_t long_size, size_t int_size, size_t record_size, int lower_bound, int upper_bound) {
    // Allocate and initialize 'long' offset values array
    long* long_offsets = (long*)aligned_alloc(64, long_size * sizeof(long));
    if (!long_offsets) {
        perror("Failed to allocate memory for long offsets");
        return;
    }
    memset(long_offsets, 0, long_size * sizeof(long));

    // Allocate and initialize 'int' keys array
    int* int_keys = (int*)aligned_alloc(64, int_size * sizeof(int));
    if (!int_keys) {
        perror("Failed to allocate memory for int keys");
        free(long_offsets);
        return;
    }
    memset(int_keys, 0, int_size * sizeof(int));

    // Allocate and initialize 'record' structures array
    Record* records = (Record*)aligned_alloc(64, record_size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(long_offsets);
        free(int_keys);
        return;
    }
    memset(records, 0, record_size * sizeof(Record));

    // Populate each record's int field with a random value
    srand(time(NULL));
    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        records[i].str = (char*)aligned_alloc(64, 256); // Example string size
        if (!records[i].str) {
            perror("Failed to allocate memory for record string");
            free(long_offsets);
            free(int_keys);
            free(records);
            return;
        }
        memset(records[i].str, 0, 256);
    }

    // Validation mechanisms (simplified example)
    if (long_size > 0 && int_size > 0 && record_size > 0) {
        printf("Memory allocation and initialization successful.\n");
    } else {
        fprintf(stderr, "Memory allocation failed.\n");
    }

    // Free allocated memory
    for (size_t i = 0; i < record_size; ++i) {
        free(records[i].str);
    }
    free(long_offsets);
    free(int_keys);
    free(records);
}
