#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024
#define MAX_LOG_ENTRIES 1000
#define DEFAULT_TRUNCATION_THRESHOLD 80
#define DEFAULT_CLEANUP_INTERVAL 60

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} log_severity;

typedef struct {
    unsigned long timestamp;
    char *message;
    log_severity severity;
} log_entry;

typedef struct {
    char **buffer_pointers;
    log_entry *log_entries;
    size_t N;
    size_t M;
    size_t L;
    size_t total_size;
    int truncation_threshold;
    time_t last_cleanup_time;
    pthread_mutex_t lock;
} resource_manager;

resource_manager *create_resource_manager(size_t N, size_t M, size_t L) {
    resource_manager *rm = (resource_manager *)malloc(sizeof(resource_manager));
    rm->buffer_pointers = (char **)calloc(N, sizeof(char *));
    rm->log_entries = (log_entry *)calloc(N, sizeof(log_entry));
    rm->N = N;
    rm->M = M;
    rm->L = L;
    rm->total_size = 0;
    rm->truncation_threshold = DEFAULT_TRUNCATION_THRESHOLD;
    rm->last_cleanup_time = time(NULL);
    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

void destroy_resource_manager(resource_manager *rm) {
    for (size_t i = 0; i < rm->N; i++) {
        free(rm->buffer_pointers[i]);
    }
    free(rm->buffer_pointers);
    free(rm->log_entries);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}

void log_message(resource_manager *rm, const char *message, log_severity severity) {
    pthread_mutex_lock(&rm->lock);

    // Check if total size exceeds limit and adjust message
    while (strlen(message) + rm->total_size > rm->L) {
        size_t new_length = strlen(message) * rm->truncation_threshold / 100;
        char *new_message = (char *)malloc(new_length + 1);
        strncpy(new_message, message, new_length);
        new_message[new_length] = '\0';
        free(rm->log_entries[rm->total_size % rm->N].message);
        rm->log_entries[rm->total_size % rm->N].message = new_message;
        rm->total_size -= strlen(message) - new_length;
        message = new_message;
    }

    // Add log entry
    time_t now = time(NULL);
    rm->log_entries[rm->total_size % rm->N].timestamp = (unsigned long)now;
    rm->log_entries[rm->total_size % rm->N].message = strdup(message);
    rm->log_entries[rm->total_size % rm->N].severity = severity;
    rm->total_size += strlen(message);

    // Perform cleanup if necessary
    time_t current_time = time(NULL);
    if (current_time - rm->last_cleanup_time > DEFAULT_CLEANUP_INTERVAL) {
        for (size_t i = 0; i < rm->N; i++) {
            free(rm->log_entries[i].message);
        }
        memset(rm->log_entries, 0, sizeof(log_entry) * rm->N);
        rm->total_size = 0;
        rm->last_cleanup_time = current_time;
    }

    pthread_mutex_unlock(&rm->lock);
}

int main() {
    resource_manager *rm = create_resource_manager(10, MAX_BUFFER_SIZE, 1024 * 1024);

    log_message(rm, "This is a debug message.", DEBUG);
    log_message(rm, "This is an info message.", INFO);
    log_message(rm, "This is a warning message.", WARNING);
    log_message(rm, "This is an error message.", ERROR);

    destroy_resource_manager(rm);
    return 0;
}
