#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

char* append_slash_if_needed(const char* path, size_t size_limit, char** buffer, int verify_directory) {
    if (path == NULL || buffer == NULL) {
        return NULL;
    }

    struct stat path_stat;
    if (verify_directory && lstat(path, &path_stat) != 0) {
        return NULL;
    }

    size_t path_len = strlen(path);
    size_t new_path_len = path_len + 2; // For '/' and '\0'

    if (*buffer == NULL || *buffer_size < new_path_len) {
        char* new_buffer = realloc(*buffer, new_path_len);
        if (new_buffer == NULL) {
            return NULL;
        }
        *buffer = new_buffer;
        *buffer_size = new_path_len;
    }

    strcpy((*buffer), path);
    if (path[path_len - 1] != '/' && new_path_len <= size_limit) {
        (*buffer)[path_len] = '/';
        (*buffer)[path_len + 1] = '\0';
    } else {
        (*buffer)[path_len] = '\0';
    }

    return *buffer;
}
