#include <openssl/pbkdf2.h>
#include <string.h>
#include <time.h>

#define KEY_SIZE 32
#define IV_SIZE 16
#define SALT_SIZE 16
#define PBKDF2_ITERATIONS 10000

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} CipherInstance;

CipherInstance* create_cipher_instance(const char *password, const unsigned char *salt) {
    CipherInstance *instance = malloc(sizeof(CipherInstance));
    if (!instance) return NULL;

    instance->ctx = EVP_CIPHER_CTX_new();
    if (!instance->ctx) {
        free(instance);
        return NULL;
    }

    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, SALT_SIZE, PBKDF2_ITERATIONS, EVP_sha256(), KEY_SIZE, instance->key) != 1) {
        EVP_CIPHER_CTX_free(instance->ctx);
        free(instance);
        return NULL;
    }

    if (RAND_bytes(instance->iv, IV_SIZE) != 1) {
        EVP_CIPHER_CTX_free(instance->ctx);
        free(instance);
        return NULL;
    }

    return instance;
}

void destroy_cipher_instance(CipherInstance *instance) {
    EVP_CIPHER_CTX_free(instance->ctx);
    free(instance);
}

int encrypt_data(const CipherInstance *instance, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (EVP_EncryptInit_ex(instance->ctx, EVP_aes_256_cbc(), NULL, instance->key, instance->iv) != 1) return -1;
    if (EVP_EncryptUpdate(instance->ctx, ciphertext, &plaintext_len, plaintext, plaintext_len) != 1) return -1;
    int final_len = 0;
    if (EVP_EncryptFinal_ex(instance->ctx, ciphertext + plaintext_len, &final_len) != 1) return -1;
    return plaintext_len + final_len;
}

int decrypt_data(const CipherInstance *instance, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (EVP_DecryptInit_ex(instance->ctx, EVP_aes_256_cbc(), NULL, instance->key, instance->iv) != 1) return -1;
    if (EVP_DecryptUpdate(instance->ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len) != 1) return -1;
    int final_len = 0;
    if (EVP_DecryptFinal_ex(instance->ctx, plaintext + ciphertext_len, &final_len) != 1) return -1;
    return ciphertext_len + final_len;
}
