#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int packet_id;
    int payload_length;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PacketList;

void initPacketList(PacketList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addPacket(PacketList* list, DataPacket packet) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = packet;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void updatePacket(PacketList* list, int packet_id, DataPacket new_data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            current->data = new_data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

Node* getPacketByTimestampRange(PacketList* list, int start_time, int end_time) {
    Node* resultHead = NULL;
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.timestamp >= start_time && current->data.timestamp <= end_time) {
            Node* newNode = (Node*)malloc(sizeof(Node));
            newNode->data = current->data;
            newNode->next = resultHead;
            resultHead = newNode;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return resultHead;
}

void freePacketList(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
