const axios = require('axios');
const LRU = require('lru-cache');

// Create an LRU cache instance for storing weather data
const cache = new LRU({ max: 500, maxAge: 10 * 60 * 1000 }); // Cache up to 500 items with a TTL of 10 minutes

async function fetchWeatherData(locations) {
    const results = {};
    const promises = [];

    locations.forEach(location => {
        if (cache.has(location)) {
            results[location] = cache.get(location);
        } else {
            const promise = axios.get(`https://api.weatherapi.com/v1/current.json?key=YOUR_API_KEY&q=${location}`)
                .then(response => {
                    cache.set(location, response.data.current);
                    return response.data.current;
                })
                .catch(error => {
                    console.error(`Error fetching weather data for ${location}:`, error);
                    throw error;
                });
            promises.push(promise);
        }
    });

    try {
        const responses = await Promise.all(promises);
        responses.forEach((data, index) => {
            results[locations[index]] = data;
        });
        return results;
    } catch (error) {
        console.error('Error fetching weather data:', error);
        throw error;
    }
}

// Example usage
const locations = ['New York', 'London', 'Tokyo'];
fetchWeatherData(locations)
    .then(data => {
        console.log('Fetched weather data:', data);
    })
    .catch(error => {
        console.error('Failed to fetch weather data:', error);
    });
```

