using System;
using System.Collections.Concurrent;
using System.Threading;

public class CustomRandomGenerator
{
    private readonly Random _random = new Random();
    private readonly ConcurrentDictionary<string, WeightedDistribution> _distributions = new ConcurrentDictionary<string, WeightedDistribution>();

    public float GetRandomFloat(float min, float max)
    {
        return (float)(_random.NextDouble() * (max - min) + min);
    }

    public int GetRandomInt(int min, int max)
    {
        return _random.Next(min, max + 1);
    }

    public float GetWeightedRandomFloat(string distributionKey, float[] weights)
    {
        var distribution = _distributions.GetOrAdd(distributionKey, key => new WeightedDistribution(weights));
        return distribution.GetNext();
    }

    public int GetWeightedRandomInt(string distributionKey, int[] weights)
    {
        var distribution = _distributions.GetOrAdd(distributionKey, key => new WeightedDistribution(weights));
        return distribution.GetNextInt();
    }
}

public class WeightedDistribution
{
    private readonly float[] _weights;
    private readonly float[] _cumulativeWeights;
    private readonly Random _random;

    public WeightedDistribution(float[] weights)
    {
        _weights = weights;
        _cumulativeWeights = new float[weights.Length];
        _random = new Random();

        for (int i = 0; i < weights.Length; i++)
        {
            if (i > 0)
                _cumulativeWeights[i] = _cumulativeWeights[i - 1] + weights[i];
            else
                _cumulativeWeights[i] = weights[i];
        }
    }

    public float GetNext()
    {
        float randomValue = _random.NextSingle() * _cumulativeWeights[_cumulativeWeights.Length - 1];
        int index = Array.BinarySearch(_cumulativeWeights, randomValue);
        if (index < 0)
            index = ~index;
        return _weights[index];
    }

    public int GetNextInt()
    {
        float randomValue = _random.NextSingle() * _cumulativeWeights[_cumulativeWeights.Length - 1];
        int index = Array.BinarySearch(_cumulativeWeights, randomValue);
        if (index < 0)
            index = ~index;
        return index;
    }
}
