import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;

public class CommandExecutor {
    public static void executeCommand(String command, String[] envp, File dir) {
        try {
            if (dir != null && dir.exists() && !dir.isDirectory()) {
                throw new IllegalArgumentException("The provided directory is not a valid directory");
            }

            Process process = Runtime.getRuntime().exec(command, envp, dir);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("Command execution failed with exit code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String command = "ls -l";
        String[] envp = {"PATH=/usr/bin"};
        File dir = new File("/home/user");

        executeCommand(command, envp, dir);
    }
}
