#define NR_PHY_STATS_T struct { int PCI; int NR_SFN; /* Other fields */ }
#define INITIAL_CAPACITY 1024

typedef struct {
    NR_PHY_STATS_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} PhyStatsManager;

PhyStatsManager* phy_stats_manager_init() {
    PhyStatsManager *manager = (PhyStatsManager*)malloc(sizeof(PhyStatsManager));
    manager->data = (NR_PHY_STATS_T*)calloc(INITIAL_CAPACITY, sizeof(NR_PHY_STATS_T));
    manager->size = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void phy_stats_manager_free(PhyStatsManager *manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int phy_stats_manager_insert(PhyStatsManager *manager, NR_PHY_STATS_T entry) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NR_PHY_STATS_T *new_data = (NR_PHY_STATS_T*)realloc(manager->data, new_capacity * sizeof(NR_PHY_STATS_T));
        if (!new_data) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->data = new_data;
        manager->capacity = new_capacity;
    }
    manager->data[manager->size++] = entry;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int phy_stats_manager_delete(PhyStatsManager *manager, int PCI, int NR_SFN) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].PCI == PCI && manager->data[i].NR_SFN == NR_SFN) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->data[j] = manager->data[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Entry not found
}

NR_PHY_STATS_T* phy_stats_manager_get(PhyStatsManager *manager, int PCI, int NR_SFN) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].PCI == PCI && manager->data[i].NR_SFN == NR_SFN) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->data[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Entry not found
}
