using System;
using System.Collections.Generic;
using System.Data.SqlClient;

public class DataProcessor
{
    private int minValue;
    private int maxValue;

    public DataProcessor(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public int GetRandomInt()
    {
        return new Random().Next(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue == maxValue) throw new ArgumentException("Min value cannot equal max value for exclusive random integer.");
        return new Random().Next(minValue + 1, maxValue);
    }

    public int GetRandomWeightedInt(int[] weights)
    {
        if (weights.Length != maxValue - minValue + 1) throw new ArgumentException("Weights array must match the range of values.");
        int totalWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }
        int randomValue = new Random().Next(totalWeight);
        int cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue < cumulativeWeight)
            {
                return minValue + i;
            }
        }
        throw new InvalidOperationException("Failed to select a value from the weighted distribution.");
    }

    public int FindDisjointPairs(int[] array)
    {
        UnionFind uf = new UnionFind(array.Length);
        for (int i = 0; i < array.Length - 1; i++)
        {
            if (!uf.IsConnected(i, i + 1))
            {
                uf.Union(i, i + 1);
            }
        }
        return uf.GetNumberOfComponents();
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }

    public List<Employee> GetEmployeeData(string connectionString, int supervisorId)
    {
        List<Employee> employees = new List<Employee>();
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();
                string query = "SELECT Name, City, Address FROM Employees WHERE SupervisorID = @SupervisorID";
                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@SupervisorID", supervisorId);
                    using (SqlDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            employees.Add(new Employee
                            {
                                Name = reader.GetString(0),
                                City = reader.GetString(1),
                                Address = reader.GetString(2)
                            });
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error retrieving employee data: {ex.Message}");
            }
        }
        return employees;
    }

    private class UnionFind
    {
        private int[] parent;
        private int[] rank;

        public UnionFind(int size)
        {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++)
            {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public void Union(int p, int q)
        {
            int rootP = Find(p);
            int rootQ = Find(q);
            if (rootP != rootQ)
            {
                if (rank[rootP] < rank[rootQ])
                {
                    parent[rootP] = rootQ;
                }
                else if (rank[rootP] > rank[rootQ])
                {
                    parent[rootQ] = rootP;
                }
                else
                {
                    parent[rootQ] = rootP;
                    rank[rootP]++;
                }
            }
        }

        public bool IsConnected(int p, int q)
        {
            return Find(p) == Find(q);
        }

        private int Find(int x)
        {
            if (parent[x] != x)
            {
                parent[x] = Find(parent[x]);
            }
            return parent[x];
        }

        public int GetNumberOfComponents()
        {
            HashSet<int> components = new HashSet<int>();
            for (int i = 0; i < parent.Length; i++)
            {
                components.Add(Find(i));
            }
            return components.Count;
        }
    }

    public class Employee
    {
        public string Name { get; set; }
        public string City { get; set; }
        public string Address { get; set; }
    }
}
