    int ret;

    if ((ret = avformat_open_input(&fmt_ctx, filename, NULL, NULL)) < 0) {
        fprintf(stderr, "Could not open input file '%s'", filename);
        return NULL;
    }

    if (format_name) {
        AVInputFormat *iformat = av_find_input_format(format_name);
        if (!iformat) {
            fprintf(stderr, "Unsupported format: %s\n", format_name);
            avformat_close_input(&fmt_ctx);
            return NULL;
        }
        fmt_ctx->iformat = iformat;
    }

    if ((ret = avformat_find_stream_info(fmt_ctx, NULL)) < 0) {
        fprintf(stderr, "Could not find stream information");
        avformat_close_input(&fmt_ctx);
        return NULL;
    }

    return fmt_ctx;
}

void close_media_file(AVFormatContext *fmt_ctx) {
    if (fmt_ctx) {
        avformat_close_input(&fmt_ctx);
