import requests
from retrying import retry
import time

# Define constants for API endpoints and logging
API_BASE_URL = "https://api.example.com"
LOGGING_SERVICE_URL = "https://logs.example.com"

@retry(stop_max_attempt_number=5, wait_exponential_multiplier=1000)
def fetch_config(service_id):
    response = requests.get(f"{API_BASE_URL}/config/{service_id}")
    response.raise_for_status()
    return response.json()

@retry(stop_max_attempt_number=5, wait_exponential_multiplier=1000)
def update_service(service_id, config):
    response = requests.put(f"{API_BASE_URL}/services/{service_id}", json=config)
    response.raise_for_status()

def log_message(message):
    requests.post(LOGGING_SERVICE_URL, json={"message": message})

def configure_services(service_instances):
    for service_id, params in service_instances.items():
        try:
            config = fetch_config(service_id)
            updated_params = {**params, **config}
            update_service(service_id, updated_params)
            log_message(f"Service {service_id} configured successfully.")
        except requests.exceptions.RequestException as e:
            log_message(f"Failed to configure service {service_id}: {e}")

if __name__ == "__main__":
    service_instances = {
        "service1": {"param1": "value1", "health_check_interval": 60},
        "service2": {"param2": "value2", "health_check_interval": 30}
    }
    configure_services(service_instances)
```

