typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Function to create a new record with a given key
Record* create_record(int key) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed for record\n");
        return NULL;
    }
    new_record->value = hash_function(key); // Assuming hash_function is defined elsewhere
    return new_record;
}

// Function to create a new node with a given record
Node* create_node(Record *record) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        return NULL;
    }
    new_node->record = record;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a record into the linked list
void insert_record(Node **head, Record *record) {
    Node *new_node = create_node(record);
    if (new_node == NULL) {
        return;
    }
    new_node->next = *head;
    *head = new_node;
}

// Function to free all allocated memory for records and nodes
void free_memory(Node **head, Record **records, int size) {
    Node *current = *head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->record);
        free(temp);
    }
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
}

// Function to handle database persistence
void persist_records(Node **head, int max_records) {
    // Implementation of database persistence logic here
    // This is a placeholder for actual database operations
    Node *current = *head;
    int count = 0;
    while (current != NULL && count < max_records) {
        // Persist current record to database
        printf("Persisting record with value: %d\n", current->record->value);
        current = current->next;
        count++;
    }
}

// Main function to demonstrate the usage of the above functions
int main() {
    int keys[] = {1, 2, 3, 4, 5};
    int size = sizeof(keys) / sizeof(keys[0]);
    Record **records = (Record**)malloc(size * sizeof(Record*));
    Node *head = NULL;

    for (int i = 0; i < size; i++) {
        records[i] = create_record(keys[i]);
        if (records[i] != NULL) {
            insert_record(&head, records[i]);
        }
    }

    persist_records(&head, 3); // Persist up to 3 records

    free_memory(&head, records, size);

    return 0;
}
