#include <limits.h>

#define MAX_ELEMENTS 10000000
#define MAX_UNIQUE 995000

int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

void processFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    int *data = (int *)malloc(MAX_ELEMENTS * sizeof(int));
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return;
    }

    int count = 0;
    while (fscanf(file, "%d", &data[count]) == 1 && count < MAX_ELEMENTS) {
        count++;
    }
    fclose(file);

    if (count > MAX_ELEMENTS) {
        fprintf(stderr, "Input size exceeds maximum allowed\n");
        free(data);
        return;
    }

    qsort(data, count, sizeof(int), compare);

    int uniqueCount = 1;
    for (int i = 1; i < count; i++) {
        if (data[i] != data[i - 1]) {
            uniqueCount++;
            if (uniqueCount > MAX_UNIQUE) {
                fprintf(stderr, "Too many unique integers\n");
                free(data);
                return;
            }
        } else {
            fprintf(stderr, "Duplicate found: %d\n", data[i]);
            free(data);
            exit(EXIT_FAILURE);
        }
    }

    printf("Largest integer: %d\n", data[count - 1]);

    free(data);
}

int main() {
    processFile("input.txt");
    return 0;
}
