#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define CACHE_SIZE 100

typedef struct {
    char hostname[256];
    u_char ip[4];
} DNSCacheEntry;

DNSCacheEntry cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock;

void init_cache() {
    pthread_mutex_init(&cache_lock, NULL);
}

u_char* resolveDNS(const char* hostname) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return cache[i].ip;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        // save the IP in cache
        pthread_mutex_lock(&cache_lock);
        if (cache_count < CACHE_SIZE) {
            strcpy(cache[cache_count].hostname, hostname);
            inet_pton(AF_INET, ipstr, cache[cache_count].ip);
            cache_count++;
        }
        pthread_mutex_unlock(&cache_lock);

        freeaddrinfo(res); // all done with this structure
        return cache[cache_count - 1].ip;
    }

    return NULL;
}

void* process_log_line(void* arg) {
    char* line = (char*)arg;
    // Process the log line here
    printf("Processing line: %s\n", line);
    free(line); // Free allocated memory
    return NULL;
}

int main() {
    init_cache();

    FILE* fp = fopen("web_log.txt", "r");
    if (!fp) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    char line[MAX_LINE_LENGTH];
    pthread_t threads[10]; // Example: 10 threads for processing

    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        char* processed_line = strdup(line); // Duplicate the line to avoid freeing it in main
        if (pthread_create(&threads[0], NULL, process_log_line, processed_line) != 0) {
            perror("Error creating thread");
            free(processed_line);
        }
    }

    fclose(fp);

    for (int i = 0; i < 10; i++) { // Example: Joining 10 threads
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
