#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 1024

typedef struct record {
    int value;
    struct record *next;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t size;
    int merge_consecutive;
} DynamicRecordStorage;

DynamicRecordStorage* init_storage(size_t initial_capacity, int merge_consecutive) {
    DynamicRecordStorage *storage = (DynamicRecordStorage*)malloc(sizeof(DynamicRecordStorage));
    if (!storage) {
        fprintf(stderr, "Memory allocation failed for storage\n");
        return NULL;
    }

    storage->offsets = (long*)calloc(initial_capacity, sizeof(long));
    storage->keys = (int*)calloc(initial_capacity, sizeof(int));
    storage->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!storage->offsets || !storage->keys || !storage->records) {
        fprintf(stderr, "Memory allocation failed for arrays\n");
        free(storage);
        return NULL;
    }

    storage->capacity = initial_capacity;
    storage->size = 0;
    storage->merge_consecutive = merge_consecutive;

    return storage;
}

void resize_storage(DynamicRecordStorage *storage) {
    size_t new_capacity = storage->capacity * 2;
    long *new_offsets = (long*)realloc(storage->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(storage->keys, new_capacity * sizeof(int));
    Record **new_records = (Record**)realloc(storage->records, new_capacity * sizeof(Record*));

    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        return;
    }

    storage->offsets = new_offsets;
    storage->keys = new_keys;
    storage->records = new_records;
    storage->capacity = new_capacity;
}

void add_record(DynamicRecordStorage *storage, int key, int value) {
    if (storage->size >= storage->capacity) {
        resize_storage(storage);
    }

    size_t index = hash_function(key, storage->capacity); // Assume hash_function is defined elsewhere
    while (storage->keys[index] != 0 && storage->keys[index] != key) {
        index = (index + 1) % storage->capacity;
    }

    if (storage->keys[index] == key) {
        Record *current = storage->records[index];
        while (current) {
            if (current->value == value) {
                return; // Value already exists
            }
            current = current->next;
        }
    } else {
        storage->keys[index] = key;
        storage->offsets[index] = storage->size * sizeof(Record);
        storage->records[index] = NULL;
        storage->size++;
    }

    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for new record\n");
        return;
    }

    new_record->value = value;
    new_record->next = storage->records[index];
    storage->records[index] = new_record;
}

void merge_consecutive_records(DynamicRecordStorage *storage) {
    if (!storage->merge_consecutive) {
        return;
    }

    for (size_t i = 0; i < storage->capacity - 1; i++) {
        if (storage->keys[i] != 0 && storage->keys[i + 1] == storage->keys[i] + 1) {
            Record *current = storage->records[i];
            while (current) {
                Record *next = current->next;
                free(current);
                current = next;
            }

            storage->records[i] = storage->records[i + 1];
            storage->records[i + 1] = NULL;
            storage->keys[i + 1] = 0;
        }
    }
}

void free_storage(DynamicRecordStorage *storage) {
    for (size_t i = 0; i < storage->capacity; i++) {
        Record *current = storage->records[i];
        while (current) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }

    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    free(storage);
}
