typedef struct {
    time_t timestamp;
    int packetID;
    size_t payloadLength;
} DataPacket;

DataPacket* packets = NULL;
size_t packetCount = 0;
size_t packetCapacity = 0;

void addPacket(time_t timestamp, int packetID, size_t payloadLength) {
    if (packetCount >= packetCapacity) {
        packetCapacity = (packetCapacity == 0) ? 1 : packetCapacity * 2;
        packets = realloc(packets, packetCapacity * sizeof(DataPacket));
    }
    packets[packetCount].timestamp = timestamp;
    packets[packetCount].packetID = packetID;
    packets[packetCount].payloadLength = payloadLength;
    packetCount++;
}

void updatePacket(int packetID, time_t newTimestamp, size_t newPayloadLength) {
    for (size_t i = 0; i < packetCount; i++) {
        if (packets[i].packetID == packetID) {
            packets[i].timestamp = newTimestamp;
            packets[i].payloadLength = newPayloadLength;
            return;
        }
    }
}

DataPacket* get_packets_in_range(time_t start, time_t end) {
    static DataPacket* result = NULL;
    size_t resultCount = 0;

    for (size_t i = 0; i < packetCount; i++) {
        if (packets[i].timestamp >= start && packets[i].timestamp <= end) {
            resultCount++;
        }
    }

    result = realloc(result, resultCount * sizeof(DataPacket));
    size_t j = 0;
    for (size_t i = 0; i < packetCount; i++) {
        if (packets[i].timestamp >= start && packets[i].timestamp <= end) {
            result[j++] = packets[i];
        }
    }

    return result;
}

// Function to generate random values within specified ranges
int random_int_in_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

float random_float_in_range(float min, float max) {
    return min + ((float)rand() / RAND_MAX) * (max - min);
}

// Function to handle weighted distributions for integers
int weighted_random_int(int* weights, int numWeights) {
    int totalWeight = 0;
    for (int i = 0; i < numWeights; i++) {
        totalWeight += weights[i];
    }

    int randomValue = rand() % totalWeight;
    int cumulativeWeight = 0;

    for (int i = 0; i < numWeights; i++) {
        cumulativeWeight += weights[i];
        if (randomValue < cumulativeWeight) {
            return i;
        }
    }

    return numWeights - 1; // Fallback
}

// Function to handle weighted distributions for floats
float weighted_random_float(float* weights, float* values, int numWeights) {
    float totalWeight = 0.0f;
    for (int i = 0; i < numWeights; i++) {
        totalWeight += weights[i];
    }

    float randomValue = ((float)rand() / RAND_MAX) * totalWeight;
    float cumulativeWeight = 0.0f;

    for (int i = 0; i < numWeights; i++) {
        cumulativeWeight += weights[i];
        if (randomValue < cumulativeWeight) {
            return values[i];
        }
    }

    return values[numWeights - 1]; // Fallback
}

// Example usage
int main() {
    srand(time(NULL));

    addPacket(time(NULL), 1, 1024);
    updatePacket(1, time(NULL) + 60, 2048);

    DataPacket* rangePackets = get_packets_in_range(time(NULL) - 3600, time(NULL));
    for (size_t i = 0; i < packetCount; i++) {
        printf("Timestamp: %ld, Packet ID: %d, Payload Length: %zu\n", rangePackets[i].timestamp, rangePackets[i].packetID, rangePackets[i].payloadLength);
    }

    free(rangePackets);

    int weights[] = {10, 20, 30};
    int randomInt = weighted_random_int(weights, sizeof(weights) / sizeof(weights[0]));
    printf("Random Int: %d\n", randomInt);

    float weightFloats[] = {0.5f, 0.3f, 0.2f};
    float valueFloats[] = {1.0f, 2.0f, 3.0f};
    float randomFloat = weighted_random_float(weightFloats, valueFloats, sizeof(weightFloats) / sizeof(weightFloats[0]));
    printf("Random Float: %f\n", randomFloat);

    return 0;
}
