typedef struct HashNode {
    DataPacket data;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(capacity, sizeof(HashNode*));
    table->capacity = capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node != NULL) {
            HashNode* next = node->next;
            free(node->data.metadata);
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hashFunction(uint32_t packetID, size_t capacity) {
    return packetID % capacity;
}

void addPacket(HashTable* table, DataPacket newPacket) {
    pthread_mutex_lock(&table->lock);
    size_t index = hashFunction(newPacket.packetID, table->capacity);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->data = newPacket;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

void updatePacket(HashTable* table, uint32_t packetID, DataPacket updatedPacket) {
    pthread_mutex_lock(&table->lock);
    size_t index = hashFunction(packetID, table->capacity);
    HashNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->data.packetID == packetID) {
            free(node->data.metadata);
            node->data = updatedPacket;
            break;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
