#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_BUFFER_SIZE 1024
#define MAX_LOG_ENTRIES 1000
#define HASH_LIMIT 100

typedef enum {DEBUG, INFO, WARNING, ERROR} severity_level;

typedef struct {
    unsigned long timestamp;
    char *message;
    severity_level level;
} log_entry;

char* generate_random_string(int length, const char* charset) {
    static char buffer[MAX_BUFFER_SIZE];
    int charset_length = strlen(charset);
    for (int i = 0; i < length; i++) {
        buffer[i] = charset[rand() % charset_length];
    }
    buffer[length] = '\0';
    return buffer;
}

unsigned long hash_password(const char* password) {
    unsigned long hash = 5381;
    int c;
    while ((c = *password++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % HASH_LIMIT;
}

void manage_resources(int N, int M, unsigned long L, char* charset) {
    static log_entry *log_entries[MAX_LOG_ENTRIES] = {NULL};
    static char *message_buffers[MAX_LOG_ENTRIES] = {NULL};
    static size_t total_size = 0;

    for (int i = 0; i < N; i++) {
        if (!log_entries[i]) {
            log_entries[i] = malloc(sizeof(log_entry));
            message_buffers[i] = malloc(M);
        }
        char *random_string = generate_random_string(M, charset);
        unsigned long hash_value = hash_password(random_string);

        size_t new_size = strlen(random_string) + 1;
        if (total_size + new_size > L) {
            // Handle overflow and adjust message content
            printf("Adjusting message content to fit within the limit.\n");
            random_string[new_size - 2] = '\0'; // Truncate for demonstration
            new_size--;
        }

        strcpy(message_buffers[i], random_string);
        log_entries[i]->timestamp = time(NULL);
        log_entries[i]->message = message_buffers[i];
        log_entries[i]->level = INFO;

        total_size += new_size;
    }

    // Periodic cleanup mechanism
    for (int i = 0; i < N; i++) {
        if (log_entries[i] && log_entries[i]->timestamp + 3600 < time(NULL)) { // Cleanup after 1 hour
            free(log_entries[i]);
            free(message_buffers[i]);
            log_entries[i] = NULL;
            message_buffers[i] = NULL;
            total_size -= strlen(log_entries[i]->message) + 1;
        }
    }

    printf("Total size of message buffers: %zu\n", total_size);
}

int main() {
    srand(time(NULL));
    manage_resources(5, 20, 1000, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");
    return 0;
}
