    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    KeyValue* data;
    int size;
    int capacity;
} Event;

typedef struct {
    Event** events;
    int count;
    std::atomic<int> successful_allocations;
} EventManager;

EventManager* create_event_manager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;
    manager->events = (Event**)calloc(MAX_EVENTS, sizeof(Event*));
    if (!manager->events) {
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->successful_allocations.store(0);
    return manager;
}

void destroy_event_manager(EventManager* manager) {
    for (int i = 0; i < manager->count; ++i) {
        Event* event = manager->events[i];
        if (event) {
            free(event->data);
            free(event);
        }
    }
    free(manager->events);
    free(manager);
}

Event* create_event(RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    Event* event = (Event*)malloc(sizeof(Event));
    if (!event) return NULL;
    event->ue_info_tag = ue_info_tag;
    event->rnti = rnti;
    event->crc_indication_rel8_tag = crc_indication_rel8_tag;
    event->data = (KeyValue*)calloc(10, sizeof(KeyValue)); // Initial capacity
    if (!event->data) {
        free(event);
        return NULL;
    }
    event->size = 0;
    event->capacity = 10;
    return event;
}

void destroy_event(Event* event) {
    free(event->data);
    free(event);
}

int add_key_value(Event* event, int key, int value) {
    if (event->size == event->capacity) {
        KeyValue* new_data = (KeyValue*)realloc(event->data, event->capacity * 2 * sizeof(KeyValue));
        if (!new_data) return -1;
        event->data = new_data;
        event->capacity *= 2;
    }
    event->data[event->size].key = key;
    event->data[event->size].value = value;
    ++event->size;
    return 0;
}

void* process_events(void* arg) {
    EventManager* manager = (EventManager*)arg;
    // Simulate processing events
    for (int i = 0; i < MAX_EVENTS; ++i) {
        Event* event = create_event(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
        if (!event) continue;
        add_key_value(event, i, i * 2);
        manager->events[manager->count++] = event;
        ++manager->successful_allocations;
    }
    return NULL;
}

int main() {
    EventManager* manager = create_event_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create event manager\n");
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_events, manager)) {
        fprintf(stderr, "Failed to create thread\n");
        destroy_event_manager(manager);
        return 1;
    }

    pthread_join(thread, NULL);

    printf("Successful allocations: %d\n", manager->successful_allocations.load());

    destroy_event_manager(manager);
    return 0;
}
