// Function to initialize dynamic memory for multiple data structures
void* init_dynamic_memory(int num_elements, char type, int include_color) {
    void* memory = NULL;
    switch (type) {
        case 'd': // Double precision floating-point numbers
            memory = malloc(num_elements * sizeof(double));
            break;
        case 's': // Char strings
            memory = malloc(num_elements * sizeof(char *));
            for (int i = 0; i < num_elements; i++) {
                ((char **)memory)[i] = malloc(256); // Assuming max string length of 255
            }
            break;
        case 'p': // Struct point objects
            memory = malloc(num_elements * sizeof(Point));
            if (include_color) {
                for (int i = 0; i < num_elements; i++) {
                    ((Point *)memory)[i].color = malloc(sizeof(Color));
                }
            }
            break;
        default:
            fprintf(stderr, "Invalid type\n");
            exit(EXIT_FAILURE);
    }
    return memory;
}

// Function to free dynamically allocated memory
void free_dynamic_memory(void* memory, char type, int include_color) {
    switch (type) {
        case 'd': // Double precision floating-point numbers
            free(memory);
            break;
        case 's': // Char strings
            for (int i = 0; i < num_elements; i++) {
                free(((char **)memory)[i]);
            }
            free(memory);
            break;
        case 'p': // Struct point objects
            for (int i = 0; i < num_elements; i++) {
                if (((Point *)memory)[i].color) {
                    free(((Point *)memory)[i].color);
                }
            }
            free(memory);
            break;
    }
}

// Function to perform distance calculation between two points
double calculate_distance(Point p1, Point p2) {
    // Use an external library for advanced geometric computations
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

// Function to determine centroid of a set of points
Point find_centroid(Point* points, int num_points) {
    Point centroid = {0.0, 0.0};
    for (int i = 0; i < num_points; i++) {
        centroid.x += points[i].x;
        centroid.y += points[i].y;
    }
    centroid.x /= num_points;
    centroid.y /= num_points;
    return centroid;
}

// Function to sort points based on user-defined comparison function
void sort_points(Point* points, int num_points, int (*compare)(const void*, const void*)) {
    qsort(points, num_points, sizeof(Point), compare);
}

