#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 500
#define RECORD_SIZE sizeof(record)
#define PAGE_SIZE 4096

typedef struct record {
    int value;
} record;

typedef struct node {
    record *data;
    struct node *next;
} node;

typedef struct memory_pool {
    char *pool;
    size_t size;
    size_t used;
} memory_pool;

memory_pool *create_memory_pool(size_t initial_size) {
    memory_pool *mp = (memory_pool *)malloc(sizeof(memory_pool));
    mp->pool = (char *)malloc(initial_size);
    mp->size = initial_size;
    mp->used = 0;
    return mp;
}

void destroy_memory_pool(memory_pool *mp) {
    free(mp->pool);
    free(mp);
}

void *allocate_from_pool(memory_pool *mp, size_t size) {
    if (mp->used + size > mp->size) {
        // Resize the pool
        mp->size *= 2;
        mp->pool = realloc(mp->pool, mp->size);
    }
    void *ptr = mp->pool + mp->used;
    mp->used += size;
    return ptr;
}

long hash_function(int key) {
    // Custom hash function to minimize collisions
    return (key * 2654435761) % MAX_KEY_SIZE;
}

void allocate_arrays_and_list(long **offsets, int **keys, record ***records, node **head, size_t num_keys, memory_pool *mp) {
    if (num_keys > MAX_KEY_SIZE) {
        fprintf(stderr, "Error: Number of keys exceeds maximum limit.\n");
        exit(EXIT_FAILURE);
    }

    *offsets = (long *)allocate_from_pool(mp, num_keys * sizeof(long));
    *keys = (int *)allocate_from_pool(mp, num_keys * sizeof(int));
    *records = (record **)allocate_from_pool(mp, num_keys * sizeof(record *));
    *head = NULL;

    for (size_t i = 0; i < num_keys; ++i) {
        (*offsets)[i] = hash_function((*keys)[i]);
        (*records)[i] = (record *)allocate_from_pool(mp, RECORD_SIZE);
        (*records)[i]->value = hash_function((*keys)[i]); // Initialize with hash value
        node *new_node = (node *)allocate_from_pool(mp, sizeof(node));
        new_node->data = (*records)[i];
        new_node->next = *head;
        *head = new_node;
    }
}

void free_arrays_and_list(long *offsets, int *keys, record **records, node *head) {
    while (head != NULL) {
        node *temp = head;
        head = head->next;
        free(temp->data);
        free(temp);
    }
    free(offsets);
    free(keys);
    for (size_t i = 0; i < MAX_KEY_SIZE; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
}

int main() {
    size_t num_keys = 100;
    long *offsets;
    int *keys;
    record **records;
    node *head;

    memory_pool *mp = create_memory_pool(PAGE_SIZE);

    allocate_arrays_and_list(&offsets, &keys, &records, &head, num_keys, mp);

    // Use the allocated arrays and list...

    free_arrays_and_list(offsets, keys, records, head);
    destroy_memory_pool(mp);

    return 0;
}
