#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
    struct record *next;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicRecordStorage;

DynamicRecordStorage* init_storage(size_t initial_capacity) {
    DynamicRecordStorage *storage = (DynamicRecordStorage*)malloc(sizeof(DynamicRecordStorage));
    if (!storage) return NULL;

    storage->offsets = (long*)calloc(initial_capacity, sizeof(long));
    storage->keys = (int*)calloc(initial_capacity, sizeof(int));
    storage->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    storage->capacity = initial_capacity;
    storage->size = 0;
    pthread_mutex_init(&storage->lock, NULL);

    if (!storage->offsets || !storage->keys || !storage->records) {
        free(storage);
        return NULL;
    }

    return storage;
}

void destroy_storage(DynamicRecordStorage *storage) {
    for (size_t i = 0; i < storage->size; ++i) {
        Record *current = storage->records[i];
        while (current) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }

    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

int insert_record(DynamicRecordStorage *storage, int key, int value) {
    pthread_mutex_lock(&storage->lock);

    if (storage->size >= storage->capacity) {
        // Resize the storage
        size_t new_capacity = storage->capacity * 2;
        long *new_offsets = (long*)realloc(storage->offsets, new_capacity * sizeof(long));
        int *new_keys = (int*)realloc(storage->keys, new_capacity * sizeof(int));
        Record **new_records = (Record**)realloc(storage->records, new_capacity * sizeof(Record*));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&storage->lock);
            return -1; // Memory allocation failed
        }

        storage->offsets = new_offsets;
        storage->keys = new_keys;
        storage->records = new_records;
        storage->capacity = new_capacity;
    }

    size_t index = key % storage->capacity;
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&storage->lock);
        return -1; // Memory allocation failed
    }

    new_record->value = value;
    new_record->next = storage->records[index];
    storage->records[index] = new_record;

    storage->keys[storage->size] = key;
    storage->offsets[storage->size] = (long)new_record;
    ++storage->size;

    pthread_mutex_unlock(&storage->lock);
    return 0; // Success
}

// Additional functions for concurrency support, customizable node compression,
// resource monitoring, dynamic hash function selection, error reporting and logging,
// and performance profiling can be implemented here.
