typedef struct {
    double temperature;
    time_t timestamp;
} sensor;

void initialize_sensors(double *temperatures, time_t *timestamps, sensor *sensors, size_t N, double mu, double sigma, double T_max) {
    srand(time(NULL));
    double total_temp = 0.0;

    // Initialize sensors with Gaussian distribution
    for (size_t i = 0; i < N; ++i) {
        temperatures[i] = mu + sigma * rand() / (RAND_MAX / 2.0);
        timestamps[i] = time(NULL);
        sensors[i].temperature = temperatures[i];
        sensors[i].timestamp = timestamps[i];
        total_temp += temperatures[i];
    }

    // Calculate average temperature
    double avg_temp = total_temp / N;

    // Adjust temperatures if average exceeds T_max
    if (avg_temp > T_max) {
        double adjustment_factor = T_max / avg_temp;
        for (size_t i = 0; i < N; ++i) {
            sensors[i].temperature *= adjustment_factor;
        }
    }
}
