int initialize_arrays(long *offsets, int *keys, int N, int key_range_start, int key_range_end) {
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        if (keys[i] <= 0 || keys[i] > key_range_end) {
            fprintf(stderr, "Invalid key: %d\n", keys[i]);
            return -1;
        }
    }

    int unique_div_by_3 = 0;
    for (int i = 0; i < N; i++) {
        if (keys[i] % 3 == 0) {
            unique_div_by_3++;
        }
    }

    record *records = malloc(unique_div_by_3 * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    int random_values[unique_div_by_3];
    for (int i = 0; i < unique_div_by_3; i++) {
        do {
            random_values[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        } while (i > 0 && random_values[i] == random_values[i - 1]);
    }

    for (int i = 0, j = 0; i < N; i++) {
        if (keys[i] % 3 == 0) {
            records[j].value = random_values[j];
            j++;
        }
    }

    // Log initialization steps
    printf("Initialized offsets array with %d elements\n", N);
    printf("Initialized keys array with %d unique values divisible by 3\n", unique_div_by_3);

    return 0;
}

int main() {
    int N = 10;
    long *offsets = malloc(N * sizeof(long));
    int *keys = malloc(N * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize offsets array with non-negative values
    for (int i = 0; i < N; i++) {
        offsets[i] = rand() % 100;
    }

    if (initialize_arrays(offsets, keys, N, 1, 100) != 0) {
        free(offsets);
        free(keys);
        return -1;
    }

    // Free allocated memory
    free(offsets);
    free(keys);

    return 0;
}
