#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <dlfcn.h>

typedef struct {
    char *name;
    char *weaknesses;
} PokemonType;

typedef struct {
    void *(*get_pokemon_type)(const char *);
} PokemonLibrary;

char* encrypt_pokemon_name(const char *name, const unsigned char *key) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
    memset(iv, 0, sizeof(iv));

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int len;
    unsigned char *encrypted = malloc(strlen(name) + EVP_MAX_BLOCK_LENGTH);
    if (!encrypted) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptUpdate(ctx, encrypted, &len, (unsigned char *)name, strlen(name))) {
        free(encrypted);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    int final_len;
    if (1 != EVP_EncryptFinal_ex(ctx, encrypted + len, &final_len)) {
        free(encrypted);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    encrypted[len + final_len] = '\0';
    EVP_CIPHER_CTX_free(ctx);

    return encrypted;
}

char* get_pokemon_weaknesses(const char *name) {
    void *handle = dlopen("libpokemon.so", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading library: %s\n", dlerror());
        return NULL;
    }

    PokemonLibrary *lib = (PokemonLibrary *)dlsym(handle, "get_pokemon_library");
    const char *error = dlerror();
    if (error) {
        fprintf(stderr, "Error retrieving symbol: %s\n", error);
        dlclose(handle);
        return NULL;
    }

    PokemonType (*get_type)(const char *);
    get_type = lib->get_pokemon_type;

    PokemonType type = get_type(name);
    if (!type.name || !type.weaknesses) {
        fprintf(stderr, "Error retrieving Pokemon type or weaknesses\n");
        dlclose(handle);
        return NULL;
    }

    dlclose(handle);

    return strdup(type.weaknesses);
}

char* get_encrypted_pokemon_weaknesses(const char *name, const unsigned char *key) {
    char *encrypted_name = encrypt_pokemon_name(name, key);
    if (!encrypted_name) {
        fprintf(stderr, "Error encrypting Pokemon name\n");
        return NULL;
    }

    char *weaknesses = get_pokemon_weaknesses(encrypted_name);
    free(encrypted_name);

    return weaknesses;
}
