#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double temperature;
    time_t timestamp;
} Sensor;

double gaussian(double mu, double sigma) {
    static const double two_pi = 2.0 * M_PI;
    double u1, u2, v1, v2, s;
    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);
        v1 = 2 * u1 - 1;
        v2 = 2 * u2 - 1;
        s = v1 * v1 + v2 * v2;
    } while (s >= 1 || s == 0);
    double multiplier = sqrt(-2 * log(s) / s);
    return mu + sigma * v1 * multiplier;
}

Sensor* initialize_sensors(int N, double mu, double sigma, double T_max) {
    Sensor* sensors = malloc(N * sizeof(Sensor));
    if (!sensors) {
        perror("Failed to allocate memory for sensors");
        exit(EXIT_FAILURE);
    }

    double total_temp = 0;
    for (int i = 0; i < N; ++i) {
        sensors[i].temperature = gaussian(mu, sigma);
        sensors[i].timestamp = time(NULL);
        total_temp += sensors[i].temperature;
    }

    if (total_temp / N > T_max) {
        double adjustment_factor = T_max / (total_temp / N);
        for (int i = 0; i < N; ++i) {
            sensors[i].temperature *= adjustment_factor;
        }
    }

    return sensors;
}

EVP_CIPHER_CTX* manage_resources(const char* command, const char* input_string) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Failed to create cipher context");
        exit(EXIT_FAILURE);
    }

    unsigned char md5_hash[EVP_MAX_MD_SIZE];
    if (EVP_Digest(input_string, strlen(input_string), md5_hash, NULL, EVP_md5(), NULL) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        perror("Failed to compute MD5 hash");
        exit(EXIT_FAILURE);
    }

    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, md5_hash, md5_hash) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        perror("Failed to initialize encryption context");
        exit(EXIT_FAILURE);
    }

    return ctx;
}

int main() {
    const char* command = "encrypt";
    const char* input_string = "Hello, World!";
    Sensor* sensors = initialize_sensors(100, 25.0, 5.0, 30.0);
    EVP_CIPHER_CTX* ctx = manage_resources(command, input_string);

    // Use the cipher context and sensor data for further operations

    free(sensors);
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
