#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_PRECISION_RANGE 100.0
#define TIME_WINDOW_SECONDS (60 * 60) // 1 hour

typedef struct {
    float precision;
    double timestamp;
} Measurement;

int allocate_and_initialize(float **precision_values, double **timestamps, int N, float threshold, pthread_mutex_t *mutex) {
    *precision_values = malloc(N * sizeof(float));
    if (*precision_values == NULL) {
        perror("Failed to allocate memory for precision values");
        return -1;
    }

    *timestamps = malloc(N * sizeof(double));
    if (*timestamps == NULL) {
        free(*precision_values);
        perror("Failed to allocate memory for timestamps");
        return -1;
    }

    pthread_mutex_lock(mutex);

    // Initialize arrays with random data
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        (*precision_values)[i] = ((float)rand() / RAND_MAX) * MAX_PRECISION_RANGE;
        (*timestamps)[i] = time(NULL) + rand() % 1000; // Random timestamp in the next 1000 seconds
    }

    pthread_mutex_unlock(mutex);

    return 0;
}

int process_measurements(float *precision_values, double *timestamps, int N, float threshold, Measurement **measurements, int *measurement_count, pthread_mutex_t *mutex) {
    pthread_mutex_lock(mutex);

    for (int i = 0; i < N; i++) {
        if (precision_values[i] > threshold && precision_values[i] >= 0.0 && precision_values[i] <= MAX_PRECISION_RANGE) {
            Measurement new_measurement;
            new_measurement.precision = precision_values[i];
            new_measurement.timestamp = timestamps[i];

            // Check for uniqueness within the time window
            int is_unique = 1;
            for (int j = 0; j < *measurement_count; j++) {
                if (fabs(new_measurement.timestamp - (*measurements)[j].timestamp) <= TIME_WINDOW_SECONDS &&
                    fabs(new_measurement.precision - (*measurements)[j].precision) < 1e-6) {
                    is_unique = 0;
                    break;
                }
            }

            if (is_unique) {
                *measurements = realloc(*measurements, (*measurement_count + 1) * sizeof(Measurement));
                if (*measurements == NULL) {
                    perror("Failed to reallocate memory for measurements");
                    pthread_mutex_unlock(mutex);
                    return -1;
                }

                (*measurements)[*measurement_count] = new_measurement;
                (*measurement_count)++;
            }
        }
    }

    pthread_mutex_unlock(mutex);

    return 0;
}

int main() {
    int N = 1000;
    float threshold = 50.0;
    Measurement *measurements = NULL;
    int measurement_count = 0;
    pthread_mutex_t mutex;

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        return -1;
    }

    float *precision_values = NULL;
    double *timestamps = NULL;

    if (allocate_and_initialize(&precision_values, &timestamps, N, threshold, &mutex) == 0) {
        if (process_measurements(precision_values, timestamps, N, threshold, &measurements, &measurement_count, &mutex) == 0) {
            printf("Processed %d measurements\n", measurement_count);
        }
    }

    free(precision_values);
    free(timestamps);
    pthread_mutex_destroy(&mutex);

    return 0;
}
