#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <signal.h>
#include <pthread.h>

#define SEM_FILE "/tmp/my_semaphore"
#define MAX_SEM_COUNT 100

sem_t *sem;
int sem_count = 0;
pthread_mutex_t count_lock;

void cleanup_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        sem_close(sem);
        sem_unlink(SEM_FILE);
        exit(0);
    }
}

void init_semaphore(int initial_value) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sem = sem_open(SEM_FILE, O_CREAT | O_EXCL, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(1);
    }

    pthread_mutex_init(&count_lock, NULL);
}

void destroy_semaphore() {
    sem_close(sem);
    sem_unlink(SEM_FILE);
    pthread_mutex_destroy(&count_lock);
}

void reset_semaphore(int new_value) {
    sem_t *new_sem = sem_open(SEM_FILE, O_CREAT | O_EXCL, 0644, new_value);
    if (new_sem == SEM_FAILED) {
        perror("Failed to create new semaphore");
        return;
    }

    sem_close(sem);
    sem_unlink(SEM_FILE);
    sem = new_sem;
}

void acquire_semaphore() {
    pthread_mutex_lock(&count_lock);
    if (sem_count >= MAX_SEM_COUNT) {
        printf("Semaphore limit reached\n");
        pthread_mutex_unlock(&count_lock);
        return;
    }
    sem_wait(sem);
    sem_count++;
    pthread_mutex_unlock(&count_lock);
}

void release_semaphore() {
    pthread_mutex_lock(&count_lock);
    sem_post(sem);
    sem_count--;
    pthread_mutex_unlock(&count_lock);
}
