#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_IDENTIFIER_LENGTH 256
#define MIN_ALLOC_SIZE 10
#define DEFAULT_REALLOC_FACTOR 2

typedef struct Record {
    long offset;
    int key;
    char identifier[MAX_IDENTIFIER_LENGTH];
} Record;

typedef struct RecordSet {
    Record *records;
    size_t capacity;
    size_t size;
    clock_t allocation_time;
    int reallocations;
} RecordSet;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

RecordSet* create_record_set(size_t initial_capacity) {
    if (initial_capacity == 0) {
        log_error("Initial capacity must be greater than zero.");
    }
    RecordSet *set = malloc(sizeof(RecordSet));
    if (!set) {
        log_error("Memory allocation failed.");
    }
    set->records = malloc(initial_capacity * sizeof(Record));
    if (!set->records) {
        free(set);
        log_error("Memory allocation failed.");
    }
    set->capacity = initial_capacity;
    set->size = 0;
    set->allocation_time = clock();
    set->reallocations = 0;
    return set;
}

void destroy_record_set(RecordSet *set) {
    if (set->records) {
        free(set->records);
    }
    free(set);
}

void resize_record_set(RecordSet *set, size_t new_capacity) {
    Record *new_records = realloc(set->records, new_capacity * sizeof(Record));
    if (!new_records) {
        log_error("Memory reallocation failed.");
    }
    set->records = new_records;
    set->capacity = new_capacity;
    set->reallocations++;
}

void add_record(RecordSet *set, long offset, int key, const char *identifier) {
    if (set->size >= set->capacity) {
        size_t new_capacity = set->capacity ? set->capacity * DEFAULT_REALLOC_FACTOR : MIN_ALLOC_SIZE;
        resize_record_set(set, new_capacity);
    }
    Record *record = &set->records[set->size++];
    record->offset = offset;
    record->key = key;
    strncpy(record->identifier, identifier, MAX_IDENTIFIER_LENGTH - 1);
    record->identifier[MAX_IDENTIFIER_LENGTH - 1] = '\0';
}

int hash_function(int key) {
    // Simple hash function for demonstration purposes
    return abs(key % set->capacity);
}

void process_input(RecordSet *set) {
    int offset;
    int key;
    char identifier[MAX_IDENTIFIER_LENGTH];

    while (scanf("%ld %d %s", &offset, &key, identifier) == 3) {
        add_record(set, offset, key, identifier);
    }
}

void process_file(RecordSet *set, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open file.");
    }

    int offset;
    int key;
    char identifier[MAX_IDENTIFIER_LENGTH];

    while (fscanf(file, "%ld %d %s", &offset, &key, identifier) == 3) {
        add_record(set, offset, key, identifier);
    }

    fclose(file);
}

void monitor_performance(RecordSet *set) {
    clock_t current_time = clock();
    double time_taken = (double)(current_time - set->allocation_time) / CLOCKS_PER_SEC;
    printf("Memory allocation took %.6f seconds\n", time_taken);
    printf("%d reallocations performed\n", set->reallocations);
}

int main() {
    RecordSet *set = create_record_set(MIN_ALLOC_SIZE);

    process_input(set);
    process_file(set, "identifiers.txt");

    monitor_performance(set);

    destroy_record_set(set);

    return 0;
}
```

This code provides a basic implementation of the described functionality. It includes error handling, dynamic memory management, and performance monitoring. The `hash_function` is a simple example that can be replaced with more sophisticated hash functions as needed. The `process_input` function reads integers from standard input, while `process_file` reads identifiers from a file. The `monitor_performance` function logs the time taken for memory allocation and the number of reallocations performed.']

