#include <time.h>

#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 500
#define RECORD_SIZE sizeof(record)
#define MEMORY_THRESHOLD 1024 * 1024 // 1MB

typedef struct {
    long timestamp;
    int key;
} record;

long hash_function(int key, int unique_id) {
    return (key * 31 + unique_id) % MAX_OFFSET_SIZE;
}

int allocate_memory(long **offsets, int **keys, record **records, int offset_size, int key_size, int max_offset_size, int max_key_size) {
    if (offset_size > max_offset_size || key_size > max_key_size) {
        fprintf(stderr, "Error: Size exceeds maximum limits.\n");
        return -1;
    }

    *offsets = (long *)malloc(offset_size * sizeof(long));
    *keys = (int *)malloc(key_size * sizeof(int));
    *records = (record *)malloc(key_size * RECORD_SIZE);

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    for (int i = 0; i < key_size; i++) {
        (*records)[i].timestamp = time(NULL) + hash_function((*keys)[i], i);
    }

    return 0;
}

void resize_memory(long **offsets, int **keys, record **records, int *offset_size, int *key_size, int new_key_size) {
    if (new_key_size <= *key_size) {
        fprintf(stderr, "Error: New key size must be greater than current size.\n");
        return;
    }

    long *new_offsets = (long *)realloc(*offsets, new_key_size * sizeof(long));
    int *new_keys = (int *)realloc(*keys, new_key_size * sizeof(int));
    record *new_records = (record *)realloc(*records, new_key_size * RECORD_SIZE);

    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        fprintf(stderr, "Error: Memory reallocation failed.\n");
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return;
    }

    for (int i = *key_size; i < new_key_size; i++) {
        new_records[i].timestamp = time(NULL) + hash_function(new_keys[i], i);
    }

    *offsets = new_offsets;
    *keys = new_keys;
    *records = new_records;
    *key_size = new_key_size;
}

int main() {
    long *offsets;
    int *keys;
    record *records;
    int offset_size = 100;
    int key_size = 50;
    int max_offset_size = MAX_OFFSET_SIZE;
    int max_key_size = MAX_KEY_SIZE;

    if (allocate_memory(&offsets, &keys, &records, offset_size, key_size, max_offset_size, max_key_size) != 0) {
        return -1;
    }

    // Simulate dynamic resizing
    resize_memory(&offsets, &keys, &records, &offset_size, &key_size, key_size * 2);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
