import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import os

def calculate_md5(file_path, chunk_size=64*1024):
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b''):
            md5.update(chunk)
    return file_path, md5.hexdigest()

def process_files_concurrently(file_paths, max_workers=10):
    results = []
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(calculate_md5, file): file for file in file_paths}
        for future in as_completed(futures):
            try:
                result = future.result()
                results.append(result)
            except Exception as e:
                print(f"Error processing file: {futures[future]}")
                print(f"Exception: {e}")
    return results

# Example usage
file_paths = ['path/to/file1', 'path/to/file2']
hashed_files = process_files_concurrently(file_paths, max_workers=5)
for file, md5 in hashed_files:
    print(f"{file}: {md5}")
```

This code snippet defines a function `calculate_md5` that calculates the MD5 hash of a given file using a specified chunk size. It then defines another function `process_files_concurrently` that uses a thread pool to process multiple files concurrently, handling exceptions and logging errors for failed files. The example usage demonstrates how to use these functions with a list of file paths.']

