fn manage_directory_and_data(
    num_floats: usize,
    num_chars: usize,
    num_points: usize,
    max_memory_limit: usize,
) -> Result<(), Box<dyn std::error::Error>> {
    const MAX_NUM_ELEMENTS: usize = 10000;

    if num_floats > MAX_NUM_ELEMENTS || num_chars > MAX_NUM_ELEMENTS || num_points > MAX_NUM_ELEMENTS {
        eprintln!("Exceeding maximum number of elements");
        return Err("Memory allocation limit exceeded".into());
    }

    let mut float_array = vec![0.0; num_floats];
    let mut char_array = vec!['\0'; num_chars];
    let mut point_array: Vec<Point> = Vec::with_capacity(num_points);

    // Parse floating-point numbers from input
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let floats: Result<Vec<f64>, _> = input.split(',').map(|s| s.parse()).collect();
    if let Err(e) = floats {
        eprintln!("Error parsing floating-point numbers: {}", e);
        return Err("Invalid input".into());
    }
    for (i, &f) in floats.iter().enumerate() {
        float_array[i] = f as f32;
    }

    // Calculate average value
    let sum: f32 = float_array.iter().sum();
    let average = if num_floats > 0 { sum / num_floats as f32 } else { 0.0 };

    // Create directory and set environment variable
    let dir_name = "my_directory";
    let mut env_var_set = false;
    if let Ok(path) = env::var(dir_name) {
        env_var_set = true;
    } else {
        DirBuilder::new().create(dir_name)?;
        env::set_var(dir_name, dir_name);
    }

    // Sort points using a custom comparison function
    point_array.sort_by(|a, b| a.x.partial_cmp(&b.x).unwrap());

    // Log memory usage and errors
    log_memory_usage(num_floats, num_chars, num_points);

    Ok(())
}

fn parse_comma_separated_floats(input: &str) -> Result<Vec<f64>, Box<dyn std::error::Error>> {
    input.split(',').map(|s| s.parse()).collect()
}

fn log_memory_usage(floats: usize, chars: usize, points: usize) {
    let total_memory = floats * std::mem::size_of::<f32>() + chars * std::mem::size_of::<char>() + points * std::mem::size_of::<Point>();
    println!("Total memory used: {} bytes", total_memory);
}

