#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <pthread.h>

#define M 1000
#define U 100.0
#define μ 50.0
#define σ 10.0

typedef struct {
    float timestamp;
    double measurement;
} event;

event events[M];
float timestamps[M];
double measurements[M];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void generate_events() {
    for (int i = 0; i < M; i++) {
        pthread_mutex_lock(&lock);
        events[i].timestamp = clock();
        double z = ((double)rand() / RAND_MAX) * 2.0 - 1.0;
        double measurement = μ + σ * z;
        events[i].measurement = measurement;
        measurements[i] = measurement;
        timestamps[i] = events[i].timestamp;
        pthread_mutex_unlock(&lock);
    }
}

void adjust_measurements() {
    double sum = 0.0;
    for (int i = 0; i < M; i++) {
        sum += measurements[i];
    }
    double average = sum / M;

    if (average > U) {
        double factor = U / average;
        pthread_mutex_lock(&lock);
        for (int i = 0; i < M; i++) {
            measurements[i] *= factor;
            events[i].measurement = measurements[i];
        }
        pthread_mutex_unlock(&lock);
    }
}

void* pipeline_thread(void* arg) {
    while (1) {
        generate_events();
        adjust_measurements();
        // Simulate processing
        usleep(1000); // 1 ms
    }
    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, pipeline_thread, NULL);

    pthread_join(thread, NULL);
    return 0;
}
```

