#define MAX_SENSORS 100000

typedef struct sensor_data {
    float temperature;
    char unit_code;
    int timestamp;
    float humidity;
} sensor_data;

typedef struct sensor_node {
    int index;
    struct sensor_node* next;
} sensor_node;

sensor_data* allocate_sensor_data(int num_sensors) {
    sensor_data* data = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));
    if (!data) {
        perror("Failed to allocate memory for sensor data");
        return NULL;
    }
    for (int i = 0; i < num_sensors; ++i) {
        data[i].temperature = 0.0f;
        data[i].unit_code = 'C';
        data[i].timestamp = 0;
        data[i].humidity = 0.0f;
    }
    return data;
}

sensor_node* allocate_sensor_index_list(int num_sensors) {
    sensor_node* head = NULL;
    for (int i = 0; i < num_sensors; ++i) {
        sensor_node* new_node = (sensor_node*)malloc(sizeof(sensor_node));
        if (!new_node) {
            perror("Failed to allocate memory for sensor index node");
            free_sensor_index_list(head);
            return NULL;
        }
        new_node->index = i;
        new_node->next = head;
        head = new_node;
    }
    return head;
}

void free_sensor_data(sensor_data* data, int num_sensors) {
    if (data) {
        free(data);
    }
}

void free_sensor_index_list(sensor_node* head) {
    sensor_node* current = head;
    while (current) {
        sensor_node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int num_sensors = 100000;
    sensor_data* data = allocate_sensor_data(num_sensors);
    if (!data) {
        return EXIT_FAILURE;
    }

    sensor_node* index_list = allocate_sensor_index_list(num_sensors);
    if (!index_list) {
        free_sensor_data(data, num_sensors);
        return EXIT_FAILURE;
    }

    // Use the allocated data and index list for further processing

    free_sensor_data(data, num_sensors);
    free_sensor_index_list(index_list);

    return EXIT_SUCCESS;
}
