    if (initial_states == NULL || num_initial_states <= 0 || fsa_ptr == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    *offsets = malloc(num_initial_states * sizeof(long));
    *keys = malloc(num_initial_states * sizeof(int));
    *records = malloc(num_initial_states * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < num_initial_states; i++) {
        (*offsets)[i] = initial_states[i];
        (*keys)[i] = hash_function(initial_states[i]);
        (*records)[i].value = (*keys)[i];
    }

    *total_memory_used += num_initial_states * (sizeof(long) + sizeof(int) + sizeof(record));

    if (*total_memory_used > memory_threshold) {
        fprintf(stderr, "Memory usage exceeds threshold\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return;
    }

