#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CONCURRENT_CALLS 100

typedef struct {
    int value;
} record;

void initialize_data(long *offsets, int *keys, record **records, int N, int L) {
    // Initialize offsets and keys
    for (int i = 0; i < N; i++) {
        offsets[i] = i * sizeof(record);
        keys[i] = rand() % 1001;
    }

    // Initialize records with random values ensuring sum does not exceed L
    int total_sum = 0;
    for (int i = 0; i < N; i++) {
        records[i] = malloc(sizeof(record));
        records[i]->value = rand() % 1001;
        total_sum += records[i]->value;
    }

    // Adjust values if sum exceeds L
    while (total_sum > L) {
        int excess = total_sum - L;
        for (int i = 0; i < N && excess > 0; i++) {
            int adjustment = rand() % (excess + 1);
            records[i]->value -= adjustment;
            total_sum -= adjustment;
            excess -= adjustment;
        }
    }

    // Log the number of adjustments made
    printf("Number of adjustments: %d\n", N - (L / 1001));
}

void free_data(record **records, int N) {
    for (int i = 0; i < N; i++) {
        free(records[i]);
    }
}

int main() {
    srand(time(NULL));

    long offsets[MAX_CONCURRENT_CALLS];
    int keys[MAX_CONCURRENT_CALLS];
    record *records[MAX_CONCURRENT_CALLS];

    int N = 100;
    int L = 50000;

    initialize_data(offsets, keys, records, N, L);

    // Simulate concurrent calls
    for (int i = 1; i < MAX_CONCURRENT_CALLS; i++) {
        initialize_data(offsets + i * N, keys + i * N, records + i * N, N, L);
    }

    // Free allocated memory
    for (int i = 0; i < MAX_CONCURRENT_CALLS; i++) {
        free_data(records + i * N, N);
    }

    return 0;
}
