#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int packet_id;
    int payload_length;
} DataPacket;

typedef struct Node {
    int vertex_id;
    struct Node* next;
} Node;

typedef struct Graph {
    int num_vertices;
    Node** adjacency_list;
    pthread_mutex_t lock;
} Graph;

Graph* create_graph(int num_vertices) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->num_vertices = num_vertices;
    graph->adjacency_list = (Node**)calloc(num_vertices, sizeof(Node*));
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

void add_vertex(Graph* graph, int vertex_id) {
    pthread_mutex_lock(&graph->lock);
    if (graph->adjacency_list[vertex_id] == NULL) {
        graph->adjacency_list[vertex_id] = (Node*)malloc(sizeof(Node));
        graph->adjacency_list[vertex_id]->vertex_id = vertex_id;
        graph->adjacency_list[vertex_id]->next = NULL;
    }
    pthread_mutex_unlock(&graph->lock);
}

void add_edge(Graph* graph, int src, int dest) {
    pthread_mutex_lock(&graph->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->vertex_id = dest;
    new_node->next = graph->adjacency_list[src];
    graph->adjacency_list[src] = new_node;
    pthread_mutex_unlock(&graph->lock);
}

void update_packet(DataPacket** packets, int num_packets, int packet_id, DataPacket new_packet) {
    for (int i = 0; i < num_packets; i++) {
        if (packets[i]->packet_id == packet_id) {
            packets[i] = (DataPacket*)realloc(packets[i], sizeof(DataPacket));
            *packets[i] = new_packet;
            break;
        }
    }
}

DataPacket* get_packets_by_timestamp_range(DataPacket** packets, int num_packets, int start_time, int end_time) {
    DataPacket* result = NULL;
    int count = 0;

    for (int i = 0; i < num_packets; i++) {
        if (packets[i]->timestamp >= start_time && packets[i]->timestamp <= end_time) {
            result = (DataPacket*)realloc(result, (count + 1) * sizeof(DataPacket));
            result[count++] = *packets[i];
        }
    }

    return result;
}

void free_packets(DataPacket** packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        free(packets[i]);
    }
    free(packets);
}

void free_graph(Graph* graph) {
    for (int i = 0; i < graph->num_vertices; i++) {
        Node* current = graph->adjacency_list[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&graph->lock);
    free(graph->adjacency_list);
    free(graph);
}
