double* allocate_doubles(size_t size) {
    if (size > MAX_FLOATS) {
        log_error("Exceeded maximum number of doubles");
        return NULL;
    }
    return (double*)malloc(size * sizeof(double));
}

unsigned int* allocate_identifiers(size_t size) {
    if (size > MAX_IDENTIFIERS) {
        log_error("Exceeded maximum number of identifiers");
        return NULL;
    }
    return (unsigned int*)malloc(size * sizeof(unsigned int));
}

Transaction* allocate_transactions(size_t size) {
    return (Transaction*)malloc(size * sizeof(Transaction));
}

void free_memory(double *doubles, unsigned int *identifiers, Transaction *transactions, size_t transaction_count) {
    for (size_t i = 0; i < transaction_count; ++i) {
        free(transactions[i].identifier);
    }
    free(doubles);
    free(identifiers);
    free(transactions);
}

int main() {
    size_t num_floats = 500;
    size_t num_identifiers = 300;

    double *floats = allocate_doubles(num_floats);
    unsigned int *identifiers = allocate_identifiers(num_identifiers);
    Transaction *transactions = allocate_transactions(num_identifiers);

    if (!floats || !identifiers || !transactions) {
        log_error("Memory allocation failed");
        free_memory(floats, identifiers, transactions, 0);
        return EXIT_FAILURE;
    }

    // Initialize arrays and transactions
    for (size_t i = 0; i < num_identifiers; ++i) {
        floats[i] = (double)i * 1.1;
        identifiers[i] = i + 1;
        transactions[i].value = floats[i];
        transactions[i].identifier = &identifiers[i];
    }

    // Process transactions
    for (size_t i = 0; i < num_identifiers; ++i) {
        printf("Transaction %zu: Value = %.2f, Identifier = %u\n", i, transactions[i].value, *transactions[i].identifier);
    }

    free_memory(floats, identifiers, transactions, num_identifiers);

    return EXIT_SUCCESS;
}
