#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_INTERFACES 1024

typedef struct {
    char interface_name[64];
    char ip_address[16];
    char subnet_mask[16];
} NIMConfig;

typedef struct {
    NIMConfig *configs;
    size_t count;
    size_t capacity;
} NIMCollection;

bool is_valid_ip(const char *ip) {
    // Simple validation, not comprehensive
    return strchr(ip, '.') != NULL && strchr(ip, ':') == NULL;
}

NIMCollection* nim_collection_init() {
    NIMCollection *collection = (NIMCollection*)malloc(sizeof(NIMCollection));
    if (!collection) {
        perror("Failed to allocate memory for NIM collection");
        return NULL;
    }
    collection->configs = NULL;
    collection->count = 0;
    collection->capacity = 0;
    return collection;
}

bool nim_collection_add(NIMCollection *collection, const char *interface_name, const char *ip_address, const char *subnet_mask) {
    if (!is_valid_ip(ip_address)) {
        fprintf(stderr, "Invalid IP address: %s\n", ip_address);
        return false;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->configs[i].interface_name, interface_name) == 0) {
            fprintf(stderr, "Duplicate interface name: %s\n", interface_name);
            return false;
        }
    }

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity > 0 ? collection->capacity * 2 : MAX_INTERFACES;
        NIMConfig *new_configs = realloc(collection->configs, new_capacity * sizeof(NIMConfig));
        if (!new_configs) {
            perror("Failed to reallocate memory for NIM collection");
            return false;
        }
        collection->configs = new_configs;
        collection->capacity = new_capacity;
    }

    strcpy(collection->configs[collection->count].interface_name, interface_name);
    strcpy(collection->configs[collection->count].ip_address, ip_address);
    strcpy(collection->configs[collection->count].subnet_mask, subnet_mask);
    ++collection->count;

    return true;
}

void nim_collection_free(NIMCollection *collection) {
    if (collection->configs) {
        free(collection->configs);
    }
    free(collection);
}
