#include <iostream>
#include <vector>
#include <unordered_map>
#include <map>
#include <mutex>

class TransactionLog {
public:
    int transactionID;
    int userID;
    std::string timestamp;
    double amount;

    TransactionLog(int id, int uid, const std::string& ts, double amt)
        : transactionID(id), userID(uid), timestamp(ts), amount(amt) {}
};

class TransactionManager {
private:
    std::unordered_map<int, TransactionLog*> userMap; // Fast lookup by user ID
    std::map<std::string, std::vector<TransactionLog*>> timeRangeMap; // Ordered access by timestamp
    std::mutex mutex;

public:
    ~TransactionManager() {
        for (auto& pair : userMap) {
            delete pair.second;
        }
    }

    void addTransaction(const TransactionLog& transaction) {
        std::lock_guard<std::mutex> lock(mutex);
        userMap[transaction.userID] = new TransactionLog(transaction);
        timeRangeMap[transaction.timestamp].push_back(new TransactionLog(transaction));
    }

    void updateTransaction(int userID, const TransactionLog& updatedTransaction) {
        std::lock_guard<std::mutex> lock(mutex);
        if (userMap.find(userID) != userMap.end()) {
            delete userMap[userID];
            userMap[userID] = new TransactionLog(updatedTransaction);
            // Update timeRangeMap as well
        }
    }

    std::vector<TransactionLog*> getTransactionsByUserID(int userID) {
        std::lock_guard<std::mutex> lock(mutex);
        if (userMap.find(userID) != userMap.end()) {
            return {userMap[userID]};
        }
        return {};
    }

    std::vector<TransactionLog*> getTransactionsInTimeRange(const std::string& start, const std::string& end) {
        std::lock_guard<std::mutex> lock(mutex);
        auto range = timeRangeMap.equal_range(start);
        std::vector<TransactionLog*> transactions;
        for (auto it = range.first; it != range.second && it->first <= end; ++it) {
            transactions.insert(transactions.end(), it->second.begin(), it->second.end());
        }
        return transactions;
    }
};
