#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

NFAPI_CRC_ARRAY_T* create_crc_array(size_t initial_capacity) {
    NFAPI_CRC_ARRAY_T *array = (NFAPI_CRC_ARRAY_T*)malloc(sizeof(NFAPI_CRC_ARRAY_T));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY_T *array) {
    if (array) {
        pthread_mutex_destroy(&array->mutex);
        free(array->array);
        free(array);
    }
}

int add_or_update_crc_entry(NFAPI_CRC_ARRAY_T *array, uint32_t tag, uint16_t rnti) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RX_UE_INFORMATION_TAG == tag && array->array[i].RNTI == rnti) {
            array->array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
            pthread_mutex_unlock(&array->mutex);
            return 0; // Updated
        }
    }

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->size].RX_UE_INFORMATION_TAG = tag;
    array->array[array->size].RNTI = rnti;
    array->array[array->size].CRC_INDICATION_REL8_TAG = rand() % 256;
    ++array->size;

    pthread_mutex_unlock(&array->mutex);
    return 1; // Added
}

void update_crc_flags(NFAPI_CRC_ARRAY_T *array, uint32_t tag, uint16_t rnti, uint8_t new_flag) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RX_UE_INFORMATION_TAG == tag && array->array[i].RNTI == rnti) {
            array->array[i].CRC_INDICATION_REL8_TAG = new_flag;
            break;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

void iterate_and_update_crc_flags(NFAPI_CRC_ARRAY_T *array, void (*update_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        update_func(&array->array[i]);
    }

    pthread_mutex_unlock(&array->mutex);
}
