typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketRepository;

void init_packet_repository(PacketRepository *repo, size_t initial_capacity) {
    repo->packets = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    repo->count = 0;
    repo->capacity = initial_capacity;
}

void add_packet(PacketRepository *repo, DataPacket packet) {
    if (repo->count >= repo->capacity) {
        repo->capacity *= 2;
        repo->packets = (DataPacket *)realloc(repo->packets, repo->capacity * sizeof(DataPacket));
    }
    repo->packets[repo->count++] = packet;
}

void update_packet(PacketRepository *repo, int packet_id, DataPacket new_data) {
    for (size_t i = 0; i < repo->count; ++i) {
        if (repo->packets[i].packet_id == packet_id) {
            repo->packets[i] = new_data;
            return;
        }
    }
}

DataPacket *get_packet(PacketRepository *repo, int packet_id) {
    for (size_t i = 0; i < repo->count; ++i) {
        if (repo->packets[i].packet_id == packet_id) {
            return &repo->packets[i];
        }
    }
    return NULL;
}

void free_packet_repository(PacketRepository *repo) {
    free(repo->packets);
    repo->packets = NULL;
    repo->count = 0;
    repo->capacity = 0;
}
