#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
    void* metadata;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager* pm) {
    pm->packets = NULL;
    pm->count = 0;
    pthread_mutex_init(&pm->lock, NULL);
}

void add_packet(PacketManager* pm, DataPacket* packet) {
    pthread_mutex_lock(&pm->lock);
    // Add packet to the array
    pm->packets = realloc(pm->packets, (pm->count + 1) * sizeof(DataPacket*));
    pm->packets[pm->count++] = packet;
    pthread_mutex_unlock(&pm->lock);
}

void update_packet(PacketManager* pm, int packet_id, DataPacket* new_packet) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i]->packet_id == packet_id) {
            // Update the packet
            free(pm->packets[i]);
            pm->packets[i] = new_packet;
            break;
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

DataPacket* get_packets_by_timestamp_range(PacketManager* pm, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&pm->lock);
    // Create a new array to store packets within the range
    DataPacket** result = malloc(pm->count * sizeof(DataPacket*));
    size_t result_count = 0;
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i]->timestamp >= start_time && pm->packets[i]->timestamp <= end_time) {
            result[result_count++] = pm->packets[i];
        }
    }
    pthread_mutex_unlock(&pm->lock);
    // Return the new array
    return result;
}

void free_packet_manager(PacketManager* pm) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        free(pm->packets[i]);
    }
    free(pm->packets);
    pthread_mutex_unlock(&pm->lock);
    pthread_mutex_destroy(&pm->lock);
}
