#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>

EVP_CIPHER_CTX* allocateLogEntry(const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Allocate memory for the log entry
    char* buffer = (char*)malloc(1024);
    if (!buffer) {
        return NULL; // Handle memory allocation failure
    }

    // Format the message using snprintf and va_list
    int len = vsnprintf(buffer, 1024, format, args);
    if (len < 0 || len >= 1024) {
        free(buffer);
        return NULL; // Handle formatting error or buffer overflow
    }

    // Initialize the cipher context for AES encryption
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        free(buffer);
        return NULL; // Handle cipher context creation failure
    }

    // Set up the cipher mode (e.g., AES-256-CBC)
    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        free(buffer);
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle encryption initialization failure
    }

    // Generate a random key and IV for AES encryption
    unsigned char key[32], iv[16];
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        free(buffer);
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle random number generation failure
    }

    // Initialize the cipher context with the key and IV
    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv)) {
        free(buffer);
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle encryption initialization failure
    }

    // Encrypt the log message
    int ciphertext_len;
    if (!EVP_EncryptUpdate(ctx, (unsigned char*)buffer + len, &ciphertext_len, (unsigned char*)buffer, len)) {
        free(buffer);
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle encryption update failure
    }
    len += ciphertext_len;

    // Finalize the encryption
    if (!EVP_EncryptFinal_ex(ctx, (unsigned char*)buffer + len, &ciphertext_len)) {
        free(buffer);
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle encryption finalization failure
    }
    len += ciphertext_len;

    // Free the original buffer and return the cipher context
    free(buffer);
    return ctx;
}
