#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct Record {
    long offset;
    int key;
    char* identifier;
} Record;

typedef struct DynamicSet {
    Record** records;
    size_t capacity;
    size_t size;
    void (*hashFunction)(int, size_t*);
} DynamicSet;

void hashFunction(int key, size_t* hash) {
    *hash = (size_t)key % 100; // Simple hash function for demonstration
}

DynamicSet* createDynamicSet(void (*hashFunc)(int, size_t*)) {
    DynamicSet* set = (DynamicSet*)malloc(sizeof(DynamicSet));
    if (!set) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    set->records = (Record**)calloc(INITIAL_CAPACITY, sizeof(Record*));
    if (!set->records) {
        free(set);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    set->capacity = INITIAL_CAPACITY;
    set->size = 0;
    set->hashFunction = hashFunc;
    return set;
}

void insert(DynamicSet* set, long offset, int key, const char* identifier) {
    if (set->size >= set->capacity) {
        size_t newCapacity = set->capacity * GROWTH_FACTOR;
        Record** newRecords = (Record**)realloc(set->records, newCapacity * sizeof(Record*));
        if (!newRecords) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        set->records = newRecords;
        set->capacity = newCapacity;
    }

    size_t hash;
    set->hashFunction(key, &hash);
    while (set->records[hash] != NULL) {
        hash = (hash + 1) % set->capacity; // Linear probing
    }
    set->records[hash] = (Record*)malloc(sizeof(Record));
    if (!set->records[hash]) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    set->records[hash]->offset = offset;
    set->records[hash]->key = key;
    set->records[hash]->identifier = strdup(identifier);
    if (!set->records[hash]->identifier) {
        free(set->records[hash]);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    set->size++;
}

void destroyDynamicSet(DynamicSet* set) {
    for (size_t i = 0; i < set->capacity; i++) {
        if (set->records[i]) {
            free(set->records[i]->identifier);
            free(set->records[i]);
        }
    }
    free(set->records);
    free(set);
}

int main() {
    DynamicSet* set = createDynamicSet(hashFunction);

    insert(set, 100L, 42, "example");
    insert(set, 200L, 99, "test");

    destroyDynamicSet(set);

    return 0;
}
