#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct MemoryManager {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        free(manager->records);
        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_record(MemoryManager* manager, int key, long offset) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record* new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Out of memory
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].key == key || manager->records[i].offset == offset) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate key or offset
        }
    }

    manager->records[manager->size].key = key;
    manager->records[manager->size].offset = offset;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int get_offset(MemoryManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].key == key) {
            long offset = manager->records[i].offset;
            pthread_mutex_unlock(&manager->lock);
            return offset;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Key not found
}
