#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int PCI;
    int NR_SFN;
    // Add other fields for performance metrics
} NR_PHY_STATS_T;

typedef struct node {
    NR_PHY_STATS_T data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DataStore;

DataStore* create_data_store() {
    DataStore* store = (DataStore*)malloc(sizeof(DataStore));
    if (store == NULL) {
        return NULL; // Handle memory allocation failure
    }
    store->head = NULL;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void insert_data(DataStore* store, NR_PHY_STATS_T data) {
    pthread_mutex_lock(&store->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&store->lock);
        return; // Handle memory allocation failure
    }
    new_node->data = data;
    new_node->next = store->head;
    store->head = new_node;
    pthread_mutex_unlock(&store->lock);
}

NR_PHY_STATS_T* retrieve_data(DataStore* store, int PCI, int NR_SFN) {
    pthread_mutex_lock(&store->lock);
    Node* current = store->head;
    while (current != NULL) {
        if (current->data.PCI == PCI && current->data.NR_SFN == NR_SFN) {
            pthread_mutex_unlock(&store->lock);
            return &current->data; // Return a pointer to the data
        }
        current = current->next;
    }
    pthread_mutex_unlock(&store->lock);
    return NULL; // Data not found
}

void aggregate_and_report(DataStore* store) {
    pthread_mutex_lock(&store->lock);
    Node* current = store->head;
    while (current != NULL) {
        // Aggregate performance metrics here
        printf("PCI: %d, NR_SFN: %d\n", current->data.PCI, current->data.NR_SFN);
        current = current->next;
    }
    pthread_mutex_unlock(&store->lock);
}

void destroy_data_store(DataStore* store) {
    Node* current = store->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&store->lock);
    free(store);
}
