#include <time.h>

typedef struct {
    int value;
    long offsetPointer;
    char status;
} Record;

int createRecords(int maxRecords, int **keys, long **offsets, Record **records) {
    if (maxRecords <= 0) {
        fprintf(stderr, "Error: Invalid number of records.\n");
        return -1;
    }

    *keys = (int *)malloc(maxRecords * sizeof(int));
    *offsets = (long *)malloc(maxRecords * sizeof(long));
    *records = (Record *)malloc(maxRecords * sizeof(Record));

    if (*keys == NULL || *offsets == NULL || *records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*keys);
        free(*offsets);
        free(*records);
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < maxRecords; i++) {
        (*keys)[i] = i;
        (*offsets)[i] = i * sizeof(long); // Simplified offset calculation
        (*records)[i].value = rand() % 201 - 100; // Random value between -100 and 100
        if ((*records)[i].value > 0) {
            (*records)[i].status = 'A';
        } else if ((*records)[i].value < 0) {
            (*records)[i].status = 'N';
        } else {
            (*records)[i].status = 'Z';
        }
        (*records)[i].offsetPointer = (long)&(*offsets)[i];
    }

    return 0;
}

void freeRecords(int *keys, long *offsets, Record *records) {
    if (keys != NULL) free(keys);
    if (offsets != NULL) free(offsets);
    if (records != NULL) free(records);
}
