#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <openssl/md5.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct AudioStream {
    int id;
    time_t timestamp;
    char format[20];
    int sample_rate;
    unsigned char *audio_payload;
    size_t payload_size;
} AudioStream;

typedef struct AudioList {
    AudioStream **streams;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} AudioList;

void initAudioList(AudioList *list) {
    list->streams = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void freeAudioList(AudioList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->streams[i]->audio_payload);
        free(list->streams[i]);
    }
    free(list->streams);
    pthread_mutex_destroy(&list->lock);
}

void addAudioStream(AudioList *list, AudioStream *stream) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        AudioStream **new_streams = realloc(list->streams, new_capacity * sizeof(AudioStream *));
        if (!new_streams) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->streams = new_streams;
        list->capacity = new_capacity;
    }
    list->streams[list->count++] = stream;
    pthread_mutex_unlock(&list->lock);
}

AudioStream* getAudioStream(AudioList *list, int id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->streams[i]->id == id) {
            AudioStream *stream = list->streams[i];
            pthread_mutex_unlock(&list->lock);
            return stream;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void removeAudioStream(AudioList *list, int id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->streams[i]->id == id) {
            free(list->streams[i]->audio_payload);
            free(list->streams[i]);
            memmove(list->streams + i, list->streams + i + 1, (list->count - i - 1) * sizeof(AudioStream *));
            --list->count;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void encryptAudioPayload(AudioStream *stream, unsigned char *key, int key_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, stream->audio_payload)) {
        int len;
        if (EVP_EncryptUpdate(ctx, stream->audio_payload + 32, &len, stream->audio_payload + 32, stream->payload_size - 32) > 0) {
            int final_len;
            EVP_EncryptFinal_ex(ctx, stream->audio_payload + len, &final_len);
            stream->payload_size = len + final_len;
        }
    }
    EVP_CIPHER_CTX_free(ctx);
}

void decryptAudioPayload(AudioStream *stream, unsigned char *key, int key_len) {
