#define MAX_RECORDS 1000
#define IDENTIFIER_SIZE 256

typedef struct {
    int value;
    char *identifier;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t count;
    size_t capacity;
    size_t memory_limit;
    clock_t allocation_time;
    int reallocations;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity, size_t memory_limit) {
    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->memory_limit = memory_limit;
    manager->allocation_time = clock();
    manager->reallocations = 0;

    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_memory_manager(MemoryManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]->identifier);
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}

int add_record(MemoryManager *manager, long offset, int key, const char *identifier) {
    if (manager->count >= manager->capacity || strlen(identifier) > IDENTIFIER_SIZE - 1) return -1;

    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) return -1;

    record->value = key;
    record->identifier = strdup(identifier);
    if (!record->identifier) {
        free(record);
        return -1;
    }

    manager->offsets[manager->count] = offset;
    manager->keys[manager->count] = key;
    manager->records[manager->count++] = record;

    clock_t current_time = clock();
    double time_taken = (double)(current_time - manager->allocation_time) / CLOCKS_PER_SEC;
    printf("Memory allocation took %f seconds\n", time_taken);

    if (time_taken > 1.0) {
        manager->reallocations++;
        manager->allocation_time = current_time;
    }

    return 0;
}

void resize_memory_manager(MemoryManager *manager, size_t new_capacity) {
    long *new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));
    Record **new_records = (Record**)realloc(manager->records, new_capacity * sizeof(Record*));

    if (!new_offsets || !new_keys || !new_records) {
        printf("Memory reallocation failed\n");
        return;
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->records = new_records;
    manager->capacity = new_capacity;
}

void read_and_find_largest() {
    int *numbers = NULL;
    size_t count = 0, capacity = 10;

    numbers = (int*)malloc(capacity * sizeof(int));
    if (!numbers) return;

    while (scanf("%d", &numbers[count]) == 1) {
        if (count >= capacity - 1) {
            capacity *= 2;
            int *new_numbers = (int*)realloc(numbers, capacity * sizeof(int));
            if (!new_numbers) {
                printf("Memory reallocation failed\n");
                free(numbers);
                return;
            }
            numbers = new_numbers;
        }
        count++;
    }

    int largest = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("Largest number: %d\n", largest);
    free(numbers);
}

int main() {
    MemoryManager *manager = create_memory_manager(10, 1024 * 1024); // Initial capacity of 10 records and memory limit of 1MB
    if (!manager) return -1;

    add_record(manager, 100, 5, "record1");
    add_record(manager, 200, 3, "record2");

    resize_memory_manager(manager, 20); // Resize to accommodate more records

    destroy_memory_manager(manager);

    read_and_find_largest();

    return 0;
}
