#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEYS 1000
#define MIN_ALLOC_SIZE 16

typedef struct {
    char flag;
    int value;
    char* string;
} Record;

typedef struct {
    size_t offset_size;
    size_t key_size;
    Record** records;
    pthread_mutex_t lock;
} DynamicCollection;

DynamicCollection* create_collection() {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->offset_size = 0;
    collection->key_size = 0;
    collection->records = (Record**)calloc(MIN_ALLOC_SIZE, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    for (size_t i = 0; i < collection->key_size; ++i) {
        Record* record = collection->records[i];
        if (record) {
            free(record->string);
            free(record);
        }
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(DynamicCollection* collection, char flag, int value, const char* string) {
    pthread_mutex_lock(&collection->lock);

    if (collection->key_size >= MAX_KEYS) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Exceeds maximum keys
    }

    size_t new_key_size = collection->key_size + 1;
    if (new_key_size > collection->offset_size) {
        Record** new_records = (Record**)realloc(collection->records, new_key_size * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Memory allocation failed
        }
        collection->records = new_records;
        collection->offset_size = new_key_size;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -3; // Memory allocation failed
    }

    record->flag = flag;
    record->value = value;
    record->string = strdup(string);
    if (!record->string) {
        free(record);
        pthread_mutex_unlock(&collection->lock);
        return -4; // Memory allocation failed
    }

    collection->records[collection->key_size++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Additional functions for resizing, concurrent access handling, memory monitoring, and logging can be implemented here.
```

