#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    void* metadata; // Pointer to external data source metadata
    struct Record* next;
} Record;

typedef struct List {
    Record* head;
    size_t count;
} List;

List* create_list(size_t initial_size) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    // Pre-allocate memory for initial records
    for (size_t i = 0; i < initial_size; ++i) {
        Record* new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            free_list(list);
            return NULL;
        }
        new_record->value = rand() % 100; // Random value between 0 and 99
        new_record->metadata = NULL; // Initialize metadata pointer to NULL
        new_record->next = list->head;
        list->head = new_record;
    }
    return list;
}

void free_list(List* list) {
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

void insert_record(List* list, int value, void* metadata) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return;
    new_record->value = value;
    new_record->metadata = metadata;
    new_record->next = list->head;
    list->head = new_record;
    ++list->count;
}

void delete_record(List* list, int value) {
    Record* current = list->head;
    Record* prev = NULL;
    while (current) {
        if (current->value == value) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            --list->count;
            return;
        }
        prev = current;
        current = current->next;
    }
}

void traverse_list(List* list) {
    Record* current = list->head;
    while (current) {
        printf("Value: %d, Metadata: %p\n", current->value, current->metadata);
        current = current->next;
    }
}

int main() {
    srand(time(NULL));
    List* my_list = create_list(10);
    if (!my_list) {
        fprintf(stderr, "Failed to create list.\n");
        return 1;
    }

    insert_record(my_list, 42, NULL);
    delete_record(my_list, 50); // Assuming 50 was inserted earlier
    traverse_list(my_list);

    free_list(my_list);
    return 0;
}
