#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    long offset;
    int* value_ptr;
} Offset;

typedef struct {
    int key;
    Offset* offset_ptr;
} KeyValue;

typedef struct {
    int value;
    KeyValue* kv_pair_ptr;
} Record;

void initialize_memory(int num_offsets, int num_records, int range_start, int range_end, int log_level) {
    // Step 1: Allocate and initialize offsets
    Offset* offsets = (Offset*)malloc(num_offsets * sizeof(Offset));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }
    long predefined_values[] = {0, 1024, 2048, 3072}; // Example values
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i].offset = predefined_values[i % sizeof(predefined_values) / sizeof(long)];
        offsets[i].value_ptr = NULL;
    }

    // Step 2: Allocate and initialize key-value pairs
    KeyValue* kv_pairs = (KeyValue*)malloc(num_records * sizeof(KeyValue));
    if (!kv_pairs) {
        fprintf(stderr, "Memory allocation failed for key-value pairs\n");
        free(offsets);
        return;
    }
    int keys[num_records];
