    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_nfaapi_crc_array(size_t initial_capacity) {
    NFAPI_CRC_ARRAY *array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_nfaapi_crc_array(NFAPI_CRC_ARRAY *array) {
    free(array->array);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int update_crc_flag(NFAPI_CRC_ARRAY *array, int index, int new_crcflag) {
    pthread_mutex_lock(&array->lock);
    if (index >= array->size) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Index out of bounds
    }
    array->array[index].CRC_INDICATION_REL8_TAG = new_crcflag;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void log_crc_update(NFAPI_CRC_ARRAY *array, int index, int new_crcflag) {
    static time_t last_log_time = 0;
    static int update_count = 0;

    if (time(NULL) - last_log_time >= 1) {
        printf("CRCFLAG updates per second: %d\n", update_count);
        last_log_time = time(NULL);
        update_count = 0;
    }

    update_count++;
}

int get_last_n_crc_updates(NFAPI_CRC_ARRAY *array, int n, NFAPI_CRC_INDICATION_PDU_T **updates) {
    pthread_mutex_lock(&array->lock);
    if (n > array->size) {
        n = array->size;
    }
    for (int i = 0; i < n; i++) {
        updates[i] = &array->array[array->size - n + i];
    }
    pthread_mutex_unlock(&array->lock);
    return n;
}

void compact_array(NFAPI_CRC_ARRAY *array) {
    pthread_mutex_lock(&array->lock);
    size_t new_size = 0;
    for (size_t i = 0; i < array->size; i++) {
        if (array->array[i].CRC_INDICATION_REL8_TAG != -1) { // Assuming -1 is an unused flag
            array->array[new_size++] = array->array[i];
        }
    }
    array->size = new_size;
    pthread_mutex_unlock(&array->lock);
}
