#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define HASH_SIZE 1024

typedef struct {
    double timestamp;
    int key;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    pthread_mutex_t lock;
    int count;
} DataStore;

void init_data_store(DataStore *store) {
    store->count = 0;
    pthread_mutex_init(&store->lock, NULL);
}

int insert_record(DataStore *store, double timestamp, int key) {
    pthread_mutex_lock(&store->lock);
    if (store->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&store->lock);
        return -1; // Overflow
    }
    store->records[store->count].timestamp = timestamp;
    store->records[store->count].key = key;
    store->count++;
    pthread_mutex_unlock(&store->lock);
    return 0;
}

int lookup_record(DataStore *store, int key) {
    pthread_mutex_lock(&store->lock);
    for (int i = 0; i < store->count; i++) {
        if (store->records[i].key == key) {
            pthread_mutex_unlock(&store->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&store->lock);
    return -1; // Not found
}

int remove_record(DataStore *store, int key) {
    pthread_mutex_lock(&store->lock);
    for (int i = 0; i < store->count; i++) {
        if (store->records[i].key == key) {
            memmove(&store->records[i], &store->records[i + 1], sizeof(Record) * (store->count - i - 1));
            store->count--;
            pthread_mutex_unlock(&store->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&store->lock);
    return -1; // Not found
}

void compact_data_store(DataStore *store) {
    pthread_mutex_lock(&store->lock);
    int new_count = 0;
    for (int i = 0; i < store->count; i++) {
        if (store->records[i].timestamp > 0) { // Assuming timestamp 0 is invalid
            store->records[new_count++] = store->records[i];
        }
    }
    memmove(store->records, &store->records[new_count], sizeof(Record) * (store->count - new_count));
    store->count -= (store->count - new_count);
    pthread_mutex_unlock(&store->lock);
}

void destroy_data_store(DataStore *store) {
    pthread_mutex_destroy(&store->lock);
}
