#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager* pm, size_t initial_capacity) {
    pm->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    if (!pm->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pm->count = 0;
    pm->capacity = initial_capacity;
    pthread_mutex_init(&pm->lock, NULL);
}

void add_packet(PacketManager* pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count == pm->capacity) {
        size_t new_capacity = pm->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }
    pm->packets[pm->count++] = packet;
    pthread_mutex_unlock(&pm->lock);
}

void update_packet(PacketManager* pm, int packet_id, DataPacket new_data) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            pm->packets[i] = new_data;
            break;
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

DataPacket* get_packet_by_id(PacketManager* pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            DataPacket* result = &pm->packets[i];
            pthread_mutex_unlock(&pm->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return NULL;
}

void free_packet_manager(PacketManager* pm) {
    pthread_mutex_lock(&pm->lock);
    free(pm->packets);
    pthread_mutex_destroy(&pm->lock);
}
