#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

long* offset = NULL;
int* keys = NULL;
record** records = NULL;
size_t size = 0;
size_t capacity = 0;
size_t memory_threshold = 1024 * 1024; // 1MB
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void hash_function(int key, int* hash_value) {
    *hash_value = (key * 31 + 7) % capacity;
}

int add_record(int key) {
    pthread_mutex_lock(&mutex);
    if (size >= capacity) {
        size_t new_capacity = capacity == 0 ? 8 : capacity * 2;
        if (new_capacity * sizeof(record*) > memory_threshold) {
            pthread_mutex_unlock(&mutex);
            return -1; // Memory threshold exceeded
        }
        records = realloc(records, new_capacity * sizeof(record*));
        capacity = new_capacity;
    }

    int hash_value;
    hash_function(key, &hash_value);

    while (records[hash_value] != NULL) {
        if (records[hash_value]->value == key) {
            pthread_mutex_unlock(&mutex);
            return 0; // Record already exists
        }
        hash_value = (hash_value + 1) % capacity;
    }

    records[hash_value] = malloc(sizeof(record));
    records[hash_value]->value = key;

    if (offset == NULL) {
        offset = malloc(capacity * sizeof(long));
        keys = malloc(capacity * sizeof(int));
    } else {
        offset = realloc(offset, capacity * sizeof(long));
        keys = realloc(keys, capacity * sizeof(int));
    }

    offset[hash_value] = size;
    keys[hash_value] = key;

    size++;
    pthread_mutex_unlock(&mutex);
    return 1; // Record added successfully
}

void free_memory() {
    for (size_t i = 0; i < size; i++) {
        free(records[i]);
    }
    free(offset);
    free(keys);
    free(records);
}
