#define MAX_RECORDS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    int count;
    int maxRecords;
    pthread_mutex_t lock;
} NFAPI_CRC_COLLECTION_T;

int init_collection(NFAPI_CRC_COLLECTION_T *collection, int maxRecords) {
    if (maxRecords <= 0) return -1; // Handle invalid input sizes
    collection->records = malloc(maxRecords * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->records) return -2; // Handle memory allocation failures
    collection->count = 0;
    collection->maxRecords = maxRecords;
    pthread_mutex_init(&collection->lock, NULL);
    return 0;
}

int add_record(NFAPI_CRC_COLLECTION_T *collection, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->maxRecords) {
        pthread_mutex_unlock(&collection->lock);
        return -3; // Handle reaching max records
    }
    NFAPI_CRC_INDICATION_PDU_T *record = &collection->records[collection->count];
    record->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    record->RNTI = RNTI;
    record->CRC_INDICATION_REL8_TAG = 0; // Placeholder for actual value
    record->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    collection->count++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int serialize_collection(NFAPI_CRC_COLLECTION_T *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -4; // Handle file open failures
    fwrite(collection->records, sizeof(NFAPI_CRC_INDICATION_PDU_T), collection->count, file);
    fclose(file);
    return 0;
}

void free_collection(NFAPI_CRC_COLLECTION_T *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
}
