#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NetworkSession {
    int sessionId;
    time_t connectionTime;
    int refCount;
    struct NetworkSession *next;
} NetworkSession;

typedef struct {
    NetworkSession *head;
    pthread_mutex_t lock;
} SessionManager;

void initSessionManager(SessionManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

NetworkSession* createSession(int sessionId) {
    NetworkSession *session = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (session == NULL) {
        perror("Failed to allocate memory for session");
        return NULL;
    }
    session->sessionId = sessionId;
    session->connectionTime = time(NULL);
    session->refCount = 1;
    session->next = NULL;
    return session;
}

void addSession(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->head == NULL) {
        manager->head = session;
    } else {
        NetworkSession *current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = session;
    }
    pthread_mutex_unlock(&manager->lock);
}

void updateRefCount(SessionManager *manager, int sessionId, int increment) {
    pthread_mutex_lock(&manager->lock);
    NetworkSession *current = manager->head;
    while (current != NULL) {
        if (current->sessionId == sessionId) {
            current->refCount += increment;
            if (current->refCount < 0) {
                printf("Error: Negative reference count for session %d\n", sessionId);
                current->refCount = 0; // Prevent negative ref counts
            }
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void closeSession(SessionManager *manager, int sessionId) {
    pthread_mutex_lock(&manager->lock);
    NetworkSession *current = manager->head;
    NetworkSession *prev = NULL;
    while (current != NULL) {
        if (current->sessionId == sessionId) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void logSessionActivity(NetworkSession *session, const char *action) {
    printf("Session %d: %s at %ld\n", session->sessionId, action, time(NULL));
}
