    double x;
    double y;
} Point;

typedef struct {
    char* name;
    double value;
    Point* point;
} Plot;

Plot** plotCollection = NULL;
int collectionSize = 0;
int maxCollectionSize = 10000;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializePlotCollection() {
    pthread_mutex_lock(&mutex);
    if (plotCollection == NULL) {
        plotCollection = (Plot**)malloc(maxCollectionSize * sizeof(Plot*));
        memset(plotCollection, 0, maxCollectionSize * sizeof(Plot*));
    }
    collectionSize = 0;
    pthread_mutex_unlock(&mutex);
}

void addPlot(const char* name, double value, Point* point) {
    pthread_mutex_lock(&mutex);
    if (collectionSize >= maxCollectionSize) {
        printf("Plot collection is full.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    plotCollection[collectionSize] = (Plot*)malloc(sizeof(Plot));
    plotCollection[collectionSize]->name = strdup(name);
    plotCollection[collectionSize]->value = value;
    plotCollection[collectionSize]->point = point;
    collectionSize++;
    pthread_mutex_unlock(&mutex);
}

void freePlotCollection() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < collectionSize; i++) {
        if (plotCollection[i] != NULL) {
            free(plotCollection[i]->name);
            free(plotCollection[i]->point);
            free(plotCollection[i]);
        }
    }
    free(plotCollection);
    plotCollection = NULL;
    collectionSize = 0;
    pthread_mutex_unlock(&mutex);
}

int main() {
    initializePlotCollection();

    Point point1 = {1.0, 2.0};
    addPlot("Plot1", 3.14, &point1);

    freePlotCollection();
    return 0;
}
