#include <arpa/inet.h>
#include <pthread.h>

#define MAX_FILES 10000
#define MAX_LINE_LENGTH 4096
#define MAX_THREADS 10

typedef struct {
    char *filename;
    u_char ip[4];
} FileData;

void* processFile(void* arg) {
    FileData *data = (FileData*)arg;
    FILE *file = fopen(data->filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Process each line here
        printf("%s", line);
    }

    fclose(file);
    free(data->filename);
    free(data);
    return NULL;
}

u_char* resolveDNS(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char ip[4];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &(ipv4->sin_addr), 4);
        freeaddrinfo(res); // Free the linked list
        return ip;
    }

    fprintf(stderr, "Failed to resolve hostname\n");
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    FileData *fileData[MAX_FILES];

    // Simulate loading file data
    for (int i = 0; i < MAX_FILES; i++) {
        fileData[i] = (FileData*)malloc(sizeof(FileData));
        fileData[i]->filename = strdup("example.txt");
        u_char *ip = resolveDNS("example.com");
        if (ip) {
            memcpy(fileData[i]->ip, ip, 4);
        }
    }

    // Process files concurrently
    for (int i = 0; i < MAX_FILES; i++) {
        pthread_create(&threads[i], NULL, processFile, fileData[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_FILES; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    for (int i = 0; i < MAX_FILES; i++) {
        free(fileData[i]->filename);
        free(fileData[i]);
    }

    return 0;
}
