#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct ResourceRequest {
    int userID;
    time_t requestTimestamp;
    char resourceType[256];
} ResourceRequest;

typedef struct HashNode {
    ResourceRequest data;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned int hashFunction(const char* key, size_t capacity) {
    unsigned int hash = 0;
    while (*key) {
        hash = (hash * 31) + *key++;
    }
    return hash % capacity;
}

HashTable* createHashTable() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(INITIAL_CAPACITY, sizeof(HashNode*));
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void resizeHashTable(HashTable* table) {
    size_t newCapacity = table->capacity * 2;
    HashNode** newBuckets = (HashNode**)calloc(newCapacity, sizeof(HashNode*));

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node != NULL) {
            HashNode* next = node->next;
            size_t newIndex = hashFunction(node->data.resourceType, newCapacity);
            node->next = newBuckets[newIndex];
            newBuckets[newIndex] = node;
            node = next;
        }
    }

    free(table->buckets);
    table->buckets = newBuckets;
    table->capacity = newCapacity;
}

void addOrUpdateRequest(HashTable* table, ResourceRequest request) {
    pthread_mutex_lock(&table->lock);
    size_t index = hashFunction(request.resourceType, table->capacity);
    HashNode* node = table->buckets[index];

    while (node != NULL) {
        if (strcmp(node->data.resourceType, request.resourceType) == 0) {
            node->data = request;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        node = node->next;
    }

    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->data = request;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    table->size++;
    if ((double)table->size / table->capacity > LOAD_FACTOR_THRESHOLD) {
        resizeHashTable(table);
    }

    pthread_mutex_unlock(&table->lock);
}

ResourceRequest* getRequestByTimeWindow(HashTable* table, time_t start, time_t end) {
    ResourceRequest* results = NULL;
    size_t resultCount = 0;

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node != NULL) {
            if (node->data.requestTimestamp >= start && node->data.requestTimestamp <= end) {
                results = realloc(results, (resultCount + 1) * sizeof(ResourceRequest));
                memcpy(&results[resultCount], &node->data, sizeof(ResourceRequest));
                resultCount++;
            }
            node = node->next;
        }
    }

    return results;
}

void freeHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node != NULL) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
