#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
    int priority_score;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
} PacketQueue;

void init_queue(PacketQueue* queue) {
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;
}

void enqueue(PacketQueue* queue, DataPacket data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;

    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;
    queue->size++;
}

DataPacket dequeue(PacketQueue* queue) {
    if (!queue->head) {
        fprintf(stderr, "Dequeue from empty queue\n");
        exit(EXIT_FAILURE);
    }

    Node* temp = queue->head;
    DataPacket data = temp->data;

    queue->head = temp->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    free(temp);
    queue->size--;

    return data;
}

void update_priority(PacketQueue* queue, int packet_id, int new_priority) {
    Node* current = queue->head;
    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            current->data.priority_score = new_priority;
            break;
        }
        current = current->next;
    }
}

void print_queue(PacketQueue* queue) {
    Node* current = queue->head;
    while (current != NULL) {
        printf("Timestamp: %ld, Packet ID: %d, Payload Length: %zu, Priority Score: %d\n",
               current->data.timestamp, current->data.packet_id, current->data.payload_length,
               current->data.priority_score);
        current = current->next;
    }
}

int main() {
    PacketQueue queue;
    init_queue(&queue);

    DataPacket packet1 = {time(NULL), 1, 1024, 5};
    enqueue(&queue, packet1);

    DataPacket packet2 = {time(NULL) + 1, 2, 2048, 3};
    enqueue(&queue, packet2);

    print_queue(&queue);

    update_priority(&queue, 1, 7);
    printf("Updated Priority:\n");
    print_queue(&queue);

    DataPacket dequeued_packet = dequeue(&queue);
    printf("Dequeued Packet: Timestamp: %ld, Packet ID: %d\n", dequeued_packet.timestamp, dequeued_packet.packet_id);

    return 0;
}
