#define M 100
#define L 50000
#define S 10000

typedef struct node {
    int value;
    char description[M];
    struct node* next;
} node;

typedef struct hash_map_entry {
    char key[M];
    node* value;
    pthread_mutex_t lock;
} hash_map_entry;

typedef struct hash_map {
    hash_map_entry** entries;
    size_t size;
} hash_map;

hash_map* create_hash_map(size_t size) {
    hash_map* map = (hash_map*)malloc(sizeof(hash_map));
    map->entries = (hash_map_entry**)calloc(size, sizeof(hash_map_entry*));
    map->size = size;
    return map;
}

void destroy_hash_map(hash_map* map) {
    for (size_t i = 0; i < map->size; ++i) {
        hash_map_entry* entry = map->entries[i];
        if (entry != NULL) {
            pthread_mutex_destroy(&entry->lock);
            free(entry);
        }
    }
    free(map->entries);
    free(map);
}

hash_map_entry* get_hash_map_entry(hash_map* map, const char* key) {
    size_t hash = 0;
    for (size_t i = 0; key[i] != '\0'; ++i) {
        hash = (hash * 31 + key[i]) % map->size;
    }
    return map->entries[hash];
}

void insert_hash_map_entry(hash_map* map, const char* key, node* value) {
    hash_map_entry* entry = get_hash_map_entry(map, key);
    pthread_mutex_lock(&entry->lock);
    if (entry->value != NULL) {
        free(entry->value);
    }
    entry->value = value;
    pthread_mutex_unlock(&entry->lock);
}

node* create_node(int value, const char* description) {
    node* n = (node*)malloc(sizeof(node));
    n->value = value;
    strncpy(n->description, description, M - 1);
    n->description[M - 1] = '\0';
    n->next = NULL;
    return n;
}

void destroy_node(node* n) {
    free(n);
}

int validate_and_adjust(node** nodes, size_t N, int L, int S) {
    int sum_values = 0;
    int total_length = 0;

    for (size_t i = 0; i < N; ++i) {
        sum_values += nodes[i]->value;
        total_length += strlen(nodes[i]->description);
    }

    if (sum_values > L || total_length > S) {
        // Adjust values and descriptions
        // ...
        return 1; // Adjustments made
    }
    return 0; // No adjustments needed
}

int manage_memory_allocation_and_initialization(size_t N, int L, int S) {
    if (N < 0 || L < 0 || S < 0) {
        return -1; // Invalid input parameters
    }

    node** nodes = (node**)malloc(N * sizeof(node*));
    hash_map* map = create_hash_map(1024);

    for (size_t i = 0; i < N; ++i) {
        int value = rand() % 1001;
        char description[M];
        snprintf(description, M, "Node%d", i);
        nodes[i] = create_node(value, description);
        insert_hash_map_entry(map, description, nodes[i]);
    }

    if (validate_and_adjust(nodes, N, L, S)) {
        printf("Adjustments made to maintain constraints.\n");
    } else {
        printf("Constraints maintained without adjustments.\n");
    }

    for (size_t i = 0; i < N; ++i) {
        destroy_node(nodes[i]);
    }
    free(nodes);
    destroy_hash_map(map);

    return 0;
}
