#include <stdio.h>

typedef struct {
    int key;
    float value;
    char *string;
} record;

record* create_record(int key, float value, const char *str) {
    record *r = (record *)malloc(sizeof(record));
    if (!r) return NULL;
    r->key = key;
    r->value = value;
    r->string = strdup(str);
    if (!r->string) {
        free(r);
        return NULL;
    }
    return r;
}

void destroy_record(record *r) {
    if (r) {
        free(r->string);
        free(r);
    }
}

int compare_records(const void *a, const void *b) {
    record **ra = (record **)a;
    record **rb = (record **)b;
    return (*ra)->key - (*rb)->key;
}

void sort_records(record **records, int num_records) {
    qsort(records, num_records, sizeof(record *), compare_records);
}

int insert_record(record ***records, int *num_records, int max_records, record *new_record) {
    if (*num_records >= max_records) return -1; // Overflow
    (*records)[*num_records] = new_record;
    (*num_records)++;
    sort_records(*records, *num_records);
    return 0;
}

void print_records(record **records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        printf("Key: %d, Value: %.2f, String: %s\n", records[i]->key, records[i]->value, records[i]->string);
    }
}

int main() {
    const int max_records = 10;
    record **records = (record **)malloc(max_records * sizeof(record *));
    if (!records) return -1;

    int num_records = 0;
    insert_record(&records, &num_records, max_records, create_record(3, 3.14, "Three"));
    insert_record(&records, &num_records, max_records, create_record(1, 2.71, "One"));
    insert_record(&records, &num_records, max_records, create_record(2, 1.62, "Two"));

    print_records(records, num_records);

    for (int i = 0; i < num_records; i++) {
        destroy_record(records[i]);
    }
    free(records);

    return 0;
}
