#include <openssl/evp.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
    void* metadata;
} DataPacket;

typedef struct {
    pthread_mutex_t lock;
    DataPacket** table;
    size_t size;
    size_t capacity;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = (DataPacket**)calloc(initial_capacity, sizeof(DataPacket*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);
    ht->size = 0;
    ht->capacity = initial_capacity;

    return ht;
}

void destroy_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->table[i]) {
            free(ht->table[i]->metadata);
            free(ht->table[i]);
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht->table);
    free(ht);
}

size_t hash_function(const DataPacket* packet, size_t capacity) {
    return (packet->timestamp + packet->packet_id) % capacity;
}

int add_packet(HashTable* ht, const DataPacket* packet) {
    pthread_mutex_lock(&ht->lock);

    if (ht->size >= ht->capacity * 0.75) {
        // Resize the table
        size_t new_capacity = ht->capacity * 2;
        DataPacket** new_table = (DataPacket**)calloc(new_capacity, sizeof(DataPacket*));
        if (!new_table) {
            pthread_mutex_unlock(&ht->lock);
            return -1; // Memory allocation failed
        }

        for (size_t i = 0; i < ht->capacity; ++i) {
            if (ht->table[i]) {
                size_t new_index = hash_function(ht->table[i], new_capacity);
                while (new_table[new_index]) {
                    new_index = (new_index + 1) % new_capacity;
                }
                new_table[new_index] = ht->table[i];
            }
        }

        free(ht->table);
        ht->table = new_table;
        ht->capacity = new_capacity;
    }

    size_t index = hash_function(packet, ht->capacity);
    while (ht->table[index]) {
        if (ht->table[index]->packet_id == packet->packet_id && ht->table[index]->timestamp == packet->timestamp) {
            // Update existing packet
            free(ht->table[index]->metadata);
            memcpy(ht->table[index], packet, sizeof(DataPacket));
            pthread_mutex_unlock(&ht->lock);
            return 0;
        }
        index = (index + 1) % ht->capacity;
    }

    // Add new packet
    DataPacket* new_packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!new_packet) {
        pthread_mutex_unlock(&ht->lock);
        return -1; // Memory allocation failed
    }
    memcpy(new_packet, packet, sizeof(DataPacket));
    ht->table[index] = new_packet;
    ++ht->size;

    pthread_mutex_unlock(&ht->lock);
    return 0;
}

DataPacket* get_packet(HashTable* ht, int packet_id, time_t timestamp) {
    pthread_mutex_lock(&ht->lock);

    size_t index = hash_function(&(DataPacket){timestamp, packet_id}, ht->capacity);
    while (ht->table[index]) {
        if (ht->table[index]->packet_id == packet_id && ht->table[index]->timestamp == timestamp) {
            DataPacket* result = (DataPacket*)malloc(sizeof(DataPacket));
            if (!result) {
                pthread_mutex_unlock(&ht->lock);
                return NULL; // Memory allocation failed
            }
            memcpy(result, ht->table[index], sizeof(DataPacket));
            pthread_mutex_unlock(&ht->lock);
            return result;
        }
        index = (index + 1) % ht->capacity;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL; // Packet not found
}

int main() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest(EVP_rsa_sha1());

    HashTable* ht = create_hash_table(100);
    if (!ht) return -1; // Memory allocation failed

    DataPacket packet = {time(NULL), 1, 1024, malloc(1024)};
    if (add_packet(ht, &packet) != 0) {
        destroy_hash_table(ht);
        return -1; // Failed to add packet
    }

    DataPacket* retrieved_packet = get_packet(ht, 1, packet.timestamp);
    if (!retrieved_packet) {
        destroy_hash_table(ht);
        return -1; // Packet not found
    }

    free(retrieved_packet->metadata);
    free(retrieved_packet);
    destroy_hash_table(ht);

    return 0;
}
