    struct nr_phy_layer_stats {
        // Define fields here
    } stats;
};

typedef struct {
    NR_PHY_STATS_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} nr_phy_stats_manager;

void init_nr_phy_stats_manager(nr_phy_stats_manager *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->array = (NR_PHY_STATS_T *)malloc(initial_capacity * sizeof(NR_PHY_STATS_T));
    pthread_mutex_init(&manager->mutex, NULL);
}

void destroy_nr_phy_stats_manager(nr_phy_stats_manager *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->mutex);
}

int add_entry(nr_phy_stats_manager *manager, NR_PHY_STATS_T entry) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NR_PHY_STATS_T *new_array = (NR_PHY_STATS_T *)realloc(manager->array, new_capacity * sizeof(NR_PHY_STATS_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failed
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }
    manager->array[manager->size++] = entry;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int remove_entry(nr_phy_stats_manager *manager, int PCI) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].PCI == PCI) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->array[j] = manager->array[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // Entry not found
}

int update_stats(nr_phy_stats_manager *manager, int PCI, NR_PHY_LAYER_STATS new_stats) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].PCI == PCI) {
            manager->array[i].stats = new_stats;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // Entry not found
}
