typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketCollection;

void init_packet_collection(PacketCollection *collection) {
    collection->packets = NULL;
    collection->count = 0;
    collection->capacity = 0;
}

void add_packet(PacketCollection *collection, DataPacket packet) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = (collection->capacity == 0) ? 1 : collection->capacity * 2;
        collection->packets = realloc(collection->packets, new_capacity * sizeof(DataPacket));
        collection->capacity = new_capacity;
    }
    collection->packets[collection->count++] = packet;
}

void update_packet(PacketCollection *collection, int packet_id, DataPacket new_packet) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->packets[i].packet_id == packet_id) {
            collection->packets[i] = new_packet;
            return;
        }
    }
}

DataPacket* get_packets_in_range(PacketCollection *collection, time_t start_time, time_t end_time) {
    DataPacket *result = NULL;
    size_t result_count = 0;

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->packets[i].timestamp >= start_time && collection->packets[i].timestamp <= end_time) {
            result = realloc(result, (result_count + 1) * sizeof(DataPacket));
            result[result_count++] = collection->packets[i];
        }
    }

    return result;
}

void free_packet_collection(PacketCollection *collection) {
    free(collection->packets);
    init_packet_collection(collection);
}
