#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long value;
} offset;

typedef struct {
    int key;
} key;

typedef struct {
    int record;
} record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

void initialize_offset(offset* offsets, int count) {
    for (int i = 0; i < count; i++) {
        offsets[i].value = i * 100L;
    }
}

void initialize_key(key* keys, int count) {
    for (int i = 0; i < count; i++) {
        keys[i].key = i * 256;
    }
}

void initialize_record(record* records, int count) {
    srand(time(NULL));
    int last_value = -1;
    for (int i = 0; i < count; i++) {
        int value;
        do {
            value = rand() % 1000;
        } while (value == last_value);
        records[i].record = value;
        last_value = value;
    }
}

void free_all_memory(offset* offsets, key* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

void log_performance(double allocation_time, double deallocation_time) {
    printf("Memory Allocation Time: %f seconds\n", allocation_time);
    printf("Memory Deallocation Time: %f seconds\n", deallocation_time);
}

int main() {
    int offset_count = 10;
    int key_count = (offset_count + 1) / 2;

    offset* offsets = allocate_memory(offset_count * sizeof(offset));
    initialize_offset(offsets, offset_count);

    key* keys = allocate_memory(key_count * sizeof(key));
    initialize_key(keys, key_count);

    record* records = allocate_memory((offset_count + key_count) * sizeof(record));
    initialize_record(records, offset_count + key_count);

    double allocation_time = clock() / (double)CLOCKS_PER_SEC;
    // Perform operations with the allocated memory
    double deallocation_time = clock() / (double)CLOCKS_PER_SEC;

    free_all_memory(offsets, keys, records);
    log_performance(allocation_time, deallocation_time);

    return 0;
}
