#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int key;
    float value;
    char* str;
    time_t timestamp;
} Record;

typedef struct RecordCollection {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]->str);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void insert_record(RecordCollection* collection, int key, float value, const char* str) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    record->str = strdup(str);
    time(&record->timestamp);
    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->lock);
}

void sort_records(RecordCollection* collection) {
    qsort(collection->records, collection->size, sizeof(Record*), 
          (int (*)(const void*, const void*))compare_records);
}

int compare_records(const void* a, const void* b) {
    Record** record_a = (Record**)a;
    Record** record_b = (Record**)b;
    return (*record_a)->key - (*record_b)->key;
}

void serialize_collection(RecordCollection* collection, FILE* file) {
    fwrite(&collection->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->size; ++i) {
        fwrite(&collection->records[i]->key, sizeof(int), 1, file);
        fwrite(&collection->records[i]->value, sizeof(float), 1, file);
        size_t str_len = strlen(collection->records[i]->str) + 1;
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(collection->records[i]->str, sizeof(char), str_len, file);
        fwrite(&collection->records[i]->timestamp, sizeof(time_t), 1, file);
    }
}

void deserialize_collection(RecordCollection* collection, FILE* file) {
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    if (size > collection->capacity) {
        Record** new_records = (Record**)realloc(collection->records, size * sizeof(Record*));
        if (!new_records) {
            perror("Failed to reallocate memory");
            return;
        }
        collection->records = new_records;
        collection->capacity = size;
    }
    for (size_t i = 0; i < size; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(float), 1, file);
        size_t str_len;
        fread(&str_len, sizeof(size_t), 1, file);
        record->str = (char*)malloc(str_len * sizeof(char));
        fread(record->str, sizeof(char), str_len, file);
        time_t timestamp;
        fread(&timestamp, sizeof(time_t), 1, file);
        record->timestamp = timestamp;
        collection->records[i] = record;
    }
    collection->size = size;
}
