#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    int CRCFLAG;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordList;

int init_record_list(RecordList *list, size_t initial_capacity) {
    list->records = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->records) return -1; // Memory allocation failed
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

void free_record_list(RecordList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->records);
    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int add_record(RecordList *list, NFAPI_CRC_INDICATION_PDU_T record) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_records = realloc(list->records, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_records) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }
    list->records[list->count++] = record;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_record_list(RecordList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1; // Failed to open file

    pthread_mutex_lock(&list->lock);
    size_t written = fwrite(list->records, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return written != list->count ? -1 : 0;
}

int deserialize_record_list(RecordList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1; // Failed to open file

    pthread_mutex_lock(&list->lock);
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t count = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (count > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_records = realloc(list->records, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_records) {
            pthread_mutex_unlock(&list->lock);
            fclose(file);
            return -1; // Memory allocation failed
        }
        list->records = new_records;
        list->capacity = count;
    }

    size_t read_count = fread(list->records, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return read_count != count ? -1 : 0;
}

int main() {
    RecordList list;
    if (init_record_list(&list, 1024) != 0) {
        fprintf(stderr, "Failed to initialize record list\n");
        return 1;
    }

    // Populate the list with records
    for (size_t i = 0; i < 1024; ++i) {
        NFAPI_CRC_INDICATION_PDU_T record;
        record.CRCFLAG = rand() % 256;
        if (add_record(&list, record) != 0) {
            fprintf(stderr, "Failed to add record\n");
            free_record_list(&list);
            return 1;
        }
    }

    // Serialize the list
    if (serialize_record_list(&list, "records.bin") != 0) {
        fprintf(stderr, "Failed to serialize record list\n");
        free_record_list(&list);
        return 1;
    }

    // Deserialize the list
    RecordList new_list;
    if (init_record_list(&new_list, 1024) != 0) {
        fprintf(stderr, "Failed to initialize new record list\n");
        free_record_list(&list);
        return 1;
    }
    if (deserialize_record_list(&new_list, "records.bin") != 0) {
        fprintf(stderr, "Failed to deserialize record list\n");
        free_record_list(&list);
        free_record_list(&new_list);
        return 1;
    }

    // Free the lists
    free_record_list(&list);
    free_record_list(&new_list);

    return 0;
}
