import java.security.*;
import javax.crypto.*;
import java.util.*;

class DataPacket {
    long timestamp;
    int packetID;
    int payloadLength;
    String metadata;

    public DataPacket(long timestamp, int packetID, int payloadLength, String metadata) {
        this.timestamp = timestamp;
        this.packetID = packetID;
        this.payloadLength = payloadLength;
        this.metadata = metadata;
    }
}

class DataManagementService {
    private Map<Integer, DataPacket> packetMap;
    private Cipher aesCipher;
    private Cipher camelliaCipher;
    private MessageDigest md5Digest;
    private MessageDigest shaDigest;

    public DataManagementService() throws NoSuchAlgorithmException, NoSuchPaddingException {
        packetMap = new HashMap<>();
        aesCipher = Cipher.getInstance("AES");
        camelliaCipher = Cipher.getInstance("Camellia");
        md5Digest = MessageDigest.getInstance("MD5");
        shaDigest = MessageDigest.getInstance("SHA-1");
    }

    public void addPacket(DataPacket packet) {
        packetMap.put(packet.packetID, packet);
    }

    public void updatePacket(int packetID, DataPacket newPacket) {
        if (packetMap.containsKey(packetID)) {
            packetMap.put(packetID, newPacket);
        }
    }

    public List<DataPacket> getPacketsInRange(long startTimestamp, long endTimestamp) {
        List<DataPacket> result = new ArrayList<>();
        for (DataPacket packet : packetMap.values()) {
            if (packet.timestamp >= startTimestamp && packet.timestamp <= endTimestamp) {
                result.add(packet);
            }
        }
        return result;
    }

    public byte[] encrypt(byte[] data, String algorithm) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm);
        SecretKeySpec keySpec = new SecretKeySpec("0123456789abcdef".getBytes(), algorithm);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec);
        return cipher.doFinal(data);
    }

    public byte[] decrypt(byte[] encryptedData, String algorithm) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm);
        SecretKeySpec keySpec = new SecretKeySpec("0123456789abcdef".getBytes(), algorithm);
        cipher.init(Cipher.DECRYPT_MODE, keySpec);
        return cipher.doFinal(encryptedData);
    }

    public byte[] digest(byte[] data, String algorithm) throws Exception {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        return digest.digest(data);
    }
}
