#define MAX_RECORDS 1000

typedef struct {
    int key;
    float value;
    char* str;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
} RecordCollection;

void init_collection(RecordCollection* collection) {
    collection->count = 0;
}

int insert_record(RecordCollection* collection, int key, float value, const char* str) {
    if (collection->count >= MAX_RECORDS) return -1; // Collection is full
    Record new_record = {key, value, strdup(str)};
    collection->records[collection->count++] = new_record;
    return 0;
}

Record* get_record(RecordCollection* collection, int key) {
    for (int i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) return &collection->records[i];
    }
    return NULL;
}

void sort_collection(RecordCollection* collection) {
    // Implement a sorting algorithm here
    // For simplicity, using bubble sort for demonstration purposes
    for (int i = 0; i < collection->count - 1; i++) {
        for (int j = 0; j < collection->count - i - 1; j++) {
            if (collection->records[j].key > collection->records[j + 1].key) {
                Record temp = collection->records[j];
                collection->records[j] = collection->records[j + 1];
                collection->records[j + 1] = temp;
            }
        }
    }
}

void free_collection(RecordCollection* collection) {
    for (int i = 0; i < collection->count; i++) {
        free(collection->records[i].str);
    }
}
