#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define NetworkInterfaceConfig structure
typedef struct {
    char name[64];
    char ip[16];
} NetworkInterfaceConfig;

// Define DataPacket structure
typedef struct {
    int id;
    char content[256];
} DataPacket;

// Define a simple hash table for network interfaces
#define HASH_SIZE 1024
typedef struct {
    NetworkInterfaceConfig *interfaces[HASH_SIZE];
    pthread_mutex_t locks[HASH_SIZE];
} NetworkInterfaceTable;

// Define a linked list for data packets
typedef struct DataPacketNode {
    DataPacket packet;
    struct DataPacketNode *next;
} DataPacketNode;

typedef struct {
    DataPacketNode *head;
    pthread_mutex_t lock;
} DataPacketList;

// Initialize network interface table and data packet list
void init_network_interface_table(NetworkInterfaceTable *table) {
    for (int i = 0; i < HASH_SIZE; i++) {
        table->interfaces[i] = NULL;
        pthread_mutex_init(&table->locks[i], NULL);
    }
    pthread_mutex_init(&table->lock, NULL);
}

void init_data_packet_list(DataPacketList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add or update a network interface
int add_or_update_network_interface(NetworkInterfaceTable *table, NetworkInterfaceConfig *config) {
    int hash = (hash_string(config->name) % HASH_SIZE);
    pthread_mutex_lock(&table->locks[hash]);
    NetworkInterfaceConfig *existing = table->interfaces[hash];
    if (existing != NULL && strcmp(existing->name, config->name) == 0) {
        // Update existing interface
        strcpy(existing->ip, config->ip);
        pthread_mutex_unlock(&table->locks[hash]);
        return 1;
    } else {
        // Add new interface
        NetworkInterfaceConfig *new_config = malloc(sizeof(NetworkInterfaceConfig));
        if (new_config == NULL) {
            pthread_mutex_unlock(&table->locks[hash]);
            return -1; // Memory allocation failed
        }
        strcpy(new_config->name, config->name);
        strcpy(new_config->ip, config->ip);
        table->interfaces[hash] = new_config;
        pthread_mutex_unlock(&table->locks[hash]);
        return 0;
    }
}

// Retrieve a network interface by name
NetworkInterfaceConfig *get_network_interface(NetworkInterfaceTable *table, const char *name) {
    int hash = (hash_string(name) % HASH_SIZE);
    pthread_mutex_lock(&table->locks[hash]);
    NetworkInterfaceConfig *interface = table->interfaces[hash];
    if (interface != NULL && strcmp(interface->name, name) == 0) {
        pthread_mutex_unlock(&table->locks[hash]);
        return interface;
    } else {
        pthread_mutex_unlock(&table->locks[hash]);
        return NULL;
    }
}

// Add a data packet to the list
int add_data_packet(DataPacketList *list, DataPacket *packet) {
    pthread_mutex_lock(&list->lock);
    DataPacketNode *new_node = malloc(sizeof(DataPacketNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->packet = *packet;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Retrieve the first data packet from the list
DataPacket *get_first_data_packet(DataPacketList *list) {
    pthread_mutex_lock(&list->lock);
    DataPacketNode *node = list->head;
    if (node != NULL) {
        DataPacket *packet = malloc(sizeof(DataPacket));
        if (packet == NULL) {
            pthread_mutex_unlock(&list->lock);
            return NULL; // Memory allocation failed
        }
        *packet = node->packet;
        pthread_mutex_unlock(&list->lock);
        return packet;
    } else {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
}

// Helper function to hash a string
unsigned int hash_string(const char *str) {
    unsigned int hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

// Unit tests
void test_network_interface_table() {
    NetworkInterfaceTable table;
    init_network_interface_table(&table);

    NetworkInterfaceConfig config1 = {"eth0", "192.168.1.1"};
    NetworkInterfaceConfig config2 = {"eth1", "192.168.1.2"};

    add_or_update_network_interface(&table, &config1);
    add_or_update_network_interface(&table, &config2);

    NetworkInterfaceConfig *interface = get_network_interface(&table, "eth0");
    if (interface != NULL && strcmp(interface->ip, "192.168.1.1") == 0) {
        printf("Test passed: eth0 interface found with correct IP.\n");
    } else {
        printf("Test failed: eth0 interface not found or incorrect IP.\n");
    }

    free_network_interface_table(&table);
}

void test_data_packet_list() {
    DataPacketList list;
    init_data_packet_list(&list);

    DataPacket packet1 = {1, "Hello, world!"};
    DataPacket packet2 = {2, "Data packet 2"};

    add_data_packet(&list, &packet1);
    add_data_packet(&list, &packet2);

    DataPacket *first_packet = get_first_data_packet(&list);
    if (first_packet != NULL && first_packet->id == 1) {
        printf("Test passed: First data packet retrieved correctly.\n");
    } else {
        printf("Test failed: First data packet not retrieved or incorrect ID.\n");
    }

    free_data_packet_list(&list);
}

int main() {
    test_network_interface_table();
    test_data_packet_list();
    return 0;
}
