    pthread_mutex_lock(&profile->lock);
    Role* newRole = createRole(roleName);
    if (!profile->roles) {
        profile->roles = newRole;
    } else {
        Role* current = profile->roles;
        while (current->next) {
            current = current->next;
        }
        current->next = newRole;
