    time_t timestamp;
    float temperature;
    size_t event_count;
} sensor;

sensor** sensors = NULL;
size_t sensor_count = 0;
size_t max_sensors = 1024;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_sensor_data(sensor* s) {
    pthread_mutex_lock(&lock);
    printf("Sensor: %s, Timestamp: %ld, Temperature: %.2f, Events: %zu\n", 
           s->identifier, s->timestamp, s->temperature, s->event_count);
    pthread_mutex_unlock(&lock);
}

void add_sensor_data(sensor* s) {
    pthread_mutex_lock(&lock);
    if (sensor_count >= max_sensors) {
        max_sensors *= 2;
        sensors = realloc(sensors, max_sensors * sizeof(sensor*));
    }
    sensors[sensor_count++] = s;
    log_sensor_data(s);
    pthread_mutex_unlock(&lock);
}

void* sensor_thread(void* arg) {
    // Simulate sensor data processing
    for (int i = 0; i < 1000; i++) {
        sensor* s = malloc(sizeof(sensor));
        s->identifier = "sensor1";
        s->timestamp = time(NULL);
        s->temperature = (float)(rand() % 100) / 10.0;
        s->event_count = rand() % 100;
        add_sensor_data(s);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, sensor_thread, NULL);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
    free(sensors);
    return 0;
}
