#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long *offsets;
    int *keys;
    record_t *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} shared_memory_t;

shared_memory_t* init_shared_memory(size_t initial_capacity) {
    shared_memory_t *shm = (shared_memory_t*)malloc(sizeof(shared_memory_t));
    if (!shm) return NULL;

    shm->offsets = (long*)calloc(initial_capacity, sizeof(long));
    shm->keys = (int*)calloc(initial_capacity, sizeof(int));
    shm->records = (record_t*)calloc(initial_capacity, sizeof(record_t));
    if (!shm->offsets || !shm->keys || !shm->records) {
        free(shm);
        return NULL;
    }

    shm->capacity = initial_capacity;
    shm->count = 0;
    pthread_mutex_init(&shm->mutex, NULL);

    return shm;
}

void destroy_shared_memory(shared_memory_t *shm) {
    if (shm) {
        free(shm->offsets);
        free(shm->keys);
        free(shm->records);
        pthread_mutex_destroy(&shm->mutex);
        free(shm);
    }
}

int add_record(shared_memory_t *shm, long offset, int key, record_t record) {
    pthread_mutex_lock(&shm->mutex);

    if (shm->count >= shm->capacity) {
        size_t new_capacity = shm->capacity * 2;
        long *new_offsets = (long*)realloc(shm->offsets, new_capacity * sizeof(long));
        int *new_keys = (int*)realloc(shm->keys, new_capacity * sizeof(int));
        record_t *new_records = (record_t*)realloc(shm->records, new_capacity * sizeof(record_t));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&shm->mutex);
            return -1; // Memory allocation failed
        }

        shm->offsets = new_offsets;
        shm->keys = new_keys;
        shm->records = new_records;
        shm->capacity = new_capacity;
    }

    shm->offsets[shm->count] = offset;
    shm->keys[shm->count] = key;
    shm->records[shm->count++] = record;

    pthread_mutex_unlock(&shm->mutex);
    return 0; // Success
}

// Additional functions for updating records, retrieving data, etc.
