#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRC_INDICATION_REL8_TAG; }
#define MAX_NF_API_ENTRIES 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_NF_API_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
} NFAPICRCArray;

void initNFAPICRCArray(NFAPICRCArray *array) {
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

int addNFAPICRCEntry(NFAPICRCArray *array, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= MAX_NF_API_ENTRIES) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    array->entries[array->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array->entries[array->count].RNTI = RNTI;
    array->entries[array->count].CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRCFLAG
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void compactNFAPICRCArray(NFAPICRCArray *array) {
    pthread_mutex_lock(&array->lock);
    size_t new_count = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (array->entries[i].CRC_INDICATION_REL8_TAG != -1) { // Assuming -1 is a marker for unused entries
            array->entries[new_count++] = array->entries[i];
        }
    }
    while (new_count < array->count) {
        array->entries[new_count++].CRC_INDICATION_REL8_TAG = -1; // Mark remaining entries as unused
    }
    array->count = new_count;
    pthread_mutex_unlock(&array->lock);
}

void logNFAPICRCUpdates(NFAPICRCArray *array, int interval) {
    clock_t start = clock();
    size_t updates = 0;
    while (1) {
        pthread_mutex_lock(&array->lock);
        for (size_t i = 0; i < array->count; i++) {
            if (array->entries[i].CRC_INDICATION_REL8_TAG != -1) {
                updates++;
            }
        }
        pthread_mutex_unlock(&array->lock);
        clock_t end = clock();
        double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
        if (time_taken >= interval) {
            printf("Total CRCFLAG updates per second: %zu\n", updates / time_taken);
            updates = 0;
            start = end;
        }
    }
}

int queryNFAPICRCUpdates(NFAPICRCArray *array, int lastN, int *RX_UE_INFORMATION_TAGs, int *RNTIs, int *CRC_INDICATION_REL8_TAGS) {
    pthread_mutex_lock(&array->lock);
    size_t start_index = array->count > lastN ? array->count - lastN : 0;
    for (size_t i = start_index; i < array->count; i++) {
        RX_UE_INFORMATION_TAGs[i - start_index] = array->entries[i].RX_UE_INFORMATION_TAG;
        RNTIs[i - start_index] = array->entries[i].RNTI;
        CRC_INDICATION_REL8_TAGS[i - start_index] = array->entries[i].CRC_INDICATION_REL8_TAG;
    }
    pthread_mutex_unlock(&array->lock);
    return array->count - start_index;
}
