CryptoContext crypto_context;

void init_crypto() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest(EVP_md5());
    pthread_mutex_init(&crypto_context.lock, NULL);
}

void cleanup_crypto() {
    EVP_cleanup();
    pthread_mutex_destroy(&crypto_context.lock);
}

int encrypt_data(unsigned char *data, size_t data_size, unsigned char *key, unsigned char *iv) {
