    int len;
    if (EVP_EncryptInit_ex(crypto_context.cipher_ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1 ||
        EVP_EncryptUpdate(crypto_context.cipher_ctx, data, &len, data, data_size) != 1 ||
        EVP_EncryptFinal_ex(crypto_context.cipher_ctx, data + len, &len) != 1) {
        pthread_mutex_unlock(&crypto_context.lock);
        return -1;
    }
    pthread_mutex_unlock(&crypto_context.lock);
    return len;
}

