typedef struct {
    char* key;
    long timestamp;
    double value;
} entry;

entry* init_entries(const char* input, int count, int min_offset, int max_offset, double min_value, double max_value) {
    entry* entries = (entry*)malloc(count * sizeof(entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < count; i++) {
        pthread_mutex_lock(&lock);

        entries[i].key = strndup(input + i * 10, 10);
        if (!entries[i].key) {
            fprintf(stderr, "Memory allocation failed for key\n");
            free(entries);
            return NULL;
        }

        time_t now = time(NULL);
        long offset = min_offset + rand() % (max_offset - min_offset + 1);
        entries[i].timestamp = now + offset;

        double random_value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
        entries[i].value = random_value;

        pthread_mutex_unlock(&lock);
    }

    return entries;
}

void free_entries(entry* entries, int count) {
    for (int i = 0; i < count; i++) {
        free(entries[i].key);
    }
    free(entries);
}
