using System;
using System.IO;
using System.Xml.XPath;
using log4net;

public class XmlParser
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(XmlParser));
    private const string BaseDirectory = "C:\\XmlData";
    private static readonly object LockObject = new object();

    public XPathNavigator ParseAndFindElement(string xmlContent, string elementName)
    {
        try
        {
            var navigator = new XPathDocument(new StringReader(xmlContent)).CreateNavigator();
            var node = navigator.SelectSingleNode($"//{elementName}");
            if (node == null)
            {
                Log.Info($"No element with name '{elementName}' found.");
                return null;
            }
            else if (navigator.SelectNodes($"//{elementName}").Count > 1)
            {
                Log.Warn($"Multiple elements with name '{elementName}' found. Returning the first one.");
            }
            return node;
        }
        catch (Exception ex)
        {
            Log.Error($"Error parsing XML: {ex.Message}", ex);
            throw;
        }
    }

    public string GetStorageLocation(string specifiedPath = null)
    {
        lock (LockObject)
        {
            if (!string.IsNullOrEmpty(specifiedPath))
            {
                return Path.GetFullPath(specifiedPath);
            }

            var newDirectory = Path.Combine(BaseDirectory, Guid.NewGuid().ToString());
            Directory.CreateDirectory(newDirectory);

            Environment.SetEnvironmentVariable("XmlDataPath", newDirectory, EnvironmentVariableTarget.Process);
            return newDirectory;
        }
    }

    public void ValidateElement(XPathNavigator node, string elementName, string[] requiredAttributes)
    {
        if (node == null)
        {
            Log.Error($"Validation failed: Element '{elementName}' not found.");
            throw new InvalidOperationException("Element not found");
        }

        foreach (var attr in requiredAttributes)
        {
            if (!node.GetAttribute(attr, "") != null)
            {
                Log.Error($"Validation failed: Attribute '{attr}' is missing on element '{elementName}'.");
                throw new InvalidOperationException($"Missing attribute '{attr}'");
            }
        }
    }
}
