void manage_memory_and_update(weather_record *weather, sensor **sensors, event **events, int num_sensors, int num_events) {
    for (int i = 0; i < num_sensors; i++) {
        sensors[i]->timestamps = malloc(num_events * sizeof(long));
        if (!sensors[i]->timestamps) {
            printf("Failed to allocate memory for sensor timestamps\n");
