        events[i]->temperature_readings = malloc(num_sensors * sizeof(double));
        if (!events[i]->temperature_readings) {
            printf("Failed to allocate memory for event temperature readings\n");
            free(events[i]->sensors);
            return;
        }
    }

    weather_record *updated_weather = update_weather_record(weather);
    if (updated_weather) {
        for (int i = 0; i < num_events; i++) {
            for (int j = 0; j < num_sensors; j++) {
                events[i]->temperature_readings[j] = updated_weather->current_temperature;
            }
        }
    }

    // Free allocated memory
    for (int i = 0; i < num_sensors; i++) {
        free(sensors[i]->timestamps);
        free(sensors[i]->temperature);
    }
    for (int i = 0; i < num_events; i++) {
        free(events[i]->sensors);
        free(events[i]->temperature_readings);
    }
}

