#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    int priority;
    int status;
} Item;

typedef struct Node {
    Item item;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ItemCollection;

ItemCollection* create_collection() {
    ItemCollection* collection = (ItemCollection*)malloc(sizeof(ItemCollection));
    if (collection == NULL) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_item(ItemCollection* collection, Item item) {
    pthread_mutex_lock(&collection->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    new_node->item = item;
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->lock);
}

Item* get_item(ItemCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);
    Node* current = collection->head;
    while (current != NULL) {
        if (current->item.id == id) {
            Item* result = &current->item;
            pthread_mutex_unlock(&collection->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void update_item(ItemCollection* collection, int id, int new_priority, int new_status) {
    pthread_mutex_lock(&collection->lock);
    Node* current = collection->head;
    while (current != NULL) {
        if (current->item.id == id) {
            current->item.priority = new_priority;
            current->item.status = new_status;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
}

void destroy_collection(ItemCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
