#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} dynamic_array;

void init_dynamic_array(dynamic_array* arr, size_t initial_capacity) {
    arr->records = (record*)malloc(initial_capacity * sizeof(record));
    if (!arr->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

void free_dynamic_array(dynamic_array* arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->records);
    arr->records = NULL;
    arr->capacity = 0;
    arr->size = 0;
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

void add_record(dynamic_array* arr, record new_record) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity ? arr->capacity * 2 : 1;
        record* new_records = (record*)realloc(arr->records, new_capacity * sizeof(record));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        arr->records = new_records;
        arr->capacity = new_capacity;
    }
    arr->records[arr->size++] = new_record;
    pthread_mutex_unlock(&arr->mutex);
}

void iterate_dynamic_array(dynamic_array* arr, void (*callback)(record)) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; ++i) {
        callback(arr->records[i]);
    }
    pthread_mutex_unlock(&arr->mutex);
}
