#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <openssl/sha.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <thread>
#include <atomic>
#include <fstream>
#include <string>

class DataPacket {
public:
    uint64_t timestamp;
    uint32_t packetID;
    std::vector<uint8_t> payload;

    DataPacket(uint64_t ts, uint32_t id, const std::vector<uint8_t>& pld)
        : timestamp(ts), packetID(id), payload(pld) {}
};

class PacketManager {
private:
    std::vector<DataPacket> packets;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> running;

public:
    PacketManager() : running(true) {}

    ~PacketManager() {
        running = false;
        cv.notify_all();
    }

    void insert(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mtx);
        packets.push_back(packet);
        cv.notify_one();
    }

    bool remove(uint32_t packetID, DataPacket& removedPacket) {
        std::unique_lock<std::mutex> lock(mtx);
        while (packets.empty() && running) {
            cv.wait(lock);
        }
        if (!running) return false;
        auto it = std::find_if(packets.begin(), packets.end(),
                               [packetID](const DataPacket& p) { return p.packetID == packetID; });
        if (it != packets.end()) {
            removedPacket = *it;
            packets.erase(it);
            return true;
        }
        return false;
    }

    bool retrieve(uint32_t packetID, DataPacket& retrievedPacket) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(packets.begin(), packets.end(),
                               [packetID](const DataPacket& p) { return p.packetID == packetID; });
        if (it != packets.end()) {
            retrievedPacket = *it;
            return true;
        }
        return false;
    }

    void startProcessing() {
        std::thread([this]() {
            while (running) {
                DataPacket packet;
                if (remove(0, packet)) { // Assuming 0 is a placeholder for actual retrieval logic
                    processPacket(packet);
                }
            }
        }).detach();
    }

private:
    void processPacket(const DataPacket& packet) {
        // Implement packet processing logic here
        std::cout << "Processing packet with ID: " << packet.packetID << std::endl;
    }
};

int main() {
    PacketManager manager;
    manager.startProcessing();

    // Simulate inserting packets
    for (uint32_t i = 0; i < 10; ++i) {
        DataPacket packet(i, i, {static_cast<uint8_t>(i)});
        manager.insert(packet);
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    return 0;
}
```

