#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    int priority;
    int status;
} Item;

typedef struct {
    Item* items;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ItemCollection;

ItemCollection* create_item_collection() {
    ItemCollection* collection = (ItemCollection*)malloc(sizeof(ItemCollection));
    if (!collection) return NULL;
    collection->items = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_item_collection(ItemCollection* collection) {
    if (collection->items) free(collection->items);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_or_update_item(ItemCollection* collection, int id, int priority, int status) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i].id == id) {
            collection->items[i].priority = priority;
            collection->items[i].status = status;
            pthread_mutex_unlock(&collection->lock);
            return 1;
        }
    }
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 4;
        Item* new_items = (Item*)realloc(collection->items, new_capacity * sizeof(Item));
        if (!new_items) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->items = new_items;
        collection->capacity = new_capacity;
    }
    collection->items[collection->count].id = id;
    collection->items[collection->count].priority = priority;
    collection->items[collection->count].status = status;
    ++collection->count;
    pthread_mutex_unlock(&collection->lock);
    return 1;
}

Item* get_item_by_id(ItemCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i].id == id) {
            Item* item = &collection->items[i];
            pthread_mutex_unlock(&collection->lock);
            return item;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}
