    int usage_status;
} Resource;

typedef struct Node {
    Resource data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ResourceCollection;

ResourceCollection* create_collection() {
    ResourceCollection* collection = (ResourceCollection*)malloc(sizeof(ResourceCollection));
    if (collection == NULL) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_resource(ResourceCollection* collection, Resource resource) {
    pthread_mutex_lock(&collection->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    new_node->data = resource;
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->lock);
}

void update_resource(ResourceCollection* collection, int identifier, Resource updated_resource) {
    pthread_mutex_lock(&collection->lock);
    Node* current = collection->head;
    while (current != NULL) {
        if (current->data.identifier == identifier) {
            current->data = updated_resource;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
}

Resource* get_resource(ResourceCollection* collection, int identifier) {
    pthread_mutex_lock(&collection->lock);
    Node* current = collection->head;
    while (current != NULL) {
        if (current->data.identifier == identifier) {
            Resource* result = (Resource*)malloc(sizeof(Resource));
            if (result != NULL) *result = current->data;
            pthread_mutex_unlock(&collection->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void free_collection(ResourceCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
