#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_INSTANCES 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *array[MAX_INSTANCES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int instance_count = 0;
int timeout_period = 60; // seconds

void* update_crc_flag(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < instance_count) {
        array[index]->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly generate CRCFLAG
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* clear_array(void* arg) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < instance_count; i++) {
        free(array[i]);
        array[i] = NULL;
    }
    instance_count = 0;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void add_instance(int RX_UE_INFORMATION_TAG, int RNTI) {
    if (instance_count >= MAX_INSTANCES) {
        printf("Error: Maximum instances reached.\n");
        return;
    }
    array[instance_count] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array[instance_count]) {
        printf("Error: Memory allocation failed.\n");
        return;
    }
    array[instance_count]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array[instance_count]->RNTI = RNTI;
    array[instance_count]->CRC_INDICATION_REL8_TAG = 0; // Initialize CRCFLAG
    instance_count++;
}

void* monitor_and_update_crc_flag(void* arg) {
    while (1) {
        for (int i = 0; i < instance_count; i++) {
            pthread_t thread;
            int *index = (int*)malloc(sizeof(int));
            *index = i;
            pthread_create(&thread, NULL, update_crc_flag, index);
            pthread_detach(thread);
        }
        sleep(timeout_period);
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_and_update_crc_flag, NULL);

    // Example usage
    add_instance(12345, 67890);
    add_instance(54321, 98765);

    pthread_join(monitor_thread, NULL);

    return 0;
}
