#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int packetID;
    size_t payloadLength;
    int priorityScore;
} DataPacket;

typedef struct {
    DataPacket *data;
    size_t size;
    size_t capacity;
} PacketArray;

void initPacketArray(PacketArray *array, size_t initialCapacity) {
    array->data = (DataPacket *)malloc(initialCapacity * sizeof(DataPacket));
    if (array->data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initialCapacity;
}

void addPacket(PacketArray *array, DataPacket packet) {
    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        DataPacket *newData = (DataPacket *)realloc(array->data, newCapacity * sizeof(DataPacket));
        if (newData == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->data = newData;
        array->capacity = newCapacity;
    }
    array->data[array->size++] = packet;
}

void updatePacket(PacketArray *array, int packetID, DataPacket updatedPacket) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].packetID == packetID) {
            array->data[i] = updatedPacket;
            return;
        }
    }
}

void get_packets_by_timestamp_range(PacketArray *array, time_t start, time_t end, DataPacket **result, size_t *resultSize) {
    *resultSize = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].timestamp >= start && array->data[i].timestamp <= end) {
            (*resultSize)++;
        }
    }
    *result = (DataPacket *)malloc((*resultSize) * sizeof(DataPacket));
    size_t j = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].timestamp >= start && array->data[i].timestamp <= end) {
            (*result)[j++] = array->data[i];
        }
    }
}

void freePacketArray(PacketArray *array) {
    free(array->data);
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
}
