typedef enum {DEBUG, INFO, WARNING, ERROR} log_severity;

typedef struct {
    unsigned long timestamp;
    char *message;
    log_severity severity;
} log_entry;

log_entry log_entries[MAX_LOG_ENTRIES];
char *message_buffers[MAX_LOG_ENTRIES];
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_log_system(int N, int M, int L) {
    for (int i = 0; i < N; i++) {
        message_buffers[i] = malloc(M);
        if (!message_buffers[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        log_entries[i].timestamp = time(NULL);
        log_entries[i].message = message_buffers[i];
        log_entries[i].severity = INFO;
    }
}

void cleanup_log_system() {
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        free(message_buffers[i]);
    }
}

void log_message(log_severity severity, const char *format, ...) {
    pthread_mutex_lock(&log_mutex);
    int index = find_available_entry();
    if (index == -1) {
        cleanup_log_system();
        initialize_log_system(MAX_LOG_ENTRIES, MAX_MESSAGE_LENGTH, 0);
        index = find_available_entry();
    }
    log_entries[index].severity = severity;
    va_list args;
    va_start(args, format);
    vsnprintf(log_entries[index].message, MAX_MESSAGE_LENGTH, format, args);
    va_end(args);
    log_entries[index].timestamp = time(NULL);
    pthread_mutex_unlock(&log_mutex);
}

int find_available_entry() {
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        if (log_entries[i].severity == INFO) {
            return i;
        }
    }
    return -1;
}
