#include <mutex>

struct Record {
    int value;
};

class MemoryManager {
private:
    static const size_t MAX_CACHE_SIZE = 100;
    Record* cache[MAX_CACHE_SIZE];
    size_t cacheSize;
    std::mutex mutex;

public:
    MemoryManager() : cacheSize(0) {}

    ~MemoryManager() {
        clearCache();
    }

    Record* getRecord(int value) {
        std::lock_guard<std::mutex> lock(mutex);
        for (size_t i = 0; i < cacheSize; ++i) {
            if (cache[i]->value == value) {
                return cache[i];
            }
        }
        if (cacheSize < MAX_CACHE_SIZE) {
            Record* newRecord = new Record{value};
            cache[cacheSize++] = newRecord;
            return newRecord;
        } else {
            // Handle cache overflow, e.g., replace least recently used item
            delete cache[0];
            for (size_t i = 1; i < cacheSize; ++i) {
                cache[i - 1] = cache[i];
            }
            Record* newRecord = new Record{value};
            cache[cacheSize - 1] = newRecord;
            return newRecord;
        }
    }

    void clearCache() {
        std::lock_guard<std::mutex> lock(mutex);
        for (size_t i = 0; i < cacheSize; ++i) {
            delete cache[i];
        }
        cacheSize = 0;
    }
};

void processForwardList(std::forward_list<std::string>& list, const std::string& searchStr, const std::string& insertStr, MemoryManager& memoryManager) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == searchStr) {
            it = list.insert_after(it, insertStr);
            break;
        }
        ++it;
    }
    if (it == list.end()) {
        list.push_back(insertStr);
    }

    // Initialize and set random values for Records
    std::srand(std::time(nullptr));
    for (auto& str : list) {
        int randomValue = std::rand() % 100; // Random value between 0 and 99
        Record* record = memoryManager.getRecord(randomValue);
        // Use the record as needed
    }
}

int main() {
    MemoryManager memoryManager;
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    processForwardList(myList, "banana", "orange", memoryManager);

    for (const auto& str : myList) {
        std::cout << str << " ";
    }
    std::cout << std::endl;

    return 0;
}
