    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    Point* points;
    int num_points;
    Color** colors;
    int num_colors;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu(int n, int with_colors) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->points = (Point*)malloc(n * sizeof(Point));
    if (!pdu->points) {
        free(pdu);
        return NULL;
    }

    pdu->num_points = n;
    for (int i = 0; i < n; i++) {
        pdu->points[i].x = ((double)rand() / RAND_MAX) * 100.0;
        pdu->points[i].y = ((double)rand() / RAND_MAX) * 100.0;
    }

    if (with_colors) {
        pdu->colors = (Color**)malloc(n * sizeof(Color*));
        if (!pdu->colors) {
            free(pdu->points);
            free(pdu);
            return NULL;
        }
        for (int i = 0; i < n; i++) {
            pdu->colors[i] = (Color*)malloc(sizeof(Color));
            if (!pdu->colors[i]) {
                for (int j = 0; j < i; j++) free(pdu->colors[j]);
                free(pdu->colors);
                free(pdu->points);
                free(pdu);
                return NULL;
            }
            pdu->colors[i]->r = rand() % 256;
            pdu->colors[i]->g = rand() % 256;
            pdu->colors[i]->b = rand() % 256;
        }
        pdu->num_colors = n;
    } else {
        pdu->colors = NULL;
        pdu->num_colors = 0;
    }

    return pdu;
}

void free_nfaapi_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->points) {
        free(pdu->points);
    }
    if (pdu->colors) {
        for (int i = 0; i < pdu->num_colors; i++) {
            if (pdu->colors[i]) free(pdu->colors[i]);
        }
        free(pdu->colors);
    }
    free(pdu);
}

