#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    STATUS_OK,
    STATUS_ERROR
} status_t;

typedef struct record {
    char* name;
    double temperature;
    status_t status;
} record_t;

typedef struct collection {
    record_t** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} collection_t;

collection_t* create_collection() {
    collection_t* col = (collection_t*)malloc(sizeof(collection_t));
    if (!col) return NULL;
    col->records = NULL;
    col->count = 0;
    col->capacity = 0;
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

status_t add_record(collection_t* col, const char* name, double temperature, status_t status) {
    if (!col || !name) return STATUS_ERROR;

    pthread_mutex_lock(&col->mutex);

    if (col->count >= col->capacity) {
        size_t new_capacity = (col->capacity == 0) ? 1 : col->capacity * 2;
        record_t** new_records = (record_t**)realloc(col->records, new_capacity * sizeof(record_t*));
        if (!new_records) {
            pthread_mutex_unlock(&col->mutex);
            return STATUS_ERROR;
        }
        col->records = new_records;
        col->capacity = new_capacity;
    }

    record_t* rec = (record_t*)malloc(sizeof(record_t));
    if (!rec) {
        pthread_mutex_unlock(&col->mutex);
        return STATUS_ERROR;
    }

    rec->name = strdup(name);
    rec->temperature = temperature;
    rec->status = status;

    col->records[col->count++] = rec;

    pthread_mutex_unlock(&col->mutex);

    return STATUS_OK;
}

size_t get_record_count(collection_t* col) {
    if (!col) return 0;
    return col->count;
}

void free_collection(collection_t* col) {
    if (!col) return;

    pthread_mutex_lock(&col->mutex);

    for (size_t i = 0; i < col->count; ++i) {
        free(col->records[i]->name);
        free(col->records[i]);
    }

    free(col->records);
    pthread_mutex_unlock(&col->mutex);

    pthread_mutex_destroy(&col->mutex);
    free(col);
}
