void initializeModule(record** records, int* statusFlags, float*** matrix, int numRecords, int numRows, int numCols) {
    *records = (record*)malloc(numRecords * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }

    *statusFlags = (int*)malloc(numRecords * sizeof(int));
    if (*statusFlags == NULL) {
        fprintf(stderr, "Memory allocation failed for status flags\n");
        free(*records);
        exit(EXIT_FAILURE);
    }

    *matrix = (float**)malloc(numRows * sizeof(float*));
    if (*matrix == NULL) {
        fprintf(stderr, "Memory allocation failed for matrix rows\n");
        free(*records);
        free(*statusFlags);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numRows; ++i) {
        (*matrix)[i] = (float*)malloc(numCols * sizeof(float));
        if ((*matrix)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for matrix row %d\n", i);
            for (int j = 0; j < i; ++j) {
                free((*matrix)[j]);
            }
            free(*records);
            free(*statusFlags);
            free(*matrix);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize records and status flags
    for (int i = 0; i < numRecords; ++i) {
        (*records)[i].value = 0.0;
        (*records)[i].str = (char*)malloc(100 * sizeof(char)); // Assuming max string length of 99 characters
        if ((*records)[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d string\n", i);
            for (int j = 0; j < i; ++j) {
                free((*records)[j].str);
            }
            free(*records);
            free(*statusFlags);
            for (int j = 0; j < numRows; ++j) {
                free((*matrix)[j]);
            }
            free(*matrix);
            exit(EXIT_FAILURE);
        }
        strcpy((*records)[i].str, "default");
        (*statusFlags)[i] = 0;
    }

    // Fill matrix with values based on a specified formula
    for (int i = 0; i < numRows; ++i) {
        for (int j = 0; j < numCols; ++j) {
            (*matrix)[i][j] = (float)(i * j); // Example formula
        }
    }
}

void freeModule(record* records, int* statusFlags, float** matrix, int numRows) {
    for (int i = 0; i < numRows; ++i) {
        free(matrix[i]);
    }
    free(matrix);
    for (int i = 0; i < numRecords; ++i) {
        free(records[i].str);
    }
    free(records);
    free(statusFlags);
}

int main() {
