    if (initial_size == 0) return;
    offset = malloc(initial_size * sizeof(long));
    keys = malloc(initial_size * sizeof(int));
    records = malloc(initial_size * sizeof(record*));
    if (!offset || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    size = initial_size;
}

void resize_memory(size_t new_capacity) {
    pthread_mutex_lock(&mutex);
    long* new_offset = realloc(offset, new_capacity * sizeof(long));
    int* new_keys = realloc(keys, new_capacity * sizeof(int));
    record** new_records = realloc(records, new_capacity * sizeof(record*));
    if (!new_offset || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    offset = new_offset;
    keys = new_keys;
    records = new_records;
    capacity = new_capacity;
    pthread_mutex_unlock(&mutex);
}

