["```javascript
const fs = require('fs').promises;
const path = require('path');
const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);

async function processFiles(directory, allowedExtensions, maxConcurrency) {
  const files = await fs.readdir(directory);
  const filteredFiles = files.filter(file => 
    allowedExtensions.includes(path.extname(file).toLowerCase())
  );

  let processedCount = 0;
  let totalProcessingTime = 0;

  const results = {};
  const concurrencyQueue = [];

  for (const file of filteredFiles) {
    concurrencyQueue.push(async () => {
      try {
        const startTime = Date.now();
        const content = await readFileAsync(path.join(directory, file));
        const endTime = Date.now();
        totalProcessingTime += endTime - startTime;
        results[file] = { content, processingTime: endTime - startTime };
        processedCount++;
      } catch (error) {
        console.error(`Error processing ${file}:`, error);
      }
    });

    if (concurrencyQueue.length >= maxConcurrency) {
      await concurrencyQueue.shift()();
    }
  }

  while (concurrencyQueue.length > 0) {
    await concurrencyQueue.shift()();
  }

  const averageProcessingTime = totalProcessingTime / processedCount;
  console.log(`Total files processed: ${processedCount}`);
  console.log(`Files filtered out: ${filteredFiles.length - processedCount}`);
  console.log(`Average processing time per file: ${averageProcessingTime}ms`);

  return results;
}

// Example usage:
const directoryPath = '/path/to/directory';
const allowedExtensions = ['.txt', '.json'];
const maxConcurrency = 5;

processFiles(directoryPath, allowedExtensions, maxConcurrency)
  .then(results => console.log('Processed files:', results))
  .catch(error => console.error('Error processing files:', error));
```

This code snippet provides a basic implementation of the described functionality. It uses `fs.promises` for asynchronous file operations and `util.promisify` to convert callback-based functions into promises, making them easier to work with in an async/await context. The function reads all files from the specified directory, filters them based on allowed extensions, and processes each file concurrently up to a maximum concurrency limit. It logs processing metrics and handles errors gracefully."]

