    while (1) {
        if (currentSize >= newSize) {
            newSize *= 2;
            array = realloc(array, newSize * sizeof(int));
            if (!array) {
                fprintf(stderr, "Memory reallocation failed.\n");
                exit(EXIT_FAILURE);
            }
        }

        int num;
        if (scanf("%d", &num) != 1) {
            break; // End of input or error
        }

        array[currentSize++] = num;

        if (num > largest) {
            largest = num;
        }
    }

    free(array);
    return largest;
}

