#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 100
#define INITIAL_CAPACITY 16

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_mutex_t lock;
} ListElement;

typedef struct {
    ListElement* elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t list_lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->elements = (ListElement*)calloc(INITIAL_CAPACITY, sizeof(ListElement));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->list_lock, NULL);

    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        pthread_mutex_init(&list->elements[i].lock, NULL);
    }

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->capacity; ++i) {
        pthread_mutex_destroy(&list->elements[i].lock);
    }

    free(list->elements);
    pthread_mutex_destroy(&list->list_lock);
    free(list);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || !data.RX_UE_INFORMATION_TAG || !data.RNTI || !data.CRC_INDICATION_REL8_TAG) return -1;

    pthread_mutex_lock(&list->list_lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        ListElement* new_elements = (ListElement*)realloc(list->elements, new_capacity * sizeof(ListElement));
        if (!new_elements) {
            pthread_mutex_unlock(&list->list_lock);
            return -1;
        }

        for (size_t i = list->capacity; i < new_capacity; ++i) {
            pthread_mutex_init(&new_elements[i].lock, NULL);
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    ListElement* element = &list->elements[list->size++];
    element->data = data;
    pthread_mutex_unlock(&element->lock);
    pthread_mutex_unlock(&list->list_lock);

    return 0;
}

int update_element(DynamicList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!list || index >= list->size || !new_data.RX_UE_INFORMATION_TAG || !new_data.RNTI || !new_data.CRC_INDICATION_REL8_TAG) return -1;

    pthread_mutex_lock(&list->elements[index].lock);
    pthread_mutex_lock(&list->list_lock);

    ListElement* element = &list->elements[index];
    element->data = new_data;

    pthread_mutex_unlock(&element->lock);
    pthread_mutex_unlock(&list->list_lock);

    return 0;
}

void iterate_elements(DynamicList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->list_lock);

    for (size_t i = 0; i < list->size; ++i) {
        pthread_mutex_lock(&list->elements[i].lock);
        callback(list->elements[i].data);
        pthread_mutex_unlock(&list->elements[i].lock);
    }

    pthread_mutex_unlock(&list->list_lock);
}

void log_operation(const char* operation, size_t index) {
    printf("Operation: %s, Index: %zu\n", operation, index);
}
