#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class NetworkAdapter {
public:
    virtual boost::future<std::string> sendRequest(const std::string& url) = 0;
};

class MockNetworkAdapter : public NetworkAdapter {
private:
    std::mt19937 rng;
    std::uniform_int_distribution<> latencyDist;
    std::uniform_int_distribution<> packetLossDist;

public:
    MockNetworkAdapter() : rng(std::random_device{}()), latencyDist(50, 200), packetLossDist(0, 10) {}

    boost::future<std::string> sendRequest(const std::string& url) override {
        return boost::async(boost::launch::async, [this, url]() -> std::string {
            // Simulate latency
            std::this_thread::sleep_for(std::chrono::milliseconds(latencyDist(rng)));

            // Simulate packet loss
            if (packetLossDist(rng) < 5) {
                return "Packet Loss";
            }

            // Simulate response
            return "Response from " + url;
        });
    }
};

class HttpClient {
private:
    NetworkAdapter& networkAdapter;
    std::queue<std::string> requestQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    bool stop;

public:
    HttpClient(NetworkAdapter& adapter) : networkAdapter(adapter), stop(false) {}

    void enqueueRequest(const std::string& url) {
        std::lock_guard<std::mutex> lock(queueMutex);
        requestQueue.push(url);
        queueCondVar.notify_one();
    }

    void start() {
        boost::thread_group threads;
        for (int i = 0; i < 10; ++i) {
            threads.create_thread([this]() {
                while (true) {
                    std::string url;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        queueCondVar.wait(lock, [this] { return !requestQueue.empty() || stop; });
                        if (stop && requestQueue.empty()) break;
                        url = requestQueue.front();
                        requestQueue.pop();
                    }

                    auto future = networkAdapter.sendRequest(url);
                    try {
                        std::string response = future.get();
                        std::cout << "Success: " << response << std::endl;
                    } catch (const boost::exception& e) {
                        std::cerr << "Failure: " << e.what() << std::endl;
                    }
                }
            });
        }

        threads.join_all();
    }

    void stopClient() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stop = true;
        }
        queueCondVar.notify_all();
    }
};

int main() {
    MockNetworkAdapter adapter;
    HttpClient client(adapter);

    client.enqueueRequest("http://api1.example.com/data");
    client.enqueueRequest("http://api2.example.com/info");

    client.start();

    return 0;
}
