```java
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;

public class CryptoLibrary {

    public enum Algorithm {
        AES, DES, TDEA
    }

    public enum Mode {
        ECB, CBC, CFB
    }

    public static byte[] encrypt(Algorithm algorithm, Mode mode, Key key, byte[] data) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm.name() + "/" + mode.name());
        if (mode == Mode.CBC || mode == Mode.CFB) {
            IvParameterSpec iv = new IvParameterSpec(new byte[16]); // Initialize IV
            cipher.init(Cipher.ENCRYPT_MODE, key, iv);
        } else {
            cipher.init(Cipher.ENCRYPT_MODE, key);
        }
        return cipher.doFinal(data);
    }

    public static byte[] decrypt(Algorithm algorithm, Mode mode, Key key, byte[] data) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm.name() + "/" + mode.name());
        if (mode == Mode.CBC || mode == Mode.CFB) {
            IvParameterSpec iv = new IvParameterSpec(new byte[16]); // Initialize IV
            cipher.init(Cipher.DECRYPT_MODE, key, iv);
        } else {
            cipher.init(Cipher.DECRYPT_MODE, key);
        }
        return cipher.doFinal(data);
    }

    public static Key generateKey(Algorithm algorithm) throws Exception {
        switch (algorithm) {
            case AES:
                return new SecretKeySpec(new byte[16], "AES");
            case DES:
                return new SecretKeySpec(new byte[8], "DES");
            case TDEA:
                return new SecretKeySpec(new byte[24], "TDEA");
            default:
                throw new IllegalArgumentException("Unsupported algorithm");
        }
    }

    public static void main(String[] args) {
        try {
            Algorithm algorithm = Algorithm.AES;
            Mode mode = Mode.CBC;
            Key key = generateKey(algorithm);
            String originalData = "Hello, World!";
            byte[] encryptedData = encrypt(algorithm, mode, key, originalData.getBytes());
            byte[] decryptedData = decrypt(algorithm, mode, key, encryptedData);

            System.out.println("Original: " + originalData);
            System.out.println("Encrypted: " + new String(encryptedData));
            System.out.println("Decrypted: " + new String(decryptedData));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
