```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef enum {
    AES, DES, TDEA
} Algorithm;

typedef enum {
    ECB, CBC, CFB
} Mode;

int encrypt(Algorithm algorithm, Mode mode, unsigned char *key, int key_len, unsigned char *iv, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    switch (algorithm) {
        case AES:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, iv))
                goto err;
            break;
        case DES:
            if (!EVP_EncryptInit_ex(ctx, EVP_des_cbc(), NULL, key, iv))
                goto err;
            break;
        case TDEA:
            if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv))
                goto err;
            break;
        default:
            EVP_CIPHER_CTX_free(ctx);
            return -1;
    }

    if (mode == ECB) {
        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
            goto err;
        ciphertext_len = len;
    } else if (mode == CBC) {
        if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv))
            goto err;
        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
            goto err;
        ciphertext_len = len;
    } else if (mode == CFB) {
        if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv))
            goto err;
        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
            goto err;
        ciphertext_len = len;
    }

    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto err;
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

int decrypt(Algorithm algorithm, Mode mode, unsigned char *key, int key_len, unsigned char *iv, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    switch (algorithm) {
        case AES:
            if (!EVP_DecryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, iv))
                goto err;
            break;
        case DES:
            if (!EVP_DecryptInit_ex(ctx, EVP_des_cbc(), NULL, key, iv))
                goto err;
            break;
        case TDEA:
            if (!EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv))
                goto err;
            break;
        default:
            EVP_CIPHER_CTX_free(ctx);
            return -1;
    }

    if (mode == ECB) {
        if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
            goto err;
        plaintext_len = len;
    } else if (mode == CBC) {
        if (!EVP_DecryptInit_ex(ctx, NULL, NULL, key, iv))
            goto err;
        if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
            goto err;
        plaintext_len = len;
    } else if (mode == CFB) {
        if (!EVP_DecryptInit_ex(ctx, NULL, NULL, key, iv))
            goto err;
        if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
            goto err;
        plaintext_len = len;
    }

    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        goto err;
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

int main() {
    unsigned char key[24] = {0}; // 24 bytes for TDEA
    unsigned char iv[8] = {0}; // 8 bytes for DES and TDEA, 16 bytes for AES
    unsigned char plaintext[] = "Hello, World!";
    int plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    int len;
    int ciphertext_len;

    if (RAND_bytes(key, sizeof(key)) != 1)
        return -1;

    if (RAND_bytes(iv, sizeof(iv)) != 1)
        return -1;

    ciphertext_len = encrypt(TDEA, CBC, key, sizeof(key), iv, plaintext, plaintext_len, ciphertext);
    if (ciphertext_len < 0)
        return -1;

    len = decrypt(TDEA, CBC, key, sizeof(key), iv, ciphertext, ciphertext_len, decryptedtext);
    if (len < 0)
        return -1;

    decryptedtext[len] = '\0';

    printf("Decrypted: %s\n", decryptedtext);

    return 0;
}
```

