#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    OK,
    ERROR_OUT_OF_MEMORY,
    // Add more status codes as needed
} Status;

typedef struct Record {
    char* sensor_id;
    double temperature;
    enum status quality_indicator;
    struct Record* next;
} Record;

typedef struct {
    Record* head;
    size_t count;
    pthread_mutex_t lock;
} EnvironmentalMonitor;

EnvironmentalMonitor* create_monitor() {
    EnvironmentalMonitor* monitor = (EnvironmentalMonitor*)malloc(sizeof(EnvironmentalMonitor));
    if (!monitor) return NULL;
    monitor->head = NULL;
    monitor->count = 0;
    pthread_mutex_init(&monitor->lock, NULL);
    return monitor;
}

Status add_record(EnvironmentalMonitor* monitor, const char* sensor_id, double temperature, enum status quality_indicator) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return ERROR_OUT_OF_MEMORY;

    new_record->sensor_id = strdup(sensor_id);
    new_record->temperature = temperature;
    new_record->quality_indicator = quality_indicator;
    new_record->next = NULL;

    pthread_mutex_lock(&monitor->lock);
    new_record->next = monitor->head;
    monitor->head = new_record;
    monitor->count++;
    pthread_mutex_unlock(&monitor->lock);

    return OK;
}

size_t get_record_count(EnvironmentalMonitor* monitor) {
    size_t count;
    pthread_mutex_lock(&monitor->lock);
    count = monitor->count;
    pthread_mutex_unlock(&monitor->lock);
    return count;
}

void free_monitor(EnvironmentalMonitor* monitor) {
    Record* current = monitor->head;
    while (current) {
        Record* next = current->next;
        free(current->sensor_id);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&monitor->lock);
    free(monitor);
}

// Add more functions as needed for exporting, filtering, statistics, etc.
