    MAC_LTE_TAP_PDU* packet_b = (MAC_LTE_TAP_PDU*)b;
    return (packet_a->TSN > packet_b->TSN) - (packet_a->TSN < packet_b->TSN);
}

int compare_packets_by_snr(const void* a, const void* b) {
    MAC_LTE_TAP_PDU* packet_a = (MAC_LTE_TAP_PDU*)a;
    MAC_LTE_TAP_PDU* packet_b = (MAC_LTE_TAP_PDU*)b;
    return (packet_a->SNR_INFORMATION > packet_b->SNR_INFORMATION) - (packet_a->SNR_INFORMATION < packet_b->SNR_INFORMATION);
}

void sort_packets(MAC_LTE_TAP_PDU** packets, int count, SortKey key, Order order) {
