typedef struct {
    int value;
    char* str;
} Record;

Record** create_records(int num_records, int min_value, int max_value, int string_length) {
    srand(time(NULL));
    Record** records = (Record**)malloc(num_records * sizeof(Record*));

    for (int i = 0; i < num_records; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;

        records[i]->str = (char*)malloc((string_length + 1) * sizeof(char));
        for (int j = 0; j < string_length; j++) {
            records[i]->str[j] = 'a' + rand() % 26;
        }
        records[i]->str[string_length] = '\0';
    }

    return records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);
}
