public class PageSectionService
{
    private ConcurrentDictionary<string, string> pageSections = new ConcurrentDictionary<string, string>();

    public IActionResult UpdatePageSection(string sectionId, string elementId, string htmlContent)
    {
        if (pageSections.TryUpdate(sectionId, htmlContent, out _))
        {
            return Ok("Update successful");
        }
        else
        {
            return StatusCode(500, "Failed to update page section");
        }
    }
