    return NULL;
}

void validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->CRC_INDICATION_REL8_TAG != 0 && pdu->CRC_INDICATION_REL8_TAG != 1) {
        printf("Error: Invalid CRC indication tag\n");
    }
}

void process_text_document(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    regex_t regex;
    regcomp(&regex, "(aws|azure|google cloud)", REG_EXTENDED | REG_ICASE);

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        regmatch_t matches[1];
        if (regexec(&regex, buffer, 1, matches, 0) == 0) {
            printf("Found technical term: %.*s\n", matches[0].rm_eo - matches[0].rm_so, buffer + matches[0].rm_so);
        }
    }

    regfree(&regex);
    fclose(file);
}

int main() {
    pthread_t thread;
    pthread_mutex_init(&mutex, NULL);

    if (pthread_create(&thread, NULL, generate_structs, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread, NULL);

    for (int i = 0; i < num_structs; i++) {
        validate_crc_indication(structs[i]);
        free(structs[i]);
    }

    pthread_mutex_destroy(&mutex);
    process_text_document("document.txt");

    return 0;
}
