function processTextFiles(urls, configPath) {
  const config = loadConfig(configPath);
  const keywordCounts = {};
  let totalProcessedSize = 0;

  urls.forEach(url => {
    downloadAndProcessFile(url, config, keywordCounts, (err, hash) => {
      if (err) {
        console.error(`Error processing file from ${url}:`, err);
      } else {
        console.log(`File processed successfully. SHA-256: ${hash}`);
      }
    });
  });

  function loadConfig(configPath) {
    return JSON.parse(fs.readFileSync(configPath, 'utf8'));
  }

  function downloadAndProcessFile(url, config, keywordCounts, callback) {
    const worker = new Worker(path.join(__dirname, 'worker.js'), { workerData: { url, config } });
    worker.on('message', data => {
      totalProcessedSize += data.size;
      updateKeywordCounts(keywordCounts, data.keywords);
      if (totalProcessedSize > 20 * 1024 * 1024) {
        pauseProcessing();
      }
    });
    worker.on('error', err => {
      callback(err);
    });
    worker.on('exit', code => {
      if (code !== 0) {
        callback(new Error(`Worker stopped with exit code ${code}`));
      } else {
        const hash = crypto.createHash('sha256').update(Buffer.from(JSON.stringify(keywordCounts))).digest('hex');
        callback(null, hash);
      }
    });
