    }
    for (int i = 0; i < matrix->rows; i++) {
        matrix->matrix[i] = (float*)malloc(matrix->cols * sizeof(float));
        if (!matrix->matrix[i]) {
            freeMatrix(matrix);
            return -1; // Memory allocation failed
        }
    }

    // Load bundle from file
    FILE* file = fopen(bundlePath, "r");
    if (!file) {
        freeMatrix(matrix);
