#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_RECORDS 10000
#define SUM_MIN 500000
#define SUM_MAX 750000
#define MIN_KEY 100
#define MAX_KEY 999
#define MIN_PRIME 2
#define MAX_PRIME 9973

typedef struct {
    int *value;
    int prime;
    time_t timestamp;
} record;

int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

void generate_primes(int *primes, int min_prime, int max_prime) {
    // Non-trivial algorithm to generate primes
    for (int i = min_prime; i <= max_prime; i++) {
        if (is_prime(i)) {
            *primes++ = i;
        }
    }
}

void initialize_system() {
    long *offsets = malloc(NUM_RECORDS * sizeof(long));
    int *keys = malloc(NUM_RECORDS * sizeof(int));
    record *records = malloc(NUM_RECORDS * sizeof(record));
    char *buffer = malloc(1024 * 1024);

    if (!offsets || !keys || !records || !buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets
    long sum = 0;
    for (int i = 0; i < NUM_RECORDS; i++) {
        offsets[i] = rand() % (SUM_MAX - SUM_MIN + 1) + SUM_MIN;
        sum += offsets[i];
    }
    if (sum < SUM_MIN || sum > SUM_MAX) {
        fprintf(stderr, "Offset sum out of range\n");
        exit(EXIT_FAILURE);
    }

    // Initialize keys
    for (int i = 0; i < NUM_RECORDS; i++) {
        do {
            keys[i] = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        } while (!is_prime(keys[i]));
    }

    // Initialize records
    int *prime_pool = malloc((max_prime - min_prime + 1) * sizeof(int));
    generate_primes(prime_pool, min_prime, max_prime);
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].value = NULL;
        records[i].prime = prime_pool[i];
        records[i].timestamp = time(NULL);
    }

    // Validate initialization
    FILE *log_file = fopen("validation_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < NUM_RECORDS; i++) {
        if (!is_prime(records[i].prime)) {
            fprintf(log_file, "Invalid prime number at index %d\n", i);
        }
    }
    fclose(log_file);

    // Handle buffer overflow
    int buffer_size = 1024 * 1024;
    int used_space = 0;
    while (used_space < buffer_size * 0.8) {
        // Use buffer efficiently
        used_space += rand() % 1024;
    }
    if (used_space >= buffer_size * 0.8) {
        fprintf(stderr, "Buffer overflow detected\n");
        exit(EXIT_FAILURE);
    }

    free(offsets);
    free(keys);
    free(records);
    free(buffer);
    free(prime_pool);
}

int main() {
    srand(time(NULL));
    initialize_system();
    return 0;
}
