#include <future>
#include <chrono>
#include <mutex>

class AsyncStringListManager {
public:
    void insertAfterTimeout(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert, std::chrono::milliseconds timeout) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto searchFuture = std::async(std::launch::async, [this, &list, &target](std::forward_list<std::string>::iterator& it) {
            for (it = list.begin(); it != list.end(); ++it) {
                if (*it == target) {
                    return true;
                }
            }
            return false;
        });

        auto insertFuture = std::async(std::launch::async, [this, &list, &toInsert](std::forward_list<std::string>::iterator& it) {
            list.insert_after(it, toInsert);
        });

        if (searchFuture.wait_for(timeout) == std::future_status::ready && searchFuture.get()) {
            auto insertIt = list.begin();
            while (insertIt != list.end() && *insertIt != target) {
                ++insertIt;
            }
            if (insertIt != list.end()) {
                insertFuture.wait_for(timeout);
                if (insertFuture.wait_for(std::chrono::milliseconds(0)) == std::future_status::ready) {
                    // Insertion completed within timeout
                } else {
                    // Insertion timed out, handle accordingly
                }
            }
        }

        // If search or insertion timed out, list remains unchanged
    }

private:
    std::mutex mutex_;
};
