#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000000
#define BATCH_SIZE 10000
#define INITIAL_RECORDS 100000

typedef struct {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void resize_array(void** array, size_t* capacity, size_t new_capacity) {
    *capacity = new_capacity;
    *array = realloc(*array, *capacity * sizeof(long));
    if (*array == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void initialize_records(Record** records, size_t* count) {
    *records = safe_malloc(INITIAL_RECORDS * sizeof(Record));
    *count = INITIAL_RECORDS;
    srand(time(NULL));
    for (size_t i = 0; i < *count; ++i) {
        (*records)[i].value = rand() % 1000001;
    }
}

void serialize_records(const Record* records, size_t count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(records, sizeof(Record), count, file);
    fclose(file);
}

void deserialize_records(Record** records, size_t* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    fseek(file, 0, SEEK_END);
    *count = ftell(file) / sizeof(Record);
    fseek(file, 0, SEEK_SET);
    *records = safe_malloc(*count * sizeof(Record));
    fread(*records, sizeof(Record), *count, file);
    fclose(file);
}

void verify_data_integrity(const Record* records, size_t count) {
    unsigned long long checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += records[i].value;
    }
    printf("Checksum: %llu\n", checksum);
}

int main() {
    long* offsets = NULL;
    size_t offset_capacity = 1000;
    Record* records = NULL;
    size_t record_count = 0;

    resize_array((void**)&offsets, &offset_capacity, MAX_ELEMENTS);
    initialize_records(&records, &record_count);

    serialize_records(records, record_count, "data.bin");
    deserialize_records(&records, &record_count, "data.bin");

    verify_data_integrity(records, record_count);

    free(offsets);
    free(records);

    return 0;
}
