const fs = require('fs').promises;
const path = require('path');

async function concatenateBinaryFiles(filePaths, maxSizeLimit) {
  let totalSize = 0;
  const buffers = [];

  for (let i = 0; i < filePaths.length; i++) {
    const filePath = filePaths[i];
    try {
      const fileStats = await fs.stat(filePath);
      if (totalSize + fileStats.size > maxSizeLimit) {
        throw new Error(`File size limit exceeded: ${maxSizeLimit} bytes`);
      }
      totalSize += fileStats.size;
      const buffer = await fs.readFile(filePath);
      buffers.push(buffer);
    } catch (error) {
      console.error(`Error reading file ${filePath}:`, error);
      throw error;
    }

    if ((i + 1) % Math.floor(filePaths.length / 10) === 0 || i === filePaths.length - 1) {
      const progress = Math.round(((i + 1) / filePaths.length) * 100);
      console.log(`Progress: ${progress}%`);
    }
  }

  return Buffer.concat(buffers);
}

// Example usage:
const filePaths = [
  'path/to/file1.bin',
  'path/to/file2.bin',
  // Add more file paths as needed
];
const maxSizeLimit = 10 * 1024 * 1024; // 10 MB

concatenateBinaryFiles(filePaths, maxSizeLimit)
  .then((resultBuffer) => {
    console.log('Concatenation complete. Buffer size:', resultBuffer.length);
  })
  .catch((error) => {
    console.error('Error during concatenation:', error);
  });
```

