['```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_RECORDS 1024

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int used[MAX_RECORDS];
    int nextFree;
} MemoryManager;

MemoryManager manager;

void init_memory_manager() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        manager.used[i] = 0;
    }
    manager.nextFree = 0;
}

Record* allocate_record(long *offset, int *key) {
    if (manager.nextFree >= MAX_RECORDS) {
        log_error("Memory allocation failed: Maximum records reached.");
        return NULL;
    }

    Record *record = &manager.records[manager.nextFree];
    record->value = 0; // Initialize value
    record->offset = offset;
    record->key = key;

    manager.used[manager.nextFree] = 1;
    manager.nextFree++;

    return record;
}

void free_record(Record *record) {
    int index = (record - manager.records);
    if (index < 0 || index >= MAX_RECORDS || !manager.used[index]) {
        log_error("Attempted to free an invalid or already freed record.");
        return;
    }

    manager.used[index] = 0;
}

void log_error(const char *message) {
    FILE *errorFile = fopen("error.log", "a");
    if (errorFile != NULL) {
        fprintf(errorFile, "%s\n", message);
        fclose(errorFile);
    } else {
        // Fallback to standard error if file opening fails
        fprintf(stderr, "%s\n", message);
    }
}

void release_all_memory() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (manager.used[i]) {
            free_record(&manager.records[i]);
        }
    }
}
