pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void update_ue_state(int ue_id, int signal_strength, int uplink_grants) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_active_states; i++) {
        if (ue_states[i].ue_id == ue_id) {
            ue_states[i].signal_strength = signal_strength;
            ue_states[i].uplink_grant_requests += uplink_grants;
            ue_states[i].last_activity = time(NULL);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    if (num_active_states < MAX_UE_STATES) {
        ue_states[num_active_states].ue_id = ue_id;
        ue_states[num_active_states].signal_strength = signal_strength;
        ue_states[num_active_states].uplink_grant_requests = uplink_grants;
        ue_states[num_active_states].last_activity = time(NULL);
        num_active_states++;
    }
    pthread_mutex_unlock(&mutex);
}

void evict_stale_entries() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_active_states; ) {
        if (time(NULL) - ue_states[i].last_activity > TIMEOUT_SECONDS) {
            for (int j = i; j < num_active_states - 1; j++) {
                ue_states[j] = ue_states[j + 1];
            }
            num_active_states--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&mutex);
}

