#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_crc_list(CRC_LIST_T *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

int validate_rnti(int rnti) {
    // Placeholder for RNTI validation logic
    return (rnti >= 1 && rnti <= 4095); // Example range
}

void add_crc_indication(CRC_LIST_T *list, int rx_tag, int rnti, int crc_flag) {
    pthread_mutex_lock(&list->lock);
    if (list->count < MAX_STRUCTURES && validate_rnti(rnti)) {
        list->data[list->count].RX_UE_INFORMATION_TAG = rx_tag;
        list->data[list->count].RNTI = rnti;
        list->data[list->count].CRC_INDICATION_REL8_TAG = crc_flag;
        list->count++;
    } else if (!validate_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI: %d\n", rnti);
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_crc_list(CRC_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    fclose(file);
}

void deserialize_crc_list(CRC_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    fseek(file, 0, SEEK_SET);
    list->count = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (list->count > MAX_STRUCTURES) {
        fprintf(stderr, "Too many structures in file\n");
        fclose(file);
        return;
    }
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size);
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

int main() {
    CRC_LIST_T crc_list;
    init_crc_list(&crc_list);

    srand(time(NULL));
    for (size_t i = 0; i < MAX_STRUCTURES; i++) {
        add_crc_indication(&crc_list, rand(), rand() % 4096, rand() % 2);
    }

    serialize_crc_list(&crc_list, "crc_data.bin");
    destroy_crc_list(&crc_list);

    return 0;
}
