NFAPI_CRC_INDICATION_PDU_T* create_doubly_linked_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->RX_UE_INFORMATION_TAG = rand() % 100;
        new_node->RNTI = rand() % 1000;
        new_node->CRC_INDICATION_REL8_TAG = rand() % 2;
        new_node->prev = tail;
        if (tail) {
            tail->next = new_node;
        } else {
            head = new_node;
        }
        tail = new_node;
    }
    return head;
}

void free_doubly_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
}

