using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class QueryOptimizer
{
    private readonly ConcurrentDictionary<string, object> _queryCache = new ConcurrentDictionary<string, object>();
    private int _totalStructuresCreated = 0;
    private const int MaxStructuresPerCall = 1000; // Example limit

    public List<IDataReader> ExecuteQueries(List<string> queries, SqlConnection connection, List<List<object>> parameters)
    {
        if (queries == null || connection == null || parameters == null)
            throw new ArgumentNullException("Input parameters cannot be null.");

        var results = new List<IDataReader>();

        foreach (var query in queries)
        {
            var key = query + string.Join(",", parameters[queries.IndexOf(query)]);
            if (!_queryCache.TryGetValue(key, out var cachedResult))
            {
                using (var command = new SqlCommand(query, connection))
                {
                    for (int i = 0; i < parameters[queries.IndexOf(query)].Count; i++)
                        command.Parameters.AddWithValue($"@p{i}", parameters[queries.IndexOf(query)][i]);

                    cachedResult = command.ExecuteReader(CommandBehavior.CloseConnection);
                    _queryCache.TryAdd(key, cachedResult);
                }
            }

            results.Add((IDataReader)cachedResult);
        }

        return results;
    }

    public void AllocateStructures(int N)
    {
        if (N <= 0 || N > MaxStructuresPerCall)
            throw new ArgumentOutOfRangeException("N must be a positive integer less than or equal to the maximum allowed structures per call.");

        lock (_queryCache)
        {
            if (_totalStructuresCreated + N > MaxStructuresPerCall)
                throw new InvalidOperationException("Memory allocation limit exceeded.");

            for (int i = 0; i < N; i++)
            {
                var structure = new NFAPI_CRC_INDICATION_PDU_T
                {
                    RX_UE_INFORMATION_TAG = GenerateRandomTag(),
                    RNTI = GenerateRandomRNTI(),
                    CRC_INDICATION_REL8_TAG = GenerateRandomCRCFLAG()
                };

                // Validate and handle memory allocation errors
                if (!IsValidCRCFLAG(structure.CRC_INDICATION_REL8_TAG))
                {
                    throw new InvalidOperationException("Invalid CRCFLAG value.");
                }

                _totalStructuresCreated++;
            }
        }
    }

    private static RX_UE_INFORMATION_TAG GenerateRandomTag()
    {
        // Implement logic to generate a random RX_UE_INFORMATION_TAG
        return (RX_UE_INFORMATION_TAG)Guid.NewGuid().GetHashCode();
    }

    private static RNTI GenerateRandomRNTI()
    {
        // Implement logic to generate a random RNTI
        return (RNTI)new Random().Next(1, int.MaxValue);
    }

    private static CRC_INDICATION_REL8_TAG GenerateRandomCRCFLAG()
    {
        // Implement logic to generate a random CRCFLAG within the valid range
        return (CRC_INDICATION_REL8_TAG)new Random().Next(0, 256);
    }

    private static bool IsValidCRCFLAG(CRC_INDICATION_REL8_TAG crcFlag)
    {
        // Implement logic to validate the CRCFLAG value
        return crcFlag >= 0 && crcFlag <= 255;
    }
}

public struct NFAPI_CRC_INDICATION_PDU_T
{
    public RX_UE_INFORMATION_TAG RX_UE_INFORMATION_TAG;
    public RNTI RNTI;
    public CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
}

public enum RX_UE_INFORMATION_TAG : int { /* Define your enum values */ }
public enum RNTI : int { /* Define your enum values */ }
public enum CRC_INDICATION_REL8_TAG : byte { /* Define your enum values */ }
