void initialize_arrays(int num_elements, long **offsets, int **keys, record **records) {
    *offsets = (long *)malloc(num_elements * sizeof(long));
    *keys = (int *)malloc(num_elements * sizeof(int));
    *records = (record *)malloc(num_elements * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < num_elements; i++) {
        (*records)[i].value = i;
        (*records)[i].offset = &(*offsets)[i];
        (*records)[i].key = &(*keys)[i];
    }
}

void free_arrays(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

