#define MAX_RECORDS 1000
#define MAX_KEY_LENGTH 256
#define MAX_BUFFER_SIZE 4096

typedef struct {
    int key;
    int offset;
    char buffer[MAX_BUFFER_SIZE];
} Record;

typedef struct {
    Record *records;
    int count;
    int capacity;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection *create_record_collection(int initial_capacity) {
    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    if (collection) {
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int add_record(RecordCollection *collection, int key, int offset, const char *buffer, size_t buffer_size) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        Record *new_records = (Record *)realloc(collection->records, collection->capacity * 2 * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->records = new_records;
        collection->capacity *= 2;
    }

    Record *record = &collection->records[collection->count++];
    record->key = key;
    record->offset = offset;
    strncpy(record->buffer, buffer, buffer_size);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

