#define MAX_FILES 1024
#define MAX_LOG_ENTRIES 512
#define MAX_PATH_LENGTH 256

typedef struct {
    float timestamp;
    char path[MAX_PATH_LENGTH];
} file_info;

typedef enum {
    INFO,
    WARNING,
    ERROR
} log_level;

typedef struct log_entry {
    char message[256];
    log_level level;
} log_entry;

typedef struct file_descriptor {
    int fd;
    pthread_t thread_id;
    struct file_descriptor *next;
} file_descriptor;

int process_directory(const char *path, float timestamps[], char paths[][MAX_PATH_LENGTH], file_info **file_list, log_entry logs[]) {
    DIR *dir = opendir(path);
    if (!dir) return -1; // Directory opening failed

    struct dirent *entry;
    int file_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char full_path[MAX_PATH_LENGTH];
        snprintf(full_path, MAX_PATH_LENGTH, "%s/%s", path, entry->d_name);

        struct stat file_stat;
        if (stat(full_path, &file_stat) != 0) {
            logs[file_count].level = ERROR;
            snprintf(logs[file_count].message, 256, "Failed to get stats for %s", full_path);
            file_count++;
            continue;
        }

        timestamps[file_count] = (float)file_stat.st_mtime;
        strncpy(paths[file_count], full_path, MAX_PATH_LENGTH);

        file_info *new_file = malloc(sizeof(file_info));
        new_file->timestamp = timestamps[file_count];
        strncpy(new_file->path, paths[file_count], MAX_PATH_LENGTH);
        new_file->next = *file_list;
        *file_list = new_file;

        // Asynchronous operation setup
        file_descriptor *fd = malloc(sizeof(file_descriptor));
        fd->fd = open(full_path, O_RDONLY | O_NONBLOCK);
        if (fd->fd == -1) {
            logs[file_count].level = ERROR;
            snprintf(logs[file_count].message, 256, "Failed to open %s", full_path);
            free(new_file);
            continue;
        }
        fd->next = NULL;

        // Start thread for file descriptor operation
        if (pthread_create(&fd->thread_id, NULL, file_operation_thread, fd) != 0) {
            logs[file_count].level = ERROR;
            snprintf(logs[file_count].message, 256, "Failed to create thread for %s", full_path);
            close(fd->fd);
            free(new_file);
            free(fd);
            continue;
        }

        file_count++;
    }

    closedir(dir);
    return file_count;
}

void *file_operation_thread(void *arg) {
    file_descriptor *fd = (file_descriptor *)arg;

    // Perform non-blocking I/O operations here
    // ...

    close(fd->fd);
    free(fd);

    pthread_exit(NULL);
}
