```php
<?php
session_start();

function authenticateUser($client, $username, $password) {
    try {
        $tokenResponse = $client->getAccessToken('password', [
            'username' => $username,
            'password' => $password,
            'scope' => 'openid profile email'
        ]);

        $_SESSION['access_token'] = $tokenResponse['access_token'];

        return true;
    } catch (Exception $e) {
        error_log("Authentication failed: " . $e->getMessage());
        return false;
    }
}

function getUserInfo($client, $accessToken) {
    try {
        $userInfo = $client->getAuthenticatedUserinfo($accessToken);
        return $userInfo;
    } catch (Exception $e) {
        error_log("Failed to retrieve user info: " . $e->getMessage());
        return [
            'name' => 'Guest',
            'email' => 'guest@example.com'
        ];
    }
}

function getUserDetails() {
    if (!isset($_SESSION['access_token'])) {
        return [
            'name' => 'Guest',
            'email' => 'guest@example.com'
        ];
    }

    $client = new OAuth2\Client([
        'clientId'     => 'your_client_id',
        'clientSecret' => 'your_client_secret',
        'redirectUri'  => 'http://example.com/callback'
    ]);

    return getUserInfo($client, $_SESSION['access_token']);
}
?>
