#include <libswscale/swscale.h>
#include <pthread.h>

typedef struct {
    AVFormatContext *fmt_ctx;
    int status_code;
} MediaProcessor;

MediaProcessor* create_media_processor(const char *file_path, int quality, int resolution) {
    MediaProcessor *processor = (MediaProcessor*)malloc(sizeof(MediaProcessor));
    processor->fmt_ctx = NULL;
    processor->status_code = 0;

    AVFormatContext *fmt_ctx = NULL;
    if (avformat_open_input(&fmt_ctx, file_path, NULL, NULL) != 0) {
        processor->status_code = -1;
        return processor;
    }

    if (avformat_find_stream_info(fmt_ctx, NULL) < 0) {
        avformat_close_input(&fmt_ctx);
        processor->status_code = -2;
        return processor;
    }

    AVCodecContext *codec_ctx = fmt_ctx->streams[0]->codec;
    AVCodec *codec = avcodec_find_decoder(codec_ctx->codec_id);
    if (!codec) {
        avformat_close_input(&fmt_ctx);
        processor->status_code = -3;
        return processor;
    }

    codec_ctx->codec = codec;
    if (avcodec_open2(codec_ctx, codec, NULL) < 0) {
        avformat_close_input(&fmt_ctx);
        processor->status_code = -4;
        return processor;
    }

    processor->fmt_ctx = fmt_ctx;
    return processor;
}

void destroy_media_processor(MediaProcessor *processor) {
    if (processor->fmt_ctx) {
        avformat_close_input(&processor->fmt_ctx);
    }
    free(processor);
}
