#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 10000

typedef struct PacketHeader {
    char src_ip[16];
    char dst_ip[16];
    int protocol;
    int payload_length;
} PacketHeader;

typedef struct Node {
    PacketHeader header;
    struct Node* next;
} Node;

typedef struct PacketList {
    Node* head;
    size_t count;
} PacketList;

void initPacketList(PacketList* list) {
    list->head = NULL;
    list->count = 0;
}

Node* createNode(const PacketHeader* header) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(&newNode->header, header, sizeof(PacketHeader));
    newNode->next = NULL;
    return newNode;
}

int insertPacket(PacketList* list, const PacketHeader* header) {
    Node* newNode = createNode(header);

    if (list->head == NULL || strcmp(newNode->header.src_ip, list->head->header.src_ip) < 0) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL && strcmp(current->next->header.src_ip, newNode->header.src_ip) <= 0) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    list->count++;
    return 1;
}

int removePacket(PacketList* list, const char* src_ip) {
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL && strcmp(current->header.src_ip, src_ip) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        return 0; // Packet not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->count--;
    return 1;
}

void printPacketList(const PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("Source IP: %s, Destination IP: %s, Protocol: %d, Payload Length: %d\n",
               current->header.src_ip, current->header.dst_ip,
               current->header.protocol, current->header.payload_length);
        current = current->next;
    }
}

void freePacketList(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int main() {
    srand(time(NULL));
    PacketList packetList;
    initPacketList(&packetList);

    // Example usage
    PacketHeader header1 = {"192.168.1.1", "10.0.0.1", 6, 1024};
    insertPacket(&packetList, &header1);

    PacketHeader header2 = {"10.0.0.1", "192.168.1.1", 6, 512};
    insertPacket(&packetList, &header2);

    printPacketList(&packetList);

    removePacket(&packetList, "192.168.1.1");

    printPacketList(&packetList);

    freePacketList(&packetList);

    return 0;
}
