#define MAX_RECORDS 1000

typedef struct {
    int value;
    long *offset;
    char status;
} record;

int manage_memory(int size, long **offsets, int **keys, record **records) {
    if (size <= 0 || size > MAX_RECORDS) {
        fprintf(stderr, "Invalid size: %d\n", size);
        return -1;
    }

    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (record *)malloc(size * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = i;

        (*records)[i].value = rand() % 201 - 100;
        if ((*records)[i].value > 0) {
            (*records)[i].status = 'A';
        } else if ((*records)[i].value < 0) {
            (*records)[i].status = 'N';
        } else {
            (*records)[i].status = 'Z';
        }

        (*records)[i].offset = &(*offsets)[i];
    }

    return 0;
}

void free_memory(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
