List* createList() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insertHeader(List* list, PacketHeader header) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    strcpy(newNode->header.sourceIP, header.sourceIP);
    strcpy(newNode->header.destinationIP, header.destinationIP);
    newNode->header.protocolType = header.protocolType;
    newNode->header.payloadLength = header.payloadLength;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void removeHeader(List* list, char* sourceIP, char* destinationIP) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->header.sourceIP, sourceIP) == 0 && strcmp(current->header.destinationIP, destinationIP) == 0) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void compressList(List* list) {
