import java.net.URL;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class URLDownloader {

    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static final String LOG_FILE_PATH = "download_log.txt";

    public void downloadUrls(List<String> urls) {
        for (String url : urls) {
            executor.submit(() -> {
                try {
                    if (!isValidUrl(url)) {
                        throw new InvalidUrlException("Invalid URL: " + url);
                    }
                    if (!isReachable(url)) {
                        throw new UnreachableUrlException("Unreachable URL: " + url);
                    }
                    downloadContent(url);
                } catch (IOException | InterruptedException e) {
                    handleException(e, url);
                }
            });
        }
    }

    private boolean isValidUrl(String url) {
        try {
            new URL(url).toURI();
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private boolean isReachable(String url) throws IOException, InterruptedException {
        HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
        connection.setConnectTimeout(30000);
        connection.setRequestMethod("HEAD");
        int responseCode = connection.getResponseCode();
        return responseCode == HttpURLConnection.HTTP_OK;
    }

    private void downloadContent(String url) throws IOException {
        // Implement streaming download logic here
    }

    private void handleException(Exception e, String url) {
        logError(e.getMessage(), url);
        // Handle exception gracefully, e.g., retry or notify monitoring system
    }

    private void logError(String message, String url) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(LOG_FILE_PATH, true))) {
            writer.write(message + " for URL: " + url + "\n");
        } catch (IOException ex) {
            // Log the error logging failure
        }
    }

    public static void main(String[] args) {
        List<String> urls = Arrays.asList("http://example.com", "http://invalidurl.com");
        new URLDownloader().downloadUrls(urls);
    }
}

class InvalidUrlException extends Exception {
    public InvalidUrlException(String message) {
        super(message);
    }
}

class UnreachableUrlException extends Exception {
    public UnreachableUrlException(String message) {
        super(message);
    }
}
