#include <stdlib.h>
#include <pthread.h>

typedef struct Item {
    int key;
    struct Item* next;
} Item;

typedef struct LinkedList {
    Item* head;
    pthread_mutex_t lock;
} LinkedList;

// Function to create a new item
Item* create_item(int key) {
    Item* item = (Item*)malloc(sizeof(Item));
    if (item == NULL) return NULL;
    item->key = key;
    item->next = NULL;
    return item;
}

// Function to insert an item at the end of the list
void insert_item(LinkedList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Item* new_item = create_item(key);
    if (new_item == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->head == NULL) {
        list->head = new_item;
    } else {
        Item* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_item;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to find an item by key
Item* find_item(LinkedList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Function to iterate over the list
void iterate_list(LinkedList* list, void (*callback)(Item*)) {
    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to free the entire list
void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current != NULL) {
        Item* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}
