#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N, int min_RX_UE_INFORMATION_TAG, int max_RX_UE_INFORMATION_TAG, int min_RNTI, int max_RNTI) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static NFAPI_CRC_INDICATION_PDU_T* array[MAX_ELEMENTS] = {NULL};
    static int count = 0;

    pthread_mutex_lock(&mutex);

    if (N > MAX_ELEMENTS - count) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Not enough space
    }

    for (int i = 0; i < N; i++) {
        array[count + i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[count + i]) {
            pthread_mutex_unlock(&mutex);
            return NULL; // Memory allocation failed
        }

        array[count + i]->RX_UE_INFORMATION_TAG = rand() % (max_RX_UE_INFORMATION_TAG - min_RX_UE_INFORMATION_TAG + 1) + min_RX_UE_INFORMATION_TAG;
        array[count + i]->RNTI = rand() % (max_RNTI - min_RNTI + 1) + min_RNTI;
        array[count + i]->CRC_INDICATION_REL8_TAG = rand() % 256; // Random value for demonstration
        array[count + i]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    count += N;

    pthread_mutex_unlock(&mutex);

    return array[count - N];
}

void free_array(NFAPI_CRC_INDICATION_PDU_T** array, int N) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int count = 0;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < N; i++) {
        if (array[count - N + i]) {
            free(array[count - N + i]);
            array[count - N + i] = NULL;
        }
    }

    count -= N;

    pthread_mutex_unlock(&mutex);
}
