#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h> // For SHA-256 hashing

#define MAX_RANDOM_STRING_LENGTH 100
#define PASSWORD_HASH_SIZE SHA256_DIGEST_LENGTH

typedef struct {
    RX_UE_INFORMATION_TAG ueInfoTag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
    char randomString[MAX_RANDOM_STRING_LENGTH];
    unsigned char passwordHash[PASSWORD_HASH_SIZE];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateNfapiPduList(int numElements, const char* charset, size_t charsetLength, const char* password) {
    if (numElements <= 0 || charset == NULL || password == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduList == NULL) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < numElements; ++i) {
        // Generate random RX_UE_INFORMATION_TAG and RNTI
        pduList[i].ueInfoTag = rand() % UINT32_MAX;
        pduList[i].rnti = rand() % UINT16_MAX;

        // Set a random CRCFLAG
        pduList[i].crcIndication.CRCFLAG = (rand() % 2) == 0 ? 0 : 1;

        // Generate a random string from the given character set
        size_t randomStringLength = rand() % MAX_RANDOM_STRING_LENGTH;
        for (size_t j = 0; j < randomStringLength; ++j) {
            pduList[i].randomString[j] = charset[rand() % charsetLength];
        }
        pduList[i].randomString[randomStringLength] = '\0';

        // Hash the provided password using SHA-256
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, password, strlen(password));
        SHA256_Final(pduList[i].passwordHash, &sha256);
    }

    return pduList;
}

// Example usage:
int main() {
    const char* charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    NFAPI_CRC_INDICATION_PDU_T* pdus = generateNfapiPduList(10, charset, strlen(charset), "mySecretPassword");
    if (pdus != NULL) {
        // Process the generated PDUs
        free(pdus); // Don't forget to free the allocated memory
    }
    return 0;
}
```

