using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;

public class JsonMetricsExtractor
{
    private readonly ConcurrentDictionary<string, Func<JToken, JToken>> _extractors = new ConcurrentDictionary<string, Func<JToken, JToken>>();

    public void RegisterJsonPath(string jsonPath, Func<JToken, JToken> extractor)
    {
        _extractors[jsonPath] = extractor;
    }

    public JToken ExtractMetric(string jsonPath, JObject userActivityLog)
    {
        if (!_extractors.TryGetValue(jsonPath, out var extractor))
            throw new ArgumentException("No extractor registered for the provided JSON path.");

        try
        {
            var result = extractor(userActivityLog);
            if (result == null)
                throw new InvalidOperationException("No matching metric found.");
            return result;
        }
        catch (Exception ex)
        {
            throw new JsonProcessingException($"Error processing JSON: {ex.Message}", ex);
        }
    }

    public void ProcessJsonFile(string filePath, string jsonPath)
    {
        using (var reader = new StreamReader(filePath))
        using (var jsonReader = new JsonTextReader(reader))
        {
            var serializer = new JsonSerializer();
            while (jsonReader.Read())
            {
                if (jsonReader.TokenType == JsonToken.StartObject)
                {
                    JObject userActivityLog = serializer.Deserialize<JObject>(jsonReader);
                    try
                    {
                        JToken metric = ExtractMetric(jsonPath, userActivityLog);
                        // Process the extracted metric for reporting
                    }
                    catch (JsonProcessingException ex)
                    {
                        // Log or handle the error gracefully
                    }
                }
            }
        }
    }

    public class JsonProcessingException : Exception
    {
        public JsonProcessingException(string message, Exception innerException) : base(message, innerException) { }
    }
}
