#include <string.h>

typedef struct Node {
    int key;
    struct Node* next;
} Node;

Node* createNode(int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->key = key;
    newNode->next = NULL;
    return newNode;
}

void insertAtEnd(Node** head, int key) {
    Node* newNode = createNode(key);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

Node* findNode(Node* head, int key) {
    Node* current = head;
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void freeList(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

// Additional code for managing file extensions
char* changeFileExtension(const char* filename, const char* newExtension) {
    size_t len = strlen(filename);
    if (len > 0 && filename[len - 1] == '.') {
        // Replace existing extension
        return strndup(filename, len - 1);
    } else {
        // Append new extension
        char* newFilename = (char*)malloc(len + strlen(newExtension) + 2);
        if (newFilename == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        snprintf(newFilename, len + strlen(newExtension) + 2, "%s.%s", filename, newExtension);
        return newFilename;
    }
}

int main() {
    Node* head = NULL;

    insertAtEnd(&head, 10);
    insertAtEnd(&head, 20);
    insertAtEnd(&head, 30);

    Node* foundNode = findNode(head, 20);
    if (foundNode != NULL) {
        printf("Found node with key: %d\n", foundNode->key);
    } else {
        printf("Node not found\n");
    }

    freeList(&head);

    // Example of changing file extension
    const char* filename = "example.txt";
    const char* newExtension = "csv";
    char* newFilename = changeFileExtension(filename, newExtension);
    if (newFilename != NULL) {
        printf("New filename: %s\n", newFilename);
        free(newFilename);
    }

    return 0;
}
