        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = MAX_STRUCTURES;
    list->last_gc_time = time(NULL);
    return list;
}

void destroy_crc_list(CRC_LIST_T *list) {
    free(list->data);
    free(list);
}

int add_crc_indication(CRC_LIST_T *list, const char *tag, int rnti, int crcflag) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1;
        list->data = new_data;
        list->capacity = new_capacity;
    }
    strcpy(list->data[list->size].tag, tag);
    list->data[list->size].rnti = rnti;
    list->data[list->size].crcflag = crcflag;
    list->size++;
    return 0;
}

void log_memory_usage(CRC_LIST_T *list) {
    printf("Memory used: %zu bytes\n", list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int main() {
    CRC_LIST_T *list = create_crc_list();
    if (!list) {
        fprintf(stderr, "Failed to create CRC list\n");
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        char tag[MAX_TAG_LENGTH];
        snprintf(tag, sizeof(tag), "tag_%d", i);
        int rnti = rand() % (MAX_RNTI + 1);
        int crcflag = rand() % (MAX_CRCFLAG + 1);
        if (add_crc_indication(list, tag, rnti, crcflag) != 0) {
            fprintf(stderr, "Failed to add CRC indication\n");
            destroy_crc_list(list);
            return 1;
        }
    }

    log_memory_usage(list);

    destroy_crc_list(list);
    return 0;
}
