void initializePlotElement(PlotElement* element, const char* identifier, float value, int x, int y) {
    element->identifier = strdup(identifier);
    if (element->identifier == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
