#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STREAMS 1000000

typedef struct PacketHeader {
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    int payload_size;
    time_t timestamp;
} PacketHeader;

typedef struct StreamNode {
    PacketHeader header;
    struct StreamNode* next;
} StreamNode;

StreamNode* stream_list = NULL;
int stream_count = 0;

void init_stream_manager() {
    srand(time(NULL));
}

PacketHeader generate_random_header() {
    PacketHeader header;
    snprintf(header.source_ip, sizeof(header.source_ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    snprintf(header.destination_ip, sizeof(header.destination_ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    header.protocol_type = rand() % 10;
    header.payload_size = rand() % 1000;
    header.timestamp = time(NULL);
    return header;
}

int insert_stream(PacketHeader header) {
    if (stream_count >= MAX_STREAMS) {
        return -1; // List is full
    }
    StreamNode* new_node = (StreamNode*)malloc(sizeof(StreamNode));
    if (!new_node) {
        return -2; // Memory allocation failed
    }
    memcpy(&new_node->header, &header, sizeof(PacketHeader));
    new_node->next = stream_list;
    stream_list = new_node;
    stream_count++;
    return 0;
}

int remove_stream_by_ip(const char* source_ip, const char* destination_ip) {
    StreamNode* current = stream_list;
    StreamNode* prev = NULL;
    while (current != NULL) {
        if (strcmp(current->header.source_ip, source_ip) == 0 && strcmp(current->header.destination_ip, destination_ip) == 0) {
            if (prev == NULL) {
                stream_list = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            stream_count--;
            return 0;
        }
        prev = current;
        current = current->next;
    }
    return -1; // Stream not found
}

StreamNode* find_stream_by_ip(const char* source_ip, const char* destination_ip) {
    StreamNode* current = stream_list;
    while (current != NULL) {
        if (strcmp(current->header.source_ip, source_ip) == 0 && strcmp(current->header.destination_ip, destination_ip) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL; // Stream not found
}

void free_stream_manager() {
    while (stream_list != NULL) {
        StreamNode* temp = stream_list;
        stream_list = stream_list->next;
        free(temp);
    }
}
