<?php
// Define the PHP function to handle user requests
function handleUserRequest() {
    $request = $_REQUEST;
    $response = array('status' => 'error', 'message' => '');

    if (!isset($request['name']) || !isset($request['email']) || !isset($request['password'])) {
        $response['message'] = 'Missing required fields';
        echo json_encode($response);
        return;
    }

    if (isset($request['id'])) {
        // Update user account
        if ($request['sub_action'] == 'delete') {
            if (deleteUser($request['id'])) {
                $response['status'] = 'success';
                $response['message'] = 'User deleted successfully';
            } else {
                $response['message'] = 'Failed to delete user';
            }
        } else {
            if (updateUser($request['id'], $request)) {
                $response['status'] = 'success';
                $response['message'] = 'User updated successfully';
            } else {
                $response['message'] = 'Failed to update user';
            }
        }
    } else {
        // Create new user account
        if (createUser($request)) {
            $response['status'] = 'success';
            $response['message'] = 'User created successfully';
        } else {
            $response['message'] = 'Failed to create user';
        }
    }

    echo json_encode($response);
}

// Function to interact with the external API for saving user data
function Save($data) {
    $url = "https://external-api.com/save";
    $options = array(
        'http' => array(
            'header'  => "Content-type: application/json\r\n",
            'method'  => 'POST',
            'content' => json_encode($data),
        ),
    );
    $context  = stream_context_create($options);
    $result = file_get_contents($url, false, $context);

    if ($result === FALSE) {
        // Handle API timeout or rate limiting
        return false;
    }

    return true;
}

// Function to interact with the external API for fetching user data
function Get($id) {
    $url = "https://external-api.com/get?id=" . urlencode($id);
    $options = array(
        'http' => array(
            'method'  => 'GET',
        ),
    );
    $context  = stream_context_create($options);
    $result = file_get_contents($url, false, $context);

    if ($result === FALSE) {
        // Handle API timeout or rate limiting
        return null;
    }

    return json_decode($result, true);
}

// Function to create a new user account
function createUser($data) {
    $user = array(
        'name' => $data['name'],
        'email' => $data['email'],
        'password' => password_hash($data['password'], PASSWORD_DEFAULT),
    );

    return Save($user);
}

// Function to update an existing user account
function updateUser($id, $data) {
    $user = Get($id);

    if ($user === null) {
        return false;
    }

    $user['name'] = $data['name'];
    $user['email'] = $data['email'];
    $user['password'] = password_hash($data['password'], PASSWORD_DEFAULT);

    return Save($user);
}

// Function to delete a user account
function deleteUser($id) {
    $user = Get($id);

    if ($user === null) {
        return false;
    }

    // Simulate deletion by setting an 'active' flag to false
    $user['active'] = false;

    return Save($user);
}

// Call the function to handle user requests
handleUserRequest();
