#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* dynamic_list_create() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = MAX_ELEMENTS;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->elements);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->size++] = element;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_list_filter_by_rnti(DynamicList *list, uint16_t min_rnti, uint16_t max_rnti) {
    NFAPI_CRC_INDICATION_PDU_T *filtered_elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!filtered_elements) return NULL;

    size_t filtered_size = 0;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].rnti >= min_rnti && list->elements[i].rnti <= max_rnti) {
            filtered_elements[filtered_size++] = list->elements[i];
        }
    }
    pthread_mutex_unlock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *result = (NFAPI_CRC_INDICATION_PDU_T*)realloc(filtered_elements, filtered_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        free(filtered_elements);
        return NULL; // Memory allocation failed
    }

    return result;
}
