public class PageUpdateHandler
{
    private readonly ISectionService _sectionService;
    private readonly ConcurrentDictionary<string, object> _cacheLocks = new ConcurrentDictionary<string, object>();
    private readonly MemoryCache _memoryCache;

    public PageUpdateHandler(ISectionService sectionService, MemoryCache memoryCache)
    {
        _sectionService = sectionService;
        _memoryCache = memoryCache;
    }

    [HttpPost]
    public async Task<IActionResult> UpdatePage(int userId, string sessionToken, int targetSectionId, string updatedHtmlContent)
    {
        if (!IsValidSessionToken(sessionToken))
        {
            return Unauthorized();
        }

        if (!HasPermission(userId, targetSectionId))
        {
            return Forbid();
        }

        var cacheKey = $"section_{targetSectionId}";
        object lockObject = _cacheLocks.GetOrAdd(cacheKey, k => new object());

        lock (lockObject)
        {
            if (_memoryCache.Contains(cacheKey))
            {
                // Handle potential race conditions by checking the cache before updating
                var cachedContent = _memoryCache.Get<string>(cacheKey);
                if (cachedContent == updatedHtmlContent)
                {
                    return Ok(new { RefreshPage = false });
                }
            }

            await _sectionService.UpdateSection(targetSectionId, updatedHtmlContent);

            // Update the cache with the new content
            _memoryCache.Set(cacheKey, updatedHtmlContent, DateTimeOffset.UtcNow.AddMinutes(10));
        }

        return Ok(new { RefreshPage = true });
    }

    private bool IsValidSessionToken(string sessionToken)
    {
        // Implement token validation logic here
        return true;
    }

    private bool HasPermission(int userId, int targetSectionId)
    {
        // Implement permission check logic here
        return true;
    }
}

public interface ISectionService
{
    Task UpdateSection(int sectionId, string updatedHtmlContent);
