    size_t length;
    size_t capacity;
} MessagePayload;

typedef struct {
    ClientIdentifier client;
    Timestamp ts;
    MessagePayload payload;
} NetworkMessage;

NetworkMessage* allocate_network_messages(size_t count, size_t max_payload_size) {
    NetworkMessage* messages = (NetworkMessage*)malloc(count * sizeof(NetworkMessage));
    if (!messages) {
        // Log error
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        // Populate ClientIdentifier and Timestamp
        snprintf(messages[i].client.identifier, sizeof(messages[i].client.identifier), "Client%d", i);
        messages[i].ts.timestamp = time(NULL);

        // Initialize MessagePayload with variable length content
        messages[i].payload.content = (char*)malloc(max_payload_size);
        if (!messages[i].payload.content) {
            // Log error and free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(messages[j].payload.content);
            }
            free(messages);
            return NULL;
        }
        messages[i].payload.length = 0;
        messages[i].payload.capacity = max_payload_size;

        // Simulate fetching data from external source
        size_t data_length = rand() % max_payload_size;
        memcpy(messages[i].payload.content, "SampleData", data_length);
        messages[i].payload.length = data_length;
    }

    return messages;
}

void free_network_messages(NetworkMessage* messages, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(messages[i].payload.content);
    }
    free(messages);
}
