#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t list_lock;
} LinkedList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) return NULL;
    node->data = data;
    node->next = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->list_lock);
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->list_lock);
        return;
    }
    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->list_lock);
}

void delete_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->list_lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->list_lock);
    pthread_mutex_destroy(&list->list_lock);
}

void destroy_node(Node* node) {
    if (node != NULL) {
        free(node);
    }
}
