#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 1000000
#define MAX_METADATA_SIZE 1024
#define CACHE_SIZE 100

typedef struct {
    long offset;
    int key;
    char metadata[MAX_METADATA_SIZE];
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} Database;

typedef struct {
    Record cache[CACHE_SIZE];
    int hit_count;
    int miss_count;
    pthread_mutex_t lock;
} Cache;

Database db;
Cache cache;

void init_database() {
    memset(&db, 0, sizeof(db));
    pthread_mutex_init(&db.lock, NULL);
}

void init_cache() {
    memset(&cache, 0, sizeof(cache));
    pthread_mutex_init(&cache.lock, NULL);
}

int load_data_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    int count;
    fscanf(file, "%d", &count);
    if (count > MAX_RECORDS) {
        fclose(file);
        return -2;
    }

    pthread_mutex_lock(&db.lock);
    for (int i = 0; i < count; ++i) {
        Record record;
        fscanf(file, "%ld %d %s", &record.offset, &record.key, record.metadata);
        db.records[i] = record;
    }
    db.count = count;
    pthread_mutex_unlock(&db.lock);

    fclose(file);
    return 0;
}

void* access_record(void* arg) {
    int key = *(int*)arg;
    Record result;

    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < cache.hit_count; ++i) {
        if (cache.cache[i].key == key) {
            result = cache.cache[i];
            cache.hit_count++;
            pthread_mutex_unlock(&cache.lock);
            return &result;
        }
    }
    pthread_mutex_unlock(&cache.lock);

    pthread_mutex_lock(&db.lock);
    for (int i = 0; i < db.count; ++i) {
        if (db.records[i].key == key) {
            result = db.records[i];
            pthread_mutex_unlock(&db.lock);

            pthread_mutex_lock(&cache.lock);
            if (cache.hit_count < CACHE_SIZE) {
                cache.cache[cache.hit_count++] = result;
            } else {
                // Evict least recently used record
                memmove(cache.cache, &cache.cache[1], sizeof(Record) * (CACHE_SIZE - 1));
                cache.cache[CACHE_SIZE - 1] = result;
            }
            pthread_mutex_unlock(&cache.lock);
            return &result;
        }
    }
    pthread_mutex_unlock(&db.lock);

    return NULL; // Record not found
}

int main() {
    init_database();
    init_cache();

    if (load_data_from_file("data.txt") != 0) {
        printf("Failed to load data from file.\n");
        return -1;
    }

    int keys[] = {1, 2, 3, 4, 5};
    for (int i = 0; i < sizeof(keys) / sizeof(keys[0]); ++i) {
        Record* record = (Record*)access_record(&keys[i]);
        if (record) {
            printf("Key %d found at offset %ld with metadata: %s\n", keys[i], record->offset, record->metadata);
        } else {
            printf("Key %d not found.\n", keys[i]);
        }
    }

    return 0;
}
