#define MAX_NFAPIS 1024
#define MAX_CRC_INDICATIONS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *nfapis[MAX_NFAPIS];
    int count;
    pthread_mutex_t lock;
} NFAPICRCManager;

NFAPICRCManager crc_manager = {0};

void initialize_crc_manager() {
    pthread_mutex_init(&crc_manager.lock, NULL);
}

int hash_function(int tag) {
    return tag % MAX_NFAPIS;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *nfaapi = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaapi) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    nfaapi->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    nfaapi->RNTI = RNTI;
    nfaapi->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    nfaapi->CRCFLAG = CRCFLAG;
    return nfaapi;
}

void add_nfaapi(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&crc_manager.lock);
    if (crc_manager.count >= MAX_NFAPIS) {
        fprintf(stderr, "Maximum number of NFAPIS reached\n");
        pthread_mutex_unlock(&crc_manager.lock);
        return;
    }
    int index = hash_function(RX_UE_INFORMATION_TAG);
    while (crc_manager.nfapis[index] != NULL) {
        index = (index + 1) % MAX_NFAPIS;
    }
    crc_manager.nfapis[index] = create_nfaapi(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG);
    crc_manager.count++;
    pthread_mutex_unlock(&crc_manager.lock);
}

void* manage_crc_indications(void *arg) {
    // Simulate processing of CRC indications
    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        add_nfaapi(i, i * 10, i * 100, rand() % 2);
        usleep(100); // Simulate time taken to process each indication
    }
    return NULL;
}

int main() {
    initialize_crc_manager();
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, manage_crc_indications, NULL);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
