#include <time.h>

#define MAX_UE_ID 65535
#define MAX_CRC_INDICATIONS 1000

typedef struct {
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int max_indications, int *num_indications) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static NFAPI_CRC_INDICATION_PDU_T pool[MAX_UE_ID];
    static int pool_index = 0;

    pthread_mutex_lock(&mutex);

    if (pool_index >= MAX_UE_ID) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Pool exhausted
    }

    *num_indications = 0;
    for (int i = 0; i < max_indications && pool_index < MAX_UE_ID; ++i) {
        uint16_t rnti = rand() % (MAX_UE_ID + 1);
        while (pool_index > 0 && pool[pool_index - 1].RNTI == rnti) {
            rnti = rand() % (MAX_UE_ID + 1); // Ensure uniqueness
        }
        pool[pool_index].RNTI = rnti;
        pool[pool_index].CRCFLAG = rand() % 2; // Random CRCFLAG
        ++pool_index;
        (*num_indications)++;
    }

    pthread_mutex_unlock(&mutex);
    return &pool[0];
}
