#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    char mac_address[18];
    char ip_config[16];
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts;
    size_t count;
    pthread_mutex_t lock;
} LTE_UE_List;

LTE_UE_List* create_lte_ue_list(size_t initial_size) {
    LTE_UE_List *list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    list->contexts = (LTE_UE_Context*)calloc(initial_size, sizeof(LTE_UE_Context));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_lte_ue_list(LTE_UE_List *list) {
    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_lte_ue_context(LTE_UE_List *list, int ue_id, const char *mac_address, const char *ip_config) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->initial_size) {
        // Resize the list
        LTE_UE_Context *new_contexts = (LTE_UE_Context*)realloc(list->contexts, list->initial_size * 2 * sizeof(LTE_UE_Context));
        if (!new_contexts) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->contexts = new_contexts;
        list->initial_size *= 2;
    }
    list->contexts[list->count].ue_id = ue_id;
    snprintf(list->contexts[list->count].mac_address, sizeof(list->contexts[list->count].mac_address), "%s", mac_address);
    snprintf(list->contexts[list->count].ip_config, sizeof(list->contexts[list->count].ip_config), "%s", ip_config);
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_lte_ue_context(LTE_UE_List *list, int ue_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        if (list->contexts[i].ue_id == ue_id) {
            // Shift elements to fill the gap
            memmove(&list->contexts[i], &list->contexts[i + 1], (list->count - i - 1) * sizeof(LTE_UE_Context));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // UE ID not found
}
