import requests
from time import sleep

class LTE_NMS_API:
    def __init__(self, base_url):
        self.base_url = base_url

    def provision_network_resource(self, ue_id, mac_address, ip_config):
        url = f"{self.base_url}/provision"
        payload = {
            "ue_id": ue_id,
            "mac_address": mac_address,
            "ip_config": ip_config
        }
        response = requests.post(url, json=payload)
        if response.status_code != 200:
            self.handle_api_error(response)

    def deprovision_network_resource(self, ue_id):
        url = f"{self.base_url}/deprovision/{ue_id}"
        response = requests.delete(url)
        if response.status_code != 204:
            self.handle_api_error(response)

    def handle_api_error(self, response):
        print(f"API Error: {response.status_code} - {response.text}")
        sleep(1)  # Retry after a short delay
        self.retry_api_call(response.request.method, response.request.url, response.request.body)

    def retry_api_call(self, method, url, body):
        for _ in range(3):  # Maximum of 3 retries
            if method == "POST":
                response = requests.post(url, json=body)
            elif method == "DELETE":
                response = requests.delete(url)
            else:
                raise ValueError("Unsupported HTTP method")
            if response.status_code == 200 or response.status_code == 204:
                break
            sleep(1)  # Wait before retrying

# Usage example
api = LTE_NMS_API("http://nms.example.com/api")
api.provision_network_resource(1, "00:1A:2B:3C:4D:5E", "192.168.1.100/24")
api.deprovision_network_resource(1)
