#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000

typedef struct {
    int value;
} record;

long *offsets;
int *keys;
record *records;
int N = 0;
int L = 0;
int adjustment_count = 0;
pthread_mutex_t lock;

void initialize_resources(int n, int limit) {
    N = n;
    L = limit;
    offsets = (long *)malloc(N * sizeof(long));
    keys = (int *)malloc(N * sizeof(int));
    records = (record *)malloc(N * sizeof(record));

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 1000;
        records[i].value = rand() % 1001;
    }
}

void adjust_values() {
    int current_sum = 0;
    for (int i = 0; i < N; i++) {
        current_sum += records[i].value;
    }

    if (current_sum > L) {
        pthread_mutex_lock(&lock);
        int excess = current_sum - L;
        int adjustment = excess / N;
        for (int i = 0; i < N; i++) {
            records[i].value -= adjustment;
            if (records[i].value < 0) {
                records[i].value = 0;
            }
        }
        pthread_mutex_unlock(&lock);
        adjustment_count++;
    }
}

void update_limit(int new_limit) {
    L = new_limit;
    adjust_values();
}

void *worker_thread(void *arg) {
    int thread_id = *(int *)arg;
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        records[i].value += rand() % 1001;
        if (records[i].value > 1000) {
            records[i].value = 1000;
        }
        pthread_mutex_unlock(&lock);
        adjust_values();
    }
    return NULL;
}

int main() {
    initialize_resources(1000, 500000);

    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Adjustment count: %d\n", adjustment_count);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```

