#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkSession {
    int sessionId;
    time_t connectionTime;
    int refCount;
    time_t expirationTime;
    struct NetworkSession *next;
} NetworkSession;

NetworkSession *head = NULL;
pthread_mutex_t sessionMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t sessionCond = PTHREAD_COND_INITIALIZER;
int shutdownFlag = 0;

void* manageSessions(void* arg) {
    while (1) {
        pthread_mutex_lock(&sessionMutex);
        while (!shutdownFlag && head == NULL) {
            pthread_cond_wait(&sessionCond, &sessionMutex);
        }
        if (shutdownFlag) break;

        NetworkSession *current = head;
        NetworkSession *prev = NULL;
        time_t now = time(NULL);

        while (current != NULL) {
            if ((current->refCount == 0 && current->expirationTime <= now) || current->expirationTime <= now) {
                if (prev == NULL) {
                    head = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current);
                current = prev ? prev->next : head;
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&sessionMutex);
    }
    return NULL;
}

void addSession(int sessionId, time_t connectionTime, int refCount, time_t expirationTime) {
    NetworkSession *newSession = (NetworkSession*)malloc(sizeof(NetworkSession));
    newSession->sessionId = sessionId;
    newSession->connectionTime = connectionTime;
    newSession->refCount = refCount;
    newSession->expirationTime = expirationTime;
    newSession->next = NULL;

    pthread_mutex_lock(&sessionMutex);
    if (head == NULL) {
        head = newSession;
    } else {
        NetworkSession *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newSession;
    }
    pthread_cond_signal(&sessionCond);
    pthread_mutex_unlock(&sessionMutex);
}

void updateRefCount(int sessionId, int increment) {
    pthread_mutex_lock(&sessionMutex);
    NetworkSession *current = head;
    while (current != NULL) {
        if (current->sessionId == sessionId) {
            current->refCount += increment;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&sessionMutex);
}

void closeSession(int sessionId) {
    pthread_mutex_lock(&sessionMutex);
    NetworkSession *current = head;
    NetworkSession *prev = NULL;
    while (current != NULL) {
        if (current->sessionId == sessionId) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_cond_signal(&sessionCond);
    pthread_mutex_unlock(&sessionMutex);
}

int main() {
    pthread_t sessionThread;
    pthread_create(&sessionThread, NULL, manageSessions, NULL);

    // Example usage
    addSession(1, time(NULL), 1, time(NULL) + 3600);
    updateRefCount(1, 1);
    closeSession(1);

    pthread_join(sessionThread, NULL);
    return 0;
}
