#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

int init_crc_array(NFAPI_CRC_ARRAY *crc_array, size_t N) {
    crc_array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array->array) {
        return -1; // Memory allocation failed
    }
    crc_array->size = N;
    pthread_mutex_init(&crc_array->mutex, NULL);
    for (size_t i = 0; i < N; ++i) {
        crc_array->array[i].RX_UE_INFORMATION_TAG = i;
        crc_array->array[i].RNTI = rand() % 1024; // Random RNTI
        crc_array->array[i].CRC_INDICATION_REL8_TAG = i;
        crc_array->array[i].CRCFLAG = rand() % 2; // Random CRCFLAG
    }
    return 0;
}

void update_crc_flag(NFAPI_CRC_ARRAY *crc_array, size_t index) {
    pthread_mutex_lock(&crc_array->mutex);
    if (index < crc_array->size) {
        crc_array->array[index].CRCFLAG = rand() % 2; // Update CRCFLAG
    }
    pthread_mutex_unlock(&crc_array->mutex);
}

void log_crc_updates(NFAPI_CRC_ARRAY *crc_array, size_t interval_ms) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000 >= interval_ms) {
            for (size_t i = 0; i < crc_array->size; ++i) {
                printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                       crc_array->array[i].RX_UE_INFORMATION_TAG,
                       crc_array->array[i].RNTI,
                       crc_array->array[i].CRC_INDICATION_REL8_TAG,
                       crc_array->array[i].CRCFLAG);
            }
            clock_gettime(CLOCK_MONOTONIC, &start);
        }
    }
}

void destroy_crc_array(NFAPI_CRC_ARRAY *crc_array) {
    pthread_mutex_destroy(&crc_array->mutex);
