typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) {
        log_error("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        log_error("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int validate_and_add(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!is_crc_flag_valid(data.crc_indication.CRCFLAG)) {
        log_error("Invalid CRC flag: %d", data.crc_indication.CRCFLAG);
        return -1;
    }
    return add_to_list(list, data);
}
