#define MAX_SIZE 1000

typedef struct {
    long offset;
    int key;
    bool crc_flag;
} Record;

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

unsigned long custom_hash(int key, int unique_id) {
    // Implement a hash function that minimizes collisions and ensures uniform distribution
    return (unsigned long)(key * unique_id) % MAX_SIZE;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu_list(int N, Record** records, int* record_count) {
    if (N > MAX_SIZE) {
        fprintf(stderr, "Error: Size exceeds maximum limit.\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = malloc(N * sizeof(long));
    int* keys = malloc(N * sizeof(int));
    bool* crc_flags = malloc(N * sizeof(bool));

    if (!offsets || !keys || !crc_flags) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(crc_flags);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < N; i++) {
        offsets[i] = rand();
        keys[i] = rand() % MAX_SIZE;
        crc_flags[i] = (rand() % 2) == 0;

        Record* record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(crc_flags);
            free(pdu_list);
            exit(EXIT_FAILURE);
        }

        record->offset = offsets[i];
        record->key = keys[i];
        record->crc_flag = crc_flags[i];

        records[i] = record;
        *record_count += 1;

        pdu_list[i].rx_tag = RX_UE_INFORMATION_TAG(rand());
        pdu_list[i].rnti = RNTI(rand());
        pdu_list[i].crc_indication.crcflag = (rand() % 2) == 0;
    }

    free(offsets);
    free(keys);
    free(crc_flags);

    return pdu_list;
}

int main() {
    srand(time(NULL));

    Record* records[MAX_SIZE];
    int record_count = 0;

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_and_populate_pdu_list(10, records, &record_count);

    // Use the pdu_list and records as needed

    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(pdu_list);

    return 0;
}
