        snprintf(records[i].data, sizeof(records[i].data), "Record %d", i);
        records[i].value = i * 10;
        records[i].precision = i * 0.5;
    }

    // Simulate external process
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        printf("Child process created\n");
        sleep(2);
        exit(EXIT_SUCCESS);
    } else {
        // Parent process
        int status;
        wait(&status);
        if (WIFEXITED(status)) {
            printf("Child process exited with status %d\n", WEXITSTATUS(status));
        }
    }

    free_records(records, num_records);

    return 0;
}
