    CRCArray* array = (CRCArray*)malloc(sizeof(CRCArray));
    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_size;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_crc_array(CRCArray* array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array->data);
        free(array);
    }
}

int resize_crc_array(CRCArray* array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->data = new_data;
    array->capacity = new_capacity;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void update_crc_flag(CRCArray* array, size_t index, int new_crcflag) {
    pthread_mutex_lock(&array->lock);

    if (index < array->size) {
        array->data[index].CRCFLAG = new_crcflag;
    }

    pthread_mutex_unlock(&array->lock);
}

int iterate_and_update_crc(CRCArray* array, void (*update_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        update_func(&array->data[i]);
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}
