typedef struct LinkedList {
    Item* head;
    pthread_mutex_t lock;
} LinkedList;

Item* create_item(const char* key, double value) {
    Item* item = (Item*)malloc(sizeof(Item));
    if (item == NULL) {
        perror("Failed to allocate memory for item");
        return NULL;
    }
    strncpy(item->key, key, MAX_KEY_LENGTH);
    item->timestamp = time(NULL) + rand() % 1000; // Adjust timestamp with a random offset
    item->value = value;
    item->next = NULL;
    return item;
}

void insert_item(LinkedList* list, Item* item) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = item;
    } else {
        Item* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = item;
    }
    pthread_mutex_unlock(&list->lock);
}

Item* find_item(LinkedList* list, const char* key) {
    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void iterate_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current != NULL) {
        printf("Key: %s, Timestamp: %ld, Value: %f\n", current->key, current->timestamp, current->value);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

