        entries[i].timestamp = time(NULL);
        entries[i].value = ((double)rand() / RAND_MAX) * 100.0; // Random double between 0 and 100
    }
}

void free_entry_array(entry* entries, int size) {
    for (int i = 0; i < size; i++) {
        free(entries[i].key);
    }
}
