    FILE *file = fopen(filePath, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize > bufferLimit) {
        fclose(file);
        return NULL;
    }

    char *buffer = malloc(fileSize + 1);
    fread(buffer, 1, fileSize, file);
    fclose(file);
    buffer[fileSize] = '\0';

    time_t lastModified = get_last_modified_time(filePath);

    // Parse JSON and extract valid audio metadata
    // ...

    free(buffer);
    return formatLastModified(lastModified);
}

time_t get_last_modified_time(const char *filePath) {
    struct stat fileStat;
    if (stat(filePath, &fileStat) == 0) {
        return fileStat.st_mtime;
    }
    return -1;
}

char* formatLastModified(time_t lastModified) {
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&lastModified));
    return strdup(buffer);
}
