typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct LogEntry {
    LogLevel level;
    time_t timestamp;
    int id;
    size_t message_length;
    char *message;
    struct LogEntry *next;
} LogEntry;

typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
} LogList;

void init_log_list(LogList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_log_list(LogList *list) {
    LogEntry *entry = list->head;
    while (entry != NULL) {
        LogEntry *next = entry->next;
        free(entry->message);
        free(entry);
        entry = next;
    }
    pthread_mutex_destroy(&list->lock);
}

void add_log_entry(LogList *list, LogLevel level, time_t timestamp, int id, const char *message) {
    pthread_mutex_lock(&list->lock);
    LogEntry *new_entry = (LogEntry *)malloc(sizeof(LogEntry));
    new_entry->level = level;
    new_entry->timestamp = timestamp;
    new_entry->id = id;
    new_entry->message_length = strlen(message);
    new_entry->message = strdup(message);
    new_entry->next = list->head;
    list->head = new_entry;
    pthread_mutex_unlock(&list->lock);
}

void filter_logs(LogList *list, LogLevel min_level, time_t start_time, time_t end_time) {
    LogEntry *entry = list->head;
    while (entry != NULL) {
        if (entry->level >= min_level && entry->timestamp >= start_time && entry->timestamp <= end_time) {
            printf("Log ID: %d, Level: %d, Timestamp: %ld, Message: %s\n", entry->id, entry->level, entry->timestamp, entry->message);
        }
        entry = entry->next;
    }
}

void update_log_message(LogList *list, int id, const char *new_message) {
    pthread_mutex_lock(&list->lock);
    LogEntry *entry = list->head;
    while (entry != NULL) {
        if (entry->id == id) {
            free(entry->message);
            entry->message_length = strlen(new_message);
            entry->message = strdup(new_message);
            break;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&list->lock);
}
