#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_APP_NAME_LEN 100
#define MAX_METRIC_NAME_LEN 50
#define MAX_METRICS_PER_APP 10

typedef struct {
    char name[MAX_APP_NAME_LEN];
    int interval;
    char metrics[MAX_METRICS_PER_APP][MAX_METRIC_NAME_LEN];
} AppConfig;

typedef struct Node {
    AppConfig app;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} APMFramework;

APMFramework* create_apm_framework() {
    APMFramework* framework = (APMFramework*)malloc(sizeof(APMFramework));
    if (!framework) {
        perror("Failed to allocate memory for APMFramework");
        return NULL;
    }
    framework->head = NULL;
    pthread_mutex_init(&framework->lock, NULL);
    return framework;
}

void destroy_apm_framework(APMFramework* framework) {
    Node* current = framework->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&framework->lock);
    free(framework);
}

int add_application(APMFramework* framework, const char* name, int interval, const char** metrics, int num_metrics) {
    pthread_mutex_lock(&framework->lock);

    Node* current = framework->head;
    while (current) {
        if (strcmp(current->app.name, name) == 0) {
            fprintf(stderr, "Application with name '%s' already exists.\n", name);
            pthread_mutex_unlock(&framework->lock);
            return -1;
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new application node");
        pthread_mutex_unlock(&framework->lock);
        return -1;
    }

    strncpy(new_node->app.name, name, MAX_APP_NAME_LEN);
    new_node->app.interval = interval;
    for (int i = 0; i < num_metrics && i < MAX_METRICS_PER_APP; i++) {
        strncpy(new_node->app.metrics[i], metrics[i], MAX_METRIC_NAME_LEN);
    }
    new_node->next = framework->head;
    framework->head = new_node;

    pthread_mutex_unlock(&framework->lock);
    return 0;
}

int remove_application(APMFramework* framework, const char* name) {
    pthread_mutex_lock(&framework->lock);

    Node** current_ptr = &framework->head;
    while (*current_ptr) {
        if (strcmp((*current_ptr)->app.name, name) == 0) {
            Node* temp = *current_ptr;
            *current_ptr = (*current_ptr)->next;
            free(temp);
            pthread_mutex_unlock(&framework->lock);
            return 0;
        }
        current_ptr = &(*current_ptr)->next;
    }

    pthread_mutex_unlock(&framework->lock);
    fprintf(stderr, "Application with name '%s' not found.\n", name);
    return -1;
}

int update_application(APMFramework* framework, const char* name, int interval, const char** metrics, int num_metrics) {
    pthread_mutex_lock(&framework->lock);

    Node* current = framework->head;
    while (current) {
        if (strcmp(current->app.name, name) == 0) {
            strncpy(current->app.name, name, MAX_APP_NAME_LEN);
            current->app.interval = interval;
            for (int i = 0; i < num_metrics && i < MAX_METRICS_PER_APP; i++) {
                strncpy(current->app.metrics[i], metrics[i], MAX_METRIC_NAME_LEN);
            }
            pthread_mutex_unlock(&framework->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&framework->lock);
    fprintf(stderr, "Application with name '%s' not found.\n", name);
    return -1;
}

void list_applications(APMFramework* framework) {
    pthread_mutex_lock(&framework->lock);

    Node* current = framework->head;
    while (current) {
        printf("App Name: %s, Interval: %d\n", current->app.name, current->app.interval);
        for (int i = 0; i < MAX_METRICS_PER_APP && strlen(current->app.metrics[i]) > 0; i++) {
            printf("  Metric %d: %s\n", i + 1, current->app.metrics[i]);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&framework->lock);
}

int main() {
    APMFramework* framework = create_apm_framework();

    const char* metrics1[] = {"CPU Usage", "Memory Usage"};
    add_application(framework, "App1", 60, metrics1, 2);

    const char* metrics2[] = {"Disk I/O", "Network Traffic"};
    add_application(framework, "App2", 30, metrics2, 2);

    list_applications(framework);

    remove_application(framework, "App1");

    list_applications(framework);

    destroy_apm_framework(framework);
    return 0;
}
