#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>
#include <openssl/evp.h>

#define N 10 // Number of structures to generate

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNfareEncryptData(NFAPI_CRC_INDICATION_PDU_T *data, unsigned char *key, unsigned char *iv, unsigned char **encrypted_data, size_t *encrypted_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    // Initialize the encryption context
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Allocate memory for encrypted data
    *encrypted_len = N * sizeof(NFAPI_CRC_INDICATION_PDU_T) + EVP_CIPHER_block_size(EVP_aes_256_cbc());
    *encrypted_data = (unsigned char *)malloc(*encrypted_len);
    if (!*encrypted_data) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Populate and encrypt the data
    for (int i = 0; i < N; i++) {
        data[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        data[i].RNTI = rand() % 65536;
        data[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        if (1 != EVP_EncryptUpdate(ctx, (*encrypted_data) + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), encrypted_len, (unsigned char *)&data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            free(*encrypted_data);
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
    }

    // Finalize the encryption
    int len;
    if (1 != EVP_EncryptFinal_ex(ctx, (*encrypted_data) + N * sizeof(NFAPI_CRC_INDICATION_PDU_T), &len)) {
        free(*encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *encrypted_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int main() {
    unsigned char key[32];
    unsigned char iv[16];
    NFAPI_CRC_INDICATION_PDU_T data[N];
    unsigned char *encrypted_data;
    size_t encrypted_len;

    // Generate random key and IV
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate random bytes\n");
        return 1;
    }

    // Populate and encrypt data
    if (generateNfareEncryptData(data, key, iv, &encrypted_data, &encrypted_len) != 0) {
        fprintf(stderr, "Encryption failed\n");
        return 1;
    }

    // Free allocated memory
    free(encrypted_data);

    return 0;
}
