#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_THRESHOLD 1024 * 1024 // 1 MB

typedef struct {
    long offset;
    int key;
    struct record {
        long timestamp;
        int key;
    } record;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct point {
    double x, y;
} Point;

typedef struct color {
    unsigned char r, g, b;
} Color;

typedef struct hash_table_entry {
    Point *point;
    Color *color;
    struct hash_table_entry *next;
} HashTableEntry;

typedef struct hash_table {
    HashTableEntry **buckets;
    size_t size;
    size_t count;
} HashTable;

// Function to dynamically allocate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int N) {
    if (N > MAX_MEMORY_THRESHOLD / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Exceeds maximum memory threshold\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        list[i].offset = rand();
        list[i].key = rand() % 100;
        list[i].record.timestamp = time(NULL);
        list[i].record.key = rand() % 100;
    }

    return list;
}

// Function to create and populate a hash table
HashTable* create_hash_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    if (table == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    table->buckets = calloc(size, sizeof(HashTableEntry *));
    if (table->buckets == NULL) {
        free(table);
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    table->size = size;
    table->count = 0;

    return table;
}

// Function to insert a point into the hash table
void insert_point(HashTable *table, Point *point, Color *color) {
    if (table->count >= table->size * 0.75) {
        // Resize and rehash
        HashTableEntry **old_buckets = table->buckets;
        size_t old_size = table->size;

        table->size *= 2;
        table->buckets = calloc(table->size, sizeof(HashTableEntry *));
        if (table->buckets == NULL) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        for (size_t i = 0; i < old_size; i++) {
            HashTableEntry *entry = old_buckets[i];
            while (entry != NULL) {
                HashTableEntry *next_entry = entry->next;
                size_t index = hash_function(entry->point, table->size);
                entry->next = table->buckets[index];
                table->buckets[index] = entry;
                entry = next_entry;
            }
        }

        free(old_buckets);
    }

    size_t index = hash_function(point, table->size);
    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    if (entry == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    entry->point = point;
    entry->color = color;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    table->count++;
}

// Custom hash function for points
size_t hash_function(Point *point, size_t size) {
    return (size_t)(point->x + point->y) % size;
}

int main() {
    int N = 1000;
    NFAPI_CRC_INDICATION_PDU_T *list = create_crc_indication_pdu_list(N);

    HashTable *table = create_hash_table(128);
    Point point = {3.5, 4.2};
    Color color = {255, 0, 0};
    insert_point(table, &point, &color);

    free(list);
    for (size_t i = 0; i < table->size; i++) {
        HashTableEntry *entry = table->buckets[i];
        while (entry != NULL) {
            HashTableEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }
    free(table->buckets);
    free(table);

    return 0;
}
