#define MAX_STRUCTS 1000
#define ENCRYPTION_KEY_SIZE 32
#define IV_SIZE 16

typedef struct {
    uint8_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    FAILURE
} Status;

Status processNfaPduStream(NFAPI_CRC_INDICATION_PDU_T *structs, int numStructs, const uint8_t *key, const uint8_t *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return FAILURE;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return FAILURE;
    }

    for (int i = 0; i < numStructs; i++) {
        if (1 != EVP_EncryptUpdate(ctx, structs[i].crc_indication_rel8_tag, NULL, &structs[i].crc_indication_rel8_tag, sizeof(structs[i].crc_indication_rel8_tag))) {
            EVP_CIPHER_CTX_free(ctx);
            return FAILURE;
        }
    }

    int len;
    if (1 != EVP_EncryptFinal_ex(ctx, structs[numStructs - 1].crc_indication_rel8_tag + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return FAILURE;
    }

    EVP_CIPHER_CTX_free(ctx);
    return SUCCESS;
}

int main(int argc, char *argv[]) {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T structs[MAX_STRUCTS];
    uint8_t key[ENCRYPTION_KEY_SIZE];
    uint8_t iv[IV_SIZE];

    // Initialize structures and key/iv here

    Status status = processNfaPduStream(structs, MAX_STRUCTS, key, iv);
    if (status == SUCCESS) {
        printf("Processing successful.\n");
    } else {
        printf("Processing failed.\n");
    }

    return 0;
}
