typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint8_t data[ENCRYPTED_DATA_SIZE];
    uint32_t identifier;
} EncryptedStruct;

EncryptedStruct* generateNFARawAndEncryptedData(NFAPI_CRC_INDICATION_PDU_T* rawStructs, int numStructs, const unsigned char* key, const unsigned char* iv) {
    EncryptedStruct* encryptedStructs = (EncryptedStruct*)malloc(numStructs * ENCRYPTED_DATA_SIZE);
    if (!encryptedStructs) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    AES_KEY enc_key;
    if (AES_set_encrypt_key(key, 128, &enc_key) < 0) {
        fprintf(stderr, "Failed to set encryption key\n");
        free(encryptedStructs);
        return NULL;
    }

    for (int i = 0; i < numStructs; ++i) {
        // Populate the raw structure with valid data
        // ...

        // Encrypt the structure
        AES_cbc_encrypt((unsigned char*)&rawStructs[i], encryptedStructs[i].data, STRUCT_SIZE, &enc_key, iv, AES_ENCRYPT);

        // Generate a unique identifier
        uint32_t timestamp = (uint32_t)time(NULL);
        uint32_t sequenceNumber = i;
        uint16_t rnti = rawStructs[i].RNTI; // Assuming RNTI is a 16-bit field
        encryptedStructs[i].identifier = (timestamp << 16) | (sequenceNumber << 8) | rnti;

        // Update the IV for the next encryption
        memcpy(iv, iv + AES_BLOCK_SIZE, AES_BLOCK_SIZE);
    }

    return encryptedStructs;
}

