    unsigned char key[AES_BLOCK_SIZE] = { /* Initialize with a valid 128-bit key */ };
    unsigned char iv[AES_BLOCK_SIZE] = { /* Initialize with a valid IV */ };

    EncryptedStruct* encryptedStructs = generateNFARawAndEncryptedData(rawStructs, MAX_STRUCTS, key, iv);
    if (encryptedStructs) {
        // Process the encrypted data
        free(encryptedStructs);
    }

    return 0;
