#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024

typedef struct {
    char *buffer;
    size_t size;
    pthread_mutex_t mutex;
} LogEntry;

LogEntry* allocateLogEntry() {
    LogEntry *entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    entry->size = MAX_LOG_SIZE;
    entry->buffer = (char*)malloc(entry->size);
    if (!entry->buffer) {
        free(entry);
        return NULL;
    }

    pthread_mutex_init(&entry->mutex, NULL);
    return entry;
}

void logMessage(LogEntry *entry, const char *format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&entry->mutex);
    int result = vsnprintf(entry->buffer, entry->size, format, args);
    if (result >= entry->size) {
        // Handle buffer overflow
        printf("Log message too long\n");
    }
    pthread_mutex_unlock(&entry->mutex);

    va_end(args);
}

void freeLogEntry(LogEntry *entry) {
    if (entry) {
        pthread_mutex_destroy(&entry->mutex);
        free(entry->buffer);
        free(entry);
    }
}
