UeState* ue_state_array = NULL;
int array_size = 0;
int current_index = 0;

void initialize_ue_state() {
    ue_state_array = (UeState*)malloc(10 * sizeof(UeState)); // Initial allocation
    array_size = 10;
}

void add_or_update_ue_state(int ue_id, char* name) {
    for (int i = 0; i < current_index; i++) {
        if (ue_state_array[i].ue_id == ue_id) {
            strcpy(ue_state_array[i].name, name);
            return;
        }
    }
    if (current_index >= array_size) {
        array_size *= 2;
        ue_state_array = realloc(ue_state_array, array_size * sizeof(UeState));
    }
    ue_state_array[current_index].ue_id = ue_id;
    strcpy(ue_state_array[current_index].name, name);
    current_index++;
}

void manage_ue_state(int ue_id, char* action, char* name) {
    if (strcmp(action, "add") == 0) {
        add_or_update_ue_state(ue_id, name);
    } else if (strcmp(action, "update") == 0) {
        add_or_update_ue_state(ue_id, name);
    }
}

void free_ue_state() {
    free(ue_state_array);
}
