NFAPI_CRC_INDICATION_PDU_T* allocate_NFAPI_CRC_INDICATION_PDU(int N, int *error_code) {
    if (N <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    static unsigned short rnti_set[] = {1, 2, 3, 4, 5}; // Predefined RNTI set
    static int rnti_index = 0;

    time_t current_time = time(NULL);
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG.sequence_number = ((current_time + i) * 12345) % 65536; // Unique sequence number
        if (rnti_index >= sizeof(rnti_set) / sizeof(rnti_set[0])) {
            rnti_index = 0; // Reset index for fallback mechanism
        }
        array[i].RNTI = rnti_set[rnti_index++];
        array[i].CRC_INDICATION_REL8_TAG.CRC_INDICATION = (i & 0x1F) ^ 0xAA; // CRC flag based on bitwise operation
    }

    *error_code = 0; // Success
    return array;
}
