int cache_index = 0;

NFAPI_CRC_INDICATION_PDU_T* generateNFAPI_CRC_Indication_List(int num_tags) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_tags * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_tags; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % MAX_UE_INFO_TAGS;
        list[i].RNTI = rand() % 16384;
        list[i].CRCFLAG = rand() % 2;
    }

