}

char* getAccessTokenFromAPI() {
    // Simulate OAuth 2.0 token retrieval
    static char token[256];
    snprintf(token, sizeof(token), "Bearer %d", time(NULL));
    return token;
}

void cacheAccessToken(const char* access_token) {
    if (cache_index >= CACHE_SIZE) {
        cache_index = 0; // Simple round-robin eviction policy
    }
    strcpy(token_cache[cache_index].access_token, access_token);
    token_cache[cache_index].expiration_time = time(NULL) + 3600; // Cache for 1 hour
    cache_index++;
}

const char* getAccessToken() {
    time_t now = time(NULL);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(token_cache[i].access_token, "") != 0 && token_cache[i].expiration_time > now) {
            return token_cache[i].access_token;
        }
    }
    const char* new_token = getAccessTokenFromAPI();
    cacheAccessToken(new_token);
    return new_token;
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* crc_list = generateNFAPI_CRC_Indication_List(10);

    // Simulate API call with access token
    const char* access_token = getAccessToken();
    printf("Access Token: %s\n", access_token);

    free(crc_list);
    return 0;
}
