typedef struct LTE_ENB_CONTEXT {
    int PHY_CELL_ID;
    int PCI;
    PHY_CELL_CONFIG config;
    PHY_CELL_STATS stats;
} LTE_ENB_CONTEXT;

LTE_ENB_CONTEXT* create_enb_contexts(int num_contexts, size_t max_memory_size) {
    if (num_contexts > MAX_ENB_CONTEXTS || num_contexts * sizeof(LTE_ENB_CONTEXT) > max_memory_size) {
        return NULL; // Insufficient memory or too many contexts
    }

    LTE_ENB_CONTEXT* enb_contexts = (LTE_ENB_CONTEXT*)malloc(num_contexts * sizeof(LTE_ENB_CONTEXT));
    if (!enb_contexts) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_contexts; ++i) {
        enb_contexts[i].PHY_CELL_ID = i + 1; // Unique sequence number based on index
        enb_contexts[i].PCI = i % 256; // Unique identifier from a predefined set

        // Initialize PHY_CELL_CONFIG with default values or data from external sources
        enb_contexts[i].config.bandwidth = 20;
        enb_contexts[i].config.subcarrier_spacing = 15e3;
        enb_contexts[i].config.frequency_offset = 0;

        // Initialize PHY_CELL_STATS with historical data points
        for (int j = 0; j < MAX_SIGNAL_HISTORY; ++j) {
            enb_contexts[i].stats.signal_strength[j] = 90 + i % 10;
            enb_contexts[i].stats.snr[j] = 20.5 - i * 0.1;
            enb_contexts[i].stats.throughput[j] = 1000 + i * 10;
        }
    }

    return enb_contexts;
}

void update_enb_stats(LTE_ENB_CONTEXT* enb_context, int index, int signal_strength, float snr, int throughput) {
    if (index >= 0 && index < MAX_ENB_CONTEXTS) {
        enb_context[index].stats.signal_strength[enb_context[index].stats.signal_strength[0] % MAX_SIGNAL_HISTORY] = signal_strength;
        enb_context[index].stats.snr[enb_context[index].stats.snr[0] % MAX_SIGNAL_HISTORY] = snr;
        enb_context[index].stats.throughput[enb_context[index].stats.throughput[0] % MAX_SIGNAL_HISTORY] = throughput;
    }
}

void free_enb_contexts(LTE_ENB_CONTEXT* enb_contexts) {
    if (enb_contexts) {
        free(enb_contexts);
    }
}
