LTE_ENB_MESSAGE_PDU_T* create_message(E_UTRAN_RRC_MESSAGE_TYPE type, int* channel_ids, int num_channels) {
    LTE_ENB_MESSAGE_PDU_T* message = (LTE_ENB_MESSAGE_PDU_T*)malloc(sizeof(LTE_ENB_MESSAGE_PDU_T));
