    char value[MAX_KEY_SIZE];
    long timestamp;
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} Database;

Database* create_database() {
    Database *db = (Database*)malloc(sizeof(Database));
    db->records = NULL;
    db->size = 0;
    db->capacity = 10;
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

void destroy_database(Database *db) {
    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

int hash_function(int key, int capacity) {
    // Simple hash function for demonstration purposes
    return abs(key % capacity);
}

int insert_record(Database *db, Record record) {
    pthread_mutex_lock(&db->lock);
    if (db->size >= db->capacity) {
        // Resize the database
        db->capacity *= 2;
        db->records = (Record*)realloc(db->records, db->capacity * sizeof(Record));
    }
    int index = hash_function(record.key, db->capacity);
    while (db->records[index].key != -1 && db->records[index].timestamp != record.timestamp) {
        index = (index + 1) % db->capacity;
    }
    if (db->records[index].key == -1) {
        db->records[index] = record;
        db->size++;
    } else {
        // Handle collision, e.g., by chaining or open addressing
        printf("Collision detected!\n");
    }
    pthread_mutex_unlock(&db->lock);
    return 0;
}

Record* lookup_record(Database *db, int key) {
    pthread_mutex_lock(&db->lock);
    int index = hash_function(key, db->capacity);
    while (db->records[index].key != -1 && db->records[index].key != key) {
        index = (index + 1) % db->capacity;
    }
    if (db->records[index].key == key) {
        Record *result = (Record*)malloc(sizeof(Record));
        *result = db->records[index];
        pthread_mutex_unlock(&db->lock);
        return result;
    } else {
        pthread_mutex_unlock(&db->lock);
        return NULL;
    }
}

int delete_record(Database *db, int key) {
    pthread_mutex_lock(&db->lock);
    int index = hash_function(key, db->capacity);
    while (db->records[index].key != -1 && db->records[index].key != key) {
        index = (index + 1) % db->capacity;
    }
    if (db->records[index].key == key) {
        memset(&db->records[index], 0, sizeof(Record));
        db->size--;
    } else {
        printf("Key not found!\n");
    }
    pthread_mutex_unlock(&db->lock);
    return 0;
}

int main() {
    Database *db = create_database();
    Record record1 = {1, "Value1", 12345};
    insert_record(db, record1);

    Record *result = lookup_record(db, 1);
    if (result != NULL) {
        printf("Found: key=%d, value=%s, timestamp=%ld\n", result->key, result->value, result->timestamp);
        free(result);
    }

    delete_record(db, 1);
    destroy_database(db);
    return 0;
}
