void generate_report(void);
void send_report_to_server(const char* report);

// Global variables
char* input_filename;
char* output_filename;
char* aggregation_rules;
size_t memory_threshold;
int cache_enabled;
int remote_send_enabled;

int main(int argc, char* argv[]) {
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <aggregation_rules> <memory_threshold> <cache_enabled> <remote_send_enabled>\n", argv[0]);
        return 1;
    }

    input_filename = argv[1];
    output_filename = argv[2];
    aggregation_rules = argv[3];
    memory_threshold = atoi(argv[4]);
    cache_enabled = atoi(argv[5]);
    remote_send_enabled = atoi(argv[6]);

    if (!validate_input_file(input_filename)) {
        fprintf(stderr, "Error: Input file is not accessible.\n");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_log_file, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread_id, NULL);

    return 0;
}

void* process_log_file(void* arg) {
    FILE* file = fopen(input_filename, "r");
    if (!file) {
        perror("Error opening input file");
        return NULL;
    }

    size_t line_size = 128;
    char* line = (char*)malloc(line_size);
    if (!line) {
        perror("Error allocating memory for line buffer");
        fclose(file);
        return NULL;
    }

    while (fgets(line, line_size, file)) {
        parse_log_line(line, aggregation_rules);
    }

    free(line);
    fclose(file);

    generate_report();

    if (remote_send_enabled) {
        send_report_to_server(output_filename);
    } else {
        // Store report locally
        printf("Report stored locally: %s\n", output_filename);
    }

    return NULL;
}

int validate_input_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return 0;
    }
    fclose(file);
    return 1;
}

int allocate_memory(size_t size, void** ptr) {
    *ptr = malloc(size);
    if (!*ptr) {
        fprintf(stderr, "Error allocating memory: %zu bytes\n", size);
        return -1;
    }
    return 0;
}

void parse_log_line(const char* line, void (*callback)(const char*)) {
    // Apply aggregation rules using callback
