#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int structure_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_structures(int N) {
    pthread_mutex_lock(&mutex);
    if (structure_count + N > MAX_STRUCTURES) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Memory limit exceeded
    }
    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Memory allocation failed
    }
    for (int i = 0; i < N; i++) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structures[i].RNTI = rand() % 256;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    structure_count += N;
    pthread_mutex_unlock(&mutex);
    return structures;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T* structures, int N) {
    pthread_mutex_lock(&mutex);
    structure_count -= N;
    free(structures);
    pthread_mutex_unlock(&mutex);
}

