# Import necessary libraries
from flask import Flask, request, jsonify
from elasticsearch import Elasticsearch
from redis import Redis
import time

app = Flask(__name__)
es = Elasticsearch([{'host': 'localhost', 'port': 9200}])
redis_client = Redis(host='localhost', port=6379, db=0)

# Define search endpoint
@app.route('/search', methods=['GET'])
def search():
    query = request.args.get('query')
    date_range = request.args.get('date_range')
    file_type = request.args.get('file_type')
    metadata_field = request.args.get('metadata_field')

    # Check cache for results
    cached_results = redis_client.get(query)
    if cached_results:
        return jsonify({'results': eval(cached_results)})

    # Build Elasticsearch query
    es_query = {
        "query": {
            "multi_match": {
                "query": query,
                "fields": ["content", metadata_field]
            }
        },
        "filter": [
            {"range": {"date": date_range}},
            {"term": {"file_type": file_type}}
        ]
    }

    # Execute search
    start_time = time.time()
    results = es.search(index="documents", body=es_query)
    end_time = time.time()

    # Cache results for future requests
    redis_client.set(query, str(results), ex=3600)  # Cache for 1 hour

    return jsonify({'results': results['hits']['hits'], 'query_time': end_time - start_time})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

This code snippet provides a basic implementation of a search engine using Flask, Elasticsearch, and Redis. It includes caching to reduce database load and supports customizable search criteria. The system can be further optimized for scalability and performance by adding more advanced features such as distributed caching, horizontal scaling, and robust logging and monitoring.']

