import json
import os
import requests
from threading import Lock, Event
from queue import Queue
from concurrent.futures import ThreadPoolExecutor

class ConfigManager:
    def __init__(self, config_sources, logger, update_callback):
        self.config_sources = config_sources
        self.logger = logger
        self.update_callback = update_callback
        self.cache = {}
        self.lock = Lock()
        self.event = Event()
        self.executor = ThreadPoolExecutor(max_workers=5)
        self.subscribers = []

    def load_config(self):
        with self.lock:
            for source in self.config_sources:
                if source['type'] == 'json':
                    self.load_json(source['path'])
                elif source['type'] == 'env':
                    self.load_env()
                elif source['type'] == 'api':
                    self.load_api(source['url'])
            self.update_callback(self.cache)

    def load_json(self, path):
        try:
            with open(path, 'r') as file:
                data = json.load(file)
                for key, value in data.items():
                    self.cache[key] = value
        except Exception as e:
            self.logger.error(f"Failed to load JSON config: {e}")

    def load_env(self):
        try:
            for key in os.environ:
                self.cache[key] = os.getenv(key)
        except Exception as e:
            self.logger.error(f"Failed to load environment variables: {e}")

    def load_api(self, url):
        try:
            response = requests.get(url)
            data = response.json()
            for key, value in data.items():
                self.cache[key] = value
        except Exception as e:
            self.logger.error(f"Failed to load API config: {e}")

    def subscribe(self, callback):
        with self.lock:
            self.subscribers.append(callback)

    def notify_subscribers(self):
        with self.lock:
            for subscriber in self.subscribers:
                subscriber(self.cache)

    def update_config_async(self):
        self.executor.submit(self.load_config)
        self.event.set()

    def wait_for_update(self):
        self.event.wait()
        self.event.clear()

# Example usage
config_sources = [
    {'type': 'json', 'path': 'config.json'},
    {'type': 'env', 'key': 'API_KEY'},
    {'type': 'api', 'url': 'https://api.example.com/config'}
]

def update_callback(config):
    print("Configuration updated:", config)

logger = Logger()  # Assume a custom logger class is defined

config_manager = ConfigManager(config_sources, logger, update_callback)
config_manager.update_config_async()
config_manager.wait_for_update()
