class ForwardListModifier {
public:
    void insertAfterInForwardList(std::forward_list<std::string>& list, const std::string& targetString, const std::string& newString) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == targetString) {
                it = list.insert_after(it, newString);
                return;
            }
            ++it;
        }
        list.push_back(newString);
    }

private:
    std::mutex mutex_;
};

