["```javascript
function fetchMatchingElements(selector, callback, maxDepth = 3, timeout = 5000) {
    if (typeof selector !== 'string' || typeof callback !== 'function') return [];
    if (maxDepth < 1 || maxDepth > 10) maxDepth = 3;
    if (timeout < 100 || timeout > 60000) timeout = 5000;

    const startTime = Date.now();
    let result = [];

    function traverse(node, depth) {
        if (!node || depth > maxDepth || Date.now() - startTime > timeout) return;
        if (node.nodeType === Node.ELEMENT_NODE && node.matches(selector)) {
            if (callback(node)) result.push(node);
        }
        for (let child of node.childNodes) {
            traverse(child, depth + 1);
        }
    }

    traverse(document.body, 0);
    return result;
}
