// Main Program
async function loadAndExecuteScripts(directory) {
    try {
        const scriptFiles = await getScriptFiles(directory);
        const uniqueScripts = await modifyFileExtensions(scriptFiles);
        for (const script of uniqueScripts) {
            await executeScript(script);
        }
    } catch (error) {
        console.error('Error loading or executing scripts:', error);
    }
}

async function getScriptFiles(directory) {
    // Fetch script files from the specified directory
    const response = await fetch(`/api/scripts?directory=${encodeURIComponent(directory)}`);
    if (!response.ok) throw new Error('Failed to fetch script files');
    return await response.json();
}

async function modifyFileExtensions(scriptFiles) {
    const uniqueScripts = [];
    for (const file of scriptFiles) {
        try {
            const contentHash = await getFileContentHash(file);
            const uniqueName = generateUniqueFileName(file.name, contentHash);
            uniqueScripts.push({ ...file, name: uniqueName });
        } catch (error) {
            console.error(`Failed to modify file extension for ${file.name}:`, error);
        }
    }
    return uniqueScripts;
}

async function getFileContentHash(filePath) {
    // Fetch and hash the content of a file
    const response = await fetch(`/api/file-content?path=${encodeURIComponent(filePath)}`);
    if (!response.ok) throw new Error('Failed to fetch file content');
    const content = await response.text();
    return crypto.subtle.digest('SHA-256', new TextEncoder().encode(content)).then(buffer => {
        return Array.from(new Uint8Array(buffer)).map(b => b.toString(16).padStart(2, '0')).join('');
    });
}

function generateUniqueFileName(originalName, hash) {
    // Generate a unique file name based on the original and content hash
    const baseName = originalName.split('.').slice(0, -1).join('.');
    return `${baseName}-${hash.slice(0, 8)}.js`;
}

async function executeScript(script) {
    try {
        const scriptElement = document.createElement('script');
        scriptElement.src = script.path;
        document.head.appendChild(scriptElement);
        await new Promise(resolve => scriptElement.onload = resolve);
    } catch (error) {
        console.error(`Failed to execute script ${script.name}:`, error);
    }
}

// Utility Function
function validateFileName(fileName) {
    // Validate the modified file name against naming conventions
    const regex = /^[a-zA-Z0-9_]+\.[a-z]+$/;
    return regex.test(fileName);
}
