import os
import json
import threading
from functools import lru_cache
from datetime import datetime

class UserPreferenceManager:
    def __init__(self, default_dir='~/.user_prefs', auth_service=None):
        self.default_dir = os.path.expanduser(default_dir)
        self.auth_service = auth_service
        self.locks = {}
        self.metrics = {}

    def get_user_preference_file(self, user_id):
        return os.path.join(self.default_dir, f'user_{user_id}.json')

    @lru_cache(maxsize=128)
    def load_preferences(self, user_id):
        file_path = self.get_user_preference_file(user_id)
        if not os.path.exists(file_path):
            return {}
        try:
            with open(file_path, 'r') as file:
                preferences = json.load(file)
                self.metrics[user_id] = {'reads': self.metrics.get(user_id, {}).get('reads', 0) + 1}
                return preferences
        except (FileNotFoundError, json.JSONDecodeError):
            return {}

    def save_preferences(self, user_id, preferences):
        file_path = self.get_user_preference_file(user_id)
        with open(file_path, 'w') as file:
            json.dump(preferences, file, indent=4)
            self.metrics[user_id] = {'writes': self.metrics.get(user_id, {}).get('writes', 0) + 1}

    def update_preference(self, user_id, key, value):
        with self.get_lock(user_id):
            preferences = self.load_preferences(user_id)
            preferences[key] = value
            self.save_preferences(user_id, preferences)

    def get_lock(self, user_id):
        if user_id not in self.locks:
            self.locks[user_id] = threading.Lock()
        return self.locks[user_id]

    def authenticate_user(self, user_id, token):
        if self.auth_service:
            try:
                return self.auth_service.authenticate(user_id, token)
            except Exception as e:
                print(f"Authentication failed: {e}")
                return False
        return True

    def get_usage_metrics(self):
        return self.metrics

# Example usage
class MockAuthService:
    @staticmethod
    def authenticate(user_id, token):
        # Simulate authentication logic
        return user_id == 'admin' and token == 'secret'

auth_service = MockAuthService()
manager = UserPreferenceManager(auth_service=auth_service)

user_id = 'admin'
token = 'secret'
if manager.authenticate_user(user_id, token):
    manager.update_preference(user_id, 'theme', 'dark')
    print(manager.load_preferences(user_id))
    print(manager.get_usage_metrics())
else:
    print("Authentication failed")
