const axios = require('axios');
const fs = require('fs');
const path = require('path');

class CertificateGenerator {
  constructor() {
    this.state = { currentRequest: null, lastProcessedIndex: -1 };
    this.cache = {};
    this.logService = new ExternalLoggingService();
  }

  async generateCertificateFromOAuthRequest(requests) {
    const results = [];
    for (let i = 0; i < requests.length; i++) {
      if (this.state.currentRequest && this.state.currentRequest !== requests[i]) {
        await this.pauseProcessing();
      }
      this.state.currentRequest = requests[i];
      try {
        const result = await this.processRequest(requests[i]);
        results.push(result);
        this.state.lastProcessedIndex = i;
        this.logService.logSuccess(`Processed request ${i}`);
      } catch (error) {
        this.logService.logError(`Failed to process request ${i}: ${error.message}`);
        await this.handleRetry(requests[i], error);
      }
    }
    return results;
  }

  async processRequest(request) {
    const { keyUrl, certUrl } = request;
    let privateKey, certificate;

    if (this.cache[keyUrl]) {
      privateKey = this.cache[keyUrl];
    } else {
      privateKey = await axios.get(keyUrl).then(response => response.data);
      this.cache[keyUrl] = privateKey;
    }

    if (this.cache[certUrl]) {
      certificate = this.cache[certUrl];
    } else {
      certificate = await axios.get(certUrl).then(response => response.data);
      this.cache[certUrl] = certificate;
    }

    return this.mergePemFiles(privateKey, certificate);
  }

  mergePemFiles(privateKey, certificate) {
    const pemFile = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`;
    return pemFile;
  }

  async pauseProcessing() {
    // Implement state management and pausing logic here
  }

  async handleRetry(request, error) {
    const retryInterval = this.calculateRetryInterval(error);
    await new Promise(resolve => setTimeout(resolve, retryInterval));
    try {
      await this.processRequest(request);
    } catch (retryError) {
      this.logService.logError(`Failed to process request ${request.id} after retry: ${retryError.message}`);
    }
  }

  calculateRetryInterval(error) {
    // Implement backoff strategy here
    return 1000; // Example fixed interval for demonstration
  }
}

class ExternalLoggingService {
  logSuccess(message) {
    console.log(`SUCCESS: ${message}`);
  }

  logError(message) {
    console.error(`ERROR: ${message}`);
  }
}
