#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEY_LENGTH 256

typedef enum {
    INT,
    FLOAT,
    STRING
} ValueType;

typedef struct {
    int key;
    ValueType type;
    union {
        int intValue;
        float floatValue;
        char stringValue[MAX_KEY_LENGTH];
    } value;
} Setting;

Setting* createSettings(int maxSettings) {
    if (maxSettings <= 0) {
        return NULL; // Handle edge case
    }

    Setting* settings = malloc(maxSettings * sizeof(Setting));
    if (!settings) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < maxSettings; ++i) {
        settings[i].key = i;
        settings[i].type = INT; // Default type
        settings[i].value.intValue = 0; // Default value
    }

    return settings;
}

void freeSettings(Setting* settings, int maxSettings) {
    if (settings) {
        free(settings);
    }
}

int loadDefaultValues(Setting* settings, int maxSettings, const char* configFilePath) {
    FILE* file = fopen(configFilePath, "r");
    if (!file) {
        return -1; // Handle file open failure
    }

    for (int i = 0; i < maxSettings; ++i) {
        char line[256];
        if (fgets(line, sizeof(line), file)) {
            char key[256], type[256], value[256];
            sscanf(line, "%s %s %s", key, type, value);

            for (int j = 0; j < maxSettings; ++j) {
                if (settings[j].key == atoi(key)) {
                    if (strcmp(type, "INT") == 0) {
                        settings[j].type = INT;
                        settings[j].value.intValue = atoi(value);
                    } else if (strcmp(type, "FLOAT") == 0) {
                        settings[j].type = FLOAT;
                        settings[j].value.floatValue = atof(value);
                    } else if (strcmp(type, "STRING") == 0) {
                        strncpy(settings[j].value.stringValue, value, MAX_KEY_LENGTH - 1);
                        settings[j].value.stringValue[MAX_KEY_LENGTH - 1] = '\0';
                    }
                    break;
                }
            }
        }
    }

    fclose(file);
    return 0; // Success
}

int validateSettings(Setting* settings, int maxSettings) {
    for (int i = 0; i < maxSettings; ++i) {
        switch (settings[i].type) {
            case INT:
                if (settings[i].value.intValue < 0 || settings[i].value.intValue > 100) {
                    return -1; // Invalid integer value
                }
                break;
            case FLOAT:
                if (settings[i].value.floatValue < 0.0f || settings[i].value.floatValue > 100.0f) {
                    return -1; // Invalid float value
                }
                break;
            case STRING:
                if (strlen(settings[i].value.stringValue) > MAX_KEY_LENGTH - 1) {
                    return -1; // String too long
                }
                break;
        }
    }
    return 0; // Success
}

Setting* getSettingByKey(Setting* settings, int maxSettings, int key) {
    for (int i = 0; i < maxSettings; ++i) {
        if (settings[i].key == key) {
            return &settings[i];
        }
    }
    return NULL; // Key not found
}

