class OAuth2Authenticator {
    private $client;
    private $sessionKey = 'oauth_user';
    private $retryCount = 3;

    public function __construct($clientId, $clientSecret) {
        $this->client = new OAuth2\Client($clientId, $clientSecret);
    }

    public function authenticate($code) {
        for ($i = 0; $i <= $this->retryCount; $i++) {
            try {
                $tokenResponse = $this->client->getAccessToken('authorization_code', [
                    'code' => $code,
                ]);
                $_SESSION[$this->sessionKey] = $tokenResponse;
                return true;
            } catch (Exception $e) {
                if ($i == $this->retryCount) {
                    throw $e;
                }
                sleep(1); // Exponential backoff
            }
        }
    }

    public function getUserProfile() {
        if (!isset($_SESSION[$this->sessionKey])) {
            return null;
        }

        try {
            $token = $_SESSION[$this->sessionKey];
            $userResponse = $this->client->fetchResource('GET', 'https://api.example.com/user');
            return json_decode($userResponse, true);
        } catch (Exception $e) {
            unset($_SESSION[$this->sessionKey]);
            throw $e;
        }
    }

    public function logout() {
        unset($_SESSION[$this->sessionKey]);
    }

    public function handleSessionInactivity() {
        if (!isset($_SESSION[$this->sessionKey])) {
            return;
        }

