        // Lock the account after a certain number of failed attempts
        $failedAttempts = $this->getFailedAttempts($userId);
        if ($failedAttempts >= 5) {
            throw new Exception("Account locked due to too many failed attempts");
        }

        // Update the password in the database
        $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
        $stmt->execute([$hashedPassword, $userId]);

        // Reset failed attempts on successful update
