        time_t hour = events[i].timestamp / 3600 * 3600;
        char* source_ip = events[i].source_ip;
        size_t payload_size = events[i].payload_size;

        int found = 0;
        for (int j = 0; j < summary_index; j++) {
            if (summaries[j].hour == hour && strcmp(summaries[j].source_ip, source_ip) == 0) {
                summaries[j].total_payload_size += payload_size;
                summaries[j].event_count++;
                found = 1;
                break;
            }
        }

        if (!found) {
            summaries[summary_index].hour = hour;
            strcpy(summaries[summary_index].source_ip, source_ip);
            summaries[summary_index].total_payload_size = payload_size;
            summaries[summary_index].event_count = 1;
            summary_index++;
        }
    }

    // Further processing and aggregation can be done here

    return NULL;
}

int main() {
    NetworkEvent events[MAX_EVENTS];
    pthread_t thread;

    // Populate the events array with data
    for (int i = 0; i < MAX_EVENTS; i++) {
        events[i].timestamp = time(NULL) - rand() % 86400; // Random timestamp within the last day
        snprintf(events[i].event_type, sizeof(events[i].event_type), "Event%d", rand() % 10);
        snprintf(events[i].source_ip, sizeof(events[i].source_ip), "%d.%d.%d.%d",
                 rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        events[i].payload_size = rand() % 1024; // Random payload size
    }

    pthread_create(&thread, NULL, process_events, (void*)events);
    pthread_join(thread, NULL);

    return 0;
}
