MyStruct* create_struct_array(int length, const char** strings, int string_count, int min_num, int max_num, int seed) {
    if (length <= 0 || (string_count > 0 && strings == NULL)) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    MyStruct* array = (MyStruct*)malloc(length * sizeof(MyStruct));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for struct array.\n");
        return NULL;
    }

    srand(seed);
    const char* default_string = "default";

    for (int i = 0; i < length; ++i) {
        int random_index = rand() % string_count;
        array[i].str = (char*)malloc((strlen(strings[random_index]) + 1) * sizeof(char));
        if (array[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed for string at index %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(array[j].str);
            }
            free(array);
            return NULL;
        }
        strcpy(array[i].str, strings[random_index]);

        array[i].num = rand() % (max_num - min_num + 1) + min_num;

        if (seed == 0) {
            array[i].fnum = 0.0;
        } else {
            // Use the seed to ensure reproducibility
            srand(seed);
            array[i].fnum = (float)(rand() % 100) / 100.0; // Random float between 0 and 1
        }
    }

    return array;
}

void free_struct_array(MyStruct* array, int length) {
    if (array == NULL || length <= 0) {
        return;
    }

    for (int i = 0; i < length; ++i) {
        free(array[i].str);
    }
    free(array);
}
