const axios = require('axios');
const retry = require('async-retry');

async function aggregateData(initialAccumulator, dataStructure, callback, updateCallback) {
  let accumulator = initialAccumulator;
  const resolvedReferences = new Map();

  for (let i = 0; i < dataStructure.length; i++) {
    try {
      const result = await retry(async bail => {
        if (typeof dataStructure[i] === 'object' && dataStructure[i] !== null) {
          if (resolvedReferences.has(dataStructure[i])) {
            return resolvedReferences.get(dataStructure[i]);
          } else {
            const response = await axios.get(`https://api.example.com/resolve?ref=${dataStructure[i].id}`);
            resolvedReferences.set(dataStructure[i], response.data);
            return response.data;
          }
        } else {
          return dataStructure[i];
        }
      }, { retries: 5, factor: 2 });

      const nextAccumulator = await callback(result, i, accumulator);
      if (nextAccumulator instanceof Error) {
        throw nextAccumulator;
      }
      accumulator = nextAccumulator;

      updateCallback(accumulator, i);
    } catch (error) {
      console.error(`Error processing element at index ${i}:`, error);
      const skippedIndex = await callback(error, i, accumulator);
      if (skippedIndex instanceof Error) {
        throw skippedIndex;
      }
      accumulator = skippedIndex;

      updateCallback(accumulator, i);
    }
  }

  return accumulator;
}

// Example usage
const dataStructure = [
  { id: '1', value: 10 },
  { id: '2', value: 'invalid' },
  [3, 4],
  { id: '3', value: 5 }
];

aggregateData(0, dataStructure, async (element, index) => {
  if (typeof element === 'number') {
    return element;
  } else if (typeof element === 'string') {
    if (isNaN(element)) {
      throw new Error('Invalid number');
    }
    return parseInt(element);
  } else if (Array.isArray(element)) {
    return element.reduce((acc, val) => acc + val, 0);
  } else if (element instanceof Object && element.id) {
    const response = await axios.get(`https://api.example.com/resolve?ref=${element.id}`);
    return response.data.value;
  }
}, (accumulator, index) => {
  console.log(`Progress: Index ${index}, Accumulator: ${accumulator}`);
}).then(result => {
  console.log('Final Result:', result);
}).catch(error => {
  console.error('Aggregation failed:', error);
});
