#define MAX_LINE_LENGTH 1024

typedef struct {
    char *filename;
    pthread_mutex_t lock;
} FileData;

void* process_file(void* arg) {
    FileData *file_data = (FileData*)arg;
    FILE *file = fopen(file_data->filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        pthread_mutex_lock(&file_data->lock);
        // Process the line and compute average of last two numerical fields
        // ...
        pthread_mutex_unlock(&file_data->lock);
    }

    fclose(file);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename1> <filename2> ...\n", argv[0]);
        return 1;
    }

    pthread_t threads[argc - 1];
    FileData file_data[argc - 1];

    for (int i = 1; i < argc; i++) {
        file_data[i-1].filename = argv[i];
        pthread_mutex_init(&file_data[i-1].lock, NULL);
        if (pthread_create(&threads[i-1], NULL, process_file, &file_data[i-1]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
        pthread_mutex_destroy(&file_data[i].lock);
    }

    return 0;
}
