#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/md5.h>

typedef struct {
    long offset;
    int key;
    char* identifier;
} Record;

Record* create_record(long offset, int key, const char* identifier) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->offset = offset;
    record->key = key;
    record->identifier = strdup(identifier);
    return record;
}

void free_record(Record* record) {
    if (record) {
        free(record->identifier);
        free(record);
    }
}

unsigned char* compute_md5(const unsigned char* data, size_t length) {
    unsigned char* digest = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    if (!digest) return NULL;
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, data, length);
    MD5_Final(digest, &md5);
    return digest;
}

void process_tiff(const char* filename) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filename);
        return;
    }

    uint16 bitsPerSample, samplesPerPixel;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);

    Record* records = NULL;
    size_t capacity = 1024;
    size_t count = 0;

    while (TIFFReadDirectory(tif)) {
        if (count >= capacity) {
            capacity *= 2;
            records = realloc(records, capacity * sizeof(Record));
            if (!records) {
                fprintf(stderr, "Memory allocation failed\n");
                TIFFClose(tif);
                return;
            }
        }

        long offset = TIFFCurrentDirectoryOffset(tif);
        int key = count + 1; // Example key generation
        const char* identifier = "example_identifier"; // Example identifier

        records[count++] = *create_record(offset, key, identifier);
    }

    for (size_t i = 0; i < count; ++i) {
        Record record = records[i];
        unsigned char* md5_digest = compute_md5((unsigned char*)&record, sizeof(Record));
        if (md5_digest) {
            printf("MD5: ");
            for (int j = 0; j < MD5_DIGEST_LENGTH; ++j) {
                printf("%02x", md5_digest[j]);
            }
            printf("\n");
            free(md5_digest);
        } else {
            fprintf(stderr, "Failed to compute MD5\n");
        }
        free_record(&record);
    }

    free(records);
    TIFFClose(tif);
}

int main() {
    process_tiff("example.tiff");
    return 0;
}
