    srand(time(NULL));

    // Allocate memory for keys array
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys array.\n");
        return NULL;
    }

    // Populate keys array with sequential integers
    for (int i = 0; i < num_records; ++i) {
        keys[i] = i + 1;
    }

    // Allocate memory for offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array.\n");
        free(keys);
        return NULL;
    }

    // Populate offsets array with random values
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
    }

    // Allocate memory for records array
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        free(keys);
        free(offsets);
        return NULL;
    }

    // Populate records array with random values and offset pointers
    for (int i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].offset_ptr = &offsets[i % num_records];
    }

    // Free allocated memory upon successful completion
    free(offsets);

    return records;
}

