use hyper::{Client, Request, Uri};
use hyper_tls::HttpsConnector;
use std::time::Duration;

// Define a custom error type for HTTP client operations
#[derive(Debug)]
enum HttpClientError {
    Hyper(hyper::Error),
    Io(std::io::Error),
}

impl From<hyper::Error> for HttpClientError {
    fn from(err: hyper::Error) -> Self {
        HttpClientError::Hyper(err)
    }
}

impl From<std::io::Error> for HttpClientError {
    fn from(err: std::io::Error) -> Self {
        HttpClientError::Io(err)
    }
}

// Define a struct to hold global defaults
struct GlobalDefaults {
    timeout: Duration,
    headers: hyper::header::HeaderMap,
}

impl Default for GlobalDefaults {
    fn default() -> Self {
        GlobalDefaults {
            timeout: Duration::from_secs(10),
            headers: hyper::header::HeaderMap::new(),
        }
    }
}

// Define a struct to hold per-request settings
struct RequestSettings {
    timeout: Option<Duration>,
    headers: Option<hyper::header::HeaderMap>,
}

impl Default for RequestSettings {
    fn default() -> Self {
        RequestSettings {
            timeout: None,
            headers: None,
        }
    }
}

// Define the HTTP client library
pub struct HttpClient {
    client: Client<HttpsConnector, hyper::Body>,
    global_defaults: GlobalDefaults,
}

impl HttpClient {
    // Create a new instance of the HTTP client with default settings
    pub fn new() -> Result<Self, HttpClientError> {
        let https = HttpsConnector::new();
        Ok(HttpClient {
            client: Client::builder().build(https),
            global_defaults: GlobalDefaults::default(),
        })
    }

    // Set global defaults for timeouts and headers
    pub fn set_global_defaults(&mut self, timeout: Duration, headers: hyper::header::HeaderMap) {
        self.global_defaults.timeout = timeout;
        self.global_defaults.headers = headers;
    }

    // Send a synchronous HTTP request with customizable settings
    pub async fn send_request(
        &self,
        method: hyper::Method,
        uri: Uri,
        body: Option<hyper::Body>,
        settings: RequestSettings,
    ) -> Result<hyper::Response<hyper::Body>, HttpClientError> {
        let mut req = Request::builder()
            .method(method)
            .uri(uri)
            .body(body.unwrap_or_default())
            .map_err(|err| err.into())?;

        if let Some(timeout) = settings.timeout.or(self.global_defaults.timeout) {
            req.extensions_mut().insert(hyper::header::TIMEOUT, timeout);
        }

        if let Some(headers) = settings.headers.or_else(|| self.global_defaults.headers.clone()) {
            for (key, value) in headers.iter() {
                req.headers_mut().insert(key, value.clone());
            }
        }

        self.client.request(req).await.map_err(|err| err.into())
    }

    // Send an asynchronous HTTP request with customizable settings
    pub async fn send_request_async(
        &self,
        method: hyper::Method,
        uri: Uri,
        body: Option<hyper::Body>,
        settings: RequestSettings,
    ) -> Result<hyper::Response<hyper::Body>, HttpClientError> {
        self.send_request(method, uri, body, settings).await
    }
}
