#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <time.h>

#define MAX_FILE_SIZE 1024 * 1024 // 1 MB
#define MAX_PROCESSING_TIME 30 // seconds

typedef struct {
    char* directory_path;
    char* filter_string;
    void (*transformation_rule)(char*);
} LogProcessorConfig;

void process_log_file(const char* file_path, const LogProcessorConfig* config) {
    FILE* input_file = fopen(file_path, "r");
    if (!input_file) {
        perror("Failed to open log file for reading");
        return;
    }

    FILE* output_file = fopen("aggregated_output.txt", "a");
    if (!output_file) {
        perror("Failed to open aggregated output file for writing");
        fclose(input_file);
        return;
    }

    char buffer[1024];
    clock_t start_time = clock();
    while (fgets(buffer, sizeof(buffer), input_file)) {
        if ((clock() - start_time) / CLOCKS_PER_SEC > MAX_PROCESSING_TIME) {
            fprintf(stderr, "Processing time limit exceeded for file: %s\n", file_path);
            break;
        }

        config->transformation_rule(buffer);
        if (ftell(output_file) + strlen(buffer) > MAX_FILE_SIZE) {
            fprintf(stderr, "Output file size limit reached for file: %s\n", file_path);
            break;
        }
        fputs(buffer, output_file);
    }

    fclose(input_file);
    fclose(output_file);
}

void process_directory(const LogProcessorConfig* config) {
    DIR* dir = opendir(config->directory_path);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    struct dirent* entry;
    int processed_files = 0;

    while ((entry = readdir(dir)) != NULL) {
        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", config->directory_path, entry->d_name);

        if (entry->d_type == DT_REG && strstr(entry->d_name, config->filter_string) != NULL) {
            process_log_file(file_path, config);
            processed_files++;
        }
    }

    closedir(dir);
    printf("Processed %d files\n", processed_files);
}

void transformation_rule(char* line) {
    // Example transformation: Convert all characters to uppercase
    for (int i = 0; line[i]; i++) {
        line[i] = toupper(line[i]);
    }
}

int main() {
    LogProcessorConfig config = {
        .directory_path = "/path/to/logs",
        .filter_string = "error",
        .transformation_rule = transformation_rule
    };

    process_directory(&config);

    return 0;
}
