#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define MIN_POOL_SIZE 2
#define MAX_POOL_SIZE 10
#define TIMEOUT_SECONDS 60

typedef enum { LOW, MEDIUM, HIGH } Priority;

typedef struct {
    pid_t pid;
    int priority;
    time_t start_time;
} Process;

Process process_pool[MAX_POOL_SIZE];
int pool_size = MIN_POOL_SIZE;

void log_process_exit(pid_t pid, int status) {
    FILE *log_file = fopen("process_log.txt", "a");
    if (log_file != NULL) {
        time_t current_time = time(NULL);
        fprintf(log_file, "%s - Process %d exited with status %d\n", ctime(&current_time), pid, status);
        fclose(log_file);
    }
}

void handle_signal(int signum) {
    // Custom signal handler logic here
    printf("Signal %d received\n", signum);
}

int execute_command(const char *command, Priority priority) {
    if (pool_size >= MAX_POOL_SIZE) {
        return 0; // Pool is full
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        signal(SIGINT, handle_signal);
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        process_pool[pool_size].pid = pid;
        process_pool[pool_size].priority = priority;
        process_pool[pool_size].start_time = time(NULL);
        pool_size++;
        return 1; // Process started successfully
    }
}

int manage_process_pool(const char *command, Priority priority) {
    if (!execute_command(command, priority)) {
        return 0; // Failed to start process
    }

    int all_completed = 0;
    while (!all_completed) {
        for (int i = 0; i < pool_size; i++) {
            pid_t pid = waitpid(process_pool[i].pid, NULL, WNOHANG);
            if (pid == -1) {
                perror("waitpid");
                return 0;
            } else if (pid == 0) {
                // Process is still running
                time_t current_time = time(NULL);
                if (current_time - process_pool[i].start_time > TIMEOUT_SECONDS) {
                    kill(process_pool[i].pid, SIGKILL);
                    log_process_exit(process_pool[i].pid, -1);
                    pool_size--;
                }
            } else {
                // Process has completed
                log_process_exit(pid, 0);
                for (int j = i; j < pool_size - 1; j++) {
                    process_pool[j] = process_pool[j + 1];
                }
                pool_size--;
                if (pool_size == 0) {
                    all_completed = 1;
                }
            }
        }

        // Adjust pool size based on system load
        // ...

        sleep(1); // Check every second
    }

    return 1; // All processes completed successfully
}

int main() {
    const char *command = "sleep 30"; // Example command
    Priority priority = MEDIUM;
    int result = manage_process_pool(command, priority);
    printf("All processes %s\n", result ? "completed successfully" : "failed or timed out");
    return result;
}
