typedef struct {
    char* identifier;
    float value;
    int x, y;
    char* base64_password;
    void* connection_object;
    void (*callback_function)();
} PlotElement;

PlotElement* create_plot_element(const char* identifier, float value, int x, int y, const char* base64_password, void* connection_object, void (*callback_function)()) {
    if (base64_password == NULL || *base64_password == '\0') {
        return NULL; // Error: Password is empty or NULL
    }
    if (connection_object == NULL) {
        return NULL; // Error: Connection object is NULL
    }
    if (callback_function == NULL) {
        return NULL; // Error: Callback function is NULL
    }

    PlotElement* element = (PlotElement*)malloc(sizeof(PlotElement));
    if (element == NULL) {
        return NULL; // Memory allocation failed
    }

    element->identifier = strdup(identifier);
    element->value = value;
    element->x = x;
    element->y = y;

    size_t password_len = strlen(base64_password);
    element->base64_password = (char*)malloc(password_len + 1);
    if (element->base64_password == NULL) {
        free(element->identifier);
        free(element);
        return NULL; // Memory allocation failed
    }
    strcpy(element->base64_password, base64_password);

    element->connection_object = connection_object;
    element->callback_function = callback_function;

    return element;
}

void destroy_plot_element(PlotElement* element) {
    if (element != NULL) {
        free(element->identifier);
        free(element->base64_password);
        free(element);
    }
}
