typedef struct {
    long offset;
    int key;
    char* identifier;
    int status;
} DataRecord;

DataRecord* initializeDataRecords(int numRecords, int arraySize, int range) {
    srand(time(NULL));
    const char* chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    DataRecord* records = (DataRecord*)malloc(numRecords * sizeof(DataRecord));
    long* offsets = (long*)malloc(arraySize * sizeof(long));
    int* keys = (int*)malloc(arraySize * sizeof(int));
    char** identifiers = (char**)malloc(arraySize * sizeof(char*));
    int* statuses = (int*)malloc(arraySize * sizeof(int));

    if (!records || !offsets || !keys || !identifiers || !statuses) {
        free(records);
        free(offsets);
        free(keys);
        free(identifiers);
        free(statuses);
        return NULL;
    }

    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = offsets[i] = i * 10L;
        records[i].key = keys[i] = i + 1;
        records[i].identifier = (char*)malloc(21 * sizeof(char));
        if (!records[i].identifier) {
            for (int j = 0; j < i; ++j) free(records[j].identifier);
            free(records);
            free(offsets);
            free(keys);
            free(identifiers);
            free(statuses);
            return NULL;
        }
        for (int j = 0; j < 20; ++j) {
            records[i].identifier[j] = chars[rand() % 62];
        }
        records[i].identifier[20] = '\0';
        records[i].status = statuses[i] = rand() % 2 ? 'success' : 'failure';
    }

    free(offsets);
    free(keys);
    free(identifiers);
    free(statuses);

    return records;
}

int main() {
    int numRecords = 1000;
    int arraySize = 500;
    int range = 100;

    DataRecord* records = initializeDataRecords(numRecords, arraySize, range);
    if (records) {
        for (int i = 0; i < numRecords; ++i) {
            printf("Record %d: Offset=%ld, Key=%d, Identifier=%s, Status=%c\n",
                   i, records[i].offset, records[i].key, records[i].identifier, records[i].status);
        }
        for (int i = 0; i < numRecords; ++i) free(records[i].identifier);
        free(records);
    } else {
        printf("Failed to initialize data records.\n");
    }

    return 0;
}
