    public async Task<DataTableReader> SendDataToDatabase(byte[] data)
    {
        if (data == null || data.Length == 0)
            throw new ArgumentException("Byte array cannot be null or empty.");

        var connectionString = GetConnectionStringFromKMS();
        var commandText = "YourStoredProcedureName";
        var timeout = int.Parse(GetConfigValue("DefaultTimeout"));

        for (int attempt = 1; ; attempt++)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    using (var command = new SqlCommand(commandText, connection))
                    {
                        command.CommandType = CommandType.StoredProcedure;
                        command.CommandTimeout = timeout;

                        AddParametersToCommand(command, data);

                        using (var reader = await command.ExecuteReaderAsync(CommandBehavior.CloseConnection))
                        {
                            return reader;
                        }
                    }
                }
            }
            catch (SqlException ex) when (ex.Number == -2 || ex.Number >= 4060 && ex.Number <= 4091)
            {
                if (attempt > 5)
                    throw;

                await Task.Delay((int)Math.Pow(2, attempt) * 100);
            }
        }
    }

    private string GetConnectionStringFromKMS()
    {
        // Implement logic to retrieve connection string from KMS
        return "your_connection_string";
    }

    private string GetConfigValue(string key)
    {
        // Implement logic to load configuration value from XML file
        return System.Xml.Linq.XDocument.Load(_configFilePath).Descendants("appSettings").Elements().Where(e => e.Attribute("key").Value == key).Select(e => e.Attribute("value").Value).FirstOrDefault();
    }

    private void AddParametersToCommand(SqlCommand command, byte[] data)
    {
        // Implement logic to add parameters to the SQL command
        command.Parameters.AddWithValue("@Data", data);
    }
}
