#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int value;
    int ref_count;
    struct node* next;
} Node;

Node* create_node(int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->value = value;
    new_node->ref_count = 1;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, int position, int value) {
    Node* new_node = create_node(value);
    if (position == 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        for (int i = 0; i < position - 1 && current != NULL; i++) {
            current = current->next;
        }
        if (current == NULL) {
            fprintf(stderr, "Position out of bounds\n");
            free(new_node);
            return;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void update_nodes(Node* head, int factor) {
    Node* current = head;
    while (current != NULL) {
        current->value *= factor;
        current = current->next;
    }
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
