    private readonly ConcurrentDictionary<string, byte[]> _ivCache = new ConcurrentDictionary<string, byte[]>();
    private readonly ILogger<TripleDESDecryptor> _logger;
    private readonly int _cacheSize;

    public TripleDESDecryptor(ILoggerFactory loggerFactory, int cacheSize)
    {
        _logger = loggerFactory.CreateLogger<TripleDESDecryptor>();
        _cacheSize = cacheSize;
    }

    public string Decrypt(string messageId, string base64EncodedMessage)
    {
        if (!_keyCache.TryGetValue(messageId, out var key))
        {
            key = LoadKeyFromConfigService(messageId);
            _keyCache.TryAdd(messageId, key);
        }

        if (!_ivCache.TryGetValue(messageId, out var iv))
        {
            iv = LoadIVFromConfigService(messageId);
            _ivCache.TryAdd(messageId, iv);
        }

        try
        {
            using (var des = new TripleDESCryptoServiceProvider())
            {
                des.Key = key;
                des.IV = iv;
                des.Mode = CipherMode.CBC;
                des.Padding = PaddingMode.PKCS7;

                var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
                var decryptedBytes = des.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

                var decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);
                VerifyChecksum(decryptedMessage);

                return decryptedMessage;
            }
        }
        catch (Exception ex)
