using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using StackExchange.Redis;

public class MessageProcessor
{
    private readonly ConnectionMultiplexer _redisConnection;
    private readonly IDatabase _database;
    private readonly ISubscriber _subscriber;
    private readonly ConcurrentDictionary<string, DateTime> _latencyLog = new ConcurrentDictionary<string, DateTime>();

    public MessageProcessor(string redisConnectionString)
    {
        _redisConnection = ConnectionMultiplexer.Connect(redisConnectionString);
        _database = _redisConnection.GetDatabase();
        _subscriber = _redisConnection.GetSubscriber();
    }

    public async Task StartProcessingAsync()
    {
        _subscriber.Subscribe("message_queue", async (channel, message) =>
        {
            try
            {
                var latencyStart = DateTime.UtcNow;
                var md5Hash = ComputeMd5Hash(message);
                await PersistToDatabaseAsync(md5Hash);
                var latencyEnd = DateTime.UtcNow;
                _latencyLog.TryAdd(message, latencyEnd - latencyStart);
            }
            catch (Exception ex)
            {
                LogError(ex.Message);
            }
        });
    }

    private string ComputeMd5Hash(string message)
    {
        using (var md5 = MD5.Create())
        {
            var inputBytes = Encoding.ASCII.GetBytes(message);
            var hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    private async Task PersistToDatabaseAsync(string md5Hash)
    {
        await _database.StringSetAsync(md5Hash, "Processed");
    }

    private void LogError(string errorMessage)
    {
        Console.Error.WriteLine($"Error: {errorMessage}");
    }
}
```

This code snippet provides a basic implementation of the described functionality. It uses StackExchange.Redis for interacting with a Redis database and subscribes to a message queue using the `ISubscriber` interface. The `StartProcessingAsync` method listens for messages on the "message_queue" channel, computes their MD5 hashes, persists the results in Redis, logs processing latency, and handles exceptions gracefully.

Please note that this is a simplified example and may require additional features such as connection pooling, error handling, and performance optimization based on specific requirements and constraints.']

