import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.HashMap;
import java.util.Map;

public class SerializationUtil {

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws SerializationException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            Object obj = ois.readObject();
            if (!clazz.isInstance(obj)) {
                throw new SerializationException("Deserialized object is not an instance of " + clazz.getName());
            }
            return clazz.cast(obj);
        } catch (IOException | ClassNotFoundException e) {
            throw new SerializationException("Failed to deserialize data", e);
        }
    }

    public static <T> byte[] serialize(T obj) throws SerializationException {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject(obj);
            return bos.toByteArray();
        } catch (IOException e) {
            throw new SerializationException("Failed to serialize object", e);
        }
    }

    public static class SerializationException extends Exception {
        public SerializationException(String message, Throwable cause) {
            super(message, cause);
        }

        public SerializationException(String message) {
            super(message);
        }
    }
}
