#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct UeState {
    int ue_id;
    int signal_strength;
    int* uplink_grants;
    size_t grant_count;
    time_t last_activity;
} UeState;

typedef struct DynamicArray {
    UeState** data;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (UeState**)calloc(initial_capacity, sizeof(UeState*));
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void dynamic_array_destroy(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]->uplink_grants);
        free(array->data[i]);
    }
    free(array->data);
    free(array);
}

void dynamic_array_add(DynamicArray* array, UeState* state) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->data = (UeState**)realloc(array->data, array->capacity * sizeof(UeState*));
    }
    array->data[array->size++] = state;
}

// Additional functions for updating, evicting stale entries, and generating statistics would be implemented here.
