# Import necessary libraries
from typing import Any, Dict, Optional
import threading
import time

class KeyValueStore:
    def __init__(self):
        self.store = {}
        self.lock = threading.Lock()

    def set(self, key: str, value: Any, metadata: Optional[Dict[str, Any]] = None) -> None:
        with self.lock:
            if key not in self.store:
                self.store[key] = {'value': value, 'metadata': metadata}
            else:
                self.store[key]['value'] = value
                self.store[key]['metadata'] = metadata

    def get(self, key: str) -> Any:
        with self.lock:
            return self.store.get(key, {}).get('value', None)

    def delete(self, key: str) -> None:
        with self.lock:
            if key in self.store:
                del self.store[key]

class DistributedKeyValueStore(KeyValueStore):
    def __init__(self, nodes: int):
        super().__init__()
        self.nodes = [KeyValueStore() for _ in range(nodes)]

    def set(self, key: str, value: Any, metadata: Optional[Dict[str, Any]] = None) -> None:
        for node in self.nodes:
            node.set(key, value, metadata)

    def get(self, key: str) -> Any:
        values = [node.get(key) for node in self.nodes]
        return values

    def delete(self, key: str) -> None:
        for node in self.nodes:
            node.delete(key)

# Example usage
if __name__ == "__main__":
    store = DistributedKeyValueStore(3)
    store.set("key1", "value1")
    print(store.get("key1"))
    store.delete("key1")
```

This code provides a basic implementation of a distributed key-value store using multiple instances of a `KeyValueStore` class. Each instance represents a node in the cluster. The `DistributedKeyValueStore` class manages operations across all nodes, ensuring data consistency and availability through simple replication.

For a more robust solution, consider implementing additional features such as:
- **Consistency Models**: Implement different consistency models (e.g., eventual consistency) based on client requirements.
- **Node Failure Handling**: Use mechanisms like heartbeats to detect node failures and implement failover strategies.
- **Cache Management**: Integrate a distributed cache layer using libraries like Redis or Memcached.
- **Resource Utilization**: Optimize memory and CPU usage by using efficient data structures and algorithms.
- **Concurrency Control**: Implement robust concurrency control mechanisms, such as optimistic locking with versioning.
- **Network Latency and Load Balancing**: Use load balancers to distribute network traffic evenly across nodes.
- **Scalability and Elasticity**: Design the system to scale horizontally by adding more nodes dynamically.

This basic implementation serves as a starting point for understanding the key components of a distributed key-value store.']

