fn manage_directory_structure(
    directory_name: &str,
    base_path: &str,
    max_records: usize,
) -> io::Result<()> {
    let config_dir = format!("{}/{}", base_path, directory_name);
    let env_config_dir = env::var("CONFIG_DIR").unwrap_or_else(|_| String::new());

    if env_config_dir != config_dir {
        fs::create_dir_all(&config_dir)?;
        env::set_var("CONFIG_DIR", &config_dir);
        println!("Created and set CONFIG_DIR to: {}", config_dir);
    } else {
        println!("Using existing CONFIG_DIR: {}", config_dir);
    }

    let mut records = Vec::new();
    for i in 0..max_records {
        if max_records <= 0 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "Max records must be positive"));
        }
        let record = NFAPI_CRC_INDICATION_PDU_T::new(i as u32, (i % 100) as u16);
        if !record.is_valid() {
            eprintln!("Validation failed for record: {:?}", record);
            continue;
        }
        records.push(record);
    }

    let file_path = Path::new(&config_dir).join("records.bin");
    let mut file = File::create(file_path)?;
    for record in records {
        file.write_all(&record.to_le_bytes())?;
    }

    Ok(())
}
