import json
import xml.etree.ElementTree as ET
import yaml
import pandas as pd
import pyarrow.parquet as pq
from abc import ABC, abstractmethod
from concurrent.futures import ThreadPoolExecutor
from functools import lru_cache

class DataFormatHandler(ABC):
    @abstractmethod
    def parse(self, data):
        pass

    @abstractmethod
    def format(self, data):
        pass

class JSONHandler(DataFormatHandler):
    def parse(self, data):
        return json.loads(data)

    def format(self, data):
        return json.dumps(data)

class XMLHandler(DataFormatHandler):
    def parse(self, data):
        return ET.fromstring(data)

    def format(self, data):
        return ET.tostring(data, encoding='unicode')

class YAMLHandler(DataFormatHandler):
    def parse(self, data):
        return yaml.safe_load(data)

    def format(self, data):
        return yaml.dump(data)

class CSVHandler(DataFormatHandler):
    def parse(self, data):
        return pd.read_csv(pd.compat.StringIO(data))

    def format(self, data):
        return data.to_csv(index=False)

class ParquetHandler(DataFormatHandler):
    def parse(self, data):
        return pq.read_table(data)

    def format(self, data):
        return pq.write_table(data, 'output.parquet')

class DataProcessor:
    def __init__(self):
        self.handlers = {
            'json': JSONHandler(),
            'xml': XMLHandler(),
            'yaml': YAMLHandler(),
            'csv': CSVHandler(),
            'parquet': ParquetHandler()
        }

    def process(self, data, format_type):
        handler = self.handlers.get(format_type)
        if handler:
            return handler.parse(data)
        else:
            raise ValueError(f"Unsupported format type: {format_type}")

class DataExporter:
    def __init__(self):
        self.handlers = {
            'json': JSONHandler(),
            'xml': XMLHandler(),
            'yaml': YAMLHandler(),
            'csv': CSVHandler(),
            'parquet': ParquetHandler()
        }

    @lru_cache(maxsize=None)
    def export(self, data, format_type):
        handler = self.handlers.get(format_type)
        if handler:
            return handler.format(data)
        else:
            raise ValueError(f"Unsupported format type: {format_type}")

class DataPipeline:
    def __init__(self, processor, exporter):
        self.processor = processor
        self.exporter = exporter

    def run(self, data, input_format, output_format):
        processed_data = self.processor.process(data, input_format)
        return self.exporter.export(processed_data, output_format)

# Example usage
processor = DataProcessor()
exporter = DataExporter()
pipeline = DataPipeline(processor, exporter)

data = '{"name": "John", "age": 30}'
output = pipeline.run(data, 'json', 'csv')
print(output)
```']

