#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define SEED_VALUE 0x12345678

typedef struct {
    uint32_t RNTI;
    uint32_t CRCFLAG;
    time_t timestamp;
    int sequence_number;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_indication_pdu_list[MAX_ENTRIES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void calculate_crc_flag(RX_UE_INFORMATION_TAG *tag) {
    tag->CRCFLAG = tag->RNTI ^ SEED_VALUE;
}

int add_entry(uint32_t RNTI, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (nfaapi_crc_indication_pdu_list[i] == NULL) {
            nfaapi_crc_indication_pdu_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (nfaapi_crc_indication_pdu_list[i] == NULL) {
                pthread_mutex_unlock(&mutex);
                return -1; // Memory allocation failed
            }
            nfaapi_crc_indication_pdu_list[i]->tag.RNTI = RNTI;
            calculate_crc_flag(&nfaapi_crc_indication_pdu_list[i]->tag);
            nfaapi_crc_indication_pdu_list[i]->pdu = pdu;
            nfaapi_crc_indication_pdu_list[i]->tag.timestamp = time(NULL);
            nfaapi_crc_indication_pdu_list[i]->tag.sequence_number = i + 1;
            pthread_mutex_unlock(&mutex);
            return 0; // Entry added successfully
        }
    }
    pthread_mutex_unlock(&mutex);
    return -2; // List is full
}

void free_entries() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (nfaapi_crc_indication_pdu_list[i] != NULL) {
            free(nfaapi_crc_indication_pdu_list[i]);
            nfaapi_crc_indication_pdu_list[i] = NULL;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void *update_rnti(void *arg) {
    uint32_t RNTI = *(uint32_t *)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu; // Assume this is populated from external data source
    add_entry(RNTI, pdu);
    return NULL;
}

int main() {
    pthread_t thread_id;
    uint32_t RNTI = 12345;

    if (pthread_create(&thread_id, NULL, update_rnti, &RNTI) != 0) {
        perror("Failed to create thread");
        return -1;
    }

    pthread_join(thread_id, NULL);

    free_entries();

    return 0;
}
