#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

// Function to resolve DNS and return IP as u_char array
u_char* dnsResolve(const char* hostname) {
    struct addrinfo hints, *res;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    void *addr;
    char *ipver;

    // get the pointer to the address itself,
    // different fields in IPv4 and IPv6:
    if (res->ai_family == AF_INET) { // IPv4
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        addr = &(ipv4->sin_addr);
        ipver = "IPv4";
    } else { // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        addr = &(ipv6->sin6_addr);
        ipver = "IPv6";
    }

    // convert the IP to a string and print it:
    inet_ntop(res->ai_family, addr, ipstr, sizeof ipstr);
    printf("IP: %s\n", ipstr);

    freeaddrinfo(res); // all done with this structure

    u_char* ipArray = (u_char*)malloc(16 * sizeof(u_char));
    if (ipver == "IPv4") {
        memcpy(ipArray, addr, 4);
    } else {
        memcpy(ipArray, addr, 16);
    }

    return ipArray;
}

// Callback function for DOM traversal
int callback(xmlNode* node, void* userData) {
    // Implement attribute checking logic here
    // Return 0 to continue traversal, non-zero to stop
    return 0;
}

// Function to traverse HTML DOM and apply callback
void traverseDOM(xmlDocPtr doc, const char* selector, int (*callback)(xmlNode*, void*), void* userData) {
    xmlXPathContextPtr xpathCtx = xmlXPathNewContext(doc);
    if (xpathCtx == NULL) {
        fprintf(stderr, "Error creating XPath context\n");
        return;
    }

    xmlXPathObjectPtr xpathObj = xmlXPathEvalExpression(BAD_CAST selector, xpathCtx);
    if (xpathObj == NULL || xpathObj->type != XPATH_NODESET) {
        fprintf(stderr, "Error evaluating XPath expression\n");
        xmlXPathFreeContext(xpathCtx);
        return;
    }

    xmlNodeSetPtr nodeset = xpathObj->nodesetval;

    for (int i = 0; i < nodeset->nodeNr; i++) {
        if (callback(nodeset->nodeTab[i], userData) != 0) {
            break;
        }
    }

    xmlXPathFreeObject(xpathObj);
    xmlXPathFreeContext(xpathCtx);
}

// Main function to demonstrate usage
int main() {
    // Load HTML document
    xmlDocPtr doc = htmlReadFile("example.html", NULL, HTML_PARSE_NOERROR | HTML_PARSE_NOWARNING);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse HTML\n");
        return 1;
    }

    // Resolve DNS for a hostname
    u_char* ipArray = dnsResolve("example.com");
    if (ipArray != NULL) {
        free(ipArray);
    }

    // Traverse DOM and apply callback
    traverseDOM(doc, "//div[@class='example']", callback, NULL);

