#include <pthread.h>

#define MAX_ENTRIES 50000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    L1_RX_BUFFER_TAG buffer_tag;
    uint32_t crcflag;
    time_t timestamp;
    uint32_t sequence_number;
} NFAPI_L1_RX_BUFFER_PDU_T;

typedef struct {
    NFAPI_L1_RX_BUFFER_PDU_T *entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(DynamicList *list, NFAPI_L1_RX_BUFFER_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_L1_RX_BUFFER_PDU_T* get_entry(DynamicList *list, size_t index) {
    if (index >= list->count) return NULL;
    return list->entries[index];
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void update_rnti(DynamicList *list, uint16_t old_rnti, uint16_t new_rnti) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i]->rnti == old_rnti) {
            list->entries[i]->rnti = new_rnti;
            // Recalculate CRCFLAG based on new RNTI and current time
            list->entries[i]->crcflag = calculate_crc(list->entries[i], time(NULL));
        }
    }
    pthread_mutex_unlock(&list->lock);
}

uint32_t calculate_crc(NFAPI_L1_RX_BUFFER_PDU_T *entry, time_t seed) {
    // Implement rolling hash function using RNTI and seed
    return (entry->rnti + seed) % UINT32_MAX;
}
