#include <pthread.h>

typedef struct NetworkEventRecord {
    int Timestamp;
    char EventType[50];
    struct EventDetails {
        char Source[100];
        char Target[100];
        char Status[20];
    } EventDetails;
} NetworkEventRecord;

typedef struct Node {
    NetworkEventRecord data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertEvent(LinkedList* list, NetworkEventRecord event) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = event;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void deleteEvent(LinkedList* list, int timestamp) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->data.Timestamp != timestamp) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Event not found
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

void* monitorPerformance(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    while (1) {
        // Implement performance monitoring logic here
        printf("Current list size: %d\n", getLinkedListSize(list));
        sleep(1); // Monitor every second
    }
    return NULL;
}

int getLinkedListSize(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    int count = 0;
    Node* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

int main() {
    LinkedList eventList;
    initLinkedList(&eventList);

    // Example usage
    NetworkEventRecord event1 = {1, "Connection", {"SourceA", "TargetB", "Established"}};
    insertEvent(&eventList, event1);

    NetworkEventRecord event2 = {2, "Disconnection", {"SourceC", "TargetD", "Terminated"}};
    insertEvent(&eventList, event2);

    deleteEvent(&eventList, 1);

    pthread_t monitorThread;
    pthread_create(&monitorThread, NULL, monitorPerformance, &eventList);
    pthread_join(monitorThread, NULL);

    return 0;
}
