#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* str;
    int num;
    float fnum;
} MyStruct;

MyStruct* allocateStructures(int size, const char** external_strings, int string_length_limit, int* int_range, float* float_range, unsigned long seed) {
    if (size <= 0 || string_length_limit <= 0) {
        return NULL; // Handle edge cases
    }

    MyStruct* array = (MyStruct*)malloc(size * sizeof(MyStruct));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < size; ++i) {
        array[i].str = (char*)malloc(string_length_limit);
        if (!array[i].str) {
            perror("String memory allocation failed");
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(array[j].str);
            }
            free(array);
            return NULL;
        }

        if (external_strings && external_strings[i]) {
            strncpy(array[i].str, external_strings[i], string_length_limit - 1);
            array[i].str[string_length_limit - 1] = '\0';
        } else {
            strcpy(array[i].str, "");
        }

        int min_int_range = int_range ? int_range[0] : -1000;
        int max_int_range = int_range ? int_range[1] : 1000;
        array[i].num = rand() % (max_int_range - min_int_range + 1) + min_int_range;

        float min_float_range = float_range ? float_range[0] : -1000.0f;
        float max_float_range = float_range ? float_range[1] : 1000.0f;
        array[i].fnum = (float)(rand() % ((int)((max_float_range - min_float_range) * 1000 + 1))) / 1000.0f + min_float_range;
    }

    return array;
}

// Example usage
int main() {
    const char* strings[] = {"Hello", "World"};
    MyStruct* structs = allocateStructures(2, strings, 128, NULL, NULL, time(NULL));
    if (structs) {
        // Use the structures...
        for (int i = 0; i < 2; ++i) {
            free(structs[i].str);
        }
        free(structs);
    }
    return 0;
}
