    srand(time(NULL));

    Transaction* transactions = (Transaction*)malloc(numTransactions * sizeof(Transaction));
    if (!transactions) {
        return NULL;
    }

    int currentBudget = budget;
    for (int i = 0; i < numTransactions; ++i) {
        transactions[i].id = i + 1;
        transactions[i].amount = rand() % (maxAmount - minAmount + 1) + minAmount;
        if (transactions[i].amount > currentBudget) {
            transactions[i].amount = currentBudget;
        }
        currentBudget -= transactions[i].amount;

        // Simulate status based on transaction amount
        if (transactions[i].amount == maxAmount) {
            strcpy(transactions[i].status, "pending");
        } else {
            strcpy(transactions[i].status, "completed");
        }
    }

    return transactions;
}

int main() {
