    int maxID = 20;
    int minAmount = 50;
    int maxAmount = 100;
    int budget = 500;

    Transaction* transactions = processBatchTransactions(numTransactions, maxID, minAmount, maxAmount, budget);
    if (transactions) {
        for (int i = 0; i < numTransactions; ++i) {
            printf("Transaction %d: ID=%d, Amount=%d, Status=%s\n", i + 1, transactions[i].id, transactions[i].amount, transactions[i].status);
