#define MAX_ENTRIES 15000
#define SEED_VALUE 0x12345678

typedef struct {
    uint16_t RNTI;
    uint8_t CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t timestamp;
    uint16_t sequence_number;
    uint32_t unique_id;
    RX_UE_INFORMATION_TAG rx_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST;

CRC_LIST crc_list = {0};

void init_crc_list() {
    pthread_mutex_init(&crc_list.lock, NULL);
}

void destroy_crc_list() {
    for (size_t i = 0; i < crc_list.count; ++i) {
        free(crc_list.entries[i]);
    }
    pthread_mutex_destroy(&crc_list.lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_entry(uint16_t RNTI, uint8_t *mac_address, pid_t pid) {
    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) return NULL;

    entry->rx_tag.RNTI = RNTI;
    entry->rx_tag.CRCFLAG = RNTI ^ SEED_VALUE;
    entry->timestamp = (uint32_t)time(NULL);
    entry->sequence_number = rand();
    uint64_t unique_id = ((uint64_t)pid << 32) | (rand() & 0xFFFFFFFF);
    memcpy(&entry->unique_id, &unique_id, sizeof(uint32_t));

    return entry;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&crc_list.lock);
    if (crc_list.count < MAX_ENTRIES) {
        crc_list.entries[crc_list.count++] = entry;
    } else {
        // Handle full list, e.g., remove oldest entries
    }
    pthread_mutex_unlock(&crc_list.lock);
}

void* manage_crc_entries(void *arg) {
    while (1) {
        pthread_mutex_lock(&crc_list.lock);
        if (crc_list.count > 0 && time(NULL) - crc_list.entries[0]->timestamp > 3600) {
            free(crc_list.entries[0]);
            memmove(crc_list.entries, crc_list.entries + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (crc_list.count - 1));
            --crc_list.count;
        }
        pthread_mutex_unlock(&crc_list.lock);
        sleep(60); // Check every minute
    }
}

void serialize_crc_list(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    size_t count = crc_list.count;
    fwrite(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        fwrite(crc_list.entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

void deserialize_crc_list(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!entry) continue;

        fread(entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        add_entry(entry);
    }

    fclose(file);
}

uint32_t rolling_hash(const uint8_t *data, size_t length) {
    uint32_t hash = 0;
    for (size_t i = 0; i < length; ++i) {
        hash = (hash << 5) + hash + data[i];
    }
    return hash;
}

void validate_checksum(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        fread(&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        uint32_t expected_checksum = rolling_hash((uint8_t*)&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Compare expected_checksum with actual checksum from file
    }

    fclose(file);
}
