typedef struct Task {
    int id;
    int priority;
    char* description;
} Task;

typedef struct PriorityQueue {
    Task** tasks;
    size_t capacity;
    size_t size;
    int (*compare)(const void*, const void*);
} PriorityQueue;

PriorityQueue* create_priority_queue(size_t initial_capacity, int (*compare)(const void*, const void*)) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (!pq) return NULL;

    pq->tasks = (Task**)malloc(initial_capacity * sizeof(Task*));
    if (!pq->tasks) {
        free(pq);
        return NULL;
    }

    pq->capacity = initial_capacity;
    pq->size = 0;
    pq->compare = compare;

    return pq;
}

void destroy_priority_queue(PriorityQueue* pq) {
    for (size_t i = 0; i < pq->size; ++i) {
        free(pq->tasks[i]->description);
        free(pq->tasks[i]);
    }
    free(pq->tasks);
    free(pq);
}

int compare_tasks(const void* a, const void* b) {
    Task* task_a = *(Task**)a;
    Task* task_b = *(Task**)b;
    return task_b->priority - task_a->priority; // Max heap
}

void insert_task(PriorityQueue* pq, Task* task) {
    if (!pq || !task) return;

    if (pq->size == pq->capacity) {
        pq->capacity *= 2;
        pq->tasks = (Task**)realloc(pq->tasks, pq->capacity * sizeof(Task*));
        if (!pq->tasks) return;
    }

    pq->tasks[pq->size++] = task;
    size_t i = pq->size - 1;
    while (i > 0 && pq->compare(&pq->tasks[i], &pq->tasks[(i - 1) / 2]) < 0) {
        Task* temp = pq->tasks[i];
        pq->tasks[i] = pq->tasks[(i - 1) / 2];
        pq->tasks[(i - 1) / 2] = temp;
        i = (i - 1) / 2;
    }
}

Task* get_highest_priority_task(PriorityQueue* pq) {
    if (!pq || pq->size == 0) return NULL;

    Task* highest_priority_task = pq->tasks[0];
    pq->tasks[0] = pq->tasks[--pq->size];
    size_t i = 0;
    while (i * 2 + 1 < pq->size) {
        size_t left_child = i * 2 + 1;
        size_t right_child = i * 2 + 2;
        size_t max_child = left_child;

        if (right_child < pq->size && pq->compare(&pq->tasks[right_child], &pq->tasks[left_child]) < 0) {
            max_child = right_child;
        }

        if (pq->compare(&pq->tasks[i], &pq->tasks[max_child]) >= 0) break;

        Task* temp = pq->tasks[i];
        pq->tasks[i] = pq->tasks[max_child];
        pq->tasks[max_child] = temp;
        i = max_child;
    }

    return highest_priority_task;
}

void remove_highest_priority_task(PriorityQueue* pq) {
    if (!pq || pq->size == 0) return;

    pq->tasks[0] = pq->tasks[--pq->size];
    size_t i = 0;
    while (i * 2 + 1 < pq->size) {
        size_t left_child = i * 2 + 1;
        size_t right_child = i * 2 + 2;
        size_t max_child = left_child;

        if (right_child < pq->size && pq->compare(&pq->tasks[right_child], &pq->tasks[left_child]) < 0) {
            max_child = right_child;
        }

        if (pq->compare(&pq->tasks[i], &pq->tasks[max_child]) >= 0) break;

        Task* temp = pq->tasks[i];
        pq->tasks[i] = pq->tasks[max_child];
        pq->tasks[max_child] = temp;
        i = max_child;
    }
}

Task* read_task_from_input() {
    int id, priority;
    char description[256];

    if (scanf("%d", &id) != 1 || scanf("%d", &priority) != 1) return NULL;

    getchar(); // Consume newline character
