#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

typedef struct LogEntry {
    LogLevel level;
    time_t timestamp;
    int id;
    size_t message_length;
    char *message;
    struct LogEntry *next;
} LogEntry;

typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
} Logger;

void init_logger(Logger *logger) {
    logger->head = NULL;
    pthread_mutex_init(&logger->lock, NULL);
}

void add_log_entry(Logger *logger, LogLevel level, const char *message) {
    pthread_mutex_lock(&logger->lock);
    LogEntry *new_entry = (LogEntry *)malloc(sizeof(LogEntry));
    new_entry->level = level;
    new_entry->timestamp = time(NULL);
    new_entry->id = rand();
    new_entry->message_length = strlen(message);
    new_entry->message = strdup(message);
    new_entry->next = logger->head;
    logger->head = new_entry;
    pthread_mutex_unlock(&logger->lock);
}

void update_log_entry(Logger *logger, int id, LogLevel level, const char *message) {
    pthread_mutex_lock(&logger->lock);
    LogEntry *current = logger->head;
    while (current != NULL) {
        if (current->id == id) {
            current->level = level;
            free(current->message);
            current->message_length = strlen(message);
            current->message = strdup(message);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&logger->lock);
}

void filter_logs(Logger *logger, LogLevel min_level, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&logger->lock);
    LogEntry *current = logger->head;
    while (current != NULL) {
        if ((current->level >= min_level && current->timestamp >= start_time && current->timestamp <= end_time)) {
