    LogEntry *current = logger->head;
    while (current != NULL) {
        if ((time(NULL) - current->timestamp) > age_threshold) {
            // Implement log rotation logic here
            printf("Rotating log entry with ID: %d\n", current->id);
            // Move the log to secondary storage and compress it
            // ...
            // Remove the rotated log from the list
            LogEntry *temp = current;
            current = current->next;
            free(temp->message);
            free(temp);
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&logger->lock);
}

void destroy_logger(Logger *logger) {
    pthread_mutex_lock(&logger->lock);
    LogEntry *current = logger->head;
    while (current != NULL) {
        LogEntry *temp = current;
        current = current->next;
        free(temp->message);
        free(temp);
    }
    pthread_mutex_destroy(&logger->lock);
}
