#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define log levels
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARN,
    LOG_ERROR
} LogLevel;

// Function to initialize logging based on environment variables
void init_logging(LogLevel *log_level) {
    const char *env_log_level = getenv("LOG_LEVEL");
    if (env_log_level != NULL) {
        if (strcmp(env_log_level, "DEBUG") == 0) {
            *log_level = LOG_DEBUG;
        } else if (strcmp(env_log_level, "INFO") == 0) {
            *log_level = LOG_INFO;
        } else if (strcmp(env_log_level, "WARN") == 0) {
            *log_level = LOG_WARN;
        } else if (strcmp(env_log_level, "ERROR") == 0) {
            *log_level = LOG_ERROR;
        }
    } else {
        *log_level = LOG_INFO; // Default log level
    }
}

// Function to log messages based on the current log level
void log_message(LogLevel log_level, const char *message) {
    static LogLevel current_log_level = LOG_INFO;
    init_logging(&current_log_level);

    if (log_level >= current_log_level) {
        switch (log_level) {
            case LOG_DEBUG:
                printf("[DEBUG] %s\n", message);
                break;
            case LOG_INFO:
                printf("[INFO] %s\n", message);
                break;
            case LOG_WARN:
                printf("[WARN] %s\n", message);
                break;
            case LOG_ERROR:
                printf("[ERROR] %s\n", message);
                break;
        }
    }
}

// Function to derive a key using PBKDF2
int derive_key(const char *password, const unsigned char *salt, size_t salt_len, int iterations, size_t key_length, unsigned char *key) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, iterations, EVP_sha256(), key_length, key);
}

// Function to encrypt data using AES-128 in CBC mode
int encrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    size_t ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using AES-128 in CBC mode
int decrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return -1;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    size_t plaintext_len = len;

    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Example usage
int main() {
    unsigned char key[32];
    unsigned char iv[16];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    // Derive a key using PBKDF2
    derive_key("password", NULL, 0, 10000, sizeof(key), key);

    // Generate random IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        log_message(LOG_ERROR, "Failed to generate random IV");
        return -1;
    }

    // Encrypt data
    int ciphertext_len = encrypt_data(key, iv, plaintext, strlen((char *)plaintext), ciphertext);
    if (ciphertext_len < 0) {
        log_message(LOG_ERROR, "Encryption failed");
        return -1;
    }
    ciphertext[ciphertext_len] = '\0';

    // Decrypt data
    int decryptedtext_len = decrypt_data(key, iv, ciphertext, ciphertext_len, decryptedtext);
    if (decryptedtext_len < 0) {
        log_message(LOG_ERROR, "Decryption failed");
        return -1;
    }
    decryptedtext[decryptedtext_len] = '\0';

    // Log the results
    log_message(LOG_INFO, "Encrypted: %s", ciphertext);
    log_message(LOG_INFO, "Decrypted: %s", decryptedtext);

    return 0;
}
