#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    int count;
    int maxRecords;
    pthread_mutex_t mutex;
} RecordList;

int initRecordList(RecordList *list, int maxRecords) {
    list->maxRecords = maxRecords;
    list->count = 0;
    list->records = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxRecords * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->records) {
        return -1; // Memory allocation failed
    }
    pthread_mutex_init(&list->mutex, NULL);
    return 0;
}

void freeRecordList(RecordList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->records);
    list->records = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int addRecord(RecordList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->maxRecords) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    NFAPI_CRC_INDICATION_PDU_T *record = &list->records[list->count++];
    record->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    record->RNTI = RNTI;
    record->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    record->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int serializeRecords(RecordList *list, const char *filename) {
    pthread_mutex_lock(&list->mutex);
    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Failed to open file
    }
    fwrite(list->records, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int deserializeRecords(RecordList *list, const char *filename) {
    pthread_mutex_lock(&list->mutex);
    FILE *file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Failed to open file
    }
    list->count = fread(list->records, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->maxRecords, file);
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int main() {
    RecordList list;
    if (initRecordList(&list, MAX_RECORDS) != 0) {
        fprintf(stderr, "Failed to initialize record list\n");
        return -1;
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (addRecord(&list, i, i % 1024, i % 256) != 0) {
            fprintf(stderr, "Failed to add record\n");
            break;
        }
    }

    serializeRecords(&list, "records.bin");

    freeRecordList(&list);
    return 0;
}
