#define MAX_RECORDS 1000

typedef struct {
    long *offset;
    int key;
} record;

int allocate_offsets(long **offsets, size_t count) {
    *offsets = (long *)malloc(count * sizeof(long));
    if (*offsets == NULL) {
        return -1; // Memory allocation failed
    }
    return 0;
}

void insert_key(int **keys, int *count, int key) {
    *count += 1;
    *keys = realloc(*keys, *count * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(1);
    }
    int i;
    for (i = *count - 2; i >= 0 && (*keys)[i] > key; i--) {
        (*keys)[i + 1] = (*keys)[i];
    }
    (*keys)[i + 1] = key;
}

record *load_records(const char *filename, int *record_count) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    record *records = (record *)malloc(MAX_RECORDS * sizeof(record));
    if (records == NULL) {
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }

    int count = 0;
    while (fscanf(file, "%ld %d", &records[count].offset, &records[count].key) != EOF && count < MAX_RECORDS) {
        count++;
    }
    fclose(file);

    *record_count = count;
    return records;
}

void populate_records(record *records, int record_count, int min_value, int max_value, int limit) {
    srand(time(NULL));
    int sum = 0;
    for (int i = 0; i < record_count; i++) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        if (sum + value > limit) {
            break;
        }
        records[i].key = value;
        sum += value;
    }
}

void cleanup(record *records, long *offsets, int *keys) {
    free(records);
    free(offsets);
    free(keys);
}

int main() {
    size_t offset_count;
    printf("Enter the number of offsets: ");
    scanf("%zu", &offset_count);

    if (allocate_offsets(&offsets, offset_count) != 0) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return 1;
    }

    int key_count = 0;
    int *keys = NULL;

    // Example usage of insert_key
    insert_key(&keys, &key_count, 5);
    insert_key(&keys, &key_count, 3);
    insert_key(&keys, &key_count, 7);

    record *records = load_records("data.txt", &record_count);
    if (records == NULL) {
        return 1;
    }

    populate_records(records, record_count, 10, 50, 1000);

    cleanup(records, offsets, keys);

    return 0;
}
