#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    int ref_count;
} custom_object;

typedef struct {
    custom_object** objects;
    size_t capacity;
    size_t size;
    size_t max_size;
    size_t max_memory;
} object_collection;

object_collection* create_collection(size_t initial_capacity, size_t max_size, size_t max_memory) {
    object_collection* collection = (object_collection*)malloc(sizeof(object_collection));
    if (!collection) return NULL;

    collection->objects = (custom_object**)malloc(initial_capacity * sizeof(custom_object*));
    if (!collection->objects) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->max_size = max_size;
    collection->max_memory = max_memory;

    return collection;
}

void destroy_collection(object_collection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->objects[i]);
    }
    free(collection->objects);
    free(collection);
}

int add_object(object_collection* collection, double value) {
    if (collection->size >= collection->max_size) return -1;
    if (collection->size == collection->capacity) {
        custom_object** new_objects = (custom_object**)realloc(collection->objects, 2 * collection->capacity * sizeof(custom_object*));
        if (!new_objects) return -1;
        collection->objects = new_objects;
        collection->capacity *= 2;
    }

    custom_object* obj = (custom_object*)malloc(sizeof(custom_object));
    if (!obj) return -1;

    obj->value = value;
    obj->ref_count = 1;

    size_t i = collection->size;
    while (i > 0 && collection->objects[i - 1]->value > value) {
        collection->objects[i] = collection->objects[i - 1];
        --i;
    }
    collection->objects[i] = obj;
    ++collection->size;

    return 0;
}

int serialize_collection(object_collection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    size_t total_size = sizeof(size_t) + collection->size * (sizeof(custom_object*) + sizeof(custom_object));
    if (total_size > collection->max_memory) {
        fclose(file);
        return -1;
    }

    fwrite(&collection->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->size; ++i) {
        fwrite(collection->objects[i], sizeof(custom_object), 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize_collection(object_collection* collection, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    if (size > collection->max_size) {
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < size; ++i) {
        custom_object* obj = (custom_object*)malloc(sizeof(custom_object));
        fread(obj, sizeof(custom_object), 1, file);
        add_object(collection, obj->value);
        free(obj);
    }

    fclose(file);
    return 0;
}

int main() {
    object_collection* collection = create_collection(10, 1000, 1024 * 1024); // Initial capacity, max size, max memory
    if (!collection) {
        fprintf(stderr, "Failed to create collection\n");
        return -1;
    }

    double values[] = {3.14, 2.71, 1.618, 0.577};
    for (size_t i = 0; i < sizeof(values) / sizeof(double); ++i) {
        if (add_object(collection, values[i]) != 0) {
            fprintf(stderr, "Failed to add object\n");
            destroy_collection(collection);
            return -1;
        }
    }

    if (serialize_collection(collection, "collection.bin") != 0) {
        fprintf(stderr, "Failed to serialize collection\n");
        destroy_collection(collection);
        return -1;
    }

    object_collection* new_collection = create_collection(10, 1000, 1024 * 1024); // Initial capacity, max size, max memory
    if (!new_collection) {
        fprintf(stderr, "Failed to create collection\n");
        destroy_collection(collection);
        return -1;
    }

    if (deserialize_collection(new_collection, "collection.bin") != 0) {
        fprintf(stderr, "Failed to deserialize collection\n");
        destroy_collection(collection);
        destroy_collection(new_collection);
        return -1;
    }

    destroy_collection(collection);
    destroy_collection(new_collection);

    return 0;
}
