// GraphTraversal.h
#ifndef GRAPHTRAVERSAL_H
#define GRAPHTRAVERSAL_H

#include <vector>
#include <unordered_set>

struct Graph {
    std::vector<std::vector<int>> adjacencyList;
};

class GraphTraverser {
public:
    static void traverseGraph(const int* sourceVertices, int numSources, Graph& graph, int targetVertex, int maxDepth);
private:
    static void dfs(int vertex, int depth, const Graph& graph, std::unordered_set<int>& visited);
};

#endif // GRAPHTRAVERSAL_H

// TaskScheduling.h
#ifndef TASKSCHEDULING_H
#define TASKSCHEDULING_H

#include <vector>
#include <queue>
#include <functional>

struct Task {
    std::function<void()> taskFunction;
    int priority;
    std::vector<int> dependencies;

    bool operator<(const Task& other) const {
        return priority > other.priority; // Max-heap based on priority
    }
};

class TaskScheduler {
public:
    static void scheduleTasks(const std::vector<Task>& tasks);
private:
    static void executeTask(int taskId, std::priority_queue<Task>& taskQueue);
};

#endif // TASKSCHEDULING_H

// GraphTraversal.cpp
#include "GraphTraversal.h"

void GraphTraverser::traverseGraph(const int* sourceVertices, int numSources, Graph& graph, int targetVertex, int maxDepth) {
    if (numSources <= 0 || maxDepth < 0) return;

    std::unordered_set<int> visited;
    for (int i = 0; i < numSources; ++i) {
        dfs(sourceVertices[i], 0, graph, visited);
    }
}

void GraphTraverser::dfs(int vertex, int depth, const Graph& graph, std::unordered_set<int>& visited) {
    if (depth > maxDepth || visited.find(vertex) != visited.end()) return;
    visited.insert(vertex);

    for (int neighbor : graph.adjacencyList[vertex]) {
        dfs(neighbor, depth + 1, graph, visited);
    }
}

// TaskScheduling.cpp
#include "TaskScheduling.h"

void TaskScheduler::scheduleTasks(const std::vector<Task>& tasks) {
    std::priority_queue<Task> taskQueue(tasks.begin(), tasks.end());

    while (!taskQueue.empty()) {
        int taskId = taskQueue.top().priority;
        executeTask(taskId, taskQueue);
    }
}

void TaskScheduler::executeTask(int taskId, std::priority_queue<Task>& taskQueue) {
    // Execute the task function
    taskQueue.pop();
}
