#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_IP_LENGTH 16

typedef struct {
    uint64_t session_id;
    time_t timestamp;
    char *ip_address;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t capacity;
    size_t size;
    double memory_threshold;
    clock_t allocation_time;
    size_t reallocations;
} SessionManager;

void initialize_session_manager(SessionManager *manager, size_t initial_capacity, double threshold) {
    manager->sessions = (UserSession *)malloc(initial_capacity * sizeof(UserSession));
    if (!manager->sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->memory_threshold = threshold;
    manager->allocation_time = clock();
    manager->reallocations = 0;
}

void add_session(SessionManager *manager, uint64_t session_id, time_t timestamp, const char *ip_address) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UserSession *new_sessions = (UserSession *)realloc(manager->sessions, new_capacity * sizeof(UserSession));
        if (!new_sessions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
        manager->reallocations++;
    }

    manager->sessions[manager->size].session_id = session_id;
    manager->sessions[manager->size].timestamp = timestamp;
    manager->sessions[manager->size].ip_address = strdup(ip_address);
    if (!manager->sessions[manager->size].ip_address) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->size++;
}

void find_most_recent_session(SessionManager *manager) {
    if (manager->size == 0) {
        printf("No sessions available\n");
        return;
    }

    size_t most_recent_index = 0;
    for (size_t i = 1; i < manager->size; i++) {
        if (manager->sessions[i].timestamp > manager->sessions[most_recent_index].timestamp) {
            most_recent_index = i;
        }
    }

    printf("Most recent session: ID=%llu, Timestamp=%ld, IP=%s\n",
           manager->sessions[most_recent_index].session_id,
           manager->sessions[most_recent_index].timestamp,
           manager->sessions[most_recent_index].ip_address);
}

void free_session_manager(SessionManager *manager) {
    for (size_t i = 0; i < manager->size; i++) {
        free(manager->sessions[i].ip_address);
    }
    free(manager->sessions);
}

int main() {
    SessionManager manager;
    initialize_session_manager(&manager, 10, 0.8);

    // Example usage
    add_session(&manager, 123456789, time(NULL), "192.168.1.1");
    add_session(&manager, 987654321, time(NULL) - 3600, "10.0.0.1");

    find_most_recent_session(&manager);

    free_session_manager(&manager);
    return 0;
}
