#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    char* value;
} record;

record* create_records(int start, int end, int* size) {
    if (start > end || size == NULL) return NULL;

    *size = end - start + 1;
    record* records = malloc(*size * sizeof(record));
    if (records == NULL) return NULL;

    srand(time(NULL));
    for (int i = 0; i < *size; i++) {
        records[i].key = rand() % (*size);
        records[i].value = malloc(256); // Assuming max string length of 255
        if (records[i].value == NULL) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) free(records[j].value);
            free(records);
            return NULL;
        }
    }

    return records;
}

void save_records(record* records, int size, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error opening file for writing");
        return;
    }

    for (int i = 0; i < size; i++) {
        fprintf(file, "%d %s\n", records[i].key, records[i].value);
    }

    fclose(file);
}

record* load_records(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file for reading");
        return NULL;
    }

    // Estimate initial size based on file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    *size = file_size / 256; // Assuming max string length of 255 and int key takes 4 bytes
    record* records = malloc(*size * sizeof(record));
    if (records == NULL) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < *size; i++) {
        fscanf(file, "%d %255s", &records[i].key, records[i].value);
    }

    fclose(file);
    return records;
}

void free_records(record* records, int size) {
    for (int i = 0; i < size; i++) free(records[i].value);
    free(records);
}
