typedef struct {
    int id;
    char *name;
    float price;
} Product;

typedef struct {
    Product **products;
    size_t count;
    size_t capacity;
} ProductList;

ProductList* create_product_list() {
    ProductList *list = (ProductList*)malloc(sizeof(ProductList));
    if (!list) return NULL;
    list->products = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

void destroy_product_list(ProductList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->products[i]->name);
        free(list->products[i]);
    }
    free(list->products);
    free(list);
}

int add_product(ProductList *list, int id, const char *name, float price) {
    if (id <= 0 || !name) return -1;
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 4;
        Product **new_products = realloc(list->products, new_capacity * sizeof(Product*));
        if (!new_products) return -1;
        list->products = new_products;
        list->capacity = new_capacity;
    }
    Product *product = (Product*)malloc(sizeof(Product));
    if (!product) return -1;
    product->id = id;
    product->name = strdup(name);
    product->price = price;
    list->products[list->count++] = product;
    return 0;
}

int remove_product_by_id(ProductList *list, int id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->products[i]->id == id) {
            free(list->products[i]->name);
            free(list->products[i]);
            memmove(&list->products[i], &list->products[i + 1], (list->count - i - 1) * sizeof(Product*));
            --list->count;
            return 0;
        }
    }
    return -1;
}

Product* find_product_by_id(ProductList *list, int id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->products[i]->id == id) {
            return list->products[i];
        }
    }
    return NULL;
}

Product* find_product_by_name(ProductList *list, const char *name) {
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->products[i]->name, name) == 0) {
            return list->products[i];
        }
    }
    return NULL;
}

int serialize_product_list(ProductList *list, const char *filename) {
    json_object *array = json_array();
    for (size_t i = 0; i < list->count; ++i) {
        json_object *obj = json_object_new_object();
        json_object_object_add(obj, "id", json_object_new_int(list->products[i]->id));
        json_object_object_add(obj, "name", json_object_new_string(list->products[i]->name));
        json_object_object_add(obj, "price", json_object_new_double(list->products[i]->price));
        json_array_append(array, obj);
    }
    FILE *file = fopen(filename, "w");
    if (!file) return -1;
    int result = json_object_to_file_ext(file, array, JSON_C_TO_FILE_PRETTY);
    fclose(file);
    json_object_put(array);
    return result;
}

int deserialize_product_list(ProductList *list, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;
    json_object *array = json_tokener_parse_file_ext(file, JSON_C_TO_FILE_PRETTY);
    fclose(file);
    if (!json_is_array(array)) {
        json_object_put(array);
        return -1;
    }
    for (size_t i = 0; i < json_array_length(array); ++i) {
        json_object *obj = json_array_get_idx(array, i);
        int id = json_object_get_int(json_object_object_get_ex(obj, "id", NULL));
        const char *name = json_object_get_string(json_object_object_get_ex(obj, "name", NULL));
        float price = json_object_get_double(json_object_object_get_ex(obj, "price", NULL));
        if (add_product(list, id, name, price) != 0) {
            json_object_put(array);
            return -1;
        }
    }
    json_object_put(array);
    return 0;
}
