typedef struct {
    long timestamp;
    double measurement;
    char identifier;
} sensor_data;

sensor_data* allocate_sensor_data(int size) {
    return (sensor_data*)malloc(size * sizeof(sensor_data));
}

void initialize_sensor_data(sensor_data* data, int size, long timestamp, double measurement, char identifier) {
    for (int i = 0; i < size; i++) {
        data[i].timestamp = timestamp + i;
        data[i].measurement = measurement + i * 0.1;
        data[i].identifier = 'A' + i % 26;
    }
}

void apply_moving_average(sensor_data* data, int size, int window_size) {
    if (window_size <= 0 || window_size > size) return;

    double sum = 0;
    for (int i = 0; i < window_size; i++) {
        sum += data[i].measurement;
    }
    data[0].measurement = sum / window_size;

    for (int i = 1; i < size - window_size + 1; i++) {
        sum -= data[i - 1].measurement;
        sum += data[i + window_size - 1].measurement;
        data[i].measurement = sum / window_size;
    }

    for (int i = size - window_size + 1; i < size; i++) {
        data[i].measurement = sum / (size - i);
    }
}

void free_sensor_data(sensor_data* data) {
    free(data);
}
