void processFileContent(const char *filePath, size_t maxBufferSize, void *hashMap, int (*validateKey)(const char *)) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize > maxBufferSize) {
        fileSize = maxBufferSize;
    }

    char *buffer = malloc((fileSize + 1) * sizeof(char));
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        fclose(file);
        return;
    }

    size_t bytesRead = fread(buffer, sizeof(char), fileSize, file);
    if (bytesRead != fileSize) {
        perror("Error reading file");
    }
    buffer[bytesRead] = '\0';

    fclose(file);

    char timestamp[20];
    time_t lastModifiedTime = get_last_modified_time(filePath);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&lastModifiedTime));
    add_to_hash_map(hashMap, filePath, timestamp);

    struct json_object *parsedJson = json_tokener_parse(buffer);
    if (!parsedJson) {
        fprintf(stderr, "Malformed JSON encountered\n");
        free(buffer);
        return;
    }

    traverseJson(parsedJson, hashMap, validateKey);

    json_object_put(parsedJson);
    free(buffer);
}

void traverseJson(struct json_object *obj, void *hashMap, int (*validateKey)(const char *)) {
    if (json_object_is_type(obj, json_type_object)) {
        struct json_object_iter iter;
        json_object_object_foreachC(obj, iter) {
            const char *key = iter.key;
            struct json_object *value = iter.val;

            if (validateKey(key)) {
                if (json_object_is_type(value, json_type_int)) {
                    int intValue = json_object_get_int(value);
                    add_to_hash_map(hashMap, key, intValue);
                } else if (json_object_is_type(value, json_type_array)) {
                    traverseJsonArray(value, hashMap, validateKey);
                }
            }
        }
    } else if (json_object_is_type(obj, json_type_array)) {
        traverseJsonArray(obj, hashMap, validateKey);
    }
}

void traverseJsonArray(struct json_object *array, void *hashMap, int (*validateKey)(const char *)) {
    struct json_object_iterator iter;
    json_object_array_foreachC(array, iter) {
        struct json_object *value = iter.val;

        if (json_object_is_type(value, json_type_int)) {
            int intValue = json_object_get_int(value);
            add_to_hash_map(hashMap, "array_element", intValue);
        } else if (json_object_is_type(value, json_type_array)) {
            traverseJsonArray(value, hashMap, validateKey);
        }
    }
}

time_t get_last_modified_time(const char *filePath) {
    struct stat fileStat;
    if (stat(filePath, &fileStat) != 0) {
        perror("Failed to get file stats");
        return -1;
    }
    return fileStat.st_mtime;
}

