#define MAX_DEVICE_NAME_LENGTH 50

typedef enum {
    NO_ERROR,
    ERROR_CODE_1,
    ERROR_CODE_2
} ErrorCode;

typedef struct {
    int sensorID;
    float temperature;
    char deviceName[MAX_DEVICE_NAME_LENGTH];
    ErrorCode errorCode;
} DeviceData;

DeviceData* initialize_device_data(int num_devices) {
    DeviceData* data = (DeviceData*)malloc(num_devices * sizeof(DeviceData));
    if (data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < num_devices; i++) {
        data[i].sensorID = -1;
        data[i].temperature = 0.0f;
        memset(data[i].deviceName, 0, MAX_DEVICE_NAME_LENGTH);
        data[i].errorCode = NO_ERROR;
    }
    return data;
}

void process_device_data(DeviceData* data, int num_devices) {
    if (data == NULL || num_devices <= 0) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    // Filter out devices with non-zero error codes
    DeviceData* filtered_data = initialize_device_data(num_devices);
    int filtered_count = 0;
    for (int i = 0; i < num_devices; i++) {
        if (data[i].errorCode == NO_ERROR) {
            filtered_data[filtered_count++] = data[i];
        }
    }

    // Apply weighted average filter to temperature readings
    float total_weight = 0.0f;
    float weighted_sum = 0.0f;
    for (int i = 0; i < filtered_count - 1; i++) {
        int current_id = filtered_data[i].sensorID;
        int next_id = filtered_data[i + 1].sensorID;
        float proximity_factor = (next_id - current_id) / (float)(next_id - current_id);
        total_weight += proximity_factor;
        weighted_sum += filtered_data[i].temperature * proximity_factor;
    }
    if (total_weight > 0.0f) {
        float average_temperature = weighted_sum / total_weight;
        printf("Weighted Average Temperature: %.2f\n", average_temperature);
    } else {
        printf("No valid data for averaging\n");
    }

    // Free allocated memory
    free(filtered_data);
}

int main() {
    int num_devices = 5;
    DeviceData* device_data = initialize_device_data(num_devices);

    if (device_data != NULL) {
        // Populate device_data with sample data
        device_data[0].sensorID = 101;
        device_data[0].temperature = 23.5f;
        strcpy(device_data[0].deviceName, "DeviceA");
        device_data[0].errorCode = NO_ERROR;

        device_data[1].sensorID = 102;
        device_data[1].temperature = 24.0f;
        strcpy(device_data[1].deviceName, "DeviceB");
        device_data[1].errorCode = ERROR_CODE_1;

        device_data[2].sensorID = 103;
        device_data[2].temperature = 25.5f;
        strcpy(device_data[2].deviceName, "DeviceC");
        device_data[2].errorCode = NO_ERROR;

        device_data[3].sensorID = 104;
        device_data[3].temperature = 26.0f;
        strcpy(device_data[3].deviceName, "DeviceD");
        device_data[3].errorCode = ERROR_CODE_2;

        device_data[4].sensorID = 105;
        device_data[4].temperature = 27.5f;
        strcpy(device_data[4].deviceName, "DeviceE");
        device_data[4].errorCode = NO_ERROR;

        process_device_data(device_data, num_devices);

        // Free allocated memory
        free(device_data);
    }

    return 0;
}
