#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for (int i = 0; i < array->size; i++) {
        free(array->elements[i]);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (array->size >= MAX_ELEMENTS) return -1;
    array->elements[array->size++] = element;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray *array, int index) {
    if (index < 0 || index >= array->size) return NULL;
    return array->elements[index];
}

int remove_element(DynamicArray *array, int index) {
    if (index < 0 || index >= array->size) return -1;
    free(array->elements[index]);
    for (int i = index; i < array->size - 1; i++) {
        array->elements[i] = array->elements[i + 1];
    }
    array->size--;
    return 0;
}

int validate_array(DynamicArray *array) {
    int rnti_count[65536] = {0};
    for (int i = 0; i < array->size; i++) {
        if (!array->elements[i]) return -1;
        if (rnti_count[array->elements[i]->RNTI] > 0) return -2;
        rnti_count[array->elements[i]->RNTI]++;
    }
    return 0;
}
