double weighted_moving_average(double* measurements, int size, double weights[], int window_size) {
    double sum = 0.0;
    for (int i = 0; i < window_size; i++) {
        sum += measurements[i] * weights[i];
    }
    return sum / window_size;
}

void apply_weighted_moving_average(sensor_data* data, int size, double weights[], int window_size) {
    if (size < window_size) {
        printf("Error: Data size is smaller than the window size.\n");
        return;
    }

    double* measurements = (double*)malloc(size * sizeof(double));
    for (int i = 0; i < size; i++) {
        measurements[i] = data[i].measurement;
    }

    for (int i = 0; i < size - window_size + 1; i++) {
        data[i].measurement = weighted_moving_average(&measurements[i], window_size, weights, window_size);
    }

    free(measurements);
}

