    record* records = (record*)malloc(size * sizeof(record));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % 201 - 100;
        records[i].offset = (long)i;
        records[i].status = records[i].value > 0 ? 'A' : (records[i].value < 0 ? 'N' : 'Z');
    }
    return records;
}

void parse_input(double* array, int size) {
    char input[1024];
    fgets(input, sizeof(input), stdin);
    char* token = strtok(input, ",");
    for (int i = 0; i < size && token != NULL; i++) {
        array[i] = atof(token);
        token = strtok(NULL, ",");
    }
}

double calculate_average(double* array, int size) {
    double sum = 0;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    return sum / size;
}

void sort_points(point* points, int size, int (*compare)(const void*, const void*)) {
    qsort(points, size, sizeof(point), compare);
}

int compare_x(const void* a, const void* b) {
    point* pa = (point*)a;
    point* pb = (point*)b;
    return (pa->x > pb->x) - (pa->x < pb->x);
}

int compare_y(const void* a, const void* b) {
    point* pa = (point*)a;
    point* pb = (point*)b;
    return (pa->y > pb->y) - (pa->y < pb->y);
}

void free_all(double* doubles, char** strings, point* points, record* records) {
    free(doubles);
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(strings[i]);
    }
    free(strings);
    free(points);
    free(records);
}
