        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    long *offsets_ptr = malloc(size * sizeof(long));
    int *keys_ptr = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));

    if (!offsets_ptr || !keys_ptr || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets_ptr);
        free(keys_ptr);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        offsets_ptr[i] = offsets[i];
        keys_ptr[i] = keys[i];
        records[i].offset = &offsets_ptr[i];
        records[i].key = &keys_ptr[i];
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

// Example usage
