    long offsets[] = {1, 2, 3};
    int keys[] = {4, 5, 6};
    int size = sizeof(offsets) / sizeof(offsets[0]);
    int min_value = 10;
    int max_value = 100;

    record *records = allocate_records(offsets, keys, size, min_value, max_value);
    if (records) {
        for (int i = 0; i < size; i++) {
            printf("Record %d: Offset=%ld, Key=%d, Value=%d\n", i, *(records[i].offset), *(records[i].key), records[i].value);
