#define KEY_SIZE 32
#define SALT_SIZE 16
#define IV_SIZE 12
#define TAG_SIZE 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_SIZE];
} AES_GCM_CTX;

int derive_key(const char *password, size_t password_len, const unsigned char *salt, size_t salt_len, unsigned char *key) {
    return PKCS5_PBKDF2_HMAC_SHA256(password, password_len, salt, salt_len, 100000, KEY_SIZE, key);
}

int init_aes_gcm(AES_GCM_CTX **ctx, const char *password, size_t password_len, const unsigned char *salt, size_t salt_len) {
    AES_GCM_CTX *new_ctx = (AES_GCM_CTX *)malloc(sizeof(AES_GCM_CTX));
    if (!new_ctx) return -1;

    new_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!new_ctx->ctx) {
        free(new_ctx);
        return -1;
    }

    unsigned char key[KEY_SIZE];
    if (derive_key(password, password_len, salt, salt_len, key) != 0) {
        EVP_CIPHER_CTX_free(new_ctx->ctx);
        free(new_ctx);
        return -1;
    }

    memcpy(new_ctx->key, key, KEY_SIZE);

    *ctx = new_ctx;
    return 0;
}

int encrypt_data(AES_GCM_CTX *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *iv, unsigned char *ciphertext, unsigned char *tag) {
    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, iv) != 1) return -1;
    if (EVP_EncryptUpdate(ctx->ctx, ciphertext, NULL, plaintext, plaintext_len) != 1) return -1;
    if (EVP_EncryptFinal_ex(ctx->ctx, ciphertext + plaintext_len, NULL) != 1) return -1;
    if (EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, TAG_SIZE, tag) != 1) return -1;

    return 0;
}

int decrypt_data(AES_GCM_CTX *ctx, const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *iv, const unsigned char *tag, unsigned char *plaintext) {
    if (EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, iv) != 1) return -1;
    if (EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, TAG_SIZE, tag) != 1) return -1;
    if (EVP_DecryptUpdate(ctx->ctx, plaintext, NULL, ciphertext, ciphertext_len) != 1) return -1;
    if (EVP_DecryptFinal_ex(ctx->ctx, plaintext + ciphertext_len, NULL) != 1) return -1;

    return 0;
}

void cleanup_aes_gcm(AES_GCM_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
