#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct {
    long* offsets;
    int* keys;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager() {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(INITIAL_CAPACITY, sizeof(long));
    manager->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    if (!manager->offsets || !manager->keys) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (!manager) return;

    free(manager->offsets);
    free(manager->keys);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(RecordManager* manager, long offset, int key) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * GROWTH_FACTOR;
        long* new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));

        if (!new_offsets || !new_keys) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->capacity = new_capacity;
    }

    manager->offsets[manager->size] = offset;
    manager->keys[manager->size++] = key;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void iterate_records_reverse(RecordManager* manager, void (*callback)(long, int)) {
    if (!manager || !callback) return;

    for (size_t i = manager->size; i > 0; --i) {
        callback(manager->offsets[i - 1], manager->keys[i - 1]);
    }
}

void log_memory_event(const char* event, size_t size) {
    printf("%s: %zu bytes\n", event, size);
}
