#include <stdlib.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define your structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
    struct PoolNode* prev;
} PoolNode;

typedef struct MemoryPool {
    PoolNode* head;
    PoolNode* tail;
    size_t poolSize;
    size_t usedCount;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool() {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->head = NULL;
    pool->tail = NULL;
    pool->poolSize = INITIAL_POOL_SIZE;
    pool->usedCount = 0;
    pthread_mutex_init(&pool->lock, NULL);

    // Pre-allocate initial nodes
    for (size_t i = 0; i < pool->poolSize; ++i) {
        PoolNode* node = (PoolNode*)malloc(sizeof(PoolNode));
        if (!node) {
            destroyMemoryPool(pool);
            return NULL;
        }
        node->next = NULL;
        node->prev = pool->tail;
        if (pool->tail) pool->tail->next = node;
        pool->tail = node;
    }

    return pool;
}

void destroyMemoryPool(MemoryPool* pool) {
    PoolNode* current = pool->head;
    while (current) {
        PoolNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->usedCount == pool->poolSize) {
        // Resize the pool
        size_t newPoolSize = pool->poolSize * 2;
        for (size_t i = 0; i < newPoolSize - pool->poolSize; ++i) {
            PoolNode* node = (PoolNode*)malloc(sizeof(PoolNode));
            if (!node) {
                pthread_mutex_unlock(&pool->lock);
                return NULL; // Handle out-of-memory condition
            }
            node->next = NULL;
            node->prev = pool->tail;
            if (pool->tail) pool->tail->next = node;
            pool->tail = node;
        }
        pool->poolSize = newPoolSize;
    }

    PoolNode* node = pool->head;
    pool->head = node->next;
    if (node == pool->tail) {
        pool->tail = NULL;
    } else {
        pool->head->prev = NULL;
    }
    ++pool->usedCount;

    pthread_mutex_unlock(&pool->lock);
    return &node->data;
}

void deallocateToPool(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    PoolNode* node = (PoolNode*)((char*)data - offsetof(PoolNode, data));

    pthread_mutex_lock(&pool->lock);

    if (!pool->tail) {
        pool->head = node;
        pool->tail = node;
    } else {
        pool->tail->next = node;
        node->prev = pool->tail;
        pool->tail = node;
    }
    --pool->usedCount;

    pthread_mutex_unlock(&pool->lock);
}

// Additional functions for traversal, integrity validation, and background defragmentation can be implemented here
