#include <string.h>

typedef struct {
    double value;
    char* name;
    size_t id;
} item;

item* create_items(double* values, char** names, int num_names, char* string_pool) {
    if (values == NULL || names == NULL || string_pool == NULL) {
        fprintf(stderr, "Error: Null pointer provided.\n");
        return NULL;
    }

    if (num_names <= 0) {
        fprintf(stderr, "Error: Invalid number of names.\n");
        return NULL;
    }

    item* items = (item*)malloc(num_names * sizeof(item));
    if (items == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    size_t string_pool_offset = 0;
    for (int i = 0; i < num_names; ++i) {
        items[i].value = values[i];
        items[i].id = i;

        // Calculate the length of the name including the null terminator
        size_t name_length = strlen(names[i]) + 1;

        // Check if there is enough space in the string pool for this name
        if (string_pool_offset + name_length > strlen(string_pool)) {
            fprintf(stderr, "Error: Insufficient string pool space.\n");
            free(items);
            return NULL;
        }

        // Allocate memory for the name and copy it into the string pool
        items[i].name = &string_pool[string_pool_offset];
        strcpy(items[i].name, names[i]);

        // Update the offset to the next available position in the string pool
        string_pool_offset += name_length;
    }

    return items;
}

int main() {
    double values[] = {1.0, 2.0, 3.0};
    char* names[] = {"apple", "banana", "cherry"};
    char string_pool[50] = "applebananacherry";

    item* items = create_items(values, names, sizeof(names) / sizeof(names[0]), string_pool);
    if (items != NULL) {
        for (int i = 0; i < sizeof(names) / sizeof(names[0]); ++i) {
            printf("Item %d: Value = %.2f, Name = %s, ID = %zu\n", i, items[i].value, items[i].name, items[i].id);
        }
        free(items);
    }

    return 0;
}
