#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    unsigned char key[32];
    unsigned char iv[16];
} CipherHandle;

CipherHandle* create_cipher_handle(const char *algorithm, const unsigned char *key, size_t key_len) {
    CipherHandle *handle = (CipherHandle*)malloc(sizeof(CipherHandle));
    if (!handle) return NULL;

    handle->cipher = EVP_CIPHER_fetch(NULL, algorithm, NULL);
    if (!handle->cipher) {
        free(handle);
        return NULL;
    }

    handle->ctx = EVP_CIPHER_CTX_new();
    if (!handle->ctx) {
        EVP_CIPHER_free(handle->cipher);
        free(handle);
        return NULL;
    }

    if (EVP_EncryptInit_ex(handle->ctx, handle->cipher, NULL, key, NULL) != 1) {
        EVP_CIPHER_CTX_free(handle->ctx);
        EVP_CIPHER_free(handle->cipher);
        free(handle);
        return NULL;
    }

    memcpy(handle->key, key, key_len);
    memset(handle->iv, 0, sizeof(handle->iv));

    return handle;
}

void destroy_cipher_handle(CipherHandle *handle) {
    if (handle) {
        EVP_CIPHER_CTX_free(handle->ctx);
        EVP_CIPHER_free(handle->cipher);
        free(handle);
    }
}

int encrypt_data(CipherHandle *handle, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    int len;
    if (EVP_EncryptUpdate(handle->ctx, ciphertext, &len, plaintext, plaintext_len) != 1) return -1;
    int ciphertext_len = len;

    if (EVP_EncryptFinal_ex(handle->ctx, ciphertext + len, &len) != 1) return -1;
    ciphertext_len += len;

    return ciphertext_len;
}

int decrypt_data(CipherHandle *handle, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    int len;
    if (EVP_DecryptUpdate(handle->ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) return -1;
    int plaintext_len = len;

    if (EVP_DecryptFinal_ex(handle->ctx, plaintext + len, &len) != 1) return -1;
    plaintext_len += len;

    return plaintext_len;
}

int main() {
    unsigned char key[32];
    unsigned char iv[16];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[100];
    unsigned char decryptedtext[100];

    if (!RAND_bytes(key, sizeof(key))) return -1;
    if (!RAND_bytes(iv, sizeof(iv))) return -1;

    CipherHandle *handle = create_cipher_handle("AES-256-CBC", key, sizeof(key));
    if (!handle) return -1;

    int ciphertext_len = encrypt_data(handle, plaintext, strlen((char*)plaintext), ciphertext);
    if (ciphertext_len < 0) {
        destroy_cipher_handle(handle);
        return -1;
    }

    int decryptedtext_len = decrypt_data(handle, ciphertext, ciphertext_len, decryptedtext);
    if (decryptedtext_len < 0) {
        destroy_cipher_handle(handle);
        return -1;
    }

    decryptedtext[decryptedtext_len] = '\0';
    printf("Decrypted text: %s\n", decryptedtext);

    destroy_cipher_handle(handle);
    return 0;
}
