int pool_index = 0;

record* allocate_records(int N, int L) {
    if (pool_index >= MAX_CONCURRENT_CALLS) {
        fprintf(stderr, "Memory pool overflow\n");
        return NULL;
    }

    record* records = (record*)memory_pool[pool_index++];
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    long total_offset = 0;
    int total_key = 0;

    for (int i = 0; i < N; i++) {
        records[i].offset = rand() % 1000000L;
        records[i].key = rand() % 1000;
        records[i].value = records[i].offset * records[i].key;

        total_offset += records[i].offset;
        total_key += records[i].key;
    }

    while (total_key > L) {
        int adjustment = rand() % (total_key - L);
        for (int i = 0; i < N && total_key > L; i++) {
            if (records[i].key > adjustment) {
                records[i].key -= adjustment;
                total_key -= adjustment;
                break;
            } else {
                adjustment -= records[i].key;
                total_key -= records[i].key;
                records[i].key = 0;
            }
        }
    }

    return records;
}

void free_records(record* records) {
    for (int i = pool_index - 1; i >= 0; i--) {
        if (memory_pool[i] == records) {
            memory_pool[i] = NULL;
            break;
        }
    }
}

