#define MAX_DOUBLE_SIZE 1000
#define MAX_CHAR_SIZE 1000
#define MAX_POINT_SIZE 1000

typedef struct {
    int x;
    int y;
} point;

typedef struct {
    double* doubles;
    char** chars;
    point* points;
    size_t double_size;
    size_t char_size;
    size_t point_size;
    pthread_mutex_t mutex;
} memory_manager;

void initialize_memory_manager(memory_manager* mm, size_t max_double_size, size_t max_char_size, size_t max_point_size) {
    mm->doubles = (double*)malloc(max_double_size * sizeof(double));
    mm->chars = (char**)malloc(max_char_size * sizeof(char*));
    mm->points = (point*)malloc(max_point_size * sizeof(point));
    mm->double_size = 0;
    mm->char_size = 0;
    mm->point_size = 0;
    pthread_mutex_init(&mm->mutex, NULL);
}

void free_memory_manager(memory_manager* mm) {
    for (size_t i = 0; i < mm->char_size; ++i) {
        free(mm->chars[i]);
    }
    free(mm->doubles);
    free(mm->chars);
    free(mm->points);
    pthread_mutex_destroy(&mm->mutex);
}

