double* parse_floats(const char* input, int* count) {
    double* floats = NULL;
    char* token = strtok((char*)input, ",");
    while (token != NULL) {
        if (*count >= MAX_ELEMENTS) {
            fprintf(stderr, "Error: Maximum number of elements exceeded.\n");
            free(floats);
            return NULL;
        }
        floats = realloc(floats, (*count + 1) * sizeof(double));
        if (floats == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return NULL;
        }
        floats[*count] = atof(token);
        (*count)++;
        token = strtok(NULL, ",");
    }
    return floats;
}

double calculate_average(double* numbers, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

void free_memory(void** ptr) {
    if (*ptr != NULL) {
        free(*ptr);
        *ptr = NULL;
    }
}

