#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TASKS 1000

typedef struct {
    int id;
    int priority;
    char description[256];
} Task;

typedef struct {
    Task *tasks[MAX_TASKS];
    int size;
    int capacity;
} PriorityQueue;

PriorityQueue* create_priority_queue() {
    PriorityQueue *pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->size = 0;
    pq->capacity = MAX_TASKS;
    return pq;
}

void destroy_priority_queue(PriorityQueue *pq) {
    for (int i = 0; i < pq->size; i++) {
        free(pq->tasks[i]);
    }
    free(pq);
}

Task* read_task_from_input() {
    Task *task = (Task*)malloc(sizeof(Task));
    printf("Enter task ID: ");
    scanf("%d", &task->id);
    printf("Enter task priority: ");
    scanf("%d", &task->priority);
    getchar(); // Consume newline character
    printf("Enter task description: ");
    fgets(task->description, sizeof(task->description), stdin);
    return task;
}

void insert_task(PriorityQueue *pq, Task *task) {
    if (pq->size >= pq->capacity) {
        pq->capacity *= 2;
        pq->tasks = realloc(pq->tasks, pq->capacity * sizeof(Task*));
    }
    pq->tasks[pq->size++] = task;
}

Task* get_highest_priority_task(PriorityQueue *pq) {
    if (pq->size == 0) return NULL;
    int max_index = 0;
    for (int i = 1; i < pq->size; i++) {
        if (pq->tasks[i]->priority > pq->tasks[max_index]->priority) {
            max_index = i;
        }
    }
    Task *task = pq->tasks[max_index];
    pq->tasks[max_index] = pq->tasks[--pq->size];
    return task;
}

void remove_task(PriorityQueue *pq, int id) {
    for (int i = 0; i < pq->size; i++) {
        if (pq->tasks[i]->id == id) {
            free(pq->tasks[i]);
            for (; i < pq->size - 1; i++) {
                pq->tasks[i] = pq->tasks[i + 1];
            }
            pq->size--;
            break;
        }
    }
}

void serialize_priority_queue(PriorityQueue *pq, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) return;
    fprintf(file, "%d\n", pq->size);
    for (int i = 0; i < pq->size; i++) {
        fprintf(file, "%d %d %s", pq->tasks[i]->id, pq->tasks[i]->priority, pq->tasks[i]->description);
    }
    fclose(file);
}

void deserialize_priority_queue(PriorityQueue *pq, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) return;
    int size;
    fscanf(file, "%d\n", &size);
    for (int i = 0; i < size; i++) {
        Task *task = (Task*)malloc(sizeof(Task));
        fscanf(file, "%d %d %s", &task->id, &task->priority, task->description);
        insert_task(pq, task);
    }
    fclose(file);
}

void log_operation(const char *operation, int status_code) {
    time_t now = time(NULL);
    printf("%s - Operation: %s, Status Code: %d\n", ctime(&now), operation, status_code);
}
