#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2
#define HASH_SEED 31

typedef struct {
    int value;
    time_t timestamp;
    bool access_flag;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t size;
    size_t threshold;
    bool logging_enabled;
} DynamicCollection;

DynamicCollection* create_collection(size_t initial_capacity, size_t threshold, bool logging) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    collection->offsets = (long*)calloc(initial_capacity, sizeof(long));
    collection->keys = (int*)calloc(initial_capacity, sizeof(int));
    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->threshold = threshold;
    collection->logging_enabled = logging;
    return collection;
}

void destroy_collection(DynamicCollection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]);
    }
    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
    free(collection);
}

size_t hash_function(int key) {
    size_t hash = HASH_SEED;
    while (key != 0) {
        hash = hash * HASH_SEED + (key & 0xFF);
        key >>= 8;
    }
    return hash % collection->capacity;
}

void resize_collection(DynamicCollection *collection) {
    size_t new_capacity = collection->capacity * GROWTH_FACTOR;
    long *new_offsets = (long*)realloc(collection->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(collection->keys, new_capacity * sizeof(int));
    Record **new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));

    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    collection->offsets = new_offsets;
    collection->keys = new_keys;
    collection->records = new_records;
    collection->capacity = new_capacity;

    for (size_t i = collection->size; i < new_capacity; ++i) {
        collection->offsets[i] = -1;
        collection->keys[i] = -1;
        collection->records[i] = NULL;
    }
}

void add_record(DynamicCollection *collection, long offset, int key, Record metadata) {
    if (collection->size >= collection->capacity) {
        resize_collection(collection);
    }

    size_t index = hash_function(key);
    while (collection->keys[index] != -1 && collection->keys[index] != key) {
        index = (index + 1) % collection->capacity;
    }

    if (collection->keys[index] == key) {
        fprintf(stderr, "Key already exists\n");
        return;
    }

    collection->offsets[index] = offset;
    collection->keys[index] = key;
    collection->records[index] = (Record*)malloc(sizeof(Record));
    *collection->records[index] = metadata;

    if (collection->logging_enabled) {
        printf("Added record with key %d at index %zu\n", key, index);
    }

    ++collection->size;
}

void process_batch(DynamicCollection *collection, long *offsets, int *keys, Record **metadatas, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        add_record(collection, offsets[i], keys[i], metadatas[i]);
    }
}

int main() {
    DynamicCollection *collection = create_collection(INITIAL_CAPACITY, 1024, true);

    long offsets[] = {100, 200, 300};
    int keys[] = {1, 2, 3};
    Record metadatas[3] = {
        {.value = 10, .timestamp = time(NULL), .access_flag = true},
        {.value = 20, .timestamp = time(NULL), .access_flag = false},
        {.value = 30, .timestamp = time(NULL), .access_flag = true}
    };

    process_batch(collection, offsets, keys, metadatas, 3);

    destroy_collection(collection);
    return 0;
}
