// AES-256-CBC Encryption with OpenSSL
std::string encrypt(const std::string& data, const std::string& password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    unsigned char key[32], iv[16];
    SHA256((unsigned char*)password.c_str(), password.length(), key);
    RAND_bytes(iv, 16);

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Encryption initialization failed");
    }

    int len;
    unsigned char ciphertext[data.length() + EVP_CIPHER_block_size(EVP_aes_256_cbc())];
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)data.c_str(), data.length())) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Encryption update failed");
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Encryption finalization failed");
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return std::string((char*)ciphertext, ciphertext_len);
}

