#define MAX_LOG_ENTRY_SIZE 1024
#define MAX_ARRAY_SIZE 1000

typedef struct {
    char* message;
    int value;
    double precision;
} record;

void allocateLogEntry(int offsetSize, int keySize, int precisionSize) {
    if (offsetSize > MAX_ARRAY_SIZE || keySize > MAX_ARRAY_SIZE || precisionSize > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Error: Array size exceeds maximum limit.\n");
        return;
    }

    long* offsets = malloc(offsetSize * sizeof(long));
    int* keys = malloc(keySize * sizeof(int));
    double* precisions = malloc(precisionSize * sizeof(double));

    if (!offsets || !keys || !precisions) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(precisions);
        return;
    }

    record* records = malloc(sizeof(record) * offsetSize);
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(precisions);
        return;
    }

    // Initialize records
    for (int i = 0; i < offsetSize; i++) {
        records[i].message = malloc(MAX_LOG_ENTRY_SIZE * sizeof(char));
        if (!records[i].message) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            for (int j = 0; j < i; j++) {
                free(records[j].message);
            }
            free(offsets);
            free(keys);
            free(precisions);
            free(records);
            return;
        }
    }

    // Allocate memory for command execution
    pid_t pid = fork();
    if (pid == -1) {
        fprintf(stderr, "Error: Fork failed.\n");
        for (int i = 0; i < offsetSize; i++) {
            free(records[i].message);
        }
        free(offsets);
        free(keys);
        free(precisions);
        free(records);
        return;
    } else if (pid == 0) {
        // Child process
        execlp("command", "command", NULL); // Replace with actual command
        fprintf(stderr, "Error: Command execution failed.\n");
        exit(1);
    }

    // Parent process
    int status;
    wait(&status);

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        printf("Command executed successfully.\n");
    } else {
        fprintf(stderr, "Error: Command execution failed with status %d.\n", WEXITSTATUS(status));
    }

    // Free allocated memory
    for (int i = 0; i < offsetSize; i++) {
        free(records[i].message);
    }
    free(offsets);
    free(keys);
    free(precisions);
    free(records);
}

int main() {
    allocateLogEntry(10, 10, 10);
    return 0;
}
