NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(int N, void (*fetch_data)(int, NFAPI_CRC_INDICATION_PDU_T*)) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array != NULL) {
            for (int i = 0; i < N; i++) {
                fetch_data(i, &array[i]);
            }
            break;
        } else {
            log_error("Memory allocation failed. Retrying...");
            retries++;
            sleep(1); // Simulate retry delay
        }
    }

    if (retries == MAX_RETRIES) {
        log_error("Failed to allocate memory after multiple retries.");
        return NULL;
    }

    return array;
}

void fetch_data(int index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
