#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

#define MAX_PROJECTS 1000
#define MAX_TEAMS 50
#define MEMORY_THRESHOLD 1024 * 1024 * 1024 // 1GB

typedef struct task {
    char* description;
    int duration;
} Task;

typedef struct project {
    char* name;
    int budget;
    struct timeval deadline;
    Task* tasks;
    int num_tasks;
} Project;

typedef struct team {
    Project** projects;
    int num_projects;
} Team;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void free_project(Project* project) {
    if (project->name) free(project->name);
    for (int i = 0; i < project->num_tasks; ++i) {
        if (project->tasks[i].description) free(project->tasks[i].description);
    }
    free(project->tasks);
    free(project);
}

void free_team(Team* team) {
    for (int i = 0; i < team->num_projects; ++i) {
        free_project(team->projects[i]);
    }
    free(team->projects);
    free(team);
}

void free_all(Project** projects, Team** teams, int num_teams) {
    for (int i = 0; i < num_teams; ++i) {
        free_team(teams[i]);
    }
    free(projects);
    free(teams);
}

Team* create_team() {
    Team* team = malloc(sizeof(Team));
    if (!team) {
        log_error("Failed to allocate memory for team");
        return NULL;
    }
    team->projects = NULL;
    team->num_projects = 0;
    return team;
}

Project* create_project(const char* name, int budget, struct timeval deadline) {
    Project* project = malloc(sizeof(Project));
    if (!project) {
        log_error("Failed to allocate memory for project");
        return NULL;
    }
    project->name = strdup(name);
    project->budget = budget;
    project->deadline = deadline;
    project->tasks = NULL;
    project->num_tasks = 0;
    return project;
}

void add_task(Project* project, const char* description, int duration) {
    Task* task = malloc(sizeof(Task));
    if (!task) {
        log_error("Failed to allocate memory for task");
        return;
    }
    task->description = strdup(description);
    task->duration = duration;
    project->tasks = realloc(project->tasks, (project->num_tasks + 1) * sizeof(Task));
    if (!project->tasks) {
        log_error("Failed to reallocate memory for tasks");
        free(task);
        return;
    }
    project->tasks[project->num_tasks++] = *task;
}

Team** manage_projects(Project* projects, int num_projects, struct timeval deadline, int* num_teams) {
    if (num_projects > MAX_PROJECTS) {
        log_error("Too many projects");
        return NULL;
    }

    Team** teams = malloc(MAX_TEAMS * sizeof(Team*));
    if (!teams) {
        log_error("Failed to allocate memory for teams");
        return NULL;
    }
    memset(teams, 0, MAX_TEAMS * sizeof(Team*));

    int team_index = 0;
    for (int i = 0; i < num_projects; ++i) {
        if (!projects[i].deadline.tv_sec || !projects[i].deadline.tv_usec) {
            log_error("Invalid deadline");
            free_all(projects, teams, team_index);
            return NULL;
        }

        if (team_index >= MAX_TEAMS) {
            log_error("Too many teams");
            free_all(projects, teams, team_index);
            return NULL;
        }

        if (!teams[team_index]) {
            teams[team_index] = create_team();
            if (!teams[team_index]) {
                free_all(projects, teams, team_index);
                return NULL;
            }
        }

        add_task(&projects[i], "Default Task", 10); // Example task
        teams[team_index]->projects = realloc(teams[team_index]->projects, (teams[team_index]->num_projects + 1) * sizeof(Project*));
        if (!teams[team_index]->projects) {
            log_error("Failed to reallocate memory for team projects");
            free_all(projects, teams, team_index);
            return NULL;
        }
        teams[team_index]->projects[teams[team_index]->num_projects++] = &projects[i];
    }

    *num_teams = team_index + 1;
    return teams;
}

int main() {
    Project projects[MAX_PROJECTS];
    struct timeval deadline = { .tv_sec = 1633072800, .tv_usec = 0 }; // Example deadline
    int num_projects = 5; // Example number of projects

    Team** teams;
    int num_teams;

    teams = manage_projects(projects, num_projects, deadline, &num_teams);
    if (!teams) {
        return 1;
    }

    for (int i = 0; i < num_teams; ++i) {
        printf("Team %d:\n", i);
        for (int j = 0; j < teams[i]->num_projects; ++j) {
            printf("  Project: %s\n", teams[i]->projects[j]->name);
        }
    }

    free_all(projects, teams, num_teams);

    return 0;
}
