    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->packets = (DataPacket *)realloc(manager->packets, manager->capacity * sizeof(DataPacket));
        if (!manager->packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
