#include <iostream>
#include <mutex>
#include <shared_mutex>
#include <unordered_map>
#include <vector>

class ResourceUsage {
public:
    int resourceID;
    long timestamp;
    double cpuUtilization;
    double memoryUsage;
    double networkIO;

    ResourceUsage(int id, long ts, double cpu, double mem, double net)
        : resourceID(id), timestamp(ts), cpuUtilization(cpu), memoryUsage(mem), networkIO(net) {}
};

class ConcurrentResourceIndex {
private:
    std::unordered_map<int, ResourceUsage> index;
    mutable std::shared_mutex mutex;

public:
    void insert(const ResourceUsage& usage) {
        std::unique_lock<std::shared_mutex> lock(mutex);
        index[usage.resourceID] = usage;
    }

    bool remove(int resourceID) {
        std::unique_lock<std::shared_mutex> lock(mutex);
        if (index.find(resourceID) != index.end()) {
            index.erase(resourceID);
            return true;
        }
        return false;
    }

    ResourceUsage* find(int resourceID) const {
        std::shared_lock<std::shared_mutex> lock(mutex);
        auto it = index.find(resourceID);
        if (it != index.end()) {
            return &it->second;
        }
        return nullptr;
    }

    void update(const ResourceUsage& usage) {
        std::unique_lock<std::shared_mutex> lock(mutex);
        if (index.find(usage.resourceID) != index.end()) {
            index[usage.resourceID] = usage;
        }
    }

    void monitorResources(long startTs, long endTs, double cpuThreshold, double memoryLimit) const {
        std::shared_lock<std::shared_mutex> lock(mutex);
        for (const auto& pair : index) {
            if (pair.second.timestamp >= startTs && pair.second.timestamp <= endTs &&
                pair.second.cpuUtilization > cpuThreshold &&
                pair.second.memoryUsage < memoryLimit) {
                // Process the resource usage
            }
        }
    }
};

int main() {
    ConcurrentResourceIndex index;
    ResourceUsage usage1(1, 1633072800, 5.5, 1024, 10);
    ResourceUsage usage2(2, 1633072900, 3.0, 512, 5);

    index.insert(usage1);
    index.insert(usage2);

    if (ResourceUsage* found = index.find(1)) {
        std::cout << "Found resource: ID=" << found->resourceID << ", CPU=" << found->cpuUtilization << std::endl;
    }

    index.update(ResourceUsage(1, 1633072800, 5.0, 1024, 10));

    index.monitorResources(1633072800, 1633072900, 4.0, 768);

    return 0;
}
