    unsigned char hash[MD5_DIGEST_LENGTH];
    struct Record *next;
} Record;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char **)userp)[0] = realloc(((char **)userp)[0], size * nmemb + 1);
    if (((char **)userp)[0]) == NULL) {
        return 0;
    }
    memcpy(((char **)userp)[0], contents, size * nmemb);
    ((char **)userp)[0][size * nmemb] = '\0';
    return size * nmemb;
}

Record* fetchAndTransformData(const char *url) {
    CURL *curl;
    CURLcode res;
    char *data = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            free(data);
            return NULL;
        }

        json_object *root = json_tokener_parse(data);
        if(root == NULL) {
            fprintf(stderr, "Failed to parse JSON data.\n");
            free(data);
            return NULL;
        }

        Record *head = NULL, **tail = &head;
        json_object_array_foreach(json_object_array_get_idx(root, 0), i, obj) {
            int key = json_object_get_int(json_object_object_get(obj, "key"));
            const char *value = json_object_get_string(json_object_object_get(obj, "value"));

            Record *new_record = (Record *)malloc(sizeof(Record));
            if(new_record == NULL) {
                fprintf(stderr, "Memory allocation failed.\n");
                free(data);
                json_object_put(root);
                return head;
            }
            new_record->key = key;
            new_record->value = strdup(value);
            MD5((unsigned char *)new_record->value, strlen(new_record->value), new_record->hash);
            new_record->next = NULL;

            *tail = new_record;
            tail = &new_record->next;
        }

        json_object_put(root);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return head;
}

void freeRecords(Record *head) {
    Record *current, *next;
    for(current = head; current != NULL; current = next) {
        next = current->next;
        free(current->value);
        free(current);
    }
}

int main() {
    const char *url = "https://api.example.com/data";
    Record *records = fetchAndTransformData(url);

    if(records == NULL) {
        fprintf(stderr, "Failed to fetch and transform data.\n");
        return 1;
    }

    // Process the records as needed
    freeRecords(records);
    return 0;
}
