#define MAX_STREAMS 100
#define INITIAL_SIZE 1024
#define RESIZE_THRESHOLD 0.75

typedef struct {
    double value;
} Record;

typedef struct {
    int offset;
    float* keys;
    int key_count;
    Record* records;
    int record_size;
    int record_capacity;
} DataStream;

int hash_function(float key, int capacity) {
    return (int)((key * capacity) / 3.14159); // Example hash function
}

void initialize_stream(DataStream* stream, int offset, float* keys, int key_count) {
    if (!stream || !keys || key_count <= 0) {
        fprintf(stderr, "Invalid input for data stream initialization.\n");
        return;
    }

    stream->offset = offset;
    stream->keys = keys;
    stream->key_count = key_count;

    // Pre-allocate memory for records
    stream->record_capacity = INITIAL_SIZE;
    stream->records = (Record*)malloc(stream->record_capacity * sizeof(Record));
    if (!stream->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }
    memset(stream->records, 0, stream->record_capacity * sizeof(Record));

    // Initialize records
    for (int i = 0; i < key_count; ++i) {
        int index = hash_function(keys[i], stream->record_capacity);
        while (stream->records[index].value != 0) { // Handle collisions
            fprintf(stderr, "Collision detected at index %d. Adjusting hash function.\n", index);
            index = (index + 1) % stream->record_capacity;
        }
        stream->records[index].value = exp(keys[i]);
    }

    stream->record_size = key_count;
}

void resize_records(DataStream* stream) {
    if (!stream || stream->record_size == stream->record_capacity) {
        return;
    }

    int new_capacity = (int)(stream->record_capacity * 2);
    Record* new_records = (Record*)realloc(stream->records, new_capacity * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed.\n");
        return;
    }
    memset(new_records + stream->record_size, 0, (new_capacity - stream->record_size) * sizeof(Record));

    // Rehash records
    for (int i = 0; i < stream->record_size; ++i) {
        if (stream->records[i].value != 0) {
            int index = hash_function(stream->keys[i], new_capacity);
            while (new_records[index].value != 0) { // Handle collisions
                fprintf(stderr, "Collision detected at index %d. Adjusting hash function.\n", index);
                index = (index + 1) % new_capacity;
            }
            new_records[index] = stream->records[i];
        }
    }

    free(stream->records);
    stream->records = new_records;
    stream->record_capacity = new_capacity;
}

void process_data_streams(DataStream* streams, int stream_count) {
    if (!streams || stream_count <= 0) {
        fprintf(stderr, "Invalid input for data stream processing.\n");
        return;
    }

    for (int i = 0; i < stream_count; ++i) {
        DataStream* stream = &streams[i];
        if (stream->record_size / (double)stream->record_capacity > RESIZE_THRESHOLD) {
            resize_records(stream);
        }
    }
}

void cleanup_streams(DataStream* streams, int stream_count) {
    for (int i = 0; i < stream_count; ++i) {
        DataStream* stream = &streams[i];
        free(stream->records);
    }
}
