void init_dao(DAO* dao) {
    dao->head = NULL;
    pthread_mutex_init(&dao->lock, NULL);
}

void destroy_dao(DAO* dao) {
    Record* current = dao->head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&dao->lock);
}

Record* create_record(int key, long offset, double value, void (*process)(Record*)) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    record->key = key;
    record->offset = offset;
    record->value = value;
    record->process = process;
    record->next = NULL;
    return record;
}

void insert_record(DAO* dao, Record* record) {
    pthread_mutex_lock(&dao->lock);
    if (dao->head == NULL || dao->head->key > record->key) {
        record->next = dao->head;
        dao->head = record;
    } else {
        Record* current = dao->head;
        while (current->next != NULL && current->next->key < record->key) {
            current = current->next;
        }
        record->next = current->next;
        current->next = record;
    }
    pthread_mutex_unlock(&dao->lock);
}

void traverse_records(DAO* dao, void (*callback)(Record*)) {
    pthread_mutex_lock(&dao->lock);
    Record* current = dao->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&dao->lock);
}

