#define MAX_CACHE_SIZE 1024

typedef struct {
    char* payload;
    int status_code;
} Response;

typedef struct {
    Response** cache;
    size_t size;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_size) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->size = initial_size;
    cache->cache = (Response**)calloc(initial_size, sizeof(Response*));
    if (!cache->cache) {
        free(cache);
        return NULL;
    }

    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(Cache* cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        if (cache->cache[i]) {
            free(cache->cache[i]->payload);
            free(cache->cache[i]);
        }
    }
    free(cache->cache);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void insert_response(Cache* cache, int status_code, const char* payload) {
    pthread_mutex_lock(&cache->lock);
    size_t index = (size_t)status_code % cache->size;
    while (cache->cache[index]) {
        if (cache->cache[index]->status_code == status_code) {
            free(cache->cache[index]->payload);
            break;
        }
        index = (index + 1) % cache->size;
    }

    Response* new_response = (Response*)malloc(sizeof(Response));
    if (!new_response) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    new_response->status_code = status_code;
    new_response->payload = strdup(payload);
    cache->cache[index] = new_response;

    pthread_mutex_unlock(&cache->lock);
}

Response* lookup_response(Cache* cache, int status_code) {
    pthread_mutex_lock(&cache->lock);
    size_t index = (size_t)status_code % cache->size;
    while (cache->cache[index]) {
        if (cache->cache[index]->status_code == status_code) {
            Response* response = cache->cache[index];
            pthread_mutex_unlock(&cache->lock);
            return response;
        }
        index = (index + 1) % cache->size;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void remove_response(Cache* cache, int status_code) {
    pthread_mutex_lock(&cache->lock);
    size_t index = (size_t)status_code % cache->size;
    while (cache->cache[index]) {
        if (cache->cache[index]->status_code == status_code) {
            free(cache->cache[index]->payload);
            free(cache->cache[index]);
            cache->cache[index] = NULL;
            break;
        }
        index = (index + 1) % cache->size;
    }

    pthread_mutex_unlock(&cache->lock);
}

void compact_cache(Cache* cache) {
    pthread_mutex_lock(&cache->lock);
    size_t new_size = cache->size / 2;
    Response** new_cache = (Response**)calloc(new_size, sizeof(Response*));
    if (!new_cache) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    for (size_t i = 0; i < cache->size; ++i) {
        if (cache->cache[i]) {
            size_t index = (size_t)cache->cache[i]->status_code % new_size;
            while (new_cache[index]) {
                index = (index + 1) % new_size;
            }
            new_cache[index] = cache->cache[i];
        }
    }

    free(cache->cache);
    cache->cache = new_cache;
    cache->size = new_size;

    pthread_mutex_unlock(&cache->lock);
}
