#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 500
#define RECORD_HASH_RANGE 100

typedef struct {
    int value;
} record;

int hash_function(int key) {
    // Custom hash function to minimize collisions and distribute values uniformly
    return (key * 31 + 7) % RECORD_HASH_RANGE;
}

void process_data(long* offsets, int* keys, int num_keys, record** records, size_t* total_memory_used, size_t max_memory_threshold) {
    if (!offsets || !keys || num_keys <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    if (num_keys > MAX_KEY_SIZE) {
        fprintf(stderr, "Number of keys exceeds maximum limit\n");
        return;
    }

    size_t required_memory = sizeof(record) * num_keys;
    if (*total_memory_used + required_memory > max_memory_threshold) {
        fprintf(stderr, "Memory allocation would exceed threshold\n");
        return;
    }

    *records = realloc(*records, required_memory);
    if (!*records) {
        perror("Failed to allocate memory for records");
        return;
    }

    *total_memory_used += required_memory;

    for (int i = 0; i < num_keys; i++) {
        (*records)[i].value = hash_function(keys[i]);
    }
}

