#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
    unsigned char *metadata;
} DataPacket;

typedef struct {
    DataPacket **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (DataPacket**)calloc(initial_capacity, sizeof(DataPacket*));
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        DataPacket *packet = table->buckets[i];
        if (packet != NULL) {
            free(packet->metadata);
            free(packet);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(int packet_id, size_t capacity) {
    return (size_t)(packet_id % capacity);
}

void add_packet(HashTable *table, DataPacket *packet) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(packet->packet_id, table->capacity);
    while (table->buckets[index] != NULL) {
        if (table->buckets[index]->packet_id == packet->packet_id) {
            // Update existing packet
            free(table->buckets[index]->metadata);
            table->buckets[index]->timestamp = packet->timestamp;
            table->buckets[index]->payload_length = packet->payload_length;
            table->buckets[index]->metadata = (unsigned char*)malloc(packet->payload_length);
            memcpy(table->buckets[index]->metadata, packet->metadata, packet->payload_length);
            pthread_mutex_unlock(&table->lock);
            return;
        }
        index = (index + 1) % table->capacity;
    }
    // Add new packet
    table->buckets[index] = packet;
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

DataPacket* get_packet(HashTable *table, int packet_id) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(packet_id, table->capacity);
    while (table->buckets[index] != NULL) {
        if (table->buckets[index]->packet_id == packet_id) {
            DataPacket *result = (DataPacket*)malloc(sizeof(DataPacket));
            result->timestamp = table->buckets[index]->timestamp;
            result->packet_id = table->buckets[index]->packet_id;
            result->payload_length = table->buckets[index]->payload_length;
            result->metadata = (unsigned char*)malloc(result->payload_length);
            memcpy(result->metadata, table->buckets[index]->metadata, result->payload_length);
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        index = (index + 1) % table->capacity;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void remove_packet(HashTable *table, int packet_id) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(packet_id, table->capacity);
    while (table->buckets[index] != NULL) {
        if (table->buckets[index]->packet_id == packet_id) {
            free(table->buckets[index]->metadata);
            free(table->buckets[index]);
            table->buckets[index] = NULL;
            table->size--;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        index = (index + 1) % table->capacity;
    }
    pthread_mutex_unlock(&table->lock);
}
