#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000000

typedef struct {
    time_t timestamp;
    int packet_id;
    size_t payload_length;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    pthread_mutex_t lock;
    int count;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_packet(PacketManager *manager, DataPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Overflow
    }
    manager->packets[manager->count++] = &packet;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_packet(PacketManager *manager, int packet_id, DataPacket new_packet) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i]->packet_id == packet_id) {
            manager->packets[i] = &new_packet;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Packet not found
}

DataPacket* get_packets_by_timestamp_range(PacketManager *manager, time_t start_time, time_t end_time) {
    static DataPacket result[MAX_PACKETS];
    int count = 0;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i]->timestamp >= start_time && manager->packets[i]->timestamp <= end_time) {
            result[count++] = *manager->packets[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return result;
}

int remove_packet_by_timestamp(PacketManager *manager, time_t timestamp) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i]->timestamp == timestamp) {
            for (int j = i; j < manager->count - 1; j++) {
                manager->packets[j] = manager->packets[j + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Packet not found
}

void destroy_packet_manager(PacketManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}
