typedef struct {
    int offset;
    char *key;
    char *record;
} DataBatch;

typedef unsigned long (*HashFunction)(const char*);

DataBatch* createBatch(int size, HashFunction hashFunc, int logMemory) {
    DataBatch *batch = (DataBatch*)malloc(size * sizeof(DataBatch));
    if (!batch) {
        fprintf(stderr, "Failed to allocate memory for batch\n");
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        batch[i].offset = i;
        batch[i].key = (char*)malloc(256 * sizeof(char));
        if (!batch[i].key) {
            fprintf(stderr, "Failed to allocate memory for key\n");
            freeBatch(batch, i);
            return NULL;
        }
        batch[i].record = (char*)malloc(256 * sizeof(char));
        if (!batch[i].record) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            freeBatch(batch, i);
            return NULL;
        }

        // Initialize record with hash of key
        snprintf(batch[i].key, 256, "Key%d", i);
        batch[i].record[0] = '\0';
        hashFunc(batch[i].key, batch[i].record);

        if (logMemory) {
            printf("Allocated memory for batch[%d]: key=%p, record=%p\n", i, batch[i].key, batch[i].record);
        }
    }

    return batch;
}

void freeBatch(DataBatch *batch, int size) {
    for (int i = 0; i < size; ++i) {
        if (batch[i].key) free(batch[i].key);
        if (batch[i].record) free(batch[i].record);
    }
    free(batch);
}

unsigned long simpleHash(const char *str, char *result) {
    unsigned long hash = 0;
    while (*str) {
        hash = hash * 31 + *str++;
    }
    snprintf(result, 256, "%lu", hash);
    return hash;
}

int main() {
    DataBatch *batch = createBatch(10, simpleHash, 1);
    if (batch) {
        // Process batch
        freeBatch(batch, 10);
    }

    return 0;
}
