#define MAX_POINTS 1024
#define MAX_POLYGONS 512
#define MAX_STRING_LENGTH 256

typedef struct {
    float x, y;
} point;

typedef struct {
    int num_points;
    int* points;
} polygon;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

polygon* create_polygon(int num_points) {
    if (num_points > MAX_POINTS) {
        fprintf(stderr, "Too many points for a polygon\n");
        exit(EXIT_FAILURE);
    }
    polygon* poly = allocate_memory(sizeof(polygon));
    poly->num_points = num_points;
    poly->points = allocate_memory(num_points * sizeof(int));
    return poly;
}

void free_polygon(polygon* poly) {
    if (poly) {
        free_memory(poly->points);
        free_memory(poly);
    }
}

void serialize_polygon(const polygon* poly, FILE* file) {
    fwrite(&poly->num_points, sizeof(int), 1, file);
    fwrite(poly->points, sizeof(int), poly->num_points, file);
}

int deserialize_polygon(polygon* poly, FILE* file) {
    int num_points;
    if (fread(&num_points, sizeof(int), 1, file) != 1) return -1;
    if (num_points > MAX_POINTS) return -1;
    free_memory(poly->points);
    poly->num_points = num_points;
    poly->points = allocate_memory(num_points * sizeof(int));
    if (fread(poly->points, sizeof(int), num_points, file) != num_points) {
        free_memory(poly->points);
        return -1;
    }
    return 0;
}

int main() {
    polygon* my_polygon = create_polygon(3);
    my_polygon->points[0] = 0;
    my_polygon->points[1] = 1;
    my_polygon->points[2] = 2;

    FILE* file = fopen("polygon.dat", "wb");
    if (file) {
        serialize_polygon(my_polygon, file);
        fclose(file);
    }

    polygon* loaded_polygon = create_polygon(0);
    file = fopen("polygon.dat", "rb");
    if (file) {
        int result = deserialize_polygon(loaded_polygon, file);
        if (result == 0) {
            printf("Polygon loaded successfully\n");
        } else {
            printf("Failed to load polygon\n");
        }
        fclose(file);
    }

    free_polygon(my_polygon);
    free_polygon(loaded_polygon);

    return 0;
}
