#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 100000

typedef struct NetworkSession {
    int sessionId;
    char clientIP[16];
    time_t startTimestamp;
    time_t endTimestamp;
    size_t byteCount;
} NetworkSession;

typedef struct SessionNode {
    NetworkSession session;
    struct SessionNode *next;
} SessionNode;

typedef struct SessionManager {
    SessionNode *sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
} SessionManager;

void initSessionManager(SessionManager *manager) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        manager->sessions[i] = NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

void addSession(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    int index = session->sessionId % MAX_SESSIONS;
    SessionNode *newNode = (SessionNode *)malloc(sizeof(SessionNode));
    newNode->session = *session;
    newNode->next = manager->sessions[index];
    manager->sessions[index] = newNode;
    pthread_mutex_unlock(&manager->lock);
}

void updateSession(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    int index = session->sessionId % MAX_SESSIONS;
    SessionNode *current = manager->sessions[index];
    while (current != NULL) {
        if (current->session.sessionId == session->sessionId) {
            current->session = *session;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

NetworkSession* getSession(SessionManager *manager, int sessionId) {
    pthread_mutex_lock(&manager->lock);
    NetworkSession *result = NULL;
    int index = sessionId % MAX_SESSIONS;
    SessionNode *current = manager->sessions[index];
    while (current != NULL) {
        if (current->session.sessionId == sessionId) {
            result = &current->session;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return result;
}

void terminateSession(SessionManager *manager, int sessionId) {
    pthread_mutex_lock(&manager->lock);
    int index = sessionId % MAX_SESSIONS;
    SessionNode *current = manager->sessions[index];
    SessionNode *prev = NULL;
    while (current != NULL) {
        if (current->session.sessionId == sessionId) {
            if (prev == NULL) {
                manager->sessions[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroySessionManager(SessionManager *manager) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        SessionNode *current = manager->sessions[i];
        while (current != NULL) {
            SessionNode *next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&manager->lock);
}
