#include <stdio.h>
#include <stdlib.h>

#define MAX_LIST_SIZE 1000

typedef struct Node {
    char value;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    int size;
    int max_size;
} LinkedList;

void initList(LinkedList* list, int max_size) {
    if (max_size > MAX_LIST_SIZE) {
        printf("Error: Maximum list size exceeded.\n");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
}

void insertNode(LinkedList* list, char value) {
    if (list->size >= list->max_size) {
        printf("Warning: List is nearly full. Consider optimizing memory usage.\n");
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    newNode->value = value;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    list->size++;
}

void traverseList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("%c ", current->value);
        current = current->next;
    }
    printf("\n");
}

void freeList(LinkedList* list) {
    Node* current = list->head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
}

int main() {
    LinkedList myList;
    initList(&myList, MAX_LIST_SIZE);

    insertNode(&myList, 'A');
    insertNode(&myList, 'B');
    insertNode(&myList, 'C');

    traverseList(&myList);

    freeList(&myList);

    return 0;
}
