#define MAX_RECORD_SIZE 50

typedef struct Record {
    int value;
    char data[MAX_RECORD_SIZE];
    struct Record* next;
} Record;

Record* create_record(int value, const char* data) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;
    new_record->value = value;
    strncpy(new_record->data, data, MAX_RECORD_SIZE - 1);
    new_record->data[MAX_RECORD_SIZE - 1] = '\0';
    new_record->next = NULL;
    return new_record;
}

void insert_sorted(Record** head, Record* new_record) {
    if (!new_record) return;

    if (*head == NULL || (*head)->value >= new_record->value) {
        new_record->next = *head;
        *head = new_record;
    } else {
        Record* current = *head;
        while (current->next != NULL && current->next->value < new_record->value) {
            current = current->next;
        }
        new_record->next = current->next;
        current->next = new_record;
    }
}

void print_list(Record* head) {
    Record* current = head;
    while (current != NULL) {
        printf("Value: %d, Data: %s\n", current->value, current->data);
        current = current->next;
    }
}

void free_list(Record** head) {
    Record* current = *head;
    Record* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    // Example usage
    Record* head = NULL;

    // Simulate external data source
    int offsets[] = {3, 1, 2};
    int keys[] = {50, 40, 60};
    const char* data[] = {"Data1", "Data2", "Data3"};

    for (int i = 0; i < 3; i++) {
        Record* new_record = create_record(keys[i], data[i]);
        if (new_record) {
            insert_sorted(&head, new_record);
        } else {
            printf("Failed to allocate memory for record %d\n", i);
        }
    }

    print_list(head);

    free_list(&head);

    return 0;
}
