#define MAX_SESSIONS 50000
#define SESSION_STATS_SIZE 1024

typedef struct {
    int user_id;
    time_t login_time;
    char session_stats[SESSION_STATS_SIZE];
} USER_SESSION_T;

typedef struct {
    USER_SESSION_T sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
    size_t count;
} SESSION_MANAGER_T;

void init_session_manager(SESSION_MANAGER_T *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int insert_session(SESSION_MANAGER_T *manager, USER_SESSION_T session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Out of space
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_session(SESSION_MANAGER_T *manager, int user_id, time_t login_time, USER_SESSION_T new_session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].user_id == user_id && manager->sessions[i].login_time == login_time) {
            manager->sessions[i] = new_session;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

int get_session(SESSION_MANAGER_T *manager, int user_id, time_t login_time, USER_SESSION_T *session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].user_id == user_id && manager->sessions[i].login_time == login_time) {
            *session = manager->sessions[i];
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

void aggregate_and_report(SESSION_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        // Aggregate and report session statistics here
        printf("User ID: %d, Login Time: %ld\n", manager->sessions[i].user_id, manager->sessions[i].login_time);
    }
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    SESSION_MANAGER_T manager;
    init_session_manager(&manager);

    USER_SESSION_T session = {1, time(NULL), "Initial Stats"};
    insert_session(&manager, session);

    USER_SESSION_T updated_session = {1, time(NULL), "Updated Stats"};
    update_session(&manager, 1, time(NULL), updated_session);

    USER_SESSION_T retrieved_session;
    if (get_session(&manager, 1, time(NULL), &retrieved_session) == 0) {
        printf("Retrieved Session: User ID %d, Login Time %ld\n", retrieved_session.user_id, retrieved_session.login_time);
    }

    aggregate_and_report(&manager);

    return 0;
}
