typedef struct value {
    char *str;
    int key;
} Value;

typedef struct node {
    Value *data;
    struct node *next;
} Node;

typedef struct list {
    Node *head;
    size_t count;
} List;

List* create_list() {
    List *list = (List*)malloc(sizeof(List));
    if (list) {
        list->head = NULL;
        list->count = 0;
    }
    return list;
}

void insert_node(List *list, int index, Value *value) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = value;
    new_node->next = NULL;

    if (index == 0 || !list->head) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node *current = list->head;
        for (int i = 1; current && i < index; i++) {
            current = current->next;
        }
        if (current) {
            new_node->next = current->next;
            current->next = new_node;
        }
    }
    list->count++;
}

Node* find_node(List *list, int key) {
    Node *current = list->head;
    while (current) {
        if (current->data->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void delete_node(List *list, int index) {
    if (index < 0 || index >= list->count) return;

    Node *current = list->head;
    if (index == 0) {
        list->head = current->next;
        free(current);
    } else {
        for (int i = 1; current && i < index; i++) {
            current = current->next;
        }
        if (current && current->next) {
            Node *temp = current->next;
            current->next = temp->next;
            free(temp);
        }
    }
    list->count--;
}

void free_list(List *list) {
    Node *current = list->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp->data->str);
        free(temp->data);
        free(temp);
    }
    free(list);
}
