#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000

typedef struct {
    time_t timestamp;
    int packet_id;
    int payload_length;
    int acknowledged;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
    FILE *log_file;
} NetworkModule;

NetworkModule *init_network_module(const char *log_filename) {
    NetworkModule *module = (NetworkModule *)malloc(sizeof(NetworkModule));
    if (!module) {
        perror("Failed to allocate memory for network module");
        return NULL;
    }
    module->count = 0;
    pthread_mutex_init(&module->lock, NULL);
    module->log_file = fopen(log_filename, "a");
    if (!module->log_file) {
        perror("Failed to open log file");
        free(module);
        return NULL;
    }
    return module;
}

void add_packet(NetworkModule *module, DataPacket packet) {
    pthread_mutex_lock(&module->lock);
    if (module->count >= MAX_PACKETS) {
        fprintf(stderr, "Error: Packet array overflow\n");
        pthread_mutex_unlock(&module->lock);
        return;
    }
    module->packets[module->count++] = &packet;
    fprintf(module->log_file, "Added packet with ID %d at timestamp %ld\n", packet.packet_id, packet.timestamp);
    pthread_mutex_unlock(&module->lock);
}

void update_packet(NetworkModule *module, int packet_id, DataPacket new_data) {
    pthread_mutex_lock(&module->lock);
    for (int i = 0; i < module->count; ++i) {
        if (module->packets[i]->packet_id == packet_id) {
            *module->packets[i] = new_data;
            fprintf(module->log_file, "Updated packet with ID %d\n", packet_id);
            pthread_mutex_unlock(&module->lock);
            return;
        }
    }
    fprintf(stderr, "Error: Packet with ID %d not found\n", packet_id);
    pthread_mutex_unlock(&module->lock);
}

void mark_packet_as_acknowledged(NetworkModule *module, int packet_id) {
    pthread_mutex_lock(&module->lock);
    for (int i = 0; i < module->count; ++i) {
        if (module->packets[i]->packet_id == packet_id) {
            module->packets[i]->acknowledged = 1;
            fprintf(module->log_file, "Marked packet with ID %d as acknowledged\n", packet_id);
            pthread_mutex_unlock(&module->lock);
            return;
        }
    }
    fprintf(stderr, "Error: Packet with ID %d not found\n", packet_id);
    pthread_mutex_unlock(&module->lock);
}

void cleanup_packets(NetworkModule *module) {
    pthread_mutex_lock(&module->lock);
    for (int i = 0; i < module->count; ++i) {
        if (time(NULL) - module->packets[i]->timestamp > 3600) { // Example: Remove packets older than 1 hour
            free(module->packets[i]);
            module->packets[i] = NULL;
        }
    }
    int new_count = 0;
    for (int i = 0; i < module->count; ++i) {
        if (module->packets[i]) {
            module->packets[new_count++] = module->packets[i];
        }
    }
    module->count = new_count;
    pthread_mutex_unlock(&module->lock);
}

void *network_module_thread(void *arg) {
    NetworkModule *module = (NetworkModule *)arg;
    // Simulate network operations
    DataPacket packet = {time(NULL), 1, 1024, 0};
    add_packet(module, packet);
    update_packet(module, 1, (DataPacket){time(NULL), 1, 2048, 0});
    mark_packet_as_acknowledged(module, 1);
    cleanup_packets(module);
    return NULL;
}

int main() {
    NetworkModule *module = init_network_module("network_log.txt");
    if (!module) {
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, network_module_thread, module) != 0) {
        perror("Failed to create thread");
        free(module);
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    fclose(module->log_file);
    free(module);
    return EXIT_SUCCESS;
}
