#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define N 100
#define MAX_KEY 1000

typedef struct record {
    int value;
    char data[50];
    struct record *next;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    int size;
    int limit;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(int initial_size, int limit) {
    RecordManager *rm = (RecordManager*)malloc(sizeof(RecordManager));
    rm->offsets = (long*)calloc(initial_size, sizeof(long));
    rm->keys = (int*)calloc(initial_size, sizeof(int));
    rm->records = (Record**)calloc(initial_size, sizeof(Record*));
    rm->size = initial_size;
    rm->limit = limit;
    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

void destroy_record_manager(RecordManager *rm) {
    for (int i = 0; i < rm->size; i++) {
        Record *current = rm->records[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(rm->offsets);
    free(rm->keys);
    free(rm->records);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}

void add_record(RecordManager *rm, int key, int value, const char *data) {
    pthread_mutex_lock(&rm->lock);
    if (rm->size == 0) {
        rm->offsets = (long*)realloc(rm->offsets, sizeof(long));
        rm->keys = (int*)realloc(rm->keys, sizeof(int));
        rm->records = (Record**)realloc(rm->records, sizeof(Record*));
        rm->size = 1;
    }
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->value = value;
    strncpy(new_record->data, data, 50);
    new_record->next = NULL;

    int sum = 0;
    for (int i = 0; i < rm->size; i++) {
        Record *current = rm->records[i];
        while (current != NULL) {
            sum += current->value;
            current = current->next;
        }
    }

    if (sum + value > rm->limit) {
        int total_value = 0;
        for (int i = 0; i < rm->size; i++) {
            Record *current = rm->records[i];
            while (current != NULL) {
                total_value += current->value;
                current = current->next;
            }
        }

        float scale_factor = (float)(rm->limit - sum + value) / total_value;
        for (int i = 0; i < rm->size; i++) {
            Record *current = rm->records[i];
            while (current != NULL) {
                current->value = (int)((float)current->value * scale_factor);
                current = current->next;
            }
        }
    }

    int index = rm->size - 1;
    if (rm->keys[index] < key) {
        for (int i = rm->size - 2; i >= 0; i--) {
            if (rm->keys[i] < key) {
                break;
            }
            rm->offsets[i + 1] = rm->offsets[i];
            rm->keys[i + 1] = rm->keys[i];
            rm->records[i + 1] = rm->records[i];
        }
        rm->offsets[index] = (long)new_record;
        rm->keys[index] = key;
        rm->records[index] = new_record;
    } else {
        for (int i = rm->size - 2; i >= 0; i--) {
            if (rm->keys[i] < key) {
                break;
            }
            rm->offsets[i + 1] = rm->offsets[i];
            rm->keys[i + 1] = rm->keys[i];
        }
        rm->offsets[index] = (long)new_record;
        rm->keys[index] = key;
        rm->records[index] = new_record;
    }

    rm->size++;
    pthread_mutex_unlock(&rm->lock);
}

void print_records(RecordManager *rm) {
    pthread_mutex_lock(&rm->lock);
    for (int i = 0; i < rm->size; i++) {
        Record *current = rm->records[i];
        while (current != NULL) {
            printf("Key: %d, Value: %d, Data: %s\n", current->value, current->data);
            current = current->next;
        }
    }
    pthread_mutex_unlock(&rm->lock);
}
