#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB

typedef struct {
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = NULL;
    collection->capacity = 0;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (collection->records) free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int load_records_from_file(RecordCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    size_t capacity = 1024; // Initial capacity
    Record* new_records = (Record*)realloc(collection->records, capacity * sizeof(Record));
    if (!new_records) {
        fclose(file);
        return -1;
    }
    collection->records = new_records;
    collection->capacity = capacity;

    size_t count = 0;
    while (fscanf(file, "%d", &collection->records[count].value) == 1) {
        if (++count >= capacity) {
            capacity *= 2;
            Record* new_records = (Record*)realloc(collection->records, capacity * sizeof(Record));
            if (!new_records) {
                fclose(file);
                return -1;
            }
            collection->records = new_records;
            collection->capacity = capacity;
        }
    }

    collection->size = count;
    fclose(file);
    return 0;
}

int add_record(RecordCollection* collection, int value) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size].value = value;
    collection->size++;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int get_record(RecordCollection* collection, size_t index, int* value) {
    if (index >= collection->size) return -1;

    *value = collection->records[index].value;
    return 0;
}
