#define NR_PHY_STATS_T struct nr_phy_stats_t
NR_PHY_STATS_T {
    int PCI;
    int NR_SFN;
    // Add other fields as needed
};

typedef struct node {
    NR_PHY_STATS_T data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray* array) {
    array->head = NULL;
    pthread_mutex_init(&array->mutex, NULL);
}

void addEntry(DynamicArray* array, NR_PHY_STATS_T data) {
    pthread_mutex_lock(&array->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = array->head;
    array->head = newNode;
    pthread_mutex_unlock(&array->mutex);
}

void removeEntry(DynamicArray* array, int PCI) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data.PCI == PCI) {
            if (previous == NULL) {
                array->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

void updateEntry(DynamicArray* array, int PCI, NR_PHY_STATS_T newData) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;

    while (current != NULL) {
        if (current->data.PCI == PCI) {
            current->data = newData;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

void logOperation(DynamicArray* array, const char* operation, NR_PHY_STATS_T data) {
    // Implement file-based logging with thread safety
    FILE* logFile = fopen("operation_log.txt", "a");
    if (logFile != NULL) {
        pthread_mutex_lock(&array->mutex);
        fprintf(logFile, "%s: PCI=%d, SFN=%d\n", operation, data.PCI, data.NR_SFN);
        pthread_mutex_unlock(&array->mutex);
        fclose(logFile);
    }
}

void destroyDynamicArray(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->mutex);
}
