#include <iostream>
#include <forward_list>
#include <string>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>
#include <cstdlib>
#include <cstring>

struct Record {
    unsigned long id;
    unsigned long timestamp;
    void* payload;
};

class DataStore {
private:
    std::forward_list<Record> records;
    std::unordered_map<unsigned long, std::forward_list<Record>::iterator> index;
    std::mutex mutex;
    size_t memoryUsage;
    size_t maxMemory;

public:
    DataStore(size_t maxMemory) : maxMemory(maxMemory), memoryUsage(0) {}

    void insertAfterTimeout(const std::string& target, const std::string& insertion, unsigned long timeout, unsigned long T) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = records.begin();
        while (it != records.end()) {
            if (it->payload == nullptr || std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - std::chrono::system_clock::from_time_t(it->timestamp)).count() > timeout) {
                memoryUsage -= calculateMemoryUsage(it->payload);
                delete[] static_cast<char*>(it->payload);
                it = records.erase_after(it);
            } else {
                ++it;
            }
        }

        if (memoryUsage + calculateMemoryUsage(insertion.c_str()) <= T) {
            Record newRecord{generateUniqueId(), std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()), new char[insertion.size()]};
            std::memcpy(newRecord.payload, insertion.c_str(), insertion.size());
            records.push_back(newRecord);
            index[newRecord.id] = --records.end();
            memoryUsage += calculateMemoryUsage(insertion.c_str());
        }
    }

    void* retrieve(unsigned long id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = index.find(id);
        if (it != index.end()) {
            return it->second->payload;
        }
        return nullptr;
    }

private:
    unsigned long generateUniqueId() {
        static unsigned long id = 0;
        return ++id;
    }

    size_t calculateMemoryUsage(const void* payload) {
        return strlen(static_cast<const char*>(payload)) + sizeof(Record);
    }
};

int main() {
    DataStore store(1024 * 1024); // 1MB max memory
    store.insertAfterTimeout("target", "insertion", 5, 1024 * 1024);
    void* payload = store.retrieve(1);
    if (payload) {
        std::cout << "Retrieved payload: " << static_cast<char*>(payload) << std::endl;
    }
    return 0;
}
