from flask import Flask, request, jsonify
import os
import shutil
from PIL import Image
import threading

app = Flask(__name__)

def handleFileOperations(request):
    action = request.form.get('action')
    file = request.files['file']
    new_name = request.form.get('new_name', None)
    thumbnail_size = (int(request.form.get('thumbnail_width', 100)), int(request.form.get('thumbnail_height', 100)))
    quality = int(request.form.get('quality', 85))

    if action == 'upload':
        # Validate file metadata
        if not allowed_file(file.filename):
            return jsonify({"status": "error", "message": "Invalid file type"}), 400
        if file.content_length > MAX_FILE_SIZE:
            return jsonify({"status": "error", "message": "File too large"}), 413

        # Save the file to a temporary location
        temp_path = os.path.join(TEMP_DIR, secure_filename(file.filename))
        file.save(temp_path)

        # Handle large files asynchronously
        threading.Thread(target=process_large_file, args=(temp_path,)).start()

    elif action == 'rename':
        if not new_name:
            return jsonify({"status": "error", "message": "New name is required"}), 400

        old_path = os.path.join(UPLOAD_DIR, file.filename)
        new_path = os.path.join(UPLOAD_DIR, new_name)

        # Rename the file
        os.rename(old_path, new_path)

    elif action == 'delete':
        path = os.path.join(UPLOAD_DIR, file.filename)

        # Check if the file exists
        if not os.path.exists(path):
            return jsonify({"status": "error", "message": "File does not exist"}), 404

        # Delete the file
        os.remove(path)

    return jsonify({"status": "success", "message": "Operation completed"})

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def process_large_file(temp_path):
    try:
        # Move the file to permanent storage
        shutil.move(temp_path, PERMANENT_STORAGE_DIR)

        # Generate thumbnail if it's a JPEG
        if temp_path.lower().endswith('.jpg') or temp_path.lower().endswith('.jpeg'):
            generate_thumbnail(temp_path, thumbnail_size, quality)
    except Exception as e:
        print(f"Error processing file: {e}")

def generate_thumbnail(file_path, size, quality):
    try:
        with Image.open(file_path) as img:
            img.thumbnail(size)
            img.save(file_path, 'JPEG', quality=quality)
    except Exception as e:
        print(f"Error generating thumbnail: {e}")

if __name__ == '__main__':
    app.run(debug=True)
