    private Jedis jedis;

    public TransactionManager() {
        this.transactionList = new ArrayList<>();
        this.jedis = new Jedis("localhost");
    }

    public void addTransaction(TransactionRecord transaction) {
        // Add transaction to list and cache
        transactionList.add(transaction);
        jedis.set(transaction.getTransactionId(), transaction.toString());
    }

    public void updateTransaction(String transactionId, TransactionRecord updatedTransaction) {
        // Update transaction in list and cache
        for (int i = 0; i < transactionList.size(); i++) {
            if (transactionList.get(i).getTransactionId().equals(transactionId)) {
                transactionList.set(i, updatedTransaction);
                jedis.set(updatedTransaction.getTransactionId(), updatedTransaction.toString());
                break;
            }
        }
    }

    public void deleteTransaction(String transactionId) {
        // Remove transaction from list and cache
        transactionList.removeIf(t -> t.getTransactionId().equals(transactionId));
        jedis.del(transactionId);
    }

    public List<TransactionRecord> getTransactionsByTimeRange(LocalDateTime start, LocalDateTime end) {
        // Retrieve transactions within specified time range
        return transactionList.stream()
                .filter(t -> !t.getTimestamp().isBefore(start) && !t.getTimestamp().isAfter(end))
                .collect(Collectors.toList());
    }

