        return NULL;
    }

    // Step 1: Verify the existence of the directory path
    if (!externalDataSource->pathExists(inputPath)) {
        return NULL;
    }

    // Step 2: Resolve any symbolic links
    char resolvedPath[PATH_MAX];
    if (realpath(inputPath, resolvedPath) == NULL) {
        return NULL;
    }

    // Step 3: Check and append trailing slash if necessary
    int pathLength = strlen(resolvedPath);
    if ((resolvedPath[0] == '/' && pathLength > 1) || resolvedPath[pathLength - 1] != '/') {
        if (pathLength + 2 > sizeLimit) {
            return NULL;
        }
        resolvedPath[pathLength++] = '/';
        resolvedPath[pathLength] = '\0';
    }

    // Step 4: Check total length
    if (pathLength > sizeLimit) {
        return NULL;
    }

    // Step 5: Handle buffer overflow
    strncpy(resultBuffer, resolvedPath, sizeLimit);
    resultBuffer[sizeLimit - 1] = '\0';

    return resultBuffer;
}
