typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} log_severity;

typedef struct {
    unsigned long timestamp;
    char* message;
    log_severity severity;
} log_entry;

typedef struct {
    char** buffers;
    log_entry entries[MAX_LOG_ENTRIES];
    size_t buffer_size;
    size_t total_buffer_used;
    pthread_mutex_t lock;
    // Cache and cleanup mechanism
} resource_manager;

void init_resource_manager(resource_manager* rm, size_t N, size_t M) {
    rm->buffers = (char**)malloc(N * sizeof(char*));
    for (size_t i = 0; i < N; ++i) {
        rm->buffers[i] = (char*)malloc(M);
    }
    memset(rm->entries, 0, sizeof(log_entry) * MAX_LOG_ENTRIES);
    rm->buffer_size = M;
    rm->total_buffer_used = 0;
    pthread_mutex_init(&rm->lock, NULL);
}

void cleanup_resource_manager(resource_manager* rm) {
    for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
        free(rm->entries[i].message);
    }
    for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
        free(rm->buffers[i]);
    }
    pthread_mutex_destroy(&rm->lock);
    free(rm->buffers);
}

void log_message(resource_manager* rm, const char* message, log_severity severity) {
    pthread_mutex_lock(&rm->lock);

    // Check and adjust buffer size if necessary
    size_t new_size = strlen(message) + 1;
    if (new_size > rm->buffer_size) {
        for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
            free(rm->buffers[i]);
            rm->buffers[i] = (char*)realloc(rm->buffers[i], new_size);
        }
        rm->buffer_size = new_size;
    }

    // Find an available log entry
    for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
        if (rm->entries[i].message == NULL) {
            rm->entries[i].timestamp = time(NULL);
            rm->entries[i].severity = severity;
            rm->entries[i].message = strdup(message);
            break;
        }
    }

    pthread_mutex_unlock(&rm->lock);
}

void cleanup_old_logs(resource_manager* rm, size_t max_entries_to_cleanup) {
