#include <sys/socket.h>
#include <netdb.h>

#define MAX_IP_LEN 16

typedef struct {
    char *filename;
} FileData;

u_char* resolveDNS(const char *hostname) {
    struct addrinfo hints, *res, *p;
    u_char ip[MAX_IP_LEN];
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s\n", ipstr);

        // Copy the IP address to the output buffer
        strcpy(ip, (char*)addr);
    }

    freeaddrinfo(res); // free the linked list

    return ip;
}

void* processFile(void *arg) {
    FileData *data = (FileData *)arg;
    FILE *file = fopen(data->filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        // Process each line here
        printf("%s", line);
    }

    free(line);
    fclose(file);

    return NULL;
}

int main() {
    pthread_t thread1, thread2;
    FileData data1 = {"file1.txt"};
    FileData data2 = {"file2.txt"};

    if (pthread_create(&thread1, NULL, processFile, &data1) != 0) {
        perror("Error creating thread");
        return 1;
    }

    if (pthread_create(&thread2, NULL, processFile, &data2) != 0) {
        perror("Error creating thread");
        return 1;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
