#define MAX_SIZE 1000
#define THRESHOLD 500

typedef struct {
    int value;
    char* identifier;
} Record;

long* offsets = NULL;
int* keys = NULL;
Record** records = NULL;
size_t size = 0;
size_t capacity = 0;

void resize(size_t new_capacity) {
    if (new_capacity > MAX_SIZE) {
        fprintf(stderr, "Error: Maximum size exceeded.\n");
        exit(EXIT_FAILURE);
    }
    offsets = realloc(offsets, new_capacity * sizeof(long));
    keys = realloc(keys, new_capacity * sizeof(int));
    records = realloc(records, new_capacity * sizeof(Record*));
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    capacity = new_capacity;
}

void add_record(long offset, int key, const char* identifier) {
    if (size >= capacity) {
        resize(capacity * 2);
    }
    offsets[size] = offset;
    keys[size] = key;
    records[size] = malloc(sizeof(Record));
    records[size]->value = key;
    records[size]->identifier = strdup(identifier);
    size++;
}

void free_records() {
    for (size_t i = 0; i < size; i++) {
        free(records[i]->identifier);
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

int find_largest() {
    if (size == 0) {
        fprintf(stderr, "Error: Empty array.\n");
        return -1;
    }
    int largest = records[0]->value;
    for (size_t i = 1; i < size; i++) {
        if (records[i]->value > largest) {
            largest = records[i]->value;
        }
    }
    return largest;
}

int main() {
    long offset;
    int key;
    char identifier[256];
    while (scanf("%ld %d %s", &offset, &key, identifier) == 3) {
        add_record(offset, key, identifier);
    }
    printf("Largest integer: %d\n", find_largest());
    free_records();
    return 0;
}
