import java.io.*;
import java.util.Random;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class SensorDataLoader {

    private static final Logger logger = LoggerFactory.getLogger(SensorDataLoader.class);

    public static Object loadStateFromFile(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Failed to load state from file: {}", filePath, e);
            return null;
        }
    }

    public static SensorData[] initializeSensorData(int count, int tempRangeStart, int tempRangeEnd, boolean includeHumidity) {
        if (count <= 0 || tempRangeStart >= tempRangeEnd) {
            logger.warn("Invalid input parameters for sensor data initialization.");
            return new SensorData[0];
        }

        SensorData[] sensorData = new SensorData[count];
        Random random = new Random();

        try {
            for (int i = 0; i < count; i++) {
                int temperature = tempRangeStart + random.nextInt(tempRangeEnd - tempRangeStart);
                String unitCode = "C"; // Assuming Celsius for simplicity
                Double humidity = includeHumidity ? random.nextDouble() * 100 : null;

                sensorData[i] = new SensorData(temperature, unitCode, humidity);
            }
        } catch (OutOfMemoryError e) {
            logger.error("Out of memory error while initializing sensor data.", e);
            // Handle allocation failure gracefully
            System.gc(); // Request garbage collection
            return new SensorData[0];
        }

        return sensorData;
    }

    public static void main(String[] args) {
        String filePath = "state.ser";
        Object stateObject = loadStateFromFile(filePath);

        if (stateObject instanceof MoSTState) {
            logger.info("Loaded state object: {}", stateObject);
        } else {
            logger.info("No valid state object found.");
        }

        SensorData[] sensorData = initializeSensorData(10, -20, 50, true);
        for (SensorData data : sensorData) {
            logger.debug("Sensor Data: {}", data);
        }
    }
}

class SensorData implements Serializable {
    private static final long serialVersionUID = 1L;
    private int temperature;
    private String unitCode;
    private Double humidity;

    public SensorData(int temperature, String unitCode, Double humidity) {
        this.temperature = temperature;
        this.unitCode = unitCode;
        this.humidity = humidity;
    }

    @Override
    public String toString() {
        return "SensorData{" +
                "temperature=" + temperature +
                ", unitCode='" + unitCode + '\'' +
                ", humidity=" + humidity +
                '}';
    }
}

class MoSTState implements Serializable {
    // Define the fields and methods for MoSTState class
}
