    record* records = (record*)malloc(num_offsets * sizeof(record));
    if (!records) {
        *error_code = -1; // Memory allocation failed
        return NULL;
    }

    transform_keys(offsets, num_offsets, keys, records);
    return records;
}

void free_records(record* records, int num_offsets) {
    for (int i = 0; i < num_offsets; ++i) {
        records[i].key_ptr = NULL;
    }
    free(records);
}

