typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(size_t max_size) {
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_size);
    if (!memory_pool.pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = max_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    memory_pool.used_size = 0;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_pdu(size_t N) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_size + N > memory_pool.pool_size) {
        pthread_mutex_unlock(&memory_pool.lock);
        fprintf(stderr, "Memory pool overflow\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = &memory_pool.pool[memory_pool.used_size];
    memory_pool.used_size += N;
    pthread_mutex_unlock(&memory_pool.lock);

    for (size_t i = 0; i < N; i++) {
        pdu[i].ue_info_tag = generate_rx_ue_information_tag();
        pdu[i].rnti = generate_rnti();
        pdu[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }

    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t N) {
    pthread_mutex_lock(&memory_pool.lock);
    memory_pool.used_size -= N;
    pthread_mutex_unlock(&memory_pool.lock);
}

