using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Threading.Tasks;

public class CertificateManager
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, X509Certificate2> _certificateCache;
    private bool _isPaused;

    public CertificateManager()
    {
        _httpClient = new HttpClient();
        _certificateCache = new Dictionary<string, X509Certificate2>();
        _isPaused = false;
    }

    public void PauseOperations()
    {
        _isPaused = true;
    }

    public void ResumeOperations()
    {
        _isPaused = false;
    }

    public async Task<X509Certificate2> GetCertificateAsync(string provider, string userId)
    {
        if (_isPaused) throw new InvalidOperationException("Operations are paused.");

        var cacheKey = $"{provider}_{userId}";
        if (_certificateCache.ContainsKey(cacheKey))
        {
            return _certificateCache[cacheKey];
        }

        try
        {
            var response = await _httpClient.GetAsync($"https://api.{provider}.com/certificate?userId={userId}");
            response.EnsureSuccessStatusCode();
            var certificateBytes = await response.Content.ReadAsByteArrayAsync();

            var certificate = new X509Certificate2(certificateBytes);
            _certificateCache[cacheKey] = certificate;
            return certificate;
        }
        catch (HttpRequestException ex)
        {
            // Log the exception and retry logic here
            throw;
        }
    }

    public void ClearCache()
    {
        _certificateCache.Clear();
    }
}
