#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_SRB_RELEASE_COMMAND {
    int SRB_ID;
    int SRB_PRIORITY;
    char SRB_RELEASE_REASON[256];
    struct NFAPI_SRB_RELEASE_COMMAND *next;
} NFAPI_SRB_RELEASE_COMMAND;

typedef struct LinkedList {
    NFAPI_SRB_RELEASE_COMMAND *head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_command(LinkedList *list, NFAPI_SRB_RELEASE_COMMAND *command) {
    pthread_mutex_lock(&list->lock);
    command->next = list->head;
    list->head = command;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_SRB_RELEASE_COMMAND* remove_command(LinkedList *list, int SRB_ID) {
    pthread_mutex_lock(&list->lock);
    NFAPI_SRB_RELEASE_COMMAND *current = list->head;
    NFAPI_SRB_RELEASE_COMMAND *prev = NULL;

    while (current != NULL && current->SRB_ID != SRB_ID) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current;
}

void update_reason(LinkedList *list, int SRB_ID, const char *new_reason) {
    pthread_mutex_lock(&list->lock);
    NFAPI_SRB_RELEASE_COMMAND *current = list->head;

    while (current != NULL && current->SRB_ID != SRB_ID) {
        current = current->next;
    }

    if (current != NULL) {
        strncpy(current->SRB_RELEASE_REASON, new_reason, sizeof(current->SRB_RELEASE_REASON));
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_SRB_RELEASE_COMMAND *current = list->head;
    while (current != NULL) {
        NFAPI_SRB_RELEASE_COMMAND *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
