#define MAX_OFFSETS 1000
#define MAX_KEYS 1000

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int custom_hash(int key) {
    return abs(key) % MAX_KEYS;
}

record* initialize_arrays(json_object *config) {
    json_object *offsets_obj, *keys_obj;
    int offsets_size, keys_size;
    long *offsets;
    int *keys;
    record *records;

    if (!json_object_object_get_ex(config, "offsets", &offsets_obj)) {
        log_error("Missing 'offsets' key in JSON configuration.");
        return NULL;
    }
    if (!json_object_object_get_ex(config, "keys", &keys_obj)) {
        log_error("Missing 'keys' key in JSON configuration.");
        return NULL;
    }

    offsets_size = json_object_array_length(offsets_obj);
    keys_size = json_object_array_length(keys_obj);

    if (offsets_size > MAX_OFFSETS || keys_size > MAX_KEYS) {
        log_error("Array size exceeds maximum limit.");
        return NULL;
    }

    offsets = malloc(offsets_size * sizeof(long));
    keys = malloc(keys_size * sizeof(int));
    records = malloc(keys_size * sizeof(record));

    if (!offsets || !keys || !records) {
        log_error("Memory allocation failed.");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (int i = 0; i < offsets_size; i++) {
        json_object *offset_obj = json_object_array_get_idx(offsets_obj, i);
        if (!json_object_is_type(offset_obj, json_type_int)) {
            log_error("Invalid offset value in JSON configuration.");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        offsets[i] = json_object_get_int(offset_obj);
    }

    for (int i = 0; i < keys_size; i++) {
        json_object *key_obj = json_object_array_get_idx(keys_obj, i);
        if (!json_object_is_type(key_obj, json_type_int)) {
            log_error("Invalid key value in JSON configuration.");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        keys[i] = json_object_get_int(key_obj);

        records[i].value = 0; // Initialize record value
        records[i].offset_ptr = &offsets[custom_hash(keys[i])];
        records[i].key_ptr = &keys[i];
    }

    return records;
}

void free_arrays(record *records, int keys_size) {
    if (records) {
        for (int i = 0; i < keys_size; i++) {
            // No need to free individual elements as they are pointers
        }
        free(records);
    }
}
