sqlite3_stmt* create_sql_command(sqlite3* db, const char* sql, int argc, const char** argv) {
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        return NULL;
    }
    for (int i = 0; i < argc; i++) {
        if (sqlite3_bind_text(stmt, i + 1, argv[i], -1, SQLITE_STATIC) != SQLITE_OK) {
            fprintf(stderr, "SQL bind error: %s\n", sqlite3_errmsg(db));
            sqlite3_finalize(stmt);
            return NULL;
        }
    }
    return stmt;
