use tonic::{transport::Channel, Request};
use std::{
    env,
    time::{Duration, Instant},
};
use tokio::time::sleep;
use hyper_tls::HttpsConnector;

async fn create_grpc_client(
    service_name: &str,
    tls_verification: bool,
    metadata: Option<Metadata>,
    request_body: &[u8],
    deadline: Option<Instant>,
    max_retries: u32,
    total_duration_limit: Duration,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut retries = 0;
    let start_time = Instant::now();

    loop {
        if let Ok(channel) = create_channel(service_name, tls_verification).await {
            let mut client = YourGrpcServiceClient::new(channel);

            let request = Request::new(request_body.to_vec());
            if let Some(metadata) = metadata.clone() {
                request.metadata_mut().extend(metadata);
            }

            match client.your_grpc_method(request).await {
                Ok(response) => return Ok(()),
                Err(e) => {
                    if retries >= max_retries || start_time.elapsed() > total_duration_limit {
                        return Err(e.into());
                    }
                    retries += 1;
                    let backoff = calculate_exponential_backoff(retries);
                    sleep(backoff).await;
                }
            }
        } else {
            if retries >= max_retries || start_time.elapsed() > total_duration_limit {
                return Err("Failed to create channel".into());
            }
            retries += 1;
            let backoff = calculate_exponential_backoff(retries);
            sleep(backoff).await;
        }
    }
}

async fn create_channel(
    service_name: &str,
    tls_verification: bool,
) -> Result<Channel, Box<dyn std::error::Error>> {
    let resolver = DnsResolver::new();
    let address = resolver.resolve(service_name).await?;

    if tls_verification {
        let connector = HttpsConnector::new();
        Channel::builder()
            .default_service_address(address)
            .tls_connector(connector)
            .connect()
            .await
    } else {
        Channel::builder().default_service_address(address).connect().await
    }
}

fn calculate_exponential_backoff(retries: u32) -> Duration {
    let base = 100; // milliseconds
    let factor = 2.0;
    let max_duration = Duration::from_secs(60); // 1 minute

    let backoff = Duration::from_millis((base * factor.powi(retries as i32)) as u64);
    std::cmp::min(backoff, max_duration)
}
