    if (!manager) {
        perror("Failed to allocate memory for MemoryManager");
        return NULL;
    }
    pthread_mutex_init(&manager->mutex, NULL);
    manager->allocated_memory = 0;
    manager->memory_limit_kb = limit_kb * 1024; // Convert KB to bytes
    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_array(MemoryManager* manager, size_t N) {
    pthread_mutex_lock(&manager->mutex);

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t alignment = __alignof__(NFAPI_CRC_INDICATION_PDU_T);
    size_t padded_struct_size = ((struct_size + alignment - 1) / alignment) * alignment;

    size_t required_memory = N * padded_struct_size;
    if (manager->allocated_memory + required_memory > manager->memory_limit_kb) {
        pthread_mutex_unlock(&manager->mutex);
        fprintf(stderr, "Memory allocation exceeds limit\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(alignment, required_memory);
    if (!array) {
        perror("Failed to allocate memory for PDU array");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    manager->allocated_memory += required_memory;

    pthread_mutex_unlock(&manager->mutex);

    // Initialize the array elements here

    return array;
}

void free_pdu_array(MemoryManager* manager, NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
