#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 500

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t offset_size;
    size_t key_size;
    size_t record_count;
    pthread_mutex_t lock;
} dynamic_array;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int initialize_dynamic_array(dynamic_array *array, size_t initial_size) {
    array->offsets = (long *)malloc(initial_size * sizeof(long));
    array->keys = (int *)malloc(initial_size * sizeof(int));
    array->records = (record **)malloc(initial_size * sizeof(record *));
    if (!array->offsets || !array->keys || !array->records) {
        log_error("Memory allocation failed");
        return -1;
    }
    array->offset_size = initial_size;
    array->key_size = initial_size;
    array->record_count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return 0;
}

void free_dynamic_array(dynamic_array *array) {
    for (size_t i = 0; i < array->record_count; ++i) {
        free(array->records[i]);
    }
    free(array->offsets);
    free(array->keys);
    free(array->records);
    pthread_mutex_destroy(&array->lock);
}

int add_element(dynamic_array *array, long offset, int key) {
    if (array->record_count >= array->key_size) {
        log_error("Key array size exceeded");
        return -1;
    }
    if (array->record_count >= array->offset_size) {
        log_error("Offset array size exceeded");
        return -1;
    }

    pthread_mutex_lock(&array->lock);
    array->offsets[array->record_count] = offset;
    array->keys[array->record_count] = key;
    array->records[array->record_count] = (record *)malloc(sizeof(record));
    if (!array->records[array->record_count]) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    array->records[array->record_count]->value = key * 2; // Example value calculation
    ++array->record_count;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

int main() {
    dynamic_array my_array;
    if (initialize_dynamic_array(&my_array, 10) == 0) {
        add_element(&my_array, 12345, 6789);
        free_dynamic_array(&my_array);
    }
    return 0;
}
