typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

int nfapi_crc_array_init(NFAPI_CRC_ARRAY_T *array, size_t initial_capacity) {
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) return -1;
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return 0;
}

int nfapi_crc_array_add(NFAPI_CRC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = new_element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T nfapi_crc_array_get(NFAPI_CRC_ARRAY_T *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->size) {
        NFAPI_CRC_INDICATION_PDU_T zeroed_element = {0};
        pthread_mutex_unlock(&array->mutex);
        return zeroed_element;
    }
    NFAPI_CRC_INDICATION_PDU_T element = array->array[index];
    pthread_mutex_unlock(&array->mutex);
    return element;
}

void nfapi_crc_array_free(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}
