#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char* data;
    size_t data_size;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* structures[MAX_STRUCTURES];
int structure_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int create_structure(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, const char* data, size_t data_size) {
    pthread_mutex_lock(&mutex);
    if (structure_count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&mutex);
        return -1; // Insufficient memory
    }

    NFAPI_CRC_INDICATION_PDU_T* new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_structure) {
        pthread_mutex_unlock(&mutex);
        return -2; // Memory allocation failed
    }

    new_structure->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_structure->RNTI = RNTI;
    new_structure->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    if (data_size > 0) {
        new_structure->data = malloc(data_size);
        if (!new_structure->data) {
            free(new_structure);
            pthread_mutex_unlock(&mutex);
            return -3; // Memory allocation failed for data
        }
        memcpy(new_structure->data, data, data_size);
        new_structure->data_size = data_size;
    } else {
        new_structure->data = NULL;
        new_structure->data_size = 0;
    }

    structures[structure_count++] = new_structure;
    pthread_mutex_unlock(&mutex);
    return structure_count - 1; // Return index of created structure
}

int delete_structure(int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= structure_count) {
        pthread_mutex_unlock(&mutex);
        return -4; // Invalid index
    }

    NFAPI_CRC_INDICATION_PDU_T* to_delete = structures[index];
    free(to_delete->data);
    free(to_delete);

    for (int i = index; i < structure_count - 1; i++) {
        structures[i] = structures[i + 1];
    }
    structure_count--;
    pthread_mutex_unlock(&mutex);
    return 0;
}

