    uint8_t *data_buffer;
    size_t buffer_size;
    time_t last_accessed;
    int access_count;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *cache[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
} CacheManager;

int create_structure(CacheManager *manager, RX_UE_INFORMATION_TAG ue_info, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication, uint8_t *data_buffer, size_t buffer_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    new_struct->ue_info = ue_info;
    new_struct->rnti = rnti;
    new_struct->crc_indication = crc_indication;
    new_struct->data_buffer = malloc(buffer_size);
    if (!new_struct->data_buffer) {
        free(new_struct);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    memcpy(new_struct->data_buffer, data_buffer, buffer_size);
    new_struct->buffer_size = buffer_size;
    new_struct->last_accessed = time(NULL);
    new_struct->access_count = 0;
    manager->cache[manager->count++] = new_struct;
    pthread_mutex_unlock(&manager->lock);
    return manager->count - 1;
}

void update_structure(CacheManager *manager, int index, RX_UE_INFORMATION_TAG ue_info, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication, uint8_t *data_buffer, size_t buffer_size) {
    pthread_mutex_lock(&manager->lock);
    if (index >= 0 && index < manager->count) {
        NFAPI_CRC_INDICATION_PDU_T *struct_ptr = manager->cache[index];
        struct_ptr->ue_info = ue_info;
        struct_ptr->rnti = rnti;
        struct_ptr->crc_indication = crc_indication;
        free(struct_ptr->data_buffer);
        struct_ptr->data_buffer = malloc(buffer_size);
        if (struct_ptr->data_buffer) {
            memcpy(struct_ptr->data_buffer, data_buffer, buffer_size);
            struct_ptr->buffer_size = buffer_size;
        }
        struct_ptr->last_accessed = time(NULL);
        struct_ptr->access_count++;
    }
    pthread_mutex_unlock(&manager->lock);
}

void evict_least_frequently_used(CacheManager *manager) {
    pthread_mutex_lock(&manager->lock);
    int lfu_index = -1;
    int min_access_count = INT_MAX;
    for (int i = 0; i < manager->count; i++) {
        if (manager->cache[i]->access_count < min_access_count) {
            min_access_count = manager->cache[i]->access_count;
            lfu_index = i;
        }
    }
    if (lfu_index != -1) {
        free(manager->cache[lfu_index]->data_buffer);
        free(manager->cache[lfu_index]);
        for (int i = lfu_index; i < manager->count - 1; i++) {
            manager->cache[i] = manager->cache[i + 1];
        }
        manager->count--;
    }
    pthread_mutex_unlock(&manager->lock);
}

void cleanup_cache(CacheManager *manager, time_t max_age) {
    pthread_mutex_lock(&manager->lock);
    for (int i = manager->count - 1; i >= 0; i--) {
        if (time(NULL) - manager->cache[i]->last_accessed > max_age) {
            free(manager->cache[i]->data_buffer);
            free(manager->cache[i]);
            for (int j = i; j < manager->count - 1; j++) {
                manager->cache[j] = manager->cache[j + 1];
            }
            manager->count--;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

