        (*double_array)[i] = i * 1.1; // Example initialization
    }

    for (size_t i = 0; i < string_count; ++i) {
        (*string_array)[i] = malloc((strlen(strings[i]) + 1) * sizeof(char));
        if ((*string_array)[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            for (size_t j = 0; j < i; ++j) {
                free((*string_array)[j]);
            }
            free(*double_array);
            free(*string_array);
            free(*point_array);
            return;
        }
        strcpy((*string_array)[i], strings[i]);

        (*point_array)[i].x = generate_id(strings[i]) % 1000;
        (*point_array)[i].y = generate_id(strings[i]) / 1000;
    }

    // Simulate memory usage monitoring and defragmentation
    if (string_count > max_points) {
        *point_array = realloc(*point_array, string_count * sizeof(point));
        if (*point_array == NULL) {
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            for (size_t i = 0; i < string_count; ++i) {
                free((*string_array)[i]);
            }
            free(*double_array);
            free(*string_array);
            return;
        }
    }

    // Free allocated memory
    for (size_t i = 0; i < string_count; ++i) {
        free((*string_array)[i]);
    }
    free(*double_array);
    free(*string_array);
    free(*point_array);
}

