const fs = require('fs').promises;
const path = require('path');

async function readFilesInDirectory(directory, pattern, timeout) {
  const files = await fs.readdir(directory);
  const matchingFiles = files.filter(file => file.match(pattern));

  const results = [];
  for (const file of matchingFiles) {
    try {
      const filePath = path.join(directory, file);
      const content = await readWithTimeout(filePath, timeout);
      results.push(content);
    } catch (error) {
      logError(error, 'error.log');
    }
  }

  return results;
}

async function readWithTimeout(filePath, timeout) {
  return new Promise((resolve, reject) => {
    let timerId;

    const fileStream = fs.createReadStream(filePath, { encoding: 'utf8' });
    const contentChunks = [];

    fileStream.on('data', chunk => {
      contentChunks.push(chunk);
    });

    fileStream.on('end', () => {
      clearTimeout(timerId);
      resolve(contentChunks.join(''));
    });

    timerId = setTimeout(() => {
      fileStream.destroy();
      reject(new Error(`File read timed out after ${timeout}ms`));
    }, timeout);

    fileStream.on('error', error => {
      clearTimeout(timerId);
      reject(error);
    });
  });
}

function logError(error, logFilePath) {
  fs.appendFile(logFilePath, `${new Date().toISOString()} - ${error.message}\n`, (err) => {
    if (err) console.error('Failed to log error:', err);
  });
}
