#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 10000

typedef struct {
    int PCI;
    int NR_SFN;
    // Add other fields as needed
} NR_PHY_LAYER_STATS;

typedef struct {
    int key;
    NR_PHY_LAYER_STATS stats;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t capacity;
    size_t size;
} dynamic_array;

// Custom hash function
size_t custom_hash(int key) {
    return (size_t)key % MAX_RECORDS;
}

// Initialize the dynamic array
void init_dynamic_array(dynamic_array *arr, size_t initial_capacity) {
    arr->offsets = malloc(initial_capacity * sizeof(long));
    arr->keys = malloc(initial_capacity * sizeof(int));
    arr->records = malloc(initial_capacity * sizeof(record));
    arr->capacity = initial_capacity;
    arr->size = 0;
}

// Resize the dynamic array
void resize_dynamic_array(dynamic_array *arr, size_t new_capacity) {
    long *new_offsets = realloc(arr->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(arr->keys, new_capacity * sizeof(int));
    record *new_records = realloc(arr->records, new_capacity * sizeof(record));

    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    arr->offsets = new_offsets;
    arr->keys = new_keys;
    arr->records = new_records;
    arr->capacity = new_capacity;
}

// Add a record to the dynamic array
void add_record(dynamic_array *arr, int key, NR_PHY_LAYER_STATS stats) {
    if (arr->size >= arr->capacity) {
        resize_dynamic_array(arr, arr->capacity * 2);
    }

    size_t index = custom_hash(key);
    while (arr->keys[index] != -1 && arr->keys[index] != key) {
        index = (index + 1) % arr->capacity;
    }

    if (arr->keys[index] == -1) {
        arr->offsets[arr->size] = sizeof(record) * arr->size;
        arr->keys[index] = key;
        arr->records[arr->size].key = key;
        arr->records[arr->size].stats = stats;
        arr->size++;
    }
}

// Remove a record from the dynamic array
void remove_record(dynamic_array *arr, int key) {
    size_t index = custom_hash(key);
    while (arr->keys[index] != -1) {
        if (arr->keys[index] == key) {
            arr->keys[index] = -2; // Mark as deleted
            break;
        }
        index = (index + 1) % arr->capacity;
    }
}

// Update a record in the dynamic array
void update_record(dynamic_array *arr, int key, NR_PHY_LAYER_STATS stats) {
    size_t index = custom_hash(key);
    while (arr->keys[index] != -1) {
        if (arr->keys[index] == key) {
            arr->records[arr->size].stats = stats;
            break;
        }
        index = (index + 1) % arr->capacity;
    }
}

// Free the dynamic array
void free_dynamic_array(dynamic_array *arr) {
    free(arr->offsets);
    free(arr->keys);
    free(arr->records);
}
