#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Product {
    int id;
    char *name;
    float price;
    struct Product *next;
} Product;

typedef struct ProductList {
    Product *head;
    pthread_mutex_t lock;
} ProductList;

ProductList *create_product_list() {
    ProductList *list = (ProductList *)malloc(sizeof(ProductList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_product(ProductList *list, int id, const char *name, float price) {
    pthread_mutex_lock(&list->lock);
    Product *current = list->head;
    while (current != NULL) {
        if (current->id == id) {
            free(current->name);
            current->name = strdup(name);
            current->price = price;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }
    Product *new_product = (Product *)malloc(sizeof(Product));
    new_product->id = id;
    new_product->name = strdup(name);
    new_product->price = price;
    new_product->next = list->head;
    list->head = new_product;
    pthread_mutex_unlock(&list->lock);
}

void remove_product_by_id(ProductList *list, int id) {
    pthread_mutex_lock(&list->lock);
    Product *current = list->head;
    Product *prev = NULL;
    while (current != NULL) {
        if (current->id == id) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->name);
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_product_by_name(ProductList *list, const char *name) {
    pthread_mutex_lock(&list->lock);
    Product *current = list->head;
    Product *prev = NULL;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->name);
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

Product *search_product_by_id(ProductList *list, int id) {
    pthread_mutex_lock(&list->lock);
    Product *current = list->head;
    while (current != NULL) {
        if (current->id == id) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

Product *search_product_by_name(ProductList *list, const char *name) {
    pthread_mutex_lock(&list->lock);
    Product *current = list->head;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void serialize_to_json(ProductList *list, const char *filename) {
    // Custom JSON serialization logic here
}

void destroy_product_list(ProductList *list) {
    Product *current = list->head;
    while (current != NULL) {
        Product *next = current->next;
        free(current->name);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
