#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFPAPI_MESSAGE_T {
    int UE_ID;
    int SEQUENCE_NUMBER;
    int DATA_LENGTH;
    struct NFPAPI_MESSAGE_T *next;
} NFPAPI_MESSAGE_T;

typedef struct LinkedList {
    NFPAPI_MESSAGE_T *head;
    pthread_mutex_t lock;
} LinkedList;

int init_list(LinkedList *list) {
    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        return -1; // Mutex initialization failed
    }
    return 0;
}

int insert_node(LinkedList *list, int UE_ID, int SEQUENCE_NUMBER, int DATA_LENGTH) {
    pthread_mutex_lock(&list->lock);
    NFPAPI_MESSAGE_T *new_node = (NFPAPI_MESSAGE_T *)malloc(sizeof(NFPAPI_MESSAGE_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->UE_ID = UE_ID;
    new_node->SEQUENCE_NUMBER = SEQUENCE_NUMBER;
    new_node->DATA_LENGTH = DATA_LENGTH;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        NFPAPI_MESSAGE_T *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFPAPI_MESSAGE_T* retrieve_node(LinkedList *list, int SEQUENCE_NUMBER) {
    pthread_mutex_lock(&list->lock);
    NFPAPI_MESSAGE_T *current = list->head;
    while (current != NULL && current->SEQUENCE_NUMBER != SEQUENCE_NUMBER) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

int update_data_length(LinkedList *list, int SEQUENCE_NUMBER, int new_DATA_LENGTH) {
    pthread_mutex_lock(&list->lock);
    NFPAPI_MESSAGE_T *current = list->head;
    while (current != NULL && current->SEQUENCE_NUMBER != SEQUENCE_NUMBER) {
        current = current->next;
    }
    if (current != NULL) {
        current->DATA_LENGTH = new_DATA_LENGTH;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_node(LinkedList *list, int SEQUENCE_NUMBER) {
    pthread_mutex_lock(&list->lock);
    NFPAPI_MESSAGE_T *current = list->head;
    NFPAPI_MESSAGE_T *prev = NULL;

    while (current != NULL && current->SEQUENCE_NUMBER != SEQUENCE_NUMBER) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Node not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFPAPI_MESSAGE_T* find_node_by_data_length(LinkedList *list, int threshold) {
    pthread_mutex_lock(&list->lock);
    NFPAPI_MESSAGE_T *current = list->head;
    while (current != NULL && current->DATA_LENGTH <= threshold) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

void cleanup_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    NFPAPI_MESSAGE_T *current = list->head;
    while (current != NULL) {
        NFPAPI_MESSAGE_T *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    LinkedList list;
    init_list(&list);

    // Example usage
    insert_node(&list, 1, 100, 200);
    NFPAPI_MESSAGE_T *node = retrieve_node(&list, 100);
    if (node != NULL) {
        printf("Retrieved node: UE_ID=%d, SEQUENCE_NUMBER=%d, DATA_LENGTH=%d\n", node->UE_ID, node->SEQUENCE_NUMBER, node->DATA_LENGTH);
    }

    update_data_length(&list, 100, 300);

    remove_node(&list, 100);

    cleanup_list(&list);

