typedef struct {
    void *memory;
    size_t size;
    size_t used;
} memory_pool;

memory_pool pool = {NULL, 0, 0};

void* allocate_from_pool(size_t size) {
    if (pool.memory == NULL || pool.used + size > pool.size) {
        pool.size = MAX_POOL_SIZE * ((pool.size / MAX_POOL_SIZE) + 1);
        pool.memory = realloc(pool.memory, pool.size);
        if (pool.memory == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
    void *ptr = (char*)pool.memory + pool.used;
    pool.used += size;
    return ptr;
}

void initialize_data_points(double *weights, char **labels, int num_points, data_point **data_points) {
    *data_points = allocate_from_pool(num_points * sizeof(data_point));
    if (*data_points == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < num_points; i++) {
        (*data_points)[i].weight = &weights[i];
        (*data_points)[i].label = &labels[i];
        (*data_points)[i].index = hash((*data_points)[i].label[0]);
    }
}

uint32_t hash(const char *str) {
    uint32_t hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash;
}

data_point* create_data_points(double *weights, char **labels, int num_points) {
    if (num_points <= 0 || weights == NULL || labels == NULL) {
        fprintf(stderr, "Invalid input\n");
        return NULL;
    }

    data_point *data_points = NULL;
    initialize_data_points(weights, labels, num_points, &data_points);

    return data_points;
}

void free_data_points(data_point *data_points, int num_points) {
    for (int i = 0; i < num_points; i++) {
        // Free any additional resources if needed
    }
    free(data_points);
}

int main() {
    double weights[] = {1.2, 3.4, 5.6};
    char *labels[] = {"apple", "banana", "cherry"};
    int num_points = sizeof(weights) / sizeof(weights[0]);

    data_point *data_points = create_data_points(weights, labels, num_points);
    if (data_points != NULL) {
        // Use the data points
        free_data_points(data_points, num_points);
    }

    return 0;
}
