import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class RemoteConnectionManager {

    private final AsynchronousSocketChannel channel;
    private final ExecutorService executorService;
    private final ConfigurationService configService;
    private final MetricsSystem metricsSystem;
    private final PersistenceLayer persistenceLayer;

    public RemoteConnectionManager(ConfigurationService configService, MetricsSystem metricsSystem, PersistenceLayer persistenceLayer) throws IOException {
        this.configService = configService;
        this.metricsSystem = metricsSystem;
        this.persistenceLayer = persistenceLayer;
        this.executorService = Executors.newFixedThreadPool(configService.getThreadPoolSize());
        this.channel = AsynchronousSocketChannel.open(executorService);
    }

    public void connect(String host, int port) throws IOException {
        channel.connect(new InetSocketAddress(host, port), null, new CompletionHandler<Void, Void>() {
            @Override
            public void completed(Void result, Void attachment) {
                handleConnectionSuccess();
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                handleConnectionFailure(exc);
            }
        });
    }

    private void handleConnectionSuccess() {
        metricsSystem.incrementSuccessfulConnections();
        persistenceLayer.logConnectionAttempt(true);
        // Start listening for messages
        listenForMessages();
    }

    private void handleConnectionFailure(Throwable exc) {
        metricsSystem.incrementFailedConnections();
        persistenceLayer.logConnectionAttempt(false);
        // Retry logic with exponential backoff
        CompletableFuture.runAsync(() -> {
            try {
                TimeUnit.SECONDS.sleep(configService.getRetryDelay());
                connect(configService.getHost(), configService.getPort());
            } catch (IOException | InterruptedException e) {
                handleConnectionFailure(e);
            }
        }, executorService);
    }

    private void listenForMessages() {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        channel.read(buffer, buffer, null, new CompletionHandler<Integer, ByteBuffer>() {
            @Override
            public void completed(Integer result, ByteBuffer attachment) {
                handleReadCompletion(result, attachment);
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                handleReadFailure(exc, attachment);
            }
        });
    }

    private void handleReadCompletion(Integer bytesRead, ByteBuffer buffer) {
        if (bytesRead == -1) {
            // Connection closed by peer
            persistenceLayer.logConnectionClosed();
            return;
        }
        buffer.flip();
        byte[] data = new byte[buffer.remaining()];
        buffer.get(data);
        String message = new String(data);
        metricsSystem.incrementMessagesReceived();
        persistenceLayer.storeMessage(message);
        listenForMessages(); // Continue listening for more messages
    }

    private void handleReadFailure(Throwable exc, ByteBuffer attachment) {
        metricsSystem.incrementFailedReads();
        persistenceLayer.logError(exc.getMessage());
        // Retry logic with exponential backoff
        CompletableFuture.runAsync(() -> {
            try {
                TimeUnit.SECONDS.sleep(configService.getRetryDelay());
                listenForMessages();
            } catch (InterruptedException e) {
                handleReadFailure(e, attachment);
            }
        }, executorService);
    }

    public void sendStatusUpdate(String status) throws IOException {
        ByteBuffer buffer = ByteBuffer.wrap(status.getBytes());
        channel.write(buffer, null, new CompletionHandler<Integer, Void>() {
            @Override
            public void completed(Integer result, Void attachment) {
                metricsSystem.incrementMessagesSent();
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                metricsSystem.incrementFailedWrites();
                persistenceLayer.logError(exc.getMessage());
                // Retry logic with exponential backoff
                CompletableFuture.runAsync(() -> {
                    try {
                        TimeUnit.SECONDS.sleep(configService.getRetryDelay());
                        sendStatusUpdate(status);
                    } catch (IOException | InterruptedException e) {
                        handleReadFailure(e, null);
                    }
                }, executorService);
            }
        });
    }

    public void close() throws IOException {
        channel.close();
        executorService.shutdown();
    }
}
