#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    double value;
} Entry;

Entry** create_entry_array(size_t initial_size) {
    return (Entry**)malloc(initial_size * sizeof(Entry*));
}

void free_entry_array(Entry** array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] != NULL) {
            free(array[i]->key);
            free(array[i]);
        }
    }
    free(array);
}

int populate_entries_from_file(Entry** entries, size_t* size, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char* key = strtok(line, ":");
        char* value_str = strtok(NULL, ":");
        if (key != NULL && value_str != NULL) {
            double value;
            if (sscanf(value_str, "%lf", &value) == 1) {
                entries[*size] = (Entry*)malloc(sizeof(Entry));
                entries[*size]->key = strdup(key);
                entries[*size]->value = value;
                (*size)++;
            }
        }
    }

    fclose(file);
    return 0;
}

double* search_entry_by_key(Entry** entries, size_t size, const char* key) {
    for (size_t i = 0; i < size; ++i) {
        if (strcmp(entries[i]->key, key) == 0) {
            return &entries[i]->value;
        }
    }
    return NULL;
}

int main() {
    Entry** entries = create_entry_array(10);
    size_t size = 0;

    if (populate_entries_from_file(entries, &size, "data.txt") != 0) {
        printf("Failed to populate entries from file.\n");
        free_entry_array(entries, size);
        return 1;
    }

    double* value = search_entry_by_key(entries, size, "exampleKey");
    if (value != NULL) {
        printf("Value for 'exampleKey': %f\n", *value);
    } else {
        printf("Key not found.\n");
    }

    free_entry_array(entries, size);
    return 0;
}
