using System;
using System.Collections.Concurrent;
using System.Xml.XPath;

public class XmlParser
{
    private ConcurrentDictionary<string, Element> _elements = new ConcurrentDictionary<string, Element>();
    private Random _random = new Random();

    public void ParseXmlForElement(string xmlContent, string elementName)
    {
        XPathDocument doc = new XPathDocument(new System.IO.StringReader(xmlContent));
        XPathNavigator navigator = doc.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select($"//{elementName}");

        if (nodes.Count == 0)
            throw new InvalidOperationException("No element found with the specified name.");
        else if (nodes.Count > 1)
            throw new InvalidOperationException("Multiple elements found with the given name.");

        while (nodes.MoveNext())
        {
            XPathNavigator node = nodes.Current;
            string tag = node.GetAttribute("Tag", "");
            int rnti = GetUniqueRNTI();
            bool crcFlag = _random.Next(2) == 0;

            Element newElement = new Element { Tag = tag, RNTI = rnti, CRC_FLAG = crcFlag };
            if (!_elements.TryAdd(tag, newElement))
                throw new InvalidOperationException("Failed to add element due to a collision.");
        }
    }

    private int GetUniqueRNTI()
    {
        while (true)
        {
            int rnti = _random.Next(int.MaxValue);
            if (_elements.Values.All(e => e.RNTI != rnti))
                return rnti;
        }
    }

    public Element GetElementByIndex(int index)
    {
        if (!_elements.Values.Skip(index).Any())
            throw new IndexOutOfRangeException("Index out of range.");

        return _elements.Values.Skip(index).First();
    }

    public void FreeResources()
    {
        _elements.Clear();
    }
}

public class Element
{
    public string Tag { get; set; }
    public int RNTI { get; set; }
    public bool CRC_FLAG { get; set; }
}
