#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char* key;
    double value;
} Entry;

typedef struct {
    int timestamp;
    int packet_id;
    void* payload;
    size_t payload_size;
    Entry* entry;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager* pm, size_t initial_capacity) {
    pm->packets = (DataPacket**)malloc(initial_capacity * sizeof(DataPacket*));
    pm->capacity = initial_capacity;
    pm->size = 0;
    pthread_mutex_init(&pm->lock, NULL);
}

void add_packet(PacketManager* pm, DataPacket* packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->size == pm->capacity) {
        pm->capacity *= 2;
        pm->packets = (DataPacket**)realloc(pm->packets, pm->capacity * sizeof(DataPacket*));
    }
    pm->packets[pm->size++] = packet;
    pthread_mutex_unlock(&pm->lock);
}

void update_packet(PacketManager* pm, int packet_id, DataPacket* new_packet) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i]->packet_id == packet_id) {
            free(pm->packets[i]);
            pm->packets[i] = new_packet;
            break;
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

DataPacket* get_packet(PacketManager* pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i]->packet_id == packet_id) {
            DataPacket* result = pm->packets[i];
            pthread_mutex_unlock(&pm->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return NULL;
}

void free_packet_manager(PacketManager* pm) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->size; ++i) {
        free(pm->packets[i]);
    }
    free(pm->packets);
    pthread_mutex_unlock(&pm->lock);
    pthread_mutex_destroy(&pm->lock);
}
