#define MAX_RETRIES 3

typedef struct {
    int value;
    long* key_ptr;
} record;

int allocate_and_initialize(long** offsets, int** keys, record** records, size_t array_size, size_t num_records, int min_value, int max_value) {
    // Allocate memory for arrays
    *offsets = (long*)malloc(array_size * sizeof(long));
    *keys = (int*)malloc(array_size * sizeof(int));
    *records = (record*)malloc(num_records * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        return -1; // Memory allocation failed
    }

    // Initialize arrays
    srand(time(NULL));
    for (size_t i = 0; i < array_size; ++i) {
        (*offsets)[i] = rand() % array_size;
        (*keys)[i] = rand() % array_size;
    }

    // Populate records with random values and set key pointers
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;

        size_t key_index = (*records)[i].value % array_size;
        while ((*keys)[key_index] <= i) {
            key_index = (key_index + 1) % array_size;
        }
        (*records)[i].key_ptr = &(*keys)[key_index];
    }

    return 0; // Success
}

void free_memory(long* offsets, int* keys, record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int validate_records(record* records, size_t num_records, long* offsets, size_t array_size) {
    for (size_t i = 0; i < num_records; ++i) {
        if ((*records)[i].value < 0 || (*records)[i].value >= array_size) {
            return -1; // Invalid record value
        }
        if (!(*records)[i].key_ptr) {
            return -2; // Null key pointer
        }
        size_t expected_index = (*records)[i].value % array_size;
        while (expected_index != i && *((*records)[i].key_ptr) <= i) {
            expected_index = (*records)[i].key_ptr - keys;
        }
        if (expected_index != i) {
            return -3; // Incorrect key pointer
        }
    }
    return 0; // Validation successful
}

int main() {
    long* offsets;
    int* keys;
    record* records;

    size_t array_size = 1000;
    size_t num_records = 500;
    int min_value = 0;
    int max_value = 10000;

    if (allocate_and_initialize(&offsets, &keys, &records, array_size, num_records, min_value, max_value) == 0) {
        printf("Initialization successful.\n");

        // Perform validation
        if (validate_records(records, num_records, offsets, array_size) == 0) {
            printf("Validation successful.\n");
        } else {
            printf("Validation failed.\n");
        }

        free_memory(offsets, keys, records);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
