#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* key;
    double value;
} Entry;

typedef struct {
    Entry** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EntryArray;

EntryArray* create_entry_array(size_t initial_capacity) {
    EntryArray* array = (EntryArray*)malloc(sizeof(EntryArray));
    array->entries = (Entry**)calloc(initial_capacity, sizeof(Entry*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_entry_array(EntryArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->entries[i]->key);
        free(array->entries[i]);
    }
    free(array->entries);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void add_entry(EntryArray* array, const char* key, double value) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->entries = (Entry**)realloc(array->entries, array->capacity * sizeof(Entry*));
    }
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->value = value;
    array->entries[array->size++] = entry;
    pthread_mutex_unlock(&array->lock);
}

double get_entry_value(EntryArray* array, const char* key) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->entries[i]->key, key) == 0) {
            double value = array->entries[i]->value;
            pthread_mutex_unlock(&array->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1.0; // Key not found
}

