#define MAX_UE_STATES 1024
#define TIMEOUT_SECONDS 60

typedef struct {
    int ue_id;
    int signal_strength;
    int *uplink_grants;
    size_t grant_count;
    time_t last_activity;
} UeState;

UeState ue_states[MAX_UE_STATES];
int next_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_or_update_ue_state(int ue_id, int signal_strength, int *uplink_grants, size_t grant_count) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < next_index; ++i) {
        if (ue_states[i].ue_id == ue_id) {
            free(ue_states[i].uplink_grants);
            memcpy(&ue_states[i], &(UeState){ue_id, signal_strength, uplink_grants, grant_count, time(NULL)}, sizeof(UeState));
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    if (next_index < MAX_UE_STATES) {
        ue_states[next_index++] = (UeState){ue_id, signal_strength, uplink_grants, grant_count, time(NULL)};
    } else {
        printf("Maximum number of UE states reached.\n");
    }
    pthread_mutex_unlock(&mutex);
}

void evict_stale_entries() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < next_index; ++i) {
        if (time(NULL) - ue_states[i].last_activity > TIMEOUT_SECONDS) {
            free(ue_states[i].uplink_grants);
            memmove(&ue_states[i], &ue_states[i + 1], sizeof(UeState) * (next_index - i - 1));
            next_index--;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* aggregation_thread(void* arg) {
    while (1) {
        evict_stale_entries();
        // Perform statistical aggregation here
        sleep(5); // Simulate aggregation interval
    }
    return NULL;
}

int main() {
    pthread_t agg_thread;
    pthread_create(&agg_thread, NULL, aggregation_thread, NULL);

    int signal_strength = 10;
    int uplink_grants[] = {1, 2, 3};
    size_t grant_count = sizeof(uplink_grants) / sizeof(uplink_grants[0]);

    add_or_update_ue_state(1, signal_strength, uplink_grants, grant_count);

    pthread_join(agg_thread, NULL);
    return 0;
}
