int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

void generate_primes(int* primes, int min_prime, int max_prime) {
    int size = max_prime - min_prime + 1;
    char* sieve = (char*)calloc(size, sizeof(char));
    for (int i = 2; i * i < size; i++) {
        if (!sieve[i]) {
            for (int j = i * i; j < size; j += i) {
                sieve[j] = 1;
            }
        }
    }
    int count = 0;
    for (int i = min_prime; i <= max_prime; i++) {
        if (!sieve[i - min_prime]) {
            primes[count++] = i;
        }
    }
    free(sieve);
}

void initialize_records(record* records, int num_records, int min_prime, int max_prime) {
    generate_primes(records[0].data, min_prime, max_prime);
    for (int i = 1; i < num_records; i++) {
        records[i].data = (int*)malloc(sizeof(int));
        *records[i].data = records[i - 1].data + rand() % 10 + 1;
        records[i].timestamp = time(NULL);
