#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct TaskLog {
    int id;
    time_t timestamp;
    char status[20];
    char *description;
} TaskLog;

typedef struct TaskList {
    TaskLog **tasks;
    size_t count;
    size_t capacity;
} TaskList;

TaskList* create_task_list() {
    TaskList *list = (TaskList*)malloc(sizeof(TaskList));
    list->tasks = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

void add_task(TaskList *list, int id, time_t timestamp, const char *status, const char *description) {
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        TaskLog **new_tasks = (TaskLog**)realloc(list->tasks, new_capacity * sizeof(TaskLog*));
        if (!new_tasks) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }
    TaskLog *task = (TaskLog*)malloc(sizeof(TaskLog));
    task->id = id;
    task->timestamp = timestamp;
    strcpy(task->status, status);
    task->description = strdup(description);
    list->tasks[list->count++] = task;
}

void update_task(TaskList *list, int id, time_t new_timestamp, const char *new_status, const char *new_description) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->tasks[i]->id == id) {
            free(list->tasks[i]->description);
            list->tasks[i]->timestamp = new_timestamp;
            strcpy(list->tasks[i]->status, new_status);
            list->tasks[i]->description = strdup(new_description);
            return;
        }
    }
    fprintf(stderr, "Task with ID %d not found\n", id);
}

void filter_tasks(TaskList *list, const char *status, time_t start_time, time_t end_time) {
    for (size_t i = 0; i < list->count; ++i) {
        if ((strcmp(list->tasks[i]->status, status) == 0) &&
            (list->tasks[i]->timestamp >= start_time && list->tasks[i]->timestamp <= end_time)) {
            printf("Task ID: %d, Timestamp: %s, Status: %s, Description: %s\n",
                   list->tasks[i]->id, ctime(&list->tasks[i]->timestamp), list->tasks[i]->status, list->tasks[i]->description);
        }
    }
}

void free_task_list(TaskList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->tasks[i]->description);
        free(list->tasks[i]);
    }
    free(list->tasks);
    free(list);
}
