typedef struct {
    int value;
} record;

int initialize_cipher(const char *password, size_t password_len, size_t num_records, int min_value, int max_value, unsigned char **key, unsigned char **iv, EVP_CIPHER_CTX **ctx) {
    if (num_records == 0 || min_value > max_value) {
        return -1; // Invalid input
    }

    *key = OPENSSL_malloc(32);
    *iv = OPENSSL_malloc(16);
    *ctx = EVP_CIPHER_CTX_new();

    if (!*key || !*iv || !*ctx) {
        goto error;
    }

    unsigned char salt[8];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        goto error;
    }

    unsigned char derived_key[32];
    if (PKCS5_PBKDF2_HMAC(password, password_len, salt, sizeof(salt), 10000, EVP_sha256(), 32, derived_key) != 1) {
        goto error;
    }

    memcpy(*key, derived_key, 32);
    memset(derived_key, 0, 32);

    if (RAND_bytes(*iv, 16) != 1) {
        goto error;
    }

    EVP_CIPHER_CTX_init(*ctx);
    if (EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, *key, *iv) != 1) {
        goto error;
    }

    unsigned char **offsets = OPENSSL_malloc(num_records * sizeof(unsigned char *));
    int *keys = OPENSSL_malloc(num_records * sizeof(int));
    record *records = OPENSSL_malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        goto error;
    }

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = OPENSSL_malloc(sizeof(long));
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = keys[i];
    }

    // Use the allocated arrays and context for further operations

    return 0;

error:
    if (*key) {
        OPENSSL_free(*key);
    }
    if (*iv) {
        OPENSSL_free(*iv);
    }
    if (*ctx) {
        EVP_CIPHER_CTX_free(*ctx);
    }
    if (offsets) {
        for (size_t i = 0; i < num_records; ++i) {
            if (offsets[i]) {
                OPENSSL_free(offsets[i]);
            }
        }
        OPENSSL_free(offsets);
    }
    if (keys) {
        OPENSSL_free(keys);
    }
    if (records) {
        OPENSSL_free(records);
    }

    return -1;
}

void disable_cipher(unsigned char *key, unsigned char *iv, EVP_CIPHER_CTX *ctx, unsigned char **offsets, int *keys, record *records, size_t num_records) {
    if (key) {
        OPENSSL_cleanse(key, 32);
        OPENSSL_free(key);
    }
    if (iv) {
        OPENSSL_cleanse(iv, 16);
        OPENSSL_free(iv);
    }
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
    for (size_t i = 0; i < num_records; ++i) {
        if (offsets[i]) {
            OPENSSL_free(offsets[i]);
        }
    }
    if (keys) {
        OPENSSL_free(keys);
    }
    if (records) {
        OPENSSL_free(records);
    }
}
