#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    char* key;
    double value;
    time_t timestamp;
} Entry;

typedef struct {
    Entry** buckets;
    size_t capacity;
    size_t size;
} HashTable;

unsigned int hash(const char* key, size_t capacity) {
    unsigned int hash = 0;
    while (*key) {
        hash = (hash * 31) + *key++;
    }
    return hash % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(initial_capacity, sizeof(Entry*));
    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

void insert_entry(HashTable* table, const char* key, double value) {
    if ((double)table->size / table->capacity >= LOAD_FACTOR) {
        // Resize the hash table
        size_t new_capacity = table->capacity * 2;
        Entry** old_buckets = table->buckets;
        table->buckets = calloc(new_capacity, sizeof(Entry*));
        table->capacity = new_capacity;
        for (size_t i = 0; i < old_capacity; ++i) {
            if (old_buckets[i]) {
                size_t index = hash(old_buckets[i]->key, new_capacity);
                while (table->buckets[index]) {
                    index = (index + 1) % new_capacity;
                }
                table->buckets[index] = old_buckets[i];
                old_buckets[i]->timestamp = time(NULL); // Update timestamp
            }
        }
        free(old_buckets);
    }

    size_t index = hash(key, table->capacity);
    while (table->buckets[index]) {
        if (strcmp(table->buckets[index]->key, key) == 0) {
            table->buckets[index]->value = value;
            table->buckets[index]->timestamp = time(NULL); // Update timestamp
            return;
        }
        index = (index + 1) % table->capacity;
    }

    Entry* new_entry = malloc(sizeof(Entry));
    new_entry->key = strdup(key);
    new_entry->value = value;
    new_entry->timestamp = time(NULL); // Set initial timestamp
    table->buckets[index] = new_entry;
    ++table->size;
}

void delete_entry(HashTable* table, const char* key) {
    size_t index = hash(key, table->capacity);
    while (table->buckets[index]) {
        if (strcmp(table->buckets[index]->key, key) == 0) {
            free(table->buckets[index]->key);
            free(table->buckets[index]);
            table->buckets[index] = NULL;
            --table->size;
            return;
        }
        index = (index + 1) % table->capacity;
    }
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->buckets[i]) {
            free(table->buckets[i]->key);
            free(table->buckets[i]);
        }
    }
    free(table->buckets);
    free(table);
}

int main() {
    HashTable* table = create_hash_table(INITIAL_CAPACITY);

    insert_entry(table, "key1", 3.14);
    insert_entry(table, "key2", 2.718);
    delete_entry(table, "key1");

    destroy_hash_table(table);

    return 0;
}
