#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 1024

typedef struct {
    int NODE_ID;
    char CURRENT_STATUS[50];
    // Define PERIODIC_STATS structure here
} NODE_INFO_T;

typedef struct node {
    NODE_INFO_T data;
    struct node *next;
} NODE_T;

typedef struct {
    NODE_T *buckets[MAX_NODES];
    pthread_mutex_t lock;
} HASH_TABLE_T;

HASH_TABLE_T hash_table;

void init_hash_table() {
    for (int i = 0; i < MAX_NODES; i++) {
        hash_table.buckets[i] = NULL;
    }
    pthread_mutex_init(&hash_table.lock, NULL);
}

unsigned int hash_function(int node_id) {
    return abs(node_id % MAX_NODES);
}

void insert_node(NODE_INFO_T *node_info) {
    pthread_mutex_lock(&hash_table.lock);
    unsigned int index = hash_function(node_info->NODE_ID);
    NODE_T *new_node = (NODE_T *)malloc(sizeof(NODE_T));
    new_node->data = *node_info;
    new_node->next = hash_table.buckets[index];
    hash_table.buckets[index] = new_node;
    pthread_mutex_unlock(&hash_table.lock);
}

void update_node(int node_id, NODE_INFO_T *new_data) {
    pthread_mutex_lock(&hash_table.lock);
    unsigned int index = hash_function(node_id);
    NODE_T *current = hash_table.buckets[index];
    while (current != NULL) {
        if (current->data.NODE_ID == node_id) {
            current->data = *new_data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&hash_table.lock);
}

NODE_INFO_T* retrieve_node(int node_id) {
    pthread_mutex_lock(&hash_table.lock);
    unsigned int index = hash_function(node_id);
    NODE_T *current = hash_table.buckets[index];
    while (current != NULL) {
        if (current->data.NODE_ID == node_id) {
            NODE_INFO_T *result = malloc(sizeof(NODE_INFO_T));
            *result = current->data;
            pthread_mutex_unlock(&hash_table.lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&hash_table.lock);
    return NULL;
}

void free_hash_table() {
    for (int i = 0; i < MAX_NODES; i++) {
        NODE_T *current = hash_table.buckets[i];
        while (current != NULL) {
            NODE_T *temp = current;
            current = current->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&hash_table.lock);
}
