#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdlib.h>
#include <string.h>

#define KEY_LENGTH 32
#define IV_LENGTH 16
#define MIN_BLOCK_SIZE 16
#define MAX_BLOCK_SIZE 4096

typedef struct {
    int value;
} record;

int initialize_cipher(const char *password, unsigned char **key, unsigned char **iv) {
    // Derive key using PBKDF2
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, 10000, EVP_sha256(), KEY_LENGTH, *key)) {
        return -1; // Error during key derivation
    }

    // Generate random IV
    if (!RAND_bytes(*iv, IV_LENGTH)) {
        return -2; // Error generating IV
    }

    return 0; // Success
}

void allocate_memory(long num_records, int **offsets, record **records) {
    *offsets = (long *)malloc(num_records * sizeof(long));
    *records = (record *)malloc(num_records * sizeof(record));

    if (!*offsets || !*records) {
        free(*offsets);
        free(*records);
        exit(EXIT_FAILURE); // Memory allocation failed
    }
}

void initialize_records(int num_records, record *records, int min_value, int max_value) {
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

int encrypt_data(EVP_CIPHER_CTX *ctx, const unsigned char *key, const unsigned char *iv, record *records, int num_records, unsigned char **encrypted_data, size_t *encrypted_len) {
    // Calculate optimal block size
    int block_size = MIN_BLOCK_SIZE + (num_records % 16); // Example heuristic

    if (block_size > MAX_BLOCK_SIZE) {
        block_size = MAX_BLOCK_SIZE;
    }

    *encrypted_data = (unsigned char *)malloc(block_size);
    *encrypted_len = block_size;

    if (!*encrypted_data) {
        return -3; // Memory allocation failed
    }

    int len, ciphertext_len;
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    for (int i = 0; i < num_records; ++i) {
        if (!EVP_EncryptUpdate(ctx, *encrypted_data + len, &ciphertext_len, (unsigned char *)&records[i], sizeof(record))) {
            free(*encrypted_data);
            return -4; // Encryption failed
        }
        len += ciphertext_len;
    }

    if (!EVP_EncryptFinal_ex(ctx, *encrypted_data + len, &ciphertext_len)) {
        free(*encrypted_data);
        return -5; // Finalization failed
    }
    len += ciphertext_len;

    *encrypted_len = len;
    return 0; // Success
}

void cleanup(EVP_CIPHER_CTX *ctx, unsigned char *key, unsigned char *iv, unsigned char *encrypted_data) {
    EVP_CIPHER_CTX_free(ctx);
    free(key);
    free(iv);
    free(encrypted_data);
}
