        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize records with random values within specified range
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Perform encryption using AES-256-CBC cipher
    int len, ciphertext_len;
    unsigned char *ciphertext = malloc(EVP_CIPHER_block_size(ctx) * numRecords);
    if (!ciphertext) {
        // Handle memory allocation error
        json_object_put(report);
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(records);
        free(ciphertext);
        return;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        // Handle error
        json_object_put(report);
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(records);
        free(ciphertext);
        return;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char *)records, numRecords * sizeof(Record))) {
        // Handle error
        json_object_put(report);
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(records);
        free(ciphertext);
        return;
    }

    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        // Handle error
        json_object_put(report);
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(records);
        free(ciphertext);
        return;
    }

    ciphertext_len += len;

    // Add encrypted data to JSON report
    json_object_object_add(report, "encrypted_data", json_object_new_string((char *)ciphertext));

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
    free(offsets);
    free(keys);
    free(records);
    free(ciphertext);

    // Output the JSON report
    printf("%s\n", json_object_to_json_string(report));
    json_object_put(report);
}
