#include <string.h>
#include <pthread.h>

#define MAX_TASK_DESCRIPTION 256

typedef struct TaskLog {
    int id;
    time_t timestamp;
    char status[10];
    char description[MAX_TASK_DESCRIPTION];
} TaskLog;

typedef struct TaskList {
    TaskLog *tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TaskList;

void initTaskList(TaskList *list) {
    list->tasks = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void freeTaskList(TaskList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->tasks[i].description);
    }
    free(list->tasks);
    pthread_mutex_destroy(&list->lock);
}

int addTask(TaskList *list, int id, time_t timestamp, const char *status, const char *description) {
    pthread_mutex_lock(&list->lock);
    if (id < 0 || strlen(description) >= MAX_TASK_DESCRIPTION) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid input
    }
    for (size_t i = 0; i < list->count; ++i) {
        if (list->tasks[i].id == id) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate task ID
        }
    }
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        TaskLog *new_tasks = realloc(list->tasks, new_capacity * sizeof(TaskLog));
        if (!new_tasks) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Memory allocation failed
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }
    TaskLog *task = &list->tasks[list->count++];
    task->id = id;
    task->timestamp = timestamp;
    strcpy(task->status, status);
    task->description = strdup(description);
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Implement other functions for updating tasks, filtering, batch operations, etc.
```

