    double value;
} record;

int execute_process(char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        execlp(command, command, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else {
        int status;
        wait(&status);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            return 1;
        }
    }
    return 0;
}

record* allocate_records(int num_records, size_t* total_size) {
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("malloc");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].str = malloc(100 * sizeof(char)); // Example size
        if (!records[i].str) {
            perror("malloc");
            free(records);
            return NULL;
        }
        snprintf(records[i].str, 100, "Record %d", i);
        records[i].key = i;
        records[i].value = i * 1.1;
    }

    *total_size = num_records * sizeof(record) + num_records * 100 * sizeof(char);
    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].str);
    }
    free(records);
}

