#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEYS 1000
#define HASH_SIZE 1024

typedef struct record {
    int key;
    long offset;
} record;

typedef struct hash_entry {
    int key;
    int value;
    struct hash_entry *next;
} hash_entry;

int custom_hash(int key) {
    return abs(key % HASH_SIZE);
}

void add_to_record(record **records, int size, int key, long offset) {
    if (size >= MAX_KEYS) {
        fprintf(stderr, "Error: Maximum number of keys reached.\n");
        exit(EXIT_FAILURE);
    }
    records[size] = (record *)malloc(sizeof(record));
    records[size]->key = key;
    records[size]->offset = offset;
}

void add_to_hash(hash_entry **hash_table, int *size, int key, int value) {
    int index = custom_hash(key);
    hash_entry *new_entry = (hash_entry *)malloc(sizeof(hash_entry));
    new_entry->key = key;
    new_entry->value = value;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;
    (*size)++;
}

int find_largest_key(record **records, int size) {
    if (size == 0) {
        fprintf(stderr, "Warning: No keys found in the input.\n");
        return -1;
    }
    int largest_key = records[0]->key;
    for (int i = 1; i < size; i++) {
        if (records[i]->key > largest_key) {
            largest_key = records[i]->key;
        }
    }
    return largest_key;
}

void free_memory(record **records, hash_entry **hash_table, int record_size, int hash_size) {
    for (int i = 0; i < record_size; i++) {
        free(records[i]);
    }
    for (int i = 0; i < hash_size; i++) {
        hash_entry *entry = hash_table[i];
        while (entry != NULL) {
            hash_entry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(records);
    free(hash_table);
}

int main() {
    FILE *file = fopen("input.txt", "r");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file.\n");
        return EXIT_FAILURE;
    }

    record **records = (record **)malloc(MAX_KEYS * sizeof(record *));
    hash_entry **hash_table = (hash_entry **)calloc(HASH_SIZE, sizeof(hash_entry *));
    int record_size = 0, hash_size = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, " ");
        if (!token) continue;
        int key = atoi(token);
        long offset = ftell(file);

        add_to_record(records, record_size, key, offset);
        add_to_hash(hash_table, &hash_size, key, custom_hash(key));

        record_size++;
    }

    fclose(file);

    int largest_key = find_largest_key(records, record_size);
    printf("Largest Key: %d\n", largest_key);

    free_memory(records, hash_table, record_size, HASH_SIZE);

    return EXIT_SUCCESS;
}
