using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;

public class SqlExecutor
{
    public (IDataReader reader, ExecutionSummary summary) ExecuteQuery(
        string connectionString,
        string baseCommandText,
        List<object> parameters,
        int retryLimit = 3,
        TimeSpan? timeout = null)
    {
        var stopwatch = new Stopwatch();
        var summary = new ExecutionSummary();

        for (int attempt = 0; attempt <= retryLimit; attempt++)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    stopwatch.Start();

                    using (var command = new SqlCommand(baseCommandText, connection))
                    {
                        foreach (var param in parameters)
                        {
                            command.Parameters.AddWithValue(param);
                        }

                        if (timeout.HasValue)
                        {
                            command.CommandTimeout = (int)timeout.Value.TotalSeconds;
                        }

                        var reader = command.ExecuteReader();
                        summary.RowsAffected = command.ExecuteNonQuery();

                        stopwatch.Stop();
                        summary.ExecutionTime = stopwatch.Elapsed;

                        return (reader, summary);
                    }
                }
            }
            catch (SqlException ex)
            {
                if (attempt == retryLimit)
                {
                    summary.Errors.Add(ex.Message);
                    break;
                }

                // Log the exception and retry
                Console.WriteLine($"Attempt {attempt + 1} failed: {ex.Message}");
                System.Threading.Thread.Sleep(500); // Simple backoff strategy
            }
        }

        return (null, summary);
    }
}

public class ExecutionSummary
{
    public int RowsAffected { get; set; }
    public TimeSpan ExecutionTime { get; set; }
    public List<string> Warnings { get; } = new List<string>();
    public List<string> Errors { get; } = new List<string>();
}
```

