void manage_memory(long* offsets, int* keys, record** records, int offset_size, int key_size) {
    if (offset_size > MAX_OFFSET_SIZE || key_size > MAX_KEY_SIZE) {
        fprintf(stderr, "Error: Array sizes exceed maximum limits.\n");
        return;
    }

    offsets = realloc(offsets, offset_size * sizeof(long));
    keys = realloc(keys, key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    records = realloc(records, key_size * sizeof(record*));
    for (int i = 0; i < key_size; i++) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d.\n", i);
            return;
        }
        records[i]->value = hash_function(keys[i]);
    }

    // Simulate memory usage monitoring
    static size_t total_memory_usage = 0;
    static time_t last_check_time = 0;

    if (time(NULL) - last_check_time >= 5) {
        last_check_time = time(NULL);
        total_memory_usage += offset_size * sizeof(long) + key_size * sizeof(int) + key_size * sizeof(record*);
        for (int i = 0; i < key_size; i++) {
            total_memory_usage += sizeof(record);
        }
        if (total_memory_usage > 1000000) { // Example threshold
            fprintf(stderr, "Warning: Memory usage exceeds threshold.\n");
        }
    }

    // Free allocated memory
    for (int i = 0; i < key_size; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

