#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int packetID;
    size_t payloadLength;
    int priorityLevel;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
} PacketList;

void initPacketList(PacketList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

void addPacket(PacketList* list, DataPacket packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = packet;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->count++;
}

void updatePacket(PacketList* list, int packetID, DataPacket newPacket) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.packetID == packetID) {
            current->data = newPacket;
            return;
        }
        current = current->next;
    }
}

DataPacket* getPacketInRange(PacketList* list, time_t startTimestamp, time_t endTimestamp, int minPriority, int maxPriority) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.timestamp >= startTimestamp && current->data.timestamp <= endTimestamp &&
            current->data.priorityLevel >= minPriority && current->data.priorityLevel <= maxPriority) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

void compactPacketList(PacketList* list, size_t threshold) {
    if (list->count < threshold) return;

    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.timestamp < time(NULL) - 3600) { // Example retention period of 1 hour
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void destroyPacketList(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
