#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 500
#define RECORD_THRESHOLD 1024 * 1024 * 1024 // 1GB

typedef struct {
    int value;
} record;

void log_message(const char* message, const char* level) {
    printf("[%s] %s\n", level, message);
}

int custom_hash(int key) {
    return abs(key) % RECORD_THRESHOLD;
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        log_message("Memory allocation failed", "ERROR");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

record* create_records(int* keys, int key_count) {
    record* records = allocate_memory(key_count * sizeof(record));
    for (int i = 0; i < key_count; i++) {
        records[i].value = custom_hash(keys[i]);
    }
    return records;
}

void free_records(record* records, int key_count) {
    free_memory(records);
}

void* memory_allocation_thread(void* arg) {
    int* offsets = (int*)arg;
    int offset_count = sizeof(offsets) / sizeof(int);

    if (offset_count > MAX_OFFSET_SIZE) {
        log_message("Offset array size exceeds maximum limit", "ERROR");
        return NULL;
    }

    record* records = create_records(offsets, offset_count);
    free_records(records, offset_count);

    return NULL;
}

int main() {
    int offsets[MAX_OFFSET_SIZE];
    // Populate offsets array with valid values

    pthread_t thread;
    if (pthread_create(&thread, NULL, memory_allocation_thread, offsets) != 0) {
        log_message("Failed to create thread", "ERROR");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        log_message("Thread join failed", "ERROR");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
