typedef struct {
    SSL_CTX *ctx;
    char *cert_dir;
} SecureConnectionConfig;

SecureConnectionConfig* init_secure_connection(const char *config_file, int enable_encryption) {
    SecureConnectionConfig *config = (SecureConnectionConfig*)malloc(sizeof(SecureConnectionConfig));
    if (!config) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    config->ctx = SSL_CTX_new(TLS_method());
    if (!config->ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        free(config);
        return NULL;
    }

    if (enable_encryption) {
        // Load CA certificates
        if (SSL_CTX_load_verify_locations(config->ctx, NULL, config->cert_dir) != 1) {
            fprintf(stderr, "Failed to load CA certificates\n");
            SSL_CTX_free(config->ctx);
            free(config);
            return NULL;
        }

        // Set up certificate verification options
        SSL_CTX_set_verify(config->ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

        // Load server certificates and keys
        if (SSL_CTX_use_certificate_chain_file(config->ctx, "server_cert.pem") != 1 ||
            SSL_CTX_use_PrivateKey_file(config->ctx, "server_key.pem", SSL_FILETYPE_PEM) != 1) {
            fprintf(stderr, "Failed to load server certificate or key\n");
            SSL_CTX_free(config->ctx);
            free(config);
            return NULL;
        }
    }

    // Configure session reuse
    SSL_CTX_set_session_cache_mode(config->ctx, SSL_SESS_CACHE_SERVER);

    return config;
}

void cleanup_secure_connection(SecureConnectionConfig *config) {
    if (config) {
        SSL_CTX_free(config->ctx);
        free(config);
    }
}
