#include <iostream>
#include <queue>
#include <unordered_map>
#include <chrono>
#include <thread>

enum class MessagePriority { HIGH, NORMAL, LOW };

struct Message {
    std::string content;
    MessagePriority priority;
    std::chrono::time_point<std::chrono::system_clock> timestamp;

    Message(std::string msg, MessagePriority prio) : content(msg), priority(prio), timestamp(std::chrono::system_clock::now()) {}
};

class MessageBroker {
private:
    std::unordered_map<MessagePriority, std::queue<Message>> messageQueues;
    std::mutex queueMutex;
    std::condition_variable cv;

public:
    void sendMessage(const Message& msg) {
        std::lock_guard<std::mutex> lock(queueMutex);
        messageQueues[msg.priority].push(msg);
        cv.notify_one();
    }

    Message receiveMessage(MessagePriority prio) {
        std::unique_lock<std::mutex> lock(queueMutex);
        cv.wait(lock, [this, prio] { return !messageQueues[prio].empty(); });
        Message msg = messageQueues[prio].front();
        messageQueues[prio].pop();
        return msg;
    }

    void startWorkerThread(MessagePriority prio) {
        std::thread([this, prio]() {
            while (true) {
                Message msg = receiveMessage(prio);
                // Process the message
                std::cout << "Processing message: " << msg.content << " with priority: " << static_cast<int>(msg.priority) << std::endl;
            }
        }).detach();
    }

    void startAllWorkerThreads() {
        for (int i = 0; i < 3; ++i) { // Assuming 3 worker threads per priority level
            startWorkerThread(MessagePriority::HIGH);
            startWorkerThread(MessagePriority::NORMAL);
            startWorkerThread(MessagePriority::LOW);
        }
    }
};

class TrieNode {
public:
    std::unordered_map<char, TrieNode*> children;
    bool isEndOfWord;

    TrieNode() : isEndOfWord(false) {}
};

class Trie {
private:
    TrieNode* root;

public:
    Trie() : root(new TrieNode()) {}

    void insert(const std::string& word) {
        TrieNode* node = root;
        for (char c : word) {
            if (!node->children.count(c)) {
                node->children[c] = new TrieNode();
            }
            node = node->children[c];
        }
        node->isEndOfWord = true;
    }

    bool search(const std::string& prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            if (!node->children.count(c)) {
                return false;
            }
            node = node->children[c];
        }
        return true;
    }
};

int main() {
    MessageBroker broker;
    broker.startAllWorkerThreads();

    // Example usage of Trie
    Trie trie;
    trie.insert("hello");
    trie.insert("world");

    std::cout << "Search 'hel': " << (trie.search("hel") ? "Found" : "Not Found") << std::endl;
    std::cout << "Search 'wor': " << (trie.search("wor") ? "Found" : "Not Found") << std::endl;

    return 0;
}
