NFAPI_CRC_QUEUE_T* create_queue(size_t initial_capacity) {
    NFAPI_CRC_QUEUE_T *queue = (NFAPI_CRC_QUEUE_T*)malloc(sizeof(NFAPI_CRC_QUEUE_T));
    if (!queue) return NULL;

    queue->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->array) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);

    return queue;
}

void destroy_queue(NFAPI_CRC_QUEUE_T *queue) {
    pthread_mutex_lock(&queue->mutex);
    free(queue->array);
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

int add_element(NFAPI_CRC_QUEUE_T *queue, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity ? queue->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(queue->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&queue->mutex);
            return -1; // Memory allocation failed
        }
        queue->array = new_array;
        queue->capacity = new_capacity;
    }

    for (size_t i = 0; i < queue->size; ++i) {
        if (queue->array[i].RNTI == element.RNTI) {
            queue->array[i] = element;
            pthread_mutex_unlock(&queue->mutex);
            return 0; // Updated existing element
        }
    }

    queue->array[queue->size++] = element;
    pthread_mutex_unlock(&queue->mutex);
    return 1; // Added new element
}

int update_element(NFAPI_CRC_QUEUE_T *queue, int RNTI, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&queue->mutex);

    for (size_t i = 0; i < queue->size; ++i) {
        if (queue->array[i].RNTI == RNTI) {
            queue->array[i] = new_element;
            pthread_mutex_unlock(&queue->mutex);
            return 0; // Updated existing element
        }
    }

    pthread_mutex_unlock(&queue->mutex);
    return -1; // Element not found
}

int remove_element(NFAPI_CRC_QUEUE_T *queue, int RNTI) {
    pthread_mutex_lock(&queue->mutex);

    for (size_t i = 0; i < queue->size; ++i) {
        if (queue->array[i].RNTI == RNTI) {
            for (size_t j = i + 1; j < queue->size; ++j) {
                queue->array[j - 1] = queue->array[j];
            }
            --queue->size;
            pthread_mutex_unlock(&queue->mutex);
            return 0; // Removed element
        }
    }

    pthread_mutex_unlock(&queue->mutex);
    return -1; // Element not found
}
