    if (!array) return NULL;

    array->offsets = (long*)malloc(initial_capacity * sizeof(long));
    array->keys = (int*)malloc(initial_capacity * sizeof(int));
    if (!array->offsets || !array->keys) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

