int populateNFAPIArray(NFAPI_CRC_INDICATION_PDU_T **array, int N) {
    if (N <= 0) return -1; // Invalid input

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) return -2; // Memory allocation failed

    srand(time(NULL)); // Seed for random number generation
    int *rntiSet = (int *)calloc(N, sizeof(int));
    if (rntiSet == NULL) {
        free(*array);
        return -3; // Memory allocation failed
    }

    int uniqueRNTIs = 0;
    while (uniqueRNTIs < N) {
        int rnti = rand() % 10000 + 1; // Generate a random RNTI between 1 and 10000
        if (!rntiSet[rnti]) {
            (*array)[uniqueRNTIs].RX_UE_INFORMATION_TAG = uniqueRNTIs;
            (*array)[uniqueRNTIs].RNTI = rnti;
            (*array)[uniqueRNTIs].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
            (*array)[uniqueRNTIs].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            rntiSet[rnti] = 1;
            uniqueRNTIs++;
        }
    }

    free(rntiSet);
    return N; // Success, return the number of elements populated
}
