    strncpy(stream->resolution, res, sizeof(stream->resolution));
}

void encryptMediaStream(MediaStream *stream, unsigned char *key, int keySize) {
    AES_KEY enc_key;
    AES_set_encrypt_key(key, keySize * 8, &enc_key);
