}

void decryptMediaStream(MediaStream *stream, unsigned char *key, int keySize) {
    AES_KEY dec_key;
    AES_set_decrypt_key(key, keySize * 8, &dec_key);
    AES_cbc_encrypt(stream->payload, stream->payload, stream->payloadSize, &dec_key, (unsigned char *)"0123456789abcdef", AES_DECRYPT);
}

void generateCRC(MediaStream *stream) {
    unsigned int crc = 0;
    for (size_t i = 0; i < stream->payloadSize; i++) {
        crc ^= (unsigned int)stream->payload[i];
    }
    // Store CRC in a specific field or handle it as needed
}

