typedef struct {
    KeyRecord *records;
    size_t capacity;
    size_t size;
    size_t max_size;
    FILE *log_file;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity, size_t max_size, const char *log_filename) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for DynamicArray\n");
        return NULL;
    }

    array->records = (KeyRecord*)calloc(initial_capacity, sizeof(KeyRecord));
    if (!array->records) {
        free(array);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    array->max_size = max_size;

    array->log_file = fopen(log_filename, "w");
    if (!array->log_file) {
        free(array->records);
        free(array);
        fprintf(stderr, "Failed to open log file\n");
        return NULL;
    }

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array->records) {
        free(array->records);
    }
    if (array->log_file) {
        fclose(array->log_file);
    }
    free(array);
}

int add_record(DynamicArray *array, long offset, int key, int value, time_t timestamp, char status) {
    if (!array || !array->records) {
        fprintf(stderr, "Invalid DynamicArray pointer\n");
        return -1;
    }

    if (array->size >= array->max_size) {
        fprintf(array->log_file, "Error: Maximum size limit exceeded\n");
        return -1;
    }

    if (array->size == array->capacity) {
        KeyRecord *new_records = (KeyRecord*)realloc(array->records, array->capacity * 2 * sizeof(KeyRecord));
        if (!new_records) {
            fprintf(stderr, "Failed to reallocate memory for records\n");
            return -1;
        }
        array->records = new_records;
        array->capacity *= 2;
    }

    array->records[array->size].offset = offset;
    array->records[array->size].key = key;
    array->records[array->size].record.value = value;
    array->records[array->size].record.timestamp = timestamp;
    array->records[array->size].record.status = status;

    fprintf(array->log_file, "Added record at index %zu\n", array->size);
    array->size++;

    return 0;
}

// Additional functions for resizing, error handling, and logging can be added here
