#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} DynamicLinkedList;

DynamicLinkedList* createList() {
    DynamicLinkedList *list = (DynamicLinkedList*)malloc(sizeof(DynamicLinkedList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freeList(DynamicLinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insertPDU(DynamicLinkedList *list, int RNTI, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    newNode->RNTI = RNTI;
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int deletePDU(DynamicLinkedList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    while (current) {
        if (current->RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

void traverseList(DynamicLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        printf("RNTI: %d, RX_UE_INFORMATION_TAG: %d, CRC_INDICATION_REL8_TAG: %d\n",
               current->RNTI, current->RX_UE_INFORMATION_TAG, current->CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicLinkedList *list = createList();
    if (!list) return 1;

    insertPDU(list, 100, 200, 300);
    insertPDU(list, 400, 500, 600);

    traverseList(list);

    deletePDU(list, 100);

    traverseList(list);

    freeList(list);
    return 0;
}
