#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NAME_LENGTH 100
#define MIN_AGE 0
#define MAX_AGE 120
#define ERROR_LOG_LIMIT 500
#define MEMORY_THRESHOLD 80
#define CHECK_INTERVAL 10

typedef struct {
    char name[MAX_NAME_LENGTH];
    int age;
    int status;
} Object;

typedef struct Node {
    Object data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t allocated_size;
    pthread_mutex_t lock;
    FILE* error_log_file;
    int error_count;
} Collection;

Collection* create_collection() {
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) return NULL;
    collection->head = NULL;
    collection->count = 0;
    collection->allocated_size = 10;
    pthread_mutex_init(&collection->lock, NULL);
    collection->error_log_file = fopen("error.log", "w");
    collection->error_count = 0;
    return collection;
}

void destroy_collection(Collection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
    fclose(collection->error_log_file);
    free(collection);
}

int add_object(Collection* collection, const char* name, int age, int status) {
    if (strlen(name) > MAX_NAME_LENGTH || age < MIN_AGE || age > MAX_AGE) {
        if (collection->error_count < ERROR_LOG_LIMIT) {
            fprintf(collection->error_log_file, "Invalid object: %s, %d, %d\n", name, age, status);
            collection->error_count++;
        }
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        if (collection->error_count < ERROR_LOG_LIMIT) {
            fprintf(collection->error_log_file, "Memory allocation failed\n");
            collection->error_count++;
        }
        return -1;
    }

    strcpy(new_node->data.name, name);
    new_node->data.age = age;
    new_node->data.status = status;
    new_node->next = NULL;

    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->allocated_size) {
        size_t new_size = collection->allocated_size * 2;
        Node** new_array = (Node**)realloc(collection->head, new_size * sizeof(Node*));
        if (!new_array) {
            free(new_node);
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->head = new_array;
        collection->allocated_size = new_size;
    }

    Node** array = (Node**)collection->head;
    for (size_t i = 0; i < collection->count; i++) {
        if (strcmp(array[i]->data.name, name) > 0) {
            memmove(&array[i + 1], &array[i], (collection->count - i) * sizeof(Node*));
            array[i] = new_node;
            break;
        }
    }

    if (!array[collection->count]) {
        array[collection->count] = new_node;
    }

    collection->count++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

