<?php

class SessionTokenGenerator {
    private $uppercaseChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    private $lowercaseChars = 'abcdefghijklmnopqrstuvwxyz';
    private $digitChars = '0123456789';
    private $specialChars = '!@#$%^&*()_+-=[]{}|;:,.<>?';

    public function generateToken($length) {
        if ($length < 4) {
            throw new InvalidArgumentException("Length must be at least 4 to include all required character types.");
        }

        $token = '';
        $token .= $this->getRandomChar($this->uppercaseChars);
        $token .= $this->getRandomChar($this->lowercaseChars);
        $token .= $this->getRandomChar($this->digitChars);
        $token .= $this->getRandomChar($this->specialChars);

        for ($i = 4; $i < $length; $i++) {
            $token .= $this->getRandomChar($this->uppercaseChars . $this->lowercaseChars . $this->digitChars . $this->specialChars);
        }

        return $token;
    }

    private function getRandomChar($chars) {
        $index = random_int(0, strlen($chars) - 1);
        return $chars[$index];
    }
}

// Usage example:
$generator = new SessionTokenGenerator();
$token = $generator->generateToken(16);
echo "Generated Token: " . $token;
?>
```

