    for (int i = 0; i < num_records; i++) {
        do {
            records[i].key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        } while (i > 0 && records[i].key == records[i - 1].key);

        records[i].offset = rand();
        records[i].value = ((double)rand()) / RAND_MAX * (MAX_VALUE - MIN_VALUE) + MIN_VALUE;
    }

    return records;
}

void free_records(Record* records, int num_records) {
    if (records) {
        free(records);
    }
