typedef struct {
    int tx_frame_parameters;
    int physical_layer_identifier;
    int transmission_power_level;
} PHY_MESSAGE_T;

int populate_phy_messages(int ssi, PHY_MESSAGE_T **messages, int *num_messages) {
    if (ssi < 0 || ssi > 100) {
        return -1; // Invalid SSI value
    }

    *num_messages = ssi + 1;
    *messages = (PHY_MESSAGE_T *)malloc(*num_messages * sizeof(PHY_MESSAGE_T));
    if (*messages == NULL) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < *num_messages; i++) {
        (*messages)[i].tx_frame_parameters = ssi + i;
        (*messages)[i].physical_layer_identifier = i % 100; // Ensure uniqueness
        (*messages)[i].transmission_power_level = ssi - i;
    }

    return 0; // Success
}

int main() {
    PHY_MESSAGE_T *messages;
    int num_messages;

    int result = populate_phy_messages(50, &messages, &num_messages);
    if (result != 0) {
        printf("Error: %d\n", result);
        return 1;
    }

    for (int i = 0; i < num_messages; i++) {
        printf("Message %d: TX Frame Params=%d, Physical Layer ID=%d, Transmission Power Level=%d\n",
               i, messages[i].tx_frame_parameters,
               messages[i].physical_layer_identifier,
               messages[i].transmission_power_level);
    }

    free(messages);

    return 0;
}
