int log_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_log(ResourceUsageLog new_log) {
    pthread_mutex_lock(&lock);
    if (log_count < MAX_LOGS) {
        logs[log_count++] = new_log;
    } else {
        // Handle log overflow, e.g., discard oldest log
        memmove(logs, logs + 1, sizeof(ResourceUsageLog) * (MAX_LOGS - 1));
        logs[MAX_LOGS - 1] = new_log;
    }
    pthread_mutex_unlock(&lock);
}

void update_log(int pid, const char* resource_type, double usage_metric) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < log_count; ++i) {
        if (logs[i].pid == pid && strcmp(logs[i].resource_type, resource_type) == 0) {
            logs[i].usage_metric = usage_metric;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

ResourceUsageLog* get_logs_by_timestamp_range(time_t start_time, time_t end_time, const char* resource_type) {
    static ResourceUsageLog result[MAX_LOGS];
    int result_count = 0;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < log_count; ++i) {
        if (logs[i].timestamp >= start_time && logs[i].timestamp <= end_time &&
            strcmp(logs[i].resource_type, resource_type) == 0) {
            result[result_count++] = logs[i];
        }
    }
    pthread_mutex_unlock(&lock);

