#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TITLE_LENGTH 256
#define MIN_MEMORY_LIMIT 1024 * 1024 // 1MB
#define DEFAULT_MEMORY_LIMIT 1024 * 1024 * 10 // 10MB

typedef struct word {
    char* content;
    struct word* next;
} Word;

typedef struct document {
    size_t length;
    const char* title;
    Word* words;
    struct document* next;
} Document;

Document* create_document(const char* title, size_t memory_limit) {
    // Validate input
    if (title == NULL || strlen(title) >= MAX_TITLE_LENGTH) {
        return NULL;
    }

    // Allocate memory for the document structure
    Document* doc = (Document*)malloc(sizeof(Document));
    if (doc == NULL) {
        return NULL;
    }

    // Initialize document fields
    doc->length = rand() % (memory_limit / sizeof(Word)) + 1; // Random length within memory limit
    doc->title = strdup(title);
    doc->words = NULL;
    doc->next = NULL;

    // Allocate memory for the linked list of words
    Word* current_word = NULL;
    for (size_t i = 0; i < doc->length; ++i) {
        Word* new_word = (Word*)malloc(sizeof(Word));
        if (new_word == NULL) {
            free_document(doc);
            return NULL;
        }
        new_word->content = (char*)malloc(rand() % 16 + 1); // Random word length
        if (new_word->content == NULL) {
            free_document(doc);
            return NULL;
        }
        strcpy(new_word->content, "word");
        new_word->next = NULL;

        if (current_word == NULL) {
            doc->words = new_word;
        } else {
            current_word->next = new_word;
        }
        current_word = new_word;
    }

    return doc;
}

void free_document(Document* doc) {
    // Free the linked list of words
    Word* word = doc->words;
    while (word != NULL) {
        Word* next_word = word->next;
        free(word->content);
        free(word);
        word = next_word;
    }

    // Free the document structure
    free((char*)doc->title);
    free(doc);
}

void log_error(const char* message, FILE* log_file) {
    if (log_file != NULL) {
        fprintf(log_file, "ERROR: %s\n", message);
    }
}

int main() {
    srand(time(NULL));

    // Set memory limit
    size_t memory_limit = DEFAULT_MEMORY_LIMIT;

    // Create a document with a unique title and random length within the memory limit
    Document* doc = create_document("SampleDocument", memory_limit);
    if (doc == NULL) {
        log_error("Failed to create document", stderr);
        return 1;
    }

    // Free the document when done
    free_document(doc);

    return 0;
}
