#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

void initialize_data(long *offsets, int *keys, record *records, size_t N, long L) {
    if (N == 0 || L < 0) {
        return; // Handle edge cases
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        offsets[i] = rand() % 1000; // Example initialization
        keys[i] = rand() % 1000;   // Example initialization

        records[i].value = rand() % 1000;
    }

    long total_sum = 0;
    for (size_t i = 0; i < N; ++i) {
        total_sum += records[i].value;
    }

    if (total_sum > L) {
        // Adjust values to meet the sum constraint
        while (total_sum > L) {
            size_t index_to_reduce = rand() % N;
            int reduction_amount = (int)((total_sum - L) / N);
            if (records[index_to_reduce].value > reduction_amount) {
                records[index_to_reduce].value -= reduction_amount;
                total_sum -= reduction_amount;
            } else {
                reduction_amount = records[index_to_reduce].value;
                records[index_to_reduce].value = 0;
                total_sum -= reduction_amount;
            }
        }
    }
}

void selective_initialize(record *records, size_t start_index, size_t length, long L) {
    if (start_index + length > N || length == 0) {
        return; // Handle edge cases
    }

    for (size_t i = 0; i < length; ++i) {
        records[start_index + i].value = rand() % 1000;
    }

    long total_sum = 0;
    for (size_t i = start_index; i < start_index + length; ++i) {
        total_sum += records[i].value;
    }

    if (total_sum > L) {
        // Adjust values to meet the sum constraint
        while (total_sum > L) {
            size_t index_to_reduce = rand() % length + start_index;
            int reduction_amount = (int)((total_sum - L) / length);
            if (records[index_to_reduce].value > reduction_amount) {
                records[index_to_reduce].value -= reduction_amount;
                total_sum -= reduction_amount;
            } else {
                reduction_amount = records[index_to_reduce].value;
                records[index_to_reduce].value = 0;
                total_sum -= reduction_amount;
            }
        }
    }
}

// Thread-safe version with mutex
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void thread_safe_initialize(record *records, size_t start_index, size_t length, long L) {
    pthread_mutex_lock(&mutex);
    selective_initialize(records, start_index, length, L);
    pthread_mutex_unlock(&mutex);
}
