from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry
import os

class JWTTokenGenerator:
    def __init__(self, environment):
        self.environment = environment
        self.config = self.load_config()
        self.ca_service_url = self.config['ca_service_url']
        self.private_key_path = self.config['private_key_path']
        self.certificate_path = self.config['certificate_path']
        self.cache = {}
        self.rate_limiter = RateLimiter(max_calls=10, period=60)

    def load_config(self):
        # Load environment-specific configuration
        if self.environment == 'development':
            return {
                'ca_service_url': 'http://dev-ca-service.com',
                'private_key_path': '/path/to/dev/private.key',
                'certificate_path': '/path/to/dev/certificate.crt'
            }
        elif self.environment == 'staging':
            return {
                'ca_service_url': 'http://staging-ca-service.com',
                'private_key_path': '/path/to/staging/private.key',
                'certificate_path': '/path/to/staging/certificate.crt'
            }
        elif self.environment == 'production':
            return {
                'ca_service_url': 'https://prod-ca-service.com',
                'private_key_path': '/path/to/prod/private.key',
                'certificate_path': '/path/to/prod/certificate.crt'
            }

    def get_private_key(self):
        # Fetch private key from secure vault with rate limiting
        if not self.rate_limiter.try_call():
            raise Exception("Rate limit exceeded for private key retrieval")

        try:
            with open(self.private_key_path, 'rb') as f:
                return f.read()
        except FileNotFoundError:
            raise Exception("Private key file not found")

    def get_certificate(self):
        # Fetch certificate from secure vault with rate limiting
        if not self.rate_limiter.try_call():
            raise Exception("Rate limit exceeded for certificate retrieval")

        try:
            with open(self.certificate_path, 'rb') as f:
                return f.read()
        except FileNotFoundError:
            raise Exception("Certificate file not found")

    def fetch_ca_certificate(self):
        # Fetch CA certificate from external service
        session = requests.Session()
        retries = Retry(total=3, backoff_factor=1, status_forcelist=[502, 503, 504])
        session.mount('http://', HTTPAdapter(max_retries=retries))
        session.mount('https://', HTTPAdapter(max_retries=retries))

        try:
            response = session.get(self.ca_service_url)
            response.raise_for_status()
            return response.content
        except requests.RequestException as e:
            raise Exception(f"Failed to fetch CA certificate: {e}")

    def generate_jwt_token(self, user_id, permissions):
        # Generate JWT token with caching and rate limiting
        cache_key = f"{user_id}_{permissions}"
        if cache_key in self.cache:
            return self.cache[cache_key]

        private_key = self.get_private_key()
        ca_certificate = self.fetch_ca_certificate()

        payload = {
            'user_id': user_id,
            'permissions': permissions,
            'exp': datetime.utcnow() + timedelta(hours=1)
        }

        token = jwt.encode(payload, private_key, algorithm='RS256', headers={'kid': 'my-key-id'})
        self.cache[cache_key] = token
        return token

class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.call_times = []

    def try_call(self):
        now = datetime.now()
        self.call_times.append(now)
        self.call_times = [t for t in self.call_times if (now - t).total_seconds() < self.period]

        return len(self.call_times) <= self.max_calls

# Example usage
generator = JWTTokenGenerator('production')
token = generator.generate_jwt_token('user123', ['read', 'write'])
print(token)
