#include <string.h>

#define MAX_EVENT_SIZE 1024

typedef struct {
    unsigned long timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    size_t payload_size;
    unsigned long hash;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
    size_t max_capacity;
    void (*hash_function)(NetworkEvent*);
} EventManager;

void default_hash_function(NetworkEvent* event) {
    // Simple hash function using source and destination IPs
    unsigned long hash = 0;
    for (int i = 0; i < strlen(event->source_ip); i++) {
        hash += event->source_ip[i];
    }
    for (int i = 0; i < strlen(event->destination_ip); i++) {
        hash += event->destination_ip[i];
    }
    event->hash = hash;
}

void init_event_manager(EventManager* manager, size_t initial_capacity, void (*hash_func)(NetworkEvent*)) {
    if (!manager || !hash_func) {
        fprintf(stderr, "Error: Null pointer provided.\n");
        return;
    }

    manager->events = (NetworkEvent*)malloc(initial_capacity * sizeof(NetworkEvent));
    if (!manager->events) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->max_capacity = MAX_EVENT_SIZE;
    manager->hash_function = hash_func;
}

void add_event(EventManager* manager, NetworkEvent event) {
    if (!manager || !manager->events) {
        fprintf(stderr, "Error: Null pointer provided.\n");
        return;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > manager->max_capacity) {
            fprintf(stderr, "Error: Maximum capacity exceeded.\n");
            return;
        }
        NetworkEvent* new_events = (NetworkEvent*)realloc(manager->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            return;
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    manager->hash_function(&event);
    manager->events[manager->count++] = event;
}

void free_event_manager(EventManager* manager) {
    if (!manager || !manager->events) {
        fprintf(stderr, "Error: Null pointer provided.\n");
        return;
    }

    free(manager->events);
    manager->events = NULL;
    manager->count = 0;
    manager->capacity = 0;
}

int main() {
    EventManager manager;
    init_event_manager(&manager, 10, default_hash_function);

    NetworkEvent event1 = {1633072800, "192.168.1.1", "10.0.0.1", 6, 1024};
    add_event(&manager, event1);

    free_event_manager(&manager);
    return 0;
}
