    // Process data concurrently
    pthread_t threads[keys[0]];
    for (int i = 0; i < keys[0]; i++) {
        pthread_create(&threads[i], NULL, process_data, &records[i]);
    }

    for (int i = 0; i < keys[0]; i++) {
