    if (!records) return NULL;

    for (int i = 0; i < numRecords; ++i) {
        records[i].value = rand() % 100; // Random value between 0 and 99
        records[i].keyPtr = &keys[i];
    }

    void (*transformFunc)(long*, int*);
    if (loadTransformationFunction(dataSources, &transformFunc)) {
        transformFunc(offsets, keys);
    } else {
        free(records);
        return NULL;
    }

    char* randomString = generateRandomString(10); // Example length
    if (!randomString) {
        free(records);
        return NULL;
    }

    unsigned int hashValue = hashString(randomString);

    for (int i = 0; i < numRecords; ++i) {
        records[i].value += hashValue % 100; // Update value based on hash
    }

    free(randomString);
    return records;
}

int loadTransformationFunction(char** dataSources, void (**funcPtr)(long*, int*)) {
    // Simulate loading transformation function from external source
    *funcPtr = transformFunction;
    return 1; // Success
}

void transformFunction(long* offsets, int* keys) {
    for (int i = 0; i < numRecords; ++i) {
        offsets[i] += keys[i];
    }
}

char* generateRandomString(int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char* randomString = (char*)malloc((length + 1) * sizeof(char));
    if (!randomString) return NULL;

    for (int i = 0; i < length; ++i) {
        randomString[i] = charset[rand() % strlen(charset)];
    }
    randomString[length] = '\0';

    return randomString;
}

unsigned int hashString(const char* str) {
    unsigned int hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash;
}
