using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class TaskScheduler
{
    private PriorityQueue<Task> taskQueue = new PriorityQueue<Task>();
    private string connectionString;
    private Dictionary<string, Func<Task, bool>> priorityComparisons;

    public TaskScheduler(string connectionString)
    {
        this.connectionString = connectionString;
        priorityComparisons = LoadPriorityComparisons();
    }

    public async Task<TaskCompletionSource> ScheduleTaskAsync(Task task)
    {
        if (task == null) throw new ArgumentNullException(nameof(task));

        lock (taskQueue)
        {
            taskQueue.Enqueue(task);
        }

        var tcs = new TaskCompletionSource<bool>();
        await SendTaskToServiceAsync(task, tcs);

        return tcs.Task;
    }

    private async Task SendTaskToServiceAsync(Task task, TaskCompletionSource<bool> tcs)
    {
        using (var client = new TcpClient(connectionString))
        {
            var stream = client.GetStream();
            var data = Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(task));
            await stream.WriteAsync(data, 0, data.Length);

            // Simulate service response
            await Task.Delay(100);
            tcs.SetResult(true);
        }
    }

    public Task<Task> GetHighestPriorityTaskAsync()
    {
        lock (taskQueue)
        {
