#include <stdlib.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t bucket_count;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->bucket_count = initial_capacity;
    list->buckets = (Node**)calloc(initial_capacity, sizeof(Node*));
    if (!list->buckets) {
        free(list);
        return NULL;
    }

    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->bucket_count; ++i) {
        Node* current = list->buckets[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    free(list->buckets);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

size_t hash_function(RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, size_t bucket_count) {
    // Simple hash function for demonstration purposes
    return (ue_info_tag + rnti) % bucket_count;
}

int add_or_update(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);
    size_t index = hash_function(new_data.ue_info_tag, new_data.rnti, list->bucket_count);

    Node** current = &list->buckets[index];
    while (*current) {
        if ((*current)->data.ue_info_tag == new_data.ue_info_tag && (*current)->data.rnti == new_data.rnti) {
            (*current)->data = new_data;
            pthread_mutex_unlock(&list->lock);
            return 0; // Updated
        }
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    new_node->data = new_data;
    new_node->next = *current;
    *current = new_node;

    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 1; // Added
}

int get_by_key(DynamicList* list, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T* result) {
    pthread_mutex_lock(&list->lock);
    size_t index = hash_function(ue_info_tag, rnti, list->bucket_count);

    Node* current = list->buckets[index];
    while (current) {
        if (current->data.ue_info_tag == ue_info_tag && current->data.rnti == rnti) {
            *result = current->data;
            pthread_mutex_unlock(&list->lock);
            return 0; // Found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}
