['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTERFACES 10000

struct Interface {
    char *ip;
    char *mask;
    char *name;
};

struct Config {
    int num_interfaces;
    struct Interface interfaces[MAX_INTERFACES];
};

void add_interface(struct Config *config, const char *ip, const char *mask, const char *name) {
    if (config->num_interfaces >= MAX_INTERFACES) return;

    config->interfaces[config->num_interfaces].ip = strdup(ip);
    config->interfaces[config->num_interfaces].mask = strdup(mask);
    config->interfaces[config->num_interfaces].name = strdup(name);

    config->num_interfaces++;
}

void update_interface(struct Config *config, int index, const char *ip, const char *mask, const char *name) {
    if (index < 0 || index >= config->num_interfaces) return;

    free(config->interfaces[index].ip);
    free(config->interfaces[index].mask);
    free(config->interfaces[index].name);

    config->interfaces[index].ip = strdup(ip);
    config->interfaces[index].mask = strdup(mask);
    config->interfaces[index].name = strdup(name);
}

void delete_interface(struct Config *config, int index) {
    if (index < 0 || index >= config->num_interfaces) return;

    free(config->interfaces[index].ip);
    free(config->interfaces[index].mask);
    free(config->interfaces[index].name);

    for (int i = index; i < config->num_interfaces - 1; i++) {
        config->interfaces[i] = config->interfaces[i + 1];
    }

    config->num_interfaces--;
}

void print_config(const struct Config *config) {
    for (int i = 0; i < config->num_interfaces; i++) {
        printf("Interface %d: IP=%s, Mask=%s, Name=%s\n", i, config->interfaces[i].ip, config->interfaces[i].mask, config->interfaces[i].name);
    }
}

int main() {
    struct Config config = {0};

    add_interface(&config, "192.168.1.1", "255.255.255.0", "eth0");
    add_interface(&config, "192.168.1.2", "255.255.255.0", "eth1");

    print_config(&config);

    update_interface(&config, 0, "192.168.1.3", "255.255.255.0", "eth0");
    print_config(&config);

    delete_interface(&config, 1);
    print_config(&config);

    return 0;
}
