#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

#define MAX_CONNECTIONS 100

typedef struct {
    sqlite3 *db;
    pthread_mutex_t lock;
} ConnectionPool;

ConnectionPool pool[MAX_CONNECTIONS];
int connection_count = 0;

void initialize_pool(int max_size) {
    for (int i = 0; i < max_size; i++) {
        if (sqlite3_open("database.db", &pool[i].db) != SQLITE_OK) {
            fprintf(stderr, "Failed to open database\n");
            exit(1);
        }
        pthread_mutex_init(&pool[i].lock, NULL);
    }
}

void *execute_query(void *arg) {
    char *query = (char *)arg;
    int index = -1;

    // Find an available connection
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_mutex_lock(&pool[i].lock);
        if (connection_count > 0) {
            index = i;
            connection_count--;
            break;
        }
        pthread_mutex_unlock(&pool[i].lock);
    }

    if (index == -1) {
        fprintf(stderr, "No available connections\n");
        return NULL;
    }

    sqlite3_stmt *stmt;
    if (sqlite3_prepare_v2(pool[index].db, query, -1, &stmt, 0) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(pool[index].db));
        pthread_mutex_lock(&pool[index].lock);
        connection_count++;
        pthread_mutex_unlock(&pool[index].lock);
        return NULL;
    }

    // Execute the query
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        // Process the result
    }

    sqlite3_finalize(stmt);

    // Release the connection
    pthread_mutex_lock(&pool[index].lock);
    connection_count++;
    pthread_mutex_unlock(&pool[index].lock);

    return NULL;
}

int main() {
    initialize_pool(MAX_CONNECTIONS);

    pthread_t threads[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        char query[256];
        snprintf(query, sizeof(query), "SELECT * FROM table WHERE id = %d", i);
        pthread_create(&threads[i], NULL, execute_query, query);
    }

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

