    if (num_messages <= 0 || num_messages > MAX_MMEs * MAX_ENBs) {
        fprintf(stderr, "Invalid number of messages. Must be between 1 and %d.\n", MAX_MMEs * MAX_ENBs);
        return NULL;
    }

    LTE_RRC_RECONFIGURATION_MESSAGE* array = (LTE_RRC_RECONFIGURATION_MESSAGE*)malloc(num_messages * sizeof(LTE_RRC_RECONFIGURATION_MESSAGE));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_messages; ++i) {
        array[i].PLMNID = -1; // Initialize to invalid value
        array[i].MME_ID = -1;
        array[i].ENB_ID = -1;

        for (int j = 0; j < MAX_SIBS; ++j) {
            array[i].SIBs[j].SIB_TYPE = -1;
            memset(array[i].SIBs[j].SIB_CONTENT, 0, sizeof(array[i].SIBs[j].SIB_CONTENT));
        }
    }

    return array;
