    if (config_array) {
        // Populate the array with valid data
        for (int i = 0; i < num_messages; ++i) {
            config_array[i].PLMNID = i % MAX_PLMNIDS;
            config_array[i].MME_ID = i % MAX_MMEs;
            config_array[i].ENB_ID = i % MAX_ENBs;

            for (int j = 0; j < MAX_SIBS; ++j) {
                config_array[i].SIBs[j].SIB_TYPE = j + 1;
                snprintf(config_array[i].SIBs[j].SIB_CONTENT, sizeof(config_array[i].SIBs[j].SIB_CONTENT), "SIB%d Content", j + 1);
            }
        }

        // Use the array...

        free_dynamic_array(config_array, num_messages);
    }

    return 0;
}
