#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_BUCKET_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    int size;
    int count;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    table->size = size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned int hash_function(int key) {
    return abs(key % MAX_BUCKET_SIZE);
}

void insert_or_update(HashTable* table, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(data.RX_UE_INFORMATION_TAG);
    HashNode* current = table->buckets[index];
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG) {
            current->data = data;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        current = current->next;
    }
    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    new_node->data = data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->count++;
    pthread_mutex_unlock(&table->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_data(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(key);
    HashNode* current = table->buckets[index];
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == key) {
            NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *result = current->data;
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        HashNode* current = table->buckets[i];
        while (current != NULL) {
            HashNode* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
