}

void update_memory_manager(MemoryManager *mm, size_t new_size) {
    pthread_mutex_lock(&mm->mutex);

    if (new_size > mm->array_size) {
        double *new_double_values = (double*)realloc(mm->double_values, new_size * sizeof(double));
        char **new_char_strings = (char**)realloc(mm->char_strings, new_size * sizeof(char*));
        Point *new_point_array = (Point*)realloc(mm->point_array, new_size * sizeof(Point));

        if (!new_double_values || !new_char_strings || !new_point_array) {
            pthread_mutex_unlock(&mm->mutex);
            return;
        }

        mm->double_values = new_double_values;
        mm->char_strings = new_char_strings;
        mm->point_array = new_point_array;
        mm->array_size = new_size;

        // Initialize new elements
        for (size_t i = mm->array_size - 1; i < new_size; ++i) {
            mm->double_values[i] = 0.0;
            mm->char_strings[i] = NULL;
            pthread_create(&mm->point_array[i].x, NULL, initialize_point, mm);
        }
    }

    pthread_mutex_unlock(&mm->mutex);
}

