void destroyMediaStream(MediaStream* stream) {
    if (stream->payload) free(stream->payload);
    for (int i = 0; i < stream->numVisualData; ++i) {
        if (stream->visualData[i]->data) free(stream->visualData[i]->data);
        free(stream->visualData[i]);
    }
