function reduceAsync(arr, initialValue, callback, cb) {
    let result = initialValue;
    const processNext = () => {
        if (arr.length === 0) {
            cb(null, result);
            return;
        }
        const item = arr.shift();
        callback(item, result, (err, nextResult) => {
            if (err) {
                cb(err);
                return;
            }
            result = nextResult;
            processNext();
        });
    };
    processNext();
}

// Example usage
const numbers = [1, 2, 3, 4, 5];
reduceAsync(numbers, 0, (num, acc, callback) => {
    setTimeout(() => {
        callback(null, acc + num);
    }, 100);
}, (err, result) => {
    if (err) console.error(err);
    else console.log(result); // Output: 15
});
```

