#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    TX_RLC_PDU pdu;
    PUSCH_GRANT grant;
    SNR_ESTIMATE snr;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T* messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_MESSAGE_ARRAY;

NFAPI_MESSAGE_ARRAY* create_nfaapi_message_array() {
    NFAPI_MESSAGE_ARRAY* array = (NFAPI_MESSAGE_ARRAY*)malloc(sizeof(NFAPI_MESSAGE_ARRAY));
    if (!array) return NULL;

    array->messages = (NFAPI_MESSAGE_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_MESSAGE_T));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_nfaapi_message_array(NFAPI_MESSAGE_ARRAY* array) {
    if (array) {
        free(array->messages);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int add_nfaapi_message(NFAPI_MESSAGE_ARRAY* array, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        NFAPI_MESSAGE_T* new_messages = (NFAPI_MESSAGE_T*)realloc(array->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
        if (!new_messages) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }

        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    array->messages[array->size++] = message;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_nfaapi_message(NFAPI_MESSAGE_ARRAY* array, size_t index, NFAPI_MESSAGE_T new_message) {
    if (index >= array->size) return -1; // Index out of bounds

    pthread_mutex_lock(&array->lock);

    array->messages[index] = new_message;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

NFAPI_MESSAGE_T get_nfaapi_message(NFAPI_MESSAGE_ARRAY* array, size_t index) {
    if (index >= array->size) {
        NFAPI_MESSAGE_T empty_message = {0};
        return empty_message; // Return an empty message for invalid index
    }

    pthread_mutex_lock(&array->lock);

    NFAPI_MESSAGE_T message = array->messages[index];

    pthread_mutex_unlock(&array->lock);
    return message;
}
