    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->records[i].key == key) {
            Record *record = &pool->records[i];
            pthread_mutex_unlock(&pool->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

int delete_record(MemoryPool *pool, int key) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->records[i].key == key) {
            memmove(&pool->records[i], &pool->records[i + 1], (pool->size - i - 1) * sizeof(Record));
            --pool->size;
            pthread_mutex_unlock(&pool->lock);
            return 0; // Record deleted successfully
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // Record not found
}

int store_records(MemoryPool *pool, StorageSystem *storage) {
