    bool crcFlag;
};

class ThreadSafeListManager {
public:
    void addOrUpdate(const std::string& key, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mutex_);
        list_[key] = pdu;
    }

    void insertAfterString(const std::string& target, const std::string& toInsert) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = forwardList_.before_begin();
        for (; it != forwardList_.end(); ++it) {
            if (*it == target) {
                break;
            }
        }
        if (it == forwardList_.end()) {
            forwardList_.push_back(toInsert);
        } else {
            forwardList_.insert_after(it, toInsert);
        }
    }

private:
    std::mutex mutex_;
    std::unordered_map<std::string, NFAPI_CRC_INDICATION_PDU_T> list_;
    std::forward_list<std::string> forwardList_;
};

void simulateExternalInteraction(ThreadSafeListManager& manager) {
    // Simulate external interactions with a database or network service
    std::this_thread::sleep_for(std::chrono::milliseconds(10));
}

int main() {
    ThreadSafeListManager manager;
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, true};
    manager.addOrUpdate("key1", pdu);

    manager.insertAfterString("target", "toInsert");

    simulateExternalInteraction(manager);

