#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} dynamic_array;

dynamic_array* create_dynamic_array(size_t initial_capacity) {
    dynamic_array* array = (dynamic_array*)malloc(sizeof(dynamic_array));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    array->offsets = (long*)malloc(initial_capacity * sizeof(long));
    array->keys = (int*)malloc(initial_capacity * sizeof(int));
    array->records = (record**)malloc(initial_capacity * sizeof(record*));
    if (!array->offsets || !array->keys || !array->records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(dynamic_array* array) {
    if (array) {
        for (size_t i = 0; i < array->size; ++i) {
            free(array->records[i]);
        }
        free(array->offsets);
        free(array->keys);
        free(array->records);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

void resize_dynamic_array(dynamic_array* array, size_t new_capacity) {
    if (new_capacity <= array->capacity) return;
    long* new_offsets = (long*)realloc(array->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(array->keys, new_capacity * sizeof(int));
    record** new_records = (record**)realloc(array->records, new_capacity * sizeof(record*));
    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        return;
    }
    array->offsets = new_offsets;
    array->keys = new_keys;
    array->records = new_records;
    array->capacity = new_capacity;
}

void add_record(dynamic_array* array, long offset, int key, int value) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
    }
    array->offsets[array->size] = offset;
    array->keys[array->size] = key;
    array->records[array->size] = (record*)malloc(sizeof(record));
    if (!array->records[array->size]) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    array->records[array->size]->value = value;
    ++array->size;
    pthread_mutex_unlock(&array->mutex);
}

record* get_record(dynamic_array* array, int key) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->keys[i] == key) {
            record* result = array->records[i];
            pthread_mutex_unlock(&array->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}
