#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_OBJECTS 10000
#define OBJECT_SIZE 50
#define MEMORY_LIMIT 500 * 1024

typedef struct {
    double value;
    int ref_count;
    time_t timestamp;
} custom_object;

custom_object** create_collection(int* size) {
    if (size == NULL || *size <= 0 || *size > MAX_OBJECTS) {
        fprintf(stderr, "Invalid size\n");
        exit(EXIT_FAILURE);
    }

    custom_object** collection = (custom_object**)malloc(*size * sizeof(custom_object*));
    if (collection == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memset(collection, 0, *size * sizeof(custom_object*));

    return collection;
}

void add_object(custom_object** collection, int* size, double value, time_t timestamp) {
    if (value < 0 || timestamp <= 0) {
        fprintf(stderr, "Invalid object parameters\n");
        return;
    }

    for (int i = 0; i < *size; i++) {
        if (collection[i] == NULL) {
            collection[i] = (custom_object*)malloc(sizeof(custom_object));
            if (collection[i] == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            collection[i]->value = value;
            collection[i]->ref_count = 1;
            collection[i]->timestamp = timestamp;
            return;
        }
    }

    // Reallocate memory if no space is available
    custom_object** new_collection = (custom_object**)realloc(collection, (*size + 1) * sizeof(custom_object*));
    if (new_collection == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection = new_collection;
    collection[*size] = (custom_object*)malloc(sizeof(custom_object));
    if (collection[*size] == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection[*size]->value = value;
    collection[*size]->ref_count = 1;
    collection[*size]->timestamp = timestamp;
    (*size)++;
}

void serialize_collection(custom_object** collection, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "File opening failed\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        if (collection[i] != NULL) {
            fwrite(collection[i], sizeof(custom_object), 1, file);
        }
    }

    fclose(file);
}

void free_collection(custom_object** collection, int size) {
    for (int i = 0; i < size; i++) {
        if (collection[i] != NULL) {
            free(collection[i]);
        }
    }
    free(collection);
}

int main() {
    int size;
    printf("Enter the number of objects: ");
    scanf("%d", &size);

    custom_object** collection = create_collection(&size);

    for (int i = 0; i < size; i++) {
        double value;
        time_t timestamp;
        printf("Enter object %d value and timestamp: ", i + 1);
        scanf("%lf %ld", &value, &timestamp);
        add_object(collection, &size, value, timestamp);
    }

    serialize_collection(collection, size, "collection.bin");

    free_collection(collection, size);

    return 0;
}
