void destroyLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data); // Free the object data
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

void insertObject(LinkedList* list, Object* obj) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = obj;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void deleteObject(LinkedList* list, Object* obj) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data == obj) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data); // Free the object data
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

Node* searchObject(LinkedList* list, Object* obj) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data == obj) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

