typedef struct PacketNode {
    DataPacket packet;
    struct PacketNode* next;
} PacketNode;

typedef struct PriorityQueue {
    PacketNode* front;
    pthread_mutex_t lock;
} PriorityQueue;

void init_priority_queue(PriorityQueue* pq) {
    pq->front = NULL;
    pthread_mutex_init(&pq->lock, NULL);
}

void enqueue_packet(PriorityQueue* pq, DataPacket packet) {
    pthread_mutex_lock(&pq->lock);
    PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
    new_node->packet = packet;
    new_node->next = NULL;

    if (pq->front == NULL || pq->front->packet.timestamp > packet.timestamp) {
        new_node->next = pq->front;
        pq->front = new_node;
    } else {
        PacketNode* current = pq->front;
        while (current->next != NULL && current->next->packet.timestamp <= packet.timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&pq->lock);
}

DataPacket* dequeue_packet(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);
    if (pq->front == NULL) {
        pthread_mutex_unlock(&pq->lock);
        return NULL;
    }

    PacketNode* temp = pq->front;
    DataPacket* packet = &temp->packet;
    pq->front = pq->front->next;
    free(temp);
    pthread_mutex_unlock(&pq->lock);
    return packet;
}

void update_packet(PriorityQueue* pq, int id, DataPacket new_packet) {
    pthread_mutex_lock(&pq->lock);
    PacketNode* current = pq->front;
    while (current != NULL) {
        if (current->packet.id == id) {
            current->packet = new_packet;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&pq->lock);
}

