    if (offsets_size <= 0 || keys_size <= 0 || records_size <= 0) {
        fprintf(stderr, "Error: Sizes must be greater than zero.\n");
        return NULL;
    }

    long* offsets = malloc(offsets_size * sizeof(long));
    int* keys = malloc(keys_size * sizeof(int));
    record* records = malloc(records_size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (int i = 0; i < offsets_size; ++i) {
        offsets[i] = i;
    }

    srand(time(NULL));
    for (int i = 0; i < keys_size; ++i) {
        int key;
        do {
            key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        } while (i > 0 && key == keys[i - 1]);
        keys[i] = key;
    }

    for (int i = 0; i < records_size; ++i) {
        records[i].value = rand() % (record_value_range_end - record_value_range_start + 1) + record_value_range_start;
        records[i].offset = &offsets[rand() % offsets_size];
    }

    return records;
}
