#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long* offset;
} record;

void allocate_memory(long** offsets, int** keys, record** records, size_t size, long increment, int key_range, int record_value_range, const char* file_name) {
    // Allocate memory for arrays
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize offsets array
    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = i * increment;
    }

    // Initialize keys array with unique random values
    srand(time(NULL));
    int* key_set = (int*)malloc(key_range * sizeof(int));
    for (int i = 0; i < key_range; ++i) {
        key_set[i] = i + 1;
    }
    for (size_t i = 0; i < size; ++i) {
        int random_index = rand() % (key_range - i);
        (*keys)[i] = key_set[random_index];
        // Swap to remove used key
        key_set[random_index] = key_set[key_range - i - 1];
    }
    free(key_set);

    // Initialize records array with random values and offsets
    for (size_t i = 0; i < size; ++i) {
        (*records)[i].value = rand() % record_value_range;
        (*records)[i].offset = &(*offsets)[i];
    }

    // Serialize records to binary file
    FILE* file = fopen(file_name, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(1);
    }
    fwrite((*records), sizeof(record), size, file);
    fclose(file);

    // Deserialize records from binary file
    record* deserialized_records = (record*)malloc(size * sizeof(record));
    FILE* read_file = fopen(file_name, "rb");
    if (read_file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        exit(1);
    }
    size_t read_count = fread(deserialized_records, sizeof(record), size, read_file);
    fclose(read_file);

    // Verify deserialization
    if (read_count != size) {
        fprintf(stderr, "Deserialization failed: incomplete data\n");
        exit(1);
    }

    // Free allocated memory
    free(*offsets);
    free(*keys);
    free(*records);
    free(deserialized_records);
}

int main() {
    size_t size = 1000;
    long increment = 10;
    int key_range = 5000;
    int record_value_range = 10000;
    const char* file_name = "records.bin";

    allocate_memory(NULL, NULL, NULL, size, increment, key_range, record_value_range, file_name);

    return 0;
}
