int validate_and_stream_frame(const char *file_path, size_t buffer_limit) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size > buffer_limit) {
        fclose(file);
        return -2;
    }

    char *buffer = malloc(file_size);
    if (!buffer) {
        fclose(file);
        return -3;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    fclose(file);

    if (bytes_read != file_size) {
        free(buffer);
        return -4;
    }

    time_t last_modified = get_last_modified_time(file_path);
    printf("Last modified: %s\n", ctime(&last_modified));

