#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_BATCH_SIZE 1024
#define MIN_MEMORY_THRESHOLD 512

typedef struct {
    int offset;
    char key[64];
    float value;
} Record;

typedef struct {
    int valid_keys;
    int allocated_size;
    Record *records;
} Batch;

Batch* create_batch(int initial_size) {
    Batch *batch = (Batch*)malloc(sizeof(Batch));
    if (!batch) return NULL;

    batch->valid_keys = 0;
    batch->allocated_size = initial_size;
    batch->records = (Record*)calloc(initial_size, sizeof(Record));
    if (!batch->records) {
        free(batch);
        return NULL;
    }

    return batch;
}

void destroy_batch(Batch *batch) {
    if (batch) {
        free(batch->records);
        free(batch);
    }
}

int add_record_to_batch(Batch *batch, int offset, const char *key, float value) {
    if (!batch || !key || offset < 0 || strlen(key) >= sizeof(batch->records[0].key)) return -1;

    if (batch->valid_keys == batch->allocated_size) {
        Batch *new_batch = create_batch(batch->allocated_size * 2);
        if (!new_batch) return -1;

        for (int i = 0; i < batch->valid_keys; i++) {
            new_batch->records[i] = batch->records[i];
        }

        destroy_batch(batch);
        batch = new_batch;
    }

    batch->records[batch->valid_keys].offset = offset;
    strcpy(batch->records[batch->valid_keys].key, key);
    batch->records[batch->valid_keys].value = value;
    batch->valid_keys++;

    return 0;
}

void* process_batch(void *arg) {
    Batch *batch = (Batch*)arg;
    if (!batch) return NULL;

    // Simulate processing
    for (int i = 0; i < batch->valid_keys; i++) {
        printf("Processing record: offset=%d, key=%s, value=%.2f\n", 
               batch->records[i].offset, batch->records[i].key, batch->records[i].value);
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_BATCH_SIZE];
    Batch *batches[MAX_BATCH_SIZE];

    // Create batches and add records
    for (int i = 0; i < MAX_BATCH_SIZE; i++) {
        batches[i] = create_batch(10);
        if (!batches[i]) continue;

        for (int j = 0; j < 5; j++) {
            add_record_to_batch(batches[i], j, "key", (float)j * 1.1);
        }
    }

    // Process batches concurrently
    for (int i = 0; i < MAX_BATCH_SIZE; i++) {
        if (batches[i]) {
            pthread_create(&threads[i], NULL, process_batch, batches[i]);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_BATCH_SIZE; i++) {
        if (batches[i]) {
            pthread_join(threads[i], NULL);
            destroy_batch(batches[i]);
        }
    }

    return 0;
}
