['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t capacity;
    size_t size;
    float load_factor_threshold;
} HashTable;

unsigned long hash_function(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

HashTable* create_hash_table(size_t initial_capacity, float load_factor_threshold) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table.\n");
        return NULL;
    }
    table->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!table->buckets) {
        free(table);
        fprintf(stderr, "Memory allocation failed for buckets.\n");
        return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    table->load_factor_threshold = load_factor_threshold;
    return table;
}

void insert_record(HashTable *table, int key, int value) {
    if (table->size / (float)table->capacity >= table->load_factor_threshold) {
        // Resize the hash table
        size_t new_capacity = table->capacity * GROWTH_FACTOR;
        Record **new_buckets = (Record**)calloc(new_capacity, sizeof(Record*));
        if (!new_buckets) {
            fprintf(stderr, "Memory allocation failed for new buckets.\n");
            return;
        }
        for (size_t i = 0; i < table->capacity; ++i) {
            Record *current = table->buckets[i];
            while (current) {
                Record *next = current->next;
                size_t index = hash_function(current->key, new_capacity);
                current->next = new_buckets[index];
                new_buckets[index] = current;
                current = next;
            }
        }
        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }

    size_t index = hash_function(key, table->capacity);
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for new record.\n");
        return;
    }
    new_record->key = key;
    new_record->value = value;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;
    ++table->size;
}

int lookup_record(HashTable *table, int key) {
    size_t index = hash_function(key, table->capacity);
    Record *current = table->buckets[index];
    while (current) {
        if (current->key == key) {
            return current->value;
        }
        current = current->next;
    }
    return -1; // Key not found
}

void delete_record(HashTable *table, int key) {
    size_t index = hash_function(key, table->capacity);
    Record *current = table->buckets[index];
    Record *prev = NULL;
    while (current) {
        if (current->key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                table->buckets[index] = current->next;
            }
            free(current);
            --table->size;
            return;
        }
        prev = current;
        current = current->next;
    }
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *current = table->buckets[i];
        while (current) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}

int main() {
    HashTable *table = create_hash_table(INITIAL_CAPACITY, LOAD_FACTOR_THRESHOLD);
    if (!table) {
        return 1;
    }

    insert_record(table, 10, 20);
    insert_record(table, 30, 40);
    printf("Value for key 10: %d\n", lookup_record(table, 10));
    delete_record(table, 10);
    printf("Value for key 10 after deletion: %d\n", lookup_record(table, 10));

    destroy_hash_table(table);
    return 0;
}
