#include <time.h>

typedef struct Record {
    int key;
    // Add other fields as needed
} Record;

typedef struct RecordList {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordList;

int initRecordList(RecordList** list, size_t maxRecords) {
    if (maxRecords == 0 || maxRecords > SIZE_MAX / sizeof(Record)) {
        return -1; // Invalid input
    }

    *list = malloc(sizeof(RecordList));
    if (*list == NULL) {
        return -2; // Memory allocation failed
    }

    (*list)->records = calloc(maxRecords, sizeof(Record));
    if ((*list)->records == NULL) {
        free(*list);
        return -3; // Memory allocation failed
    }

    (*list)->capacity = maxRecords;
    (*list)->size = 0;
    pthread_mutex_init(&(*list)->mutex, NULL);

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < maxRecords; ++i) {
        (*list)->records[i].key = rand() % maxRecords; // Initialize with random values
    }

    return 0;
}

int serializeRecordList(RecordList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // File opening failed
    }

    size_t written = fwrite(list->records, sizeof(Record), list->size, file);
    fclose(file);

    if (written != list->size) {
        return -2; // Serialization failed
    }

    return 0;
}

void freeRecordList(RecordList* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->records);
    free(list);
}
