#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CACHE_SIZE 1024

typedef struct CacheEntry {
    char *key;
    char *value;
    time_t expiration_time;
    int reference_count;
    struct CacheEntry *next;
} CacheEntry;

typedef struct Cache {
    CacheEntry **buckets;
    size_t size;
    pthread_mutex_t lock;
} Cache;

Cache *create_cache(size_t size) {
    Cache *cache = (Cache *)malloc(sizeof(Cache));
    cache->size = size;
    cache->buckets = (CacheEntry **)calloc(size, sizeof(CacheEntry *));
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(Cache *cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        CacheEntry *entry = cache->buckets[i];
        while (entry != NULL) {
            CacheEntry *next = entry->next;
            free(entry->key);
            free(entry->value);
            free(entry);
            entry = next;
        }
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache->buckets);
    free(cache);
}

CacheEntry *find_entry(Cache *cache, const char *key) {
    size_t index = hash(key) % cache->size;
    CacheEntry *entry = cache->buckets[index];
    while (entry != NULL && strcmp(entry->key, key) != 0) {
        entry = entry->next;
    }
    return entry;
}

void add_entry(Cache *cache, const char *key, const char *value, time_t expiration_time) {
    pthread_mutex_lock(&cache->lock);
    CacheEntry *entry = find_entry(cache, key);
    if (entry != NULL) {
        free(entry->value);
        entry->value = strdup(value);
        entry->expiration_time = expiration_time;
        entry->reference_count++;
    } else {
        size_t index = hash(key) % cache->size;
        CacheEntry *new_entry = (CacheEntry *)malloc(sizeof(CacheEntry));
        new_entry->key = strdup(key);
        new_entry->value = strdup(value);
        new_entry->expiration_time = expiration_time;
        new_entry->reference_count = 1;
        new_entry->next = cache->buckets[index];
        cache->buckets[index] = new_entry;
    }
    pthread_mutex_unlock(&cache->lock);
}

void update_entry(Cache *cache, const char *key, const char *value, time_t expiration_time) {
    add_entry(cache, key, value, expiration_time);
}

char *get_entry(Cache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);
    CacheEntry *entry = find_entry(cache, key);
    if (entry != NULL && entry->expiration_time > time(NULL)) {
        entry->reference_count++;
        pthread_mutex_unlock(&cache->lock);
        return strdup(entry->value);
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void evict_entries(Cache *cache) {
    // Implement LRU eviction policy
}

int main() {
    Cache *cache = create_cache(MAX_CACHE_SIZE);

    add_entry(cache, "key1", "value1", time(NULL) + 3600);
    update_entry(cache, "key1", "new_value1", time(NULL) + 7200);
    char *value = get_entry(cache, "key1");
    if (value != NULL) {
        printf("Value: %s\n", value);
        free(value);
    }

    destroy_cache(cache);

    return 0;
}
```

