typedef struct {
    time_t timestamp;
    int packet_id;
    int payload_length;
    char *metadata;
} DataPacket;

typedef struct {
    DataPacket **packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->packets = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void free_packet_manager(PacketManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i]->metadata);
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
}

void add_packet(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity > 0 ? manager->capacity * 2 : 1;
        manager->packets = realloc(manager->packets, new_capacity * sizeof(DataPacket *));
        manager->capacity = new_capacity;
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
}

DataPacket* get_packet_by_id(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->packet_id == packet_id) {
            DataPacket *result = manager->packets[i];
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void update_packet(PacketManager *manager, int packet_id, DataPacket *new_packet) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->packet_id == packet_id) {
            free(manager->packets[i]->metadata);
            memcpy(manager->packets[i], new_packet, sizeof(DataPacket));
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

