#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define MAX_STREAMS 100
#define INITIAL_ALLOC_SIZE 1024

typedef struct {
    double value;
} Record;

typedef struct {
    int offset;
    float* keys;
    size_t num_keys;
    Record* records;
    size_t alloc_size;
} DataStream;

typedef struct {
    DataStream streams[MAX_STREAMS];
    size_t num_streams;
    size_t total_memory_usage;
    size_t memory_threshold;
} DataProcessor;

size_t hash_function(float key, size_t max_index) {
    // Custom hash function to map keys to indices
    return (size_t)(key * max_index) % max_index;
}

void initialize_stream(DataStream* stream, int offset, float* keys, size_t num_keys) {
    stream->offset = offset;
    stream->keys = keys;
    stream->num_keys = num_keys;
    stream->alloc_size = INITIAL_ALLOC_SIZE;
    stream->records = (Record*)malloc(stream->alloc_size * sizeof(Record));
}

void resize_stream(DataStream* stream, size_t new_size) {
    if (new_size > stream->alloc_size) {
        Record* new_records = (Record*)realloc(stream->records, new_size * sizeof(Record));
        if (new_records == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        stream->records = new_records;
        stream->alloc_size = new_size;
    }
}

void process_stream(DataStream* stream, DataProcessor* processor) {
    size_t max_index = stream->num_keys * 2; // Example: double the number of keys for hash table size
    resize_stream(stream, max_index);

    for (size_t i = 0; i < stream->num_keys; ++i) {
        size_t index = hash_function(stream->keys[i], max_index);
        if (index >= stream->alloc_size) {
            fprintf(stderr, "Hash function produced an out-of-bounds index\n");
            exit(EXIT_FAILURE);
        }
        stream->records[index].value = exp(stream->keys[i]);
    }

    processor->total_memory_usage += sizeof(Record) * max_index;
}

void initialize_processor(DataProcessor* processor, size_t memory_threshold) {
    processor->num_streams = 0;
    processor->total_memory_usage = 0;
    processor->memory_threshold = memory_threshold;
}

void add_stream(DataProcessor* processor, int offset, float* keys, size_t num_keys) {
    if (processor->num_streams >= MAX_STREAMS) {
        fprintf(stderr, "Maximum number of streams reached\n");
        exit(EXIT_FAILURE);
    }
    initialize_stream(&processor->streams[processor->num_streams], offset, keys, num_keys);
    processor->num_streams++;
}

void process_all_streams(DataProcessor* processor) {
    for (size_t i = 0; i < processor->num_streams; ++i) {
        if (processor->total_memory_usage + sizeof(Record) * processor->streams[i].num_keys > processor->memory_threshold) {
            fprintf(stderr, "Memory threshold exceeded\n");
            exit(EXIT_FAILURE);
        }
        process_stream(&processor->streams[i], processor);
    }
}

void cleanup_processor(DataProcessor* processor) {
    for (size_t i = 0; i < processor->num_streams; ++i) {
        free(processor->streams[i].records);
    }
}
