#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double x;
    double y;
} point;

typedef struct {
    int num_points;
    point* points;
    double min_x, max_x, min_y, max_y;
} polygon;

typedef struct {
    double radius;
    double center_x, center_y;
    double rect_min_x, rect_max_x, rect_min_y, rect_max_y;
} circle;

polygon* create_polygon(int num_points) {
    if (num_points <= 0) {
        fprintf(stderr, "Error: Invalid number of points for polygon.\n");
        return NULL;
    }
    polygon* poly = (polygon*)malloc(sizeof(polygon));
    if (!poly) {
        fprintf(stderr, "Error: Memory allocation failed for polygon.\n");
        return NULL;
    }
    poly->num_points = num_points;
    poly->points = (point*)malloc(num_points * sizeof(point));
    if (!poly->points) {
        free(poly);
        fprintf(stderr, "Error: Memory allocation failed for polygon points.\n");
        return NULL;
    }
    // Initialize bounding box
    poly->min_x = poly->max_x = poly->points[0].x;
    poly->min_y = poly->max_y = poly->points[0].y;
    for (int i = 1; i < num_points; i++) {
        if (poly->points[i].x < poly->min_x) poly->min_x = poly->points[i].x;
        if (poly->points[i].x > poly->max_x) poly->max_x = poly->points[i].x;
        if (poly->points[i].y < poly->min_y) poly->min_y = poly->points[i].y;
        if (poly->points[i].y > poly->max_y) poly->max_y = poly->points[i].y;
    }
    return poly;
}

circle* create_circle(double radius, double center_x, double center_y) {
    if (radius <= 0) {
        fprintf(stderr, "Error: Invalid radius for circle.\n");
        return NULL;
    }
    circle* circ = (circle*)malloc(sizeof(circle));
    if (!circ) {
        fprintf(stderr, "Error: Memory allocation failed for circle.\n");
        return NULL;
    }
    circ->radius = radius;
    circ->center_x = center_x;
    circ->center_y = center_y;
    // Calculate bounding rectangle
    circ->rect_min_x = center_x - radius;
    circ->rect_max_x = center_x + radius;
    circ->rect_min_y = center_y - radius;
    circ->rect_max_y = center_y + radius;
    return circ;
}

void free_polygon(polygon* poly) {
    if (poly) {
        free(poly->points);
        free(poly);
    }
}

void free_circle(circle* circ) {
    if (circ) {
        free(circ);
    }
}
