void add_project(const char *title, int priority) {
    pthread_mutex_lock(&project_lock);
    if (project_count >= MAX_PROJECTS) {
        printf("Project list is full.\n");
        pthread_mutex_unlock(&project_lock);
        return;
    }
    project_list[project_count] = malloc(sizeof(project));
    strcpy(project_list[project_count]->title, title);
    project_list[project_count]->priority = priority;
    project_list[project_count]->data = malloc(sizeof(project_data));
    memset(project_list[project_count]->data, 0, sizeof(project_data));
    project_count++;
    pthread_mutex_unlock(&project_lock);
}

void update_project_completion() {
    for (int i = 0; i < project_count; i++) {
        int retries = 0;
        while (retries < API_RETRY_LIMIT) {
            // Simulate API call
            if (simulate_api_call(project_list[i]->title)) {
                pthread_mutex_lock(&project_lock);
                project_list[i]->data->completion_percentage = get_completion_from_api(project_list[i]->title);
                pthread_mutex_unlock(&project_lock);
                break;
            }
            retries++;
        }
    }
}

int simulate_api_call(const char *title) {
    // Simulate API call with random success rate
    return rand() % 2 == 0;
}

double get_completion_from_api(const char *title) {
