    return (rand() % 101) / 100.0; // Random value between 0 and 1
}

void free_project_list() {
    pthread_mutex_lock(&project_lock);
    for (int i = 0; i < project_count; i++) {
        free(project_list[i]->data);
        free(project_list[i]);
    }
    project_count = 0;
    pthread_mutex_unlock(&project_lock);
}
