typedef struct {
    float value;
    char metadata[256];
} Data;

typedef struct Node {
    Data* data;
    int index;
} Node;

typedef struct DataSource {
    // Define the interface for a data source
    const char* (*getMetadata)(int);
    float (*getValue)();
} DataSource;

Node* initializeNodes(int count, DataSource* dataSource) {
    if (count <= 0 || dataSource == NULL) {
        return NULL;
    }

    Node* nodes = (Node*)malloc(count * sizeof(Node));
    if (nodes == NULL) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        nodes[i].data = (Data*)malloc(sizeof(Data));
        if (nodes[i].data == NULL) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(nodes[j].data);
            }
            free(nodes);
            return NULL;
        }

        nodes[i].index = i;
        nodes[i].data->value = dataSource->getValue();
        strncpy(nodes[i].data->metadata, dataSource->getMetadata(i), sizeof(nodes[i].data->metadata));
    }

    return nodes;
}

void freeNodes(Node* nodes, int count) {
    if (nodes == NULL || count <= 0) {
        return;
    }

    for (int i = 0; i < count; ++i) {
        free(nodes[i].data);
    }
    free(nodes);
}
