typedef struct {
    int timestamp;
    int ci;
    int power_level;
} TX_POWER_REPORT_T;

typedef struct {
    TX_POWER_REPORT_T *reports;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PowerReportManager;

PowerReportManager* create_power_report_manager(size_t initial_capacity) {
    PowerReportManager *manager = (PowerReportManager*)malloc(sizeof(PowerReportManager));
    manager->reports = (TX_POWER_REPORT_T*)calloc(initial_capacity, sizeof(TX_POWER_REPORT_T));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_power_report_manager(PowerReportManager *manager) {
    free(manager->reports);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_power_report(PowerReportManager *manager, int ci, int power_level) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->reports[i].ci == ci) {
            manager->reports[i].timestamp = time(NULL);
            manager->reports[i].power_level = power_level;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Updated successfully
        }
    }
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TX_POWER_REPORT_T *new_reports = (TX_POWER_REPORT_T*)realloc(manager->reports, new_capacity * sizeof(TX_POWER_REPORT_T));
        if (!new_reports) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->reports = new_reports;
        manager->capacity = new_capacity;
    }
    manager->reports[manager->size].timestamp = time(NULL);
    manager->reports[manager->size].ci = ci;
    manager->reports[manager->size].power_level = power_level;
    ++manager->size;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Added successfully
}

TX_POWER_REPORT_T* get_latest_power_report(PowerReportManager *manager, int ci) {
    pthread_mutex_lock(&manager->lock);
    for (int i = manager->size - 1; i >= 0; --i) {
        if (manager->reports[i].ci == ci) {
            TX_POWER_REPORT_T* report = &manager->reports[i];
            pthread_mutex_unlock(&manager->lock);
            return report;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Report not found
}
