    }

    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand() % 1000L;
        (*keys)[i] = rand() % 100;
        (*records)[i].value = rand() % 1000;
    }

    return 0; // Success
}

int serialize_records(int size, long* offsets, int* keys, record* records, FILE* file) {
    if (fwrite(offsets, sizeof(long), size, file) != size ||
        fwrite(keys, sizeof(int), size, file) != size ||
        fwrite(records, sizeof(record), size, file) != size) {
        return -1; // Serialization failed
    }

    return 0; // Success
}

int deserialize_records(int size, long** offsets, int** keys, record** records, FILE* file) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -2; // Memory allocation failed
    }

    size_t read_offsets = fread(*offsets, sizeof(long), size, file);
    size_t read_keys = fread(*keys, sizeof(int), size, file);
    size_t read_records = fread(*records, sizeof(record), size, file);

    if (read_offsets != size || read_keys != size || read_records != size) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -3; // Deserialization failed
    }

    return 0; // Success
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}
