typedef struct {
    size_t capacity;
    size_t size;
    void **elements;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->capacity = initial_capacity;
    array->size = 0;
    array->elements = (void**)malloc(initial_capacity * sizeof(void*));
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->elements[i]);
    }
    free(array->elements);
    free(array);
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    void **new_elements = (void**)realloc(array->elements, new_capacity * sizeof(void*));
    if (new_elements == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->elements = new_elements;
    array->capacity = new_capacity;
}

int main() {
    DynamicArray *array = create_dynamic_array(10);

    int num;
    while (scanf("%d", &num) == 1) {
        if (array->size >= array->capacity) {
            resize_dynamic_array(array, array->capacity * 2);
        }
        array->elements[array->size++] = malloc(sizeof(int));
        *(int*)array->elements[array->size - 1] = num;
    }

    int max_num = array->elements[0];
    for (size_t i = 1; i < array->size; ++i) {
        if (*(int*)array->elements[i] > max_num) {
            max_num = *(int*)array->elements[i];
        }
    }

    printf("Largest integer: %d\n", max_num);

    destroy_dynamic_array(array);
    return 0;
}
