using System;
using System.IO;
using Newtonsoft.Json;

public class GameConfig
{
    public int TileWidth { get; set; }
    public int TileHeight { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public float CameraSpeed { get; set; }
    public int NetworkLatencyThreshold { get; set; }
}

public class ConfigManager
{
    private static readonly string configFilePath = "config.json";
    private GameConfig cachedConfig;
    private DateTime lastLoadTime;

    public GameConfig GetConfig()
    {
        if (cachedConfig == null || DateTime.Now - lastLoadTime > TimeSpan.FromSeconds(60))
        {
            LoadConfig();
        }
        return cachedConfig;
    }

    private void LoadConfig()
    {
        string environment = Environment.GetEnvironmentVariable("GAME_ENVIRONMENT") ?? "development";
        string filePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, $"{environment}.json");

        if (File.Exists(filePath))
        {
            string json = File.ReadAllText(filePath);
            cachedConfig = JsonConvert.DeserializeObject<GameConfig>(json);
            lastLoadTime = DateTime.Now;
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found.");
        }
    }

    public void UpdateConfig(GameConfig newConfig)
    {
        string environment = Environment.GetEnvironmentVariable("GAME_ENVIRONMENT") ?? "development";
        string filePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, $"{environment}.json");

        if (File.Exists(filePath))
        {
            File.WriteAllText(filePath, JsonConvert.SerializeObject(newConfig));
            cachedConfig = newConfig;
            lastLoadTime = DateTime.Now;
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found.");
        }
    }

    public void AdjustConfigBasedOnNetworkLatency(int latency)
    {
        GameConfig config = GetConfig();
        if (latency > config.NetworkLatencyThreshold * 2)
        {
            // Reduce camera speed and increase tile dimensions for better performance
            config.CameraSpeed *= 0.8f;
            config.TileWidth += 10;
            config.TileHeight += 10;
        }
        else if (latency < config.NetworkLatencyThreshold / 2)
        {
            // Increase camera speed and decrease tile dimensions for smoother gameplay
            config.CameraSpeed *= 1.2f;
            config.TileWidth -= 5;
            config.TileHeight -= 5;
        }

        UpdateConfig(config);
    }
}
