angular.module('myApp').service('DialogRefreshService', ['$window', '$timeout', function($window, $timeout) {
    var service = this;

    service.refreshFields = function(fieldNames, resourceId, maxRetries, timeout) {
        var retries = 0;
        var intervalId;

        function refreshField(dialogWindow, fieldName) {
            if (dialogWindow && dialogWindow.scope && dialogWindow.scope[fieldName]) {
                try {
                    $window.parent.postMessage({ field: fieldName, value: dialogWindow.scope[fieldName] }, '*');
                } catch (e) {
                    console.error('Failed to send message to parent window:', e);
                }
            }
        }

        function checkDialogs() {
            var dialogs = angular.element('[ng-dialog]').scope().$children;
            for (var i = 0; i < dialogs.length; i++) {
                if (dialogs[i].resourceId === resourceId) {
                    fieldNames.forEach(function(fieldName) {
                        refreshField(dialogs[i], fieldName);
                    });
                }
            }

            retries++;
            if (retries < maxRetries) {
                $timeout(checkDialogs, timeout);
            } else {
                console.warn('Max retries reached for resource ID:', resourceId);
            }
        }

        intervalId = $timeout(checkDialogs, timeout);

        return function() {
            $timeout.cancel(intervalId);
        };
    };
}]);
