import os
import json
from typing import Dict
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

class ConfigManager:
    def __init__(self):
        self.config = {}
        self.service_discovery_client = ServiceDiscoveryClient()

    def load_config(self, environment: str) -> None:
        env_config_path = f"config/{environment}.json"
        with open(env_config_path, 'r') as file:
            self.config = json.load(file)

    def get_service_url(self, service_name: str) -> str:
        return self.service_discovery_client.get_service_url(service_name)

class ServiceDiscoveryClient:
    def __init__(self):
        self.session = requests.Session()
        retries = Retry(total=5, backoff_factor=1, status_forcelist=[ 502, 503, 504 ])
        self.session.mount('http://', HTTPAdapter(max_retries=retries))
        self.session.mount('https://', HTTPAdapter(max_retries=retries))

    def get_service_url(self, service_name: str) -> str:
        response = self.session.get(f"https://service-discovery-api.com/services/{service_name}")
        if response.status_code == 200:
            return response.json().get("url")
        else:
            raise Exception("Failed to retrieve service URL")

def main():
    environment = os.getenv('ENVIRONMENT', 'development')
    config_manager = ConfigManager()
    config_manager.load_config(environment)

    # Example usage
    service_url = config_manager.get_service_url("example-service")
    print(f"Service URL: {service_url}")

if __name__ == "__main__":
    main()
```

