use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use libc::{getrusage, RUSAGE_SELF, rusage};
use std::fs;
use std::path::Path;

fn get_resident_set_size() -> Option<usize> {
    unsafe {
        let mut usage = rusage { ..std::mem::zeroed() };
        if getrusage(RUSAGE_SELF, &mut usage) == 0 {
            Some((usage.ru_maxrss * 1024) as usize)
        } else {
            None
        }
    }
}

fn compile_with_custom_logging_hook() -> i32 {
    let start_time = Instant::now();
    let mut child = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("main.rs")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to start rustc");

    let stdout = child.stdout.take().unwrap();
    let stderr = child.stderr.take().unwrap();

    std::thread::spawn(move || {
        for line in std::io::BufReader::new(stdout).lines() {
            if let Ok(line) = line {
                println!("stdout: {}", line);
            }
        }
    });

    std::thread::spawn(move || {
        for line in std::io::BufReader::new(stderr).lines() {
            if let Ok(line) = line {
                eprintln!("stderr: {}", line);
            }
        }
    });

    while child.poll().is_none() {
        if let Some(rss) = get_resident_set_size() {
            println!("Current RSS: {} KB", rss);
        }
        std::thread::sleep(Duration::from_secs(1));
    }

    let exit_code = child.wait().expect("Failed to wait on rustc").code().unwrap();
    let duration = start_time.elapsed();

    println!("Compilation took {:?}", duration);

    exit_code
}

fn main() {
    let exit_code = compile_with_custom_logging_hook();
    std::process::exit(exit_code);
}
