class GameCharacter {
public:
    GameCharacter(int initialCooldown = 9) : cooldown(initialCooldown), nextAttackTime(std::chrono::system_clock::now()), paused(false) {}

    void setCooldown(int newCooldown) {
        if (newCooldown > MAX_COOLDOWN || newCooldown < MIN_COOLDOWN) return;
        std::lock_guard<std::mutex> lock(mutex);
        cooldown = newCooldown;
    }

    void pauseCooldown() {
        std::lock_guard<std::mutex> lock(mutex);
        paused = true;
    }

    void resumeCooldown() {
        std::lock_guard<std::mutex> lock(mutex);
        paused = false;
    }

    void attack() {
        std::lock_guard<std::mutex> lock(mutex);
        if (std::chrono::system_clock::now() >= nextAttackTime && !paused) {
            // Execute the selected attack strategy
            std::cout << "Attacking!" << std::endl;
            logAttack();
            nextAttackTime = std::chrono::system_clock::now() + std::chrono::seconds(cooldown);
        }
    }

private:
    static const int MIN_COOLDOWN = 3;
    static const int MAX_COOLDOWN = 30;
    int cooldown;
    std::chrono::time_point<std::chrono::system_clock> nextAttackTime;
    bool paused;
    std::mutex mutex;

    void logAttack() {
        std::ofstream logFile("attack_log.csv", std::ios_base::app);
        if (logFile.is_open()) {
            auto now = std::chrono::system_clock::now();
            logFile << std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count() << ","
                    << "Attack" << std::endl;
            logFile.close();
        }
    }
};

int main() {
    GameCharacter character1(9);
    GameCharacter character2(15);

    // Simulate game loop
    while (true) {
        character1.attack();
        character2.attack();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
```

