#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024

typedef struct USER_CONNECTION_RECORD_T {
    int userID;
    time_t lastConnectionTime;
    int failedLoginAttempts;
    int isActive;
} USER_CONNECTION_RECORD_T;

typedef struct NODE_T {
    USER_CONNECTION_RECORD_T data;
    struct NODE_T *next;
} NODE_T;

NODE_T* hashTable[HASH_TABLE_SIZE] = {NULL};

unsigned int hashFunction(int userID) {
    return userID % HASH_TABLE_SIZE;
}

void addUser(int userID, time_t lastConnectionTime, int failedLoginAttempts, int isActive) {
    unsigned int index = hashFunction(userID);
    NODE_T *newNode = (NODE_T *)malloc(sizeof(NODE_T));
    newNode->data.userID = userID;
    newNode->data.lastConnectionTime = lastConnectionTime;
    newNode->data.failedLoginAttempts = failedLoginAttempts;
    newNode->data.isActive = isActive;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
}

void updateUser(int userID, time_t lastConnectionTime, int failedLoginAttempts, int isActive) {
    unsigned int index = hashFunction(userID);
    NODE_T *current = hashTable[index];
    while (current != NULL) {
        if (current->data.userID == userID) {
            current->data.lastConnectionTime = lastConnectionTime;
            current->data.failedLoginAttempts = failedLoginAttempts;
            current->data.isActive = isActive;
            return;
        }
        current = current->next;
    }
}

USER_CONNECTION_RECORD_T* getUser(int userID) {
    unsigned int index = hashFunction(userID);
    NODE_T *current = hashTable[index];
    while (current != NULL) {
        if (current->data.userID == userID) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

void cleanUpInactiveUsers(time_t inactiveThreshold) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        NODE_T *current = hashTable[i];
        while (current != NULL) {
            if (!current->data.isActive && time(NULL) - current->data.lastConnectionTime > inactiveThreshold) {
                NODE_T *temp = current;
                current = current->next;
                free(temp);
            } else {
                current = current->next;
            }
        }
    }
}

int main() {
    // Example usage
    addUser(1, time(NULL), 0, 1);
    updateUser(1, time(NULL) + 3600, 1, 0);
    USER_CONNECTION_RECORD_T *userRecord = getUser(1);
    if (userRecord != NULL) {
        printf("User ID: %d\n", userRecord->userID);
        printf("Last Connection Time: %ld\n", userRecord->lastConnectionTime);
        printf("Failed Login Attempts: %d\n", userRecord->failedLoginAttempts);
        printf("Active: %d\n", userRecord->isActive);
    }
    cleanUpInactiveUsers(86400); // Clean up users inactive for more than 24 hours
    return 0;
}
