using System.Threading.Tasks;

public class ConfigLoader
{
    private static readonly object _lock = new object();
    private static ConfigLoader _instance;
    private byte[] _encryptedConfigData;

    private ConfigLoader(string filePath)
    {
        LoadEncryptedConfig(filePath);
    }

    public static ConfigLoader Instance(string filePath)
    {
        if (_instance == null)
        {
            lock (_lock)
            {
                if (_instance == null)
                {
                    _instance = new ConfigLoader(filePath);
                }
            }
        }
        return _instance;
    }

    private void LoadEncryptedConfig(string filePath)
    {
        try
        {
            using (FileStream fs = File.OpenRead(filePath))
            {
                byte[] encryptedData = new byte[fs.Length];
                fs.Read(encryptedData, 0, encryptedData.Length);
                _encryptedConfigData = encryptedData;
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to load encrypted config: {ex.Message}");
            throw;
        }
    }

    public T LoadConfig<T>(string key) where T : new()
    {
        try
        {
            byte[] decryptedData = Decrypt(_encryptedConfigData);
            string configJson = Encoding.UTF8.GetString(decryptedData);
            return Newtonsoft.Json.JsonConvert.DeserializeObject<T>(configJson);
        }
        catch (Exception ex)
        {
            LogError($"Failed to load config for key {key}: {ex.Message}");
            throw;
        }
    }

    public async Task<T> LoadConfigAsync<T>(string key) where T : new()
    {
        try
        {
            byte[] decryptedData = await DecryptAsync(_encryptedConfigData);
            string configJson = Encoding.UTF8.GetString(decryptedData);
            return Newtonsoft.Json.JsonConvert.DeserializeObject<T>(configJson);
        }
        catch (Exception ex)
        {
            LogError($"Failed to load config for key {key}: {ex.Message}");
            throw;
        }
    }

    private byte[] Decrypt(byte[] encryptedData)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = Encoding.UTF8.GetBytes("YourSecretKey123"); // Replace with actual key
            aes.IV = Encoding.UTF8.GetBytes("YourIVVector123");  // Replace with actual IV
            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using (MemoryStream ms = new MemoryStream(encryptedData))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    return cs.ToArray();
                }
            }
        }
    }

    private async Task<byte[]> DecryptAsync(byte[] encryptedData)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = Encoding.UTF8.GetBytes("YourSecretKey123"); // Replace with actual key
            aes.IV = Encoding.UTF8.GetBytes("YourIVVector123");  // Replace with actual IV
            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using (MemoryStream ms = new MemoryStream(encryptedData))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    return await ReadFullyAsync(cs);
                }
            }
        }
    }

    private static async Task<byte[]> ReadFullyAsync(Stream input)
    {
        byte[] buffer = new byte[16 * 1024];
        using (MemoryStream ms = new MemoryStream())
        {
            int read;
            while ((read = await input.ReadAsync(buffer, 0, buffer.Length)) != 0)
            {
                ms.Write(buffer, 0, read);
            }
            return ms.ToArray();
        }
    }

    private void LogError(string message)
    {
        // Implement logging mechanism here
        Console.WriteLine($"ERROR: {message}");
    }
