const fs = require('fs');
const path = require('path');
const axios = require('axios');
const crypto = require('crypto');

const cloudStorageServiceUrl = 'https://api.cloudstorage.com/upload';
const maxRetries = 3;
const retryDelay = 2000; // milliseconds
const cache = new Map();

async function uploadFile(file, targetDirectory) {
    const filePath = path.join(targetDirectory, file.name);
    const fileHash = crypto.createHash('sha256').update(fs.readFileSync(filePath)).digest('hex');

    if (cache.has(fileHash)) {
        return { url: cache.get(fileHash), verificationStatus: 'cached' };
    }

    let retries = 0;
    while (retries < maxRetries) {
        try {
            const formData = new FormData();
            formData.append('file', fs.createReadStream(filePath));
            formData.append('targetDirectory', targetDirectory);

            const response = await axios.post(cloudStorageServiceUrl, formData, {
                headers: {
                    ...formData.getHeaders(),
                    'Content-Type': 'multipart/form-data'
                }
            });

            if (response.data.url) {
                const verificationResponse = await axios.get(response.data.url);
                const verificationHash = crypto.createHash('sha256').update(verificationResponse.data).digest('hex');

                if (verificationHash === fileHash) {
                    cache.set(fileHash, response.data.url);
                    return { url: response.data.url, verificationStatus: 'success' };
                } else {
                    console.error(`File integrity check failed for ${file.name}`);
                }
            }

            break;
        } catch (error) {
            if (error.response && error.response.status === 429) {
                console.warn('Too many requests. Retrying after delay...');
                await new Promise(resolve => setTimeout(resolve, retryDelay));
                retries++;
            } else {
                console.error(`Upload failed for ${file.name}:`, error);
                break;
            }
        }
    }

    return { url: null, verificationStatus: 'failed' };
}
