import json
from abc import ABC, abstractmethod

class ConfigBase(ABC):
    _registry = {}

    @classmethod
    def register_factory(cls, module_id, factory_func):
        if module_id in cls._registry:
            raise ValueError(f"Module ID '{module_id}' already registered.")
        cls._registry[module_id] = factory_func

    @classmethod
    def create_instance(cls, module_id, *args, **kwargs):
        factory_func = cls._registry.get(module_id)
        if not factory_func:
            raise KeyError(f"No factory function registered for module ID '{module_id}'.")
        return factory_func(*args, **kwargs)

    @abstractmethod
    def serialize(self):
        pass

    @classmethod
    def deserialize(cls, json_data, validate=None):
        try:
            data = json.loads(json_data)
            if validate:
                validate(data)
            return cls(**data)
        except (json.JSONDecodeError, TypeError) as e:
            raise ValueError(f"Invalid JSON format or parameter validation failed: {e}")

class DatabaseConfig(ConfigBase):
    def __init__(self, host, port, user, password):
        self.host = host
        self.port = port
        self.user = user
        self.password = password

    def serialize(self):
        return json.dumps({
            'host': self.host,
            'port': self.port,
            'user': self.user,
            'password': self.password
        })

class LoggingConfig(ConfigBase):
    def __init__(self, level, file_path):
        self.level = level
        self.file_path = file_path

    def serialize(self):
        return json.dumps({
            'level': self.level,
            'file_path': self.file_path
        })

class ApiKeyConfig(ConfigBase):
    def __init__(self, key, secret):
        self.key = key
        self.secret = secret

    def serialize(self):
        return json.dumps({
            'key': self.key,
            'secret': self.secret
        })

# Example usage:
def validate_database_config(data):
    if not all(key in data for key in ['host', 'port', 'user', 'password']):
        raise ValueError("Database config must include host, port, user, and password.")

ConfigBase.register_factory('database', lambda *args, **kwargs: DatabaseConfig(*args, **kwargs))
ConfigBase.register_factory('logging', lambda *args, **kwargs: LoggingConfig(*args, **kwargs))
ConfigBase.register_factory('api_key', lambda *args, **kwargs: ApiKeyConfig(*args, **kwargs))

db_config = ConfigBase.create_instance('database', 'localhost', 5432, 'user', 'password')
logging_config = ConfigBase.create_instance('logging', 'INFO', '/var/log/app.log')
api_key_config = ConfigBase.create_instance('api_key', 'key123', 'secret456')

db_json = db_config.serialize()
logging_json = logging_config.serialize()
api_key_json = api_key_config.serialize()

print(ConfigBase.deserialize(db_json, validate_database_config))
print(ConfigBase.deserialize(logging_json))
print(ConfigBase.deserialize(api_key_json))
