#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int ci;
    int power_level;
} TX_POWER_REPORT_T;

typedef struct Node {
    TX_POWER_REPORT_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_entry(DynamicArray* array, TX_POWER_REPORT_T report) {
    pthread_mutex_lock(&array->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    new_node->data = report;
    new_node->next = array->head;
    array->head = new_node;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_entry(DynamicArray* array, int ci, TX_POWER_REPORT_T report) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    while (current != NULL) {
        if (current->data.ci == ci) {
            current->data = report;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);
    return -1;
}

TX_POWER_REPORT_T* get_latest_report(DynamicArray* array, int ci) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    TX_POWER_REPORT_T* latest_report = NULL;
    while (current != NULL) {
        if (current->data.ci == ci && (latest_report == NULL || current->data.timestamp > latest_report->timestamp)) {
            latest_report = &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);
    return latest_report;
}
