typedef struct {
    char* message;
    int index;
} dataItem;

dataItem* manageDataItems(int itemCount, const char* initMessage) {
    dataItem* items = (dataItem*)malloc(itemCount * sizeof(dataItem));
    if (items == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < itemCount; ++i) {
        items[i].message = (char*)malloc((strlen(initMessage) + 1) * sizeof(char));
        if (items[i].message == NULL) {
            fprintf(stderr, "Memory allocation failed for item %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(items[j].message);
            }
            free(items);
            return NULL;
        }
        strcpy(items[i].message, initMessage);
        items[i].index = i;
    }

    return items;
}

void freeDataItems(dataItem* items, int itemCount) {
    for (int i = 0; i < itemCount; ++i) {
        free(items[i].message);
    }
    free(items);
}

int main() {
    const char* initMessage = "Hello, World!";
    int itemCount = 5;
    dataItem* items = manageDataItems(itemCount, initMessage);

    if (items != NULL) {
        for (int i = 0; i < itemCount; ++i) {
            printf("Item %d: Message - %s, Index - %d\n", i, items[i].message, items[i].index);
        }
        freeDataItems(items, itemCount);
    }

    return 0;
}
