#include <time.h>

#define MAX_SIZE 1024

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    time_t timestamp;
    record* ref;
} summary;

record* create_records(int size) {
    if (size > MAX_SIZE) {
        fprintf(stderr, "Error: Size exceeds maximum limit.\n");
        return NULL;
    }
    record* records = malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 100;
    }
    return records;
}

summary* create_summaries(int size, record* records) {
    if (size > MAX_SIZE || !records) {
        fprintf(stderr, "Error: Invalid input.\n");
        return NULL;
    }
    summary* summaries = malloc(size * sizeof(summary));
    if (!summaries) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(records);
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        summaries[i].timestamp = time(NULL);
        summaries[i].ref = &records[hash_function(i)];
    }
    return summaries;
}

int hash_function(int key) {
    // Simple hash function
    return key % MAX_SIZE;
}

void serialize(record* records, summary* summaries, int size) {
    if (!records || !summaries) {
        fprintf(stderr, "Error: Null pointer encountered.\n");
        return;
    }
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for writing.\n");
        return;
    }
    fwrite(records, sizeof(record), size, file);
    fwrite(summaries, sizeof(summary), size, file);
    fclose(file);
}

void deserialize(record** records, summary** summaries, int* size) {
    FILE* file = fopen("data.bin", "rb");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for reading.\n");
        return;
    }
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    *size = file_size / (sizeof(record) + sizeof(summary));
    *records = malloc(*size * sizeof(record));
    *summaries = malloc(*size * sizeof(summary));
    if (!*records || !*summaries) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*records);
        free(*summaries);
        fclose(file);
        return;
    }
    fread(*records, sizeof(record), *size, file);
    fread(*summaries, sizeof(summary), *size, file);
    fclose(file);
}

void monitor_memory_usage() {
    // Placeholder for memory usage monitoring logic
    printf("Memory usage monitored.\n");
}

int main() {
    srand(time(NULL));
    int size = 512;
    record* records = create_records(size);
    summary* summaries = create_summaries(size, records);

    serialize(records, summaries, size);

    record* deserialized_records;
    summary* deserialized_summaries;
    int deserialized_size;
    deserialize(&deserialized_records, &deserialized_summaries, &deserialized_size);

    monitor_memory_usage();

    free(records);
    free(summaries);
    free(deserialized_records);
    free(deserialized_summaries);

    return 0;
}
