#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int packet_id;
    void* payload;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->packets = (DataPacket**)malloc(initial_capacity * sizeof(DataPacket*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->packets[i]->payload);
        free(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void add_packet(DynamicArray* array, DataPacket* packet) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        array->packets = (DataPacket**)realloc(array->packets, new_capacity * sizeof(DataPacket*));
        array->capacity = new_capacity;
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
}

void update_packet(DynamicArray* array, int packet_id, DataPacket* new_packet) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i]->packet_id == packet_id) {
            free(array->packets[i]->payload);
            *array->packets[i] = *new_packet;
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

DataPacket* get_packet(DynamicArray* array, int packet_id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i]->packet_id == packet_id) {
            DataPacket* result = array->packets[i];
            pthread_mutex_unlock(&array->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

