int initialize_data_structures(long *offsets, int *keys, record **records, long size, int min_value, int max_value) {
    if (size < 0) {
        return -1; // Invalid input size
    }

    offsets = (long *)malloc(size * sizeof(long));
    keys = (int *)malloc(size * sizeof(int));
    records = (record **)malloc(size * sizeof(record *));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (long i = 0; i < size; i++) {
        offsets[i] = i * 10; // Example offset calculation
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            for (long j = 0; j < i; j++) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            return -2; // Memory allocation failed
        }
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return 0; // Success
}

int main() {
    long size = 5;
    int min_value = 1, max_value = 100;
    long *offsets;
    int *keys;
