typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->elements[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicList *list, int index) {
    if (index < 0 || index >= list->count) {
        return NULL; // Invalid index
    }
    return list->elements[index];
}

int main() {
    DynamicList *list = create_dynamic_list();

    NFAPI_CRC_INDICATION_PDU_T element1 = {1, 2, 3};
    NFAPI_CRC_INDICATION_PDU_T element2 = {4, 5, 6};

    add_element(list, &element1);
    add_element(list, &element2);

    NFAPI_CRC_INDICATION_PDU_T *retrievedElement = get_element(list, 0);
    if (retrievedElement != NULL) {
        printf("Retrieved element: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               retrievedElement->RX_UE_INFORMATION_TAG,
               retrievedElement->RNTI,
               retrievedElement->CRCFLAG);
    }

    destroy_dynamic_list(list);

    return 0;
}
