    uint16_t RNTI;
    uint8_t tag_flag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaapi_crc_indication_list(int N) {
    if (N <= 0) {
        // Log error
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        // Log memory allocation failure
        return NULL;
    }

    long* offsets = (long*)calloc(N, sizeof(long));
    int* keys = (int*)calloc(N, sizeof(int));
    uint16_t* RNTIs = (uint16_t*)calloc(N, sizeof(uint16_t));
    uint8_t* tag_flags = (uint8_t*)calloc(N, sizeof(uint8_t));

    if (!offsets || !keys || !RNTIs || !tag_flags) {
        // Log memory allocation failure
        free(list);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        while (1) {
            offsets[i] = rand() % 1000000L; // Example range
            if (offsets[i] >= 0 && offsets[i] <= 999999L) break;
        }

        keys[i] = rand() % 1000 + 1; // Example range
        RNTIs[i] = rand() % 65535 + 1; // Example range
        tag_flags[i] = rand() % 2;

        list[i].offset = offsets[i];
        list[i].key = keys[i];
        list[i].RNTI = RNTIs[i];
        list[i].tag_flag = tag_flags[i];

        // Log successful allocation and initialization
    }

    free(offsets);
    free(keys);
    free(RNTIs);
    free(tag_flags);

    return list;
}
