use std::fs::{self, DirBuilder};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use log::{info, error, warn};
use tokio::sync::mpsc;
use tokio::task;

#[derive(Clone)]
struct Config {
    alternative_dir_path: Option<String>,
    log_level: LogLevel,
}

enum LogLevel {
    Debug,
    Info,
    Warn,
    Error,
}

struct DirectoryManager {
    config: Arc<Mutex<Config>>,
    notification_service: NotificationService,
}

impl DirectoryManager {
    fn new(config: Config, notification_service: NotificationService) -> Self {
        DirectoryManager {
            config: Arc::new(Mutex::new(config)),
            notification_service,
        }
    }

    async fn create_directory(&self, name: &str) -> Result<(), String> {
        let mut config = self.config.lock().unwrap();
        let dir_path = if let Some(path) = &config.alternative_dir_path {
            Path::new(path).join(name)
        } else {
            Path::new("/default/path").join(name)
        };

        if dir_path.exists() {
            return Err(format!("Directory {} already exists", dir_path.display()));
        }

        let mut builder = DirBuilder::new();
        builder.mode(0o755);
        builder.recursive(true);

        match builder.create(&dir_path) {
            Ok(_) => {
                info!("Created directory: {}", dir_path.display());
                config.alternative_dir_path = Some(dir_path.to_string_lossy().to_string());
                Ok(())
            }
            Err(e) => {
                error!("Failed to create directory {}: {:?}", dir_path.display(), e);
                self.handle_failure(&dir_path, &e).await;
                Err(format!("Failed to create directory: {}", e))
            }
        }
    }

    async fn handle_failure(&self, dir_path: &Path, err: &std::io::Error) {
        let mut attempts = 0;
        loop {
            if attempts >= 3 {
                self.notify_failure(dir_path, err).await;
                break;
            }

            tokio::time::sleep(Duration::from_secs(2u64.pow(attempts))).await;
            match fs::create_dir_all(dir_path) {
                Ok(_) => {
                    info!("Created directory after retry: {}", dir_path.display());
                    break;
                }
                Err(e) => {
                    error!("Failed to create directory after retry {}: {:?}", dir_path.display(), e);
                    attempts += 1;
                }
            }
        }
    }

    async fn notify_failure(&self, dir_path: &Path, err: &std::io::Error) {
        // Implement notification logic here
        warn!("Notification sent for failed directory creation: {} - {}", dir_path.display(), err);
    }
}

struct NotificationService;

impl NotificationService {
    async fn send_notification(&self, message: String) {
        // Implement notification sending logic here
        info!("Sending notification: {}", message);
    }
}

#[tokio::main]
async fn main() {
    let config = Config {
        alternative_dir_path: None,
        log_level: LogLevel::Info,
    };
    let notification_service = NotificationService;
    let manager = DirectoryManager::new(config, notification_service);

    if let Err(e) = manager.create_directory("test_directory").await {
        error!("Error creating directory: {}", e);
    }
}
```

