#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct Record {
    int value;
} Record;

typedef struct DynamicCollection {
    Record* records;
    size_t capacity;
    size_t size;
    size_t memory_budget_kb;
    pthread_mutex_t mutex;
} DynamicCollection;

DynamicCollection* create_collection(size_t memory_budget_kb) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    collection->records = (Record*)malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!collection->records) {
        free(collection);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    collection->memory_budget_kb = memory_budget_kb * 1024; // Convert to bytes
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_record(DynamicCollection* collection, int value) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * GROWTH_FACTOR;
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    collection->records[collection->size].value = value;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

