#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_SIZE 1000
#define REALLOC_CHUNK 16

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    char log[MAX_LOG_SIZE][256];
    size_t log_count;
} CRCManager;

CRCManager* create_crc_manager() {
    CRCManager *manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) return NULL;
    manager->entries = NULL;
    manager->count = 0;
    manager->capacity = 0;
    manager->log_count = 0;
    return manager;
}

void free_crc_manager(CRCManager *manager) {
    if (manager->entries) free(manager->entries);
    free(manager);
}

int add_entry(CRCManager *manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity + REALLOC_CHUNK;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(manager->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) return -1; // Memory allocation failed
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }
    manager->entries[manager->count++] = entry;
    snprintf(manager->log[manager->log_count], sizeof(manager->log[manager->log_count]), "Added entry with RNTI %d", entry.RNTI);
    if (++manager->log_count >= MAX_LOG_SIZE) manager->log_count = 0; // Overwrite oldest log entry
    return 0;
}

int update_entry(CRCManager *manager, int rnti, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].RNTI == rnti) {
            manager->entries[i] = new_entry;
            snprintf(manager->log[manager->log_count], sizeof(manager->log[manager->log_count]), "Updated entry with RNTI %d", rnti);
            if (++manager->log_count >= MAX_LOG_SIZE) manager->log_count = 0; // Overwrite oldest log entry
            return 0;
        }
    }
    return -1; // Entry not found
}

int remove_entry(CRCManager *manager, int rnti) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].RNTI == rnti) {
            memmove(&manager->entries[i], &manager->entries[i + 1], (manager->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            manager->count--;
            snprintf(manager->log[manager->log_count], sizeof(manager->log[manager->log_count]), "Removed entry with RNTI %d", rnti);
            if (++manager->log_count >= MAX_LOG_SIZE) manager->log_count = 0; // Overwrite oldest log entry
            return 0;
        }
    }
    return -1; // Entry not found
}

int export_to_file(CRCManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t total_size = manager->count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (fwrite(&total_size, sizeof(size_t), 1, file) != 1 ||
        fwrite(manager->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->count, file) != manager->count) {
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}
