#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offsets;
    int *keys;
} record;

typedef struct {
    record **records;
    size_t size;
    pthread_mutex_t lock;
} record_manager;

record_manager* create_record_manager(size_t initial_size) {
    record_manager *rm = (record_manager*)malloc(sizeof(record_manager));
    if (!rm) return NULL;

    rm->size = initial_size;
    rm->records = (record**)calloc(initial_size, sizeof(record*));
    if (!rm->records) {
        free(rm);
        return NULL;
    }

    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

void destroy_record_manager(record_manager *rm) {
    for (size_t i = 0; i < rm->size; ++i) {
        if (rm->records[i]) {
            free(rm->records[i]->offsets);
            free(rm->records[i]->keys);
            free(rm->records[i]);
        }
    }
    free(rm->records);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}

size_t hash_function(int key, size_t table_size) {
    return (key * 31) % table_size;
}

int add_record(record_manager *rm, int key, long offset) {
    pthread_mutex_lock(&rm->lock);

    if (rm->size == 0) {
        fprintf(stderr, "Record manager is empty.\n");
        pthread_mutex_unlock(&rm->lock);
        return -1;
    }

    size_t index = hash_function(key, rm->size);
    while (rm->records[index]) {
        if (rm->records[index]->key == key) {
            fprintf(stderr, "Key already exists.\n");
            pthread_mutex_unlock(&rm->lock);
            return -1;
        }
        index = (index + 1) % rm->size;
    }

    record *r = (record*)malloc(sizeof(record));
    if (!r) {
        pthread_mutex_unlock(&rm->lock);
        return -1;
    }

    r->value = key;
    r->offsets = (long*)malloc(sizeof(long));
    if (!r->offsets) {
        free(r);
        pthread_mutex_unlock(&rm->lock);
        return -1;
    }
    *r->offsets = offset;

    r->keys = (int*)malloc(sizeof(int));
    if (!r->keys) {
        free(r->offsets);
        free(r);
        pthread_mutex_unlock(&rm->lock);
        return -1;
    }
    *r->keys = key;

    rm->records[index] = r;

    pthread_mutex_unlock(&rm->lock);
    return 0;
}

record* get_record(record_manager *rm, int key) {
    pthread_mutex_lock(&rm->lock);

    size_t index = hash_function(key, rm->size);
    while (rm->records[index]) {
        if (rm->records[index]->key == key) {
            record *r = rm->records[index];
            pthread_mutex_unlock(&rm->lock);
            return r;
        }
        index = (index + 1) % rm->size;
    }

    pthread_mutex_unlock(&rm->lock);
    return NULL;
}

int resize_record_manager(record_manager *rm, size_t new_size) {
    record **new_records = (record**)calloc(new_size, sizeof(record*));
    if (!new_records) return -1;

    for (size_t i = 0; i < rm->size; ++i) {
        if (rm->records[i]) {
            size_t index = hash_function(rm->records[i]->key, new_size);
            while (new_records[index]) {
                index = (index + 1) % new_size;
            }
            new_records[index] = rm->records[i];
        }
    }

    free(rm->records);
    rm->records = new_records;
    rm->size = new_size;

    return 0;
}
