#define MAX_SHAPES 10000000
#define INITIAL_CAPACITY 100

typedef enum { CIRCLE, RECTANGLE, TRIANGLE } ShapeType;

typedef struct {
    ShapeType type;
    union {
        struct {
            double radius;
        } circle;
        struct {
            double width, height;
        } rectangle;
        struct {
            double base, height;
        } triangle;
    };
    int id;
} Shape;

typedef struct {
    Shape *shapes;
    size_t count;
    size_t capacity;
    size_t memory_limit_mb;
} ShapeCollection;

void init_shape_collection(ShapeCollection *collection, size_t initial_capacity, size_t memory_limit_mb) {
    collection->shapes = (Shape *)malloc(initial_capacity * sizeof(Shape));
    if (!collection->shapes) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->memory_limit_mb = memory_limit_mb * 1024 * 1024; // Convert MB to bytes
}

void resize_shape_collection(ShapeCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    Shape *new_shapes = (Shape *)realloc(collection->shapes, new_capacity * sizeof(Shape));
    if (!new_shapes) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->shapes = new_shapes;
    collection->capacity = new_capacity;
}

void add_random_shape(ShapeCollection *collection) {
    if (collection->count >= collection->capacity) {
        resize_shape_collection(collection);
    }

    Shape *shape = &collection->shapes[collection->count++];
    shape->id = collection->count;

    switch ((rand() % 3)) {
        case CIRCLE:
            shape->type = CIRCLE;
            shape->circle.radius = (double)(rand() % 100) / 10.0; // Random radius between 0 and 10
            break;
        case RECTANGLE:
            shape->type = RECTANGLE;
            shape->rectangle.width = (double)(rand() % 100) / 10.0; // Random width between 0 and 10
            shape->rectangle.height = (double)(rand() % 100) / 10.0; // Random height between 0 and 10
            break;
        case TRIANGLE:
            shape->type = TRIANGLE;
            shape->triangle.base = (double)(rand() % 100) / 10.0; // Random base between 0 and 10
            shape->triangle.height = (double)(rand() % 100) / 10.0; // Random height between 0 and 10
            break;
    }
}

void load_shapes_from_file(ShapeCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    Shape shape;
    while (fscanf(file, "%d %d", &shape.id, &shape.type) == 2) {
        switch (shape.type) {
            case CIRCLE:
                fscanf(file, " %lf", &shape.circle.radius);
                break;
            case RECTANGLE:
                fscanf(file, " %lf %lf", &shape.rectangle.width, &shape.rectangle.height);
                break;
            case TRIANGLE:
                fscanf(file, " %lf %lf", &shape.triangle.base, &shape.triangle.height);
                break;
        }

        if (collection->count >= collection->capacity) {
            resize_shape_collection(collection);
        }
        collection->shapes[collection->count++] = shape;
    }

    fclose(file);
}

void serialize_shapes_to_file(const ShapeCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        fprintf(file, "%d %d ", collection->shapes[i].id, collection->shapes[i].type);
        switch (collection->shapes[i].type) {
            case CIRCLE:
                fprintf(file, "%.2f\n", collection->shapes[i].circle.radius);
                break;
            case RECTANGLE:
                fprintf(file, "%.2f %.2f\n", collection->shapes[i].rectangle.width, collection->shapes[i].rectangle.height);
                break;
            case TRIANGLE:
                fprintf(file, "%.2f %.2f\n", collection->shapes[i].triangle.base, collection->shapes[i].triangle.height);
                break;
        }
    }

    fclose(file);
}

void free_shape_collection(ShapeCollection *collection) {
    free(collection->shapes);
}
