    long *offsets = (long *)malloc(N * sizeof(long));
    int *keys = (int *)malloc(N * sizeof(int));
    short *indices = (short *)malloc(N * sizeof(short));

    if (!offsets || !keys || !indices) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_arrays(N, offsets, keys, indices);

    for (int i = 0; i < N; i++) {
        log_memory_allocation(offsets[i]);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(indices);

    return 0;
}
