['```csharp
using System;

public class DynamicRandomGenerator
{
    private double minValue;
    private double maxValue;

    public DynamicRandomGenerator(double minValue, double maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public double GetRandomDouble()
    {
        return minValue + (maxValue - minValue) * Random.Shared.NextDouble();
    }

    public int GetRandomInt()
    {
        return (int)Math.Floor(minValue) + (int)Math.Ceiling(maxValue - minValue);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue == maxValue)
            throw new ArgumentException("Min value cannot equal max value for exclusive random integer.");
        return (int)Math.Floor(minValue) + 1 + (int)Math.Ceiling(maxValue - minValue - 2);
    }

    public double GetRandomWeightedValue(double[] weights)
    {
        if (weights.Length == 0)
            throw new ArgumentException("Weights array cannot be empty.");
        double totalWeight = 0;
        foreach (var weight in weights)
        {
            if (weight < 0)
                throw new ArgumentException("Weights must be non-negative.");
            totalWeight += weight;
        }
        double randomValue = Random.Shared.NextDouble() * totalWeight;
        double cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return minValue + (maxValue - minValue) * i / (weights.Length - 1);
        }
        throw new InvalidOperationException("Failed to generate weighted random value.");
    }

    public int GetRandomWeightedInt(int[] weights)
    {
        if (weights.Length == 0)
            throw new ArgumentException("Weights array cannot be empty.");
        double totalWeight = 0;
        foreach (var weight in weights)
        {
            if (weight < 0)
                throw new ArgumentException("Weights must be non-negative.");
            totalWeight += weight;
        }
        double randomValue = Random.Shared.NextDouble() * totalWeight;
        double cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return minValue + i;
        }
        throw new InvalidOperationException("Failed to generate weighted random integer.");
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }
}
