#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_OFFSET_SIZE 1000
#define MAX_KEY_SIZE 1000
#define HASH_RANGE 10000

typedef struct {
    int value;
} record;

int custom_hash(int key) {
    // Simple hash function for demonstration purposes
    return (key * 31) % HASH_RANGE;
}

void process_data(int* offset, int* key, int size) {
    if (size > MAX_OFFSET_SIZE || size > MAX_KEY_SIZE) {
        fprintf(stderr, "Error: Size exceeds maximum limit.\n");
        return;
    }

    long* offset_array = malloc(size * sizeof(long));
    int* key_array = malloc(size * sizeof(int));
    record* record_array = NULL;

    if (!offset_array || !key_array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Initialize offset and key arrays
    for (int i = 0; i < size; i++) {
        offset_array[i] = offset[i];
        key_array[i] = key[i];
    }

    int valid_keys = 0;
    for (int i = 0; i < size; i++) {
        if (key_array[i] != 0) {
            valid_keys++;
        }
    }

    // Pre-allocate memory for record array
    record_array = malloc(valid_keys * sizeof(record));
    if (!record_array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Initialize record array with hash values
    for (int i = 0, j = 0; i < size; i++) {
        if (key_array[i] != 0) {
            record_array[j].value = custom_hash(key_array[i]);
            j++;
        }
    }

    // Free allocated memory
    free(offset_array);
    free(key_array);
    free(record_array);
}

int main() {
    int offset[] = {1, 2, 3, 4, 5};
    int key[] = {10, 20, 30, 0, 50};

    process_data(offset, key, sizeof(key) / sizeof(key[0]));

    return 0;
}
```

This code snippet demonstrates a function `process_data` that dynamically allocates memory for 'long' offset values and 'int' keys arrays, initializes an array of 'record' structures with hash values, and frees all allocated memory upon completion. It includes error handling for size limits and memory allocation failures. The function assumes the existence of a custom hash function `custom_hash`.']

