    if (!array->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

void add_record(RecordArray *array, int key, double weight) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->records = (Record *)realloc(array->records, array->capacity * sizeof(Record));
        if (!array->records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
