    Record new_record;
    new_record.offset = hash_function((const char *)&key); // Placeholder
    new_record.key = key;
    new_record.weight = weight;
    array->records[array->size++] = new_record;
    pthread_mutex_unlock(&array->lock);
}

void free_record_array(RecordArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->records);
    pthread_mutex_destroy(&array->lock);
}

