#define MAX_ITEMS 100000
#define REPORT_INTERVAL 60 // seconds

typedef struct {
    int item_id;
    int quantity;
    float price;
} ORDER_ITEM_T;

typedef struct {
    ORDER_ITEM_T items[MAX_ITEMS];
    int count;
    pthread_mutex_t lock;
} ITEM_LIST_T;

ITEM_LIST_T *item_list = NULL;

void init_item_list() {
    item_list = (ITEM_LIST_T *)malloc(sizeof(ITEM_LIST_T));
    if (!item_list) {
        fprintf(stderr, "Failed to allocate memory for item list\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&item_list->lock, NULL);
    item_list->count = 0;
}

void insert_item(int item_id, int quantity, float price) {
    pthread_mutex_lock(&item_list->lock);
    if (item_list->count >= MAX_ITEMS) {
        fprintf(stderr, "Item list is full\n");
        pthread_mutex_unlock(&item_list->lock);
        return;
    }
    item_list->items[item_list->count].item_id = item_id;
    item_list->items[item_list->count].quantity = quantity;
    item_list->items[item_list->count].price = price;
    item_list->count++;
    pthread_mutex_unlock(&item_list->lock);
}

void delete_item(int item_id) {
    pthread_mutex_lock(&item_list->lock);
    for (int i = 0; i < item_list->count; i++) {
        if (item_list->items[i].item_id == item_id) {
            for (int j = i; j < item_list->count - 1; j++) {
                item_list->items[j] = item_list->items[j + 1];
            }
            item_list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&item_list->lock);
}

ORDER_ITEM_T *get_item(int item_id) {
    pthread_mutex_lock(&item_list->lock);
    for (int i = 0; i < item_list->count; i++) {
        if (item_list->items[i].item_id == item_id) {
            pthread_mutex_unlock(&item_list->lock);
            return &item_list->items[i];
        }
    }
    pthread_mutex_unlock(&item_list->lock);
    return NULL;
}

