#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MEMORY_THRESHOLD (1024 * 1024) // 1 MB

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    pthread_mutex_t mutex;
    size_t total_memory_used;
} RecordCollection;

int initialize_collection(RecordCollection *collection) {
    collection->count = 0;
    collection->total_memory_used = 0;
    if (pthread_mutex_init(&collection->mutex, NULL) != 0) {
        return -1; // Mutex initialization failed
    }
    return 0;
}

void destroy_collection(RecordCollection *collection) {
    pthread_mutex_destroy(&collection->mutex);
}

int add_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= MAX_RECORDS || collection->total_memory_used + sizeof(Record) > MEMORY_THRESHOLD) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Collection is full or memory threshold exceeded
    }

    Record *new_record = &collection->records[collection->count];
    new_record->key = key;
    new_record->offset = offset;

    collection->total_memory_used += sizeof(Record);
    collection->count++;

    pthread_mutex_unlock(&collection->mutex);
    return 0; // Success
}

int remove_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);

    for (int i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            for (int j = i; j < collection->count - 1; j++) {
                collection->records[j] = collection->records[j + 1];
            }
            collection->total_memory_used -= sizeof(Record);
            collection->count--;
            pthread_mutex_unlock(&collection->mutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return -1; // Record not found
}

int main() {
    RecordCollection collection;
    if (initialize_collection(&collection) != 0) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return EXIT_FAILURE;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % 1000;
        long offset = rand() % MEMORY_THRESHOLD;
        if (add_record(&collection, key, offset) != 0) {
            fprintf(stderr, "Failed to add record with key %d\n", key);
            break;
        }
    }

    destroy_collection(&collection);
    return EXIT_SUCCESS;
}
