#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRC_INDICATION_REL8_TAG; }
#define MAX_ARRAY_SIZE 1024

NFAPI_CRC_INDICATION_PDU_T *array;
int array_size = 0;
pthread_mutex_t mutex;

void init_array(int N) {
    pthread_mutex_lock(&mutex);
    if (array != NULL) free(array);
    array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    array_size = N;
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = rand() % 1024;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }
    pthread_mutex_unlock(&mutex);
}

void update_crc_flag(int index, int new_value) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < array_size) {
        array[index].CRC_INDICATION_REL8_TAG = new_value;
    } else {
        fprintf(stderr, "Invalid index\n");
    }
    pthread_mutex_unlock(&mutex);
}

void *log_thread(void *arg) {
    while (1) {
        for (int i = 0; i < array_size; i++) {
            printf("Timestamp: %ld, Updated Value: %d, Index: %d\n", time(NULL), array[i].CRC_INDICATION_REL8_TAG, i);
        }
        sleep(1);
    }
}

void compact_array() {
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array, array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(1);
    }
    array = new_array;
    pthread_mutex_unlock(&mutex);
}

int get_last_n_updates(int n) {
    pthread_mutex_lock(&mutex);
    int count = 0;
    for (int i = array_size - 1; i >= 0 && count < n; i--) {
        printf("Index: %d, CRCFLAG: %d\n", i, array[i].CRC_INDICATION_REL8_TAG);
        count++;
    }
    pthread_mutex_unlock(&mutex);
    return count;
}

int main() {
    init_array(MAX_ARRAY_SIZE);
    pthread_t log_tid;
    pthread_create(&log_tid, NULL, log_thread, NULL);

    // Simulate updates
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        update_crc_flag(i, rand() % 256);
    }

    compact_array();
    get_last_n_updates(10);

    pthread_join(log_tid, NULL);
    free(array);
    return 0;
}
