#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int packetID;
    size_t payloadLength;
    int priorityScore;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
}

void addPacket(LinkedList* list, DataPacket packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->data = packet;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
}

void updatePacket(LinkedList* list, int packetID, DataPacket newPacket) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.packetID == packetID) {
            current->data = newPacket;
            return;
        }
        current = current->next;
    }
}

Node* getPacketByTimestampRange(LinkedList* list, time_t start, time_t end) {
    Node* resultHead = NULL;
    Node* resultTail = NULL;

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.timestamp >= start && current->data.timestamp <= end) {
            Node* newNode = (Node*)malloc(sizeof(Node));
            if (newNode == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                return resultHead;
            }
            newNode->data = current->data;
            newNode->next = NULL;

            if (resultHead == NULL) {
                resultHead = newNode;
                resultTail = newNode;
            } else {
                resultTail->next = newNode;
                resultTail = newNode;
            }
        }
        current = current->next;
    }

    return resultHead;
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
}
