#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct record {
    long offset;
    int key;
    float value;
    struct record *next;
} Record;

typedef struct {
    Record **pool;
    size_t pool_size;
    size_t used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (Record**)malloc(size * sizeof(Record*));
    mp->pool_size = size;
    mp->used = 0;
    return mp;
}

Record* allocate_record(MemoryPool *mp) {
    if (mp->used >= mp->pool_size) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(EXIT_FAILURE);
    }
    Record *r = (Record*)malloc(sizeof(Record));
    mp->pool[mp->used++] = r;
    return r;
}

void free_record(MemoryPool *mp, Record *r) {
    for (size_t i = 0; i < mp->used; ++i) {
        if (mp->pool[i] == r) {
            mp->pool[i] = NULL;
            break;
        }
    }
    free(r);
}

void insert_record(Record **head, Record *new_record) {
    new_record->next = *head;
    *head = new_record;
}

void delete_record(Record **head, int key) {
    Record *current = *head;
    Record *previous = NULL;

    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Key not found

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    free_record(mp, current);
}

void traverse_records(Record *head) {
    Record *current = head;
    while (current != NULL) {
        printf("Offset: %ld, Key: %d, Value: %.2f\n", current->offset, current->key, current->value);
        current = current->next;
    }
}

void serialize_records(Record *head, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    Record *current = head;
    while (current != NULL) {
        if (fwrite(&current->offset, sizeof(long), 1, file) != 1 ||
            fwrite(&current->key, sizeof(int), 1, file) != 1 ||
            fwrite(&current->value, sizeof(float), 1, file) != 1) {
            perror("Failed to write data to file");
            fclose(file);
            return;
        }
        current = current->next;
    }

    fclose(file);
}

Record* deserialize_records(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    Record *head = NULL;

    while (1) {
        Record *new_record = allocate_record(mp);
        if (fread(&new_record->offset, sizeof(long), 1, file) != 1 ||
            fread(&new_record->key, sizeof(int), 1, file) != 1 ||
            fread(&new_record->value, sizeof(float), 1, file) != 1) {
            free_record(mp, new_record);
            break;
        }
        insert_record(&head, new_record);
    }

    fclose(file);
    return head;
}

void log_operation(const char *operation, int result) {
    printf("Operation: %s, Result: %d\n", operation, result);
}
