#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 100

typedef struct StringNode {
    char* data;
    struct StringNode* next;
} StringNode;

typedef struct TreeNode {
    double value;
    StringNode* stringList;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

typedef struct CMSConfig {
    int maxDepth;
    // Add other configuration parameters here
} CMSConfig;

TreeNode* createTreeNode(double value) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node->value = value;
    node->stringList = NULL;
    node->left = NULL;
    node->right = NULL;
    return node;
}

StringNode* createStringNode(const char* data) {
    StringNode* node = (StringNode*)malloc(sizeof(StringNode));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node->data = strdup(data);
    node->next = NULL;
    return node;
}

void freeTreeNode(TreeNode* node) {
    if (node != NULL) {
        StringNode* current = node->stringList;
        while (current != NULL) {
            StringNode* next = current->next;
            free(current->data);
            free(current);
            current = next;
        }
        freeTreeNode(node->left);
        freeTreeNode(node->right);
        free(node);
    }
}

void populateStringList(StringNode** list, int minLen, int maxLen) {
    srand(time(NULL));
    for (int i = 0; i < rand() % (maxLen - minLen + 1) + minLen; i++) {
        char* str = (char*)malloc((rand() % (MAX_STRING_LENGTH - 2) + 3) * sizeof(char));
        if (str == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        for (int j = 0; j < strlen(str); j++) {
            str[j] = 'a' + rand() % 26;
        }
        StringNode* newNode = createStringNode(str);
        newNode->next = *list;
        *list = newNode;
    }
}

void traverseAndPopulate(TreeNode* node, CMSConfig* config, int currentDepth) {
    if (node == NULL || currentDepth > config->maxDepth) {
        return;
    }
    populateStringList(&node->stringList, 1, 5);
    traverseAndPopulate(node->left, config, currentDepth + 1);
    traverseAndPopulate(node->right, config, currentDepth + 1);
}

int main() {
    CMSConfig config = {3};
    TreeNode* root = createTreeNode(42.0);
    root->left = createTreeNode(17.5);
    root->right = createTreeNode(89.3);

    traverseAndPopulate(root, &config, 0);

    freeTreeNode(root);

    return 0;
}
