#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Item {
    char key[11];
    long timestamp;
    double value;
    struct Item* next;
} Item;

typedef struct LinkedList {
    Item* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

Item* create_item(const char* key, long timestamp, double value) {
    Item* item = (Item*)malloc(sizeof(Item));
    if (!item) return NULL;
    strncpy(item->key, key, 10);
    item->timestamp = timestamp;
    item->value = value;
    item->next = NULL;
    return item;
}

void insert_item(LinkedList* list, const char* key, long timestamp, double value) {
    pthread_mutex_lock(&list->lock);
    Item* new_item = create_item(key, timestamp, value);
    if (!new_item) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_item->next = list->head;
    list->head = new_item;
    pthread_mutex_unlock(&list->lock);
}

Item* search_item(LinkedList* list, const char* key) {
    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void free_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current != NULL) {
        Item* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
