}

u_char *resolveHostname(const char *hostname) {
    u_char *ip = (u_char *)malloc(4);
    if (!ip) {
        perror("Memory allocation failed");
        return NULL;
    }

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        free(ip);
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &(ipv4->sin_addr), 4);
        break;
    }

    freeaddrinfo(res);
    return ip;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file_path>\n", argv[0]);
        return 1;
    }

    manageLogProcessing(argv[1]);

    // Initialize DNS cache
    dns_cache = (dns_cache_entry *)malloc(DNS_CACHE_SIZE * sizeof(dns_cache_entry));
    if (!dns_cache) {
        perror("Memory allocation failed");
        return 1;
    }
    memset(dns_cache, 0, DNS_CACHE_SIZE * sizeof(dns_cache_entry));

    // Example usage of resolveHostname
    u_char *ip = resolveHostname("example.com");
    if (ip) {
        printf("IP address: %d.%d.%d.%d\n", ip[0], ip[1], ip[2], ip[3]);
        free(ip);
    }

    free(dns_cache);
    return 0;
}
