#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NetworkSession {
    char session_id[20];
    char *client_ips;
    int client_count;
    time_t start_time;
    time_t last_activity;
} NetworkSession;

typedef struct SessionManager {
    NetworkSession **sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    time_t timeout;
} SessionManager;

SessionManager* create_session_manager(size_t initial_capacity, time_t timeout) {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->sessions = (NetworkSession**)calloc(initial_capacity, sizeof(NetworkSession*));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->timeout = timeout;
    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]->client_ips);
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_session(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = (NetworkSession**)realloc(manager->sessions, manager->capacity * sizeof(NetworkSession*));
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void update_session(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->session_id, session->session_id) == 0) {
            free(manager->sessions[i]->client_ips);
            manager->sessions[i] = session;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

NetworkSession* get_session(SessionManager *manager, const char *session_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->session_id, session_id) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return manager->sessions[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void disconnect_client(SessionManager *manager, const char *session_id, const char *client_ip) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->session_id, session_id) == 0) {
            for (int j = 0; j < manager->sessions[i]->client_count; ++j) {
                if (strcmp(manager->sessions[i]->client_ips + j * 16, client_ip) == 0) {
                    // Remove the client IP from the list
                    memmove(manager->sessions[i]->client_ips + j * 16, manager->sessions[i]->client_ips + (j + 1) * 16, (manager->sessions[i]->client_count - j - 1) * 16);
                    manager->sessions[i]->client_count--;
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void close_inactive_sessions(SessionManager *manager) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (current_time - manager->sessions[i]->last_activity > manager->timeout) {
            // Close the session
            free(manager->sessions[i]->client_ips);
            free(manager->sessions[i]);
            memmove(manager->sessions + i, manager->sessions + i + 1, (manager->count - i - 1) * sizeof(NetworkSession*));
            manager->count--;
            i--; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void export_session_statistics(SessionManager *manager, FILE *output_file) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        fprintf(output_file, "Session ID: %s\n", manager->sessions[i]->session_id);
        fprintf(output_file, "Client IPs: ");
        for (int j = 0; j < manager->sessions[i]->client_count; ++j) {
            fprintf(output_file, "%s ", manager->sessions[i]->client_ips + j * 16);
        }
        fprintf(output_file, "\nDuration: %ld seconds\n", time(NULL) - manager->sessions[i]->start_time);
        fprintf(output_file, "Last Activity: %ld\n", manager->sessions[i]->last_activity);
    }
    pthread_mutex_unlock(&manager->lock);
}
