#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    float temperature;
    char *condition;
} weatherData;

weatherData* allocateWeatherData(int count) {
    return (weatherData*)malloc(count * sizeof(weatherData));
}

void freeWeatherData(weatherData* data, int count) {
    for (int i = 0; i < count; i++) {
        free(data[i].condition);
    }
    free(data);
}

void generateRandomWeather(weatherData* data, int count, float minTemp, float maxTemp) {
    srand(time(NULL));
    const char *conditions[] = {"Sunny", "Cloudy", "Rainy", "Snowy"};
    for (int i = 0; i < count; i++) {
        data[i].timestamp = time(NULL);
        data[i].temperature = minTemp + (float)rand() / RAND_MAX * (maxTemp - minTemp);
        int conditionIndex = rand() % 4;
        data[i].condition = strdup(conditions[conditionIndex]);
    }
}

void updateWeatherData(weatherData* data, int count, float newTemperature, char* newCondition) {
    for (int i = 0; i < count; i++) {
        data[i].temperature = newTemperature;
        free(data[i].condition);
        data[i].condition = strdup(newCondition);
    }
}

void printWeatherData(weatherData* data, int count) {
    for (int i = 0; i < count; i++) {
        printf("Timestamp: %s, Temperature: %.2f°C, Condition: %s\n", ctime(&data[i].timestamp), data[i].temperature, data[i].condition);
    }
}

int main() {
    int count = 5;
    weatherData* weather = allocateWeatherData(count);

    generateRandomWeather(weather, count, -10.0, 40.0);
    printWeatherData(weather, count);

    updateWeatherData(weather, count, 25.0, "Sunny");
    printWeatherData(weather, count);

    freeWeatherData(weather, count);

    return 0;
}
```

