#include <string.h>
#include <time.h>

typedef struct Data {
    char* identifier;
    time_t timestamp;
} Data;

typedef struct Event {
    int event_id;
    struct Event* next;
} Event;

typedef struct Node {
    Data* data;
    int index;
    Event* events;
} Node;

void initializeNodeArray(Node** nodeArray, int size) {
    for (int i = 0; i < size; ++i) {
        nodeArray[i] = (Node*)malloc(sizeof(Node));
        if (!nodeArray[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        nodeArray[i]->data = (Data*)malloc(sizeof(Data));
        if (!nodeArray[i]->data) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        nodeArray[i]->data->identifier = (char*)malloc(20 * sizeof(char));
        if (!nodeArray[i]->data->identifier) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        snprintf(nodeArray[i]->data->identifier, 20, "Node%d", i);
        time(&nodeArray[i]->data->timestamp);
        nodeArray[i]->index = i;
        nodeArray[i]->events = NULL;
    }
}

void printNodeArray(Node** nodeArray, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Node %d: Identifier=%s, Timestamp=%ld\n", 
               nodeArray[i]->index, 
               nodeArray[i]->data->identifier, 
               nodeArray[i]->data->timestamp);
    }
}

void cleanupNodeArray(Node** nodeArray, int size) {
    for (int i = 0; i < size; ++i) {
        free(nodeArray[i]->data->identifier);
        free(nodeArray[i]->data);
        Event* currentEvent = nodeArray[i]->events;
        while (currentEvent) {
            Event* nextEvent = currentEvent->next;
            free(currentEvent);
            currentEvent = nextEvent;
        }
        free(nodeArray[i]);
    }
}

int main() {
    const int arraySize = 5;
    Node** nodeArray = (Node**)malloc(arraySize * sizeof(Node*));
    if (!nodeArray) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    initializeNodeArray(nodeArray, arraySize);
    printNodeArray(nodeArray, arraySize);

    cleanupNodeArray(nodeArray, arraySize);
    free(nodeArray);

    return 0;
}
