#include <pthread.h>

#define MAX_KEY_LENGTH 10

typedef struct Value {
    long timestamp;
    double value;
} Value;

typedef struct Entry {
    char key[MAX_KEY_LENGTH + 1];
    Value value;
    struct Entry* next;
} Entry;

typedef struct Dictionary {
    Entry** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Dictionary;

Dictionary* dictionary_create(size_t initial_capacity) {
    Dictionary* dict = (Dictionary*)malloc(sizeof(Dictionary));
    if (!dict) return NULL;

    dict->buckets = (Entry**)calloc(initial_capacity, sizeof(Entry*));
    if (!dict->buckets) {
        free(dict);
        return NULL;
    }

    dict->capacity = initial_capacity;
    dict->size = 0;
    pthread_mutex_init(&dict->lock, NULL);

    return dict;
}

void dictionary_destroy(Dictionary* dict) {
    for (size_t i = 0; i < dict->capacity; ++i) {
        Entry* entry = dict->buckets[i];
        while (entry) {
            Entry* next = entry->next;
            free(entry);
            entry = next;
        }
    }

    pthread_mutex_destroy(&dict->lock);
    free(dict->buckets);
    free(dict);
}

size_t hash(const char* key, size_t capacity) {
    size_t hash_value = 0;
    for (int i = 0; key[i] != '\0' && i < MAX_KEY_LENGTH; ++i) {
        hash_value = (hash_value * 31 + key[i]) % capacity;
    }
    return hash_value;
}

void dictionary_insert(Dictionary* dict, const char* key, double value_range_min, double value_range_max) {
    pthread_mutex_lock(&dict->lock);

    size_t index = hash(key, dict->capacity);
    Entry* entry = dict->buckets[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            // Key already exists, update the value
            entry->value.value = value_range_min + (rand() / (RAND_MAX / (value_range_max - value_range_min)));
            pthread_mutex_unlock(&dict->lock);
            return;
        }
        entry = entry->next;
    }

    // Key does not exist, create a new entry
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&dict->lock);
        return; // Handle memory allocation failure gracefully
    }

    strncpy(new_entry->key, key, MAX_KEY_LENGTH);
    new_entry->value.timestamp = time(NULL) + rand() % 1000 - 500; // Adjusted by a random offset within the range [-500, 500]
    new_entry->value.value = value_range_min + (rand() / (RAND_MAX / (value_range_max - value_range_min)));
    new_entry->next = dict->buckets[index];
    dict->buckets[index] = new_entry;
    dict->size++;

    pthread_mutex_unlock(&dict->lock);
}

Value* dictionary_lookup(Dictionary* dict, const char* key) {
    pthread_mutex_lock(&dict->lock);

    size_t index = hash(key, dict->capacity);
    Entry* entry = dict->buckets[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            pthread_mutex_unlock(&dict->lock);
            return &entry->value;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&dict->lock);
    return NULL; // Key not found
}

void dictionary_delete(Dictionary* dict, const char* key) {
    pthread_mutex_lock(&dict->lock);

    size_t index = hash(key, dict->capacity);
    Entry** prev_entry = &dict->buckets[index];
    Entry* entry = *prev_entry;

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            *prev_entry = entry->next;
            free(entry);
            dict->size--;
            pthread_mutex_unlock(&dict->lock);
            return;
        }
        prev_entry = &entry->next;
        entry = entry->next;
    }

    pthread_mutex_unlock(&dict->lock);
}

int main() {
    srand(time(NULL));
    Dictionary* dict = dictionary_create(100);

    if (dict) {
        dictionary_insert(dict, "key1", 0.0, 100.0);
        Value* value = dictionary_lookup(dict, "key1");
        if (value) {
            printf("Value: %f\n", value->value);
        }

        dictionary_delete(dict, "key1");

        dictionary_destroy(dict);
    } else {
        fprintf(stderr, "Failed to create dictionary.\n");
    }

    return 0;
}
