#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    char* value;
} record;

record* create_records(int count, int min_key, int max_key, unsigned int seed) {
    if (count <= 0 || min_key > max_key) return NULL;

    srand(seed);
    record* records = malloc(count * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < count; ++i) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].value = malloc(256); // Assuming max string length of 255
        if (!records[i].value) {
            for (int j = 0; j < i; ++j) free(records[j].value);
            free(records);
            return NULL;
        }
    }

    return records;
}

void load_records_from_file(record* records, int count, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return;

    for (int i = 0; i < count && !feof(file); ++i) {
        fscanf(file, "%d %255s", &records[i].key, records[i].value);
    }

    fclose(file);
}

void save_records_to_file(record* records, int count, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    for (int i = 0; i < count; ++i) {
        fprintf(file, "%d %s\n", records[i].key, records[i].value);
    }

    fclose(file);
}

void free_records(record* records, int count) {
    for (int i = 0; i < count; ++i) free(records[i].value);
    free(records);
}
