#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_DATA_POINTS 100

typedef struct marketData {
    time_t timestamp;
    double value;
    char* trend;
} MarketData;

typedef struct analysis {
    double movingAverage;
    double standardDeviation;
} Analysis;

void initializeFinancialData(double* stockPrices, char** trends, MarketData** marketDataList, Analysis* analysis) {
    srand(time(NULL));

    for (int i = 0; i < NUM_DATA_POINTS; i++) {
        stockPrices[i] = ((double)rand() / RAND_MAX) * 100.0;
        if (i == 0) {
            trends[i] = "Uptrend";
        } else {
            trends[i] = trends[i - 1];
        }
    }

    *marketDataList = (MarketData*)malloc(NUM_DATA_POINTS * sizeof(MarketData));
    for (int i = 0; i < NUM_DATA_POINTS; i++) {
        (*marketDataList)[i].timestamp = time(NULL) + i;
        (*marketDataList)[i].value = stockPrices[i];
        (*marketDataList)[i].trend = trends[i];
    }

    analysis->movingAverage = 0.0;
    analysis->standardDeviation = 0.0;

    // Calculate moving average and standard deviation
    for (int i = 0; i < NUM_DATA_POINTS; i++) {
        analysis->movingAverage += (*marketDataList)[i].value / NUM_DATA_POINTS;
        double diff = (*marketDataList)[i].value - analysis->movingAverage;
        analysis->standardDeviation += diff * diff;
    }
    analysis->standardDeviation = sqrt(analysis->standardDeviation / NUM_DATA_POINTS);
}

void freeFinancialData(double* stockPrices, char** trends, MarketData* marketDataList) {
    free(stockPrices);
    for (int i = 0; i < NUM_DATA_POINTS; i++) {
        free(trends[i]);
    }
    free(marketDataList);
}
