#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_SENSOR_DATA 10

typedef struct {
    int device_id;
    time_t last_seen_timestamp;
    float sensor_data[MAX_SENSOR_DATA];
} DEVICE_INFO_T;

typedef struct {
    DEVICE_INFO_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DEVICE_MANAGER_T;

void init_device_manager(DEVICE_MANAGER_T *manager, size_t initial_capacity) {
    manager->data = (DEVICE_INFO_T *)malloc(initial_capacity * sizeof(DEVICE_INFO_T));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_device_manager(DEVICE_MANAGER_T *manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
}

int insert_device_info(DEVICE_MANAGER_T *manager, DEVICE_INFO_T device_info) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        // Resize the array
        manager->capacity *= 2;
        manager->data = (DEVICE_INFO_T *)realloc(manager->data, manager->capacity * sizeof(DEVICE_INFO_T));
    }
    manager->data[manager->size++] = device_info;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_device_info(DEVICE_MANAGER_T *manager, int device_id, DEVICE_INFO_T new_info) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].device_id == device_id) {
            manager->data[i] = new_info;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Device not found
}

DEVICE_INFO_T *get_device_info(DEVICE_MANAGER_T *manager, int device_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].device_id == device_id) {
            DEVICE_INFO_T *info = &manager->data[i];
            pthread_mutex_unlock(&manager->lock);
            return info;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Device not found
}

void aggregate_sensor_data(DEVICE_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        DEVICE_INFO_T *info = &manager->data[i];
        // Perform aggregation logic here
        printf("Device ID: %d, Last Seen: %ld\n", info->device_id, info->last_seen_timestamp);
    }
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    DEVICE_MANAGER_T manager;
    init_device_manager(&manager, 1024);

    DEVICE_INFO_T device = {1, time(NULL), {1.5, 2.3, 3.7}};
    insert_device_info(&manager, device);

    update_device_info(&manager, 1, (DEVICE_INFO_T){1, time(NULL) + 60, {1.6, 2.4, 3.8}});

    DEVICE_INFO_T *info = get_device_info(&manager, 1);
    if (info != NULL) {
        printf("Device ID: %d, Last Seen: %ld\n", info->device_id, info->last_seen_timestamp);
    }

    aggregate_sensor_data(&manager);

    destroy_device_manager(&manager);
    return 0;
}
