#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DEVICE_ID 1000
#define MAX_STATUS_MSG 256

typedef enum {
    ONLINE,
    OFFLINE,
    ERROR
} DeviceStatus;

typedef struct {
    int deviceID;
    DeviceStatus status;
    time_t lastUpdate;
    char* diagnosticMsg;
} deviceStatus;

typedef struct {
    deviceStatus** queue;
    int front, rear, size;
} PriorityQueue;

PriorityQueue* createPriorityQueue(int capacity) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->queue = (deviceStatus**)malloc(capacity * sizeof(deviceStatus*));
    pq->front = pq->rear = -1;
    pq->size = capacity;
    return pq;
}

int isFull(PriorityQueue* pq) {
    return ((pq->rear + 1) % pq->size == pq->front);
}

int isEmpty(PriorityQueue* pq) {
    return (pq->front == -1);
}

void enqueue(PriorityQueue* pq, deviceStatus* ds) {
    if (isFull(pq)) {
        printf("Priority Queue is Full\n");
        return;
    }
    if (isEmpty(pq))
        pq->front = pq->rear = 0;
    else
        pq->rear = (pq->rear + 1) % pq->size;
    pq->queue[pq->rear] = ds;
}

deviceStatus* dequeue(PriorityQueue* pq) {
    if (isEmpty(pq)) {
        printf("Priority Queue is Empty\n");
        return NULL;
    }
    deviceStatus* ds = pq->queue[pq->front];
    if (pq->front == pq->rear)
        pq->front = pq->rear = -1;
    else
        pq->front = (pq->front + 1) % pq->size;
    return ds;
}

void freeDeviceStatus(deviceStatus* ds) {
    free(ds->diagnosticMsg);
    free(ds);
}

// Function to handle networked device status updates
void updateDeviceStatus(PriorityQueue* pq, int deviceID, DeviceStatus status, char* diagnosticMsg) {
    deviceStatus* ds = (deviceStatus*)malloc(sizeof(deviceStatus));
    ds->deviceID = deviceID;
    ds->status = status;
    time_t now = time(NULL);
    ds->lastUpdate = now;
    ds->diagnosticMsg = strdup(diagnosticMsg);

    enqueue(pq, ds);
}

// Function to process device status updates
void processDeviceStatus(PriorityQueue* pq) {
    while (!isEmpty(pq)) {
        deviceStatus* ds = dequeue(pq);
        printf("Processing device %d: Status=%s, Last Update=%ld, Diagnostic Msg=%s\n",
               ds->deviceID, (ds->status == ONLINE ? "ONLINE" : (ds->status == OFFLINE ? "OFFLINE" : "ERROR")),
               ds->lastUpdate, ds->diagnosticMsg);
        freeDeviceStatus(ds);
    }
}

int main() {
    PriorityQueue* pq = createPriorityQueue(MAX_DEVICE_ID);

    // Simulate receiving status updates
    updateDeviceStatus(pq, 101, ONLINE, "Device is online");
    updateDeviceStatus(pq, 102, OFFLINE, "Device is offline");
    updateDeviceStatus(pq, 103, ERROR, "Device encountered an error");

    // Process status updates
    processDeviceStatus(pq);

    free(pq->queue);
    free(pq);

    return 0;
}
```

