['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

struct Record {
    int key;
    long offset;
    int value;
};

void manage_memory(int n, int m, int p, int value_min, int value_max, unsigned int seed) {
    srand(seed);

    // Allocate memory for offsets
    long *offsets = (long *)malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize unique random offsets
    for (int i = 0; i < n; ++i) {
        do {
            offsets[i] = rand() % (n * m);
        } while (i > 0 && offsets[i] == offsets[i - 1]);
    }

    // Allocate memory for keys
    int *keys = (int *)malloc(m * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize unique keys from 1 to m
    for (int i = 0; i < m; ++i) {
        keys[i] = i + 1;
    }

    // Allocate memory for records
    struct Record *records = (struct Record *)malloc(p * sizeof(struct Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize records with unique keys and random values within the specified range
    for (int i = 0; i < p; ++i) {
        int key_index = rand() % m;
        records[i].key = keys[key_index];
        records[i].offset = offsets[rand() % n];
        records[i].value = rand() % (value_max - value_min + 1) + value_min;

        // Ensure unique offset
        for (int j = 0; j < i; ++j) {
            if (records[j].offset == records[i].offset) {
                fprintf(stderr, "Duplicate offset detected\n");
                free(offsets);
                free(keys);
                free(records);
                return;
            }
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    printf("Memory management successful\n");
}

int main() {
    int n = 10, m = 5, p = 20, value_min = 10, value_max = 100, seed = time(NULL);
    manage_memory(n, m, p, value_min, value_max, seed);
    return 0;
}
