typedef struct Node {
    Data *data;
    int index;
    pthread_mutex_t lock;
} Node;

Node** init_node_array(int initial_size) {
    Node **array = (Node**)malloc(initial_size * sizeof(Node*));
    for (int i = 0; i < initial_size; i++) {
        array[i] = (Node*)malloc(sizeof(Node));
        array[i]->data = (Data*)malloc(sizeof(Data));
        pthread_mutex_init(&array[i]->lock, NULL);
    }
    return array;
}

void init_node(Node *node, int index) {
    node->index = index;
    pthread_mutex_lock(&node->lock);
    node->data->identifier = (char*)malloc(20 * sizeof(char));
    snprintf(node->data->identifier, 20, "ID%d", index);
    time_t now = time(NULL);
    node->data->timestamp = now;
    // Initialize payload with a default value
    node->data->payload = NULL; // Assuming no specific initialization needed for payload
    pthread_mutex_unlock(&node->lock);
}

void print_node(Node *node) {
    pthread_mutex_lock(&node->lock);
    printf("Identifier: %s, Timestamp: %ld\n", node->data->identifier, node->data->timestamp);
    pthread_mutex_unlock(&node->lock);
}

void add_node(Node **array, int *size, int new_index) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = (Data*)malloc(sizeof(Data));
    pthread_mutex_init(&new_node->lock, NULL);

    pthread_mutex_lock(&array[*size]->lock);
    array[*size] = new_node;
    (*size)++;
    init_node(new_node, new_index);
    pthread_mutex_unlock(&array[*size]->lock);
}

void resize_array(Node ***array, int *current_size, int new_size) {
    Node **new_array = (Node**)realloc(*array, new_size * sizeof(Node*));
    for (int i = *current_size; i < new_size; i++) {
        new_array[i] = (Node*)malloc(sizeof(Node));
        new_array[i]->data = (Data*)malloc(sizeof(Data));
        pthread_mutex_init(&new_array[i]->lock, NULL);
    }
    *array = new_array;
    *current_size = new_size;
}

void free_node_array(Node **array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i]->data->identifier);
        free(array[i]->data);
        pthread_mutex_destroy(&array[i]->lock);
        free(array[i]);
    }
    free(array);
}
