#include <json-c/json.h>

typedef struct {
    char *key;
    int value;
} KeyValuePair;

typedef struct {
    KeyValuePair **entries;
    size_t count;
} HashMap;

void processFileContent(const char *filePath, size_t maxBufferSize, HashMap *hashMap, int (*validateKey)(const char *)) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize > maxBufferSize) {
        fileSize = maxBufferSize;
    }

    char *buffer = malloc((fileSize + 1) * sizeof(char));
    if (!buffer) {
        perror("Failed to allocate memory");
        fclose(file);
        return;
    }

    fread(buffer, 1, fileSize, file);
    buffer[fileSize] = '\0';
    fclose(file);

    time_t lastModifiedTime = get_last_modified_time(filePath);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&lastModifiedTime));
    hashMap->entries[hashMap->count++] = create_entry(timestamp, 0);

    json_object *jsonObj = json_tokener_parse(buffer);
    if (!jsonObj) {
        fprintf(stderr, "Failed to parse JSON\n");
        free(buffer);
        return;
    }

    process_json(jsonObj, hashMap, validateKey);

    json_object_put(jsonObj);
    free(buffer);
}

time_t get_last_modified_time(const char *filePath) {
    struct stat fileStat;
    if (stat(filePath, &fileStat) != 0) {
        perror("Failed to get file stats");
        return -1;
    }
    return fileStat.st_mtime;
}

KeyValuePair* create_entry(const char *key, int value) {
    KeyValuePair *entry = malloc(sizeof(KeyValuePair));
    entry->key = strdup(key);
    entry->value = value;
    return entry;
}

void process_json(json_object *jsonObj, HashMap *hashMap, int (*validateKey)(const char *)) {
    if (json_is_object(jsonObj)) {
        json_object_object_foreach(jsonObj, key, val) {
            if (validateKey(key)) {
                if (json_is_number(val)) {
                    hashMap->entries[hashMap->count++] = create_entry(key, json_object_get_int(val));
                } else {
                    fprintf(stderr, "Invalid value for key: %s\n", key);
                }
            }
        }
    } else if (json_is_array(jsonObj)) {
        size_t arraySize;
        json_object_array_foreach(jsonObj, i, val) {
            process_json(val, hashMap, validateKey);
        }
    }
}
