#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_NODES 10000

typedef struct Data {
    char* identifier;
    time_t timestamp;
} Data;

typedef struct Event {
    int event_id;
    struct Event* next;
} Event;

typedef struct Node {
    Data* data;
    int index;
    Event* events;
    int ref_count;
    pthread_mutex_t lock;
} Node;

Node* node_array[MAX_NODES];
int node_count = 0;
pthread_mutex_t array_lock;

void initialize_node(Node* node, int index) {
    node->data = (Data*)malloc(sizeof(Data));
    if (!node->data) {
        fprintf(stderr, "Memory allocation failed for Data structure\n");
        exit(1);
    }
    node->data->identifier = (char*)malloc(20 * sizeof(char));
    if (!node->data->identifier) {
        fprintf(stderr, "Memory allocation failed for identifier\n");
        free(node->data);
        exit(1);
    }
    snprintf(node->data->identifier, 20, "Node%d", index);
    node->data->timestamp = time(NULL);
    node->index = index;
    node->events = NULL;
    node->ref_count = 1;
    pthread_mutex_init(&node->lock, NULL);
}

void add_node(int index) {
    pthread_mutex_lock(&array_lock);
    if (node_count < MAX_NODES) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for Node structure\n");
            pthread_mutex_unlock(&array_lock);
            return;
        }
        initialize_node(new_node, index);
        node_array[index] = new_node;
        node_count++;
    } else {
        fprintf(stderr, "Node array is full\n");
    }
    pthread_mutex_unlock(&array_lock);
}

void remove_node(int index) {
    pthread_mutex_lock(&array_lock);
    if (index >= 0 && index < node_count) {
        Node* node = node_array[index];
        free(node->data->identifier);
        free(node->data);
        Event* event = node->events;
        while (event) {
            Event* next_event = event->next;
            free(event);
            event = next_event;
        }
        pthread_mutex_destroy(&node->lock);
        free(node);
        node_array[index] = NULL;
        for (int i = index; i < node_count - 1; i++) {
            node_array[i] = node_array[i + 1];
        }
        node_count--;
    } else {
        fprintf(stderr, "Invalid node index\n");
    }
    pthread_mutex_unlock(&array_lock);
}

void clear_nodes() {
    pthread_mutex_lock(&array_lock);
    for (int i = 0; i < node_count; i++) {
        Node* node = node_array[i];
        free(node->data->identifier);
        free(node->data);
        Event* event = node->events;
        while (event) {
            Event* next_event = event->next;
            free(event);
            event = next_event;
        }
        pthread_mutex_destroy(&node->lock);
        free(node);
    }
    memset(node_array, 0, sizeof(Node*) * MAX_NODES);
    node_count = 0;
    pthread_mutex_unlock(&array_lock);
}

void print_nodes() {
    for (int i = 0; i < node_count; i++) {
        Node* node = node_array[i];
        printf("Node %d: Identifier=%s, Timestamp=%ld\n", node->index, node->data->identifier, node->data->timestamp);
    }
}

int main() {
    pthread_mutex_init(&array_lock, NULL);

    // Example usage
    add_node(0);
    print_nodes();
    remove_node(0);
    clear_nodes();

    pthread_mutex_destroy(&array_lock);
    return 0;
}
