#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256

typedef struct Node {
    char key[MAX_KEY_LENGTH];
    int value;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(initial_capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

size_t hash_function(const char* key, size_t capacity) {
    size_t hash = 0;
    for (const char* p = key; *p != '\0'; ++p) {
        hash = (hash * 31 + *p) % capacity;
    }
    return hash;
}

int insert_node(HashTable* table, const char* key, int value) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failed
    }

    strcpy(new_node->key, key);
    new_node->value = value;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    ++table->size;
    pthread_mutex_unlock(&table->lock);

    return 0; // Success
}

int retrieve_node(HashTable* table, const char* key, int* value) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);

    Node* node = table->buckets[index];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            *value = node->value;
            pthread_mutex_unlock(&table->lock);
            return 0; // Success
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1; // Key not found
}

int delete_node(HashTable* table, const char* key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);

    Node** prev = &table->buckets[index];
    Node* node = *prev;
    while (node) {
        if (strcmp(node->key, key) == 0) {
            *prev = node->next;
            free(node);
            --table->size;
            pthread_mutex_unlock(&table->lock);
            return 0; // Success
        }
        prev = &node->next;
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1; // Key not found
}

void iterate_reverse(HashTable* table, void (*callback)(const char*, int)) {
    for (size_t i = table->capacity; i-- > 0;) {
        Node* node = table->buckets[i];
        while (node) {
            callback(node->key, node->value);
            node = node->next;
        }
    }
}

void print_node(const char* key, int value) {
    printf("Key: %s, Value: %d\n", key, value);
}
