    FILE *fp1 = fopen(file1, "r");
    FILE *fp2 = fopen(file2, "r");
    FILE *fp3 = fopen(file3, "r");

    if (!fp1 || !fp2 || !fp3) {
        fprintf(stderr, "Error opening one or more files.\n");
        return;
    }

    long* offsets = (long*)malloc(expected_count * sizeof(long));
    int* keys = (int*)malloc(expected_count * sizeof(int));
    record* records = (record*)malloc(expected_count * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        fclose(fp1);
        fclose(fp2);
        fclose(fp3);
        return;
    }

    size_t count1 = 0, count2 = 0, count3 = 0;

    while (fscanf(fp1, "%ld", &offsets[count1]) == 1) count1++;
    while (fscanf(fp2, "%d", &keys[count2]) == 1) count2++;
    while (fscanf(fp3, "%ld %d", &records[count3].offset, &records[count3].key) == 2) count3++;

    if (count1 != expected_count || count2 != expected_count || count3 != expected_count) {
        fprintf(stderr, "File size discrepancy detected.\n");
        // Handle discrepancy, e.g., log warning or attempt reconciliation
    }

    srand(time(NULL));
    for (size_t i = 0; i < expected_count; i++) {
        records[i].offset = rand() % 1000L;
        records[i].key = rand() % 1000;
    }

    // Use the allocated memory...

    free(offsets);
    free(keys);
    free(records);

    fclose(fp1);
    fclose(fp2);
    fclose(fp3);
}
