#include <stdio.h>
#include <stdlib.h>

#define MAX_MEM 1024 // Maximum memory limit in kilobytes

typedef struct Node {
    int key;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t current_mem;
    size_t max_mem;
} LinkedList;

LinkedList* create_list(size_t max_mem) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->current_mem = 0;
    list->max_mem = max_mem * 1024; // Convert to bytes
    return list;
}

Node* create_node(int key, size_t node_size) {
    Node* node = (Node*)malloc(node_size);
    if (!node) return NULL;
    node->key = key;
    node->next = node->prev = NULL;
    return node;
}

int insert_node(LinkedList* list, int key, size_t node_size) {
    if (list->current_mem + node_size > list->max_mem) return -1; // Memory limit exceeded
    Node* new_node = create_node(key, node_size);
    if (!new_node) return -2; // Failed to allocate memory for new node

    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        Node* current = list->head;
        while (current != NULL && current->key < key) {
            current = current->next;
        }
        if (current == NULL) {
            // Insert at the end
            list->tail->next = new_node;
            new_node->prev = list->tail;
            list->tail = new_node;
        } else if (current == list->head) {
            // Insert at the beginning
            current->prev = new_node;
            new_node->next = current;
            list->head = new_node;
        } else {
            // Insert in between
            new_node->prev = current->prev;
            new_node->next = current;
            current->prev->next = new_node;
            current->prev = new_node;
        }
    }
    list->current_mem += node_size;
    return 0; // Success
}

void print_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("%d ", current->key);
        current = current->next;
    }
    printf("\n");
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
