#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkSession {
    int session_id;
    int user_id;
    time_t start_time;
    time_t end_time;
    double throughput;
    struct NetworkSession *next;
} NetworkSession;

typedef struct SessionManager {
    NetworkSession *head;
    pthread_mutex_t lock;
    size_t max_memory_usage;
    size_t current_memory_usage;
} SessionManager;

void session_manager_init(SessionManager *manager, size_t max_memory) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_memory_usage = max_memory;
    manager->current_memory_usage = 0;
}

void session_manager_add_session(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->current_memory_usage + sizeof(NetworkSession) > manager->max_memory_usage) {
        // Prune inactive sessions
        NetworkSession *prev = NULL;
        NetworkSession *curr = manager->head;
        while (curr != NULL) {
            if (time(NULL) - curr->end_time > 3600) { // Example: prune sessions older than 1 hour
                if (prev == NULL) {
                    manager->head = curr->next;
                } else {
                    prev->next = curr->next;
                }
                pthread_mutex_unlock(&manager->lock);
                free(curr);
                pthread_mutex_lock(&manager->lock);
                manager->current_memory_usage -= sizeof(NetworkSession);
            } else {
                prev = curr;
            }
            curr = curr->next;
        }
    }
    session->next = manager->head;
    manager->head = session;
    manager->current_memory_usage += sizeof(NetworkSession);
    pthread_mutex_unlock(&manager->lock);
}

NetworkSession* session_manager_get_session_by_user_id(SessionManager *manager, int user_id) {
    NetworkSession *curr = manager->head;
    while (curr != NULL) {
        if (curr->user_id == user_id) {
            return curr;
        }
        curr = curr->next;
    }
    return NULL;
}

double session_manager_calculate_average_throughput(SessionManager *manager, time_t start_time, time_t end_time) {
    NetworkSession *curr = manager->head;
    double total_throughput = 0.0;
    int count = 0;
    while (curr != NULL) {
        if (curr->start_time >= start_time && curr->end_time <= end_time) {
            total_throughput += curr->throughput;
            count++;
        }
        curr = curr->next;
    }
    return count > 0 ? total_throughput / count : 0.0;
}

void session_manager_destroy(SessionManager *manager) {
    NetworkSession *curr = manager->head;
    while (curr != NULL) {
        NetworkSession *temp = curr;
        curr = curr->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->lock);
}
