// Define a custom packet structure
typedef struct {
    int id;
    time_t timestamp;
    char* payload;
} Packet;

// Configuration structure for packet initialization
typedef struct {
    int num_packets;
    size_t max_payload_size;
} Config;

// Function to initialize and populate an array of packets
Packet* init_and_populate_packets(Config config) {
    Packet* packets = (Packet*)malloc(config.num_packets * sizeof(Packet));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < config.num_packets; ++i) {
        packets[i].id = i + 1;
        time_t current_time;
        time(&current_time);
        packets[i].timestamp = current_time;

        // Dynamically allocate payload based on configuration
        size_t payload_size = rand() % (config.max_payload_size + 1);
        packets[i].payload = (char*)malloc(payload_size * sizeof(char));
        if (!packets[i].payload) {
            fprintf(stderr, "Memory allocation failed for packet %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }

        // Populate payload with random data
        for (size_t j = 0; j < payload_size; ++j) {
            packets[i].payload[j] = 'A' + rand() % 26;
        }
    }

    return packets;
}

// Function to verify the integrity of the payload
void verify_payloads(Packet* packets, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        // Example verification: check if all characters are uppercase letters
        for (size_t j = 0; j < strlen(packets[i].payload); ++j) {
            if (!isupper(packets[i].payload[j])) {
                fprintf(stderr, "Payload integrity check failed for packet %d\n", i);
                return;
            }
        }
    }
    printf("All payloads verified successfully\n");
}

int main() {
    Config config = {1000, 1024}; // Example configuration
    Packet* packets = init_and_populate_packets(config);

    if (packets) {
        verify_payloads(packets, config.num_packets);
        // Free allocated memory
        for (int i = 0; i < config.num_packets; ++i) {
            free(packets[i].payload);
        }
        free(packets);
    }

    return 0;
}
```

