typedef struct {
    int key;
    char buffer[MAX_KEY_LENGTH];
} Record;

int customHash(int key) {
    return abs(key % MAX_KEY_LENGTH);
}

void processRecords(Record **records, int *size, int *capacity) {
    int input;
    while (scanf("%d", &input) == 1) {
        if (*size >= *capacity) {
            *capacity *= 2;
            *records = realloc(*records, *capacity * sizeof(Record));
            if (*records == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
        (*records)[*size].key = input;
        snprintf((*records)[*size].buffer, MAX_KEY_LENGTH, "%d", input);
        (*size)++;
    }
}

int findLargestKey(Record *records, int size) {
    if (size == 0) {
        fprintf(stderr, "No records to process\n");
        return -1;
    }
    int largest = records[0].key;
    for (int i = 1; i < size; i++) {
        if (records[i].key > largest) {
            largest = records[i].key;
        }
    }
    return largest;
}

void freeRecords(Record *records, int size) {
    free(records);
}

int main() {
    Record *records = NULL;
    int size = 0, capacity = 1;

    processRecords(&records, &size, &capacity);

    int largestKey = findLargestKey(records, size);
    if (largestKey != -1) {
        printf("Largest key: %d\n", largestKey);
    }

    freeRecords(records, size);

    return 0;
}
