#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    int* values;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) {
        fprintf(stderr, "Initial capacity must be greater than zero.\n");
        return NULL;
    }

    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for DynamicArray.");
        return NULL;
    }

    array->records = malloc(initial_capacity * sizeof(Record));
    array->values = malloc(initial_capacity * sizeof(int));
    if (!array->records || !array->values) {
        perror("Failed to allocate memory for records or values.");
        free(array->records);
        free(array->values);
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->records);
        free(array->values);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_record(DynamicArray* array, long offset, int key, int value) {
    if (!array) {
        fprintf(stderr, "DynamicArray is NULL.\n");
        return -1;
    }

    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record* new_records = realloc(array->records, new_capacity * sizeof(Record));
        int* new_values = realloc(array->values, new_capacity * sizeof(int));
        if (!new_records || !new_values) {
            perror("Failed to reallocate memory for records or values.");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->records = new_records;
        array->values = new_values;
        array->capacity = new_capacity;
    }

    array->records[array->size].offset = offset;
    array->records[array->size].key = key;
    array->values[array->size] = value;
    array->size++;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Additional functions for managing dynamic arrays can be added here
