using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;

public class JsonPathException : Exception
{
    public JsonPathException(string message) : base(message) { }
}

public class MemoryManager
{
    private readonly object _lock = new object();
    private readonly List<byte[]> _memoryPool = new List<byte[]>();

    public byte[] Allocate(int size)
    {
        lock (_lock)
        {
            if (_memoryPool.Count > 0 && _memoryPool.Last().Length >= size)
            {
                var memory = _memoryPool.Last();
                _memoryPool.RemoveAt(_memoryPool.Count - 1);
                return memory;
            }
            else
            {
                return new byte[size];
            }
        }
    }

    public void Free(byte[] memory)
    {
        lock (_lock)
        {
            _memoryPool.Add(memory);
        }
    }
}

public class JsonProcessor
{
    private readonly MemoryManager _memoryManager;

    public JsonProcessor(MemoryManager memoryManager)
    {
        _memoryManager = memoryManager;
    }

    public object FindObjectByPath(string json, string path)
    {
        try
        {
            var document = JsonDocument.Parse(json);
            var element = document.RootElement.GetProperty(path);

            if (element.ValueKind == JsonValueKind.Object)
            {
                return element.GetRawText();
            }
            else
            {
                throw new JsonPathException("No matching object found.");
            }
        }
        catch (JsonException ex)
        {
            throw new JsonPathException("Error parsing JSON.", ex);
        }
    }

    public void ProcessLargeJsonFile(string filePath, string path)
    {
        using (var reader = File.OpenText(filePath))
        {
            var json = await reader.ReadToEndAsync();
            var result = FindObjectByPath(json, path);

            // Simulate processing the result
            Console.WriteLine(result);
        }
    }

    public void AllocateMemory(int offsetSize, int keySize)
    {
        var offsets = new List<byte[]>(offsetSize);
        var keys = new List<byte[]>(keySize);

        for (int i = 0; i < offsetSize; i++)
        {
            offsets.Add(_memoryManager.Allocate(sizeof(long)));
        }

        for (int i = 0; i < keySize; i++)
        {
            keys.Add(_memoryManager.Allocate(sizeof(int)));
        }
    }

    public void InitializeRecords(List<int> records, int minValue, int maxValue)
    {
        Random random = new Random();
        int previousValue = int.MinValue;

        foreach (var record in records)
        {
            int value;
            do
            {
                value = random.Next(minValue, maxValue + 1);
            } while (value == previousValue);

            record = value;
            previousValue = value;
        }
    }

    public void MonitorPerformance()
    {
        // Simulate performance monitoring
        Console.WriteLine("Memory allocation and deallocation operations logged.");
    }
}
