        fprintf(stderr, "Error: Input is null or empty.\n");
        return;
    }

    if (strlen(input) > MAX_INPUT_SIZE) {
        fprintf(stderr, "Error: Input exceeds maximum size of %d bytes.\n", MAX_INPUT_SIZE);
