#include <iostream>
#include <unordered_map>
#include <vector>
#include <queue>
#include <mutex>

class ProjectTask {
public:
    int id;
    int priority;
    std::vector<int> dependencies;

    ProjectTask(int id, int priority) : id(id), priority(priority) {}
};

class TaskManager {
private:
    std::unordered_map<int, ProjectTask*> tasks;
    std::unordered_map<int, std::vector<int>> adjacencyList;
    std::mutex mtx;

public:
    void addTask(ProjectTask* task) {
        std::lock_guard<std::mutex> lock(mtx);
        tasks[task->id] = task;
        for (int dep : task->dependencies) {
            adjacencyList[dep].push_back(task->id);
        }
    }

    void updateDependencies(int taskId, const std::vector<int>& newDependencies) {
        std::lock_guard<std::mutex> lock(mtx);
        tasks[taskId]->dependencies = newDependencies;
        for (int dep : adjacencyList[taskId]) {
            auto it = std::find(adjacencyList[dep].begin(), adjacencyList[dep].end(), taskId);
            if (it != adjacencyList[dep].end()) {
                adjacencyList[dep].erase(it);
            }
        }
        for (int newDep : newDependencies) {
            adjacencyList[newDep].push_back(taskId);
        }
    }

    void removeTask(int taskId) {
        std::lock_guard<std::mutex> lock(mtx);
        if (tasks.find(taskId) == tasks.end()) return;
        for (int dep : adjacencyList[taskId]) {
            auto it = std::find(adjacencyList[dep].begin(), adjacencyList[dep].end(), taskId);
            if (it != adjacencyList[dep].end()) {
                adjacencyList[dep].erase(it);
            }
        }
        tasks.erase(taskId);
    }

    ProjectTask* getTask(int taskId) {
        std::lock_guard<std::mutex> lock(mtx);
        if (tasks.find(taskId) == tasks.end()) return nullptr;
        return tasks[taskId];
    }

    void removeCompletedTasks() {
        std::lock_guard<std::mutex> lock(mtx);
        std::queue<int> q;
        for (const auto& task : tasks) {
            if (task.second->dependencies.empty()) {
                q.push(task.first);
            }
        }
        while (!q.empty()) {
            int taskId = q.front();
            q.pop();
            removeTask(taskId);
            for (int dep : adjacencyList[taskId]) {
                auto it = std::find(adjacencyList[dep].begin(), adjacencyList[dep].end(), taskId);
                if (it != adjacencyList[dep].end()) {
                    adjacencyList[dep].erase(it);
                }
                if (adjacencyList[dep].empty()) {
                    q.push(dep);
                }
            }
        }
    }
};
