#define MAX_TASKS 1024
#define TASK_NAME_LEN 64

typedef struct {
    double value;
    int counter;
} Data;

typedef struct {
    char name[TASK_NAME_LEN];
    long timestamp;
    Data *data;
} Task;

typedef struct {
    Task tasks[MAX_TASKS];
    int count;
    pthread_mutex_t lock;
} TaskManager;

TaskManager task_manager;

void init_task(Task *task, const char *name, long timestamp) {
    strncpy(task->name, name, TASK_NAME_LEN);
    task->timestamp = timestamp;
    task->data = (Data *)malloc(sizeof(Data));
}

void reset_task(Task *task) {
    memset(task, 0, sizeof(Task));
}

void destroy_task(Task *task) {
    free(task->data);
}

int add_task(const char *name, long timestamp) {
    pthread_mutex_lock(&task_manager.lock);
    if (task_manager.count >= MAX_TASKS) {
        pthread_mutex_unlock(&task_manager.lock);
        return -1; // Task manager is full
    }
    init_task(&task_manager.tasks[task_manager.count], name, timestamp);
    task_manager.count++;
    pthread_mutex_unlock(&task_manager.lock);
    return 0;
}

void remove_task(int index) {
    pthread_mutex_lock(&task_manager.lock);
    if (index < 0 || index >= task_manager.count) {
        pthread_mutex_unlock(&task_manager.lock);
        return; // Invalid index
    }
    destroy_task(&task_manager.tasks[index]);
    for (int i = index; i < task_manager.count - 1; i++) {
