typedef struct MeasurementEvent {
    int event_id;
    double value;
} MeasurementEvent;

typedef struct DeviceState {
    int device_id;
    double signal_strength;
    MeasurementEvent* events;
    size_t num_events;
    size_t capacity;
    pthread_mutex_t lock;
} DeviceState;

DeviceState** create_device_state_array(size_t initial_capacity) {
    DeviceState** array = (DeviceState**)malloc(initial_capacity * sizeof(DeviceState*));
    if (!array) return NULL;
    for (size_t i = 0; i < initial_capacity; ++i) {
        array[i] = NULL;
    }
    return array;
}

void destroy_device_state_array(DeviceState** array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        if (array[i]) {
            pthread_mutex_destroy(&array[i]->lock);
            free(array[i]->events);
            free(array[i]);
        }
    }
    free(array);
}

DeviceState* create_device_state(int device_id, double signal_strength) {
    DeviceState* state = (DeviceState*)malloc(sizeof(DeviceState));
    if (!state) return NULL;
    state->device_id = device_id;
    state->signal_strength = signal_strength;
    state->events = NULL;
    state->num_events = 0;
    state->capacity = 0;
    pthread_mutex_init(&state->lock, NULL);
    return state;
}

void destroy_device_state(DeviceState* state) {
    pthread_mutex_destroy(&state->lock);
    free(state->events);
    free(state);
}

int add_measurement_event(DeviceState* state, int event_id, double value) {
    pthread_mutex_lock(&state->lock);
    if (state->num_events >= state->capacity) {
        size_t new_capacity = state->capacity ? state->capacity * 2 : 1;
        MeasurementEvent* new_events = realloc(state->events, new_capacity * sizeof(MeasurementEvent));
        if (!new_events) {
            pthread_mutex_unlock(&state->lock);
            return -1;
        }
        state->events = new_events;
        state->capacity = new_capacity;
    }
    for (size_t i = 0; i < state->num_events; ++i) {
        if (state->events[i].event_id == event_id) {
            pthread_mutex_unlock(&state->lock);
            return -1; // Duplicate event
        }
    }
    state->events[state->num_events].event_id = event_id;
    state->events[state->num_events].value = value;
    ++state->num_events;
    pthread_mutex_unlock(&state->lock);
    return 0;
}

DeviceState* find_device_state(DeviceState** array, size_t capacity, int device_id) {
    for (size_t i = 0; i < capacity; ++i) {
        if (array[i] && array[i]->device_id == device_id) {
            return array[i];
        }
    }
    return NULL;
}
