void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->data_packets = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    if (array->data_packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
}

void add_packet(PacketArray *array, DataPacket packet) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        array->data_packets = (DataPacket *)realloc(array->data_packets, new_capacity * sizeof(DataPacket));
        if (array->data_packets == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->capacity = new_capacity;
    }
    array->data_packets[array->size++] = packet;
}

void free_packet_array(PacketArray *array) {
    free(array->data_packets);
    array->data_packets = NULL;
    array->capacity = 0;
    array->size = 0;
}
