} NFAPI_CrcPool;

NFAPI_CrcPool* create_crc_pool(size_t initial_size) {
    NFAPI_CrcPool *pool = (NFAPI_CrcPool*)malloc(sizeof(NFAPI_CrcPool));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->pool_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_crc_pool(NFAPI_CrcPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu(NFAPI_CrcPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count < pool->pool_size) {
        pdu = &pool->pool[pool->used_count++];
    }
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void free_crc_pdu(NFAPI_CrcPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used_count; ++i) {
        if (&pool->pool[i] == pdu) {
            pool->used_count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void log_crc_flag_update(NFAPI_CRC_INDICATION_PDU_T *pdu, int verbosity) {
