import requests
from pydub import AudioSegment
from pydub.effects import reverb, pitch_shift
import hashlib
import threading

def process_audio_stream(url, effects):
    response = requests.get(url, stream=True)
    audio_data = b''

    for chunk in response.iter_content(chunk_size=15 * 1024 * 1024):  # 15MB chunks
        if not chunk:
            break
        audio_data += chunk

    audio_segment = AudioSegment.from_file(audio_data, format="mp3")

    for effect in effects:
        if effect == "reverb":
            audio_segment = reverb(audio_segment)
        elif effect == "pitch_shift":
            audio_segment = pitch_shift(audio_segment, 44100, n_steps=2)  # Example: Shift up by 2 semitones

    md5_hash = hashlib.md5(audio_data).hexdigest()

    return md5_hash

def handle_request(url, effects):
    try:
        result = process_audio_stream(url, effects)
        print(f"Processed audio MD5 hash: {result}")
    except requests.exceptions.RequestException as e:
        print(f"Error processing audio stream: {e}")

# Example usage
url = "http://example.com/large_audio_file.mp3"
effects = ["reverb", "pitch_shift"]
threading.Thread(target=handle_request, args=(url, effects)).start()
```

