#define MAX_FEATURES 10

typedef struct {
    int id;
    int version;
    char features[MAX_FEATURES][50];
} NetworkInterfaceConfig;

typedef struct {
    NetworkInterfaceConfig *configs;
    size_t count;
    size_t capacity;
} NetworkInterfaceManager;

NetworkInterfaceManager* create_manager() {
    NetworkInterfaceManager *manager = (NetworkInterfaceManager*)malloc(sizeof(NetworkInterfaceManager));
    manager->configs = NULL;
    manager->count = 0;
    manager->capacity = 0;
    return manager;
}

void destroy_manager(NetworkInterfaceManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->configs[i].features);
    }
    free(manager->configs);
    free(manager);
}

void add_config(NetworkInterfaceManager *manager, NetworkInterfaceConfig config) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = (manager->capacity == 0) ? 1 : manager->capacity * 2;
        NetworkInterfaceConfig *new_configs = realloc(manager->configs, new_capacity * sizeof(NetworkInterfaceConfig));
        if (!new_configs) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }
    memcpy(&manager->configs[manager->count], &config, sizeof(NetworkInterfaceConfig));
    ++manager->count;
}

void save_manager_to_file(NetworkInterfaceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(&manager->configs[i].id, sizeof(int), 1, file);
        fwrite(&manager->configs[i].version, sizeof(int), 1, file);
        for (int j = 0; j < MAX_FEATURES; ++j) {
            size_t feature_len = strlen(manager->configs[i].features[j]);
            fwrite(&feature_len, sizeof(size_t), 1, file);
            fwrite(manager->configs[i].features[j], sizeof(char), feature_len, file);
        }
    }
    fclose(file);
}

void load_manager_from_file(NetworkInterfaceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (manager->capacity < count) {
        NetworkInterfaceConfig *new_configs = realloc(manager->configs, count * sizeof(NetworkInterfaceConfig));
        if (!new_configs) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        manager->configs = new_configs;
        manager->capacity = count;
    }
    for (size_t i = 0; i < count; ++i) {
        fread(&manager->configs[i].id, sizeof(int), 1, file);
        fread(&manager->configs[i].version, sizeof(int), 1, file);
        for (int j = 0; j < MAX_FEATURES; ++j) {
            size_t feature_len;
            fread(&feature_len, sizeof(size_t), 1, file);
            if (feature_len > sizeof(manager->configs[i].features[j])) {
                fprintf(stderr, "Feature length exceeds buffer size\n");
                return;
            }
            fread(manager->configs[i].features[j], sizeof(char), feature_len, file);
        }
    }
    manager->count = count;
    fclose(file);
}
