#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* str;
} record;

typedef struct hash_node {
    int key;
    record* rec;
    struct hash_node* next;
} hash_node;

typedef struct {
    hash_node** buckets;
    size_t size;
    size_t count;
} hash_table;

hash_table* create_hash_table(size_t size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    if (!table) return NULL;
    table->buckets = (hash_node**)calloc(size, sizeof(hash_node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->size = size;
    table->count = 0;
    return table;
}

void destroy_hash_table(hash_table* table) {
    for (size_t i = 0; i < table->size; ++i) {
        hash_node* node = table->buckets[i];
        while (node) {
            hash_node* next = node->next;
            free(node->rec->str);
            free(node->rec);
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

hash_node* create_hash_node(int key, record* rec) {
    hash_node* node = (hash_node*)malloc(sizeof(hash_node));
    if (!node) return NULL;
    node->key = key;
    node->rec = rec;
    node->next = NULL;
    return node;
}

int insert_into_hash_table(hash_table* table, int key, record* rec) {
    size_t index = key % table->size;
    hash_node* new_node = create_hash_node(key, rec);
    if (!new_node) return -1;

    if (table->buckets[index]) {
        new_node->next = table->buckets[index];
    }
    table->buckets[index] = new_node;
    ++table->count;
    return 0;
}

int hash_function(int key, size_t size) {
    return abs(key % size);
}

record* create_record(int value, const char* str, size_t max_len) {
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) return NULL;
    rec->value = value;
    rec->str = (char*)calloc(max_len + 1, sizeof(char));
    if (!rec->str) {
        free(rec);
        return NULL;
    }
    strncpy(rec->str, str, max_len);
    return rec;
}

void destroy_record(record* rec) {
    free(rec->str);
    free(rec);
}

int process_dataset(size_t max_records, int value_range_start, int value_range_end, size_t max_str_len, int prioritize_speed) {
    srand(time(NULL));
    hash_table* key_table = create_hash_table(max_records * 2);
    if (!key_table) return -1;

    long* offsets = (long*)malloc(sizeof(long) * max_records);
    if (!offsets) {
        destroy_hash_table(key_table);
        return -1;
    }

    int* keys = (int*)malloc(sizeof(int) * max_records);
    if (!keys) {
        free(offsets);
        destroy_hash_table(key_table);
        return -1;
    }

    record** records = (record**)malloc(sizeof(record*) * max_records);
    if (!records) {
        free(keys);
        free(offsets);
        destroy_hash_table(key_table);
        return -1;
    }

    for (size_t i = 0; i < max_records; ++i) {
        int value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        char str[max_str_len];
        snprintf(str, max_str_len, "%d", value);

        record* rec = create_record(value, str, max_str_len);
        if (!rec) {
            for (size_t j = 0; j < i; ++j) {
                destroy_record(records[j]);
            }
            free(records);
            free(keys);
            free(offsets);
            destroy_hash_table(key_table);
            return -1;
        }

        int key;
        do {
            key = rand() % max_records;
        } while (insert_into_hash_table(key_table, key, rec) != 0);

        keys[i] = key;
        offsets[i] = i * sizeof(record);
        records[i] = rec;
    }

    // Process the dataset...

    for (size_t i = 0; i < max_records; ++i) {
        destroy_record(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
    destroy_hash_table(key_table);

    return 0;
}
