typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    new_node->next = NULL;
    return new_node;
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (*head == NULL) {
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

int validate_unique_RNTI(NFAPI_CRC_INDICATION_PDU_T* head) {
    int RNTIs[10000] = {0}; // Assuming a maximum of 10,000 unique RNTIs
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while (temp != NULL) {
        if (RNTIs[temp->RNTI]) {
            return 0; // Duplicate RNTI found
        }
        RNTIs[temp->RNTI] = 1;
        temp = temp->next;
    }
    return 1; // All RNTIs are unique
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Example usage
    insert_node(&head, 1, 101, 201);
    insert_node(&head, 2, 102, 202);

    if (validate_unique_RNTI(head)) {
        printf("All RNTIs are unique\n");
    } else {
        printf("Duplicate RNTI found\n");
    }

    free_list(head);
    return 0;
}
