                               sizeof(char*) * MAX_RECORDS + 
                               sizeof(short) * MAX_RECORDS +
                               sizeof(record) * MAX_RECORDS;
    for (int i = 0; i < MAX_RECORDS; i++) {
        total_memory_used += strlen(records[i].str);
    }

    if (total_memory_used > MEMORY_THRESHOLD) {
        // Handle memory usage exceeding threshold
        for (int i = 0; i < MAX_RECORDS; i++) free(records[i].str);
        free(offsets);
        free(keys);
        free(values);
        free(strings);
        free(svalues);
        free(records);
        return 0;
