    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    table->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!table->records) {
        perror("Failed to allocate memory for records");
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void destroy_hash_table(HashTable* table) {
    pthread_mutex_lock(&table->mutex);
    free(table->records);
    pthread_mutex_unlock(&table->mutex);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

int insert_record(HashTable* table, const char* key, int value) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key, table->capacity);
    while (table->records[index].value != 0) {
        index = (index + 1) % table->capacity;
    }
    table->records[index] = (Record){value, time(NULL)};
    table->size++;
    pthread_mutex_unlock(&table->mutex);
    return 0;
}

int get_record(HashTable* table, const char* key, Record* result) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key, table->capacity);
    while (table->records[index].value != 0) {
        if (strcmp(key, "some_key") == 0) { // Placeholder for actual comparison
            *result = table->records[index];
            pthread_mutex_unlock(&table->mutex);
            return 0;
        }
        index = (index + 1) % table->capacity;
    }
    pthread_mutex_unlock(&table->mutex);
    return -1; // Key not found
}

int resize_hash_table(HashTable* table, size_t new_capacity) {
    Record* old_records = table->records;
    size_t old_size = table->size;

    table->records = (Record*)calloc(new_capacity, sizeof(Record));
    if (!table->records) {
        perror("Failed to allocate memory for resized records");
        free(old_records);
        return -1;
    }

    pthread_mutex_lock(&table->mutex);
    table->capacity = new_capacity;
    table->size = 0;

    for (size_t i = 0; i < old_size; i++) {
        if (old_records[i].value != 0) {
            insert_record(table, "some_key", old_records[i].value); // Placeholder for actual key
        }
    }

    free(old_records);
    pthread_mutex_unlock(&table->mutex);

    return 0;
}

int main() {
    HashTable* table = create_hash_table(10);
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return EXIT_FAILURE;
    }

    insert_record(table, "key1", 42);
    Record result;
    if (get_record(table, "key1", &result) == 0) {
        printf("Value: %d, Timestamp: %ld\n", result.value, result.timestamp);
    } else {
        fprintf(stderr, "Key not found\n");
    }

    destroy_hash_table(table);
    return EXIT_SUCCESS;
}
