    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    int seen[10000] = {0}; // Assuming RNTI values are within 0-9999
    while (current) {
        if (seen[current->RNTI]) return 0; // Duplicate found
        seen[current->RNTI] = 1;
        current = current->next;
    }
    return 1;
