#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct item {
    char* name;
    int priority;
    double cost;
    struct item* next;
} Item;

typedef struct list {
    Item* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Item* current = list->head;
    while (current) {
        Item* next = current->next;
        free(current->name);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_item(List* list, const char* name, int priority, double cost) {
    pthread_mutex_lock(&list->lock);
    Item* new_item = (Item*)malloc(sizeof(Item));
    if (!new_item) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_item->name = strdup(name);
    new_item->priority = priority;
    new_item->cost = cost;
    new_item->next = NULL;

    Item** current = &list->head;
    while (*current && (*current)->priority > priority) {
        current = &(*current)->next;
    }
    new_item->next = *current;
    *current = new_item;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

Item* find_highest_priority_item(List* list) {
    pthread_mutex_lock(&list->lock);
    Item* highest_priority_item = NULL;
    for (Item* current = list->head; current; current = current->next) {
        if (!highest_priority_item || current->priority > highest_priority_item->priority) {
            highest_priority_item = current;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return highest_priority_item;
}

int read_csv_and_insert_items(List* list, const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) return -1;

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        char* name = strtok(buffer, ",");
        char* priority_str = strtok(NULL, ",");
        char* cost_str = strtok(NULL, ",");

        if (name && priority_str && cost_str) {
            int priority = atoi(priority_str);
            double cost = atof(cost_str);
            insert_item(list, name, priority, cost);
        }
    }

    fclose(file);
    return 0;
}
