NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->next = NULL;
    return new_node;
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }
    new_node->next = *head;
    *head = new_node;
}

void validate_and_prune_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;
    int rnti_count[1024] = {0}; // Assuming RNTI values are in the range 0-1023

    while (current != NULL) {
        if (rnti_count[current->RNTI] > 0) {
            NFAPI_CRC_INDICATION_PDU_T* temp = current;
            current = current->next;
            free(temp);
        } else {
            rnti_count[current->RNTI]++;
            prev = current;
            current = current->next;
        }
    }

    // Prune list if size exceeds 10,000 elements
    while (*head != NULL && *head->next != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

void initialize_crcflag(NFAPI_CRC_INDICATION_PDU_T* head) {
    srand(time(NULL));
    while (head != NULL) {
        head->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        head = head->next;
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }
}

