#include <string.h>

typedef struct ResourceRequest {
    int userID;
    char resourceType[50];
    int priority;
    struct ResourceRequest* next;
} ResourceRequest;

ResourceRequest* createRequest(int userID, const char* resourceType, int priority) {
    ResourceRequest* newRequest = (ResourceRequest*)malloc(sizeof(ResourceRequest));
    if (newRequest == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newRequest->userID = userID;
    strncpy(newRequest->resourceType, resourceType, sizeof(newRequest->resourceType) - 1);
    newRequest->priority = priority;
    newRequest->next = NULL;
    return newRequest;
}

void addRequest(ResourceRequest** head, int userID, const char* resourceType, int priority) {
    ResourceRequest* newRequest = createRequest(userID, resourceType, priority);
    if (*head == NULL || (*head)->priority < priority) {
        newRequest->next = *head;
        *head = newRequest;
    } else {
        ResourceRequest* current = *head;
        while (current->next != NULL && current->next->priority >= priority) {
            current = current->next;
        }
        newRequest->next = current->next;
        current->next = newRequest;
    }
}

void updatePriority(ResourceRequest** head, int userID, int newPriority) {
    ResourceRequest* current = *head;
    while (current != NULL) {
        if (current->userID == userID) {
            current->priority = newPriority;
            break;
        }
        current = current->next;
    }
}

void reorderRequests(ResourceRequest** head) {
    // Implement a more efficient sorting algorithm for better performance
    ResourceRequest* sortedHead = NULL;
    while (*head != NULL) {
        ResourceRequest* temp = *head;
        *head = (*head)->next;
        addRequest(&sortedHead, temp->userID, temp->resourceType, temp->priority);
        free(temp);
    }
    *head = sortedHead;
}

void printRequests(ResourceRequest* head) {
    ResourceRequest* current = head;
    while (current != NULL) {
        printf("User ID: %d, Resource Type: %s, Priority: %d\n", current->userID, current->resourceType, current->priority);
        current = current->next;
    }
}

void freeRequests(ResourceRequest** head) {
    ResourceRequest* current = *head;
    while (current != NULL) {
        ResourceRequest* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}
