    if (ds->message_count < MAX_NETWORK_MESSAGES) {
        ds->messages[ds->message_count++] = msg;
    } else {
        fprintf(stderr, "Error: Maximum number of network messages reached.\n");
    }
    pthread_mutex_unlock(&ds->mutex);
}

void add_record(DataStructures *ds, Record record) {
    pthread_mutex_lock(&ds->mutex);
    if (ds->record_count < MAX_RECORDS) {
        ds->records[ds->record_count++] = record;
    } else {
        fprintf(stderr, "Error: Maximum number of records reached.\n");
    }
    pthread_mutex_unlock(&ds->mutex);
}

void free_data_structures(DataStructures *ds) {
    free(ds->messages);
    free(ds->offsets);
    free(ds->keys);
    free(ds->values);
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
