Event** read_events_from_file(const char* filename, size_t* count) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    Event** events = malloc(sizeof(Event*) * 1024); // Initial capacity
    if (!events) {
        fclose(file);
        return NULL;
    }

    char buffer[1024];
    size_t index = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        Event* event = create_event(buffer);
        if (!event) {
            free_events(events, index);
            fclose(file);
            return NULL;
        }
        events[index++] = event;

        // Double the capacity if needed
        if (index >= 1024) {
            Event** new_events = realloc(events, sizeof(Event*) * 2048);
            if (!new_events) {
                free_events(events, index);
                fclose(file);
                return NULL;
            }
            events = new_events;
        }
    }

    *count = index;
    fclose(file);
    return events;
}

void free_events(Event** events, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free_event(events[i]);
    }
    free(events);
}

Event* find_highest_priority_event(Event** events, size_t count) {
    Event* highest_priority_event = NULL;
    int max_priority = -1;

    for (size_t i = 0; i < count; i++) {
        if (events[i]->priority > max_priority) {
            max_priority = events[i]->priority;
            highest_priority_event = events[i];
        }
    }

    return highest_priority_event;
}

int main() {
    size_t event_count;
    Event** events = read_events_from_file("events.txt", &event_count);
    if (!events) {
        fprintf(stderr, "Failed to read events from file.\n");
        return 1;
    }

    Event* highest_priority_event = find_highest_priority_event(events, event_count);
    if (highest_priority_event) {
        printf("Highest priority event: %s\n", highest_priority_event->name);
    } else {
        printf("No events found.\n");
    }

    free_events(events, event_count);
    return 0;
}
