#include <pthread.h>
#include <string.h>

#define MAX_STRUCTS 50000

typedef struct {
    int L2_PDU_TYPE;
    int RNTI;
    int UARFCN_BAND_N_5GNR;
} NFAPI_L2_PDU_T;

NFAPI_L2_PDU_T *pdu_list[MAX_STRUCTS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* generate_pdus(void* arg) {
    int start_index = *(int*)arg;
    for (int i = start_index; i < start_index + 1000; i++) {
        pthread_mutex_lock(&mutex);
        if (i >= MAX_STRUCTS) break;
        pdu_list[i] = (NFAPI_L2_PDU_T *)malloc(sizeof(NFAPI_L2_PDU_T));
        if (!pdu_list[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            continue;
        }
        // Initialize L2 PDU fields
        pdu_list[i]->L2_PDU_TYPE = rand() % 10; // Example initialization
        pdu_list[i]->RNTI = rand() % 65536;
        pdu_list[i]->UARFCN_BAND_N_5GNR = rand() % 4096;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void serialize_pdus(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    for (int i = 0; i < MAX_STRUCTS; i++) {
        if (pdu_list[i]) {
            fwrite(pdu_list[i], sizeof(NFAPI_L2_PDU_T), 1, file);
        }
    }
    fclose(file);
}

void deserialize_pdus(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    for (int i = 0; i < MAX_STRUCTS; i++) {
        pdu_list[i] = (NFAPI_L2_PDU_T *)malloc(sizeof(NFAPI_L2_PDU_T));
        if (!pdu_list[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }
        size_t result = fread(pdu_list[i], sizeof(NFAPI_L2_PDU_T), 1, file);
        if (result != 1) {
            free(pdu_list[i]);
            pdu_list[i] = NULL;
        }
    }
    fclose(file);
}

int main() {
    pthread_t threads[5];
    int indices[5] = {0, 10000, 20000, 30000, 40000};

    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, generate_pdus, &indices[i]);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    serialize_pdus("pdus.bin");

    deserialize_pdus("pdus.bin");

    // Free allocated memory
    for (int i = 0; i < MAX_STRUCTS; i++) {
        if (pdu_list[i]) {
            free(pdu_list[i]);
        }
    }

    return 0;
}
