#define MAX_RECORDS 1000
#define MAX_BOOK_NAME_LENGTH 50

typedef struct record {
    int hash;
    char *key;
} Record;

typedef struct node {
    Record data;
    struct node *next;
} Node;

typedef struct {
    Node **buckets;
    size_t capacity;
    size_t size;
    regex_t bookRegex;
} HashTable;

HashTable* createHashTable(size_t capacity) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->capacity = capacity;
    ht->size = 0;
    ht->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    int ret = regcomp(&ht->bookRegex, "^(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)$", REG_EXTENDED);
    if (ret) {
        free(ht->buckets);
        free(ht);
        return NULL;
    }

    return ht;
}

void destroyHashTable(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Node *current = ht->buckets[i];
        while (current) {
            Node *next = current->next;
            free(current);
            current = next;
        }
    }
    regfree(&ht->bookRegex);
    free(ht->buckets);
    free(ht);
}

size_t hashFunction(const char *key, size_t capacity) {
    size_t hash = 0;
    for (const char *p = key; *p != '\0'; ++p) {
        hash = (hash * 31 + *p) % capacity;
    }
    return hash;
}

void insertRecord(HashTable *ht, const char *key) {
    if (!key || strlen(key) == 0) return;

    size_t index = hashFunction(key, ht->capacity);
    Node *newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data.key = strdup(key);
    newNode->data.hash = hashFunction(key, ht->capacity);
    newNode->next = ht->buckets[index];
    ht->buckets[index] = newNode;
    ++ht->size;
}

void analyzeText(const char *text) {
    regex_t bookRegex;
    int ret = regcomp(&bookRegex, "^(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)$", REG_EXTENDED);
    if (ret) return;

    regmatch_t matches[1];
    char *textCopy = strdup(text);
    char *token = strtok(textCopy, " ");
    while (token) {
        ret = regexec(&bookRegex, token, 1, matches, 0);
        if (!ret && matches[0].rm_so == 0 && matches[0].rm_eo == strlen(token)) {
            printf("Found book: %s\n", token);
        }
        token = strtok(NULL, " ");
    }

    free(textCopy);
    regfree(&bookRegex);
}

int main() {
    HashTable *ht = createHashTable(MAX_RECORDS);
    if (!ht) return 1;

    insertRecord(ht, "Genesis");
    insertRecord(ht, "Exodus");
    insertRecord(ht, "Leviticus");
    insertRecord(ht, "Numbers");
    insertRecord(ht, "Deuteronomy");
    insertRecord(ht, "Joshua");
    insertRecord(ht, "Judges");
    insertRecord(ht, "Ruth");
    insertRecord(ht, "1 Samuel");
    insertRecord(ht, "2 Samuel");
    insertRecord(ht, "1 Kings");
    insertRecord(ht, "2 Kings");
    insertRecord(ht, "1 Chronicles");
    insertRecord(ht, "2 Chronicles");
    insertRecord(ht, "Ezra");
    insertRecord(ht, "Nehemiah");
    insertRecord(ht, "Esther");
    insertRecord(ht, "Job");
    insertRecord(ht, "Psalms");
    insertRecord(ht, "Proverbs");
    insertRecord(ht, "Ecclesiastes");
    insertRecord(ht, "Song of Solomon");
    insertRecord(ht, "Isaiah");
    insertRecord(ht, "Jeremiah");
    insertRecord(ht, "Lamentations");
    insertRecord(ht, "Ezekiel");
    insertRecord(ht, "Daniel");
    insertRecord(ht, "Hosea");
    insertRecord(ht, "Joel");
    insertRecord(ht, "Amos");
    insertRecord(ht, "Obadiah");
    insertRecord(ht, "Jonah");
    insertRecord(ht, "Micah");
    insertRecord(ht, "Nahum");
    insertRecord(ht, "Habakkuk");
    insertRecord(ht, "Zephaniah");
    insertRecord(ht, "Haggai");
    insertRecord(ht, "Zechariah");
    insertRecord(ht, "Malachi");

    analyzeText("In the beginning God created the heavens and the earth. In Genesis, God spoke and it was done.");

