typedef enum {
    STATUS_PENDING,
    STATUS_COMPLETED,
    STATUS_FAILED
} EventStatus;

typedef struct Event {
    unsigned int id;
    time_t timestamp;
    EventStatus status;
} Event;

typedef struct EventCollection {
    Event* events;
    size_t capacity;
    size_t size;
    size_t memory_usage;
    size_t threshold;
} EventCollection;

void initEventCollection(EventCollection* collection, size_t initial_capacity, size_t memory_threshold) {
    collection->events = (Event*)malloc(initial_capacity * sizeof(Event));
    if (!collection->events) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->memory_usage = initial_capacity * sizeof(Event);
    collection->threshold = memory_threshold;
}

void addEvent(EventCollection* collection, Event event) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Event* new_events = (Event*)realloc(collection->events, new_capacity * sizeof(Event));
        if (!new_events) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->events = new_events;
        collection->capacity = new_capacity;
    }
    collection->events[collection->size++] = event;
    collection->memory_usage += sizeof(Event);
    if (collection->memory_usage > collection->threshold) {
        fprintf(stderr, "Memory usage exceeded threshold\n");
        // Implement graceful failure strategy
    }
}

void removeEventById(EventCollection* collection, unsigned int id) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->events[i].id == id) {
            for (size_t j = i; j < collection->size - 1; ++j) {
                collection->events[j] = collection->events[j + 1];
            }
            --collection->size;
            collection->memory_usage -= sizeof(Event);
            break;
        }
    }
}

void processEvents(EventCollection* collection, void (*process)(Event*)) {
    for (size_t i = 0; i < collection->size; ++i) {
        process(collection->events[i]);
    }
}

void freeEventCollection(EventCollection* collection) {
    free(collection->events);
    collection->events = NULL;
    collection->capacity = 0;
    collection->size = 0;
    collection->memory_usage = 0;
}
