#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct date {
    int year;
    int month;
    int day;
} Date;

typedef struct product {
    char* name;
    int category_id;
    int priority;
    double cost;
    Date release_date;
    struct product* next;
} Product;

typedef struct {
    Product* head;
    pthread_mutex_t lock;
} ProductList;

void init_product_list(ProductList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_product(ProductList* list, char* name, int category_id, int priority, double cost, Date release_date) {
    pthread_mutex_lock(&list->lock);
    Product* new_product = (Product*)malloc(sizeof(Product));
    new_product->name = strdup(name);
    new_product->category_id = category_id;
    new_product->priority = priority;
    new_product->cost = cost;
    new_product->release_date = release_date;
    new_product->next = NULL;

    if (list->head == NULL || list->head->priority < priority) {
        new_product->next = list->head;
        list->head = new_product;
    } else {
        Product* current = list->head;
        while (current->next != NULL && current->next->priority >= priority) {
            current = current->next;
        }
        new_product->next = current->next;
        current->next = new_product;
    }
    pthread_mutex_unlock(&list->lock);
}

Product* search_highest_priority_product(ProductList* list, int category_id) {
    pthread_mutex_lock(&list->lock);
    Product* highest_priority_product = NULL;
    for (Product* current = list->head; current != NULL; current = current->next) {
        if (current->category_id == category_id && (highest_priority_product == NULL || current->priority > highest_priority_product->priority)) {
            highest_priority_product = current;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return highest_priority_product;
}

void free_product_list(ProductList* list) {
    pthread_mutex_lock(&list->lock);
    Product* current = list->head;
    while (current != NULL) {
        Product* next = current->next;
        free(current->name);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
