#include <forward_list>
#include <string>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

void populateNfarxList(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list, const std::string& targetRnti, const std::string& newRnti) {
    auto it = list.begin();
    while (it != list.end()) {
        if (it->RX_UE_INFORMATION_TAG == targetRnti) {
            NFAPI_CRC_INDICATION_PDU_T newElement;
            newElement.RX_UE_INFORMATION_TAG = newRnti;
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 1);
            newElement.CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen);
            list.insert_after(it, newElement);
            return;
        }
        ++it;
    }

    NFAPI_CRC_INDICATION_PDU_T newElement;
    newElement.RX_UE_INFORMATION_TAG = newRnti;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);
    newElement.CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen);
