#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    int* key_ptr;
} record;

void* custom_memory_pool = NULL;
size_t pool_size = 0;
size_t pool_used = 0;

void init_memory_pool(size_t size) {
    pool_size = size;
    pool_used = 0;
    custom_memory_pool = malloc(pool_size);
}

void* allocate_from_pool(size_t size) {
    if (pool_used + size > pool_size) {
        return NULL; // Out of memory
    }
    void* ptr = (char*)custom_memory_pool + pool_used;
    pool_used += size;
    return ptr;
}

void load_data(const char* filename, long** offsets, int** keys, record** records, size_t* num_records) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }
    fscanf(file, "%zu", num_records);
    *offsets = allocate_from_pool(*num_records * sizeof(long));
    *keys = allocate_from_pool(*num_records * sizeof(int));
    *records = allocate_from_pool(*num_records * sizeof(record));

    for (size_t i = 0; i < *num_records; ++i) {
        fscanf(file, "%ld %d", &(*offsets)[i], &(*keys)[i]);
        (*records)[i].value = (*keys)[i];
        (*records)[i].key_ptr = &(*keys)[i];
    }
    fclose(file);
}

void update_keys(record* records, size_t num_records, int (*transform)(int)) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = transform(records[i].value);
        *records[i].key_ptr = records[i].value;
    }
}

void serialize_data(const char* filename, long* offsets, int* keys, record* records, size_t num_records) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%zu\n", num_records);
    for (size_t i = 0; i < num_records; ++i) {
        fprintf(file, "%ld %d\n", offsets[i], keys[i]);
    }
    fclose(file);
}

void deserialize_data(const char* filename, long** offsets, int** keys, record** records, size_t* num_records) {
    load_data(filename, offsets, keys, records, num_records);
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long* offsets;
    int* keys;
    record* records;
    size_t num_records;

    init_memory_pool(1024 * 1024); // 1MB pool
    load_data("data.txt", &offsets, &keys, &records, &num_records);

    // Example transformation function
    int transform(int key) {
        return key * 2;
    }

    update_keys(records, num_records, transform);
    serialize_data("updated_data.txt", offsets, keys, records, num_records);

    deserialize_data("updated_data.txt", &offsets, &keys, &records, &num_records);

    free_memory(offsets, keys, records);

    return 0;
}
```

