#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int allocate_memory(long **offsets, int **keys, record **records, size_t count, int retries) {
    srand(time(NULL));

    for (int attempt = 0; attempt <= retries; ++attempt) {
        *offsets = malloc(count * sizeof(long));
        *keys = malloc(count * sizeof(int));
        *records = malloc(count * sizeof(record));

        if (*offsets && *keys && *records) {
            for (size_t i = 0; i < count; ++i) {
                (*records)[i].value = rand() % 1000;
            }
            return 0;
        } else {
            free(*offsets);
            free(*keys);
            free(*records);

            if (attempt == retries) {
                fprintf(stderr, "Memory allocation failed after %d attempts.\n", retries + 1);
                return -1;
            }

            printf("Attempt %d: Memory allocation failed. Retrying...\n", attempt + 1);
        }
    }

    return -1;
}

int main() {
    size_t count = 1000;
    int retries = 5;
    long *offsets;
    int *keys;
    record *records;

    if (allocate_memory(&offsets, &keys, &records, count, retries) == 0) {
        printf("Memory allocation successful.\n");

        // Use the allocated memory here

        free(offsets);
        free(keys);
        free(records);
    } else {
        printf("Failed to allocate memory after %d attempts.\n", retries + 1);
    }

    return 0;
}
