    HASH_ENTRY *entry = (HASH_ENTRY*)malloc(sizeof(HASH_ENTRY));
    entry->data = data;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    ++table->count;
    pthread_mutex_unlock(&table->lock);
}

void remove_entry(HASH_TABLE *table, const unsigned char *MAC_ADDRESS) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(MAC_ADDRESS, table->size);
    HASH_ENTRY **entry_ptr = &table->buckets[index];
    while (*entry_ptr) {
        if (memcmp((*entry_ptr)->data.MAC_ADDRESS, MAC_ADDRESS, 6) == 0) {
            HASH_ENTRY *entry = *entry_ptr;
            *entry_ptr = entry->next;
            free(entry);
            --table->count;
            break;
        }
        entry_ptr = &(*entry_ptr)->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void update_entry(HASH_TABLE *table, const unsigned char *MAC_ADDRESS, NR_NET_DEVICE_STATS_T new_data) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(MAC_ADDRESS, table->size);
    HASH_ENTRY *entry = table->buckets[index];
    while (entry) {
        if (memcmp(entry->data.MAC_ADDRESS, MAC_ADDRESS, 6) == 0) {
            entry->data = new_data;
            break;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->lock);
}

