#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Task {
    int id;
    int priority;
    char description[256];
} Task;

typedef struct PriorityQueue {
    Task** tasks;
    size_t capacity;
    size_t size;
    int (*compare)(const void*, const void*);
} PriorityQueue;

PriorityQueue* create_priority_queue(size_t initial_capacity, int (*compare)(const void*, const void*)) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (!pq) return NULL;
    pq->tasks = (Task**)malloc(initial_capacity * sizeof(Task*));
    if (!pq->tasks) {
        free(pq);
        return NULL;
    }
    pq->capacity = initial_capacity;
    pq->size = 0;
    pq->compare = compare;
    return pq;
}

void destroy_priority_queue(PriorityQueue* pq) {
    for (size_t i = 0; i < pq->size; ++i) {
        free(pq->tasks[i]);
    }
    free(pq->tasks);
    free(pq);
}

int enqueue(PriorityQueue* pq, Task* task) {
    if (!pq || !task) return -1;
    if (pq->size == pq->capacity) {
        pq->capacity *= 2;
        pq->tasks = (Task**)realloc(pq->tasks, pq->capacity * sizeof(Task*));
        if (!pq->tasks) return -1;
    }
    pq->tasks[pq->size++] = task;
    for (size_t i = pq->size - 1; i > 0 && pq->compare(pq->tasks[i], pq->tasks[(i - 1) / 2]) < 0; i = (i - 1) / 2) {
        Task* temp = pq->tasks[i];
        pq->tasks[i] = pq->tasks[(i - 1) / 2];
        pq->tasks[(i - 1) / 2] = temp;
    }
    return 0;
}

Task* dequeue(PriorityQueue* pq) {
    if (!pq || pq->size == 0) return NULL;
    Task* task = pq->tasks[0];
    pq->tasks[0] = pq->tasks[--pq->size];
    for (size_t i = 0; i * 2 + 1 < pq->size;) {
        size_t left = i * 2 + 1, right = i * 2 + 2;
        size_t child = left;
        if (right < pq->size && pq->compare(pq->tasks[right], pq->tasks[left]) < 0) {
            child = right;
        }
        if (pq->compare(pq->tasks[child], pq->tasks[i]) >= 0) break;
        Task* temp = pq->tasks[i];
        pq->tasks[i] = pq->tasks[child];
        pq->tasks[child] = temp;
        i = child;
    }
    return task;
}

int compare_tasks(const void* a, const void* b) {
    Task** ta = (Task**)a;
    Task** tb = (Task**)b;
    if ((*ta)->priority < (*tb)->priority) return -1;
    if ((*ta)->priority > (*tb)->priority) return 1;
    return 0;
}

int main() {
    PriorityQueue* pq = create_priority_queue(10, compare_tasks);
    if (!pq) {
        fprintf(stderr, "Failed to create priority queue\n");
        return 1;
    }

    // Example usage
    Task* task1 = (Task*)malloc(sizeof(Task));
    task1->id = 1;
    task1->priority = 3;
    strcpy(task1->description, "Low priority task");

    enqueue(pq, task1);

    Task* highest_priority_task = dequeue(pq);
    if (highest_priority_task) {
        printf("Highest priority task: ID %d, Priority %d, Description %s\n",
               highest_priority_task->id,
               highest_priority_task->priority,
               highest_priority_task->description);
        free(highest_priority_task);
    }

    destroy_priority_queue(pq);

    return 0;
}
