#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_EXECUTORS 1024
#define MEMORY_THRESHOLD 1024 * 1024 // 1MB

typedef struct {
    void (*task_callback)(void*);
    void* context;
    int status; // 0: pending, 1: success, -1: failure
} Executor;

typedef struct {
    Executor* executors;
    size_t count;
    size_t allocated_count;
    pthread_mutex_t lock;
} TaskManager;

typedef struct {
    FILE* log_file;
} Logger;

void initialize_logger(Logger* logger) {
    logger->log_file = fopen("task_manager.log", "w");
}

void log_message(Logger* logger, const char* message) {
    if (logger->log_file) {
        fprintf(logger->log_file, "%s\n", message);
        fflush(logger->log_file);
    }
}

int allocate_executors(TaskManager* manager, size_t count, Logger* logger) {
    pthread_mutex_lock(&manager->lock);

    if (count > MAX_EXECUTORS) {
        log_message(logger, "Error: Maximum number of executors exceeded.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    if (manager->allocated_count + count > MEMORY_THRESHOLD / sizeof(Executor)) {
        log_message(logger, "Error: Memory threshold exceeded.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t new_size = manager->allocated_count + count;
    Executor* new_executors = realloc(manager->executors, new_size * sizeof(Executor));
    if (!new_executors) {
        log_message(logger, "Error: Memory allocation failed.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->executors = new_executors;
    manager->allocated_count = new_size;

    for (size_t i = manager->count; i < new_size; ++i) {
        manager->executors[i].task_callback = NULL;
        manager->executors[i].context = NULL;
        manager->executors[i].status = 0;
    }

    manager->count += count;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_executors(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->executors[i].task_callback) {
            // Free any resources allocated by the task callback
        }
    }

    free(manager->executors);
    manager->executors = NULL;
    manager->count = 0;
    manager->allocated_count = 0;

    pthread_mutex_unlock(&manager->lock);
}

void execute_task(TaskManager* manager, size_t index) {
    if (index >= manager->count || !manager->executors[index].task_callback) {
        return;
    }

    pthread_mutex_lock(&manager->lock);

    manager->executors[index].status = 0; // Reset status to pending
    manager->executors[index].task_callback(manager->executors[index].context);
    manager->executors[index].status = (manager->executors[index].status == 0) ? -1 : 1;

    pthread_mutex_unlock(&manager->lock);
}

int get_task_status(TaskManager* manager, size_t index) {
    if (index >= manager->count) {
        return -1; // Invalid index
    }

    return manager->executors[index].status;
}
