typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
} SafeList;

void init_safe_list(SafeList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_to_list(SafeList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count < MAX_STRUCTURES) {
        list->data[list->count++] = pdu;
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // List is full
}

void validate_and_add(SafeList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (/* CRC validation logic */) {
        add_to_list(list, pdu);
    } else {
        printf("Error: Invalid CRC indication tag\n");
    }
}

void monitor_memory_usage(SafeList *list) {
    pthread_mutex_lock(&list->lock);
    int memory_used = list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T *);
    if (memory_used > MEMORY_THRESHOLD) {
        printf("Memory usage alert: %d bytes\n", memory_used);
    }
    pthread_mutex_unlock(&list->lock);
}

void filter_by_rnti_range(SafeList *list, int minRNTI, int maxRNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; ) {
        if (list->data[i]->RNTI < minRNTI || list->data[i]->RNTI > maxRNTI) {
            free(list->data[i]);
            for (int j = i; j < list->count - 1; j++) {
                list->data[j] = list->data[j + 1];
            }
            list->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_to_file(SafeList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) return;
    pthread_mutex_lock(&list->lock);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T *), list->count, file);
    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void deserialize_from_file(SafeList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) return;
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    while ((pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) != NULL && fread(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        validate_and_add(list, pdu);
    }
    fclose(file);
