#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_IDENTIFIER_SIZE 1024
#define MAX_RESOURCE_TYPE_SIZE 1024
#define INITIAL_MEMORY_ALLOCATION 100
#define MEMORY_THRESHOLD 500

typedef struct {
    char identifier[MAX_IDENTIFIER_SIZE];
    int usageCount;
    char resourceType[MAX_RESOURCE_TYPE_SIZE];
} ResourceUnit;

ResourceUnit* units = NULL;
int unitCount = 0;
int allocatedSize = 0;
double decayFactor = 0.9;

void initializeUnits(int initialCapacity) {
    if (initialCapacity > MEMORY_THRESHOLD) {
        fprintf(stderr, "Error: Initial capacity exceeds memory threshold.\n");
        exit(EXIT_FAILURE);
    }
    units = (ResourceUnit*)malloc(initialCapacity * sizeof(ResourceUnit));
    allocatedSize = initialCapacity;
}

void addOrUpdateUnit(const char* identifier, int newValue, const char* resourceType) {
    for (int i = 0; i < unitCount; ++i) {
        if (strcmp(units[i].identifier, identifier) == 0) {
            units[i].usageCount = newValue;
            strcpy(units[i].resourceType, resourceType);
            return;
        }
    }
    if (unitCount >= allocatedSize) {
        int newSize = allocatedSize * 2 > MEMORY_THRESHOLD ? MEMORY_THRESHOLD : allocatedSize * 2;
        units = realloc(units, newSize * sizeof(ResourceUnit));
        allocatedSize = newSize;
    }
    strcpy(units[unitCount].identifier, identifier);
    units[unitCount].usageCount = newValue;
    strcpy(units[unitCount].resourceType, resourceType);
    ++unitCount;
}

void updateDecayFactor(double newFactor) {
    if (newFactor > 0 && newFactor < 1) {
        decayFactor = newFactor;
    } else {
        fprintf(stderr, "Error: Invalid decay factor.\n");
    }
}

void logSystemState() {
    printf("Active Units: %d\n", unitCount);
    printf("Current Decay Factor: %.2f\n", decayFactor);
}

int main() {
    initializeUnits(INITIAL_MEMORY_ALLOCATION);

    addOrUpdateUnit("unit1", 50, "typeA");
    addOrUpdateUnit("unit2", 30, "typeB");

    updateDecayFactor(0.8);

    logSystemState();

    free(units);
    return 0;
}
