#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORD_VALUE 1000

typedef struct {
    int value;
} record;

void initialize_data(long *offsets, int *keys, record *records, size_t N, long L) {
    srand(time(NULL));
    long total_sum = 0;

    // Initialize offsets and keys
    for (size_t i = 0; i < N; ++i) {
        offsets[i] = i * sizeof(long);
        keys[i] = rand() % MAX_RECORD_VALUE;
        total_sum += keys[i];
    }

    // Adjust values to meet the sum constraint
    while (total_sum > L) {
        size_t max_index = 0;
        int max_value = keys[0];

        for (size_t i = 1; i < N; ++i) {
            if (keys[i] > max_value) {
                max_value = keys[i];
                max_index = i;
            }
        }

        if (max_value == 0) break; // All values are zero, cannot adjust further

        int adjustment = total_sum - L;
        if (adjustment >= max_value) {
            keys[max_index] = 0;
            total_sum -= max_value;
        } else {
            keys[max_index] -= adjustment;
            total_sum -= adjustment;
        }
    }

    // Initialize records with adjusted values
    for (size_t i = 0; i < N; ++i) {
        records[i].value = keys[i];
    }
}

int main() {
    size_t N = 1000000;
    long L = 500000000L;

    long *offsets = (long *)malloc(N * sizeof(long));
    int *keys = (int *)malloc(N * sizeof(int));
    record *records = (record *)malloc(N * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_data(offsets, keys, records, N, L);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
