#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_ID_SIZE 1024
#define MAX_TIMESTAMP_SIZE 1024
#define MAX_MEMORY_THRESHOLD 1024 * 1024 * 1024 // 1GB

typedef struct {
    char timestamp[MAX_TIMESTAMP_SIZE];
    int packet_id;
    size_t payload_length;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t size;
    size_t memory_usage;
} PacketManager;

void init_packet_manager(PacketManager* pm, size_t initial_capacity) {
    pm->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    if (!pm->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pm->capacity = initial_capacity;
    pm->size = 0;
    pm->memory_usage = 0;
}

void free_packet_manager(PacketManager* pm) {
    free(pm->packets);
    pm->packets = NULL;
    pm->capacity = 0;
    pm->size = 0;
    pm->memory_usage = 0;
}

int add_packet(PacketManager* pm, const char* timestamp, int packet_id, size_t payload_length) {
    if (pm->size >= pm->capacity) {
        size_t new_capacity = pm->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }

    strcpy(pm->packets[pm->size].timestamp, timestamp);
    pm->packets[pm->size].packet_id = packet_id;
    pm->packets[pm->size].payload_length = payload_length;
    pm->size++;
    pm->memory_usage += sizeof(DataPacket);

    if (pm->memory_usage > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory usage exceeded threshold\n");
        return -1;
    }

    return 0;
}

int update_packet(PacketManager* pm, int packet_id, const char* new_timestamp, size_t new_payload_length) {
    for (size_t i = 0; i < pm->size; i++) {
        if (pm->packets[i].packet_id == packet_id) {
            strcpy(pm->packets[i].timestamp, new_timestamp);
            pm->packets[i].payload_length = new_payload_length;
            return 0;
        }
    }
    return -1;
}

int get_packets_by_timestamp_range(PacketManager* pm, const char* start_timestamp, const char* end_timestamp) {
    for (size_t i = 0; i < pm->size; i++) {
        if (strcmp(pm->packets[i].timestamp, start_timestamp) >= 0 && strcmp(pm->packets[i].timestamp, end_timestamp) <= 0) {
            printf("Packet ID: %d, Timestamp: %s, Payload Length: %zu\n", pm->packets[i].packet_id, pm->packets[i].timestamp, pm->packets[i].payload_length);
        }
    }
    return 0;
}

int main() {
    PacketManager pm;
    init_packet_manager(&pm, 10);

    add_packet(&pm, "2023-04-01T12:00:00Z", 1, 1024);
    add_packet(&pm, "2023-04-01T12:01:00Z", 2, 2048);

    update_packet(&pm, 1, "2023-04-01T12:00:05Z", 1536);

    get_packets_by_timestamp_range(&pm, "2023-04-01T12:00:00Z", "2023-04-01T12:01:00Z");

    free_packet_manager(&pm);
    return 0;
}
