#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MEMORY_THRESHOLD 500 * 1024 * 1024 // 500MB

typedef struct {
    char* str;
    int value;
    double precision;
    char* pointer;
} record;

void* manage_memory(void* arg) {
    long offset = *(long*)arg;
    int keys[MAX_RECORDS];
    record records[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS; i++) {
        keys[i] = i * offset;
        records[i].str = malloc(100 * sizeof(char));
        if (!records[i].str) {
            perror("Failed to allocate memory for string");
            return NULL;
        }
        snprintf(records[i].str, 100, "Record %d", i);
        records[i].value = rand() % 1000;
        records[i].precision = (double)i / offset;
        records[i].pointer = malloc(50 * sizeof(char));
        if (!records[i].pointer) {
            perror("Failed to allocate memory for pointer");
            free(records[i].str);
            return NULL;
        }
        snprintf(records[i].pointer, 50, "Pointer %d", i);
    }

    // Simulate external process execution
    pid_t pid = fork();
    if (pid == -1) {
        perror("Failed to fork");
        for (int i = 0; i < MAX_RECORDS; i++) {
            free(records[i].str);
            free(records[i].pointer);
        }
        return NULL;
    } else if (pid == 0) {
        // Child process
        execlp("sleep", "sleep", "1", NULL);
        perror("Failed to execute external process");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "External process failed\n");
            for (int i = 0; i < MAX_RECORDS; i++) {
                free(records[i].str);
                free(records[i].pointer);
            }
            return NULL;
        }
    }

    // Free allocated memory
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i].str);
        free(records[i].pointer);
    }

    return NULL;
}

int main() {
    pthread_t thread;
    long offset = 10;

    if (pthread_create(&thread, NULL, manage_memory, &offset) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
