        node_list[i] = (Node*)malloc(sizeof(Node));
        if (!node_list[i]) {
            fprintf(stderr, "Failed to allocate memory for node %d\n", i);
            return NULL;
        }

        node_list[i]->str = (char*)malloc(20 * sizeof(char));
        if (!node_list[i]->str) {
            fprintf(stderr, "Failed to allocate memory for string in node %d\n", i);
            return NULL;
        }
        snprintf(node_list[i]->str, 20, "Node%d", i);

        node_list[i]->value = rand() % (max_value + 1);
        node_list[i]->precision = (double)rand() / RAND_MAX;

        if (sizeof(Node) * initial_size > MEMORY_THRESHOLD) {
            fprintf(stderr, "Memory usage exceeds threshold\n");
            return NULL;
        }
    }

