record* manage_memory(int num_records, int* keys) {
    if (num_records <= 0 || keys == NULL) {
        return NULL;
    }

    // Allocate memory for arrays
    long* offsets = (long*)aligned_alloc(alignof(long), num_records * sizeof(long));
    int* key_array = (int*)aligned_alloc(alignof(int), num_records * sizeof(int));
    record* records = (record*)aligned_alloc(alignof(record), num_records * sizeof(record));

    if (offsets == NULL || key_array == NULL || records == NULL) {
        // Handle memory allocation failure
        free(offsets);
        free(key_array);
        free(records);
        return NULL;
    }

    // Initialize random seed for offset calculation
    srand(time(NULL));

    // Populate arrays and records
    for (int i = 0; i < num_records; i++) {
        offsets[i] = keys[i];
        key_array[i] = keys[i];

        records[i].offset = offsets[i] + rand() % 1024; // Example formula
        records[i].key = key_array[i];
        memset(records[i].metadata, 0, sizeof(records[i].metadata)); // Initialize metadata
    }

    // Free temporary arrays if needed
    free(offsets);
    free(key_array);

    return records;
}
