using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicDataGenerator
{
    private List<Record> records;
    private Random random;

    public DynamicDataGenerator()
    {
        records = new List<Record>();
        random = new Random();
    }

    public void GenerateRecords(int count, int minValue, int maxValue)
    {
        for (int i = 0; i < count; i++)
        {
            int intValue = random.Next(minValue, maxValue + 1);
            string stringValue = GenerateRandomString(10); // Example size
            records.Add(new Record(intValue, stringValue));
        }
    }

    private string GenerateRandomString(int length)
    {
        const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        return new string(Enumerable.Repeat(chars, length).Select(s => s[random.Next(s.Length)]).ToArray());
    }

    public override string ToString()
    {
        return $"Range: {records.Min(r => r.IntValue)} to {records.Max(r => r.IntValue)}";
    }
}

public class Record
{
    public int IntValue { get; set; }
    public string StringValue { get; set; }

    public Record(int intValue, string stringValue)
    {
        IntValue = intValue;
        StringValue = stringValue;
    }
}
