typedef struct {
    char* str;
    int value;
    double precision;
    char** ptr;
} record;

int allocate_memory(long* offset, int* keys, record* records, size_t num_records) {
    if (num_records == 0) {
        fprintf(stderr, "Error: Zero-sized arrays are not allowed.\n");
        return 0;
    }

    size_t total_size = sizeof(record) * num_records + sizeof(long) * num_records + sizeof(int) * num_records;
    if (total_size > MEMORY_THRESHOLD) {
        fprintf(stderr, "Error: Memory allocation exceeds threshold.\n");
        return 0;
    }

    offset = malloc(sizeof(long) * num_records);
    keys = malloc(sizeof(int) * num_records);
    records = malloc(sizeof(record) * num_records);

    if (!offset || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return 0;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].str = malloc(256 * sizeof(char));
        records[i].ptr = malloc(sizeof(char*));
        if (!records[i].str || !records[i].ptr) {
            fprintf(stderr, "Error: Memory allocation failed for record %zu.\n", i);
            return 0;
        }
    }

    return 1;
}

void free_memory(long* offset, int* keys, record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].str);
        free(records[i].ptr);
    }
    free(offset);
    free(keys);
    free(records);
}

int main() {
