pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

int init_memory_pool(size_t initial_size) {
    if (initial_size > MAX_M / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Error: Initial size exceeds maximum allowed
    }
    pthread_mutex_lock(&pool_lock);
    pool.used = 0;
    pthread_mutex_unlock(&pool_lock);
    return 0;
}

int allocate_memory(size_t N, size_t M) {
    if (N > MAX_N || M < N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Error: Invalid input values
    }
    pthread_mutex_lock(&pool_lock);
    if ((pool.used + N) * sizeof(NFAPI_CRC_INDICATION_PDU_T) > M) {
        pthread_mutex_unlock(&pool_lock);
        return -2; // Error: Memory allocation exceeds maximum allowed
    }
    for (size_t i = 0; i < N; i++) {
        pool.data[pool.used].RX_UE_INFORMATION_TAG = rand() % 1000;
        pool.data[pool.used].RNTI = rand() % 1000;
        pool.used++;
    }
    pthread_mutex_unlock(&pool_lock);
    return 0;
}

void deallocate_memory(size_t N) {
    if (N > pool.used) {
        return; // No-op: Attempt to deallocate more than allocated
    }
    pthread_mutex_lock(&pool_lock);
    pool.used -= N;
    pthread_mutex_unlock(&pool_lock);
}

int main(int argc, char *argv[]) {
    int initial_size = 100;
    size_t max_memory = MAX_M;

    // Parse command-line arguments or environment variables for configuration
    if (argc > 1) {
        initial_size = atoi(argv[1]);
    }
    if (argc > 2) {
        max_memory = atol(argv[2]) * 1024 * 1024; // Convert MB to bytes
    }

    if (init_memory_pool(initial_size) != 0) {
        fprintf(stderr, "Error: Failed to initialize memory pool\n");
        return 1;
    }

    int result = allocate_memory(50, max_memory);
    if (result == -1) {
        fprintf(stderr, "Error: Invalid input values for N and M\n");
    } else if (result == -2) {
        fprintf(stderr, "Error: Memory allocation exceeds maximum allowed\n");
    }

    deallocate_memory(25);

    return 0;
}
