using System;

public class DynamicRandomGenerator
{
    private float minValue;
    private float maxValue;

    public DynamicRandomGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public int GetRandomInt()
    {
        return (int)Math.Round(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public int GetExclusiveRandomInt()
    {
        return (int)Math.Floor(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public float GetRandomWeightedValue(float[] weights)
    {
        if (weights.Length == 0 || !IsSumOfWeightsOne(weights))
        {
            throw new ArgumentException("Invalid weights");
        }
        float randomValue = Random.Shared.NextSingle();
        float cumulativeProbability = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeProbability += weights[i];
            if (randomValue <= cumulativeProbability)
            {
                return minValue + (maxValue - minValue) * i / (weights.Length - 1);
            }
        }
        return maxValue;
    }

    public int GetRandomWeightedInt(int[] weights)
    {
        if (weights.Length == 0 || !IsSumOfWeightsOne(weights))
        {
            throw new ArgumentException("Invalid weights");
        }
        float randomValue = Random.Shared.NextSingle();
        float cumulativeProbability = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeProbability += weights[i];
            if (randomValue <= cumulativeProbability)
            {
                return minValue + (maxValue - minValue) * i / (weights.Length - 1);
            }
        }
        return maxValue;
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }

    private bool IsSumOfWeightsOne(float[] weights)
    {
        float sum = 0;
        foreach (float weight in weights)
        {
            sum += weight;
        }
        return Math.Abs(sum - 1) < 0.0001f;
    }
}
