using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;

public class DynamicRangeGenerator
{
    private ConcurrentDictionary<string, Range> ranges = new ConcurrentDictionary<string, Range>();
    private ConcurrentQueue<LogEntry> logQueue = new ConcurrentQueue<LogEntry>();

    public void AddRange(string name, float minFloat, float maxFloat, int minInt, int maxInt, int historySize)
    {
        ranges.TryAdd(name, new Range(minFloat, maxFloat, minInt, maxInt, historySize));
    }

    public void RemoveRange(string name)
    {
        ranges.TryRemove(name, out _);
    }

    public float[] GenerateRandomNumbers(string rangeName, int count)
    {
        if (!ranges.TryGetValue(rangeName, out var range))
            throw new ArgumentException("Range not found.");

        return Enumerable.Range(0, count).Select(_ => range.Generate()).ToArray();
    }

    public void ResetHistory(string rangeName)
    {
        if (ranges.ContainsKey(rangeName))
            ranges[rangeName].ResetHistory();
    }

    public void LogRandomNumber(string rangeName, float value)
    {
        logQueue.Enqueue(new LogEntry(DateTime.Now, rangeName, value));
    }

    private class Range
    {
        private Random random = new Random();
        private ConcurrentQueue<float> history;
        private ConcurrentQueue<int> intHistory;

        public Range(float minFloat, float maxFloat, int minInt, int maxInt, int historySize)
        {
            MinFloat = minFloat;
            MaxFloat = maxFloat;
            MinInt = minInt;
            MaxInt = maxInt;
            HistorySize = historySize;
            history = new ConcurrentQueue<float>();
            intHistory = new ConcurrentQueue<int>();
        }

        public float MinFloat { get; }
        public float MaxFloat { get; }
        public int MinInt { get; }
        public int MaxInt { get; }
        public int HistorySize { get; }

        public float Generate()
        {
            var value = random.NextFloat(MinFloat, MaxFloat);
            history.Enqueue(value);
            if (history.Count > HistorySize)
                history.TryDequeue(out _);

            LogRandomNumber("Range", value);
            return value;
        }

        public int GenerateInt()
        {
            var value = random.Next(MinInt, MaxInt + 1);
            intHistory.Enqueue(value);
            if (intHistory.Count > HistorySize)
                intHistory.TryDequeue(out _);

            LogRandomNumber("Range", value);
            return value;
        }

        public void ResetHistory()
        {
            history.Clear();
            intHistory.Clear();
        }
    }

    private class LogEntry
    {
        public DateTime Timestamp { get; }
        public string RangeName { get; }
        public float Value { get; }

        public LogEntry(DateTime timestamp, string rangeName, float value)
        {
            Timestamp = timestamp;
            RangeName = rangeName;
            Value = value;
        }
    }
}
