#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char* buffer;
    int metadata;
    int ref_count;
} data_entry;

typedef struct {
    data_entry** entries;
    size_t entry_count;
    size_t max_entries;
    pthread_mutex_t lock;
} dynamic_collection_manager;

dynamic_collection_manager* create_manager(size_t initial_size, size_t max_entries) {
    dynamic_collection_manager* manager = (dynamic_collection_manager*)malloc(sizeof(dynamic_collection_manager));
    if (!manager) return NULL;

    manager->entries = (data_entry**)calloc(initial_size, sizeof(data_entry*));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->entry_count = 0;
    manager->max_entries = max_entries;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(dynamic_collection_manager* manager) {
    for (size_t i = 0; i < manager->entry_count; ++i) {
        free(manager->entries[i]->buffer);
        free(manager->entries[i]);
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int insert_entry(dynamic_collection_manager* manager, size_t buffer_size, int metadata) {
    pthread_mutex_lock(&manager->lock);

    if (manager->entry_count >= manager->max_entries) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Manager is full
    }

    data_entry* entry = (data_entry*)malloc(sizeof(data_entry));
    if (!entry) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Allocation failed
    }

    entry->buffer = (char*)malloc(buffer_size);
    if (!entry->buffer) {
        free(entry);
        pthread_mutex_unlock(&manager->lock);
        return -3; // Buffer allocation failed
    }

    entry->metadata = metadata;
    entry->ref_count = 1;

    manager->entries[manager->entry_count++] = entry;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

data_entry* get_entry(dynamic_collection_manager* manager, size_t index) {
    if (index >= manager->entry_count) return NULL;
    return manager->entries[index];
}

void increment_ref_count(data_entry* entry) {
    pthread_mutex_lock(&entry->lock);
    ++entry->ref_count;
    pthread_mutex_unlock(&entry->lock);
}

void decrement_ref_count(data_entry* entry) {
    pthread_mutex_lock(&entry->lock);
    --entry->ref_count;
    if (entry->ref_count == 0) {
        free(entry->buffer);
        free(entry);
    }
    pthread_mutex_unlock(&entry->lock);
}
