#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint8_t *buffer;
    int metadata;
} data_entry;

typedef struct {
    offset_t *file_offsets;
    uint32_t *unique_ids;
    data_entry **entries;
    size_t entry_count;
    size_t buffer_size;
    pthread_mutex_t lock;
} dynamic_memory_manager;

void init_dynamic_memory_manager(dynamic_memory_manager *manager, size_t initial_entries, size_t buffer_size) {
    manager->file_offsets = (offset_t *)malloc(initial_entries * sizeof(offset_t));
    manager->unique_ids = (uint32_t *)malloc(initial_entries * sizeof(uint32_t));
    manager->entries = (data_entry **)malloc(initial_entries * sizeof(data_entry *));
    for (size_t i = 0; i < initial_entries; ++i) {
        manager->entries[i] = (data_entry *)malloc(sizeof(data_entry));
        manager->entries[i]->buffer = (uint8_t *)malloc(buffer_size);
        manager->entries[i]->metadata = 0;
    }
    manager->entry_count = initial_entries;
    manager->buffer_size = buffer_size;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_dynamic_memory_manager(dynamic_memory_manager *manager) {
    for (size_t i = 0; i < manager->entry_count; ++i) {
        free(manager->entries[i]->buffer);
        free(manager->entries[i]);
    }
    free(manager->file_offsets);
    free(manager->unique_ids);
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
}

void add_entry(dynamic_memory_manager *manager, offset_t file_offset, uint32_t unique_id, const void *data, size_t data_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->entry_count == manager->buffer_size) {
        // Resize arrays
        manager->file_offsets = (offset_t *)realloc(manager->file_offsets, 2 * manager->buffer_size * sizeof(offset_t));
        manager->unique_ids = (uint32_t *)realloc(manager->unique_ids, 2 * manager->buffer_size * sizeof(uint32_t));
        manager->entries = (data_entry **)realloc(manager->entries, 2 * manager->buffer_size * sizeof(data_entry *));
        for (size_t i = manager->entry_count; i < 2 * manager->buffer_size; ++i) {
            manager->entries[i] = (data_entry *)malloc(sizeof(data_entry));
            manager->entries[i]->buffer = (uint8_t *)malloc(manager->buffer_size);
            manager->entries[i]->metadata = 0;
        }
        manager->buffer_size *= 2;
    }
    manager->file_offsets[manager->entry_count] = file_offset;
    manager->unique_ids[manager->entry_count] = unique_id;
    memcpy(manager->entries[manager->entry_count]->buffer, data, data_size);
    manager->entries[manager->entry_count]->metadata = data_size;
    ++manager->entry_count;
    pthread_mutex_unlock(&manager->lock);
}

