using System;
using System.Collections.Generic;

public class ResourceManager
{
    private int minValue;
    private int maxValue;
    private Random random;
    private UnionFind unionFind;
    private List<Structure> allocatedStructures;

    public ResourceManager(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.random = new Random();
        this.unionFind = new UnionFind(maxValue - minValue + 1);
        this.allocatedStructures = new List<Structure>();
    }

    public int GetRandomInt()
    {
        return random.Next(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        return random.Next(minValue + 1, maxValue);
    }

    public int GetRandomWeightedInt(int[] weights)
    {
        if (weights.Length != maxValue - minValue + 1 || !IsValidWeightArray(weights))
        {
            throw new ArgumentException("Invalid weight array");
        }
        int totalWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }
        int randomValue = random.Next(totalWeight);
        int cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue < cumulativeWeight)
            {
                return minValue + i;
            }
        }
        throw new InvalidOperationException("Failed to select a value");
    }

    public Structure[] AllocateStructures(int N)
    {
        Structure[] structures = new Structure[N];
        for (int i = 0; i < N; i++)
        {
            try
            {
                structures[i] = new Structure(GetRandomInt(), GetRandomInt());
                allocatedStructures.Add(structures[i]);
            }
            catch (OutOfMemoryException)
            {
                Array.Resize(ref structures, i);
                break;
            }
        }
        return structures;
    }

    public void Union(int a, int b)
    {
        unionFind.Union(a - minValue, b - minValue);
    }

    public bool Find(int a, int b)
    {
        return unionFind.Find(a - minValue) == unionFind.Find(b - minValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Allocations: {allocatedStructures.Count}";
    }

    private bool IsValidWeightArray(int[] weights)
    {
        for (int i = 0; i < weights.Length; i++)
        {
            if (weights[i] < 0)
            {
                return false;
            }
        }
        return true;
    }
}

