using System;
using System.Collections.Generic;

public class DynamicRandomGenerator
{
    private Tuple<float, float> currentRange;
    private List<float> weights;

    public float MinValue { get => currentRange.Item1; set => UpdateRange(value, currentRange.Item2); }
    public float MaxValue { get => currentRange.Item2; set => UpdateRange(currentRange.Item1, value); }

    public List<float> Weights
    {
        get => weights;
        set
        {
            weights = value;
            NormalizeWeights();
        }
    }

    public DynamicRandomGenerator(float minValue, float maxValue)
    {
        MinValue = minValue;
        MaxValue = maxValue;
        weights = new List<float>();
    }

    private void UpdateRange(float minValue, float maxValue)
    {
        currentRange = Tuple.Create(minValue, maxValue);
        NormalizeWeights();
    }

    private void NormalizeWeights()
    {
        if (weights.Count == 0) return;

        float sum = 0;
        foreach (var weight in weights)
        {
            sum += Math.Abs(weight);
        }

        for (int i = 0; i < weights.Count; i++)
        {
            weights[i] /= sum;
        }
    }

    public T GetRandomValue<T>(bool inclusive) where T : IConvertible
    {
        if (typeof(T) == typeof(int))
        {
            return (T)(object)GetRandomInt(inclusive);
        }
        else if (typeof(T) == typeof(float))
        {
            return (T)(object)GetRandomFloat(inclusive);
        }
        else if (typeof(T) == typeof(double))
        {
            return (T)(object)GetRandomDouble(inclusive);
        }
        throw new ArgumentException("Unsupported type");
    }

    public T GetRandomValueWithWeights<T>(bool inclusive) where T : IConvertible
    {
        if (typeof(T) == typeof(int))
        {
            return (T)(object)GetRandomIntWithWeights(inclusive);
        }
        else if (typeof(T) == typeof(float))
        {
            return (T)(object)GetRandomFloatWithWeights(inclusive);
        }
        else if (typeof(T) == typeof(double))
        {
            return (T)(object)GetRandomDoubleWithWeights(inclusive);
        }
        throw new ArgumentException("Unsupported type");
    }

    public T GetRandomValueInRange<T>(float minValue, float maxValue, bool inclusive) where T : IConvertible
    {
        MinValue = minValue;
        MaxValue = maxValue;
        return GetRandomValue<T>(inclusive);
    }

    private int GetRandomInt(bool inclusive)
    {
        Random random = new Random();
        if (inclusive)
        {
            return random.Next((int)Math.Floor(currentRange.Item1), (int)Math.Ceiling(currentRange.Item2) + 1);
        }
        else
        {
            return random.Next((int)Math.Floor(currentRange.Item1), (int)Math.Ceiling(currentRange.Item2));
        }
    }

    private float GetRandomFloat(bool inclusive)
    {
        Random random = new Random();
        if (inclusive)
        {
            return (float)random.NextDouble() * (currentRange.Item2 - currentRange.Item1) + currentRange.Item1;
        }
        else
        {
            return (float)random.NextDouble() * (currentRange.Item2 - currentRange.Item1) + currentRange.Item1;
        }
    }

    private double GetRandomDouble(bool inclusive)
    {
        Random random = new Random();
        if (inclusive)
        {
            return random.NextDouble() * (currentRange.Item2 - currentRange.Item1) + currentRange.Item1;
        }
        else
        {
            return random.NextDouble() * (currentRange.Item2 - currentRange.Item1) + currentRange.Item1;
        }
    }

    private int GetRandomIntWithWeights(bool inclusive)
    {
        Random random = new Random();
        float totalWeight = 0;
        for (int i = 0; i < weights.Count; i++)
        {
            totalWeight += weights[i];
        }

        float rand = (float)random.NextDouble() * totalWeight;

        for (int i = 0; i < weights.Count; i++)
        {
            if (rand <= weights[i])
            {
                return inclusive ? i : i + 1;
            }
            rand -= weights[i];
        }

        return inclusive ? weights.Count - 1 : weights.Count;
    }

    private float GetRandomFloatWithWeights(bool inclusive)
    {
        Random random = new Random();
        float totalWeight = 0;
        for (int i = 0; i < weights.Count; i++)
        {
            totalWeight += weights[i];
        }

        float rand = (float)random.NextDouble() * totalWeight;

        for (int i = 0; i < weights.Count; i++)
        {
            if (rand <= weights[i])
            {
                return currentRange.Item1 + (currentRange.Item2 - currentRange.Item1) * rand / totalWeight;
            }
            rand -= weights[i];
        }

        return currentRange.Item1 + (currentRange.Item2 - currentRange.Item1);
    }

    private double GetRandomDoubleWithWeights(bool inclusive)
    {
        Random random = new Random();
        float totalWeight = 0;
        for (int i = 0; i < weights.Count; i++)
        {
            totalWeight += weights[i];
        }

        float rand = (float)random.NextDouble() * totalWeight;

        for (int i = 0; i < weights.Count; i++)
        {
            if (rand <= weights[i])
            {
                return currentRange.Item1 + (currentRange.Item2 - currentRange.Item1) * rand / totalWeight;
            }
            rand -= weights[i];
        }

        return currentRange.Item1 + (currentRange.Item2 - currentRange.Item1);
    }
}
