    private readonly HttpClient _httpClient = new HttpClient();
    private bool _isProcessing = true;

    public async Task<X509Certificate2> GetCertificateAsync(string clientId)
    {
        if (!_isProcessing)
            throw new InvalidOperationException("Certificate generation is paused.");

        if (_certificateCache.TryGetValue(clientId, out var certificate))
            return certificate;

        try
        {
            var privateKey = await FetchPrivateKeyAsync(clientId);
            var certificateRequest = GenerateCertificateRequest(privateKey);
            certificate = await SignCertificateRequestAsync(certificateRequest);

            _certificateCache.TryAdd(clientId, certificate);
            return certificate;
        }
        catch (Exception ex)
        {
            // Handle exceptions and fallback mechanisms
            throw new InvalidOperationException("Failed to generate certificate.", ex);
        }
    }

    public void PauseProcessing()
    {
        _isProcessing = false;
    }

    public void ResumeProcessing()
    {
        _isProcessing = true;
    }

