#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    ACTIVE,
    INACTIVE,
    BLOCKED
} Status;

typedef struct User {
    int userID;
    char *username;
    char *email;
    Status status;
    struct User *next;
} User;

typedef struct {
    User *head;
    pthread_mutex_t lock;
} UserManager;

UserManager userManager = {NULL, PTHREAD_MUTEX_INITIALIZER};

void addUser(int userID, const char *username, const char *email, Status status) {
    pthread_mutex_lock(&userManager.lock);
    User *current = userManager.head;
    while (current != NULL) {
        if (current->userID == userID) {
            free(current->username);
            current->username = strdup(username);
            free(current->email);
            current->email = strdup(email);
            current->status = status;
            pthread_mutex_unlock(&userManager.lock);
            return;
        }
        current = current->next;
    }
    User *newUser = (User *)malloc(sizeof(User));
    newUser->userID = userID;
    newUser->username = strdup(username);
    newUser->email = strdup(email);
    newUser->status = status;
    newUser->next = userManager.head;
    userManager.head = newUser;
    pthread_mutex_unlock(&userManager.lock);
}

void removeUser(int userID) {
    pthread_mutex_lock(&userManager.lock);
    User *current = userManager.head;
    User *prev = NULL;
    while (current != NULL) {
        if (current->userID == userID) {
            if (prev == NULL) {
                userManager.head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->username);
            free(current->email);
            free(current);
            pthread_mutex_unlock(&userManager.lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&userManager.lock);
}

User *searchUser(int userID) {
    pthread_mutex_lock(&userManager.lock);
    User *current = userManager.head;
    while (current != NULL) {
        if (current->userID == userID) {
            pthread_mutex_unlock(&userManager.lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&userManager.lock);
    return NULL;
}

void updateUserStatus(int userID, Status newStatus) {
    pthread_mutex_lock(&userManager.lock);
    User *current = userManager.head;
    while (current != NULL) {
        if (current->userID == userID) {
            current->status = newStatus;
            pthread_mutex_unlock(&userManager.lock);
            return;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&userManager.lock);
}

void serializeToCSV(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    pthread_mutex_lock(&userManager.lock);
    User *current = userManager.head;
    while (current != NULL) {
        fprintf(file, "%d,%s,%s,%d\n", current->userID, current->username, current->email, current->status);
        current = current->next;
    }
    pthread_mutex_unlock(&userManager.lock);
    fclose(file);
}

void cleanup() {
    pthread_mutex_lock(&userManager.lock);
    User *current = userManager.head;
    while (current != NULL) {
        User *temp = current;
        current = current->next;
        free(temp->username);
        free(temp->email);
        free(temp);
    }
    userManager.head = NULL;
    pthread_mutex_unlock(&userManager.lock);
}

void logOperation(const char *operation, int userID) {
    printf("%s: UserID=%d\n", operation, userID);
}
