#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    int value;
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insertRecord(LinkedList* list, long offset, int key, int value) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (newRecord == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->value = value;
    newRecord->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newRecord;
    } else {
        Record* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newRecord;
    }
    pthread_mutex_unlock(&list->lock);
}

void traverseLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current != NULL) {
        printf("Offset: %ld, Key: %d, Value: %d\n", current->offset, current->key, current->value);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void serializeLinkedList(LinkedList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current != NULL) {
        fwrite(&current->offset, sizeof(long), 1, file);
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current->value, sizeof(int), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void deserializeLinkedList(LinkedList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    while (!feof(file)) {
        Record* newRecord = (Record*)malloc(sizeof(Record));
        if (newRecord == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        fread(&newRecord->offset, sizeof(long), 1, file);
        fread(&newRecord->key, sizeof(int), 1, file);
        fread(&newRecord->value, sizeof(int), 1, file);
        newRecord->next = NULL;

        if (list->head == NULL) {
            list->head = newRecord;
        } else {
            Record* current = list->head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newRecord;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current != NULL) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
