#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_DEVICE_NAME_LENGTH 256

typedef enum {
    NO_ERROR,
    ERROR_CODE_1,
    ERROR_CODE_2
} ErrorCode;

typedef struct {
    int sensorID;
    float temperature;
    char deviceName[MAX_DEVICE_NAME_LENGTH];
    ErrorCode errorCode;
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} DeviceData;

DeviceData* initializeDeviceData(int numDevices) {
    if (numDevices <= 0) {
        return NULL;
    }
    DeviceData* deviceArray = (DeviceData*)malloc(numDevices * sizeof(DeviceData));
    if (deviceArray == NULL) {
        return NULL;
    }
    for (int i = 0; i < numDevices; i++) {
        deviceArray[i].sensorID = rand() % 1000; // Example sensor ID generation
        deviceArray[i].temperature = (float)(rand() % 100) / 10.0; // Example temperature generation
        snprintf(deviceArray[i].deviceName, MAX_DEVICE_NAME_LENGTH, "Device%d", i);
        deviceArray[i].errorCode = NO_ERROR;
        deviceArray[i].RX_UE_INFORMATION_TAG = rand();
        deviceArray[i].RNTI = (unsigned short)rand();
        deviceArray[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        deviceArray[i].CRCFLAG = rand() % 2;
    }
    return deviceArray;
}

void processDeviceData(DeviceData* deviceArray, int numDevices, int currentSensorID) {
    if (deviceArray == NULL || numDevices <= 0) {
        return;
    }

    for (int i = 0; i < numDevices; i++) {
        if (deviceArray[i].errorCode != NO_ERROR) {
            continue;
        }
        float proximityFactor = (float)(abs(deviceArray[i].sensorID - currentSensorID)) / 1000.0;
        deviceArray[i].temperature *= proximityFactor;
    }
}

int main() {
    int numDevices = 5;
    DeviceData* deviceArray = initializeDeviceData(numDevices);
    if (deviceArray == NULL) {
        printf("Failed to allocate memory for device data.\n");
        return 1;
    }

    int currentSensorID = 300;
    processDeviceData(deviceArray, numDevices, currentSensorID);

    // Free allocated memory
    free(deviceArray);

    return 0;
}
