#define MAX_PLOTS 10000
#define L 1000000

typedef struct {
    double value;
} Point;

typedef struct {
    char* name;
    double* data;
    Point* point;
} Plot;

Plot* plots[MAX_PLOTS];
int plot_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int adjustment_count = 0;

void* allocate_plot(void* arg) {
    pthread_mutex_lock(&mutex);
    if (plot_count >= MAX_PLOTS) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    plots[plot_count] = malloc(sizeof(Plot));
    if (!plots[plot_count]) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    plots[plot_count]->name = strdup("Plot");
    plots[plot_count]->data = malloc(sizeof(double));
    *plots[plot_count]->data = 0.0;
    plots[plot_count]->point = malloc(sizeof(Point));
    plots[plot_count]->point->x = 0.0;
    plots[plot_count]->point->y = 0.0;
    plot_count++;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* adjust_plots(void* arg) {
    double total_sum = 0.0;
    for (int i = 0; i < plot_count; i++) {
        total_sum += *plots[i]->data;
    }
    if (total_sum > L) {
        pthread_mutex_lock(&mutex);
        adjustment_count++;
        for (int i = 0; i < plot_count; i++) {
            double random_value = ((double)rand() / RAND_MAX) * (*plots[i]->data);
            *plots[i]->data -= random_value;
            total_sum -= random_value;
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void* flush_memory(void* arg) {
    for (int i = 0; i < plot_count; i++) {
        free(plots[i]->name);
        free(plots[i]->data);
        free(plots[i]->point);
        free(plots[i]);
    }
    plot_count = 0;
    return NULL;
}

int main() {
    pthread_t threads[MAX_PLOTS];
    for (int i = 0; i < MAX_PLOTS; i++) {
        pthread_create(&threads[i], NULL, allocate_plot, NULL);
    }
    for (int i = 0; i < MAX_PLOTS; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_t adjust_thread;
    pthread_create(&adjust_thread, NULL, adjust_plots, NULL);
    pthread_join(adjust_thread, NULL);

    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, flush_memory, NULL);
    pthread_join(flush_thread, NULL);

    printf("Adjustment count: %d\n", adjustment_count);
    return 0;
}
```

