#include <time.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024
#define RESIZE_THRESHOLD 80

typedef struct {
    time_t timestamp;
    double amount;
    char status[50];
} Transaction;

typedef struct {
    Transaction *buffer;
    int head, tail, count, capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full, not_empty;
} CircularBuffer;

void init_buffer(CircularBuffer *cb, int initial_capacity) {
    cb->buffer = (Transaction *)malloc(initial_capacity * sizeof(Transaction));
    if (!cb->buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    cb->head = cb->tail = cb->count = 0;
    cb->capacity = initial_capacity;
    pthread_mutex_init(&cb->mutex, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);
}

void destroy_buffer(CircularBuffer *cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->mutex);
    pthread_cond_destroy(&cb->not_full);
    pthread_cond_destroy(&cb->not_empty);
}

void insert_transaction(CircularBuffer *cb, double amount) {
    pthread_mutex_lock(&cb->mutex);
    while (cb->count == cb->capacity) {
        pthread_cond_wait(&cb->not_full, &cb->mutex);
    }
    time_t current_time = time(NULL);
    if (cb->count > 0) {
        Transaction *last_transaction = &cb->buffer[(cb->tail - 1 + cb->capacity) % cb->capacity];
        amount = (amount + last_transaction->amount + last_transaction->amount) / 3;
    }
    cb->buffer[cb->tail].timestamp = current_time;
    cb->buffer[cb->tail].amount = amount;
    snprintf(cb->buffer[cb->tail].status, sizeof(cb->buffer[cb]->status), "Processed");
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->count++;
    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->mutex);
}

void *process_transactions(void *arg) {
    CircularBuffer *cb = (CircularBuffer *)arg;
    while (1) {
        pthread_mutex_lock(&cb->mutex);
        while (cb->count == 0) {
            pthread_cond_wait(&cb->not_empty, &cb->mutex);
        }
        Transaction transaction = cb->buffer[cb->head];
        cb->head = (cb->head + 1) % cb->capacity;
        cb->count--;
        pthread_cond_signal(&cb->not_full);
        pthread_mutex_unlock(&cb->mutex);

        // Process the transaction
        printf("Processing transaction at time: %ld, amount: %.2f, status: %s\n", transaction.timestamp, transaction.amount, transaction.status);
    }
    return NULL;
}

int main() {
    CircularBuffer cb;
    init_buffer(&cb, MAX_BUFFER_SIZE);

    pthread_t consumer_thread;
    pthread_create(&consumer_thread, NULL, process_transactions, &cb);

    for (int i = 0; i < 1000; i++) {
        insert_transaction(&cb, i * 10.5);
    }

    pthread_join(consumer_thread, NULL);
    destroy_buffer(&cb);

    return 0;
}
