// Function to append asterisk if input string fits buffer size
char* appendAsteriskIfFits(char* input, int bufferSize) {
    if (strlen(input) < bufferSize) {
        char* result = malloc(strlen(input) + 2);
        strcpy(result, input);
        strcat(result, "*");
        return result;
    } else {
        return "";
    }
}

// Recursive function to parse JSON and extract key-value pairs
void parseJSON(const char* json, const char* pathPattern, char** output, int* index) {
    // Placeholder for actual JSON parsing logic
    // This is a simplified example and should be replaced with a robust JSON parser
    if (strstr(json, pathPattern)) {
        char* key = strtok(strdup(json), ":");
        char* value = strtok(NULL, ",");
        output[*index] = malloc(strlen(key) + strlen(value) + 3);
        sprintf(output[*index], "%s:%s;", key, value);
        (*index)++;
    }
}

// Function to format extracted key-value pairs into a single string
char* formatKeyValuePairs(char** keyValuePairs, int count) {
    char* result = malloc(1); // Start with an empty string
    *result = '\0';
    for (int i = 0; i < count; i++) {
        result = realloc(result, strlen(result) + strlen(keyValuePairs[i]) + 1);
        strcat(result, keyValuePairs[i]);
    }
    return result;
}

// Main function to process input string and JSON document
char* processInputAndJSON(char* input, int bufferSize, const char* json, const char* pathPattern) {
    char* asteriskAppended = appendAsteriskIfFits(input, bufferSize);
    if (strlen(asteriskAppended) == 0) {
        return "";
    }

    // Placeholder for JSON parsing and key extraction
    int count = 10; // Example count, should be dynamically determined
    char** keyValuePairs = malloc(count * sizeof(char*));
    parseJSON(json, pathPattern, keyValuePairs, &count);

    char* formattedPairs = formatKeyValuePairs(keyValuePairs, count);
    for (int i = 0; i < count; i++) {
        free(keyValuePairs[i]);
    }
    free(keyValuePairs);

    char* result = malloc(strlen(asteriskAppended) + strlen(formattedPairs) + 3);
    sprintf(result, "[%s%s]", asteriskAppended, formattedPairs);
    free(asteriskAppended);
    free(formattedPairs);

    return result;
}

// Example usage
int main() {
    char input[] = "example";
    int bufferSize = 20;
    const char* json = "{\"name\":\"John\", \"age\":30}";
    const char* pathPattern = "\"name\":\"";

    char* result = processInputAndJSON(input, bufferSize, json, pathPattern);
    printf("%s\n", result);

    free(result);
    return 0;
}
