#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000

typedef struct {
    int identifier;
    time_t timestamp;
    double value;
} DATA_RECORD_T;

typedef struct {
    DATA_RECORD_T records[MAX_RECORDS];
    int head;
    int tail;
    int count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} RingBuffer;

void initRingBuffer(RingBuffer *rb) {
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    pthread_mutex_init(&rb->lock, NULL);
    pthread_cond_init(&rb->not_full, NULL);
    pthread_cond_init(&rb->not_empty, NULL);
}

void enqueue(RingBuffer *rb, DATA_RECORD_T record) {
    pthread_mutex_lock(&rb->lock);
    while (rb->count == MAX_RECORDS) {
        pthread_cond_wait(&rb->not_full, &rb->lock);
    }
    rb->records[rb->tail] = record;
    rb->tail = (rb->tail + 1) % MAX_RECORDS;
    rb->count++;
    pthread_cond_signal(&rb->not_empty);
    pthread_mutex_unlock(&rb->lock);
}

DATA_RECORD_T dequeue(RingBuffer *rb) {
    DATA_RECORD_T record;
    pthread_mutex_lock(&rb->lock);
    while (rb->count == 0) {
        pthread_cond_wait(&rb->not_empty, &rb->lock);
    }
    record = rb->records[rb->head];
    rb->head = (rb->head + 1) % MAX_RECORDS;
    rb->count--;
    pthread_cond_signal(&rb->not_full);
    pthread_mutex_unlock(&rb->lock);
    return record;
}

void* streamProcessRecords(void *arg) {
    RingBuffer *rb = (RingBuffer *)arg;
    while (1) {
        DATA_RECORD_T record = dequeue(rb);
        // Apply transformation function here
        printf("Processed record: ID=%d, Time=%ld, Value=%.2f\n", record.identifier, record.timestamp, record.value);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    RingBuffer rb;
    initRingBuffer(&rb);

    pthread_t thread;
    pthread_create(&thread, NULL, streamProcessRecords, &rb);

    // Simulate incoming records
    for (int i = 0; i < MAX_RECORDS; i++) {
        DATA_RECORD_T record = {i, time(NULL), (double)i * 1.1};
        enqueue(&rb, record);
    }

    pthread_join(thread, NULL);
    return 0;
}
