#define INITIAL_CAPACITY 10

typedef struct {
    char* str;
    int key;
    long offset;
} entry;

typedef struct {
    long* offsets;
    int* keys;
    entry** entries;
    size_t capacity;
    size_t size;
    FILE* log_file;
    pthread_mutex_t lock;
    // Cache mechanism can be implemented here
} data_structures;

data_structures* create_data_structures() {
    data_structures* ds = (data_structures*)malloc(sizeof(data_structures));
    if (!ds) {
        perror("Failed to allocate memory for data structures");
        return NULL;
    }
    ds->offsets = (long*)calloc(INITIAL_CAPACITY, sizeof(long));
    ds->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    ds->entries = (entry**)calloc(INITIAL_CAPACITY, sizeof(entry*));
    if (!ds->offsets || !ds->keys || !ds->entries) {
        perror("Failed to allocate memory for data structures arrays");
        free(ds);
        return NULL;
    }
    ds->capacity = INITIAL_CAPACITY;
    ds->size = 0;
    ds->log_file = fopen("init_log.txt", "w");
    if (!ds->log_file) {
        perror("Failed to open log file");
        free(ds->offsets);
        free(ds->keys);
        free(ds->entries);
        free(ds);
        return NULL;
    }
    pthread_mutex_init(&ds->lock, NULL);
    // Initialize cache mechanism here
    return ds;
}

void destroy_data_structures(data_structures* ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->entries[i]->str);
        free(ds->entries[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->entries);
    fclose(ds->log_file);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void resize_data_structures(data_structures* ds) {
    size_t new_capacity = ds->capacity * 2;
    long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    entry** new_entries = (entry**)realloc(ds->entries, new_capacity * sizeof(entry*));
    if (!new_offsets || !new_keys || !new_entries) {
        perror("Failed to reallocate memory for data structures arrays");
        return;
    }
    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->entries = new_entries;
    ds->capacity = new_capacity;
}

void add_entry(data_structures* ds, const char* str, int key, long offset) {
    pthread_mutex_lock(&ds->lock);
    if (ds->size == ds->capacity) {
        resize_data_structures(ds);
    }
    entry* new_entry = (entry*)malloc(sizeof(entry));
    if (!new_entry) {
        perror("Failed to allocate memory for new entry");
        pthread_mutex_unlock(&ds->lock);
        return;
    }
    new_entry->str = strdup(str);
    new_entry->key = key;
    new_entry->offset = offset;
    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;
    ds->entries[ds->size++] = new_entry;
    fprintf(ds->log_file, "Added entry with key %d and offset %ld\n", key, offset);
    pthread_mutex_unlock(&ds->lock);
}

// Additional functions for accessing and managing the data structures can be implemented here
