#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 1000
#define METADATA_SIZE_LIMIT 256

typedef struct {
    int timestamp;
    int packet_id;
    int payload_length;
    char metadata[METADATA_SIZE_LIMIT];
} DataPacket;

typedef struct {
    DataPacket *packets;
    int count;
    int capacity;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->packets = (DataPacket *)malloc(MAX_PACKETS * sizeof(DataPacket));
    if (!manager->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = MAX_PACKETS;
}

void add_packet(PacketManager *manager, int timestamp, int packet_id, int payload_length, const char *metadata) {
    if (manager->count >= manager->capacity) {
        fprintf(stderr, "Packet limit reached\n");
        return;
    }
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i].packet_id == packet_id) {
            fprintf(stderr, "Duplicate packet ID\n");
            return;
        }
    }
    if (strlen(metadata) > METADATA_SIZE_LIMIT) {
        fprintf(stderr, "Metadata size exceeds limit\n");
        return;
    }
    manager->packets[manager->count].timestamp = timestamp;
    manager->packets[manager->count].packet_id = packet_id;
    manager->packets[manager->count].payload_length = payload_length;
    strcpy(manager->packets[manager->count].metadata, metadata);
    manager->count++;
}

void update_packet(PacketManager *manager, int packet_id, int new_timestamp, int new_payload_length, const char *new_metadata) {
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i].packet_id == packet_id) {
            if (strlen(new_metadata) > METADATA_SIZE_LIMIT) {
                fprintf(stderr, "Metadata size exceeds limit\n");
                return;
            }
            manager->packets[i].timestamp = new_timestamp;
            manager->packets[i].payload_length = new_payload_length;
            strcpy(manager->packets[i].metadata, new_metadata);
            return;
        }
    }
    fprintf(stderr, "Packet ID not found\n");
}

void retrieve_packets(PacketManager *manager, int start_timestamp, int end_timestamp) {
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i].timestamp >= start_timestamp && manager->packets[i].timestamp <= end_timestamp) {
            printf("Packet ID: %d, Timestamp: %d, Payload Length: %d\n", 
                   manager->packets[i].packet_id, 
                   manager->packets[i].timestamp, 
                   manager->packets[i].payload_length);
        }
    }
}

void compact_packets(PacketManager *manager) {
    int new_count = 0;
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i].packet_id != -1) {
            manager->packets[new_count++] = manager->packets[i];
        }
    }
    memset(&manager->packets[new_count], -1, (manager->count - new_count) * sizeof(DataPacket));
    manager->count = new_count;
}

void statistics(PacketManager *manager) {
    int total_payload_length = 0;
    int max_packet_id = -1;
    int packet_id_count[1000] = {0};
    for (int i = 0; i < manager->count; i++) {
        total_payload_length += manager->packets[i].payload_length;
        if (manager->packets[i].packet_id > max_packet_id) {
            max_packet_id = manager->packets[i].packet_id;
        }
        packet_id_count[manager->packets[i].packet_id]++;
    }
    printf("Number of packets: %d\n", manager->count);
    printf("Average payload length: %.2f\n", (float)total_payload_length / manager->count);
    int most_frequent_packet_id = 0;
    for (int i = 1; i <= max_packet_id; i++) {
        if (packet_id_count[i] > packet_id_count[most_frequent_packet_id]) {
            most_frequent_packet_id = i;
        }
    }
    printf("Most frequent packet ID: %d\n", most_frequent_packet_id);
}

void log_operation(const char *operation) {
    // Log operation to external service
    printf("Logging operation: %s\n", operation);
}

int main() {
    PacketManager manager;
    init_packet_manager(&manager);

    add_packet(&manager, 1633072800, 1, 1024, "Metadata1");
    update_packet(&manager, 1, 1633072805, 2048, "UpdatedMetadata1");
    retrieve_packets(&manager, 1633072800, 1633072805);
    compact_packets(&manager);
    statistics(&manager);

    log_operation("Initialization");
    log_operation("Add Packet");
    log_operation("Update Packet");
    log_operation("Retrieve Packets");
    log_operation("Compact Packets");
    log_operation("Statistics");

    free(manager.packets);
    return 0;
}
