#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <fstream>

class ThreadSafeCollection {
public:
    struct Object {
        std::string name;
        unsigned long id;
        std::vector<int> data;
    };

    void insert(const Object& obj) {
        std::lock_guard<std::mutex> lock(mutex_);
        collection_[obj.id] = obj;
        cv_.notify_one();
    }

    bool remove(unsigned long id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = collection_.find(id);
        if (it != collection_.end()) {
            collection_.erase(it);
            return true;
        }
        return false;
    }

    Object* query(unsigned long id) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this, id] { return !collection_.empty() || collection_.find(id) != collection_.end(); });
        auto it = collection_.find(id);
        if (it != collection_.end()) {
            return &it->second;
        }
        return nullptr;
    }

    void serialize(const std::string& filename) {
        std::ofstream ofs(filename, std::ios::binary);
        for (const auto& pair : collection_) {
            ofs.write(pair.second.name.c_str(), pair.second.name.size());
            ofs.write(reinterpret_cast<const char*>(&pair.second.id), sizeof(unsigned long));
            ofs.write(reinterpret_cast<const char*>(pair.second.data.data()), pair.second.data.size() * sizeof(int));
        }
    }

    void deserialize(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        while (ifs.peek() != EOF) {
            Object obj;
            size_t name_size;
            ifs.read(reinterpret_cast<char*>(&name_size), sizeof(size_t));
            obj.name.resize(name_size);
            ifs.read(&obj.name[0], name_size);
            ifs.read(reinterpret_cast<char*>(&obj.id), sizeof(unsigned long));
            size_t data_size;
            ifs.read(reinterpret_cast<char*>(&data_size), sizeof(size_t));
            obj.data.resize(data_size);
            ifs.read(reinterpret_cast<char*>(obj.data.data()), data_size * sizeof(int));
            insert(obj);
        }
    }

private:
    std::unordered_map<unsigned long, Object> collection_;
    std::mutex mutex_;
    std::condition_variable cv_;
};
