#define MAX_NFAPIS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPICRCArray;

int initNFAPICRCArray(NFAPICRCArray *array, size_t initial_capacity) {
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) return -1;
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    return 0;
}

void freeNFAPICRCArray(NFAPICRCArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_unlock(&array->mutex);
}

int addNFAPICRCEntry(NFAPICRCArray *array, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : MAX_NFAPIS;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    NFAPI_CRC_INDICATION_PDU_T entry = {RX_UE_INFORMATION_TAG, RNTI, rand() % 256};
    array->array[array->size++] = entry;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void updateCRCFlag(NFAPICRCArray *array, uint16_t RNTI, uint8_t new_flag) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RNTI == RNTI) {
            array->array[i].CRC_INDICATION_REL8_TAG = new_flag;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void iterateNFAPICRCArray(NFAPICRCArray *array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        callback(&array->array[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}
