    if (pm->size >= pm->capacity) {
        size_t newCapacity = pm->capacity * 2;
        DataPacket* newPackets = (DataPacket*)realloc(pm->packets, newCapacity * sizeof(DataPacket));
        if (!newPackets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pm->packets = newPackets;
        pm->capacity = newCapacity;
    }
    pm->packets[pm->size++] = packet;
}

void updatePacket(PacketManager* pm, int packetID, DataPacket newPacket) {
    for (size_t i = 0; i < pm->size; ++i) {
