['```javascript
function renderFooterScripts(scripts, debug = false) {
    let html = '';
    const startTimes = {};

    scripts.forEach(script => {
        if (!script.name || !script.code) return;

        const id = `footer-script-${script.name.replace(/[^a-zA-Z0-9]/g, '-')}`;
        startTimes[id] = performance.now();

        try {
            html += `<script id="${id}">${script.code}</script>`;
        } catch (error) {
            console.error(`Error rendering script ${script.name}:`, error);
        }

        if (debug) {
            const endTime = performance.now();
            html += `<!-- Rendered in ${endTime - startTimes[id]}ms -->`;
        }
    });

    return html;
}
