        fprintf(stderr, "Error: Maximum limit breached.\n");
        exit(EXIT_FAILURE);
    }

    size_t total_size = sizeof(int) * num_offsets + sizeof(char*) * num_keys;
    for (int i = 0; i < num_keys; ++i) {
        total_size += strlen(keys[i]) + 1; // Include space for null terminator
    }
