    offsets = (int*)ptr;
    ptr += sizeof(int) * num_offsets;

    keys = (const char**)ptr;
    ptr += sizeof(char*) * num_keys;

    for (int i = 0; i < num_keys; ++i) {
        size_t key_len = strlen(keys[i]) + 1;
        keys[i] = ptr;
        memcpy(ptr, keys[i], key_len);
        ptr += key_len;
    }

    records = (Record**)ptr;
    ptr += sizeof(Record*) * num_keys;

    for (int i = 0; i < num_keys; ++i) {
        records[i] = (Record*)ptr;
        ptr += sizeof(Record);
