typedef struct {
    int value;
} record;

int initialize_arrays(long *offsets, int **keys, record **records, long size) {
    if (size <= 0) {
        return -1; // Invalid input size
    }

    offsets = (long *)malloc(size * sizeof(long));
    if (!offsets) {
        return -2; // Memory allocation failed for offsets
    }

    *keys = (int *)malloc((size / 2) * sizeof(int));
    if (!*keys) {
        free(offsets);
        return -3; // Memory allocation failed for keys
    }

    *records = (record *)malloc((size * 1.1) * sizeof(record));
    if (!*records) {
        free(offsets);
        free(*keys);
        return -4; // Memory allocation failed for records
    }

    // Initialize records with unique values between 1 and 1000
    int used_values[1000] = {0};
    int count = 0;
    while (count < size * 1.1) {
        int value = rand() % 1000 + 1;
        if (!used_values[value - 1]) {
            (*records)[count].value = value;
            used_values[value - 1] = 1;
            count++;
        }
    }

    return 0; // Success
}

void free_arrays(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
