// Java Cryptographic Library

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;

public class CryptoLibrary {
    public static byte[] encrypt(String algorithm, String mode, Key key, byte[] iv, byte[] data) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm + "/" + mode);
        if (iv != null) {
            cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv));
        } else {
            cipher.init(Cipher.ENCRYPT_MODE, key);
        }
        return cipher.doFinal(data);
    }

    public static byte[] decrypt(String algorithm, String mode, Key key, byte[] iv, byte[] encryptedData) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm + "/" + mode);
        if (iv != null) {
            cipher.init(Cipher.DECRYPT_MODE, key, new IvParameterSpec(iv));
        } else {
            cipher.init(Cipher.DECRYPT_MODE, key);
        }
        return cipher.doFinal(encryptedData);
    }

    public static Key generateKey(String algorithm, byte[] keyBytes) {
        return new SecretKeySpec(keyBytes, algorithm);
    }

    // Additional methods for different encryption modes and algorithms
}

// C Cryptographic Library using OpenSSL

#include <openssl/evp.h>
#include <openssl/rand.h>

void encrypt(const char* algorithm, const unsigned char* key, int key_len, const unsigned char* iv, int iv_len, const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt(const char* algorithm, const unsigned char* key, int key_len, const unsigned char* iv, int iv_len, const unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// Additional functions for different encryption modes and algorithms
