    void insertAfterInDynamicList(const std::string& targetString, const std::string& newString) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find(list.begin(), list.end(), targetString);
        if (it != list.end()) {
            it++;
            list.insert(it, newString);
        } else {
            list.push_back(newString);
        }
