int packet_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_packet(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&mutex);
    if (packet_count < MAX_PACKETS) {
        NFAPI_CRC_INDICATION_PDU *new_packet = (NFAPI_CRC_INDICATION_PDU *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        new_packet->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_packet->RNTI = RNTI;
        new_packet->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        new_packet->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        packet_array[packet_count++] = new_packet;
    }
    pthread_mutex_unlock(&mutex);
}

void update_packet(int RNTI, int new_CRCFLAG) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->RNTI == RNTI) {
            packet_array[i]->CRCFLAG = new_CRCFLAG;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU* get_packets_by_range(int start_tag, int end_tag) {
    NFAPI_CRC_INDICATION_PDU *result[MAX_PACKETS];
    int result_count = 0;

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->RX_UE_INFORMATION_TAG >= start_tag && packet_array[i]->RX_UE_INFORMATION_TAG <= end_tag) {
            result[result_count++] = packet_array[i];
        }
    }
    pthread_mutex_unlock(&mutex);

    NFAPI_CRC_INDICATION_PDU *result_packet = (NFAPI_CRC_INDICATION_PDU *)malloc(result_count * sizeof(NFAPI_CRC_INDICATION_PDU));
    for (int i = 0; i < result_count; i++) {
        memcpy(&result_packet[i], result[i], sizeof(NFAPI_CRC_INDICATION_PDU));
    }

    free(result);
    return result_packet;
}

void add_cryptographic_aliases() {
    EVP_add_cipher(EVP_aes_256_gcm());
    EVP_add_digest(EVP_sha384());
}
