typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_ENTRIES];
    int count;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->count = 0;
}

int addEntry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->count >= MAX_ENTRIES) {
        printf("Error: List is full.\n");
        return -1;
    }
    list->data[list->count++] = entry;
    return 0;
}

int removeEntry(DynamicList *list, int RNTI) {
    for (int i = 0; i < list->count; i++) {
        if (list->data[i].RNTI == RNTI) {
            for (int j = i; j < list->count - 1; j++) {
                list->data[j] = list->data[j + 1];
            }
            list->count--;
            return 0;
        }
    }
    printf("Error: Entry with RNTI %d not found.\n", RNTI);
    return -1;
}

int updateCRCFlag(DynamicList *list, int RNTI, int newCRCFLAG) {
    for (int i = 0; i < list->count; i++) {
        if (list->data[i].RNTI == RNTI) {
            list->data[i].CRC_INDICATION_REL8_TAG = newCRCFLAG;
            return 0;
        }
    }
    printf("Error: Entry with RNTI %d not found.\n", RNTI);
    return -1;
}

void iterateList(DynamicList *list, void (*action)(NFAPI_CRC_INDICATION_PDU_T)) {
    for (int i = 0; i < list->count; i++) {
        action(list->data[i]);
    }
}

void printEntry(NFAPI_CRC_INDICATION_PDU_T entry) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
           entry.RX_UE_INFORMATION_TAG, entry.RNTI, entry.CRC_INDICATION_REL8_TAG);
}

int main() {
    DynamicList list;
    initDynamicList(&list);

    NFAPI_CRC_INDICATION_PDU_T newEntry = {1, 2, 3};
    addEntry(&list, newEntry);

    iterateList(&list, printEntry);

    updateCRCFlag(&list, 2, 4);
    removeEntry(&list, 2);

    return 0;
}
