#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 50000
#define MEMORY_POOL_SIZE (MAX_RECORDS * sizeof(record))

typedef struct record {
    long offset;
    int key;
    float value;
} record;

typedef struct hash_table {
    record** buckets;
    size_t size;
    size_t capacity;
} hash_table;

hash_table* create_hash_table(size_t capacity) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    if (!table) return NULL;

    table->buckets = (record**)calloc(capacity, sizeof(record*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = 0;
    table->capacity = capacity;
    return table;
}

void destroy_hash_table(hash_table* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        record* current = table->buckets[i];
        while (current) {
            record* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}

size_t hash_function(int key, size_t capacity) {
    return ((key * 23) % capacity + capacity) % capacity; // Simple hash function
}

int insert_record(hash_table* table, int key, float value) {
    if (table->size >= table->capacity) return -1; // Table is full

    size_t index = hash_function(key, table->capacity);
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) return -2; // Memory allocation failed

    new_record->offset = key * 31 + value * 7; // Custom offset calculation
    new_record->key = key;
    new_record->value = value;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;
    ++table->size;

    return 0; // Success
}

record* find_record(hash_table* table, int key) {
    size_t index = hash_function(key, table->capacity);
    record* current = table->buckets[index];
    while (current) {
        if (current->key == key) return current;
        current = current->next;
    }
    return NULL; // Record not found
}

int serialize_hash_table(hash_table* table, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1; // File open failed

    fwrite(&table->size, sizeof(size_t), 1, file);
    fwrite(&table->capacity, sizeof(size_t), 1, file);

    for (size_t i = 0; i < table->capacity; ++i) {
        record* current = table->buckets[i];
        while (current) {
            fwrite(current, sizeof(record), 1, file);
            current = current->next;
        }
    }

    fclose(file);
    return 0; // Success
}

int deserialize_hash_table(hash_table* table, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1; // File open failed

    size_t size, capacity;
    fread(&size, sizeof(size_t), 1, file);
    fread(&capacity, sizeof(size_t), 1, file);

    if (size > table->capacity || capacity != table->capacity) {
        fclose(file);
        return -2; // Incompatible data
    }

    for (size_t i = 0; i < capacity; ++i) {
        record* current = table->buckets[i];
        while (current) {
            record* next = current->next;
            free(current);
            current = next;
        }
    }

    table->size = size;

    for (size_t i = 0; i < capacity; ++i) {
        record new_record;
        if (fread(&new_record, sizeof(record), 1, file) != 1) {
            fclose(file);
            return -3; // Read error
        }
        insert_record(table, new_record.key, new_record.value);
    }

    fclose(file);
    return 0; // Success
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    hash_table* table = create_hash_table(MAX_RECORDS);
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        int key = rand() % 2000 - 1000; // Random key between -1000 and 1000
        float value = (float)rand() / RAND_MAX * 2000.0f - 1000.0f; // Random value between -1000 and 1000
        if (insert_record(table, key, value) != 0) {
            fprintf(stderr, "Failed to insert record\n");
            destroy_hash_table(table);
            return 1;
        }
    }

    serialize_hash_table(table, "data.bin");

    hash_table* loaded_table = create_hash_table(MAX_RECORDS);
    if (!loaded_table) {
        fprintf(stderr, "Failed to create hash table for loading\n");
        destroy_hash_table(table);
        return 1;
    }

    if (deserialize_hash_table(loaded_table, "data.bin") != 0) {
        fprintf(stderr, "Failed to deserialize data\n");
        destroy_hash_table(table);
        destroy_hash_table(loaded_table);
        return 1;
    }

    record* found_record = find_record(loaded_table, 500); // Example lookup
    if (found_record) {
        printf("Found record: key=%d, value=%.2f\n", found_record->key, found_record->value);
    } else {
        printf("Record not found\n");
    }

    destroy_hash_table(table);
    destroy_hash_table(loaded_table);

    return 0;
}
