typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->offsets = (long*)calloc(initial_capacity, sizeof(long));
    array->keys = (int*)calloc(initial_capacity, sizeof(int));
    array->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    if (!array->offsets || !array->keys || !array->records) {
        free(array);
        return NULL;
    }

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->records[i]);
    }
    free(array->offsets);
    free(array->keys);
    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_record(DynamicArray *array, long offset, int key, Record *record) {
    if (!array || !record) return -1;

    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        long *new_offsets = (long*)realloc(array->offsets, new_capacity * sizeof(long));
        int *new_keys = (int*)realloc(array->keys, new_capacity * sizeof(int));
        Record **new_records = (Record**)realloc(array->records, new_capacity * sizeof(Record*));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->offsets = new_offsets;
        array->keys = new_keys;
        array->records = new_records;
        array->capacity = new_capacity;
    }

    array->offsets[array->size] = offset;
    array->keys[array->size] = key;
    array->records[array->size] = record;
    ++array->size;

    pthread_mutex_unlock(&array->lock);

    return 0;
}

// Additional functions for handling external dependencies, logging, and garbage collection can be implemented here.
