#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SENSOR_ID 100
#define MAX_DEVICE_NAME_LENGTH 50

typedef struct {
    int id;
    float temperature;
    char name[MAX_DEVICE_NAME_LENGTH];
    int error_code;
} device_data;

device_data* devices = NULL;
int device_count = 0;
int max_devices = 0;

void initialize_device_array(int initial_size) {
    if (initial_size <= 0) return;
    max_devices = initial_size;
    devices = (device_data*)malloc(max_devices * sizeof(device_data));
    if (!devices) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void add_device(int id, float temperature, const char* name, int error_code) {
    if (device_count >= max_devices) {
        max_devices *= 2;
        devices = (device_data*)realloc(devices, max_devices * sizeof(device_data));
        if (!devices) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
    }
    device_data new_device = {id, temperature, name, error_code};
    memcpy(&devices[device_count], &new_device, sizeof(device_data));
    device_count++;
}

void update_device(int id, float temperature, const char* name, int error_code) {
    for (int i = 0; i < device_count; i++) {
        if (devices[i].id == id) {
            devices[i].temperature = temperature;
            strncpy(devices[i].name, name, MAX_DEVICE_NAME_LENGTH);
            devices[i].error_code = error_code;
            return;
        }
    }
}

device_data* get_device(int id) {
    for (int i = 0; i < device_count; i++) {
        if (devices[i].id == id) {
            return &devices[i];
        }
    }
    return NULL;
}

void filter_and_average_temperature() {
    float total_temperature = 0;
    int valid_device_count = 0;

    for (int i = 0; i < device_count; i++) {
        if (devices[i].error_code == 0) {
            total_temperature += devices[i].temperature;
            valid_device_count++;
        }
    }

    if (valid_device_count > 0) {
        float average_temperature = total_temperature / valid_device_count;
        printf("Average Temperature: %.2f\n", average_temperature);
    } else {
        printf("No valid devices to calculate average temperature.\n");
    }
}

int main() {
    initialize_device_array(10);

    add_device(1, 25.3, "Device A", 0);
    add_device(2, 27.8, "Device B", 1);
    add_device(3, 26.9, "Device C", 0);

    update_device(1, 25.5, "Updated Device A", 0);

    device_data* device = get_device(3);
    if (device) {
        printf("Device ID: %d, Temperature: %.2f\n", device->id, device->temperature);
    }

    filter_and_average_temperature();

    free(devices);
    return 0;
}
