function copyBufferedData(dataChunks, bytesToCopy) {
    if (bytesToCopy <= 0 || dataChunks.length === 0) {
        return Buffer.alloc(0); // Handle invalid input
    }

    let totalBytes = 0;
    for (let chunk of dataChunks) {
        totalBytes += chunk.length;
    }

    if (totalBytes < bytesToCopy) {
        return Buffer.alloc(0); // Not enough data to copy
    }

    let newBuffer = Buffer.allocUnsafe(bytesToCopy);
    let copiedBytes = 0;

    for (let chunk of dataChunks) {
        if (copiedBytes + chunk.length > bytesToCopy) {
            chunk.copy(newBuffer, copiedBytes, 0, bytesToCopy - copiedBytes);
            break;
        } else {
            chunk.copy(newBuffer, copiedBytes);
            copiedBytes += chunk.length;
        }
    }

    return newBuffer;
}
