int allocate_memory(long **offsets, int **keys, record ***records, size_t max_size) {
    *offsets = (long *)malloc(max_size * sizeof(long));
    *keys = (int *)malloc(max_size * sizeof(int));
    *records = (record **)malloc(max_size * sizeof(record *));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1; // Out of memory
    }

    for (size_t i = 0; i < max_size; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            free_memory(*offsets, *keys, *records, i);
            return -1; // Out of memory
        }

        (*offsets)[i] = i * 8; // Example offset calculation
        (*keys)[i] = get_next_key(); // Assume this function fetches a unique key from an external data source

        if (*keys[i] == -1) {
            free_memory(*offsets, *keys, *records, i);
            return -2; // Failed to get next key
        }

        time_t current_time;
        time(&current_time);
        (*records)[i]->value = i;
        (*records)[i]->timestamp = current_time;
    }

    return 0; // Success
}

void free_memory(long *offsets, int *keys, record **records, size_t used_size) {
    for (size_t i = 0; i < used_size; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

int get_next_key() {
    // Simulate fetching a unique key from an external data source
    static int current_key = 1;
    return current_key++;
}

int main() {
    long *offsets;
    int *keys;
    record **records;
    size_t max_size = 100;

    int result = allocate_memory(&offsets, &keys, &records, max_size);

    if (result == 0) {
        printf("Memory allocation successful.\n");
        // Use the allocated memory here
        free_memory(offsets, keys, records, max_size);
    } else if (result == -1) {
        printf("Out of memory error.\n");
    } else if (result == -2) {
        printf("Failed to get next key from external data source.\n");
    }

    return 0;
}
