#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRC_INDICATION_REL8_TAG; }
#define MAX_ENTRIES 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

void init_crc_list(NFAPI_CRC_LIST *list, size_t initial_capacity) {
    list->entries = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->entries == NULL) {
        perror("Failed to allocate memory for CRC list");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void free_crc_list(NFAPI_CRC_LIST *list) {
    pthread_mutex_lock(&list->lock);
    free(list->entries);
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void add_crc_entry(NFAPI_CRC_LIST *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? MAX_ENTRIES : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_entries == NULL) {
            perror("Failed to reallocate memory for CRC list");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->entries[list->count].RNTI = RNTI;
    list->entries[list->count].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void serialize_crc_list(NFAPI_CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for serialization");
        return;
    }
    size_t written = fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    if (written != list->count) {
        perror("Failed to write to file during serialization");
    }
    fclose(file);
}

int deserialize_crc_list(NFAPI_CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for deserialization");
        return -1;
    }
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t expected_entries = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (expected_entries > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, expected_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_entries == NULL) {
            perror("Failed to reallocate memory for CRC list during deserialization");
            fclose(file);
            return -1;
        }
        list->entries = new_entries;
        list->capacity = expected_entries;
    }

    size_t read_count = fread(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), expected_entries, file);
    if (read_count != expected_entries) {
        perror("Failed to read from file during deserialization");
        fclose(file);
        return -1;
    }
    list->count = read_count;

    fclose(file);
    return 0;
}

void log_operation(const char *operation, int result) {
    if (result == 0) {
        printf("%s succeeded\n", operation);
    } else {
        printf("%s failed with error code %d\n", operation, result);
    }
}
