#include <stdlib.h>
#include <semaphore.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

sem_t state_list_semaphore;

NFAPI_CRC_INDICATION_PDU_T* create_state_list(FSA fsa, int N) {
    sem_wait(&state_list_semaphore);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_state = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_state) {
            sem_post(&state_list_semaphore);
            free_list(head);
            return NULL;
        }

        new_state->rx_ue_info = get_rx_ue_info(fsa, i); // Assume this function exists
        new_state->rnti = get_rnti(fsa, i); // Assume this function exists
        new_state->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

        if (head == NULL) {
            head = new_state;
            current = new_state;
        } else {
            current->next = new_state;
            current = new_state;
        }
    }

    current->next = head; // Circular linked list for state transitions

    sem_post(&state_list_semaphore);
    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
}

void initialize_semaphore() {
    sem_init(&state_list_semaphore, 0, 1); // Binary semaphore for thread safety
}

void destroy_semaphore() {
    sem_destroy(&state_list_semaphore);
}
