#define INITIAL_BUFFER_SIZE 1024
#define GARBAGE_COLLECTION_INTERVAL 60

typedef struct {
    char *buffer;
    size_t length;
} entry;

typedef struct {
    entry **buckets;
    size_t capacity;
    size_t size;
} hash_table;

hash_table *create_hash_table(size_t initial_capacity) {
    hash_table *table = (hash_table *)malloc(sizeof(hash_table));
    table->buckets = (entry **)calloc(initial_capacity, sizeof(entry *));
    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

void destroy_hash_table(hash_table *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        entry *e = table->buckets[i];
        if (e != NULL) {
            free(e->buffer);
            free(e);
        }
    }
    free(table->buckets);
    free(table);
}

size_t hash_function(size_t index, size_t capacity) {
    return index % capacity;
}

void insert_entry(hash_table *table, entry *e, size_t index) {
    if (table->size >= table->capacity / 2) {
        // Resize the hash table
        size_t new_capacity = table->capacity * 2;
        entry **new_buckets = (entry **)calloc(new_capacity, sizeof(entry *));
        for (size_t i = 0; i < table->capacity; ++i) {
            if (table->buckets[i] != NULL) {
                size_t new_index = hash_function(table->buckets[i]->length, new_capacity);
                while (new_buckets[new_index] != NULL) {
                    new_index = (new_index + 1) % new_capacity;
                }
                new_buckets[new_index] = table->buckets[i];
            }
        }
        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }

    size_t index_in_table = hash_function(index, table->capacity);
    while (table->buckets[index_in_table] != NULL) {
        index_in_table = (index_in_table + 1) % table->capacity;
    }
    table->buckets[index_in_table] = e;
    ++table->size;
}

entry *get_entry(hash_table *table, size_t index) {
    size_t index_in_table = hash_function(index, table->capacity);
    while (table->buckets[index_in_table] != NULL && table->buckets[index_in_table]->length != index) {
        index_in_table = (index_in_table + 1) % table->capacity;
    }
    return table->buckets[index_in_table];
}

void garbage_collection(hash_table *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        entry *e = table->buckets[i];
        if (e != NULL && e->length == 0) {
            free(e->buffer);
            free(e);
            table->buckets[i] = NULL;
            --table->size;
        }
    }
}

void log_error(const char *error_type, size_t entry_index) {
    time_t now = time(NULL);
    printf("Error at %s: Entry index %zu - %s\n", ctime(&now), entry_index, error_type);
}
