} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    sem_t semaphore;
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T **cache;
    int cache_size;
} StateManager;

NFAPI_CRC_INDICATION_PDU_T* create_state_list(int states[], int num_states, FSA *fsa, int last_state, int concurrency_level, bool use_thread_pool) {
    StateManager manager = {0};
    sem_init(&manager.semaphore, 0, concurrency_level);
    manager.cache_size = concurrency_level;
    manager.cache = (NFAPI_CRC_INDICATION_PDU_T**)malloc(manager.cache_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!manager.cache) {
        return NULL;
    }

    for (int i = 0; i < manager.cache_size; ++i) {
        manager.cache[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager.cache[i]) {
            // Clean up allocated memory
            for (int j = 0; j < i; ++j) {
                free(manager.cache[j]);
            }
            free(manager.cache);
            return NULL;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *current = NULL, *new_state;
    for (int i = 0; i < num_states; ++i) {
        sem_wait(&manager.semaphore);
        new_state = manager.cache[i];
        // Initialize new_state with data from fsa and states array
        new_state->rx_ue_info = get_rx_ue_info_from_fsa(fsa, states[i]);
        new_state->rnti = get_rnti_from_fsa(fsa, states[i]);
        new_state->crc_indication.crcflag = generate_random_crc_flag();
        new_state->next = NULL;

        if (!current) {
            manager.head = current = new_state;
        } else {
            current->next = new_state;
            current = new_state;
        }
    }

    sem_destroy(&manager.semaphore);
    free(manager.cache);

    return manager.head;
}
