    // Check if environment variable is already set
    char *env_path = getenv("TEMP_DIR_PATH");
    if (env_path == NULL) {
        // Create a new directory
        env_path = strdup(path);
        mkdir(env_path, 0755);

        // Set the environment variable
        putenv(strdup("TEMP_DIR_PATH="));
        setenv("TEMP_DIR_PATH", env_path, 1);
    }

    // Allocate memory for records and initialize with random values
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % 1000; // Random value between 0 and 999
    }

    // Allocate memory for offsets and keys
    offsets = (long *)malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        free(*records);
        exit(EXIT_FAILURE);
    }
    keys = (int *)malloc(num_records * sizeof(int));
    if (keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        free(*records);
        exit(EXIT_FAILURE);
    }

    // Populate offsets and keys with random values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000000L; // Random value between 0 and 999999
        keys[i] = rand() % 1000; // Random value between 0 and 999
    }

    // Cleanup resources when no longer needed
    free(offsets);
    free(keys);
    free(*records);

    // Remove the directory when done
    rmdir(env_path);
    unsetenv("TEMP_DIR_PATH");
    free(env_path);
