#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} LongIntPair;

typedef struct {
    float precision;
    double timestamp;
} FloatDoublePair;

typedef struct {
    void* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = malloc(initial_capacity * sizeof(void*));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]);
    }
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    void** new_data = realloc(array->data, new_capacity * sizeof(void*));
    if (!new_data) return -1;

    array->data = new_data;
    array->capacity = new_capacity;
    return 0;
}

int add_to_dynamic_array(DynamicArray* array, void* item) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity && resize_dynamic_array(array, array->capacity * 2) != 0) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int initialize_data_structures(size_t long_int_size, size_t float_double_size, int min_precision, int max_precision) {
    DynamicArray* long_int_array = create_dynamic_array(long_int_size);
    if (!long_int_array) return -1;

    DynamicArray* float_double_array = create_dynamic_array(float_double_size);
    if (!float_double_array) {
        destroy_dynamic_array(long_int_array);
        return -1;
    }

    srand(time(NULL));

    for (size_t i = 0; i < long_int_size; ++i) {
        LongIntPair* pair = (LongIntPair*)malloc(sizeof(LongIntPair));
        if (!pair) {
            destroy_dynamic_array(long_int_array);
            destroy_dynamic_array(float_double_array);
            return -1;
        }

        pair->offset = rand();
        pair->key = rand() % 100; // Assuming key range is 0-99
        add_to_dynamic_array(long_int_array, pair);
    }

    for (size_t i = 0; i < float_double_size; ++i) {
        FloatDoublePair* pair = (FloatDoublePair*)malloc(sizeof(FloatDoublePair));
        if (!pair) {
            destroy_dynamic_array(long_int_array);
            destroy_dynamic_array(float_double_array);
            return -1;
        }

        pair->precision = ((float)(rand() % (max_precision - min_precision + 1)) + min_precision) / 10.0f; // Assuming precision range is 0-max_precision
        pair->timestamp = time(NULL) + rand() % 3600; // Timestamp within the last hour

        if (pair->precision < 0 || pair->timestamp <= 0) {
            free(pair);
            destroy_dynamic_array(long_int_array);
            destroy_dynamic_array(float_double_array);
            return -1;
        }

        add_to_dynamic_array(float_double_array, pair);
    }

    // Log initialization steps and validation checks
    // ...

    destroy_dynamic_array(long_int_array);
    destroy_dynamic_array(float_double_array);

    return 0;
}
