#include <stdlib.h>
#include <pthread.h>

typedef struct TCPConnection {
    uint32_t TSN;
    uint32_t ACK;
    int FlowControlFlag;
    struct TCPConnection* next;
} TCPConnection;

typedef struct ConnectionList {
    TCPConnection* head;
    pthread_mutex_t mutex;
} ConnectionList;

TCPConnection* createTCPConnection(uint32_t TSN, uint32_t ACK, int FlowControlFlag) {
    TCPConnection* newConn = (TCPConnection*)malloc(sizeof(TCPConnection));
    if (newConn == NULL) {
        return NULL; // Insufficient memory
    }
    newConn->TSN = TSN;
    newConn->ACK = ACK;
    newConn->FlowControlFlag = FlowControlFlag;
    newConn->next = NULL;
    return newConn;
}

int addConnection(ConnectionList* list, TCPConnection* conn) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = conn;
    } else {
        TCPConnection* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = conn;
    }
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void initializeConnectionList(ConnectionList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void deleteConnectionList(ConnectionList* list) {
    pthread_mutex_lock(&list->mutex);
    TCPConnection* current = list->head;
    while (current != NULL) {
        TCPConnection* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
