#define INITIAL_POOL_SIZE 1024

typedef struct {
    int value;
    char *data;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    char *buffer_pool;
    size_t buffer_size;
    size_t pool_size;
    size_t used_records;
    pthread_mutex_t lock;
} record_pool;

record_pool* create_record_pool(size_t initial_buffer_size) {
    record_pool *pool = (record_pool*)malloc(sizeof(record_pool));
    if (!pool) return NULL;

    pool->offsets = (long*)calloc(initial_pool_size, sizeof(long));
    pool->keys = (int*)calloc(initial_pool_size, sizeof(int));
    pool->records = (record**)calloc(initial_pool_size, sizeof(record*));
    pool->buffer_pool = (char*)malloc(initial_buffer_size);
    if (!pool->offsets || !pool->keys || !pool->records || !pool->buffer_pool) {
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool->buffer_pool);
        free(pool);
        return NULL;
    }

    pool->buffer_size = initial_buffer_size;
    pool->pool_size = initial_pool_size;
    pool->used_records = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_record_pool(record_pool *pool) {
    for (size_t i = 0; i < pool->used_records; ++i) {
        free(pool->records[i]->data);
        free(pool->records[i]);
    }
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool->buffer_pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void resize_record_pool(record_pool *pool, size_t new_size) {
    pool->offsets = (long*)realloc(pool->offsets, new_size * sizeof(long));
    pool->keys = (int*)realloc(pool->keys, new_size * sizeof(int));
    pool->records = (record**)realloc(pool->records, new_size * sizeof(record*));
    if (!pool->offsets || !pool->keys || !pool->records) {
        // Handle error: reallocation failed
        return;
    }
    pool->pool_size = new_size;
}

void evict_oldest_record(record_pool *pool) {
    size_t oldest_index = 0;
    for (size_t i = 1; i < pool->used_records; ++i) {
        if (pool->offsets[i] < pool->offsets[oldest_index]) {
            oldest_index = i;
        }
    }

    free(pool->records[oldest_index]->data);
    free(pool->records[oldest_index]);
    pool->records[oldest_index] = NULL;

    for (size_t i = oldest_index; i < pool->used_records - 1; ++i) {
        pool->offsets[i] = pool->offsets[i + 1];
        pool->keys[i] = pool->keys[i + 1];
        pool->records[i] = pool->records[i + 1];
    }

    --pool->used_records;
}

void add_record(record_pool *pool, int key, int value, const char *data) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_records == pool->pool_size) {
        resize_record_pool(pool, pool->pool_size * 2);
    }

    size_t index = pool->used_records;
    pool->offsets[index] = time(NULL); // Assuming time() returns a unique offset
    pool->keys[index] = key;

    record *new_record = (record*)malloc(sizeof(record));
    new_record->value = value;
    new_record->data = strdup(data);
    if (!new_record || !new_record->data) {
        free(new_record);
        pthread_mutex_unlock(&pool->lock);
        return; // Handle error: memory allocation failed
    }

    pool->records[index] = new_record;
    ++pool->used_records;

    pthread_mutex_unlock(&pool->lock);
}

void update_record(record_pool *pool, int key, int value, const char *data) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->used_records; ++i) {
        if (pool->keys[i] == key) {
            free(pool->records[i]->data);
            pool->records[i]->value = value;
            pool->records[i]->data = strdup(data);
            pthread_mutex_unlock(&pool->lock);
            return;
        }
    }

    // If record not found, add it
    add_record(pool, key, value, data);

    pthread_mutex_unlock(&pool->lock);
}

void remove_record(record_pool *pool, int key) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->used_records; ++i) {
        if (pool->keys[i] == key) {
            free(pool->records[i]->data);
            free(pool->records[i]);
            pool->records[i] = NULL;

            for (size_t j = i; j < pool->used_records - 1; ++j) {
                pool->offsets[j] = pool->offsets[j + 1];
                pool->keys[j] = pool->keys[j + 1];
                pool->records[j] = pool->records[j + 1];
            }

            --pool->used_records;
            pthread_mutex_unlock(&pool->lock);
            return;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}
