import csv
from collections import deque
import threading
import time

class DataProcessor:
    def __init__(self, max_memory_size=1024):
        self.max_memory_size = max_memory_size
        self.memory_used = 0
        self.data_queue = deque()
        self.processing_thread = threading.Thread(target=self.process_data)
        self.processing_thread.daemon = True
        self.processing_thread.start()

    def add_data(self, data):
        if isinstance(data, int):
            size = 4  # Assuming integer size is 4 bytes
        elif isinstance(data, str):
            size = len(data) * 2  # Assuming each character takes 2 bytes
        else:
            raise ValueError("Unsupported data type")

        if self.memory_used + size > self.max_memory_size:
            print("Memory limit exceeded. Processing paused.")
            return

        self.data_queue.append(data)
        self.memory_used += size

    def process_data(self):
        while True:
            if not self.data_queue:
                time.sleep(0.1)  # Sleep to avoid busy-waiting
                continue

            data = self.data_queue.popleft()
            self.memory_used -= self.get_size(data)

            if isinstance(data, int):
                print(f"Processing integer: {data}")
            elif isinstance(data, str):
                print(f"Processing string: {data}")

    def get_size(self, data):
        if isinstance(data, int):
            return 4
        elif isinstance(data, str):
            return len(data) * 2

# Example usage
