#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int data;
} Record;

typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_index = 0;

    pool->pool = malloc(block_size * num_blocks);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool->free_index >= pool->num_blocks) return NULL;
    void* block = (char*)pool->pool + pool->block_size * pool->free_index;
    pool->free_index++;
    return block;
}

void free_to_pool(MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index < pool->num_blocks && index >= pool->free_index) {
        pool->free_index = index + 1;
    }
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    free(pool);
}

Record* initialize_records(size_t num_records, int seed, int min_val, int max_val, MemoryPool* pool) {
    srand(seed);

    Record* records = (Record*)allocate_from_pool(pool);
    if (!records) return NULL;

    long* offsets = (long*)allocate_from_pool(pool);
    if (!offsets) {
        free_to_pool(pool, records);
        return NULL;
    }

    int* keys = (int*)allocate_from_pool(pool);
    if (!keys) {
        free_to_pool(pool, offsets);
        free_to_pool(pool, records);
        return NULL;
    }

    for (size_t i = 0; i < num_records; i++) {
        records[i].data = rand() % (max_val - min_val + 1) + min_val;
        offsets[i] = 0;
        keys[i] = 0;
    }

    return records;
}

void cleanup(MemoryPool* pool, Record* records, long* offsets, int* keys) {
    free_to_pool(pool, records);
    free_to_pool(pool, offsets);
    free_to_pool(pool, keys);
    destroy_memory_pool(pool);
}
