#define MAX_ENTRIES 10000
#define INITIAL_ALLOC_SIZE 100
#define COMPACT_THRESHOLD 0.2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** list = NULL;
int allocated_size = 0;
int current_size = 0;

void log_memory_event(const char* event) {
    printf("%s\n", event);
}

void allocate_list(int initial_size) {
    list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list.\n");
        exit(EXIT_FAILURE);
    }
    allocated_size = initial_size;
    current_size = 0;
}

void compact_list() {
    int new_size = (int)(current_size / COMPACT_THRESHOLD);
    NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!new_list) {
        fprintf(stderr, "Memory reallocation failed for list.\n");
        exit(EXIT_FAILURE);
    }
    list = new_list;
    allocated_size = new_size;
}

void add_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (current_size >= allocated_size) {
        allocate_list(allocated_size * 2);
    }
    list[current_size] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list[current_size]) {
        fprintf(stderr, "Memory allocation failed for entry.\n");
        exit(EXIT_FAILURE);
    }
    list[current_size]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list[current_size]->RNTI = RNTI;
    list[current_size]->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    current_size++;
}

void free_list() {
    for (int i = 0; i < current_size; i++) {
        free(list[i]);
    }
    free(list);
    list = NULL;
    allocated_size = 0;
    current_size = 0;
}

int main() {
    srand(time(NULL));
    allocate_list(INITIAL_ALLOC_SIZE);

    for (int i = 0; i < MAX_ENTRIES; i++) {
        int RNTI = rand() % 1024 + 1; // Valid range: 1-1024
        if (i > 0) {
            while (list[i - 1]->RNTI == RNTI) {
                RNTI = rand() % 1024 + 1;
            }
        }
        add_entry(i, RNTI, rand() % 2); // Random CRCFLAG
    }

    if ((double)current_size / allocated_size < COMPACT_THRESHOLD) {
        compact_list();
    }

    free_list();

    return 0;
}
