#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    pthread_mutex_t lock;
    size_t used_records;
    size_t memory_usage;
    size_t max_memory_usage;
    void (*callback)(int, long);
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size, int seed, int min_value, int max_value, size_t max_memory, void (*cb)(int, long)) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->used_records = 0;
    pool->memory_usage = 0;
    pool->max_memory_usage = max_memory;
    pool->callback = cb;

    pthread_mutex_init(&pool->lock, NULL);

    srand(seed);
    for (size_t i = 0; i < initial_size && i < MAX_RECORDS; ++i) {
        Record *record = &pool->records[i];
        record->key = rand() % (max_value - min_value + 1) + min_value;
        record->offset = 0; // Initialize offset to zero
        pool->memory_usage += sizeof(Record);
    }

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record* get_record(MemoryPool *pool, size_t index) {
    if (index >= MAX_RECORDS || index >= pool->used_records) return NULL;

    Record *record = &pool->records[index];
    if (pool->callback) {
        pool->callback(record->key, record->offset);
    }

    return record;
}

void* memory_pool_get_first_record(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *first_record = pool->records;
    pthread_mutex_unlock(&pool->lock);

    return first_record;
}
