void parse_config(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file.\n");
        return;
    }

    json_object* config = json_tokener_parse_file(filename);
    if (!config) {
        fprintf(stderr, "Failed to parse JSON configuration.\n");
        fclose(file);
        return;
    }

    // Example parsing logic
    json_object* double_array = json_object_object_get_ex(config, "doubles", NULL);
    json_object* char_array = json_object_object_get_ex(config, "chars", NULL);
    json_object* point_array = json_object_object_get_ex(config, "points", NULL);

    if (double_array && json_object_is_type(double_array, json_type_array)) {
        int len = json_object_array_length(double_array);
        double* doubles = malloc(len * sizeof(double));
        for (int i = 0; i < len; ++i) {
            doubles[i] = json_object_get_double(json_object_array_get_idx(double_array, i));
        }
        // Use the doubles array
        free(doubles);
    }

    if (char_array && json_object_is_type(char_array, json_type_array)) {
        int len = json_object_array_length(char_array);
        char** chars = malloc(len * sizeof(char*));
        for (int i = 0; i < len; ++i) {
            chars[i] = strdup(json_object_get_string(json_object_array_get_idx(char_array, i)));
        }
        // Use the chars array
        for (int i = 0; i < len; ++i) {
            free(chars[i]);
        }
        free(chars);
    }

    if (point_array && json_object_is_type(point_array, json_type_array)) {
        int len = json_object_array_length(point_array);
        point* points = malloc(len * sizeof(point));
        for (int i = 0; i < len; ++i) {
            json_object* point_obj = json_object_array_get_idx(point_array, i);
            double x = json_object_get_double(json_object_object_get_ex(point_obj, "x", NULL));
            double y = json_object_get_double(json_object_object_get_ex(point_obj, "y", NULL));
            points[i] = (point){x, y};
        }
        // Use the points array
        free(points);
    }

    if (config) {
        json_object_put(config);
    }
    fclose(file);
}

int main() {
    parse_config("config.json");
    return 0;
}
