int serializeRecords(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&recordsMutex);
    for (int i = 0; i < recordCount; i++) {
        fwrite(records[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&recordsMutex);

    fclose(file);
    return 0;
}

void freeRecords() {
    pthread_mutex_lock(&recordsMutex);
    for (int i = 0; i < recordCount; i++) {
        free(records[i]);
    }
    recordCount = 0;
    pthread_mutex_unlock(&recordsMutex);
}

int populateRecords(int maxRecords, int startRNTI, int endRNTI) {
    if (maxRecords <= 0 || startRNTI > endRNTI) return -1;

    srand(time(NULL));
