} PacketManager;

void init_packet_manager(PacketManager *manager, size_t initial_capacity) {
    manager->packets = (DataPacket **)malloc(initial_capacity * sizeof(DataPacket *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_packet_manager(PacketManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i]->metadata);
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
}

int add_packet(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->packet_id == packet->packet_id) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate packet ID
        }
    }
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        DataPacket **new_packets = (DataPacket **)realloc(manager->packets, new_capacity * sizeof(DataPacket *));
        if (!new_packets) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

