    int index = getUserIndex(hashTable, userStats.UserID);
    if (hashTable->userStats[index].UserID == 0) { // Assuming UserID 0 is unused
        hashTable->userStats[index] = userStats;
        hashTable->size++;
    }
    pthread_mutex_unlock(&hashTable->lock);
