void deleteUserStats(HASH_TABLE_T *hashTable, int UserID) {
    pthread_mutex_lock(&hashTable->lock);
    int index = getUserIndex(hashTable, UserID);
    if (hashTable->userStats[index].UserID != 0) { // Assuming UserID 0 is unused
        memset(&hashTable->userStats[index], 0, sizeof(USER_STATS_T));
