#include <stdlib.h>
#include <string.h>

typedef struct {
    uint64_t timestamp;
    uint32_t packet_id;
    size_t payload_length;
    unsigned char *encrypted_payload;
} DataPacket;

typedef struct {
    uint64_t offset;
    int key;
    void *record;
} RecordSegment;

typedef struct {
    DataPacket **packets;
    RecordSegment *segments;
    pthread_mutex_t lock;
    size_t packet_count;
    size_t segment_count;
} DistributedDataSystem;

DistributedDataSystem* create_system(size_t initial_size) {
    DistributedDataSystem *system = (DistributedDataSystem*)malloc(sizeof(DistributedDataSystem));
    system->packets = (DataPacket**)calloc(initial_size, sizeof(DataPacket*));
    system->segments = (RecordSegment*)calloc(initial_size, sizeof(RecordSegment));
    pthread_mutex_init(&system->lock, NULL);
    system->packet_count = 0;
    system->segment_count = 0;
    return system;
}

void destroy_system(DistributedDataSystem *system) {
    for (size_t i = 0; i < system->packet_count; ++i) {
        free(system->packets[i]->encrypted_payload);
        free(system->packets[i]);
    }
    free(system->packets);
    for (size_t i = 0; i < system->segment_count; ++i) {
        free(system->segments[i].record);
    }
    free(system->segments);
    pthread_mutex_destroy(&system->lock);
    free(system);
}

void add_packet(DistributedDataSystem *system, DataPacket *packet) {
    pthread_mutex_lock(&system->lock);
    if (system->packet_count >= system->segment_count) {
        // Handle overflow or reallocation strategy
        system->segments = realloc(system->segments, system->segment_count * 2 * sizeof(RecordSegment));
        system->segment_count *= 2;
    }
    system->segments[system->packet_count].record = packet;
    ++system->packet_count;
    pthread_mutex_unlock(&system->lock);
}

void add_segment(DistributedDataSystem *system, RecordSegment segment) {
    pthread_mutex_lock(&system->lock);
    if (system->segment_count >= system->segment_count) {
        // Handle overflow or reallocation strategy
        system->segments = realloc(system->segments, system->segment_count * 2 * sizeof(RecordSegment));
        system->segment_count *= 2;
    }
    system->segments[system->segment_count] = segment;
    ++system->segment_count;
    pthread_mutex_unlock(&system->lock);
}

