    LongIntStruct* longArray = (LongIntStruct*)malloc(longSize * sizeof(LongIntStruct));
    if (!longArray) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        return -1;
    }

    FloatDoubleStruct* floatArray = (FloatDoubleStruct*)malloc(floatSize * sizeof(FloatDoubleStruct));
    if (!floatArray) {
        fprintf(stderr, "Memory allocation failed for float array\n");
        free(longArray);
        return -2;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < longSize; i++) {
        longArray[i].offset = rand();
        longArray[i].key = rand() % 100;
    }

    for (int i = 0; i < floatSize; i++) {
        floatArray[i].precision = ((float)rand() / RAND_MAX) * 100.0f;
        floatArray[i].timestamp = time(NULL);
    }

    // Log successful allocations
    printf("Long array initialized successfully\n");
    printf("Float array initialized successfully\n");

    free(longArray);
    free(floatArray);

    return 0;
}

// Function to validate timestamps and precision values
int validateData(FloatDoubleStruct* floatArray, int size) {
    for (int i = 0; i < size; i++) {
        if (floatArray[i].timestamp <= 0 || floatArray[i].precision < 0) {
            fprintf(stderr, "Validation failed: Invalid timestamp or precision value\n");
            return -1;
        }
    }
    return 0;
}

// Main function to demonstrate usage
int main() {
    int longSize = 100;
    int floatSize = 50;

    if (initializeDataStructures(longSize, floatSize) == 0) {
        FloatDoubleStruct* floatArray = (FloatDoubleStruct*)malloc(floatSize * sizeof(FloatDoubleStruct));
        if (!floatArray) {
            fprintf(stderr, "Memory allocation failed for float array\n");
            return -1;
        }

        // Populate floatArray with data
        srand(time(NULL));
        for (int i = 0; i < floatSize; i++) {
            floatArray[i].precision = ((float)rand() / RAND_MAX) * 100.0f;
            floatArray[i].timestamp = time(NULL);
        }

        if (validateData(floatArray, floatSize) == 0) {
            // Process data
            for (int i = 0; i < floatSize; i++) {
                printf("Precision: %.2f, Timestamp: %ld\n", floatArray[i].precision, floatArray[i].timestamp);
            }
        }

        free(floatArray);
    }

    return 0;
}
