#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>

class UserProfile {
public:
    std::string username;
    std::unordered_map<std::string, std::string> preferences;
    std::vector<std::string> friends;

    UserProfile(const std::string& username) : username(username) {}
};

class DistributedProfileManager {
private:
    std::unordered_map<std::string, UserProfile> cache;
    std::mutex cacheMutex;
    std::condition_variable cacheCondVar;
    std::atomic<bool> stopFlag{false};
    std::vector<std::thread> workerThreads;

public:
    void startCacheWorker(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back(&DistributedProfileManager::cacheWorker, this);
        }
    }

    void stopCacheWorker() {
        stopFlag.store(true);
        cacheCondVar.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    UserProfile getUserProfile(const std::string& username) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = cache.find(username);
        if (it != cache.end()) {
            return it->second;
        } else {
            // Fetch from external data store and update cache
            UserProfile profile = fetchFromExternalStore(username);
            cache[username] = profile;
            return profile;
        }
    }

    void updateUserProfile(const std::string& username, const UserProfile& newProfile) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cache.find(username) != cache.end()) {
            cache[username] = newProfile;
        } else {
            // Update external data store directly
            updateExternalStore(username, newProfile);
        }
    }

private:
    UserProfile fetchFromExternalStore(const std::string& username) {
        // Simulate fetching from external data store
        return UserProfile(username);
    }

    void updateExternalStore(const std::string& username, const UserProfile& profile) {
        // Simulate updating external data store
    }

    void cacheWorker() {
        while (!stopFlag.load()) {
            std::unique_lock<std::mutex> lock(cacheMutex);
            cacheCondVar.wait(lock, [this] { return !cache.empty() || stopFlag.load(); });
            if (stopFlag.load()) break;
            auto it = cache.begin();
            UserProfile profile = it->second;
            cache.erase(it);
            lock.unlock();

            // Process the profile (e.g., update external store)
            updateExternalStore(profile.username, profile);
        }
    }
};

int main() {
    DistributedProfileManager manager;
    manager.startCacheWorker(4);

    UserProfile newUser("john_doe");
    newUser.preferences["theme"] = "dark";
    newUser.friends.push_back("jane_smith");

    manager.updateUserProfile(newUser.username, newUser);

    UserProfile retrievedUser = manager.getUserProfile(newUser.username);
    std::cout << "Retrieved User: " << retrievedUser.username << ", Theme: " << retrievedUser.preferences["theme"] << std::endl;

    manager.stopCacheWorker();
    return 0;
}
