#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000000

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

Node* head = NULL;

void insertRecord(long offset, int key, int value) {
    if (head == NULL || key < head->data.key) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data.offset = offset;
        newNode->data.key = key;
        newNode->data.value = value;
        newNode->next = head;
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL && current->next->data.key < key) {
            current = current->next;
        }
        if (current->data.key == key) {
            printf("Duplicate key detected.\n");
            return;
        }
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data.offset = offset;
        newNode->data.key = key;
        newNode->data.value = value;
        newNode->next = current->next;
        current->next = newNode;
    }
}

void removeRecord(int key) {
    if (head == NULL) return;
    if (head->data.key == key) {
        Node* temp = head;
        head = head->next;
        free(temp);
        return;
    }
    Node* current = head;
    while (current->next != NULL && current->next->data.key < key) {
        current = current->next;
    }
    if (current->next == NULL || current->next->data.key != key) {
        printf("Key not found.\n");
        return;
    }
    Node* temp = current->next;
    current->next = current->next->next;
    free(temp);
}

Node* findRecord(int key) {
    Node* current = head;
    while (current != NULL && current->data.key < key) {
        current = current->next;
    }
    if (current == NULL || current->data.key != key) {
        return NULL;
    }
    return current;
}

void filterRecords(long offset, int value) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.offset == offset && current->data.value == value) {
            printf("Found record: Offset=%ld, Key=%d, Value=%d\n", current->data.offset, current->data.key, current->data.value);
        }
        current = current->next;
    }
}

int main() {
    srand(time(0));
    for (int i = 0; i < MAX_RECORDS; i++) {
        insertRecord(rand(), rand(), rand());
    }

    Node* found = findRecord(rand());
    if (found != NULL) {
        printf("Found record: Offset=%ld, Key=%d, Value=%d\n", found->data.offset, found->data.key, found->data.value);
    } else {
        printf("Record not found.\n");
    }

    filterRecords(rand(), rand());

    return 0;
}
