PacketManager packet_manager;
PacketCache packet_cache;

void init_packet_manager() {
    packet_manager.packets = (DataPacket *)malloc(MAX_PACKETS * sizeof(DataPacket));
    if (!packet_manager.packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    packet_manager.size = 0;
    packet_manager.capacity = MAX_PACKETS;
    pthread_mutex_init(&packet_manager.lock, NULL);
}

void init_packet_cache() {
    pthread_mutex_init(&packet_cache.lock, NULL);
}

void add_packet(DataPacket *new_packet) {
    pthread_mutex_lock(&packet_manager.lock);
    if (packet_manager.size >= packet_manager.capacity) {
        fprintf(stderr, "Memory overflow\n");
        pthread_mutex_unlock(&packet_manager.lock);
        return;
    }
    packet_manager.packets[packet_manager.size++] = *new_packet;
    pthread_mutex_unlock(&packet_manager.lock);
}

void update_packet(int packet_id, DataPacket *updated_packet) {
    pthread_mutex_lock(&packet_manager.lock);
    for (int i = 0; i < packet_manager.size; i++) {
        if (packet_manager.packets[i].packet_id == packet_id) {
            packet_manager.packets[i] = *updated_packet;
            pthread_mutex_unlock(&packet_manager.lock);
            return;
        }
    }
    fprintf(stderr, "Packet ID not found\n");
    pthread_mutex_unlock(&packet_manager.lock);
}

void get_packets_by_timestamp_range(int start_time, int end_time, DataPacket **result, int *count) {
    pthread_mutex_lock(&packet_manager.lock);
    *count = 0;
    for (int i = 0; i < packet_manager.size; i++) {
        if (packet_manager.packets[i].timestamp >= start_time && packet_manager.packets[i].timestamp <= end_time) {
            result[*count] = &packet_manager.packets[i];
            (*count)++;
        }
    }
