#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define RECORD_THRESHOLD 1024

typedef struct {
    int key;
    long offset;
    char* buffer;
    pthread_mutex_t lock;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t pool_lock;
} RecordPool;

int init_record_pool(RecordPool* pool, size_t initial_capacity) {
    pool->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!pool->records) return -1; // Memory allocation failed

    pool->capacity = initial_capacity;
    pool->count = 0;

    pthread_mutex_init(&pool->pool_lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->records[i] = (Record*)malloc(sizeof(Record));
        if (!pool->records[i]) {
            // Free previously allocated records
            for (size_t j = 0; j < i; ++j) free(pool->records[j]);
            free(pool->records);
            return -1; // Memory allocation failed
        }
        pthread_mutex_init(&pool->records[i]->lock, NULL);
    }

    return 0;
}

void destroy_record_pool(RecordPool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i]->buffer);
        free(pool->records[i]);
    }
    pthread_mutex_destroy(&pool->pool_lock);
    free(pool->records);
}

int allocate_record(RecordPool* pool, int key_range_start, int key_range_end) {
    pthread_mutex_lock(&pool->pool_lock);

    if (pool->count >= pool->capacity) {
        Record** new_records = (Record**)realloc(pool->records, pool->capacity * 2 * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&pool->pool_lock);
            return -1; // Memory allocation failed
        }
        pool->records = new_records;
        pool->capacity *= 2;

        for (size_t i = pool->count; i < pool->capacity; ++i) {
            pool->records[i] = (Record*)malloc(sizeof(Record));
            if (!pool->records[i]) {
                // Free previously allocated records
                for (size_t j = pool->count; j < i; ++j) free(pool->records[j]);
                pthread_mutex_unlock(&pool->pool_lock);
                return -1; // Memory allocation failed
            }
            pthread_mutex_init(&pool->records[i]->lock, NULL);
        }
    }

    Record* new_record = pool->records[pool->count];
    pthread_mutex_lock(&new_record->lock);

    new_record->key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
    new_record->offset = pool->count * sizeof(Record);
    new_record->buffer = (char*)malloc(1024); // Example buffer size
