} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    char** buffers;
    void** metadata;
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
} record_pool;

record_pool* create_record_pool(size_t initial_capacity) {
    record_pool* pool = (record_pool*)malloc(sizeof(record_pool));
    if (!pool) return NULL;

    pool->offsets = (long*)calloc(initial_capacity, sizeof(long));
    pool->keys = (int*)calloc(initial_capacity, sizeof(int));
    pool->records = (record*)calloc(initial_capacity, sizeof(record));
    pool->buffers = (char**)calloc(initial_capacity, sizeof(char*));
    pool->metadata = (void**)calloc(initial_capacity, sizeof(void*));
    if (!pool->offsets || !pool->keys || !pool->records || !pool->buffers || !pool->metadata) {
        free_record_pool(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = initial_capacity;
    pool->size = 0;

    return pool;
}

void free_record_pool(record_pool* pool) {
    if (pool) {
        for (size_t i = 0; i < pool->size; ++i) {
            free(pool->records[i].buffer);
            // Free other metadata fields here
        }
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool->buffers);
        free(pool->metadata);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int resize_record_pool(record_pool* pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return 0;

    long* new_offsets = (long*)realloc(pool->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(pool->keys, new_capacity * sizeof(int));
    record* new_records = (record*)realloc(pool->records, new_capacity * sizeof(record));
    char** new_buffers = (char**)realloc(pool->buffers, new_capacity * sizeof(char*));
    void** new_metadata = (void**)realloc(pool->metadata, new_capacity * sizeof(void*));

    if (!new_offsets || !new_keys || !new_records || !new_buffers || !new_metadata) {
        free(new_offsets);
        free(new_keys);
        free(new_records);
        free(new_buffers);
        free(new_metadata);
        return -1;
    }

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->records = new_records;
    pool->buffers = new_buffers;
    pool->metadata = new_metadata;
    pool->capacity = new_capacity;

    return 0;
}

int add_record(record_pool* pool, int key, const char* data) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity && resize_record_pool(pool, pool->capacity * 2) != 0) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    size_t index = pool->size++;
    pool->keys[index] = key;
    pool->records[index].value = 0; // Initialize value
    pool->buffers[index] = (char*)malloc(BUFFER_SIZE * sizeof(char));
    if (!pool->buffers[index]) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }
    strncpy(pool->buffers[index], data, BUFFER_SIZE);

    // Initialize metadata fields here

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

