using System;
using System.Collections.Generic;

public class TimeSeriesSensorDataProcessor
{
    private int minValue;
    private int maxValue;

    public TimeSeriesSensorDataProcessor(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public int GetRandomInt()
    {
        return new Random().Next(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue == maxValue) throw new ArgumentException("Min value cannot equal max value for exclusive random generation.");
        return new Random().Next(minValue + 1, maxValue);
    }

    public int GetRandomWeightedInt(int[] weights)
    {
        if (weights.Length != maxValue - minValue + 1) throw new ArgumentException("Weights array must match the range of values.");
        int totalWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }
        int randomValue = new Random().Next(totalWeight);
        int cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue < cumulativeWeight) return minValue + i;
        }
        throw new InvalidOperationException("Failed to select a value based on weights.");
    }

    public int FindDisjointPairs(int[] array)
    {
        UnionFind uf = new UnionFind(array.Length);
        for (int i = 0; i < array.Length - 1; i++)
        {
            if (!uf.IsConnected(array[i], array[i + 1]))
            {
                uf.Union(array[i], array[i + 1]);
            }
        }
        return uf.GetNumberOfDisjointSets();
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }
}

public class UnionFind
{
    private int[] parent;
    private int[] rank;

    public UnionFind(int size)
    {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++)
        {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public void Union(int x, int y)
    {
        int rootX = Find(x);
        int rootY = Find(y);

        if (rootX != rootY)
        {
            if (rank[rootX] > rank[rootY])
            {
                parent[rootY] = rootX;
            }
            else if (rank[rootX] < rank[rootY])
            {
                parent[rootX] = rootY;
            }
            else
            {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public int Find(int x)
    {
        if (parent[x] != x)
        {
            parent[x] = Find(parent[x]);
        }
        return parent[x];
    }

    public bool IsConnected(int x, int y)
    {
        return Find(x) == Find(y);
    }

    public int GetNumberOfDisjointSets()
    {
        HashSet<int> disjointSets = new HashSet<int>();
        for (int i = 0; i < parent.Length; i++)
        {
            disjointSets.Add(Find(i));
        }
        return disjointSets.Count;
    }
}
