    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *prev, *next;
} Node;

Record* create_record_array(int size) {
    Record *array = (Record*)malloc(size * sizeof(Record));
    if (!array) return NULL;
    for (int i = 0; i < size; ++i) {
        array[i].offset = rand();
        array[i].key = rand() % 1000;
        array[i].data = (char*)calloc(256, sizeof(char));
        if (!array[i].data) {
            for (int j = 0; j < i; ++j) free(array[j].data);
            free(array);
            return NULL;
        }
    }
    return array;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->prev = node->next = NULL;
    return node;
}

void insert_nodes(Node **head, NFAPI_CRC_INDICATION_PDU_T *data, int count) {
    for (int i = 0; i < count; ++i) {
        Node *new_node = create_node(data[i]);
        if (!new_node) continue;
        if (*head == NULL) {
            *head = new_node;
        } else {
            Node *temp = *head;
            while (temp->next != NULL) temp = temp->next;
            temp->next = new_node;
            new_node->prev = temp;
        }
    }
}

// Additional functions for merging, reversing, counting, and serialization would be implemented here.

void free_record_array(Record *array, int size) {
    for (int i = 0; i < size; ++i) free(array[i].data);
    free(array);
}

void free_linked_list(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}
