    if (!collection->records) {
        free(collection);
        fprintf(stderr, "Failed to allocate memory for records array\n");
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    if (collection) {
        for (size_t i = 0; i < collection->size; ++i) {
            Record* record = collection->records[i];
            free(record->dynamic_value);
            free(record);
        }
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int add_record(DynamicCollection* collection, int key, const char* value, size_t nth) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            fprintf(stderr, "Failed to reallocate memory for records array\n");
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->mutex);
        fprintf(stderr, "Failed to allocate memory for record\n");
        return -1;
    }
    record->key = key;
    strncpy(record->value, value, MAX_STRING_LENGTH - 1);
    record->value[MAX_STRING_LENGTH - 1] = '\0';

    if (nth > 0 && collection->size % nth == 0) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", localtime(&now));
        snprintf(record->dynamic_value, MAX_STRING_LENGTH, "Valid Record %s", timestamp);

        // Calculate checksum (example: simple sum of ASCII values)
        size_t checksum = 0;
        for (size_t i = 0; record->dynamic_value[i]; ++i) {
            checksum += (unsigned char)record->dynamic_value[i];
        }
        snprintf(record->value, MAX_STRING_LENGTH - 1, "Checksum: %zu", checksum);
    } else {
        record->dynamic_value = strdup("Record Not Found");
        if (!record->dynamic_value) {
            free(record);
            pthread_mutex_unlock(&collection->mutex);
            fprintf(stderr, "Failed to allocate memory for dynamic value\n");
            return -1;
        }
    }

    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

