record* create_records(int num_records, long* offsets, int (*transform)(long)) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum limit.\n");
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for records.\n");
        return NULL;
    }

    int* keys = malloc(num_records * sizeof(int));
    if (!keys) {
        free(records);
        fprintf(stderr, "Error: Memory allocation failed for keys.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].key = transform(offsets[i]);
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }

    free(keys); // No longer needed, keys are copied to records

    return records;
}

int key_transform(long offset) {
    return (int)(offset % 1000); // Example transformation function
}

void free_records(record* records, int num_records) {
    free(records);
}

int main() {
    long offsets[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = i * 100; // Example offset values
    }

    record* my_records = create_records(MAX_RECORDS, offsets, key_transform);
    if (my_records) {
        // Use the records array as needed
        free_records(my_records, MAX_RECORDS);
    }

    return 0;
}
