} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTS];
    int count;
    pthread_mutex_t lock;
    int logging_enabled;
} NFAPI_CRC_LIST_T;

void init_crc_list(NFAPI_CRC_LIST_T *list, int enable_logging) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->logging_enabled = enable_logging;
}

void add_to_crc_list(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count < MAX_STRUCTS) {
        list->data[list->count++] = pdu;
    } else {
        // Handle error: list is full
    }
    pthread_mutex_unlock(&list->lock);
}

void validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (/* validation condition */) {
        if (list->logging_enabled) {
            printf("CRC indication validation failed\n");
        }
        // Handle error: invalid CRC indication
    }
}

void serialize_crc_list(NFAPI_CRC_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        fwrite(list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

NFAPI_CRC_LIST_T *deserialize_crc_list(const char *filename) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T *)malloc(sizeof(NFAPI_CRC_LIST_T));
    init_crc_list(list, 0); // Disable logging for deserialization

    FILE *file = fopen(filename, "rb");
    if (!file) return list;

    pthread_mutex_lock(&list->lock);
    while (fread(list->data[list->count], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        validate_crc_indication(list->data[list->count]);
        list->count++;
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return list;
}

void free_crc_list(NFAPI_CRC_LIST_T *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->data[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
