#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 100000
#define BUFFER_SIZE 1024
#define LOG_LIMIT 1024 * 1024

typedef enum {DEBUG, INFO, WARNING, ERROR} log_severity;

typedef struct {
    int value;
    long offset_ptr;
    char status;
} record_struct;

typedef struct {
    unsigned long timestamp;
    char* message;
    log_severity severity;
} log_entry;

int initialize_data_structures(int maxRecords, int N, int M, int L) {
    if (maxRecords <= 0 || N <= 0 || M <= 0 || L <= 0) {
        fprintf(stderr, "Invalid input sizes\n");
        return -1;
    }

    int* keys = malloc(maxRecords * sizeof(int));
    long* offsets = malloc(maxRecords * sizeof(long));
    record_struct** records = malloc(maxRecords * sizeof(record_struct*));

    char** buffers = malloc(N * sizeof(char*));
    log_entry** logs = malloc(N * sizeof(log_entry*));

    if (!keys || !offsets || !records || !buffers || !logs) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (int i = 0; i < maxRecords; i++) {
        records[i] = malloc(sizeof(record_struct));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        records[i]->value = rand() % 201 - 100; // Random value between -100 and 100
        records[i]->offset_ptr = offsets + i;
        records[i]->status = (records[i]->value >= 0) ? 'P' : 'N'; // Positive or negative status
    }

    for (int i = 0; i < N; i++) {
        buffers[i] = malloc(M * sizeof(char));
        logs[i] = malloc(sizeof(log_entry));
        if (!buffers[i] || !logs[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
    }

    // Initialize log entries and calculate total message size
    unsigned long total_size = 0;
    for (int i = 0; i < N; i++) {
        logs[i]->timestamp = time(NULL);
        snprintf(buffers[i], M, "Log entry %d", i);
        logs[i]->message = buffers[i];
        logs[i]->severity = INFO;
        total_size += strlen(logs[i]->message) + sizeof(log_entry);
    }

    // Adjust message content if total size exceeds limit
    int adjustment_count = 0;
    while (total_size > L) {
        for (int i = 0; i < N && total_size > L; i++) {
            int len = strlen(logs[i]->message);
            if (len > M) {
                snprintf(buffers[i], M, "Log %d", i);
                logs[i]->message = buffers[i];
                total_size -= len - strlen(logs[i]->message);
                adjustment_count++;
            }
        }
    }

    // Periodic cleanup process for unused log entries
    int cleanup_count = 0;
    for (int i = N / 2; i < N && cleanup_count < N / 4; i++) {
        free(buffers[i]);
        buffers[i] = NULL;
        free(logs[i]);
        logs[i] = NULL;
        cleanup_count++;
    }

    // Free allocated memory
    free(keys);
    free(offsets);
    for (int i = 0; i < maxRecords; i++) {
        free(records[i]);
    }
    free(records);

    for (int i = 0; i < N; i++) {
        if (buffers[i]) {
            free(buffers[i]);
        }
        if (logs[i]) {
            free(logs[i]);
        }
    }

    free(buffers);
    free(logs);

    printf("Adjustments made: %d\n", adjustment_count);
    printf("Cleanup count: %d\n", cleanup_count);

    return 0;
}

int main() {
    srand(time(NULL));
    initialize_data_structures(100, 5, 256, LOG_LIMIT);
    return 0;
}
