#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct DataPacket {
    int packetID;
    time_t timestamp;
    size_t payloadSize;
    char* payload;
} DataPacket;

typedef struct PacketNode {
    DataPacket data;
    struct PacketNode* next;
} PacketNode;

typedef struct PacketList {
    PacketNode* head;
    pthread_mutex_t lock;
} PacketList;

void initPacketList(PacketList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addPacket(PacketList* list, DataPacket packet) {
    pthread_mutex_lock(&list->lock);
    PacketNode* newNode = (PacketNode*)malloc(sizeof(PacketNode));
    newNode->data = packet;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void updatePacket(PacketList* list, int packetID, DataPacket newPacket) {
    pthread_mutex_lock(&list->lock);
    PacketNode* current = list->head;
    while (current != NULL) {
        if (current->data.packetID == packetID) {
            current->data = newPacket;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

DataPacket* getPacket(PacketList* list, int packetID) {
    pthread_mutex_lock(&list->lock);
    PacketNode* current = list->head;
    while (current != NULL) {
        if (current->data.packetID == packetID) {
            DataPacket* result = malloc(sizeof(DataPacket));
            *result = current->data;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void freePacketList(PacketList* list) {
    pthread_mutex_lock(&list->lock);
    PacketNode* current = list->head;
    while (current != NULL) {
        PacketNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
