#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* data;
    int hash;
} Record;

typedef struct {
    int* offsets;
    char** keys;
    Record** records;
    int size;
    int capacity;
    int memory_budget;
    pthread_mutex_t lock;
} DataStructure;

DataStructure* create_data_structure(int initial_capacity, int memory_budget) {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->offsets = (int*)calloc(initial_capacity, sizeof(int));
    ds->keys = (char**)calloc(initial_capacity, sizeof(char*));
    ds->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    ds->size = 0;
    ds->capacity = initial_capacity;
    ds->memory_budget = memory_budget;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void destroy_data_structure(DataStructure* ds) {
    for (int i = 0; i < ds->size; ++i) {
        free(ds->keys[i]);
        free(ds->records[i]->data);
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int resize_data_structure(DataStructure* ds, int new_capacity) {
    if (new_capacity <= ds->capacity) return -1;

    int* new_offsets = (int*)realloc(ds->offsets, new_capacity * sizeof(int));
    char** new_keys = (char**)realloc(ds->keys, new_capacity * sizeof(char*));
    Record** new_records = (Record**)realloc(ds->records, new_capacity * sizeof(Record*));

    if (!new_offsets || !new_keys || !new_records) {
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return -1;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;

    return 0;
}

int add_record(DataStructure* ds, const char* key, int hash, const char* data) {
    pthread_mutex_lock(&ds->lock);

    if (ds->size >= ds->capacity && resize_data_structure(ds, ds->capacity * 2) != 0) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    int index = ds->size++;
    ds->offsets[index] = strlen(data);
    ds->keys[index] = strdup(key);
    ds->records[index] = (Record*)malloc(sizeof(Record));
    ds->records[index]->data = strdup(data);
    ds->records[index]->hash = hash;

    pthread_mutex_unlock(&ds->lock);

    return 0;
}

// Additional functions for managing concurrency, memory allocation strategies,
// performance evaluation, and handling edge cases would be implemented here.

int main() {
    DataStructure* ds = create_data_structure(10, 1024 * 1024); // Initial capacity of 10, memory budget of 1MB
    if (!ds) return -1;

    add_record(ds, "key1", 123, "data1");
    add_record(ds, "key2", 456, "data2");

    destroy_data_structure(ds);
    return 0;
}
