#include <string.h>
#include <openssl/evp.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    EVP_CIPHER_CTX *cipher_ctx;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* load_and_parse_config(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    // Parse the configuration file and populate the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (line[0] == '#') continue; // Skip comments

        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            perror("Failed to allocate memory for new node");
            fclose(file);
            free_list(head);
            return NULL;
        }

        // Parse the line and populate the structure
        sscanf(line, "%d %d %d", &new_node->RX_UE_INFORMATION_TAG, &new_node->RNTI, &new_node->CRC_INDICATION_REL8_TAG);

        // Initialize cryptographic operations based on configuration settings
        const EVP_CIPHER* cipher = NULL;
        switch (new_node->CRC_INDICATION_REL8_TAG) {
            case 1: cipher = EVP_aes_128_ecb(); break;
            case 2: cipher = EVP_aes_192_ecb(); break;
            case 3: cipher = EVP_aes_256_ecb(); break;
            case 4: cipher = EVP_aes_128_cfb(); break;
            default: cipher = NULL; break;
        }

        if (cipher) {
            new_node->cipher_ctx = EVP_CIPHER_CTX_new();
            if (!new_node->cipher_ctx || !EVP_EncryptInit_ex(new_node->cipher_ctx, cipher, NULL, NULL, NULL)) {
                perror("Failed to initialize cryptographic context");
                free(new_node);
                fclose(file);
                free_list(head);
                return NULL;
            }
        } else {
            new_node->cipher_ctx = NULL;
        }

        *current = new_node;
        current = &new_node->next;
    }

    fclose(file);
    *current = NULL;

    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        if (current->cipher_ctx) EVP_CIPHER_CTX_free(current->cipher_ctx);
        free(current);
        current = next;
    }
}
