    srand(time(NULL));

    for (int i = 0; i < MAX_PROJECTS; i++) {
        initialize_project(&projects[i], i + 1);
        active_projects++;
    }

    // Simulate processing projects
    for (int i = 0; i < MAX_PROJECTS; i++) {
        if (projects[i].status == PENDING) {
            projects[i].status = IN_PROGRESS;
        } else if (projects[i].status == IN_PROGRESS) {
            projects[i].status = COMPLETED;
            free_project(&projects[i]);
            active_projects--;
        }
    }

