class ModuleLoader {
  constructor() {
    this.cache = {};
    this.dependencies = {};
    this.loadingPromises = {};
    this.maxConcurrentLoads = 5;
    this.currentLoads = 0;
  }

  loadFile(url) {
    return new Promise((resolve, reject) => {
      if (this.cache[url]) {
        resolve(this.cache[url]);
      } else {
        const script = document.createElement('script');
        script.src = url;
        script.onload = () => {
          this.cache[url] = true;
          resolve(true);
        };
        script.onerror = () => {
          reject(new Error(`Failed to load file: ${url}`));
        };
        document.head.appendChild(script);
      }
    });
  }

  async loadFiles(urls) {
    const promises = urls.map(url => this.loadFile(url));
    for (const promise of promises) {
      await promise;
      if (++this.currentLoads >= this.maxConcurrentLoads) {
        await new Promise(resolve => setTimeout(resolve, 100)); // Throttle
      }
    }
    this.currentLoads = 0;
  }

  registerDependency(moduleName, dependencies) {
    this.dependencies[moduleName] = dependencies;
  }

  async executeModule(moduleName) {
    if (!this.dependencies[moduleName]) {
      throw new Error(`Module ${moduleName} has no dependencies.`);
    }

    const missingDependencies = this.dependencies[moduleName].filter(dep => !this.cache[dep]);
    if (missingDependencies.length > 0) {
      await this.loadFiles(missingDependencies);
    }

    // Simulate module execution
    console.log(`Executing module: ${moduleName}`);
  }

  async executeAllModules() {
    const modules = Object.keys(this.dependencies);
    for (const module of modules) {
      await this.executeModule(module);
    }
  }
}

// Usage example:
const loader = new ModuleLoader();
loader.registerDependency('moduleA', ['file1.js']);
loader.registerDependency('moduleB', ['file2.js', 'moduleA']);
loader.loadFiles(['file1.js', 'file2.js']).then(() => {
  return loader.executeAllModules();
}).catch(error => {
  console.error('Error loading or executing modules:', error);
});
