    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(CRC_LIST_T *list) {
    free(list->pdu_list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_indication(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->pdu_list = new_list;
        list->capacity = new_capacity;
    }
    list->pdu_list[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
