function loadAndExecuteJSFiles(filePaths, callback) {
    let loadedCount = 0;
    const totalFiles = filePaths.length;

    function executeFile(index) {
        if (index >= totalFiles) {
            callback();
            return;
        }

        fetch(filePaths[index])
            .then(response => response.text())
            .then(scriptText => {
                try {
                    eval(scriptText);
                } catch (error) {
                    console.error(`Error executing ${filePaths[index]}:`, error);
                }
                loadedCount++;
                if (loadedCount === totalFiles) {
                    callback();
                } else {
                    executeFile(index + 1);
                }
            })
            .catch(error => {
                console.error(`Failed to load ${filePaths[index]}`, error);
                loadedCount++;
                if (loadedCount === totalFiles) {
                    callback();
                } else {
                    executeFile(index + 1);
                }
            });
    }

    executeFile(0);
}
