    float temperature;
    char device_name[MAX_DEVICE_NAME_LENGTH];
    ErrorCode error_code;
} DeviceData;

void initialize_device_data(DeviceData *devices, long *offsets, int *keys, int num_devices) {
    srand(time(NULL));
    for (int i = 0; i < num_devices; i++) {
        devices[i].sensor_id = rand() % 1000;
        devices[i].temperature = ((float)rand()) / RAND_MAX * 100.0f;
        snprintf(devices[i].device_name, MAX_DEVICE_NAME_LENGTH, "Device_%d", i);
        devices[i].error_code = (ErrorCode)(rand() % 3);

        offsets[i] = rand();
        keys[i] = rand() % num_devices;
    }
}

void process_device_data(DeviceData *devices, long *offsets, int *keys, int num_devices) {
    for (int i = 0; i < num_devices; i++) {
        if (devices[i].error_code != NO_ERROR) {
            continue;
        }

        float weighted_temperature = devices[i].temperature;
        for (int j = 0; j < num_devices; j++) {
            if (i == j) continue;

            int proximity_factor = abs(devices[i].sensor_id - devices[j].sensor_id);
            weighted_temperature += devices[j].temperature * proximity_factor / 100.0f;
        }

        printf("Processed Device %d: Temperature = %.2f\n", i, weighted_temperature);
    }
}

int main() {
    int num_devices = 10;
    DeviceData *devices = (DeviceData *)malloc(num_devices * sizeof(DeviceData));
    long *offsets = (long *)malloc(num_devices * sizeof(long));
    int *keys = (int *)malloc(num_devices * sizeof(int));

    if (devices == NULL || offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_device_data(devices, offsets, keys, num_devices);
    process_device_data(devices, offsets, keys, num_devices);

    free(devices);
    free(offsets);
    free(keys);

    return 0;
}
