#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_OFFSET_SIZE 1000000
#define MAX_KEY_SIZE 1000000

typedef struct {
    char identifier;
    int key;
    double timestamp;
} record;

typedef struct {
    record *data;
    size_t capacity;
    size_t size;
} hash_table;

unsigned long custom_hash(int key, unsigned long range) {
    return (unsigned long)((key * 2654435769U) % range);
}

hash_table* create_hash_table(size_t initial_capacity) {
    hash_table *ht = (hash_table*)malloc(sizeof(hash_table));
    if (!ht) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }
    ht->data = (record*)calloc(initial_capacity, sizeof(record));
    if (!ht->data) {
        fprintf(stderr, "Memory allocation failed for hash table data\n");
        free(ht);
        return NULL;
    }
    ht->capacity = initial_capacity;
    ht->size = 0;
    return ht;
}

void resize_hash_table(hash_table *ht, size_t new_capacity) {
    record *new_data = (record*)realloc(ht->data, new_capacity * sizeof(record));
    if (!new_data) {
        fprintf(stderr, "Memory reallocation failed for hash table data\n");
        return;
    }
    ht->data = new_data;
    ht->capacity = new_capacity;
}

void insert_record(hash_table *ht, int key, char identifier, double timestamp) {
    unsigned long index = custom_hash(key, ht->capacity);
    while (ht->data[index].key != 0 && ht->data[index].key != -1) {
        if (index == ht->capacity - 1)
            index = 0;
        else
            index++;
    }
    ht->data[index].identifier = identifier;
    ht->data[index].key = key;
    ht->data[index].timestamp = timestamp;
    ht->size++;
}

void free_hash_table(hash_table *ht) {
    if (ht) {
        free(ht->data);
        free(ht);
    }
}

int main() {
    int offset_size, key_size;
    printf("Enter the size of offset and key arrays: ");
    scanf("%d %d", &offset_size, &key_size);

    if (offset_size > MAX_OFFSET_SIZE || key_size > MAX_KEY_SIZE) {
        fprintf(stderr, "Input exceeds maximum allowed size\n");
        return 1;
    }

    long *offsets = (long*)malloc(offset_size * sizeof(long));
    int *keys = (int*)malloc(key_size * sizeof(int));
    record **records = (record**)malloc(key_size * sizeof(record*));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % MAX_KEY_SIZE;
        offsets[i] = rand();
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record\n");
            for (int j = 0; j < i; j++)
                free(records[j]);
            free(offsets);
            free(keys);
            free(records);
            return 1;
        }
        records[i]->identifier = 'A' + rand() % 26;
        records[i]->key = keys[i];
        records[i]->timestamp = (double)time(NULL) + (rand() / (RAND_MAX * 1.0));
    }

    hash_table *ht = create_hash_table(key_size);
    if (!ht) {
        for (int i = 0; i < key_size; i++)
            free(records[i]);
        free(offsets);
        free(keys);
        free(records);
        return 1;
    }

    for (int i = 0; i < key_size; i++) {
        insert_record(ht, keys[i], records[i]->identifier, records[i]->timestamp);
    }

    // Perform operations on the hash table

    free_hash_table(ht);
    for (int i = 0; i < key_size; i++)
        free(records[i]);
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
