#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENT_ID 1000000

typedef struct event_record {
    int event_id;
    time_t timestamp;
    char *description;
    struct event_record *next;
} event_record;

typedef struct event_manager {
    event_record **event_map;
    pthread_mutex_t lock;
    size_t map_size;
} event_manager;

event_manager* create_event_manager(size_t initial_size) {
    event_manager *manager = (event_manager*)malloc(sizeof(event_manager));
    manager->event_map = (event_record**)calloc(initial_size, sizeof(event_record*));
    manager->map_size = initial_size;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_event_manager(event_manager *manager) {
    for (size_t i = 0; i < manager->map_size; ++i) {
        event_record *current = manager->event_map[i];
        while (current != NULL) {
            event_record *next = current->next;
            free(current->description);
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager->event_map);
    free(manager);
}

void insert_event(event_manager *manager, int event_id, time_t timestamp, const char *description) {
    pthread_mutex_lock(&manager->lock);
    size_t index = event_id % manager->map_size;
    event_record *new_record = (event_record*)malloc(sizeof(event_record));
    new_record->event_id = event_id;
    new_record->timestamp = timestamp;
    new_record->description = strdup(description);
    new_record->next = manager->event_map[index];
    manager->event_map[index] = new_record;
    pthread_mutex_unlock(&manager->lock);
}

void delete_event(event_manager *manager, int event_id) {
    pthread_mutex_lock(&manager->lock);
    size_t index = event_id % manager->map_size;
    event_record **current_ptr = &manager->event_map[index];
    while (*current_ptr != NULL) {
        if ((*current_ptr)->event_id == event_id) {
            event_record *to_delete = *current_ptr;
            *current_ptr = to_delete->next;
            free(to_delete->description);
            free(to_delete);
            break;
        }
        current_ptr = &(*current_ptr)->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void garbage_collect(event_manager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->map_size; ++i) {
        event_record **current_ptr = &manager->event_map[i];
        while (*current_ptr != NULL) {
            if (time(NULL) - (*current_ptr)->timestamp > MAX_EVENT_ID) { // Assuming expired events are older than MAX_EVENT_ID
                event_record *to_delete = *current_ptr;
                *current_ptr = to_delete->next;
                free(to_delete->description);
                free(to_delete);
            } else {
                current_ptr = &(*current_ptr)->next;
            }
        }
    }
    pthread_mutex_unlock(&manager->lock);
}
