#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CRC_INDICATIONS 1024
#define RESIZE_THRESHOLD 0.8
#define STALE_ENTRY_AGE 60 // in seconds

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t age;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *indicators;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t resize_cv;
    int pause_resizing;
} CRC_Indication_List;

void init_crc_indication_list(CRC_Indication_List *list) {
    list->indicators = malloc(MAX_CRC_INDICATIONS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->indicators == NULL) {
        // Handle memory allocation failure
    }
    list->count = 0;
    list->capacity = MAX_CRC_INDICATIONS;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->resize_cv, NULL);
    list->pause_resizing = 0;
}

void destroy_crc_indication_list(CRC_Indication_List *list) {
    free(list->indicators);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->resize_cv);
}

int add_crc_indication(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *new_indicator) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity && !list->pause_resizing) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_indicators = realloc(list->indicators, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_indicators == NULL) {
            pthread_mutex_unlock(&list->lock);
            // Handle memory allocation failure
            return -1;
        }
        list->indicators = new_indicators;
        list->capacity = new_capacity;
    }

    list->indicators[list->count++] = *new_indicator;
    new_indicator->age = time(NULL);

    pthread_cond_signal(&list->resize_cv);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_stale_entries(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0, j = 0;
    while (j < list->count) {
        if (time(NULL) - list->indicators[j].age > STALE_ENTRY_AGE) {
            j++;
        } else {
            if (i != j) {
                list->indicators[i] = list->indicators[j];
            }
            i++;
            j++;
        }
    }
    list->count = i;
    pthread_mutex_unlock(&list->lock);
}

void monitor_and_log(CRC_Indication_List *list, FILE *log_file) {
    pthread_mutex_lock(&list->lock);
    fprintf(log_file, "Current state: %zu elements, average age %.2f seconds, total memory usage %zu bytes\n",
            list->count,
            (list->count > 0) ? ((double)(time(NULL) - list->indicators[0].age)) / list->count : 0.0,
            list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->lock);
}

void pause_resizing(CRC_Indication_List *list, int pause) {
    pthread_mutex_lock(&list->lock);
    list->pause_resizing = pause;
    if (!pause) {
        pthread_cond_signal(&list->resize_cv);
    }
    pthread_mutex_unlock(&list->lock);
}
