    int sensor_id;
    float temperature;
    char device_name[MAX_DEVICE_NAME_LENGTH];
    error_code error_code;
} device_data;

void initialize_records(record *records, int N) {
    for (int i = 0; i < N; i++) {
        records[i].value = rand() % 1001;
    }
}

void process_device_data(device_data *data, int size, float *weighted_avg_temp) {
    // Filter out devices with non-zero error codes
    int valid_count = 0;
    for (int i = 0; i < size; i++) {
        if (data[i].error_code == NO_ERROR) {
            data[valid_count++] = data[i];
        }
    }

    // Apply weighted average filter to temperature readings
    *weighted_avg_temp = 0.0f;
    for (int i = 1; i < valid_count; i++) {
        float weight = (float)(data[i].sensor_id - data[i-1].sensor_id) / MAX_SENSOR_ID;
        *weighted_avg_temp += weight * data[i].temperature;
    }
    *weighted_avg_temp /= valid_count;

    // Truncate device names exceeding maximum length
    for (int i = 0; i < valid_count; i++) {
        if (strlen(data[i].device_name) > MAX_DEVICE_NAME_LENGTH) {
            data[i].device_name[MAX_DEVICE_NAME_LENGTH - 1] = '\0';
        }
    }
}

void log_adjustments(int adjustments) {
    printf("Number of adjustments made: %d\n", adjustments);
}

