    record records[MAX_RECORDS];
    initialize_records(records, MAX_RECORDS);

    device_data devices[MAX_SENSOR_ID];
    // Initialize devices with random data
    for (int i = 0; i < MAX_SENSOR_ID; i++) {
        devices[i].sensor_id = i;
        devices[i].temperature = (float)rand() / RAND_MAX * 100.0f;
        strcpy(devices[i].device_name, "Device");
        devices[i].error_code = rand() % MAX_ERROR_CODE;
    }

    float weighted_avg_temp;
    process_device_data(devices, MAX_SENSOR_ID, &weighted_avg_temp);

    printf("Weighted average temperature: %.2f\n", weighted_avg_temp);
    log_adjustments(0); // Placeholder for actual adjustment count

    return 0;
}
