    int used_keys[MAX_RECORDS] = {0};
    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        int key_index;
        do {
            key_index = rand() % key_count;
        } while (used_keys[key_index]);

        records[i].key = &keys[key_index];
        records[i].value = rand();
        used_keys[key_index] = 1;
    }

    return records;
}

void free_records(record *records, int size) {
    free(records);
}

int main() {
