#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long* offset;
} record;

void fill_records(record* records, int num_records, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void* manage_memory(int num_offsets, int min_value, int max_value) {
    if (num_offsets < 0 || num_offsets > 10000) {
        fprintf(stderr, "Invalid number of offsets. Must be between 0 and 10000.\n");
        exit(EXIT_FAILURE);
    }

    size_t total_size = num_offsets * sizeof(long) + num_offsets * sizeof(int) + num_offsets * sizeof(record);
    void* memory_block = malloc(total_size);

    if (memory_block == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = (long*)memory_block;
    int* keys = (int*)(offsets + num_offsets);
    record* records = (record*)(keys + num_offsets);

    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = (long)(records + i);
        keys[i] = 0;
        records[i].value = 0;
        records[i].offset = &offsets[i];
    }

    fill_records(records, num_offsets, min_value, max_value);

    return memory_block;
}

int main() {
    int num_offsets = 1000;
    int min_value = -1000;
    int max_value = 1000;

    void* memory_block = manage_memory(num_offsets, min_value, max_value);

    // Example usage of the allocated memory
    record* records = (record*)((char*)memory_block + num_offsets * sizeof(long) + num_offsets * sizeof(int));
    for (int i = 0; i < num_offsets; ++i) {
        printf("Record %d: Value = %d, Offset = %ld\n", i, records[i].value, *(records[i].offset));
    }

    free(memory_block);
    return 0;
}
