typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->size++] = entry;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamic_list_remove(DynamicList *list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i].rnti == rnti) {
            for (size_t j = i; j < list->size - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            --list->size;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Entry not found
}

int dynamic_list_update(DynamicList *list, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i].rnti == rnti) {
            list->entries[i] = new_entry;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Entry not found
}

size_t dynamic_list_size(DynamicList *list) {
    return list->size;
}
