#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 1000

typedef struct node {
    int value;
    struct node* children[MAX_NODES];
    int child_count;
} Node;

Node* create_node(int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed for node.\n");
        return NULL;
    }
    new_node->value = value;
    new_node->child_count = 0;
    for (int i = 0; i < MAX_NODES; i++) {
        new_node->children[i] = NULL;
    }
    return new_node;
}

void add_child(Node* parent, Node* child) {
    if (parent == NULL || child == NULL) {
        printf("Invalid node pointers.\n");
        return;
    }
    if (parent->child_count >= MAX_NODES) {
        printf("Parent node has reached maximum number of children.\n");
        return;
    }
    parent->children[parent->child_count++] = child;
}

void print_tree(Node* root, int level) {
    if (root == NULL) {
        return;
    }
    for (int i = 0; i < level; i++) {
        printf("  ");
    }
    printf("%d\n", root->value);
    for (int i = 0; i < root->child_count; i++) {
        print_tree(root->children[i], level + 1);
    }
}

void delete_tree(Node* node) {
    if (node == NULL) {
        return;
    }
    for (int i = 0; i < node->child_count; i++) {
        delete_tree(node->children[i]);
    }
    free(node);
}

int main() {
    int num_nodes, value_range;
    printf("Enter the number of nodes: ");
    scanf("%d", &num_nodes);
    if (num_nodes <= 0 || num_nodes > MAX_NODES) {
        printf("Invalid number of nodes.\n");
        return 1;
    }
    printf("Enter the range for node values: ");
    scanf("%d", &value_range);
    if (value_range <= 0) {
        printf("Invalid value range.\n");
        return 1;
    }

    Node* root = create_node(0); // Assuming root is always created with a dummy value
    if (root == NULL) {
        return 1;
    }

    int values[MAX_NODES];
    for (int i = 0; i < num_nodes; i++) {
        values[i] = rand() % value_range + 1;
    }

    // Ensure uniqueness and assign values to nodes
    for (int i = 0; i < num_nodes; i++) {
        Node* new_node = create_node(values[i]);
        if (new_node == NULL) {
            delete_tree(root);
            return 1;
        }
        add_child(root, new_node);
    }

    print_tree(root, 0);

    delete_tree(root);

    return 0;
}
