#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 500
#define MAX_TIMESTAMP 1000000

typedef struct {
    int value;
    float weight;
    char status;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    int size;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    table->size = size;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroyHashTable(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
}

unsigned int hashFunction(int key, int size) {
    return abs(key % size);
}

void insertRecord(HashTable* table, Record record) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hashFunction(record.value, table->size);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->record = record;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    pthread_mutex_unlock(&table->lock);
}

void removeRecord(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hashFunction(key, table->size);
    Node* node = table->buckets[index];
    Node* prev = NULL;

    while (node != NULL) {
        if (node->record.value == key) {
            if (prev == NULL) {
                table->buckets[index] = node->next;
            } else {
                prev->next = node->next;
            }
            free(node);
            break;
        }
        prev = node;
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void* manageMemory(void* args) {
    // Function implementation goes here
    return NULL;
}

int main() {
    HashTable* table = createHashTable(100);

    Record record1 = {1, 2.5, 'A'};
    insertRecord(table, record1);

    Record record2 = {2, 3.5, 'B'};
    insertRecord(table, record2);

    removeRecord(table, 1);

    destroyHashTable(table);
    return 0;
}
