['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORD_SIZE 1024

typedef struct {
    int key;
    long offset;
    char data[MAX_RECORD_SIZE];
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} RecordStorage;

RecordStorage* create_record_storage() {
    RecordStorage *storage = (RecordStorage*)malloc(sizeof(RecordStorage));
    storage->records = NULL;
    storage->size = 0;
    storage->capacity = 0;
    pthread_mutex_init(&storage->lock, NULL);
    return storage;
}

void destroy_record_storage(RecordStorage *storage) {
    if (storage->records != NULL) {
        free(storage->records);
    }
    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

int add_record(RecordStorage *storage, int key, long offset, const char *data) {
    pthread_mutex_lock(&storage->lock);
    if (storage->size >= storage->capacity) {
        Record *new_records = realloc(storage->records, (storage->capacity + 10) * sizeof(Record));
        if (new_records == NULL) {
            pthread_mutex_unlock(&storage->lock);
            return -1; // Memory allocation failed
        }
        storage->records = new_records;
        storage->capacity += 10;
    }
    Record *record = &storage->records[storage->size];
    record->key = key;
    record->offset = offset;
    strncpy(record->data, data, MAX_RECORD_SIZE);
    storage->size++;
    pthread_mutex_unlock(&storage->lock);
    return 0;
}

int get_record(RecordStorage *storage, int index, Record *record) {
    pthread_mutex_lock(&storage->lock);
    if (index < 0 || index >= storage->size) {
        pthread_mutex_unlock(&storage->lock);
        return -1; // Invalid index
    }
    *record = storage->records[index];
    pthread_mutex_unlock(&storage->lock);
    return 0;
}

int delete_record(RecordStorage *storage, int key) {
    pthread_mutex_lock(&storage->lock);
    for (int i = 0; i < storage->size; i++) {
        if (storage->records[i].key == key) {
            memmove(&storage->records[i], &storage->records[i + 1], (storage->size - i - 1) * sizeof(Record));
            storage->size--;
            pthread_mutex_unlock(&storage->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&storage->lock);
    return -1; // Record not found
}

int serialize_records(RecordStorage *storage, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // Failed to open file for writing
    }
    fwrite(&storage->size, sizeof(int), 1, file);
    for (int i = 0; i < storage->size; i++) {
        fwrite(&storage->records[i], sizeof(Record), 1, file);
    }
    fclose(file);
    return 0;
}

int deserialize_records(RecordStorage *storage, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Failed to open file for reading
    }
    int size;
    fread(&size, sizeof(int), 1, file);
    Record *new_records = realloc(storage->records, size * sizeof(Record));
    if (new_records == NULL) {
        fclose(file);
        return -1; // Memory allocation failed
    }
    storage->records = new_records;
    storage->size = size;
    storage->capacity = size;
    for (int i = 0; i < size; i++) {
        fread(&storage->records[i], sizeof(Record), 1, file);
    }
    fclose(file);
    return 0;
}
