    Metadata** metadatas;
    pthread_mutex_t records_lock;
    pthread_cond_t records_cv;
    size_t record_count;
    size_t max_records;
    size_t total_memory_usage;
    size_t memory_threshold;
} MemoryManager;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications;
    pthread_mutex_t crc_indications_lock;
    pthread_cond_t crc_indications_cv;
    size_t crc_indication_count;
    size_t max_crc_indications;
} NFAPICRCManager;

MemoryManager* create_memory_manager(size_t initial_size, size_t memory_threshold) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) {
        perror("Failed to allocate memory for MemoryManager");
        return NULL;
    }
    manager->offsets = (long*)calloc(initial_size, sizeof(long));
    manager->keys = (int*)calloc(initial_size, sizeof(int));
    manager->records = (Record**)calloc(initial_size, sizeof(Record*));
    manager->metadatas = (Metadata**)calloc(initial_size, sizeof(Metadata*));
    if (!manager->offsets || !manager->keys || !manager->records || !manager->metadatas) {
        perror("Failed to allocate memory for arrays");
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->records_lock, NULL);
    pthread_cond_init(&manager->records_cv, NULL);
    manager->record_count = 0;
    manager->max_records = initial_size;
    manager->total_memory_usage = 0;
    manager->memory_threshold = memory_threshold;
    return manager;
}

NFAPICRCManager* create_crc_manager(size_t initial_size) {
    NFAPICRCManager* manager = (NFAPICRCManager*)malloc(sizeof(NFAPICRCManager));
    if (!manager) {
        perror("Failed to allocate memory for NFAPICRCManager");
        return NULL;
    }
    manager->crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->crc_indications) {
        perror("Failed to allocate memory for CRC indications array");
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->crc_indications_lock, NULL);
    pthread_cond_init(&manager->crc_indications_cv, NULL);
    manager->crc_indication_count = 0;
    manager->max_crc_indications = initial_size;
    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    if (manager) {
        free(manager->offsets);
        free(manager->keys);
        for (size_t i = 0; i < manager->record_count; ++i) {
            free(manager->records[i]);
            free(manager->metadatas[i]);
        }
        free(manager->records);
        free(manager->metadatas);
        pthread_mutex_destroy(&manager->records_lock);
        pthread_cond_destroy(&manager->records_cv);
        free(manager);
    }
}

