void initialize_dataset(int dataset_index, size_t max_offset_size, size_t max_key_size, size_t num_records, long seed) {
    srand(seed + dataset_index); // Seed for reproducibility

    long* offsets = (long*)malloc(max_offset_size * sizeof(long));
    int* keys = (int*)malloc(max_key_size * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed for dataset %d\n", dataset_index);
        return;
    }

    // Initialize arrays with random values
    for (size_t i = 0; i < max_offset_size; ++i) {
        offsets[i] = rand() % max_offset_size;
    }
    for (size_t i = 0; i < max_key_size; ++i) {
        keys[i] = rand() % max_key_size;
    }

    // Initialize records
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offsets[rand() % max_offset_size];
        records[i].key = keys[rand() % max_key_size];
        records[i].status = rand() % 2 ? 'A' : 'F'; // Randomly set status
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

void reset_seed(int dataset_index, long new_seed) {
    srand(new_seed + dataset_index); // Reset seed for reproducibility
}
