#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PROFILES 1000000
#define MAX_PREFS 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char username[256];
    char preferences[MAX_PREFS][256];
} UserProfile;

typedef struct {
    UserProfile profiles[MAX_PROFILES];
    int size;
    pthread_mutex_t mutex;
} UserProfileManager;

UserProfileManager* create_user_profile_manager(int range_start, int range_end) {
    if (range_end - range_start + 1 > MAX_PROFILES) {
        return NULL; // Error: Range too large
    }

    UserProfileManager* manager = (UserProfileManager*)malloc(sizeof(UserProfileManager));
    if (!manager) {
        return NULL; // Out of memory
    }

    memset(manager, 0, sizeof(UserProfileManager));
    pthread_mutex_init(&manager->mutex, NULL);

    for (int i = range_start; i <= range_end; i++) {
        manager->profiles[i - range_start].RX_UE_INFORMATION_TAG = i;
        manager->profiles[i - range_start].RNTI = i;
        snprintf(manager->profiles[i - range_start].username, sizeof(manager->profiles[i - range_start].username), "user%d", i);
    }

    manager->size = range_end - range_start + 1;

    return manager;
}

void destroy_user_profile_manager(UserProfileManager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_user_profile(UserProfileManager* manager, int RNTI, const char* username, const char* preferences[], int num_prefs) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->size; i++) {
        if (manager->profiles[i].RNTI == RNTI && strcmp(manager->profiles[i].username, username) == 0) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Profile already exists
        }
    }

    for (int i = 0; i < manager->size; i++) {
        if (manager->profiles[i].RNTI == 0 && manager->profiles[i].username[0] == '\0') {
            manager->profiles[i].RNTI = RNTI;
            snprintf(manager->profiles[i].username, sizeof(manager->profiles[i].username), "%s", username);
            for (int j = 0; j < num_prefs && j < MAX_PREFS; j++) {
                snprintf(manager->profiles[i].preferences[j], sizeof(manager->profiles[i].preferences[j]), "%s", preferences[j]);
            }
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // No available slot
}

int remove_user_profile(UserProfileManager* manager, int RNTI, const char* username) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->size; i++) {
        if (manager->profiles[i].RNTI == RNTI && strcmp(manager->profiles[i].username, username) == 0) {
            memset(&manager->profiles[i], 0, sizeof(UserProfile));
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Profile not found
}

int get_user_profile(UserProfileManager* manager, int RNTI, const char* username, UserProfile* profile) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->size; i++) {
        if (manager->profiles[i].RNTI == RNTI && strcmp(manager->profiles[i].username, username) == 0) {
            memcpy(profile, &manager->profiles[i], sizeof(UserProfile));
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Profile not found
}
